@dataclass(frozen=True)
class _GhCleanupReceipt:
    kill_sent: bool
    child_reaped: bool
    stdout_drained: bool
    stderr_drained: bool
    status_drained: bool
    process_group_fenced: bool
    errors: tuple[str, ...]

    @property
    def complete(self) -> bool:
        return (
            self.kill_sent
            and self.child_reaped
            and self.stdout_drained
            and self.stderr_drained
            and self.status_drained
            and self.process_group_fenced
            and not self.errors
        )


@dataclass(frozen=True)
class _ProcessTerminalizationReceipt:
    kill_sent: bool
    child_reaped: bool
    process_group_fenced: bool
    returncode: int | None
    errors: tuple[str, ...]

    @property
    def complete(self) -> bool:
        return (
            self.kill_sent
            and self.child_reaped
            and self.process_group_fenced
            and self.returncode == -signal.SIGKILL
            and not self.errors
        )


