    @property
    def stdout(self) -> Any:
        return self.guardian.stdout

    @property
    def stderr(self) -> Any:
        return self.guardian.stderr

    @property
    def returncode(self) -> int | None:
        return self.guardian.returncode

    def wait(self, timeout: float | None = None) -> int:
        return self.guardian.wait(timeout=timeout)


