class ReleaseRetentionTransaction:
    batch_root: Path
    batch_root_identity: tuple[int, int] | None
    owner: str
    sha: str
    source_parent_identity: tuple[int, int]
    source_identity: tuple[int, int]
    quarantine_parent_identity: tuple[int, int]
    destination: Path
    record_snapshot: ManagedStateFileSnapshot
    pointer_snapshot: ManagedStateFileSnapshot
    committed: bool
    deletion_started: bool
    deletion_complete: bool
    clearing: bool
    clearing_deleted: bool


@dataclass(frozen=True)
class ReleaseRetentionRecoveryOutcome:
    owner: str
    sha: str
    action: str
    deleted: bool = False


def _display_path(path: Path) -> str:
    return str(path.expanduser())


def _validate_manifest_unicode_scalars(manifest: object) -> None:
    pending = [manifest]
    seen_containers: set[int] = set()
    while pending:
        value = pending.pop()
        if isinstance(value, str):
            try:
                value.encode("utf-8", errors="strict")
            except UnicodeEncodeError as error:
                raise SyncError(
                    "manifest contains a string that is not valid UTF-8"
                ) from error
            continue
        if isinstance(value, dict):
            identity = id(value)
            if identity in seen_containers:
                continue
            seen_containers.add(identity)
            pending.extend(value.keys())
            pending.extend(value.values())
            continue
        if isinstance(value, (list, tuple)):
            identity = id(value)
            if identity in seen_containers:
                continue
            seen_containers.add(identity)
            pending.extend(value)


def _validate_relative_path(raw: object, field_name: str) -> PurePosixPath:
    if not isinstance(raw, str) or not raw:
        raise SyncError(f"{field_name} must be a non-empty relative path")
    if "\0" in raw:
        raise SyncError(f"{field_name} must not contain embedded NUL")
    if "\\" in raw:
        raise SyncError(f"{field_name} must use safe POSIX path components")
    try:
        raw.encode("utf-8", errors="strict")
    except UnicodeEncodeError as error:
        raise SyncError(f"{field_name} must be valid UTF-8") from error
    raw_parts = raw.split("/")
    if raw.startswith("/") or ".." in raw_parts:
        raise SyncError(
            f"{field_name} must not be absolute or contain parent traversal: {raw}"
        )
    if any(part in ("", ".") for part in raw_parts):
        raise SyncError(
            f"{field_name} must not contain empty or current-dir segments: {raw}"
        )
    path = PurePosixPath(raw)
    return path


def _validate_target_path(raw: object, field_name: str) -> PurePosixPath:
    path = _validate_relative_path(raw, field_name)
    encoded = path.as_posix().encode("utf-8")
    if len(encoded) > MAX_MANIFEST_TARGET_PATH_BYTES:
        raise SyncError(
            f"{field_name} exceeds {MAX_MANIFEST_TARGET_PATH_BYTES} UTF-8 bytes"
        )
    if len(path.parts) > MAX_MANIFEST_TARGET_PATH_DEPTH:
        raise SyncError(
            f"{field_name} exceeds {MAX_MANIFEST_TARGET_PATH_DEPTH} path components"
        )
    for index, part in enumerate(path.parts, start=1):
        component_bytes = len(part.encode("utf-8"))
        if component_bytes > MAX_MANIFEST_TARGET_COMPONENT_BYTES:
            raise SyncError(
                f"{field_name} component {index} exceeds "
                f"{MAX_MANIFEST_TARGET_COMPONENT_BYTES} UTF-8 bytes"
            )
    path_key = _portable_target_key(path)
    for reserved_target, label in MANIFEST_RESERVED_TARGETS:
        reserved_key = _portable_target_key(reserved_target)
        if path_key[: len(reserved_key)] == reserved_key:
            raise SyncError(f"{field_name} must not use {label}: {path}")
    return path


def _owner_is_valid(raw: object) -> bool:
    return (
        isinstance(raw, str)
        and OWNER_RE.fullmatch(raw) is not None
        and len(raw.encode("utf-8")) <= MAX_OWNER_COMPONENT_BYTES
    )


def _validate_owner(raw: object, field_name: str = "owner") -> str:
    if raw is None:
        return PUBLIC_OWNER
    if not _owner_is_valid(raw):
        raise SyncError(
            f"{field_name} must be a non-empty owner id containing only letters, "
            "numbers, '.', '_', or '-', and must not exceed "
            f"{MAX_OWNER_COMPONENT_BYTES} UTF-8 bytes"
        )
    assert isinstance(raw, str)
    return raw


def _validate_explicit_owner(raw: object, field_name: str = "owner") -> str:
    if raw is None:
        raise SyncError(
            f"{field_name} must be a non-empty owner id containing only letters, "
            "numbers, '.', '_', or '-'"
        )
    return _validate_owner(raw, field_name)


def _relative_managed_link_target(
    source: PurePosixPath,
    target: PurePosixPath,
    owner: str,
) -> str:
    current = PurePosixPath("personal-sync")
    if owner != PUBLIC_OWNER:
        current = current / "overlays" / owner
    current = current / "current"
    return posixpath.relpath(
        (current / source).as_posix(),
        start=target.parent.as_posix(),
    )


def _validate_active_managed_link_target(
    source: PurePosixPath,
    target: PurePosixPath,
    owner: str,
    field_name: str,
) -> None:
    link_target = _relative_managed_link_target(source, target, owner)
    if len(link_target.encode("utf-8")) > MAX_MANAGED_LINK_TARGET_BYTES:
        raise SyncError(
            f"{field_name} managed symlink target exceeds "
            f"{MAX_MANAGED_LINK_TARGET_BYTES} UTF-8 bytes"
        )


def _validate_release_sha(raw: object, field_name: str = "release SHA") -> str:
    if not isinstance(raw, str) or RELEASE_DIR_RE.fullmatch(raw) is None:
        raise SyncError(f"{field_name} must be 40 lowercase hex characters: {raw}")
    return raw


def _validate_removed_link_key(raw: object, field_name: str) -> str:
    if not isinstance(raw, str):
        raise SyncError(f"{field_name} must be an owner:id string")
    owner, separator, removed_id = raw.partition(":")
    if (
        not separator
        or ":" in removed_id
        or REMOVED_LINK_ID_RE.fullmatch(removed_id) is None
    ):
        raise SyncError(f"{field_name} must be an owner:id string")
    return f"{_validate_owner(owner, field_name)}:{removed_id}"


def _portable_target_key(path: PurePosixPath) -> tuple[str, ...]:
    return tuple(unicodedata.normalize("NFC", part).casefold() for part in path.parts)


def _portable_owner_key(owner: str) -> str:
    return unicodedata.normalize("NFC", owner).casefold()


def _validate_portable_owner_spellings(owners: list[str]) -> None:
    spellings: dict[str, str] = {}
    for owner in sorted(
        {owner for owner in owners if owner != PUBLIC_OWNER},
        key=lambda value: (_portable_owner_key(value), value),
    ):
        key = _portable_owner_key(owner)
        previous = spellings.get(key)
        if previous is not None and previous != owner:
            raise SyncError(
                f"portable owner spellings conflict: {previous} and {owner}"
            )
        spellings[key] = owner


def _validate_portable_target_spellings(targets: list[PurePosixPath]) -> None:
    spellings: dict[tuple[str, ...], PurePosixPath] = {}
    for target in targets:
        key = _portable_target_key(target)
        previous = spellings.get(key)
        if previous is not None and previous != target:
            raise SyncError(
                f"portable target spellings conflict: {previous} and {target}"
            )
        spellings[key] = target


def _validate_non_overlapping_targets(targets: list[PurePosixPath]) -> None:
    _validate_portable_target_spellings(targets)
    unique_targets = list(dict.fromkeys(targets))
    ordered = sorted(
        ((_portable_target_key(path), path) for path in unique_targets),
        key=lambda item: (item[0], item[1].as_posix()),
    )
    for (parent_key, parent), (child_key, child) in zip(ordered, ordered[1:]):
        if (
            len(parent_key) < len(child_key)
            and child_key[: len(parent_key)] == parent_key
        ):
            raise SyncError(
                f"manifest targets must not overlap: {parent} is an ancestor of {child}"
            )


def _validate_cross_owner_active_removed_target_hierarchy(
    manifests: list[ManifestData],
) -> None:
    class TargetNode:
        __slots__ = ("children", "descendants", "exact")

        def __init__(self) -> None:
            self.children: dict[str, TargetNode] = {}
            self.descendants: list[tuple[str, PurePosixPath]] = []
            self.exact: list[tuple[str, PurePosixPath]] = []

    def add_owner_representative(
        representatives: list[tuple[str, PurePosixPath]],
        owner: str,
        target: PurePosixPath,
    ) -> None:
        if any(
            candidate_owner == owner for candidate_owner, _target in representatives
        ):
            return
        # A lookup excludes only one owner, so two distinct representatives
        # are sufficient to prove whether another owner is present.
        if len(representatives) < 2:
            representatives.append((owner, target))

    def cross_owner_representative(
        representatives: list[tuple[str, PurePosixPath]],
        owner: str,
    ) -> tuple[str, PurePosixPath] | None:
        return next(
            (candidate for candidate in representatives if candidate[0] != owner),
            None,
        )

    root = TargetNode()
    for manifest in manifests:
        for entry in manifest.entries:
            node = root
            for part in _portable_target_key(entry.target):
                add_owner_representative(
                    node.descendants,
                    manifest.owner,
                    entry.target,
                )
                child = node.children.get(part)
                if child is None:
                    child = TargetNode()
                    node.children[part] = child
                node = child
            add_owner_representative(
                node.exact,
                manifest.owner,
                entry.target,
            )

    for manifest in manifests:
        # A replacement target is an exact desired-target reference, not a
        # historical path that reconciliation mutates.
        for removed in manifest.removed_links:
            node = root
            conflict: tuple[str, PurePosixPath] | None = None
            for part in _portable_target_key(removed.target):
                conflict = cross_owner_representative(node.exact, manifest.owner)
                if conflict is not None:
                    break
                child = node.children.get(part)
                if child is None:
                    break
                node = child
            else:
                conflict = cross_owner_representative(
                    node.descendants,
                    manifest.owner,
                )
            if conflict is None:
                continue
            active_owner, active_target = conflict
            raise SyncError(
                "manifest active and removed targets must not overlap across owners: "
                f"{active_target} ({active_owner}) and "
                f"{removed.target} ({manifest.owner})"
            )


def _validate_same_owner_active_removed_target_hierarchy(
    manifests: list[ManifestData],
) -> None:
    active_by_owner: dict[str, list[PurePosixPath]] = {}
    historical_by_owner: dict[str, list[PurePosixPath]] = {}
    for manifest in manifests:
        active_by_owner.setdefault(manifest.owner, []).extend(
            entry.target for entry in manifest.entries
        )
        historical_by_owner.setdefault(manifest.owner, []).extend(
            removed.target for removed in manifest.removed_links
        )

    for historical_targets in historical_by_owner.values():
        _validate_non_overlapping_targets(historical_targets)

    for owner, active_targets in active_by_owner.items():
        historical_targets = historical_by_owner.get(owner, [])
        historical_by_key = {
            _portable_target_key(target): target for target in historical_targets
        }
        ordered_historical_keys = sorted(historical_by_key)
        for active_target in active_targets:
            active_key = _portable_target_key(active_target)
            historical_target: PurePosixPath | None = None
            for prefix_length in range(1, len(active_key)):
                historical_target = historical_by_key.get(active_key[:prefix_length])
                if historical_target is not None:
                    break
            if historical_target is None:
                descendant_index = bisect_right(ordered_historical_keys, active_key)
                if descendant_index < len(ordered_historical_keys):
                    descendant_key = ordered_historical_keys[descendant_index]
                    if (
                        len(descendant_key) > len(active_key)
                        and descendant_key[: len(active_key)] == active_key
                    ):
                        historical_target = historical_by_key[descendant_key]
            if historical_target is not None:
                raise SyncError(
                    "managed target hierarchy changes are not supported for owner "
                    f"{owner}: {historical_target} -> {active_target}"
                )


def _validate_manifest_target_portability(manifests: list[ManifestData]) -> None:
    _validate_portable_owner_spellings([manifest.owner for manifest in manifests])
    active_targets: list[PurePosixPath] = []
    all_targets: list[PurePosixPath] = []
    for manifest in manifests:
        for entry in manifest.entries:
            active_targets.append(entry.target)
            all_targets.append(entry.target)
        for removed in manifest.removed_links:
            all_targets.append(removed.target)
            if removed.replacement_target is not None:
                all_targets.append(removed.replacement_target)
    _validate_portable_target_spellings(all_targets)
    _validate_non_overlapping_targets(active_targets)
    _validate_same_owner_active_removed_target_hierarchy(manifests)
    _validate_cross_owner_active_removed_target_hierarchy(manifests)


def _validate_install_target_portability(
    current_manifests: dict[str, ManifestData],
    next_manifests: dict[str, ManifestData],
) -> None:
    _validate_manifest_target_portability(
        [*current_manifests.values(), *next_manifests.values()]
    )


def _validate_planned_overlay_base_release_shas(
    next_manifests: dict[str, ManifestData],
    planned_public_sha: str | None,
) -> None:
    for owner, manifest in sorted(next_manifests.items()):
        required_public_sha = manifest.base_release_sha
        if owner == PUBLIC_OWNER or required_public_sha is None:
            continue
        if planned_public_sha is None:
            raise SyncError(
                f"overlay {owner} requires public release {required_public_sha}, "
                "but the planned install has no public release; rerun "
                "install-private with the required public base and overlay"
            )
        if required_public_sha != planned_public_sha:
            raise SyncError(
                f"overlay {owner} requires public release {required_public_sha}, "
                f"but the planned public release is {planned_public_sha}; rerun "
                "install-private with the required public base and overlay"
            )


def _manifest_path_kind(
    path_kind: Callable[[PurePosixPath], str | None],
    path: PurePosixPath,
    field_name: str,
) -> str | None:
    try:
        return path_kind(path)
    except (OSError, ValueError) as error:
        raise SyncError(
            f"{field_name} is not a valid filesystem path: {path}"
        ) from error


def _normalize_release(release: dict[str, Any]) -> dict[str, Any]:
    if "tagName" in release:
        return release
    if "tag_name" in release:
        return {
            "tagName": release.get("tag_name"),
            "targetCommitish": release.get("target_commitish"),
            "assets": release.get("assets", []),
        }
    return release


def _manifest_payload_digest(data: dict[str, Any]) -> str:
    try:
        canonical_payload = json.dumps(
            data,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    except (
        TypeError,
        ValueError,
        OverflowError,
        RecursionError,
        UnicodeError,
    ) as error:
        raise SyncError("sync manifest payload could not be canonicalized") from error
    return hashlib.sha256(canonical_payload).hexdigest()


def _parse_manifest_data(
    data: dict[str, Any],
    path_kind: Callable[[PurePosixPath], str | None],
) -> ManifestData:
    _validate_manifest_unicode_scalars(data)
    unknown_fields = sorted(set(data) - MANIFEST_FIELDS)
    if unknown_fields:
        raise SyncError(
            "sync manifest has unsupported field(s): " + ", ".join(unknown_fields)
        )
    version = data.get("version")
    if type(version) is not int or version != 1:
        raise SyncError("sync manifest version must be 1")
    manifest_owner = _validate_explicit_owner(
        data.get("owner", PUBLIC_OWNER),
    )
    raw_links = data.get("links")
    if not isinstance(raw_links, list) or not raw_links:
        raise SyncError("sync manifest must contain a non-empty links array")
    if len(raw_links) > MAX_MANIFEST_ACTIVE_LINKS:
        raise SyncError(
            "sync manifest active links exceed runtime transaction limit: "
            f"{len(raw_links)} > {MAX_MANIFEST_ACTIVE_LINKS}"
        )

    entries: list[LinkEntry] = []
    targets: set[PurePosixPath] = set()
    for index, raw_entry in enumerate(raw_links):
        if not isinstance(raw_entry, dict):
            raise SyncError(f"manifest link #{index + 1} must be an object")
        unknown_fields = sorted(set(raw_entry) - MANIFEST_LINK_FIELDS)
        if unknown_fields:
            raise SyncError(
                f"manifest link #{index + 1} has unsupported field(s): "
                + ", ".join(unknown_fields)
            )
        source = _validate_relative_path(raw_entry.get("source"), "source")
        target = _validate_target_path(raw_entry.get("target"), "target")
        kind = raw_entry.get("kind")
        if kind not in {"file", "directory", "skill"}:
            raise SyncError(f"manifest link {source} has unsupported kind: {kind}")
        owner = _validate_explicit_owner(
            raw_entry.get("owner", manifest_owner),
            "link owner",
        )
        if owner != manifest_owner:
            raise SyncError(
                f"manifest link {source} owner {owner} does not match manifest owner "
                f"{manifest_owner}"
            )
        override = raw_entry.get("override", False)
        if not isinstance(override, bool):
            raise SyncError(f"manifest link {source} override must be boolean")
        if owner == PUBLIC_OWNER and override:
            raise SyncError("public manifest links must not declare override=true")
        _validate_active_managed_link_target(
            source,
            target,
            owner,
            f"manifest link {source}",
        )
        if target in targets:
            raise SyncError(f"duplicate manifest target: {target}")
        targets.add(target)
        source_type = _manifest_path_kind(path_kind, source, "source")
        if kind == "file":
            if source_type != "file":
                raise SyncError(f"manifest file source is missing: {source}")
        else:
            if source_type != "directory":
                raise SyncError(f"manifest directory source is missing: {source}")
            if (
                kind == "skill"
                and _manifest_path_kind(
                    path_kind,
                    source / "SKILL.md",
                    "skill source",
                )
                != "file"
            ):
                raise SyncError(f"manifest skill source is missing SKILL.md: {source}")
        entries.append(
            LinkEntry(
                source=source,
                target=target,
                kind=kind,
                owner=owner,
                override=override,
            )
        )
    _validate_non_overlapping_targets([entry.target for entry in entries])

    raw_references = data.get("reference_only", [])
    if not isinstance(raw_references, list):
        raise SyncError("reference_only must be an array when present")
    for raw_reference in raw_references:
        reference = _validate_relative_path(raw_reference, "reference_only")
        if _manifest_path_kind(path_kind, reference, "reference_only") not in {
            "file",
            "directory",
        }:
            raise SyncError(f"reference_only path is missing: {reference}")

    raw_removed_links = data.get("removed_links", [])
    if not isinstance(raw_removed_links, list):
        raise SyncError("removed_links must be an array when present")
    removed_links: list[RemovedLink] = []
    removed_ids: set[str] = set()
    for index, raw_removed in enumerate(raw_removed_links):
        if not isinstance(raw_removed, dict):
            raise SyncError(f"removed link #{index + 1} must be an object")
        unknown_fields = sorted(set(raw_removed) - REMOVED_LINK_FIELDS)
        if unknown_fields:
            raise SyncError(
                f"removed link #{index + 1} has unsupported field(s): "
                + ", ".join(unknown_fields)
            )
        removed_id = raw_removed.get("id")
        if (
            not isinstance(removed_id, str)
            or REMOVED_LINK_ID_RE.fullmatch(removed_id) is None
        ):
            raise SyncError(
                "removed link id must contain only letters, numbers, '.', '_', or '-'"
            )
        if removed_id in removed_ids:
            raise SyncError(f"duplicate removed link id: {removed_id}")
        removed_ids.add(removed_id)
        source = _validate_relative_path(
            raw_removed.get("source"), "removed link source"
        )
        target = _validate_target_path(raw_removed.get("target"), "removed link target")
        kind = raw_removed.get("kind")
        if kind not in {"file", "directory", "skill"}:
            raise SyncError(f"removed link {removed_id} has unsupported kind: {kind}")
        raw_replacement = raw_removed.get("replacement_target")
        replacement_target = (
            None
            if raw_replacement is None
            else _validate_target_path(raw_replacement, "replacement_target")
        )
        raw_retires = raw_removed.get("retires_replacements", [])
        if not isinstance(raw_retires, list):
            raise SyncError(
                f"removed link {removed_id} retires_replacements must be an array"
            )
        retires_replacements = tuple(
            _validate_removed_link_key(
                raw_key,
                f"removed link {removed_id} retires_replacements entry",
            )
            for raw_key in raw_retires
        )
        if len(set(retires_replacements)) != len(retires_replacements):
            raise SyncError(
                f"removed link {removed_id} has duplicate retires_replacements entries"
            )
        legacy = raw_removed.get("legacy", False)
        if not isinstance(legacy, bool):
            raise SyncError(f"removed link {removed_id} legacy must be boolean")
        removed_links.append(
            RemovedLink(
                id=removed_id,
                source=source,
                target=target,
                kind=kind,
                owner=manifest_owner,
                replacement_target=replacement_target,
                retires_replacements=retires_replacements,
                legacy=legacy,
            )
        )

    raw_base_release = data.get("base_release", {})
    if raw_base_release is None:
        raw_base_release = {}
    if not isinstance(raw_base_release, dict):
        raise SyncError("base_release must be an object when present")
    unknown_fields = sorted(set(raw_base_release) - BASE_RELEASE_FIELDS)
    if unknown_fields:
        raise SyncError(
            "base_release has unsupported field(s): " + ", ".join(unknown_fields)
        )
    base_release_repo = raw_base_release.get("repo")
    if base_release_repo is not None and (
        not isinstance(base_release_repo, str)
        or REPOSITORY_RE.fullmatch(base_release_repo) is None
    ):
        raise SyncError("base_release.repo must be an owner/repo string")
    base_release_sha = raw_base_release.get("sha")
    if base_release_sha is not None and (
        not isinstance(base_release_sha, str)
        or re.fullmatch(r"[0-9a-f]{40}", base_release_sha) is None
    ):
        raise SyncError("base_release.sha must be a 40-character lowercase hex SHA")

    manifest = ManifestData(
        owner=manifest_owner,
        entries=entries,
        removed_links=removed_links,
        payload_digest=_manifest_payload_digest(data),
        base_release_repo=base_release_repo,
        base_release_sha=base_release_sha,
    )
    _validate_manifest_target_portability([manifest])
    return manifest


def load_manifest_data(release_root: Path) -> ManifestData:
    parent_fd, root_fd, root_snapshot = _open_release_source_root(release_root)
    try:
        _data, manifest = _load_manifest_data_from_directory_fd(root_fd, release_root)
        _require_release_source_unchanged(
            root_snapshot,
            os.fstat(root_fd),
            release_root,
        )
        current_root = os.stat(
            release_root.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        _require_release_source_unchanged(root_snapshot, current_root, release_root)
        return manifest
    except OSError as error:
        raise SyncError(f"release source root is unsafe: {release_root}") from error
    finally:
        _close_fd_quietly(root_fd)
        _close_fd_quietly(parent_fd)


def load_manifest(release_root: Path) -> list[LinkEntry]:
    return load_manifest_data(release_root).entries


def _load_base_release_spec(
    manifest: ManifestData,
    fallback_repo: str,
) -> BaseReleaseSpec:
    repo = manifest.base_release_repo or fallback_repo
    if not isinstance(repo, str) or REPOSITORY_RE.fullmatch(repo) is None:
        raise SyncError("base_release.repo must be an owner/repo string")
    return BaseReleaseSpec(repo=repo, sha=manifest.base_release_sha)


def _validated_release_asset_metadata(
    asset: dict[str, Any],
    asset_name: str,
    *,
    maximum_bytes: int,
) -> tuple[int, int]:
    asset_id = asset.get("id")
    if isinstance(asset_id, bool) or not isinstance(asset_id, int) or asset_id <= 0:
        raise SyncError(f"release asset {asset_name} has an invalid GitHub asset id")
    asset_size = asset.get("size")
    if (
        isinstance(asset_size, bool)
        or not isinstance(asset_size, int)
        or asset_size < 0
    ):
        raise SyncError(f"release asset {asset_name} has an invalid GitHub asset size")
    if asset_size > maximum_bytes:
        raise SyncError(
            f"release asset {asset_name} exceeds {maximum_bytes} byte limit"
        )
    return asset_id, asset_size


def _validated_release_asset_digest(
    asset: dict[str, Any],
    asset_name: str,
    *,
    required: bool,
) -> str | None:
    digest = asset.get("digest")
    if digest is None and not required:
        return None
    if (
        not isinstance(digest, str)
        or re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            digest,
        )
        is None
    ):
        raise SyncError(
            f"release asset {asset_name} has an invalid GitHub sha256 digest"
        )
    return digest


def select_release_assets(
    release: dict[str, Any],
    *,
    require_digests: bool = False,
) -> ReleaseAssets:
    release = _normalize_release(release)
    tag_name = release.get("tagName")
    if not isinstance(tag_name, str) or not tag_name.startswith(TAG_PREFIX):
        raise SyncError("release tag is not a personal Codex release")
    tag_match = TAG_RE.fullmatch(tag_name)
    if tag_match is None:
        raise SyncError(f"release tag does not match personal Codex format: {tag_name}")
    assets = release.get("assets")
    if not isinstance(assets, list):
        raise SyncError("release assets must be an array")

    archive_matches: list[tuple[str, dict[str, Any]]] = []
    checksum_matches: dict[str, list[dict[str, Any]]] = {}
    for asset in assets:
        if not isinstance(asset, dict):
            continue
        name = asset.get("name")
        if not isinstance(name, str):
            continue
        archive_match = ASSET_RE.fullmatch(name)
        checksum_match = SHA256_RE.fullmatch(name)
        if archive_match is None and checksum_match is None:
            continue
        if asset.get("state") != "uploaded":
            raise SyncError(
                f"release {tag_name} has release asset {name} that is not uploaded"
            )
        if archive_match is not None:
            archive_matches.append((archive_match.group(1), asset))
            continue
        assert checksum_match is not None
        checksum_matches.setdefault(checksum_match.group(1), []).append(asset)

    if not archive_matches:
        raise SyncError(f"release {tag_name} has no personal-codex tarball asset")
    if len(archive_matches) > 1:
        names = ", ".join(str(asset.get("name")) for _, asset in archive_matches)
        raise SyncError(f"release {tag_name} has multiple tarball assets: {names}")
    sha, archive_asset = archive_matches[0]
    archive_name = archive_asset["name"]
    matching_checksums = checksum_matches.get(sha, [])
    if not matching_checksums:
        raise SyncError(
            f"release {tag_name} is missing checksum asset for {archive_name}"
        )
    if len(matching_checksums) > 1:
        raise SyncError(
            f"release {tag_name} has multiple checksum assets for {archive_name}"
        )
    matching_asset_count = len(archive_matches) + sum(
        len(matches) for matches in checksum_matches.values()
    )
    if matching_asset_count != 2:
        raise SyncError(
            f"release {tag_name} must contain exactly one personal-codex tarball "
            "and its matching checksum asset"
        )
    checksum_asset = matching_checksums[0]
    checksum_name = checksum_asset["name"]
    tag_short_sha = tag_match.group(1)
    if not sha.startswith(tag_short_sha):
        raise SyncError(
            f"release asset SHA {sha} does not match tag suffix {tag_short_sha}"
        )
    target_commitish = release.get("targetCommitish")
    if (
        isinstance(target_commitish, str)
        and re.fullmatch(r"[0-9a-f]{40}", target_commitish)
        and target_commitish != sha
    ):
        raise SyncError(
            f"release asset SHA {sha} does not match target commit {target_commitish}"
        )
    archive_id, archive_size = _validated_release_asset_metadata(
        archive_asset,
        archive_name,
        maximum_bytes=MAX_ARCHIVE_COMPRESSED_BYTES,
    )
    checksum_id, checksum_size = _validated_release_asset_metadata(
        checksum_asset,
        checksum_name,
        maximum_bytes=MAX_ARCHIVE_CHECKSUM_BYTES,
    )
    archive_digest = _validated_release_asset_digest(
        archive_asset,
        archive_name,
        required=require_digests,
    )
    checksum_digest = _validated_release_asset_digest(
        checksum_asset,
        checksum_name,
        required=require_digests,
    )
    if archive_id == checksum_id:
        raise SyncError(
            "release archive and checksum must have distinct GitHub asset ids"
        )
    return ReleaseAssets(
        tag_name=tag_name,
        sha=sha,
        archive_name=archive_name,
        archive_id=archive_id,
        archive_size=archive_size,
        checksum_name=checksum_name,
        checksum_id=checksum_id,
        checksum_size=checksum_size,
        archive_digest=archive_digest,
        checksum_digest=checksum_digest,
    )


def _release_mentions_asset_sha(release: dict[str, Any], sha: str) -> bool:
    assets = release.get("assets")
    if not isinstance(assets, list):
        return False
    for asset in assets:
        if not isinstance(asset, dict):
            continue
        name = asset.get("name")
        if not isinstance(name, str):
            continue
        archive_match = ASSET_RE.fullmatch(name)
        if archive_match and archive_match.group(1) == sha:
            return True
        checksum_match = SHA256_RE.fullmatch(name)
        if checksum_match and checksum_match.group(1) == sha:
            return True
    return False


def _regular_file_snapshot(metadata: os.stat_result) -> tuple[int, ...]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


def _open_bounded_regular_file(
    path: Path,
    *,
    maximum_bytes: int,
    description: str,
    workspace: BoundArchiveWorkspace | None = None,
) -> tuple[int, int, os.stat_result]:
    if path.name in {"", ".", ".."}:
        raise SyncError(f"refusing unsafe {description} path: {path}")
    try:
        if workspace is None:
            parent_fd = os.open(path.parent, _archive_directory_open_flags())
        else:
            parent_fd = _open_archive_directory_beneath(workspace, path.parent)
    except OSError as error:
        raise SyncError(
            f"refusing unsafe {description} parent: {path.parent}"
        ) from error
    file_descriptor = -1
    try:
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        flags |= getattr(os, "O_NONBLOCK", 0)
        file_descriptor = os.open(path.name, flags, dir_fd=parent_fd)
        metadata = os.fstat(file_descriptor)
        if not stat.S_ISREG(metadata.st_mode):
            raise SyncError(f"refusing non-regular {description}: {path}")
        if metadata.st_size > maximum_bytes:
            raise SyncError(f"{description} exceeds {maximum_bytes} byte limit: {path}")
        if (
            not _archive_path_matches_fd(path.parent, parent_fd)
            or not _archive_entry_matches_fd(parent_fd, path.name, file_descriptor)
            or not _archive_path_matches_fd(path, file_descriptor)
        ):
            raise SyncError(f"{description} changed while opening: {path}")
        return parent_fd, file_descriptor, metadata
    except OSError as error:
        if file_descriptor >= 0:
            os.close(file_descriptor)
        os.close(parent_fd)
        raise SyncError(f"refusing unsafe {description}: {path}") from error
    except BaseException:
        if file_descriptor >= 0:
            os.close(file_descriptor)
        os.close(parent_fd)
        raise


def _require_bounded_regular_file_unchanged(
    path: Path,
    parent_fd: int,
    file_descriptor: int,
    initial_metadata: os.stat_result,
    description: str,
    workspace: BoundArchiveWorkspace | None = None,
) -> None:
    current_metadata = os.fstat(file_descriptor)
    if (
        _regular_file_snapshot(current_metadata)
        != _regular_file_snapshot(initial_metadata)
        or not stat.S_ISREG(current_metadata.st_mode)
        or not _archive_path_matches_fd(path.parent, parent_fd)
        or not _archive_entry_matches_fd(parent_fd, path.name, file_descriptor)
        or not _archive_path_matches_fd(path, file_descriptor)
    ):
        raise SyncError(f"{description} changed while reading: {path}")
    if workspace is not None:
        workspace_check_fd = _duplicate_bound_archive_workspace(workspace)
        os.close(workspace_check_fd)


def _read_bounded_regular_file(
    path: Path,
    *,
    maximum_bytes: int,
    description: str,
    workspace: BoundArchiveWorkspace | None = None,
) -> bytes:
    parent_fd, file_descriptor, metadata = _open_bounded_regular_file(
        path,
        maximum_bytes=maximum_bytes,
        description=description,
        workspace=workspace,
    )
    try:
        payload = bytearray()
        remaining = metadata.st_size
        while remaining:
            chunk = os.read(file_descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise SyncError(f"{description} ended early: {path}")
            payload.extend(chunk)
            remaining -= len(chunk)
        if os.read(file_descriptor, 1):
            raise SyncError(f"{description} grew while reading: {path}")
        _require_bounded_regular_file_unchanged(
            path,
            parent_fd,
            file_descriptor,
            metadata,
            description,
            workspace,
        )
        return bytes(payload)
    finally:
        os.close(file_descriptor)
        os.close(parent_fd)


def _copy_archive_to_immutable_snapshot(
    archive_path: Path,
    *,
    workspace: BoundArchiveWorkspace | None = None,
) -> tuple[Any, str]:
    parent_fd, archive_fd, metadata = _open_bounded_regular_file(
        archive_path,
        maximum_bytes=MAX_ARCHIVE_COMPRESSED_BYTES,
        description="compressed archive",
        workspace=workspace,
    )
    snapshot: Any | None = None
    digest = hashlib.sha256()
    try:
        snapshot = tempfile.TemporaryFile(mode="w+b")
        remaining = metadata.st_size
        while remaining:
            chunk = os.read(archive_fd, min(1024 * 1024, remaining))
            if not chunk:
                raise SyncError(f"compressed archive ended early: {archive_path}")
            digest.update(chunk)
            view = memoryview(chunk)
            while view:
                written = snapshot.write(view)
                if written is None or written <= 0:
                    raise SyncError("failed to write immutable archive snapshot")
                view = view[written:]
            remaining -= len(chunk)
        if os.read(archive_fd, 1):
            raise SyncError(f"compressed archive grew while reading: {archive_path}")
        _require_bounded_regular_file_unchanged(
            archive_path,
            parent_fd,
            archive_fd,
            metadata,
            "compressed archive",
            workspace,
        )
        snapshot.flush()
        os.fsync(snapshot.fileno())
        snapshot.seek(0)
        return snapshot, digest.hexdigest()
    except BaseException:
        if snapshot is not None:
            snapshot.close()
        raise
    finally:
        os.close(archive_fd)
        os.close(parent_fd)


def _expected_archive_checksum(
    archive_path: Path,
    checksum_path: Path,
    *,
    workspace: BoundArchiveWorkspace | None = None,
    expected_api_digest: str | None = None,
) -> str:
    checksum_payload = _read_bounded_regular_file(
        checksum_path,
        maximum_bytes=MAX_ARCHIVE_CHECKSUM_BYTES,
        description="checksum file",
        workspace=workspace,
    )
    if expected_api_digest is not None:
        actual_api_digest = f"sha256:{hashlib.sha256(checksum_payload).hexdigest()}"
        if actual_api_digest != expected_api_digest:
            raise SyncError(
                f"GitHub API digest mismatch for {checksum_path.name}: "
                f"expected {expected_api_digest}, got {actual_api_digest}"
            )
    try:
        checksum_text = checksum_payload.decode("utf-8")
    except UnicodeDecodeError as error:
        raise SyncError(f"checksum file is not valid UTF-8: {checksum_path}") from error
    expected: str | None = None
    archive_name = archive_path.name
    for line in checksum_text.splitlines():
        fields = line.strip().split()
        if not fields:
            continue
        checksum_target = (
            Path(fields[-1].lstrip("*")).name if len(fields) > 1 else archive_name
        )
        if checksum_target == archive_name:
            candidate = fields[0]
            if re.fullmatch(r"[0-9a-fA-F]{64}", candidate):
                expected = candidate.lower()
                break
    if expected is None:
        raise SyncError(f"checksum file does not contain a sha256 for {archive_name}")
    return expected


def _verified_archive_snapshot(
    archive_path: Path,
    checksum_path: Path,
    *,
    workspace: BoundArchiveWorkspace | None = None,
    archive_api_digest: str | None = None,
    checksum_api_digest: str | None = None,
) -> Any:
    expected = _expected_archive_checksum(
        archive_path,
        checksum_path,
        workspace=workspace,
        expected_api_digest=checksum_api_digest,
    )
    snapshot, actual = _copy_archive_to_immutable_snapshot(
        archive_path,
        workspace=workspace,
    )
    actual_api_digest = f"sha256:{actual}"
    if archive_api_digest is not None and actual_api_digest != archive_api_digest:
        snapshot.close()
        raise SyncError(
            f"GitHub API digest mismatch for {archive_path.name}: "
            f"expected {archive_api_digest}, got {actual_api_digest}"
        )
    if actual != expected:
        snapshot.close()
        raise SyncError(
            f"checksum mismatch for {archive_path.name}: expected {expected}, got {actual}"
        )
    return snapshot


def verify_checksum(archive_path: Path, checksum_path: Path) -> None:
    """Verify one captured snapshot; use verify_and_extract_archive to extract it."""
    snapshot = _verified_archive_snapshot(archive_path, checksum_path)
    snapshot.close()


def _validated_archive_member_parts(member_name: str) -> tuple[str, ...]:
    if len(member_name) > MAX_ARCHIVE_MEMBER_PATH_BYTES:
        raise SyncError(
            "archive member path exceeds UTF-8 byte limit: "
            f"> {MAX_ARCHIVE_MEMBER_PATH_BYTES}"
        )
    if "\0" in member_name:
        raise SyncError("refusing unsafe archive member path: embedded NUL")
    try:
        encoded_name = member_name.encode("utf-8")
    except UnicodeEncodeError as error:
        raise SyncError("archive member path is not valid UTF-8") from error
    if len(encoded_name) > MAX_ARCHIVE_MEMBER_PATH_BYTES:
        raise SyncError(
            "archive member path exceeds UTF-8 byte limit: "
            f"{len(encoded_name)} > {MAX_ARCHIVE_MEMBER_PATH_BYTES}"
        )

    raw_parts = tuple(member_name.split("/"))
    if member_name.startswith("/") or any(
        part in {"", ".", ".."} for part in raw_parts
    ):
        raise SyncError(f"refusing unsafe archive member path: {member_name}")
    if len(raw_parts) > MAX_ARCHIVE_MEMBER_PATH_DEPTH:
        raise SyncError(
            "archive member path exceeds depth limit: "
            f"{len(raw_parts)} > {MAX_ARCHIVE_MEMBER_PATH_DEPTH}"
        )
    for index, part in enumerate(raw_parts, start=1):
        encoded_part = part.encode("utf-8")
        if len(encoded_part) > MAX_ARCHIVE_MEMBER_COMPONENT_BYTES:
            raise SyncError(
                "archive member path component exceeds UTF-8 byte limit: "
                f"component {index}: {len(encoded_part)} > "
                f"{MAX_ARCHIVE_MEMBER_COMPONENT_BYTES}"
            )
    return raw_parts


def _validate_tar_member(member: tarfile.TarInfo) -> None:
    member_name = member.name
    if member.isdir() and member_name.endswith("/"):
        member_name = member_name[:-1]
    _validated_archive_member_parts(member_name)
    member.name = member_name
    if member.issym() or member.islnk():
        raise SyncError(f"refusing archive link member: {member.name}")
    if not (member.isfile() or member.isdir()):
        raise SyncError(f"refusing unsupported archive member type: {member.name}")
    # Releases are installed under a single user's home; keep executables usable
    # while stripping special and group/world-write bits during extraction.
    if member.isdir():
        member.mode = (member.mode & 0o755) | 0o700
    else:
        member.mode &= 0o755


class _ArchivePathTrieNode:
    __slots__ = ("children", "kind", "original_component", "parent")

    def __init__(
        self,
        *,
        parent: _ArchivePathTrieNode | None = None,
        original_component: str | None = None,
    ) -> None:
        self.children: dict[str, _ArchivePathTrieNode] = {}
        self.kind: str | None = None
        self.original_component = original_component
        self.parent = parent


def _archive_trie_node_path(node: _ArchivePathTrieNode) -> str:
    parts: list[str] = []
    current: _ArchivePathTrieNode | None = node
    while current is not None and current.original_component is not None:
        parts.append(current.original_component)
        current = current.parent
    return "/".join(reversed(parts))


def _validate_archive_member_paths(members: list[tarfile.TarInfo]) -> None:
    explicit_paths: set[str] = set()
    portable_root = _ArchivePathTrieNode()
    path_entry_count = 0

    for member in members:
        if member.name in explicit_paths:
            raise SyncError(
                f"duplicate archive member path: {member.name} and {member.name}"
            )
        explicit_paths.add(member.name)
        parts = tuple(member.name.split("/"))
        node = portable_root
        for index, part in enumerate(parts):
            portable_component = unicodedata.normalize("NFC", part).casefold()
            child = node.children.get(portable_component)
            if child is None:
                if path_entry_count >= MAX_ARCHIVE_MEMBERS:
                    raise SyncError(
                        f"archive exceeds {MAX_ARCHIVE_MEMBERS} path entry limit"
                    )
                child = _ArchivePathTrieNode(
                    parent=node,
                    original_component=part,
                )
                node.children[portable_component] = child
                path_entry_count += 1
            desired_kind = (
                "directory" if index < len(parts) - 1 or member.isdir() else "file"
            )
            if child.original_component != part or (
                child.kind is not None and child.kind != desired_kind
            ):
                previous_kind = child.kind or "directory"
                current_path = "/".join(parts[: index + 1])
                raise SyncError(
                    "portable archive member path conflict: "
                    f"{_archive_trie_node_path(child)} ({previous_kind}) "
                    f"conflicts with {current_path} ({desired_kind})"
                )
            child.kind = desired_kind
            node = child


def _archive_path_matches_fd(path: Path, file_descriptor: int) -> bool:
    try:
        bound_metadata = os.fstat(file_descriptor)
        current_metadata = os.lstat(path)
    except OSError:
        return False
    return (bound_metadata.st_dev, bound_metadata.st_ino) == (
        current_metadata.st_dev,
        current_metadata.st_ino,
    )


def _archive_entry_matches_fd(
    parent_fd: int,
    name: str,
    file_descriptor: int,
) -> bool:
    try:
        bound_metadata = os.fstat(file_descriptor)
        current_metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except OSError:
        return False
    return (bound_metadata.st_dev, bound_metadata.st_ino) == (
        current_metadata.st_dev,
        current_metadata.st_ino,
    )


def _temporary_archive_entry_names(kind: str):
    for _attempt in range(128):
        yield f".codex-extract-{kind}-{os.getpid()}-{os.urandom(8).hex()}"
    raise SyncError("failed to allocate a temporary archive entry")


def _archive_directory_open_flags() -> int:
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    flags |= getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    return flags


def _archive_symlink_open_flags() -> int:
    flags = getattr(os, "O_CLOEXEC", 0)
    if sys.platform == "darwin":
        # Python 3.9 on macOS does not expose O_SYMLINK, although the native
        # kernel interface is available and required to bind the link object.
        return os.O_RDONLY | getattr(os, "O_SYMLINK", 0x00200000) | flags
    if hasattr(os, "O_PATH"):
        return os.O_PATH | getattr(os, "O_NOFOLLOW", 0) | flags
    raise SyncError("binding a symbolic-link object is unsupported")


def _uses_macos_system_temp_alias() -> bool:
    return sys.platform == "darwin"


def _archive_workspace_object_identity(
    metadata: os.stat_result,
) -> tuple[int, int, int]:
    return metadata.st_dev, metadata.st_ino, stat.S_IFMT(metadata.st_mode)


def _archive_workspace_access_policy(
    metadata: os.stat_result,
) -> tuple[int, int, int]:
    return stat.S_IMODE(metadata.st_mode), metadata.st_uid, metadata.st_gid


def _close_archive_workspace_alias_fd(
    file_descriptor: int,
    path: Path,
    *,
    active_error: bool,
) -> None:
    if file_descriptor < 0:
        return
    try:
        os.close(file_descriptor)
    except OSError as error:
        close_error = SyncError(
            f"failed to close system temporary archive alias {path}: {error}"
        )
        if active_error:
            print(f"warning: {close_error}", file=sys.stderr)
        else:
            raise close_error from error


def _normalize_archive_workspace_path(
    path: Path,
) -> tuple[Path, ArchiveWorkspaceAliasBinding | None]:
    """Resolve only the exact macOS system temp alias to its fixed target.

    The alias descriptor pins its filesystem object through target binding, so
    unlink/recreate cannot hide behind immediate inode reuse. The link value
    and access policy plus the target directory's object identity and access
    policy are also protected. Directory timestamps and child-entry churn are
    deliberately not treated as content mutation.
    """
    workspace_path = Path(os.path.abspath(path))
    if not _uses_macos_system_temp_alias() or workspace_path != MACOS_SYSTEM_TEMP_ALIAS:
        return workspace_path, None
    try:
        alias_metadata = os.lstat(workspace_path)
    except OSError as error:
        raise SyncError(
            f"failed to inspect archive workspace {workspace_path}: {error}"
        ) from error
    if not stat.S_ISLNK(alias_metadata.st_mode):
        return workspace_path, None

    alias_fd = -1
    try:
        alias_fd = os.open(workspace_path, _archive_symlink_open_flags())
        bound_alias_metadata = os.fstat(alias_fd)
        current_alias_metadata = os.lstat(workspace_path)
        if (
            not stat.S_ISLNK(bound_alias_metadata.st_mode)
            or _archive_workspace_object_identity(bound_alias_metadata)
            != _archive_workspace_object_identity(alias_metadata)
            or _archive_workspace_object_identity(current_alias_metadata)
            != _archive_workspace_object_identity(bound_alias_metadata)
            or _archive_workspace_access_policy(bound_alias_metadata)
            != _archive_workspace_access_policy(alias_metadata)
            or _archive_workspace_access_policy(current_alias_metadata)
            != _archive_workspace_access_policy(bound_alias_metadata)
        ):
            raise SyncError(
                f"system temporary archive alias changed while binding: "
                f"{workspace_path}"
            )
        canonical_path = Path(os.path.realpath(MACOS_SYSTEM_TEMP_DIRECTORY))
        expected_link_targets = {
            str(canonical_path),
            os.path.relpath(canonical_path, workspace_path.parent),
        }
        link_target = os.readlink(workspace_path)
        resolved_path = Path(os.path.realpath(workspace_path))
        canonical_metadata = os.lstat(canonical_path)
        followed_metadata = os.stat(workspace_path)
    except OSError as error:
        _close_archive_workspace_alias_fd(
            alias_fd,
            workspace_path,
            active_error=True,
        )
        raise SyncError(
            f"failed to bind system temporary archive workspace "
            f"{workspace_path}: {error}"
        ) from error
    except BaseException:
        _close_archive_workspace_alias_fd(
            alias_fd,
            workspace_path,
            active_error=True,
        )
        raise
    target_identity = _archive_workspace_object_identity(canonical_metadata)
    target_access_policy = _archive_workspace_access_policy(canonical_metadata)
    if (
        link_target not in expected_link_targets
        or resolved_path != canonical_path
        or not stat.S_ISDIR(canonical_metadata.st_mode)
        or _archive_workspace_object_identity(followed_metadata) != target_identity
        or _archive_workspace_access_policy(followed_metadata) != target_access_policy
    ):
        _close_archive_workspace_alias_fd(
            alias_fd,
            workspace_path,
            active_error=True,
        )
        raise SyncError(
            f"refusing non-standard macOS system temporary alias: {workspace_path}"
        )
    return canonical_path, ArchiveWorkspaceAliasBinding(
        path=workspace_path,
        target=canonical_path,
        fd=alias_fd,
        link_target=link_target,
        identity=_archive_workspace_object_identity(bound_alias_metadata),
        access_policy=_archive_workspace_access_policy(bound_alias_metadata),
        target_identity=target_identity,
        target_access_policy=target_access_policy,
    )


def _revalidate_archive_workspace_alias(
    binding: ArchiveWorkspaceAliasBinding,
    descriptor_metadata: os.stat_result,
) -> None:
    """Revalidate the system alias snapshot against the opened target fd."""
    try:
        bound_alias_metadata = os.fstat(binding.fd)
        alias_metadata = os.lstat(binding.path)
        link_target = os.readlink(binding.path)
        resolved_path = Path(os.path.realpath(binding.path))
        canonical_metadata = os.lstat(binding.target)
        followed_metadata = os.stat(binding.path)
    except OSError as error:
        raise SyncError(
            f"system temporary archive alias became unavailable: "
            f"{binding.path}: {error}"
        ) from error
    if (
        _archive_workspace_object_identity(bound_alias_metadata) != binding.identity
        or _archive_workspace_access_policy(bound_alias_metadata)
        != binding.access_policy
        or _archive_workspace_object_identity(alias_metadata) != binding.identity
        or _archive_workspace_access_policy(alias_metadata) != binding.access_policy
        or link_target != binding.link_target
        or resolved_path != binding.target
    ):
        raise SyncError(
            f"system temporary archive alias changed while binding: {binding.path}"
        )
    if (
        _archive_workspace_object_identity(canonical_metadata)
        != binding.target_identity
        or _archive_workspace_object_identity(followed_metadata)
        != binding.target_identity
        or _archive_workspace_object_identity(descriptor_metadata)
        != binding.target_identity
    ):
        raise SyncError(
            "system temporary archive directory was replaced while binding: "
            f"{binding.target}"
        )
    if (
        _archive_workspace_access_policy(canonical_metadata)
        != binding.target_access_policy
        or _archive_workspace_access_policy(followed_metadata)
        != binding.target_access_policy
        or _archive_workspace_access_policy(descriptor_metadata)
        != binding.target_access_policy
    ):
        raise SyncError(
            "system temporary archive directory access policy changed while "
            f"binding: {binding.target}"
        )


def _close_archive_workspace_alias(
    binding: ArchiveWorkspaceAliasBinding | None,
    *,
    active_error: bool,
) -> None:
    if binding is None:
        return
    _close_archive_workspace_alias_fd(
        binding.fd,
        binding.path,
        active_error=active_error,
    )


def _close_archive_workspace_fd(
    file_descriptor: int,
    path: Path,
    *,
    active_error: bool,
) -> None:
    if file_descriptor < 0:
        return
    try:
        os.close(file_descriptor)
    except OSError as error:
        close_error = SyncError(f"failed to close archive workspace {path}: {error}")
        if active_error:
            print(f"warning: {close_error}", file=sys.stderr)
        else:
            raise close_error from error


def _close_archive_workspace_bindings(
    workspace_fd: int,
    workspace_path: Path,
    alias_binding: ArchiveWorkspaceAliasBinding | None,
    *,
    active_error: bool,
) -> None:
    """Attempt each independently owned close without retrying an uncertain fd."""
    close_errors: list[SyncError] = []
    for close in (
        lambda: _close_archive_workspace_fd(
            workspace_fd,
            workspace_path,
            active_error=False,
        ),
        lambda: _close_archive_workspace_alias(
            alias_binding,
            active_error=False,
        ),
    ):
        try:
            close()
        except SyncError as error:
            close_errors.append(error)
    if not close_errors:
        return
    if active_error:
        for error in close_errors:
            print(f"warning: {error}", file=sys.stderr)
        return
    if len(close_errors) == 1:
        raise close_errors[0]
    raise SyncError(
        "archive workspace cleanup failed: "
        + "; ".join(str(error) for error in close_errors)
    ) from close_errors[0]


@contextlib.contextmanager
def bind_archive_workspace(path: Path) -> Iterator[BoundArchiveWorkspace]:
    workspace_path, alias_binding = _normalize_archive_workspace_path(path)
    workspace_fd = -1
    try:
        workspace_fd = os.open(workspace_path, _archive_directory_open_flags())
        opened_metadata = os.fstat(workspace_fd)
        path_metadata = os.lstat(workspace_path)
    except OSError as error:
        _close_archive_workspace_bindings(
            workspace_fd,
            workspace_path,
            alias_binding,
            active_error=True,
        )
        raise SyncError(
            f"failed to bind archive workspace {workspace_path}: {error}"
        ) from error
    identity = (opened_metadata.st_dev, opened_metadata.st_ino)
    access_policy = _archive_workspace_access_policy(opened_metadata)
    if (
        not stat.S_ISDIR(opened_metadata.st_mode)
        or not stat.S_ISDIR(path_metadata.st_mode)
        or (path_metadata.st_dev, path_metadata.st_ino) != identity
        or _archive_workspace_access_policy(path_metadata) != access_policy
    ):
        primary = SyncError(
            f"archive workspace changed while binding: {workspace_path}"
        )
        _close_archive_workspace_bindings(
            workspace_fd,
            workspace_path,
            alias_binding,
            active_error=True,
        )
        raise primary
    if alias_binding is not None:
        try:
            _revalidate_archive_workspace_alias(alias_binding, opened_metadata)
        except BaseException:
            _close_archive_workspace_bindings(
                workspace_fd,
                workspace_path,
                alias_binding,
                active_error=True,
            )
            raise
        try:
            _close_archive_workspace_alias(alias_binding, active_error=False)
        except BaseException:
            _close_archive_workspace_fd(
                workspace_fd,
                workspace_path,
                active_error=True,
            )
            raise
    try:
        yield BoundArchiveWorkspace(
            path=workspace_path,
            fd=workspace_fd,
            identity=identity,
            access_policy=access_policy,
        )
    finally:
        active_error = sys.exc_info()[0] is not None
        _close_archive_workspace_fd(
            workspace_fd,
            workspace_path,
            active_error=active_error,
        )


def _duplicate_bound_archive_workspace(workspace: BoundArchiveWorkspace) -> int:
    if not isinstance(workspace, BoundArchiveWorkspace):
        raise SyncError("archive workspace capability is required")
    workspace_path = Path(os.path.abspath(workspace.path))
    workspace_fd = -1
    try:
        workspace_fd = os.dup(workspace.fd)
        opened_metadata = os.fstat(workspace_fd)
        path_metadata = os.lstat(workspace_path)
    except (OSError, TypeError, ValueError) as error:
        if workspace_fd >= 0:
            os.close(workspace_fd)
        raise SyncError(
            f"archive workspace is no longer bound: {workspace_path}"
        ) from error
    identity = (opened_metadata.st_dev, opened_metadata.st_ino)
    if (
        not stat.S_ISDIR(opened_metadata.st_mode)
        or not stat.S_ISDIR(path_metadata.st_mode)
        or identity != workspace.identity
        or (path_metadata.st_dev, path_metadata.st_ino) != workspace.identity
        or _archive_workspace_access_policy(opened_metadata) != workspace.access_policy
        or _archive_workspace_access_policy(path_metadata) != workspace.access_policy
    ):
        os.close(workspace_fd)
        raise SyncError(f"archive workspace binding changed: {workspace_path}")
    return workspace_fd


def _temporary_archive_workspace_names(prefix: str) -> Iterator[str]:
    if (
        not isinstance(prefix, str)
        or not prefix
        or "\0" in prefix
        or "/" in prefix
        or len(prefix.encode("utf-8")) > 128
    ):
        raise SyncError("temporary archive workspace prefix is unsafe")
    for _attempt in range(128):
        yield f"{prefix}{os.getpid()}-{os.urandom(16).hex()}"
    raise SyncError("failed to allocate a temporary archive workspace")


def _temporary_archive_cleanup_names() -> Iterator[str]:
    for _attempt in range(128):
        yield (f".codex-archive-cleanup-{os.getpid()}-{os.urandom(16).hex()}")
    raise SyncError("failed to allocate a temporary archive cleanup name")


def _isolate_temporary_archive_entry(
    parent_fd: int,
    name: str,
    expected: os.stat_result,
) -> str:
    # POSIX has no portable unlink-by-open-fd primitive. Random no-replace
    # isolation plus identity checks protects against path replacement that is
    # observable before deletion, but a malicious same-uid process that keeps
    # racing newly isolated random names is outside this helper's threat model.
    isolated_name: str | None = None
    for candidate in _temporary_archive_cleanup_names():
        try:
            _rename_noreplace_at(
                parent_fd,
                name,
                parent_fd,
                candidate,
            )
        except FileExistsError:
            continue
        isolated_name = candidate
        break
    assert isolated_name is not None
    current = os.stat(
        isolated_name,
        dir_fd=parent_fd,
        follow_symlinks=False,
    )
    if (current.st_dev, current.st_ino) != (
        expected.st_dev,
        expected.st_ino,
    ) or stat.S_IFMT(current.st_mode) != stat.S_IFMT(expected.st_mode):
        raise SyncError(
            "temporary archive workspace entry changed during cleanup isolation; "
            f"preserved as {isolated_name}"
        )
    return isolated_name


def _remove_temporary_archive_entry(
    parent_fd: int,
    name: str,
    budget: list[int],
    *,
    depth: int,
) -> None:
    if depth > MAX_TEMP_ARCHIVE_CLEANUP_DEPTH:
        raise SyncError("temporary archive workspace cleanup exceeds depth limit")
    if budget[0] <= 0:
        raise SyncError("temporary archive workspace cleanup exceeds entry limit")
    budget[0] -= 1
    metadata = os.stat(
        name,
        dir_fd=parent_fd,
        follow_symlinks=False,
    )
    isolated_name = _isolate_temporary_archive_entry(
        parent_fd,
        name,
        metadata,
    )
    if stat.S_ISREG(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        os.unlink(isolated_name, dir_fd=parent_fd)
        return
    if not stat.S_ISDIR(metadata.st_mode):
        raise SyncError(
            "temporary archive workspace contains an unsupported entry; "
            f"preserved as {isolated_name}"
        )
    child_fd = os.open(
        isolated_name,
        _archive_directory_open_flags(),
        dir_fd=parent_fd,
    )
    try:
        expected_identity = (metadata.st_dev, metadata.st_ino)
        if _directory_identity(child_fd) != expected_identity:
            raise SyncError(
                "temporary archive workspace entry changed after isolation; "
                f"preserved as {isolated_name}"
            )
        for child_name in os.listdir(child_fd):
            _remove_temporary_archive_entry(
                child_fd,
                child_name,
                budget,
                depth=depth + 1,
            )
        if os.listdir(child_fd):
            raise SyncError(
                "temporary archive workspace directory gained an entry; "
                f"preserved as {isolated_name}"
            )
        current = os.stat(
            isolated_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISDIR(current.st_mode)
            or (current.st_dev, current.st_ino) != expected_identity
        ):
            raise SyncError(
                "temporary archive workspace entry changed before deletion; "
                f"preserved as {isolated_name}"
            )
        os.rmdir(isolated_name, dir_fd=parent_fd)
    finally:
        active_error = sys.exc_info()[0] is not None
        try:
            os.close(child_fd)
        except OSError as error:
            close_error = SyncError(
                f"failed to close temporary archive workspace entry: {error}"
            )
            if active_error:
                print(f"warning: {close_error}", file=sys.stderr)
            else:
                raise close_error from error


def _cleanup_bound_temporary_archive_workspace(
    parent_fd: int,
    name: str,
    workspace_fd: int,
    expected_identity: tuple[int, int],
) -> None:
    try:
        opened_metadata = os.fstat(workspace_fd)
        path_metadata = os.stat(
            name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
    except OSError as error:
        raise SyncError(
            f"failed to inspect temporary archive workspace {name}: {error}"
        ) from error
    if (
        not stat.S_ISDIR(opened_metadata.st_mode)
        or (opened_metadata.st_dev, opened_metadata.st_ino) != expected_identity
        or not stat.S_ISDIR(path_metadata.st_mode)
        or (path_metadata.st_dev, path_metadata.st_ino) != expected_identity
    ):
        raise SyncError(
            f"temporary archive workspace changed; refusing cleanup: {name}"
        )
    try:
        isolated_name = _isolate_temporary_archive_entry(
            parent_fd,
            name,
            path_metadata,
        )
        budget = [MAX_TEMP_ARCHIVE_CLEANUP_ENTRIES]
        for child_name in os.listdir(workspace_fd):
            _remove_temporary_archive_entry(
                workspace_fd,
                child_name,
                budget,
                depth=0,
            )
        if os.listdir(workspace_fd):
            raise SyncError(
                "temporary archive workspace gained an entry; "
                f"preserved as {isolated_name}"
            )
        opened_metadata = os.fstat(workspace_fd)
        path_metadata = os.stat(
            isolated_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISDIR(opened_metadata.st_mode)
            or (opened_metadata.st_dev, opened_metadata.st_ino) != expected_identity
            or not stat.S_ISDIR(path_metadata.st_mode)
            or (path_metadata.st_dev, path_metadata.st_ino) != expected_identity
        ):
            raise SyncError(
                "temporary archive workspace changed before deletion; "
                f"preserved as {isolated_name}"
            )
        os.rmdir(isolated_name, dir_fd=parent_fd)
    except OSError as error:
        raise SyncError(
            f"failed to clean temporary archive workspace {name}: {error}"
        ) from error


def _cleanup_created_temporary_archive_workspace(
    parent_fd: int,
    name: str,
    created_metadata: os.stat_result,
) -> None:
    try:
        isolated_name = _isolate_temporary_archive_entry(
            parent_fd,
            name,
            created_metadata,
        )
        isolated_metadata = os.stat(
            isolated_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if not stat.S_ISDIR(isolated_metadata.st_mode) or (
            isolated_metadata.st_dev,
            isolated_metadata.st_ino,
        ) != (created_metadata.st_dev, created_metadata.st_ino):
            raise SyncError(
                "temporary archive workspace changed before creation cleanup; "
                f"preserved as {isolated_name}"
            )
        os.rmdir(isolated_name, dir_fd=parent_fd)
    except OSError as error:
        raise SyncError(
            f"failed to clean created temporary archive workspace {name}: {error}"
        ) from error


@contextlib.contextmanager
def create_bound_temporary_archive_workspace(
    parent_workspace: BoundArchiveWorkspace,
    *,
    prefix: str,
) -> Iterator[BoundArchiveWorkspace]:
    parent_fd = _duplicate_bound_archive_workspace(parent_workspace)
    workspace_fd = -1
    workspace_name: str | None = None
    workspace_identity: tuple[int, int] | None = None
    created_metadata: os.stat_result | None = None
    cleanup_attempted = False
    try:
        for candidate in _temporary_archive_workspace_names(prefix):
            try:
                os.mkdir(candidate, mode=0o700, dir_fd=parent_fd)
            except FileExistsError:
                continue
            workspace_name = candidate
            break
        assert workspace_name is not None
        created_metadata = os.stat(
            workspace_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if not stat.S_ISDIR(created_metadata.st_mode):
            raise SyncError("created temporary archive workspace is not a directory")
        workspace_identity = (created_metadata.st_dev, created_metadata.st_ino)
        workspace_fd = os.open(
            workspace_name,
            _archive_directory_open_flags(),
            dir_fd=parent_fd,
        )
        opened_metadata = os.fstat(workspace_fd)
        current_metadata = os.stat(
            workspace_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISDIR(opened_metadata.st_mode)
            or (opened_metadata.st_dev, opened_metadata.st_ino) != workspace_identity
            or not stat.S_ISDIR(current_metadata.st_mode)
            or (current_metadata.st_dev, current_metadata.st_ino) != workspace_identity
        ):
            raise SyncError("temporary archive workspace changed while binding")
        workspace_path = parent_workspace.path / workspace_name
        workspace = BoundArchiveWorkspace(
            path=workspace_path,
            fd=workspace_fd,
            identity=workspace_identity,
            access_policy=_archive_workspace_access_policy(opened_metadata),
        )
        check_fd = _duplicate_bound_archive_workspace(workspace)
        os.close(check_fd)
        try:
            yield workspace
        finally:
            cleanup_attempted = True
            active_error = sys.exc_info()[0] is not None
            cleanup_error: BaseException | None = None
            try:
                _cleanup_bound_temporary_archive_workspace(
                    parent_fd,
                    workspace_name,
                    workspace_fd,
                    workspace_identity,
                )
            except BaseException as error:
                cleanup_error = error
            if cleanup_error is not None:
                if active_error:
                    print(f"warning: {cleanup_error}", file=sys.stderr)
                else:
                    raise cleanup_error
    finally:
        active_error = sys.exc_info()[0] is not None
        if (
            not cleanup_attempted
            and workspace_name is not None
            and workspace_identity is not None
        ):
            try:
                if workspace_fd >= 0:
                    _cleanup_bound_temporary_archive_workspace(
                        parent_fd,
                        workspace_name,
                        workspace_fd,
                        workspace_identity,
                    )
                elif created_metadata is not None:
                    _cleanup_created_temporary_archive_workspace(
                        parent_fd,
                        workspace_name,
                        created_metadata,
                    )
            except BaseException as cleanup_error:
                if active_error:
                    print(f"warning: {cleanup_error}", file=sys.stderr)
                else:
                    raise
        close_error: OSError | None = None
        for descriptor in (workspace_fd, parent_fd):
            if descriptor < 0:
                continue
            try:
                os.close(descriptor)
            except OSError as error:
                if close_error is None:
                    close_error = error
        if close_error is not None:
            workspace_close_error = SyncError(
                f"failed to close temporary archive workspace: {close_error}"
            )
            if active_error:
                print(f"warning: {workspace_close_error}", file=sys.stderr)
            else:
                raise workspace_close_error from close_error


@contextlib.contextmanager
def temporary_archive_workspace(
    *,
    prefix: str,
    parent: Path | None = None,
) -> Iterator[BoundArchiveWorkspace]:
    parent_path = Path(tempfile.gettempdir()) if parent is None else parent
    with bind_archive_workspace(parent_path) as parent_workspace:
        with create_bound_temporary_archive_workspace(
            parent_workspace,
            prefix=prefix,
        ) as workspace:
            yield workspace


def _archive_workspace_relative_parts(
    workspace: BoundArchiveWorkspace,
    path: Path,
) -> tuple[Path, tuple[str, ...]]:
    workspace_path = Path(os.path.abspath(workspace.path))
    if ".." in path.parts:
        raise SyncError(f"refusing archive workspace parent traversal: {path}")
    normalized_path = Path(os.path.abspath(path))
    try:
        parts = normalized_path.relative_to(workspace_path).parts
    except ValueError as error:
        raise SyncError(
            f"archive path escapes its bound workspace: {normalized_path}"
        ) from error
    if any(part in {"", ".", ".."} for part in parts):
        raise SyncError(f"refusing unsafe archive workspace path: {normalized_path}")
    return normalized_path, parts


def _open_archive_directory_beneath(
    workspace: BoundArchiveWorkspace,
    directory: Path,
    *,
    create: bool = False,
) -> int:
    directory, parts = _archive_workspace_relative_parts(workspace, directory)
    directory_fd = _duplicate_bound_archive_workspace(workspace)
    try:
        for part in parts:
            next_fd = -1
            try:
                try:
                    entry_metadata = os.stat(
                        part,
                        dir_fd=directory_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    if not create:
                        raise
                    next_fd = _create_archive_directory_at(directory_fd, part)
                    entry_metadata = os.fstat(next_fd)
                else:
                    if not stat.S_ISDIR(entry_metadata.st_mode):
                        raise SyncError(
                            f"refusing unsafe archive directory: {directory}"
                        )
                    next_fd = os.open(
                        part,
                        _archive_directory_open_flags(),
                        dir_fd=directory_fd,
                    )
                bound_metadata = os.fstat(next_fd)
                if (
                    not stat.S_ISDIR(bound_metadata.st_mode)
                    or (entry_metadata.st_dev, entry_metadata.st_ino)
                    != (bound_metadata.st_dev, bound_metadata.st_ino)
                    or not _archive_entry_matches_fd(directory_fd, part, next_fd)
                ):
                    raise SyncError(f"archive directory ancestor changed: {directory}")
            except BaseException:
                if next_fd >= 0:
                    os.close(next_fd)
                raise
            previous_fd = directory_fd
            directory_fd = next_fd
            os.close(previous_fd)
        if not _archive_path_matches_fd(directory, directory_fd):
            raise SyncError(f"archive directory ancestor changed: {directory}")
        workspace_check_fd = _duplicate_bound_archive_workspace(workspace)
        os.close(workspace_check_fd)
        result = directory_fd
        directory_fd = -1
        return result
    except SyncError:
        raise
    except OSError as error:
        raise SyncError(f"refusing unsafe archive directory: {directory}") from error
    finally:
        if directory_fd >= 0:
            os.close(directory_fd)


def _create_archive_directory_at(parent_fd: int, name: str) -> int:
    temporary_name: str | None = None
    directory_fd: int | None = None
    try:
        for candidate in _temporary_archive_entry_names("dir"):
            try:
                os.mkdir(candidate, mode=0o700, dir_fd=parent_fd)
            except FileExistsError:
                continue
            temporary_name = candidate
            break
        if temporary_name is None:
            raise SyncError("failed to allocate a temporary archive directory")
        created_metadata = os.stat(
            temporary_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        directory_fd = os.open(
            temporary_name,
            _archive_directory_open_flags(),
            dir_fd=parent_fd,
        )
        bound_metadata = os.fstat(directory_fd)
        if not stat.S_ISDIR(created_metadata.st_mode) or (
            created_metadata.st_dev,
            created_metadata.st_ino,
        ) != (bound_metadata.st_dev, bound_metadata.st_ino):
            raise SyncError(f"temporary archive directory changed: {name}")
        os.fchmod(directory_fd, 0o700)
        try:
            _rename_noreplace_at(parent_fd, temporary_name, parent_fd, name)
        except FileExistsError as error:
            raise _ArchiveEntryExistsError(
                f"archive entry already exists: {name}"
            ) from error
        temporary_name = None
        if not _archive_entry_matches_fd(parent_fd, name, directory_fd):
            raise SyncError(f"archive directory changed during publication: {name}")
        return directory_fd
    except BaseException:
        if directory_fd is not None:
            os.close(directory_fd)
        if temporary_name is not None:
            try:
                os.rmdir(temporary_name, dir_fd=parent_fd)
            except OSError:
                pass
        raise


def _create_archive_destination(
    destination: Path,
    workspace: BoundArchiveWorkspace,
) -> tuple[int, int]:
    if destination.name in {"", ".", ".."}:
        raise SyncError(f"refusing unsafe archive destination: {destination}")
    parent_fd = _open_archive_directory_beneath(
        workspace,
        destination.parent,
    )
    destination_fd: int | None = None
    try:
        try:
            destination_fd = _create_archive_directory_at(parent_fd, destination.name)
        except _ArchiveEntryExistsError as error:
            raise SyncError(
                f"refusing pre-existing archive destination: {destination}"
            ) from error
        if not _archive_path_matches_fd(destination.parent, parent_fd):
            raise SyncError(f"archive destination parent changed: {destination.parent}")
        if not _archive_entry_matches_fd(
            parent_fd,
            destination.name,
            destination_fd,
        ) or not _archive_path_matches_fd(destination, destination_fd):
            raise SyncError(
                f"archive destination changed after creation: {destination}"
            )
        workspace_check_fd = _duplicate_bound_archive_workspace(workspace)
        os.close(workspace_check_fd)
        return parent_fd, destination_fd
    except BaseException:
        if destination_fd is not None:
            os.close(destination_fd)
        os.close(parent_fd)
        raise


def _open_archive_directory(
    destination_fd: int,
    directory_identities: dict[tuple[str, ...], tuple[int, int]],
    parts: tuple[str, ...],
) -> int:
    try:
        current_fd = os.dup(destination_fd)
    except OSError as error:
        raise SyncError("failed to bind archive destination") from error
    try:
        if _directory_identity(current_fd) != directory_identities[()]:
            raise SyncError("archive destination changed during extraction")
        for length in range(1, len(parts) + 1):
            current_parts = parts[:length]
            expected_identity = directory_identities.get(current_parts)
            if expected_identity is None:
                raise SyncError("archive directory is missing during extraction")
            next_fd = os.open(
                current_parts[-1],
                _archive_directory_open_flags(),
                dir_fd=current_fd,
            )
            try:
                if _directory_identity(
                    next_fd
                ) != expected_identity or not _archive_entry_matches_fd(
                    current_fd,
                    current_parts[-1],
                    next_fd,
                ):
                    raise SyncError("archive directory changed during extraction")
            except BaseException:
                os.close(next_fd)
                raise
            os.close(current_fd)
            current_fd = next_fd
        return current_fd
    except SyncError:
        os.close(current_fd)
        raise
    except OSError as error:
        os.close(current_fd)
        raise SyncError("archive directory changed during extraction") from error
    except BaseException:
        os.close(current_fd)
        raise


def _ensure_archive_directories(
    destination_fd: int,
    directory_identities: dict[tuple[str, ...], tuple[int, int]],
    parts: tuple[str, ...],
) -> int:
    try:
        current_fd = os.dup(destination_fd)
    except OSError as error:
        raise SyncError("failed to bind archive destination") from error
    try:
        if _directory_identity(current_fd) != directory_identities[()]:
            raise SyncError("archive destination changed during extraction")
        for length in range(1, len(parts) + 1):
            current_parts = parts[:length]
            expected_identity = directory_identities.get(current_parts)
            next_fd: int | None = None
            try:
                if expected_identity is None:
                    next_fd = _create_archive_directory_at(
                        current_fd,
                        current_parts[-1],
                    )
                    expected_identity = _directory_identity(next_fd)
                    directory_identities[current_parts] = expected_identity
                else:
                    next_fd = os.open(
                        current_parts[-1],
                        _archive_directory_open_flags(),
                        dir_fd=current_fd,
                    )
                    if _directory_identity(
                        next_fd
                    ) != expected_identity or not _archive_entry_matches_fd(
                        current_fd,
                        current_parts[-1],
                        next_fd,
                    ):
                        raise SyncError("archive directory changed during extraction")
            except BaseException:
                if next_fd is not None:
                    os.close(next_fd)
                raise
            if next_fd is None:
                raise SyncError("failed to open archive directory")
            os.close(current_fd)
            current_fd = next_fd
        return current_fd
    except SyncError:
        os.close(current_fd)
        raise
    except OSError as error:
        os.close(current_fd)
        raise SyncError("archive directory changed during extraction") from error
    except BaseException:
        os.close(current_fd)
        raise


def _write_archive_member_file(
    archive: tarfile.TarFile,
    member: tarfile.TarInfo,
    parent_fd: int,
    name: str,
) -> tuple[int, ...]:
    source = archive.extractfile(member)
    if source is None:
        raise SyncError(f"failed to read archive member: {member.name}")
    temporary_name: str | None = None
    file_descriptor: int | None = None
    try:
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        flags |= getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        flags |= getattr(os, "O_NONBLOCK", 0)
        for candidate in _temporary_archive_entry_names("file"):
            try:
                file_descriptor = os.open(
                    candidate,
                    flags,
                    0o600,
                    dir_fd=parent_fd,
                )
            except FileExistsError:
                continue
            temporary_name = candidate
            break
        if temporary_name is None or file_descriptor is None:
            raise SyncError("failed to allocate a temporary archive file")

        created_metadata = os.fstat(file_descriptor)
        if not stat.S_ISREG(created_metadata.st_mode):
            raise SyncError(f"temporary archive file is not regular: {member.name}")
        remaining = member.size
        while remaining:
            chunk = source.read(min(1024 * 1024, remaining))
            if not chunk:
                raise SyncError(f"archive member ended early: {member.name}")
            view = memoryview(chunk)
            while view:
                written = os.write(file_descriptor, view)
                if written <= 0:
                    raise SyncError(f"failed to write archive member: {member.name}")
                view = view[written:]
            remaining -= len(chunk)
        os.fchmod(file_descriptor, member.mode)
        os.fsync(file_descriptor)
        metadata = os.fstat(file_descriptor)
        if (
            (created_metadata.st_dev, created_metadata.st_ino)
            != (metadata.st_dev, metadata.st_ino)
            or not stat.S_ISREG(metadata.st_mode)
            or metadata.st_size != member.size
        ):
            raise SyncError(f"temporary archive file changed: {member.name}")
        try:
            _rename_noreplace_at(parent_fd, temporary_name, parent_fd, name)
        except FileExistsError as error:
            raise _ArchiveEntryExistsError(
                f"archive entry already exists: {member.name}"
            ) from error
        temporary_name = None
        if not _archive_entry_matches_fd(parent_fd, name, file_descriptor):
            raise SyncError(f"archive file changed during publication: {member.name}")
        return _regular_file_snapshot(os.fstat(file_descriptor))
    finally:
        source.close()
        if file_descriptor is not None:
            os.close(file_descriptor)
        if temporary_name is not None:
            try:
                os.unlink(temporary_name, dir_fd=parent_fd)
            except OSError:
                pass


def _archive_member_signature(member: tarfile.TarInfo) -> tuple[Any, ...]:
    return (
        member.name,
        "directory" if member.isdir() else "file",
        member.size,
        member.mode,
    )


class _BoundedDecompressedReader:
    def __init__(self, reader: Any, maximum_bytes: int) -> None:
        self._reader = reader
        self._maximum_bytes = maximum_bytes
        self._bytes_read = 0

    def read(self, size: int = -1) -> bytes:
        remaining = self._maximum_bytes - self._bytes_read
        requested = remaining + 1 if size < 0 else min(size, remaining + 1)
        payload = self._reader.read(requested)
        self._bytes_read += len(payload)
        if self._bytes_read > self._maximum_bytes:
            raise SyncError(
                f"archive exceeds total expanded byte limit: > {self._maximum_bytes}"
            )
        return payload

    @property
    def bytes_read(self) -> int:
        return self._bytes_read


@contextlib.contextmanager
def _stream_archive_snapshot_with_metrics(
    snapshot: Any,
    *,
    maximum_expanded_bytes: int = MAX_ARCHIVE_EXPANDED_BYTES,
):
    snapshot.seek(0)
    try:
        with gzip.GzipFile(fileobj=snapshot, mode="rb") as decompressor:
            bounded_reader = _BoundedDecompressedReader(
                decompressor,
                maximum_expanded_bytes,
            )
            with tarfile.open(fileobj=bounded_reader, mode="r|") as archive:
                yield archive, bounded_reader
            while bounded_reader.read(1024 * 1024):
                pass
    finally:
        snapshot.seek(0)


@contextlib.contextmanager
def _stream_archive_snapshot(snapshot: Any):
    with _stream_archive_snapshot_with_metrics(snapshot) as (archive, _reader):
        yield archive


def _scan_archive_snapshot_with_metrics(
    snapshot: Any,
    *,
    maximum_expanded_bytes: int = MAX_ARCHIVE_EXPANDED_BYTES,
) -> tuple[
    list[tarfile.TarInfo],
    tuple[str, ...],
    tuple[str, ...],
    int,
]:
    members: list[tarfile.TarInfo] = []
    expanded_bytes = 0
    try:
        with _stream_archive_snapshot_with_metrics(
            snapshot,
            maximum_expanded_bytes=min(
                MAX_ARCHIVE_EXPANDED_BYTES,
                maximum_expanded_bytes,
            ),
        ) as (
            archive,
            bounded_reader,
        ):
            for member in archive:
                if len(members) >= MAX_ARCHIVE_MEMBERS:
                    raise SyncError(
                        f"archive exceeds {MAX_ARCHIVE_MEMBERS} member limit"
                    )
                _validate_tar_member(member)
                if member.isfile():
                    if member.size < 0 or member.size > MAX_ARCHIVE_MEMBER_BYTES:
                        raise SyncError(
                            "archive member exceeds expanded byte limit: "
                            f"{member.name}: {member.size} > {MAX_ARCHIVE_MEMBER_BYTES}"
                        )
                    expanded_bytes += member.size
                    if expanded_bytes > MAX_ARCHIVE_EXPANDED_BYTES:
                        raise SyncError(
                            "archive exceeds total expanded byte limit: "
                            f"{expanded_bytes} > {MAX_ARCHIVE_EXPANDED_BYTES}"
                        )
                members.append(member)
        scanned_bytes = bounded_reader.bytes_read
    except (tarfile.TarError, OSError, EOFError, zlib.error) as error:
        raise SyncError(f"failed to inspect archive snapshot: {error}") from error
    if not members:
        raise SyncError("archive is empty")
    _validate_archive_member_paths(members)
    release_root_parts, manifest_parts = _archive_release_root_parts(members)
    return members, release_root_parts, manifest_parts, scanned_bytes


def _scan_archive_snapshot(
    snapshot: Any,
) -> tuple[list[tarfile.TarInfo], tuple[str, ...], tuple[str, ...]]:
    members, release_root_parts, manifest_parts, _scanned_bytes = (
        _scan_archive_snapshot_with_metrics(snapshot)
    )
    return members, release_root_parts, manifest_parts


def _extract_archive_members(
    snapshot: Any,
    destination_fd: int,
    planned_members: list[tarfile.TarInfo],
) -> tuple[
    dict[tuple[str, ...], tuple[int, int]],
    dict[tuple[str, ...], tuple[int, ...]],
]:
    directory_identities = {(): _directory_identity(destination_fd)}
    file_identities: dict[tuple[str, ...], tuple[int, ...]] = {}
    directory_modes: dict[tuple[str, ...], int] = {}
    try:
        with _stream_archive_snapshot(snapshot) as archive:
            for expected_member in planned_members:
                member = archive.next()
                if member is None:
                    raise SyncError("archive snapshot ended before all planned members")
                _validate_tar_member(member)
                if _archive_member_signature(member) != _archive_member_signature(
                    expected_member
                ):
                    raise SyncError("archive snapshot metadata changed between passes")
                member_parts = PurePosixPath(member.name).parts
                if member.isdir():
                    directory_fd = _ensure_archive_directories(
                        destination_fd,
                        directory_identities,
                        member_parts,
                    )
                    try:
                        directory_modes[member_parts] = member.mode
                    finally:
                        os.close(directory_fd)
                else:
                    parent_fd = _ensure_archive_directories(
                        destination_fd,
                        directory_identities,
                        member_parts[:-1],
                    )
                    try:
                        file_identities[member_parts] = _write_archive_member_file(
                            archive,
                            member,
                            parent_fd,
                            member_parts[-1],
                        )
                    finally:
                        os.close(parent_fd)
            if archive.next() is not None:
                raise SyncError("archive snapshot gained members between passes")
        for directory_parts, mode in sorted(
            directory_modes.items(),
            key=lambda item: len(item[0]),
            reverse=True,
        ):
            directory_fd = _open_archive_directory(
                destination_fd,
                directory_identities,
                directory_parts,
            )
            try:
                os.fchmod(directory_fd, mode)
            finally:
                os.close(directory_fd)
        return directory_identities, file_identities
    except (tarfile.TarError, OSError, EOFError, zlib.error) as error:
        raise SyncError(f"failed to extract archive snapshot: {error}") from error


def _archive_release_root_parts(
    members: list[tarfile.TarInfo],
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    manifest_parts = MANIFEST_RELATIVE_PATH.parts
    candidates: list[tuple[tuple[str, ...], tuple[str, ...]]] = []
    for member in members:
        if not member.isfile():
            continue
        member_parts = PurePosixPath(member.name).parts
        if member_parts == manifest_parts:
            candidates.append(((), member_parts))
        elif (
            len(member_parts) == len(manifest_parts) + 1
            and member_parts[1:] == manifest_parts
        ):
            candidates.append((member_parts[:1], member_parts))
    if len(candidates) != 1:
        raise SyncError(
            "archive must contain exactly one release root with sync manifest"
        )
    return candidates[0]


def _validate_archive_tree_evidence(
    destination_fd: int,
    directory_identities: dict[tuple[str, ...], tuple[int, int]],
    file_identities: dict[tuple[str, ...], tuple[int, ...]],
    manifest_parts: tuple[str, ...],
) -> None:
    expected_children: dict[tuple[str, ...], set[str]] = {
        parts: set() for parts in directory_identities
    }
    for directory_parts in directory_identities:
        if directory_parts:
            expected_children[directory_parts[:-1]].add(directory_parts[-1])
    for file_parts in file_identities:
        expected_children[file_parts[:-1]].add(file_parts[-1])

    for directory_parts in sorted(directory_identities, key=len):
        directory_fd = _open_archive_directory(
            destination_fd,
            directory_identities,
            directory_parts,
        )
        try:
            metadata = os.fstat(directory_fd)
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or _directory_identity(directory_fd)
                != directory_identities[directory_parts]
            ):
                raise SyncError("archive directory changed during validation")
            with os.scandir(directory_fd) as entries:
                actual_children = {entry.name for entry in entries}
            if actual_children != expected_children[directory_parts]:
                raise SyncError("archive directory entries changed during validation")
        finally:
            os.close(directory_fd)

    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    for file_parts, expected_identity in file_identities.items():
        parent_fd = _open_archive_directory(
            destination_fd,
            directory_identities,
            file_parts[:-1],
        )
        try:
            file_descriptor = os.open(
                file_parts[-1],
                flags,
                dir_fd=parent_fd,
            )
        except OSError as error:
            os.close(parent_fd)
            raise SyncError("archive file changed during validation") from error
        try:
            metadata = os.fstat(file_descriptor)
            if (
                not stat.S_ISREG(metadata.st_mode)
                or _regular_file_snapshot(metadata) != expected_identity
            ):
                raise SyncError("archive file changed during validation")
        finally:
            os.close(file_descriptor)
            os.close(parent_fd)

    if manifest_parts not in file_identities:
        raise SyncError("archive release manifest was not extracted")


def _safe_extract_archive_snapshot(
    snapshot: Any,
    destination: Path,
    *,
    workspace: BoundArchiveWorkspace,
) -> tuple[Path, ReleaseTreeExpectation]:
    planned_members, release_root_parts, manifest_parts = _scan_archive_snapshot(
        snapshot
    )
    parent_fd, destination_fd = _create_archive_destination(
        destination,
        workspace,
    )
    directory_identities = {(): _directory_identity(destination_fd)}
    release_fd: int | None = None
    try:
        directory_identities, file_identities = _extract_archive_members(
            snapshot,
            destination_fd,
            planned_members,
        )
        _validate_archive_tree_evidence(
            destination_fd,
            directory_identities,
            file_identities,
            manifest_parts,
        )
        release_root = destination.joinpath(*release_root_parts)
        release_fd = _open_archive_directory(
            destination_fd,
            directory_identities,
            release_root_parts,
        )
        release_directory_identity = _directory_identity(release_fd)
        initial_release_identity = _release_tree_identity_from_directory_fd(
            release_fd,
            release_root,
            require_sanitized_modes=True,
        )
        _validate_archive_tree_evidence(
            destination_fd,
            directory_identities,
            file_identities,
            manifest_parts,
        )
        final_release_identity = _release_tree_identity_from_directory_fd(
            release_fd,
            release_root,
            require_sanitized_modes=True,
        )
        if final_release_identity != initial_release_identity:
            raise SyncError("archive release content changed during final validation")
        if _directory_identity(release_fd) != release_directory_identity:
            raise SyncError("archive release root changed during final validation")
        _validate_archive_tree_evidence(
            destination_fd,
            directory_identities,
            file_identities,
            manifest_parts,
        )
        if (
            not _archive_path_matches_fd(destination.parent, parent_fd)
            or not _archive_entry_matches_fd(
                parent_fd,
                destination.name,
                destination_fd,
            )
            or not _archive_path_matches_fd(destination, destination_fd)
        ):
            raise SyncError(
                f"archive destination changed during extraction: {destination}"
            )
        workspace_check_fd = _duplicate_bound_archive_workspace(workspace)
        os.close(workspace_check_fd)
        return release_root, (
            final_release_identity,
            release_directory_identity,
        )
    finally:
        if release_fd is not None:
            os.close(release_fd)
        os.close(destination_fd)
        os.close(parent_fd)


def safe_extract_archive(
    archive_path: Path,
    destination: Path,
    *,
    workspace: BoundArchiveWorkspace,
) -> Path:
    workspace_check_fd = _duplicate_bound_archive_workspace(workspace)
    os.close(workspace_check_fd)
    snapshot, _digest = _copy_archive_to_immutable_snapshot(
        archive_path,
        workspace=workspace,
    )
    try:
        release_root, _release_expectation = _safe_extract_archive_snapshot(
            snapshot,
            destination,
            workspace=workspace,
        )
        return release_root
    finally:
        snapshot.close()


def verify_and_extract_archive(
    archive_path: Path,
    checksum_path: Path,
    destination: Path,
    *,
    workspace: BoundArchiveWorkspace,
    read_workspace: (
        BoundArchiveWorkspace | None | _UseArchiveWorkspace
    ) = _USE_ARCHIVE_WORKSPACE,
    archive_api_digest: str | None = None,
    checksum_api_digest: str | None = None,
) -> tuple[Path, ReleaseTreeExpectation]:
    workspace_check_fd = _duplicate_bound_archive_workspace(workspace)
    os.close(workspace_check_fd)
    effective_read_workspace = (
        workspace
        if isinstance(read_workspace, _UseArchiveWorkspace)
        else read_workspace
    )
    snapshot = _verified_archive_snapshot(
        archive_path,
        checksum_path,
        workspace=effective_read_workspace,
        archive_api_digest=archive_api_digest,
        checksum_api_digest=checksum_api_digest,
    )
    try:
        return _safe_extract_archive_snapshot(
            snapshot,
            destination,
            workspace=workspace,
        )
    finally:
        snapshot.close()


def _release_tree_digest_from_logical_entries(
    entries: dict[PurePosixPath, tuple[bytes, int, bytes]],
) -> str:
    """Hash one normalized release tree with the installed-tree wire format."""
    digest = hashlib.sha256(b"codex-personal-sync-release-tree-v1\0")

    def record(
        entry_type: bytes,
        relative_path: PurePosixPath,
        mode: int,
        content_identity: bytes,
    ) -> None:
        relative_bytes = (
            relative_path.as_posix().encode("utf-8", "surrogateescape")
            if relative_path.parts
            else b""
        )
        _release_tree_digest_field(digest, entry_type)
        _release_tree_digest_field(digest, relative_bytes)
        _release_tree_digest_field(digest, mode.to_bytes(4, "big"))
        _release_tree_digest_field(digest, content_identity)

    record(b"directory", PurePosixPath(), 0, b"")
    for relative_path in sorted(entries, key=lambda path: path.parts):
        entry_type, mode, content_identity = entries[relative_path]
        if not relative_path.parts:
            raise SyncError("logical release tree must not contain its container root")
        if entry_type not in {b"directory", b"file"}:
            raise SyncError("logical release tree contains an invalid entry type")
        if entry_type == b"directory":
            if content_identity:
                raise SyncError("logical release directory has file content identity")
        elif len(content_identity) != 40:
            raise SyncError("logical release file has an invalid content identity")
        record(entry_type, relative_path, mode, content_identity)
    return digest.hexdigest()


def _logical_archive_tree_entries(
    members: list[tarfile.TarInfo],
    release_root_parts: tuple[str, ...],
) -> dict[PurePosixPath, tuple[bytes, int, bytes]]:
    entries: dict[PurePosixPath, tuple[bytes, int, bytes]] = {}
    root_length = len(release_root_parts)
    for member in members:
        member_parts = PurePosixPath(member.name).parts
        if member_parts[:root_length] != release_root_parts:
            raise SyncError(
                f"archive member is outside the release root: {member.name}"
            )
        relative_parts = member_parts[root_length:]
        if not relative_parts:
            if not member.isdir():
                raise SyncError("archive release root must be a directory container")
            continue
        relative_path = PurePosixPath(*relative_parts)
        for length in range(1, len(relative_parts)):
            parent = PurePosixPath(*relative_parts[:length])
            entries.setdefault(parent, (b"directory", 0o755, b""))
        if member.isdir():
            if member.mode != 0o755:
                raise SyncError(
                    f"archive release directory mode is not canonical: "
                    f"{member.name}: {member.mode:#o} != 0o755"
                )
            entries[relative_path] = (b"directory", member.mode, b"")
        else:
            if member.mode not in {0o644, 0o755}:
                raise SyncError(
                    f"archive release file mode is not canonical: "
                    f"{member.name}: {member.mode:#o}"
                )
            entries[relative_path] = (b"file", member.mode, b"")
    return entries


def _read_release_manifest_from_archive_snapshot(
    snapshot: Any,
    sha: str,
    *,
    maximum_expanded_bytes: int = MAX_ARCHIVE_EXPANDED_BYTES * 2,
) -> tuple[dict[str, Any], int, str]:
    if (
        isinstance(maximum_expanded_bytes, bool)
        or not isinstance(maximum_expanded_bytes, int)
        or maximum_expanded_bytes < 0
    ):
        raise SyncError("archive expanded byte budget must be a non-negative integer")
    (
        planned_members,
        release_root_parts,
        manifest_parts,
        first_pass_bytes,
    ) = _scan_archive_snapshot_with_metrics(
        snapshot,
        maximum_expanded_bytes=min(
            MAX_ARCHIVE_EXPANDED_BYTES,
            maximum_expanded_bytes,
        ),
    )
    expected_root_parts = (f"personal-codex-{sha}",)
    expected_manifest_parts = (
        *expected_root_parts,
        *MANIFEST_RELATIVE_PATH.parts,
    )
    expected_manifest_path = "/".join(expected_manifest_parts)
    if (
        release_root_parts != expected_root_parts
        or manifest_parts != expected_manifest_parts
    ):
        raise SyncError(
            "archive must contain exactly one release manifest at "
            f"{expected_manifest_path}"
        )

    logical_entries = _logical_archive_tree_entries(
        planned_members,
        release_root_parts,
    )

    manifest_payload: bytes | None = None
    try:
        remaining_expanded_bytes = maximum_expanded_bytes - first_pass_bytes
        with _stream_archive_snapshot_with_metrics(
            snapshot,
            maximum_expanded_bytes=min(
                MAX_ARCHIVE_EXPANDED_BYTES,
                remaining_expanded_bytes,
            ),
        ) as (
            archive,
            bounded_reader,
        ):
            for expected_member in planned_members:
                member = archive.next()
                if member is None:
                    raise SyncError("archive snapshot ended before all planned members")
                _validate_tar_member(member)
                if _archive_member_signature(member) != _archive_member_signature(
                    expected_member
                ):
                    raise SyncError("archive snapshot metadata changed between passes")
                member_parts = PurePosixPath(member.name).parts
                if member.isdir():
                    continue
                is_manifest = member_parts == expected_manifest_parts
                if is_manifest and manifest_payload is not None:
                    raise SyncError(
                        "archive contains duplicate release manifest entries"
                    )
                if is_manifest and member.size > MAX_RELEASE_MANIFEST_BYTES:
                    raise SyncError(
                        "archive release manifest exceeds byte limit: "
                        f"{member.size} > {MAX_RELEASE_MANIFEST_BYTES}"
                    )
                source = archive.extractfile(member)
                if source is None:
                    raise SyncError(f"failed to read archive member: {member.name}")
                try:
                    content_digest = hashlib.sha256()
                    manifest_chunks: list[bytes] | None = [] if is_manifest else None
                    remaining = member.size
                    while remaining:
                        chunk = source.read(min(1024 * 1024, remaining))
                        if not chunk:
                            raise SyncError(
                                f"archive member ended early: {member.name}"
                            )
                        content_digest.update(chunk)
                        if manifest_chunks is not None:
                            manifest_chunks.append(chunk)
                        remaining -= len(chunk)
                    if source.read(1):
                        raise SyncError(
                            f"archive member grew while reading: {member.name}"
                        )
                finally:
                    source.close()
                relative_path = PurePosixPath(*member_parts[len(release_root_parts) :])
                logical_entries[relative_path] = (
                    b"file",
                    member.mode,
                    member.size.to_bytes(8, "big") + content_digest.digest(),
                )
                if manifest_chunks is not None:
                    manifest_payload = b"".join(manifest_chunks)
            if archive.next() is not None:
                raise SyncError("archive snapshot gained members between passes")
        second_pass_bytes = bounded_reader.bytes_read
    except (tarfile.TarError, OSError, EOFError, zlib.error) as error:
        raise SyncError(f"failed to read archive release manifest: {error}") from error
    if manifest_payload is None:
        raise SyncError("archive release manifest disappeared between passes")
    manifest = _decode_manifest_payload(
        manifest_payload,
        Path(expected_manifest_path),
    )
    return (
        manifest,
        first_pass_bytes + second_pass_bytes,
        _release_tree_digest_from_logical_entries(logical_entries),
    )


def read_verified_release_manifest(
    repo: str,
    assets: ReleaseAssets,
    *,
    maximum_expanded_bytes: int = MAX_ARCHIVE_EXPANDED_BYTES * 2,
) -> VerifiedReleaseManifest:
    """Download exact assets and read the release manifest without extraction."""
    if not isinstance(repo, str) or REPOSITORY_RE.fullmatch(repo) is None:
        raise SyncError("release repository must be an owner/repo string")
    if not isinstance(assets, ReleaseAssets):
        raise SyncError("release assets must use the ReleaseAssets record")
    if (
        isinstance(maximum_expanded_bytes, bool)
        or not isinstance(maximum_expanded_bytes, int)
        or maximum_expanded_bytes < 0
    ):
        raise SyncError("archive expanded byte budget must be a non-negative integer")
    normalized_assets = select_release_assets(
        {
            "tagName": assets.tag_name,
            "targetCommitish": assets.sha,
            "assets": [
                {
                    "id": assets.archive_id,
                    "name": assets.archive_name,
                    "size": assets.archive_size,
                    "state": "uploaded",
                    "digest": assets.archive_digest,
                },
                {
                    "id": assets.checksum_id,
                    "name": assets.checksum_name,
                    "size": assets.checksum_size,
                    "state": "uploaded",
                    "digest": assets.checksum_digest,
                },
            ],
        },
        require_digests=True,
    )
    if normalized_assets != assets:
        raise SyncError("release asset metadata is internally inconsistent")

    try:
        with temporary_archive_workspace(prefix="codex-release-manifest.") as workspace:
            destination = workspace.path
            download_release_assets(
                repo,
                assets,
                destination,
                workspace=workspace,
            )
            archive_path = destination / assets.archive_name
            checksum_path = destination / assets.checksum_name
            snapshot = _verified_archive_snapshot(
                archive_path,
                checksum_path,
                workspace=workspace,
                archive_api_digest=assets.archive_digest,
                checksum_api_digest=assets.checksum_digest,
            )
            try:
                manifest, expanded_bytes, tree_digest = (
                    _read_release_manifest_from_archive_snapshot(
                        snapshot,
                        assets.sha,
                        maximum_expanded_bytes=maximum_expanded_bytes,
                    )
                )
            finally:
                snapshot.close()
    except SyncError:
        raise
    except OSError as error:
        raise SyncError(f"failed to read verified release manifest: {error}") from error
    return VerifiedReleaseManifest(
        manifest=manifest,
        expanded_bytes=expanded_bytes,
        tree_digest=tree_digest,
    )


def find_release_root(extract_root: Path) -> Path:
    if (extract_root / MANIFEST_RELATIVE_PATH).is_file():
        return extract_root
    candidates = [
        child
        for child in extract_root.iterdir()
        if child.is_dir() and (child / MANIFEST_RELATIVE_PATH).is_file()
    ]
    if len(candidates) != 1:
        raise SyncError(
            "archive must contain exactly one release root with sync manifest"
        )
    return candidates[0]


def _personal_sync_root(home: Path) -> Path:
    return home / "personal-sync"


def _owner_sync_root(home: Path, owner: str) -> Path:
    owner = _validate_explicit_owner(owner)
    sync_root = _personal_sync_root(home)
    if owner == PUBLIC_OWNER:
        return sync_root
    return sync_root / "overlays" / owner


def _releases_root(home: Path, owner: str = PUBLIC_OWNER) -> Path:
    return _owner_sync_root(home, owner) / "releases"


def _current_link(home: Path, owner: str = PUBLIC_OWNER) -> Path:
    return _owner_sync_root(home, owner) / "current"


def _install_lock_path(home: Path) -> Path:
    return _personal_sync_root(home) / "install.lock"


def _state_path(home: Path) -> Path:
    return _personal_sync_root(home) / STATE_RELATIVE_PATH


def _pending_link_pointer_path(home: Path) -> Path:
    # Keep the WAL pointer on the same stable home inode used by
    # ``installation_lock``.  Every directory below home may be atomically
    # rotated during recovery; placing the only pointer inside one of them
    # would let that rotation hide an unfinished transaction.
    return home / PENDING_LINK_POINTER_NAME


def _internal_path_parts(home: Path, path: Path) -> tuple[str, ...]:
    try:
        parts = _directory_parts_beneath(home, path)
    except SyncError as error:
        raise SyncError(f"sync internal path is outside home: {path}") from error
    if not parts or parts[0] != "personal-sync":
        raise SyncError(f"path is not inside personal-sync: {path}")
    return parts


def _ensure_safe_internal_directory(
    home: Path,
    path: Path,
    *,
    create: bool,
    allow_missing: bool = False,
) -> bool:
    """Validate every personal-sync directory component without following symlinks."""
    parts = _internal_path_parts(home, path)
    if create:
        home_fd = _open_or_create_bound_sync_home(home)
        try:
            directory_fd = _open_or_create_directory_beneath(
                home,
                path,
                mode=0o700,
                home_fd=home_fd,
            )
            try:
                if not _bound_directory_matches(home, path, directory_fd):
                    raise SyncError(f"sync internal directory changed: {path}")
            finally:
                _close_fd_quietly(directory_fd)
        finally:
            _close_fd_quietly(home_fd)
        return True
    current = home
    for part in parts:
        current = current / part
        try:
            mode = os.lstat(current).st_mode
        except FileNotFoundError:
            if not create:
                if allow_missing:
                    return False
                raise SyncError(f"sync internal directory is missing: {current}")
            try:
                os.mkdir(current, mode=0o700)
            except FileExistsError:
                pass
            try:
                mode = os.lstat(current).st_mode
            except FileNotFoundError as error:
                raise SyncError(
                    f"sync internal directory changed while creating it: {current}"
                ) from error
        if stat.S_ISLNK(mode):
            raise SyncError(f"refusing symlinked sync internal directory: {current}")
        if not stat.S_ISDIR(mode):
            raise SyncError(f"sync internal path is not a directory: {current}")
    return True


def _ensure_safe_internal_parent(
    home: Path,
    path: Path,
    *,
    create: bool,
    allow_missing: bool = False,
) -> bool:
    _internal_path_parts(home, path)
    return _ensure_safe_internal_directory(
        home,
        path.parent,
        create=create,
        allow_missing=allow_missing,
    )


def _directory_parts_beneath(home: Path, directory: Path) -> tuple[str, ...]:
    if os.fspath(directory) in {"", "."}:
        raise SyncError(f"refusing unsafe directory path component: {directory}")
    if home.is_absolute() != directory.is_absolute():
        raise SyncError(f"directory is outside sync home: {directory}")
    try:
        relative = directory.relative_to(home)
    except ValueError as error:
        raise SyncError(f"directory is outside sync home: {directory}") from error
    if any(part in {"", ".", ".."} for part in relative.parts):
        raise SyncError(f"refusing unsafe directory path component: {directory}")
    return relative.parts


def _directory_open_flags(*, nofollow: bool) -> int:
    root_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    root_flags |= getattr(os, "O_CLOEXEC", 0)
    if nofollow:
        root_flags |= getattr(os, "O_NOFOLLOW", 0)
    return root_flags


def _open_sync_home_parent(home: Path) -> int:
    parent = home.parent
    try:
        parent_fd = os.open(parent, _directory_open_flags(nofollow=True))
    except FileNotFoundError:
        raise
    except OSError as error:
        raise SyncError(f"refusing unsafe sync home parent: {parent}") from error
    if not _archive_path_matches_fd(parent, parent_fd):
        _close_fd_quietly(parent_fd)
        raise SyncError(f"sync home parent changed while opening it: {parent}")
    return parent_fd


def _sync_home_matches_fd(
    home: Path,
    home_fd: int,
    *,
    parent_fd: int | None = None,
) -> bool:
    try:
        _directory_identity(home_fd)
    except (OSError, SyncError):
        return False
    if home.is_absolute() and home.parent == home:
        return _archive_path_matches_fd(home, home_fd)
    owns_parent_fd = parent_fd is None
    if parent_fd is None:
        try:
            parent_fd = _open_sync_home_parent(home)
        except (OSError, SyncError):
            return False
    try:
        return (
            _archive_path_matches_fd(home.parent, parent_fd)
            and _archive_entry_matches_fd(parent_fd, home.name, home_fd)
            and _archive_path_matches_fd(home.parent, parent_fd)
        )
    finally:
        if owns_parent_fd:
            _close_fd_quietly(parent_fd)


_LOCKED_SYNC_HOME_BINDINGS: ContextVar[tuple[tuple[str, int], ...]] = ContextVar(
    "locked_sync_home_bindings",
    default=(),
)
_ACTIVE_SCHEDULER_ATTEMPT: ContextVar[SchedulerAttemptGuard | None] = ContextVar(
    "active_scheduler_attempt",
    default=None,
)
_GH_OPERATION_DEADLINE: ContextVar[float | None] = ContextVar(
    "gh_operation_deadline",
    default=None,
)


def _sync_home_binding_key(home: Path) -> str:
    return os.path.abspath(os.fspath(home.expanduser()))


def _locked_sync_home_fd(home: Path) -> int | None:
    binding_key = _sync_home_binding_key(home)
    for candidate_key, candidate_fd in reversed(_LOCKED_SYNC_HOME_BINDINGS.get()):
        if candidate_key == binding_key:
            return candidate_fd
    return None


def _open_sync_home(home: Path) -> int:
    if os.fspath(home) in {"", ".", ".."}:
        raise SyncError(f"refusing unsafe sync home: {home}")
    flags = _directory_open_flags(nofollow=True)
    if home.is_absolute() and home.parent == home:
        try:
            home_fd = os.open(home, flags)
        except OSError as error:
            raise SyncError(f"refusing unsafe sync home: {home}") from error
        if not _sync_home_matches_fd(home, home_fd):
            _close_fd_quietly(home_fd)
            raise SyncError(f"sync home changed while opening it: {home}")
        return home_fd

    parent_fd = _open_sync_home_parent(home)
    try:
        try:
            home_fd = os.open(home.name, flags, dir_fd=parent_fd)
        except FileNotFoundError:
            raise
        except OSError as error:
            raise SyncError(f"refusing unsafe sync home: {home}") from error
        if not _sync_home_matches_fd(home, home_fd, parent_fd=parent_fd):
            _close_fd_quietly(home_fd)
            raise SyncError(f"sync home changed while opening it: {home}")
        return home_fd
    finally:
        _close_fd_quietly(parent_fd)


def _open_or_create_sync_home(home: Path, *, mode: int = 0o755) -> int:
    if os.fspath(home) in {"", ".", ".."}:
        raise SyncError(f"refusing unsafe sync home: {home}")
    if home.is_absolute() and home.parent == home:
        return _open_sync_home(home)
    home.parent.mkdir(parents=True, exist_ok=True)
    parent_fd = _open_sync_home_parent(home)
    home_fd = -1
    created = False
    try:
        try:
            os.mkdir(home.name, mode=mode, dir_fd=parent_fd)
            created = True
        except FileExistsError:
            pass
        try:
            home_fd = os.open(
                home.name,
                _directory_open_flags(nofollow=True),
                dir_fd=parent_fd,
            )
        except OSError as error:
            raise SyncError(f"refusing unsafe sync home: {home}") from error
        if created:
            os.fsync(home_fd)
            os.fsync(parent_fd)
        if not _sync_home_matches_fd(home, home_fd, parent_fd=parent_fd):
            raise SyncError(f"sync home changed while creating it: {home}")
        result = home_fd
        home_fd = -1
        return result
    finally:
        if home_fd >= 0:
            _close_fd_quietly(home_fd)
        _close_fd_quietly(parent_fd)


def _bound_sync_home_anchor(home: Path, home_fd: int | None) -> int:
    if home_fd is None:
        home_fd = _locked_sync_home_fd(home)
        if home_fd is None:
            return _open_sync_home(home)
    if not _sync_home_matches_fd(home, home_fd):
        raise SyncError(f"sync home changed before reopening it: {home}")
    anchor_fd = os.dup(home_fd)
    if not _sync_home_matches_fd(home, anchor_fd):
        _close_fd_quietly(anchor_fd)
        raise SyncError(f"sync home changed while reopening it: {home}")
    return anchor_fd


def _open_or_create_bound_sync_home(home: Path, *, mode: int = 0o755) -> int:
    locked_home_fd = _locked_sync_home_fd(home)
    if locked_home_fd is not None:
        return _bound_sync_home_anchor(home, locked_home_fd)
    return _open_or_create_sync_home(home, mode=mode)


def _open_directory_beneath(
    home: Path,
    directory: Path,
    *,
    home_fd: int | None = None,
) -> int:
    parts = _directory_parts_beneath(home, directory)
    anchor_fd = _bound_sync_home_anchor(home, home_fd)
    directory_fd = -1
    child_flags = _directory_open_flags(nofollow=True)
    try:
        directory_fd = os.dup(anchor_fd)
        for part in parts:
            next_fd = os.open(part, child_flags, dir_fd=directory_fd)
            os.close(directory_fd)
            directory_fd = next_fd
        if not _sync_home_matches_fd(home, anchor_fd):
            raise SyncError(f"sync home changed while opening directory: {directory}")
    except BaseException:
        if directory_fd >= 0:
            _close_fd_quietly(directory_fd)
        raise
    finally:
        _close_fd_quietly(anchor_fd)
    return directory_fd


def _open_or_create_directory_beneath(
    home: Path,
    directory: Path,
    *,
    mode: int = 0o755,
    home_fd: int | None = None,
) -> int:
    parts = _directory_parts_beneath(home, directory)
    anchor_fd = _bound_sync_home_anchor(home, home_fd)
    directory_fd = -1
    child_flags = _directory_open_flags(nofollow=True)
    try:
        directory_fd = os.dup(anchor_fd)
        for part in parts:
            try:
                next_fd = os.open(part, child_flags, dir_fd=directory_fd)
            except FileNotFoundError:
                created = False
                try:
                    os.mkdir(part, mode=mode, dir_fd=directory_fd)
                    created = True
                except FileExistsError:
                    pass
                next_fd = os.open(part, child_flags, dir_fd=directory_fd)
                if created:
                    os.fsync(next_fd)
                    os.fsync(directory_fd)
            os.close(directory_fd)
            directory_fd = next_fd
        if not _sync_home_matches_fd(home, anchor_fd):
            raise SyncError(f"sync home changed while creating directory: {directory}")
    except BaseException as error:
        if directory_fd >= 0:
            _close_fd_quietly(directory_fd)
        if isinstance(error, OSError):
            raise SyncError(f"refusing unsafe directory path: {directory}") from error
        raise
    finally:
        _close_fd_quietly(anchor_fd)
    return directory_fd


def _close_fd_quietly(file_descriptor: int) -> None:
    try:
        os.close(file_descriptor)
    except OSError:
        pass


def _directory_identity(directory_fd: int) -> tuple[int, int]:
    metadata = os.fstat(directory_fd)
    if not stat.S_ISDIR(metadata.st_mode):
        raise SyncError("bound path is no longer a directory")
    return metadata.st_dev, metadata.st_ino


def _bound_directory_matches(home: Path, directory: Path, directory_fd: int) -> bool:
    expected_identity = _directory_identity(directory_fd)
    try:
        canonical_fd = _open_directory_beneath(home, directory)
    except (OSError, SyncError):
        return False
    try:
        return _directory_identity(canonical_fd) == expected_identity
    finally:
        _close_fd_quietly(canonical_fd)


def _rename_noreplace_at(
    source_parent_fd: int,
    source_name: str,
    destination_parent_fd: int,
    destination_name: str,
) -> None:
    libc = ctypes.CDLL(None, use_errno=True)
    source_bytes = os.fsencode(source_name)
    destination_bytes = os.fsencode(destination_name)
    if sys.platform == "darwin":
        rename_function = libc.renameatx_np
        rename_function.argtypes = [
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_uint,
        ]
        rename_function.restype = ctypes.c_int
        result = rename_function(
            source_parent_fd,
            source_bytes,
            destination_parent_fd,
            destination_bytes,
            0x00000004,
        )
    elif sys.platform.startswith("linux"):
        try:
            rename_function = libc.renameat2
        except AttributeError as error:
            raise SyncError(
                "renameat2 is required for safe sync reconciliation"
            ) from error
        rename_function.argtypes = [
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_uint,
        ]
        rename_function.restype = ctypes.c_int
        result = rename_function(
            source_parent_fd,
            source_bytes,
            destination_parent_fd,
            destination_bytes,
            0x00000001,
        )
    else:
        raise SyncError(
            f"safe no-replace rename is unsupported on platform {sys.platform}"
        )
    if result != 0:
        error_number = ctypes.get_errno()
        raise OSError(
            error_number,
            os.strerror(error_number),
            f"{source_name} -> {destination_name}",
        )


def _rename_exchange_at(
    first_parent_fd: int,
    first_name: str,
    second_parent_fd: int,
    second_name: str,
) -> None:
    libc = ctypes.CDLL(None, use_errno=True)
    first_bytes = os.fsencode(first_name)
    second_bytes = os.fsencode(second_name)
    if sys.platform == "darwin":
        rename_function = libc.renameatx_np
        rename_function.argtypes = [
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_uint,
        ]
        rename_function.restype = ctypes.c_int
        result = rename_function(
            first_parent_fd,
            first_bytes,
            second_parent_fd,
            second_bytes,
            0x00000002,
        )
    elif sys.platform.startswith("linux"):
        try:
            rename_function = libc.renameat2
        except AttributeError as error:
            raise SyncError(
                "renameat2 is required for safe scheduler publication"
            ) from error
        rename_function.argtypes = [
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_uint,
        ]
        rename_function.restype = ctypes.c_int
        result = rename_function(
            first_parent_fd,
            first_bytes,
            second_parent_fd,
            second_bytes,
            0x00000002,
        )
    else:
        raise SyncError(
            f"safe exchange rename is unsupported on platform {sys.platform}"
        )
    if result != 0:
        error_number = ctypes.get_errno()
        raise OSError(
            error_number,
            os.strerror(error_number),
            f"{first_name} <-> {second_name}",
        )


def _failed_move_isolation_parent(home: Path) -> Path:
    return _personal_sync_root(home) / FAILED_MOVE_ISOLATION_DIRECTORY_NAME


def _failed_move_receipt_payload(
    home: Path,
    source: Path,
    source_parent_identity: tuple[int, int],
    destination: Path,
    destination_parent_identity: tuple[int, int],
    isolated: Path,
    isolation_parent_identity: tuple[int, int],
    expected_identity: tuple[int, int],
    expected_mode_type: int,
    expected_target: str | None,
    expected_regular: RegularFileSnapshot | None,
) -> bytes:
    try:
        source_relative = PurePosixPath(*source.relative_to(home).parts)
        destination_relative = PurePosixPath(*destination.relative_to(home).parts)
        isolated_relative = PurePosixPath(*isolated.relative_to(home).parts)
    except ValueError as error:
        raise SyncError("failed-move recovery path escaped the sync home") from error
    regular_payload = None
    if expected_regular is not None:
        regular_payload = {
            "sha256": expected_regular.sha256,
            "size": expected_regular.size,
            "mode": expected_regular.mode,
            "uid": expected_regular.uid,
            "gid": expected_regular.gid,
            "link_count": expected_regular.link_count,
        }
    return _bounded_json_document(
        {
            "version": 1,
            "source": source_relative.as_posix(),
            "source_parent_identity": _identity_payload(source_parent_identity),
            "destination": destination_relative.as_posix(),
            "destination_parent_identity": _identity_payload(
                destination_parent_identity
            ),
            "isolated": isolated_relative.as_posix(),
            "isolation_parent_identity": _identity_payload(isolation_parent_identity),
            "expected_identity": _identity_payload(expected_identity),
            "expected_mode_type": expected_mode_type,
            "expected_target": expected_target,
            "expected_regular": regular_payload,
        },
        max_bytes=4096,
        overflow_error="failed-move recovery receipt exceeds the size limit",
    )


def _read_failed_move_recovery_receipt(
    home: Path,
) -> tuple[ManagedStateFileSnapshot, FailedMoveRecoveryReceipt] | None:
    isolation_parent = _failed_move_isolation_parent(home)
    receipt_path = isolation_parent / FAILED_MOVE_RECEIPT_NAME
    try:
        parent_fd = _open_directory_beneath(home, isolation_parent)
    except FileNotFoundError:
        return None
    try:
        parent_identity = _directory_identity(parent_fd)
        metadata = os.fstat(parent_fd)
        if (
            stat.S_IMODE(metadata.st_mode) != 0o700
            or metadata.st_uid != os.geteuid()
            or not _bound_directory_matches(home, isolation_parent, parent_fd)
        ):
            raise SyncError("failed-move recovery directory access policy changed")
        snapshot = _read_managed_state_file_snapshot(
            home,
            receipt_path,
            parent_fd,
            maximum_bytes=4096,
        )
    finally:
        _close_fd_quietly(parent_fd)
    if not snapshot.exists:
        return None
    if (
        not _managed_state_snapshot_has_complete_file_evidence(snapshot)
        or snapshot.file_type != stat.S_IFREG
        or snapshot.mode != 0o600
        or snapshot.uid != os.geteuid()
    ):
        raise SyncError("failed-move recovery receipt changed")
    data = _decode_managed_state_json(snapshot.payload, receipt_path)
    if (
        set(data)
        != {
            "version",
            "source",
            "source_parent_identity",
            "destination",
            "destination_parent_identity",
            "isolated",
            "isolation_parent_identity",
            "expected_identity",
            "expected_mode_type",
            "expected_target",
            "expected_regular",
        }
        or data.get("version") != 1
    ):
        raise SyncError("failed-move recovery receipt changed")
    source_relative = _validate_relative_path(
        data.get("source"), "failed-move recovery source"
    )
    destination_relative = _validate_relative_path(
        data.get("destination"), "failed-move recovery destination"
    )
    isolated_relative = _validate_relative_path(
        data.get("isolated"), "failed-move recovery isolated path"
    )
    source_parent_identity = _parse_pending_identity(
        data.get("source_parent_identity"),
        "failed-move recovery source parent identity",
    )
    destination_parent_identity = _parse_pending_identity(
        data.get("destination_parent_identity"),
        "failed-move recovery destination parent identity",
    )
    isolation_parent_identity = _parse_pending_identity(
        data.get("isolation_parent_identity"),
        "failed-move recovery isolation parent identity",
    )
    expected_identity = _parse_pending_identity(
        data.get("expected_identity"),
        "failed-move recovery entry identity",
    )
    expected_mode_type = data.get("expected_mode_type")
    expected_target = data.get("expected_target")
    if (
        source_parent_identity is None
        or destination_parent_identity is None
        or isolation_parent_identity is None
        or expected_identity is None
        or not isinstance(expected_mode_type, int)
        or isinstance(expected_mode_type, bool)
        or expected_mode_type not in {stat.S_IFREG, stat.S_IFLNK, stat.S_IFDIR}
        or (expected_target is not None and not isinstance(expected_target, str))
    ):
        raise SyncError("failed-move recovery receipt changed")
    expected_regular = None
    raw_regular = data.get("expected_regular")
    if raw_regular is not None:
        if not isinstance(raw_regular, dict) or set(raw_regular) != {
            "sha256",
            "size",
            "mode",
            "uid",
            "gid",
            "link_count",
        }:
            raise SyncError("failed-move recovery receipt changed")
        integer_fields = ("size", "mode", "uid", "gid", "link_count")
        if (
            expected_mode_type != stat.S_IFREG
            or not isinstance(raw_regular.get("sha256"), str)
            or len(raw_regular["sha256"]) != 64
            or any(
                not isinstance(raw_regular.get(field), int)
                or isinstance(raw_regular.get(field), bool)
                for field in integer_fields
            )
        ):
            raise SyncError("failed-move recovery receipt changed")
        expected_regular = RegularFileSnapshot(
            parent_identity=source_parent_identity,
            file_identity=expected_identity,
            sha256=raw_regular["sha256"],
            size=raw_regular["size"],
            mode=raw_regular["mode"],
            uid=raw_regular["uid"],
            gid=raw_regular["gid"],
            link_count=raw_regular["link_count"],
        )
    elif expected_mode_type == stat.S_IFREG:
        raise SyncError("failed-move regular recovery receipt is incomplete")
    if (expected_mode_type == stat.S_IFLNK and expected_target is None) or (
        expected_mode_type != stat.S_IFLNK and expected_target is not None
    ):
        raise SyncError("failed-move recovery receipt changed")
    source = home / Path(*source_relative.parts)
    destination = home / Path(*destination_relative.parts)
    isolated = home / Path(*isolated_relative.parts)
    if (
        isolated.parent != isolation_parent
        or isolated.name != FAILED_MOVE_ISOLATION_ENTRY_NAME
        or isolation_parent_identity != parent_identity
        or source == destination
        or source == isolated
        or destination == isolated
        or _failed_move_receipt_payload(
            home,
            source,
            source_parent_identity,
            destination,
            destination_parent_identity,
            isolated,
            isolation_parent_identity,
            expected_identity,
            expected_mode_type,
            expected_target,
            expected_regular,
        )
        != snapshot.payload
    ):
        raise SyncError("failed-move recovery receipt changed")
    return snapshot, FailedMoveRecoveryReceipt(
        source=source,
        source_parent_identity=source_parent_identity,
        destination=destination,
        destination_parent_identity=destination_parent_identity,
        isolated=isolated,
        isolation_parent_identity=isolation_parent_identity,
        expected_identity=expected_identity,
        expected_mode_type=expected_mode_type,
        expected_target=expected_target,
        expected_regular=expected_regular,
    )


def _failed_move_recovery_leaf_state(
    home: Path,
    path: Path,
    parent_identity: tuple[int, int],
    receipt: FailedMoveRecoveryReceipt,
) -> str:
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        if _directory_identity(
            parent_fd
        ) != parent_identity or not _bound_directory_matches(
            home, path.parent, parent_fd
        ):
            raise SyncError(f"failed-move recovery parent changed: {path.parent}")
        try:
            metadata = os.stat(
                path.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            return "missing"
        if receipt.expected_regular is not None:
            candidate = _regular_file_snapshot_at(parent_fd, path.name, path)
            matches = (
                _regular_snapshot_leaf_matches(candidate, receipt.expected_regular)
                and candidate.link_count == receipt.expected_regular.link_count
            )
        elif receipt.expected_mode_type == stat.S_IFLNK:
            identity, target = _symlink_snapshot_at(parent_fd, path.name)
            matches = (
                identity == receipt.expected_identity
                and target == receipt.expected_target
            )
        else:
            matches = (
                metadata.st_dev,
                metadata.st_ino,
            ) == receipt.expected_identity and stat.S_IFMT(
                metadata.st_mode
            ) == receipt.expected_mode_type
        return "expected" if matches else "mismatch"
    finally:
        _close_fd_quietly(parent_fd)


def _failed_move_recovery_alias_states(
    home: Path,
    receipt: FailedMoveRecoveryReceipt,
) -> tuple[str, str, str]:
    return (
        _failed_move_recovery_leaf_state(
            home,
            receipt.source,
            receipt.source_parent_identity,
            receipt,
        ),
        _failed_move_recovery_leaf_state(
            home,
            receipt.destination,
            receipt.destination_parent_identity,
            receipt,
        ),
        _failed_move_recovery_leaf_state(
            home,
            receipt.isolated,
            receipt.isolation_parent_identity,
            receipt,
        ),
    )


def _failed_move_recovery_aliases_are_terminal(
    states: tuple[str, str, str],
) -> bool:
    """Require one active expected leaf and no retained or foreign alias."""
    source_state, destination_state, isolated_state = states
    return (
        isolated_state == "missing"
        and "mismatch" not in states
        and (source_state, destination_state).count("expected") == 1
        and (source_state, destination_state).count("missing") == 1
    )


def _rebind_failed_move_recovery_parent_fds(
    home: Path,
    source_parent: Path,
    source_parent_identity: tuple[int, int],
    source_parent_fd: int,
    destination_parent: Path,
    destination_parent_identity: tuple[int, int],
    destination_parent_fd: int,
) -> tuple[int, int]:
    """Reopen mutation FDs from canonical paths after checking old bindings.

    The protected property is directory object identity. Child-entry churn does
    not change that property, so ctime and directory link count are not compared.
    """
    if (
        _directory_identity(source_parent_fd) != source_parent_identity
        or not _bound_directory_matches(home, source_parent, source_parent_fd)
        or _directory_identity(destination_parent_fd) != destination_parent_identity
        or not _bound_directory_matches(
            home,
            destination_parent,
            destination_parent_fd,
        )
    ):
        raise SyncError("failed-move recovery parent changed before restore")

    rebound_source_parent_fd = -1
    rebound_destination_parent_fd = -1
    try:
        rebound_source_parent_fd = _open_directory_beneath(home, source_parent)
        rebound_destination_parent_fd = _open_directory_beneath(
            home,
            destination_parent,
        )
        if (
            _directory_identity(rebound_source_parent_fd) != source_parent_identity
            or _directory_identity(rebound_destination_parent_fd)
            != destination_parent_identity
            or not _bound_directory_matches(
                home,
                source_parent,
                rebound_source_parent_fd,
            )
            or not _bound_directory_matches(
                home,
                destination_parent,
                rebound_destination_parent_fd,
            )
        ):
            raise SyncError("failed-move recovery parent changed before restore")
        result = (rebound_source_parent_fd, rebound_destination_parent_fd)
        rebound_source_parent_fd = -1
        rebound_destination_parent_fd = -1
        return result
    finally:
        _close_fd_quietly(rebound_destination_parent_fd)
        _close_fd_quietly(rebound_source_parent_fd)


def _clear_failed_move_recovery_receipt(
    home: Path,
    snapshot: ManagedStateFileSnapshot,
    *,
    receipt: FailedMoveRecoveryReceipt | None = None,
) -> None:
    isolation_parent = _failed_move_isolation_parent(home)
    parent_fd = _open_directory_beneath(home, isolation_parent)
    try:
        current = _read_managed_state_file_snapshot(
            home,
            isolation_parent / FAILED_MOVE_RECEIPT_NAME,
            parent_fd,
            maximum_bytes=4096,
        )
        if not _managed_state_snapshot_exact(current, snapshot):
            raise SyncError("failed-move recovery receipt changed before cleanup")
        if receipt is not None:
            states = _failed_move_recovery_alias_states(home, receipt)
            if not _failed_move_recovery_aliases_are_terminal(states):
                raise SyncError(
                    "failed-move recovery aliases changed before cleanup; "
                    "exact evidence was retained"
                )
            if not _bound_directory_matches(home, isolation_parent, parent_fd):
                raise SyncError("failed-move recovery directory changed before cleanup")
        os.unlink(FAILED_MOVE_RECEIPT_NAME, dir_fd=parent_fd)
        os.fsync(parent_fd)
        if _named_entry_identity(parent_fd, FAILED_MOVE_RECEIPT_NAME) is not None:
            raise SyncError("failed-move recovery receipt reappeared")
        if not _bound_directory_matches(home, isolation_parent, parent_fd):
            raise SyncError("failed-move recovery directory changed during cleanup")
    finally:
        _close_fd_quietly(parent_fd)


def _recover_failed_move_isolation(home: Path, *, dry_run: bool = False) -> bool:
    loaded = _read_failed_move_recovery_receipt(home)
    if loaded is None:
        return False
    snapshot, receipt = loaded
    states = _failed_move_recovery_alias_states(home, receipt)
    _, _, isolated_state = states
    if "mismatch" in states or states.count("expected") != 1:
        raise SyncError(
            "failed-move recovery aliases are ambiguous; exact evidence was retained"
        )
    if dry_run:
        return True
    if isolated_state == "expected":
        destination_parent_fd = _open_directory_beneath(
            home, receipt.destination.parent
        )
        isolation_parent_fd = _open_directory_beneath(home, receipt.isolated.parent)
        try:
            rebound_isolation_parent_fd, rebound_destination_parent_fd = (
                _rebind_failed_move_recovery_parent_fds(
                    home,
                    receipt.isolated.parent,
                    receipt.isolation_parent_identity,
                    isolation_parent_fd,
                    receipt.destination.parent,
                    receipt.destination_parent_identity,
                    destination_parent_fd,
                )
            )
            _close_fd_quietly(isolation_parent_fd)
            isolation_parent_fd = rebound_isolation_parent_fd
            _close_fd_quietly(destination_parent_fd)
            destination_parent_fd = rebound_destination_parent_fd
            _rename_noreplace_at(
                isolation_parent_fd,
                receipt.isolated.name,
                destination_parent_fd,
                receipt.destination.name,
            )
            os.fsync(destination_parent_fd)
            os.fsync(isolation_parent_fd)
        finally:
            _close_fd_quietly(isolation_parent_fd)
            _close_fd_quietly(destination_parent_fd)
    _clear_failed_move_recovery_receipt(home, snapshot, receipt=receipt)
    return True


def _isolate_failed_move_destination(
    home: Path,
    source: Path,
    destination: Path,
    expected_source_parent_identity: tuple[int, int],
    expected_parent_identity: tuple[int, int],
    expected_identity: tuple[int, int],
    expected_mode_type: int,
    expected_target: str | None,
    expected_regular: RegularFileSnapshot | None,
) -> FailedMoveIsolation:
    if _recover_failed_move_isolation(home):
        raise SyncError("recovered an earlier failed-move isolation; retry the move")
    isolation_parent = _failed_move_isolation_parent(home)
    isolation_parent_fd = _open_or_create_directory_beneath(
        home,
        isolation_parent,
        mode=0o700,
    )
    destination_parent_fd = -1
    try:
        isolation_metadata = os.fstat(isolation_parent_fd)
        isolation_parent_identity = _directory_identity(isolation_parent_fd)
        if (
            stat.S_IMODE(isolation_metadata.st_mode) != 0o700
            or isolation_metadata.st_uid != os.geteuid()
            or not _bound_directory_matches(home, isolation_parent, isolation_parent_fd)
        ):
            raise SyncError("failed-move isolation parent access policy mismatch")
        if (
            _named_entry_identity(isolation_parent_fd, FAILED_MOVE_ISOLATION_ENTRY_NAME)
            is not None
        ):
            raise SyncError("failed-move isolation entry is already occupied")
        destination_parent_fd = _open_directory_beneath(home, destination.parent)
        if _directory_identity(
            destination_parent_fd
        ) != expected_parent_identity or not _bound_directory_matches(
            home, destination.parent, destination_parent_fd
        ):
            raise SyncError(
                "canonical destination parent changed before failed-move isolation; "
                f"evidence was left in place: {destination}"
            )
        isolated = isolation_parent / FAILED_MOVE_ISOLATION_ENTRY_NAME
        expected_receipt_payload = _failed_move_receipt_payload(
            home,
            source,
            expected_source_parent_identity,
            destination,
            expected_parent_identity,
            isolated,
            isolation_parent_identity,
            expected_identity,
            expected_mode_type,
            expected_target,
            expected_regular,
        )
        receipt_path = isolation_parent / FAILED_MOVE_RECEIPT_NAME
        _publish_atomic_exclusive_internal_file(
            home,
            receipt_path,
            expected_receipt_payload,
        )
        loaded = _read_failed_move_recovery_receipt(home)
        if loaded is None or loaded[0].payload != expected_receipt_payload:
            raise SyncError("failed-move recovery receipt was not durable")
        receipt_snapshot = loaded[0]
        _rename_noreplace_at(
            destination_parent_fd,
            destination.name,
            isolation_parent_fd,
            isolated.name,
        )
        os.fsync(destination_parent_fd)
        os.fsync(isolation_parent_fd)
        if (
            _failed_move_recovery_leaf_state(
                home,
                isolated,
                isolation_parent_identity,
                loaded[1],
            )
            != "expected"
        ):
            raise SyncError(
                "destination racer was retained outside the active source after "
                f"failed-move isolation: {isolated}"
            )
        return FailedMoveIsolation(
            isolation_parent=isolation_parent,
            isolation_parent_identity=isolation_parent_identity,
            isolated=isolated,
            receipt=receipt_snapshot,
        )
    finally:
        _close_fd_quietly(destination_parent_fd)
        _close_fd_quietly(isolation_parent_fd)


def _retain_failed_restore_leaf(
    home: Path,
    destination: Path,
    expected_parent_identity: tuple[int, int],
    expected_identity: tuple[int, int],
    expected_mode_type: int,
    expected_target: str | None,
    expected_regular: RegularFileSnapshot | None,
) -> Path:
    batch_root = _quarantine_batch_root(home, [])
    isolation_parent = batch_root / "failed-move"
    isolation_parent_fd = _open_or_create_directory_beneath(
        home,
        isolation_parent,
        mode=0o700,
    )
    isolation_parent_metadata = os.fstat(isolation_parent_fd)
    if (
        stat.S_IMODE(isolation_parent_metadata.st_mode) != 0o700
        or isolation_parent_metadata.st_uid != os.geteuid()
    ):
        _close_fd_quietly(isolation_parent_fd)
        raise SyncError(
            f"failed-move isolation parent access policy mismatch: {isolation_parent}"
        )
    destination_parent_fd = -1
    isolated: Path | None = None
    try:
        for attempt in range(100):
            _close_fd_quietly(destination_parent_fd)
            destination_parent_fd = _open_directory_beneath(
                home,
                destination.parent,
            )
            if _directory_identity(
                destination_parent_fd
            ) != expected_parent_identity or not _bound_directory_matches(
                home,
                destination.parent,
                destination_parent_fd,
            ):
                raise SyncError(
                    "canonical destination parent changed before failed-move "
                    f"isolation; evidence was left in place: {destination}"
                )
            if not _bound_directory_matches(
                home,
                isolation_parent,
                isolation_parent_fd,
            ):
                raise SyncError(
                    "failed-move isolation parent changed before evidence "
                    f"retention: {isolation_parent}"
                )
            if expected_regular is not None:
                candidate = _regular_file_snapshot_at(
                    destination_parent_fd,
                    destination.name,
                    destination,
                )
                if not _regular_snapshot_matches(
                    candidate,
                    expected_parent_identity,
                    expected_regular,
                    expected_link_count=expected_regular.link_count,
                ):
                    raise SyncError(
                        "moved regular file changed before failed-move isolation "
                        f"and was left in place: {destination}"
                    )
            elif stat.S_ISLNK(expected_mode_type):
                candidate_identity, candidate_target = _symlink_snapshot_at(
                    destination_parent_fd,
                    destination.name,
                )
                if (
                    candidate_identity != expected_identity
                    or candidate_target != expected_target
                ):
                    raise SyncError(
                        "moved symlink changed before failed-move isolation and "
                        f"was left in place: {destination}"
                    )
            else:
                candidate_metadata = os.stat(
                    destination.name,
                    dir_fd=destination_parent_fd,
                    follow_symlinks=False,
                )
                if (
                    candidate_metadata.st_dev,
                    candidate_metadata.st_ino,
                ) != expected_identity or stat.S_IFMT(
                    candidate_metadata.st_mode
                ) != expected_mode_type:
                    raise SyncError(
                        "moved entry changed before failed-move isolation and "
                        f"was left in place: {destination}"
                    )
            candidate_name = f"restore-{os.getpid()}-{time.time_ns()}-{attempt}"
            try:
                _rename_noreplace_at(
                    destination_parent_fd,
                    destination.name,
                    isolation_parent_fd,
                    candidate_name,
                )
            except FileExistsError:
                continue
            isolated = isolation_parent / candidate_name
            os.fsync(destination_parent_fd)
            os.fsync(isolation_parent_fd)
            break
        if isolated is None:
            raise SyncError(
                f"could not allocate private failed-move isolation for {destination}"
            )
        if expected_regular is not None:
            isolated_regular = _regular_file_snapshot_at(
                isolation_parent_fd,
                isolated.name,
                isolated,
            )
            if (
                not _regular_snapshot_leaf_matches(
                    isolated_regular,
                    expected_regular,
                )
                or isolated_regular.link_count != expected_regular.link_count
            ):
                raise SyncError(
                    "destination racer was retained outside the active source "
                    f"after failed-move isolation: {isolated}"
                )
        elif stat.S_ISLNK(expected_mode_type):
            isolated_identity, isolated_target = _symlink_snapshot_at(
                isolation_parent_fd,
                isolated.name,
            )
            if (
                isolated_identity != expected_identity
                or isolated_target != expected_target
            ):
                raise SyncError(
                    "destination racer was retained outside the active source "
                    f"after failed-move isolation: {isolated}"
                )
        else:
            isolated_metadata = os.stat(
                isolated.name,
                dir_fd=isolation_parent_fd,
                follow_symlinks=False,
            )
            if (
                isolated_metadata.st_dev,
                isolated_metadata.st_ino,
            ) != expected_identity or stat.S_IFMT(
                isolated_metadata.st_mode
            ) != expected_mode_type:
                raise SyncError(
                    "destination racer was retained outside the active source "
                    f"after failed-move isolation: {isolated}"
                )
        if not _bound_directory_matches(
            home,
            isolation_parent,
            isolation_parent_fd,
        ):
            raise SyncError(
                "failed-move isolation parent changed after evidence retention: "
                f"{isolated}"
            )
        return isolated
    finally:
        _close_fd_quietly(destination_parent_fd)
        _close_fd_quietly(isolation_parent_fd)


def _isolate_current_failed_restore_leaf(
    home: Path,
    source: Path,
    expected_parent_identity: tuple[int, int],
    source_parent_fd: int,
) -> Path:
    metadata = os.stat(
        source.name,
        dir_fd=source_parent_fd,
        follow_symlinks=False,
    )
    identity = (metadata.st_dev, metadata.st_ino)
    mode_type = stat.S_IFMT(metadata.st_mode)
    link_target = None
    regular = None
    if stat.S_ISREG(metadata.st_mode):
        try:
            regular = _regular_file_snapshot_at(
                source_parent_fd,
                source.name,
                source,
            )
        except (OSError, SyncError):
            pass
    elif stat.S_ISLNK(metadata.st_mode):
        identity, link_target = _symlink_snapshot_at(
            source_parent_fd,
            source.name,
        )
    return _retain_failed_restore_leaf(
        home,
        source,
        expected_parent_identity,
        identity,
        mode_type,
        link_target,
        regular,
    )


def _return_failed_restore_mismatch_to_destination(
    home: Path,
    source: Path,
    destination: Path,
    source_parent_fd: int,
    expected_source_parent_identity: tuple[int, int],
    expected_destination_parent_identity: tuple[int, int],
) -> Path:
    destination_parent_fd = _open_directory_beneath(home, destination.parent)
    try:
        if (
            _directory_identity(source_parent_fd) != expected_source_parent_identity
            or not _bound_directory_matches(home, source.parent, source_parent_fd)
            or _directory_identity(destination_parent_fd)
            != expected_destination_parent_identity
            or not _bound_directory_matches(
                home, destination.parent, destination_parent_fd
            )
        ):
            raise SyncError(
                "failed-move mismatch parent changed; active evidence was retained"
            )
        _rename_noreplace_at(
            source_parent_fd,
            source.name,
            destination_parent_fd,
            destination.name,
        )
        os.fsync(source_parent_fd)
        if destination_parent_fd != source_parent_fd:
            os.fsync(destination_parent_fd)
        if _named_entry_identity(source_parent_fd, source.name) is not None:
            raise SyncError(
                "failed-move mismatch remained exposed at the active source"
            )
        return destination
    finally:
        _close_fd_quietly(destination_parent_fd)


def _atomic_move_beneath_home(
    home: Path,
    source: Path,
    destination: Path,
    expected_snapshot: ReconcileTargetSnapshot | None = None,
    expected_destination_parent_identity: tuple[int, int] | None = None,
    expected_entry_identity: tuple[int, int] | None = None,
) -> None:
    source_parent_fd = _open_directory_beneath(home, source.parent)
    try:
        destination_parent_fd = _open_directory_beneath(
            home,
            destination.parent,
        )
    except BaseException:
        _close_fd_quietly(source_parent_fd)
        raise
    moved = False
    moved_identity_for_restore: tuple[int, int] | None = None
    moved_mode_type_for_restore: int | None = None
    moved_target_for_restore: str | None = None
    source_regular_for_restore: RegularFileSnapshot | None = None
    source_parent_identity_for_restore: tuple[int, int] | None = None
    destination_parent_identity_for_restore: tuple[int, int] | None = None
    rollback_source_parent_fd = -1
    rollback_destination_parent_fd = -1
    isolated_parent_fd = -1
    try:
        source_parent_identity_for_restore = _directory_identity(source_parent_fd)
        destination_parent_identity_for_restore = _directory_identity(
            destination_parent_fd
        )
        if expected_destination_parent_identity is not None:
            if (
                destination_parent_identity_for_restore
                != expected_destination_parent_identity
            ):
                raise SyncError(
                    f"destination parent changed after planning: {destination.parent}"
                )
        source_metadata = os.stat(
            source.name,
            dir_fd=source_parent_fd,
            follow_symlinks=False,
        )
        source_identity = (source_metadata.st_dev, source_metadata.st_ino)
        moved_mode_type_for_restore = stat.S_IFMT(source_metadata.st_mode)
        if (
            expected_entry_identity is not None
            and source_identity != expected_entry_identity
        ):
            raise SyncError(f"source object changed after planning: {source}")
        if stat.S_ISREG(source_metadata.st_mode):
            source_regular_for_restore = _regular_file_snapshot_at(
                source_parent_fd,
                source.name,
                source,
            )
            if source_regular_for_restore.file_identity != source_identity:
                raise SyncError(f"source object changed after planning: {source}")
        if expected_snapshot is not None:
            if (
                expected_snapshot.parent_identity is None
                or expected_snapshot.link_identity is None
            ):
                raise SyncError(
                    f"destructive move has no planned target snapshot: {source}"
                )
            if source_parent_identity_for_restore != expected_snapshot.parent_identity:
                raise SyncError(
                    f"source parent changed after planning: {source.parent}"
                )
            planned_regular = _regular_snapshot_from_reconcile(expected_snapshot)
            if planned_regular is not None:
                if source_regular_for_restore is None:
                    raise SyncError(f"source changed after planning: {source}")
                if not _regular_snapshot_matches(
                    source_regular_for_restore,
                    planned_regular.parent_identity,
                    planned_regular,
                    expected_link_count=planned_regular.link_count,
                ):
                    raise SyncError(f"source changed after planning: {source}")
            else:
                if expected_snapshot.link_target is None or not stat.S_ISLNK(
                    source_metadata.st_mode
                ):
                    raise SyncError(f"source changed after planning: {source}")
                actual_target = os.readlink(source.name, dir_fd=source_parent_fd)
                source_metadata_after = os.stat(
                    source.name,
                    dir_fd=source_parent_fd,
                    follow_symlinks=False,
                )
                if (
                    (source_metadata_after.st_dev, source_metadata_after.st_ino)
                    != source_identity
                    or source_identity != expected_snapshot.link_identity
                    or actual_target != expected_snapshot.link_target
                ):
                    raise SyncError(f"source changed after planning: {source}")
        if not _bound_directory_matches(home, source.parent, source_parent_fd):
            raise SyncError(f"source parent changed before move: {source.parent}")
        if not _bound_directory_matches(
            home,
            destination.parent,
            destination_parent_fd,
        ):
            raise SyncError(
                f"destination parent changed before move: {destination.parent}"
            )
        if source_regular_for_restore is not None:
            _require_managed_regular_parent_chain_access(
                home,
                source.parent,
                bound_parent_fd=source_parent_fd,
            )
        _rename_noreplace_at(
            source_parent_fd,
            source.name,
            destination_parent_fd,
            destination.name,
        )
        moved = True
        os.fsync(source_parent_fd)
        if destination_parent_fd != source_parent_fd:
            os.fsync(destination_parent_fd)
        destination_metadata = os.stat(
            destination.name,
            dir_fd=destination_parent_fd,
            follow_symlinks=False,
        )
        moved_identity_for_restore = (
            destination_metadata.st_dev,
            destination_metadata.st_ino,
        )
        if stat.S_ISLNK(destination_metadata.st_mode):
            moved_identity_for_restore, moved_target_for_restore = _symlink_snapshot_at(
                destination_parent_fd,
                destination.name,
            )
        elif source_regular_for_restore is not None:
            moved_regular = _regular_file_snapshot_at(
                destination_parent_fd,
                destination.name,
                destination,
            )
            moved_identity_for_restore = moved_regular.file_identity
            if not _regular_snapshot_matches(
                moved_regular,
                destination_parent_identity_for_restore,
                source_regular_for_restore,
                expected_link_count=source_regular_for_restore.link_count,
            ):
                raise SyncError(
                    f"moved regular file changed during reconciliation: {source}"
                )
        if moved_identity_for_restore != source_identity:
            raise SyncError(f"moved entry changed during reconciliation: {source}")
        if expected_snapshot is not None:
            if (
                moved_identity_for_restore != expected_snapshot.link_identity
                or moved_target_for_restore != expected_snapshot.link_target
            ):
                raise SyncError(f"source changed while moving to quarantine: {source}")
        try:
            os.stat(
                source.name,
                dir_fd=source_parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        else:
            raise SyncError(f"source still exists after move: {source}")
        if not _bound_directory_matches(home, source.parent, source_parent_fd):
            raise SyncError(f"source parent changed during move: {source.parent}")
        if not _bound_directory_matches(
            home,
            destination.parent,
            destination_parent_fd,
        ):
            raise SyncError(
                f"destination parent changed during move: {destination.parent}"
            )
    except BaseException as error:
        if moved:
            restored = False
            isolated: Path | None = None
            try:
                assert destination_parent_identity_for_restore is not None
                assert moved_identity_for_restore is not None
                assert moved_mode_type_for_restore is not None
                rollback_source_parent_fd = _open_directory_beneath(
                    home,
                    source.parent,
                )
                if _directory_identity(
                    rollback_source_parent_fd
                ) != source_parent_identity_for_restore or not _bound_directory_matches(
                    home,
                    source.parent,
                    rollback_source_parent_fd,
                ):
                    raise SyncError(
                        "canonical source parent changed before failed-move "
                        f"restoration; evidence was retained at {destination}"
                    )
                try:
                    rollback_source_metadata = os.stat(
                        source.name,
                        dir_fd=rollback_source_parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    pass
                else:
                    rollback_source_identity = (
                        rollback_source_metadata.st_dev,
                        rollback_source_metadata.st_ino,
                    )
                    raise SyncError(
                        "canonical source leaf appeared before failed-move "
                        "restoration and was left in place: "
                        f"{source} ({rollback_source_identity}); evidence was "
                        f"retained at {destination}"
                    )
                isolation = _isolate_failed_move_destination(
                    home,
                    source,
                    destination,
                    source_parent_identity_for_restore,
                    destination_parent_identity_for_restore,
                    moved_identity_for_restore,
                    moved_mode_type_for_restore,
                    moved_target_for_restore,
                    source_regular_for_restore,
                )
                isolated = isolation.isolated
                if (
                    not _bound_directory_matches(
                        home,
                        source.parent,
                        rollback_source_parent_fd,
                    )
                    or _directory_identity(rollback_source_parent_fd)
                    != source_parent_identity_for_restore
                ):
                    raise SyncError(
                        "canonical source parent changed after failed-move "
                        f"isolation; evidence was retained at {isolated}"
                    )
                try:
                    os.stat(
                        source.name,
                        dir_fd=rollback_source_parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    pass
                else:
                    raise SyncError(
                        "canonical source leaf appeared after failed-move "
                        f"isolation and was left in place: {source}; evidence "
                        f"was retained at {isolated}"
                    )
                isolated_parent_fd = _open_directory_beneath(
                    home,
                    isolated.parent,
                )
                if not _bound_directory_matches(
                    home,
                    isolated.parent,
                    isolated_parent_fd,
                ):
                    raise SyncError(
                        "failed-move isolation parent changed before exact "
                        f"restoration; evidence was retained at {isolated}"
                    )
                if source_regular_for_restore is not None:
                    isolated_regular = _regular_file_snapshot_at(
                        isolated_parent_fd,
                        isolated.name,
                        isolated,
                    )
                    if (
                        not _regular_snapshot_leaf_matches(
                            isolated_regular,
                            source_regular_for_restore,
                        )
                        or isolated_regular.link_count
                        != source_regular_for_restore.link_count
                    ):
                        raise SyncError(
                            "failed-move isolated regular evidence changed before "
                            f"restoration and was retained at {isolated}"
                        )
                elif stat.S_ISLNK(moved_mode_type_for_restore):
                    isolated_identity, isolated_target = _symlink_snapshot_at(
                        isolated_parent_fd,
                        isolated.name,
                    )
                    if (
                        isolated_identity != moved_identity_for_restore
                        or isolated_target != moved_target_for_restore
                    ):
                        raise SyncError(
                            "failed-move isolated symlink evidence changed before "
                            f"restoration and was retained at {isolated}"
                        )
                else:
                    isolated_metadata = os.stat(
                        isolated.name,
                        dir_fd=isolated_parent_fd,
                        follow_symlinks=False,
                    )
                    if (
                        isolated_metadata.st_dev,
                        isolated_metadata.st_ino,
                    ) != moved_identity_for_restore or stat.S_IFMT(
                        isolated_metadata.st_mode
                    ) != moved_mode_type_for_restore:
                        raise SyncError(
                            "failed-move isolated evidence changed before exact "
                            f"restoration and was retained at {isolated}"
                        )
                if source_regular_for_restore is not None:
                    _require_managed_regular_parent_chain_access(
                        home,
                        source.parent,
                        bound_parent_fd=rollback_source_parent_fd,
                    )
                _rename_noreplace_at(
                    isolated_parent_fd,
                    isolated.name,
                    rollback_source_parent_fd,
                    source.name,
                )
                restored = True
                os.fsync(rollback_source_parent_fd)
                if isolated_parent_fd != rollback_source_parent_fd:
                    os.fsync(isolated_parent_fd)
                restored_metadata = os.stat(
                    source.name,
                    dir_fd=rollback_source_parent_fd,
                    follow_symlinks=False,
                )
                if (
                    restored_metadata.st_dev,
                    restored_metadata.st_ino,
                ) != moved_identity_for_restore:
                    retained_racer = _return_failed_restore_mismatch_to_destination(
                        home,
                        source,
                        destination,
                        rollback_source_parent_fd,
                        source_parent_identity_for_restore,
                        destination_parent_identity_for_restore,
                    )
                    restored = False
                    raise SyncError(
                        "restored entry changed after failed move and the racer "
                        f"was retained outside the active path: {retained_racer}"
                    )
                if moved_target_for_restore is not None:
                    restored_identity, restored_target = _symlink_snapshot_at(
                        rollback_source_parent_fd,
                        source.name,
                    )
                    if (
                        restored_identity != moved_identity_for_restore
                        or restored_target != moved_target_for_restore
                    ):
                        raise SyncError(
                            f"restored symlink changed after failed move: {source}"
                        )
                if source_regular_for_restore is not None:
                    restored_regular = None
                    restored_regular_error = None
                    try:
                        restored_regular = _regular_file_snapshot_at(
                            rollback_source_parent_fd,
                            source.name,
                            source,
                        )
                    except BaseException as snapshot_error:
                        restored_regular_error = snapshot_error
                    if restored_regular is None or not _regular_snapshot_matches(
                        restored_regular,
                        source_regular_for_restore.parent_identity,
                        source_regular_for_restore,
                        expected_link_count=source_regular_for_restore.link_count,
                    ):
                        retained_path = _return_failed_restore_mismatch_to_destination(
                            home,
                            source,
                            destination,
                            rollback_source_parent_fd,
                            source_parent_identity_for_restore,
                            destination_parent_identity_for_restore,
                        )
                        restored = False
                        semantic_error = SyncError(
                            "restored regular source changed and was retained "
                            f"outside the active path: {retained_path}"
                        )
                        if restored_regular_error is not None:
                            raise semantic_error from restored_regular_error
                        raise semantic_error
                _clear_failed_move_recovery_receipt(home, isolation.receipt)
                rollback_destination_parent_fd = _open_directory_beneath(
                    home,
                    destination.parent,
                )
                if (
                    _directory_identity(rollback_destination_parent_fd)
                    != destination_parent_identity_for_restore
                    or not _bound_directory_matches(
                        home,
                        destination.parent,
                        rollback_destination_parent_fd,
                    )
                ):
                    raise SyncError(
                        "canonical destination parent changed after exact source "
                        f"restoration: {destination.parent}"
                    )
                try:
                    os.stat(
                        destination.name,
                        dir_fd=rollback_destination_parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    pass
                else:
                    raise SyncError(
                        f"failed move destination still exists: {destination}"
                    )
                if not _bound_directory_matches(
                    home,
                    source.parent,
                    rollback_source_parent_fd,
                ):
                    raise SyncError(f"restored source parent changed: {source.parent}")
            except BaseException as rollback_error:
                if restored:
                    raise SyncError(
                        "safe move failed after exact source restoration could not "
                        f"be validated: {source}: {rollback_error}"
                    ) from error
                retained_location = isolated or destination
                raise SyncError(
                    "safe move failed and the entry was retained outside the "
                    f"active source: {retained_location}: {rollback_error}"
                ) from error
        raise
    finally:
        if rollback_destination_parent_fd >= 0:
            _close_fd_quietly(rollback_destination_parent_fd)
        if isolated_parent_fd >= 0:
            _close_fd_quietly(isolated_parent_fd)
        if rollback_source_parent_fd >= 0:
            _close_fd_quietly(rollback_source_parent_fd)
        _close_fd_quietly(source_parent_fd)
        _close_fd_quietly(destination_parent_fd)


def _symlink_snapshot_at(
    parent_fd: int,
    name: str,
) -> tuple[tuple[int, int], str]:
    metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    if not stat.S_ISLNK(metadata.st_mode):
        raise SyncError(f"managed target is not a symlink: {name}")
    link_target = os.readlink(name, dir_fd=parent_fd)
    metadata_after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    identity = (metadata.st_dev, metadata.st_ino)
    if (metadata_after.st_dev, metadata_after.st_ino) != identity:
        raise SyncError(f"managed symlink changed during validation: {name}")
    return identity, link_target


def _regular_file_snapshot_at(
    parent_fd: int,
    name: str,
    path: Path,
    *,
    maximum_bytes: int = MAX_ARCHIVE_MEMBER_BYTES,
) -> RegularFileSnapshot:
    try:
        named = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except OSError as error:
        raise SyncError(
            f"managed regular file is unreadable: {path}: {error}"
        ) from error
    if not stat.S_ISREG(named.st_mode):
        raise SyncError(f"managed target is not a regular file: {path}")
    if named.st_size > maximum_bytes:
        raise SyncError(f"managed regular file exceeds {maximum_bytes} bytes: {path}")
    expected_identity = (named.st_dev, named.st_ino)
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    file_fd = -1
    try:
        try:
            file_fd = os.open(name, flags, dir_fd=parent_fd)
        except OSError as error:
            raise SyncError(
                f"managed regular file is unreadable: {path}: {error}"
            ) from error
        opened = _require_release_identity_fd_access_policy(
            file_fd,
            path,
            os.geteuid(),
        )
        if not _regular_stat_metadata_matches(opened, named):
            raise SyncError(f"managed regular file changed before read: {path}")
        payload = _read_managed_state_bytes(file_fd, path, maximum_bytes)
        os.lseek(file_fd, 0, os.SEEK_SET)
        if _read_managed_state_bytes(file_fd, path, maximum_bytes) != payload:
            raise SyncError(f"managed regular file content changed during read: {path}")
        confirmed = os.fstat(file_fd)
        if not _regular_stat_metadata_matches(confirmed, named):
            raise SyncError(f"managed regular file changed during read: {path}")
        rebound = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if not _regular_stat_metadata_matches(rebound, named):
            raise SyncError(f"managed regular file changed during read: {path}")
        access_revalidated = _require_release_identity_fd_access_policy(
            file_fd,
            path,
            os.geteuid(),
        )
        if not _regular_stat_metadata_matches(access_revalidated, named):
            raise SyncError(
                f"managed regular file changed during access-policy revalidation: {path}"
            )
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)
    return RegularFileSnapshot(
        parent_identity=_directory_identity(parent_fd),
        file_identity=expected_identity,
        sha256=hashlib.sha256(payload).hexdigest(),
        size=len(payload),
        mode=stat.S_IMODE(named.st_mode),
        uid=named.st_uid,
        gid=named.st_gid,
        link_count=named.st_nlink,
    )


def _read_regular_file_snapshot_beneath(
    home: Path,
    path: Path,
    *,
    require_managed_access: bool,
) -> RegularFileSnapshot:
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        _require_managed_regular_parent_chain_access(
            home,
            path.parent,
            bound_parent_fd=parent_fd,
        )
        snapshot = _regular_file_snapshot_at(parent_fd, path.name, path)
        if require_managed_access and (
            snapshot.mode != 0o600
            or snapshot.uid != os.geteuid()
            or snapshot.link_count != 1
        ):
            raise SyncError(
                "managed regular file access policy mismatch: "
                f"{path} (mode={snapshot.mode:o}, uid={snapshot.uid}, "
                f"links={snapshot.link_count})"
            )
        _require_managed_regular_parent_chain_access(
            home,
            path.parent,
            bound_parent_fd=parent_fd,
        )
        return snapshot
    finally:
        _close_fd_quietly(parent_fd)


def _remove_expected_regular_file_beneath(
    home: Path,
    target: Path,
    expected: RegularFileSnapshot,
) -> None:
    parent_fd = _open_directory_beneath(home, target.parent)
    try:
        quarantine_path, moved = _move_regular_leaf_to_unique_quarantine(
            home,
            target.parent,
            parent_fd,
            target.name,
            label="remove",
            expected=expected,
        )
        if (
            not _regular_snapshot_leaf_matches(
                moved,
                expected,
            )
            or moved.link_count != expected.link_count
        ):
            raise SyncError(
                "managed regular file changed during removal and was retained "
                f"in quarantine: {target} -> {quarantine_path}"
            )
        try:
            os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise SyncError(
                "managed regular file replacement appeared during removal and "
                f"was left in place: {target}; original retained in quarantine: "
                f"{quarantine_path}"
            )
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
    finally:
        _close_fd_quietly(parent_fd)


def _validate_reconcile_link_target(link_target: str, label: str) -> str:
    try:
        encoded = os.fsencode(link_target)
    except (TypeError, UnicodeEncodeError) as error:
        raise SyncError(f"{label} is not filesystem-encodable") from error
    if not encoded or len(encoded) > MAX_RECONCILE_LINK_TARGET_BYTES:
        raise SyncError(
            f"{label} exceeds {MAX_RECONCILE_LINK_TARGET_BYTES} filesystem bytes"
        )
    return link_target


def _capture_reconcile_target_snapshot(
    home: Path,
    target: Path,
    *,
    capture_regular_content: bool = True,
    require_managed_parent_access: bool = False,
) -> ReconcileTargetSnapshot:
    parent_parts = _directory_parts_beneath(home, target.parent)
    child_flags = _directory_open_flags(nofollow=True)
    parent_fd = _open_directory_beneath(home, home)
    current_path = home
    try:
        if require_managed_parent_access:
            _require_managed_regular_directory_fd_access(
                home,
                current_path,
                parent_fd,
            )
        for index, part in enumerate(parent_parts):
            try:
                next_fd = os.open(part, child_flags, dir_fd=parent_fd)
            except FileNotFoundError:
                ancestor_identity = _directory_identity(parent_fd)
                if require_managed_parent_access:
                    _require_managed_regular_directory_fd_access(
                        home,
                        current_path,
                        parent_fd,
                    )
                elif not _bound_directory_matches(home, current_path, parent_fd):
                    raise SyncError(f"managed target ancestor changed: {current_path}")
                return ReconcileTargetSnapshot(
                    parent_identity=None,
                    ancestor_identity=ancestor_identity,
                    missing_parent_parts=parent_parts[index:],
                )
            _close_fd_quietly(parent_fd)
            parent_fd = next_fd
            current_path /= part
            if require_managed_parent_access:
                _require_managed_regular_directory_fd_access(
                    home,
                    current_path,
                    parent_fd,
                )
        parent_identity = _directory_identity(parent_fd)
        if require_managed_parent_access:
            _require_managed_regular_directory_fd_access(
                home,
                target.parent,
                parent_fd,
            )
        elif not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        try:
            metadata = os.stat(
                target.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            if require_managed_parent_access:
                _require_managed_regular_directory_fd_access(
                    home,
                    target.parent,
                    parent_fd,
                )
            elif not _bound_directory_matches(home, target.parent, parent_fd):
                raise SyncError(f"managed target parent changed: {target.parent}")
            return ReconcileTargetSnapshot(
                parent_identity=parent_identity,
                ancestor_identity=parent_identity,
            )
        if stat.S_ISREG(metadata.st_mode):
            if not capture_regular_content:
                if require_managed_parent_access:
                    _require_managed_regular_directory_fd_access(
                        home,
                        target.parent,
                        parent_fd,
                    )
                elif not _bound_directory_matches(home, target.parent, parent_fd):
                    raise SyncError(f"managed target parent changed: {target.parent}")
                return ReconcileTargetSnapshot(
                    parent_identity=parent_identity,
                    link_identity=(metadata.st_dev, metadata.st_ino),
                    ancestor_identity=parent_identity,
                )
            regular = _regular_file_snapshot_at(
                parent_fd,
                target.name,
                target,
            )
            if require_managed_parent_access:
                _require_managed_regular_directory_fd_access(
                    home,
                    target.parent,
                    parent_fd,
                )
            elif not _bound_directory_matches(home, target.parent, parent_fd):
                raise SyncError(f"managed target parent changed: {target.parent}")
            return ReconcileTargetSnapshot(
                parent_identity=parent_identity,
                link_identity=regular.file_identity,
                ancestor_identity=parent_identity,
                regular_sha256=regular.sha256,
                regular_size=regular.size,
                regular_mode=regular.mode,
                regular_uid=regular.uid,
                regular_gid=regular.gid,
                regular_link_count=regular.link_count,
            )
        if not stat.S_ISLNK(metadata.st_mode):
            if require_managed_parent_access:
                _require_managed_regular_directory_fd_access(
                    home,
                    target.parent,
                    parent_fd,
                )
            return ReconcileTargetSnapshot(
                parent_identity=parent_identity,
                link_identity=(metadata.st_dev, metadata.st_ino),
                ancestor_identity=parent_identity,
            )
        link_identity, link_target = _symlink_snapshot_at(parent_fd, target.name)
        _validate_reconcile_link_target(
            link_target,
            f"managed target symlink value for {target}",
        )
        if require_managed_parent_access:
            _require_managed_regular_directory_fd_access(
                home,
                target.parent,
                parent_fd,
            )
        elif not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        return ReconcileTargetSnapshot(
            parent_identity=parent_identity,
            link_identity=link_identity,
            link_target=link_target,
            ancestor_identity=parent_identity,
        )
    finally:
        _close_fd_quietly(parent_fd)


def _require_reconcile_target_snapshot(
    home: Path,
    target: Path,
    expected_snapshot: ReconcileTargetSnapshot,
    *,
    require_managed_parent_access: bool = False,
) -> None:
    try:
        actual_snapshot = _capture_reconcile_target_snapshot(
            home,
            target,
            require_managed_parent_access=require_managed_parent_access,
        )
    except (OSError, SyncError) as error:
        raise SyncError(f"managed target changed after planning: {target}") from error
    if not _reconcile_target_snapshot_matches(actual_snapshot, expected_snapshot):
        raise SyncError(f"managed target changed after planning: {target}")


def _move_symlink_leaf_to_unique_quarantine(
    home: Path,
    source_parent_fd: int,
    source_name: str,
    *,
    label: str,
    expected_identity: tuple[int, int] | None = None,
    expected_link_target: str | None = None,
) -> tuple[Path, tuple[int, int], str]:
    source_identity, source_target = _symlink_snapshot_at(
        source_parent_fd,
        source_name,
    )
    if (expected_identity is not None and source_identity != expected_identity) or (
        expected_link_target is not None and source_target != expected_link_target
    ):
        raise SyncError(f"symlink changed before quarantine: {source_name}")
    batch_root = _quarantine_batch_root(home, [])
    quarantine_parent = batch_root / "leaf"
    quarantine_parent_fd = _open_or_create_directory_beneath(
        home,
        quarantine_parent,
        mode=0o700,
    )
    destination: Path | None = None
    try:
        if not _bound_directory_matches(
            home,
            quarantine_parent,
            quarantine_parent_fd,
        ):
            raise SyncError(f"quarantine leaf directory changed: {quarantine_parent}")
        for attempt in range(100):
            destination_name = f"{label}-{os.getpid()}-{time.time_ns()}-{attempt}"
            try:
                _rename_noreplace_at(
                    source_parent_fd,
                    source_name,
                    quarantine_parent_fd,
                    destination_name,
                )
            except FileExistsError:
                continue
            destination = quarantine_parent / destination_name
            break
        if destination is None:
            raise SyncError(
                f"could not allocate a unique quarantine path for {source_name}"
            )

        try:
            os.fsync(source_parent_fd)
            os.fsync(quarantine_parent_fd)
            identity, link_target = _symlink_snapshot_at(
                quarantine_parent_fd,
                destination.name,
            )
            if not _bound_directory_matches(
                home,
                quarantine_parent,
                quarantine_parent_fd,
            ):
                raise SyncError(
                    f"quarantine leaf directory changed: {quarantine_parent}"
                )
        except BaseException as error:
            raise SyncError(
                "moved symlink leaf was retained in quarantine after validation "
                f"failed: {destination}: {error}"
            ) from error
        if identity != source_identity or link_target != source_target:
            try:
                _rename_noreplace_at(
                    quarantine_parent_fd,
                    destination.name,
                    source_parent_fd,
                    source_name,
                )
                os.fsync(source_parent_fd)
                if quarantine_parent_fd != source_parent_fd:
                    os.fsync(quarantine_parent_fd)
            except BaseException as restore_error:
                raise SyncError(
                    "symlink changed during quarantine and the moved replacement "
                    f"was retained at {destination}: {restore_error}"
                ) from restore_error
            restored_identity, restored_target = _symlink_snapshot_at(
                source_parent_fd,
                source_name,
            )
            if restored_identity != identity or restored_target != link_target:
                raise SyncError(
                    "symlink changed during quarantine and its exact restoration "
                    f"could not be verified: {source_name}"
                )
            raise SyncError(
                "symlink changed during quarantine; the moved replacement was "
                f"restored without replacement: {source_name}"
            )
        return destination, identity, link_target
    finally:
        _close_fd_quietly(quarantine_parent_fd)


def _move_regular_leaf_to_unique_quarantine(
    home: Path,
    source_parent: Path,
    source_parent_fd: int,
    source_name: str,
    *,
    label: str,
    expected: RegularFileSnapshot | None = None,
    expected_identity: tuple[int, int] | None = None,
    retain_batch_binding: bool = False,
) -> (
    tuple[Path, RegularFileSnapshot]
    | tuple[Path, RegularFileSnapshot, EphemeralQuarantineBatchBinding]
):
    source_path = Path(source_name)
    source_snapshot = _regular_file_snapshot_at(
        source_parent_fd,
        source_name,
        source_path,
    )
    if expected is not None and not _regular_snapshot_matches(
        source_snapshot,
        expected.parent_identity,
        expected,
        expected_link_count=expected.link_count,
    ):
        raise SyncError(f"regular file changed before quarantine: {source_name}")
    if (
        expected_identity is not None
        and source_snapshot.file_identity != expected_identity
    ):
        raise SyncError(f"regular file changed before quarantine: {source_name}")
    allocation: EphemeralQuarantineBatchAllocation | None = None
    quarantine_parent: Path | None = None
    destination: Path | None = None
    try:
        allocated = _quarantine_batch_root(
            home,
            [],
            retain_binding=True,
            retain_scaffold_binding=True,
        )
        assert isinstance(allocated, EphemeralQuarantineBatchAllocation)
        allocation = allocated
        batch_root = allocation.batch_root
        metadata = allocation.binding.metadata
        if (
            not _managed_state_snapshot_has_complete_file_evidence(metadata)
            or metadata.file_type != stat.S_IFREG
            or metadata.mode != 0o600
            or metadata.uid != os.geteuid()
        ):
            raise SyncError(f"ephemeral quarantine metadata is unsafe: {batch_root}")
        current_metadata = _read_managed_state_file_snapshot(
            home,
            batch_root / "metadata.json",
            allocation.batch_fd,
            expected_identity=metadata.file_identity,
            maximum_bytes=MAX_MANAGED_STATE_BYTES,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            current_metadata,
            metadata,
        ):
            raise SyncError(f"ephemeral quarantine metadata changed: {batch_root}")
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            batch_root / "metadata.json",
            allocation.batch_fd,
            current_metadata,
        )
        quarantine_parent = batch_root / "leaf"
        allocation.create_leaf()
        for attempt in range(100):
            destination_name = f"{label}-{os.getpid()}-{time.time_ns()}-{attempt}"
            try:
                _require_managed_regular_parent_chain_access(
                    home,
                    source_parent,
                    bound_parent_fd=source_parent_fd,
                )
                _require_ephemeral_quarantine_private_boundary(allocation)
                # rename(2) may commit and then surface a BaseException through
                # a wrapper or signal.  Empty-scaffold authority is therefore
                # revoked before the first attempt, not after apparent success.
                allocation.revoke_reclaim()
                _rename_noreplace_at(
                    source_parent_fd,
                    source_name,
                    allocation.leaf_fd,
                    destination_name,
                )
            except FileExistsError:
                continue
            destination = quarantine_parent / destination_name
            break
        if destination is None:
            raise SyncError(
                f"could not allocate a unique quarantine path for {source_name}"
            )
        try:
            os.fsync(source_parent_fd)
            os.fsync(allocation.leaf_fd)
            moved = _regular_file_snapshot_at(
                allocation.leaf_fd,
                destination.name,
                destination,
            )
            _require_ephemeral_quarantine_private_boundary(
                allocation,
                expected_leaf_members=(destination.name,),
            )
        except BaseException as error:
            raise SyncError(
                "moved regular-file leaf was retained in quarantine after "
                f"validation failed: {destination}: {error}"
            ) from error
        moved_matches = (
            _regular_snapshot_leaf_matches(
                moved,
                source_snapshot,
            )
            and moved.link_count == source_snapshot.link_count
        )
        if not moved_matches:
            raise SyncError(
                "regular file changed during quarantine and was retained as "
                f"isolated evidence at {destination}"
            )
        allocation.retire_allocation_fence_after_private_use(
            private_member_name=destination.name,
            private_member=moved,
        )
        if not retain_batch_binding:
            return destination, moved
        return (
            destination,
            moved,
            allocation.binding,
        )
    except BaseException as original_error:
        if allocation is not None and allocation.reclaim_authorized:
            try:
                allocation.reclaim_empty()
            except (OSError, SyncError) as cleanup_error:
                cleanup_note = (
                    "fallback quarantine setup failed and its empty scaffold could "
                    f"not be safely reclaimed: {cleanup_error}"
                )
                add_note = getattr(original_error, "add_note", None)
                if callable(add_note):
                    add_note(cleanup_note)
                else:
                    raise SyncError(
                        f"{cleanup_note}; original setup failure: {original_error}"
                    ) from cleanup_error
        raise
    finally:
        if allocation is not None:
            allocation.close()


def _publish_reconcile_directory_noreplace(
    parent_fd: int,
    name: str,
    display_path: Path,
) -> tuple[int, tuple[int, int]]:
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_CLOEXEC", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    temporary_name: str | None = None
    directory_fd = -1
    published = False
    try:
        for attempt in range(100):
            candidate = f".codex-sync-parent-{os.getpid()}-{time.time_ns()}-{attempt}"
            try:
                os.mkdir(candidate, mode=0o755, dir_fd=parent_fd)
            except FileExistsError:
                continue
            temporary_name = candidate
            break
        if temporary_name is None:
            raise SyncError(
                f"could not allocate temporary managed parent: {display_path}"
            )
        directory_fd = os.open(temporary_name, directory_flags, dir_fd=parent_fd)
        directory_identity = _directory_identity(directory_fd)
        try:
            _rename_noreplace_at(
                parent_fd,
                temporary_name,
                parent_fd,
                name,
            )
        except FileExistsError as error:
            raise SyncError(
                f"managed target parent appeared after planning: {display_path}"
            ) from error
        published = True
        temporary_name = None
        os.fsync(directory_fd)
        os.fsync(parent_fd)
        metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            not stat.S_ISDIR(metadata.st_mode)
            or (metadata.st_dev, metadata.st_ino) != directory_identity
        ):
            raise SyncError(
                f"managed target parent changed during creation: {display_path}"
            )
        return directory_fd, directory_identity
    except BaseException:
        if directory_fd >= 0:
            _close_fd_quietly(directory_fd)
        if temporary_name is not None:
            try:
                os.rmdir(temporary_name, dir_fd=parent_fd)
                os.fsync(parent_fd)
            except OSError:
                pass
        if published:
            raise SyncError(
                f"created managed parent was retained after validation failed: "
                f"{display_path}"
            )
        raise


def _open_reconcile_parent_for_create(
    home: Path,
    target: Path,
    expected_snapshot: ReconcileTargetSnapshot,
    created_parent_identities: dict[Path, tuple[int, int]],
    *,
    require_managed_parent_access: bool = False,
) -> int:
    if expected_snapshot.link_identity is not None:
        raise SyncError(f"create target was not absent when planned: {target}")
    if expected_snapshot.parent_identity is not None:
        _require_reconcile_target_snapshot(
            home,
            target,
            expected_snapshot,
            require_managed_parent_access=require_managed_parent_access,
        )
        parent_fd = _open_directory_beneath(home, target.parent)
        if _directory_identity(parent_fd) != expected_snapshot.parent_identity:
            _close_fd_quietly(parent_fd)
            raise SyncError(
                f"managed target parent changed after planning: {target.parent}"
            )
        if require_managed_parent_access:
            _require_managed_regular_parent_chain_access(
                home,
                target.parent,
                bound_parent_fd=parent_fd,
            )
        return parent_fd

    parent_parts = _directory_parts_beneath(home, target.parent)
    missing_parts = expected_snapshot.missing_parent_parts
    if (
        expected_snapshot.ancestor_identity is None
        or len(missing_parts) > len(parent_parts)
        or parent_parts[-len(missing_parts) :] != missing_parts
    ):
        raise SyncError(f"invalid missing-parent planning snapshot: {target.parent}")
    ancestor_parts = parent_parts[: len(parent_parts) - len(missing_parts)]
    ancestor_path = home.joinpath(*ancestor_parts)
    parent_fd = _open_directory_beneath(home, ancestor_path)
    try:
        if _directory_identity(
            parent_fd
        ) != expected_snapshot.ancestor_identity or not _bound_directory_matches(
            home, ancestor_path, parent_fd
        ):
            raise SyncError(
                f"managed target ancestor changed after planning: {ancestor_path}"
            )
        if require_managed_parent_access:
            _require_managed_regular_parent_chain_access(
                home,
                ancestor_path,
                bound_parent_fd=parent_fd,
            )
        current_path = ancestor_path
        directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        directory_flags |= getattr(os, "O_CLOEXEC", 0)
        directory_flags |= getattr(os, "O_NOFOLLOW", 0)
        for part in missing_parts:
            next_path = current_path / part
            expected_identity = created_parent_identities.get(next_path)
            if expected_identity is None:
                next_fd, expected_identity = _publish_reconcile_directory_noreplace(
                    parent_fd,
                    part,
                    next_path,
                )
                created_parent_identities[next_path] = expected_identity
            else:
                try:
                    next_fd = os.open(part, directory_flags, dir_fd=parent_fd)
                except OSError as error:
                    raise SyncError(
                        f"transaction-created managed parent changed: {next_path}"
                    ) from error
                if _directory_identity(next_fd) != expected_identity:
                    _close_fd_quietly(next_fd)
                    raise SyncError(
                        f"transaction-created managed parent changed: {next_path}"
                    )
            _close_fd_quietly(parent_fd)
            parent_fd = next_fd
            current_path = next_path
            if require_managed_parent_access:
                _require_managed_regular_directory_fd_access(
                    home,
                    current_path,
                    parent_fd,
                )
            elif not _bound_directory_matches(home, current_path, parent_fd):
                raise SyncError(
                    f"transaction-created managed parent changed: {current_path}"
                )
        try:
            os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            if require_managed_parent_access:
                _require_managed_regular_parent_chain_access(
                    home,
                    target.parent,
                    bound_parent_fd=parent_fd,
                )
            return parent_fd
        raise SyncError(f"managed target appeared after planning: {target}")
    except BaseException:
        _close_fd_quietly(parent_fd)
        raise


def _create_symlink_beneath(
    home: Path,
    target: Path,
    link_target: str,
    kind: str,
    expected_snapshot: ReconcileTargetSnapshot | None = None,
    created_parent_identities: dict[Path, tuple[int, int]] | None = None,
) -> SymlinkSnapshot:
    _ensure_safe_target_parent(home, target)
    if expected_snapshot is not None:
        if created_parent_identities is None:
            created_parent_identities = {}
        parent_fd = _open_reconcile_parent_for_create(
            home,
            target,
            expected_snapshot,
            created_parent_identities,
        )
    else:
        parent_fd = _open_or_create_directory_beneath(home, target.parent)
    created = False
    created_identity: tuple[int, int] | None = None
    try:
        parent_identity = _directory_identity(parent_fd)
        if (
            expected_snapshot is not None
            and expected_snapshot.parent_identity is not None
            and parent_identity != expected_snapshot.parent_identity
        ):
            raise SyncError(
                f"managed target parent changed after planning: {target.parent}"
            )
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        os.symlink(
            link_target,
            target.name,
            target_is_directory=kind in {"directory", "skill"},
            dir_fd=parent_fd,
        )
        created = True
        created_identity, actual_target = _symlink_snapshot_at(parent_fd, target.name)
        if actual_target != link_target:
            raise SyncError(f"created managed symlink changed: {target}")
        os.fsync(parent_fd)
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        return SymlinkSnapshot(
            parent_identity=parent_identity,
            link_identity=created_identity,
            link_target=actual_target,
        )
    except BaseException as error:
        if not created:
            raise
        if created_identity is None:
            raise SyncError(
                "managed symlink creation failed before its inode was bound; "
                f"the target was left in place: {target}"
            ) from error
        try:
            quarantine_path, moved_identity, moved_target = (
                _move_symlink_leaf_to_unique_quarantine(
                    home,
                    parent_fd,
                    target.name,
                    label="create-cleanup",
                    expected_identity=created_identity,
                    expected_link_target=link_target,
                )
            )
        except BaseException as cleanup_error:
            raise SyncError(
                "managed symlink creation failed and cleanup could not safely "
                f"quarantine {target}: {cleanup_error}"
            ) from error
        if (
            created_identity is None
            or moved_identity != created_identity
            or moved_target != link_target
        ):
            raise SyncError(
                "created managed symlink changed before cleanup and was retained "
                f"in quarantine: {target} -> {quarantine_path}"
            ) from error
        try:
            os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise SyncError(
                "managed symlink cleanup found a replacement leaf and left it in "
                f"place: {target}; created symlink retained in quarantine: "
                f"{quarantine_path}"
            ) from error
        raise
    finally:
        _close_fd_quietly(parent_fd)


def _read_regular_source_payload(home: Path, source: Path) -> bytes:
    try:
        source.relative_to(home)
    except ValueError:
        try:
            named = os.lstat(source)
        except OSError as error:
            raise SyncError(
                f"managed regular-file source is unreadable: {source}: {error}"
            ) from error
        if not stat.S_ISREG(named.st_mode):
            raise SyncError(f"managed regular-file source is not regular: {source}")
        if named.st_size > MAX_ARCHIVE_MEMBER_BYTES:
            raise SyncError(
                f"managed regular-file source exceeds the size limit: {source}"
            )
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        flags |= getattr(os, "O_NONBLOCK", 0)
        file_fd = -1
        try:
            file_fd = os.open(source, flags)
            if not _regular_stat_metadata_matches(os.fstat(file_fd), named):
                raise SyncError(
                    f"managed regular-file source changed before read: {source}"
                )
            payload = _read_managed_state_bytes(
                file_fd,
                source,
                MAX_ARCHIVE_MEMBER_BYTES,
            )
            os.lseek(file_fd, 0, os.SEEK_SET)
            confirmed = _read_managed_state_bytes(
                file_fd,
                source,
                MAX_ARCHIVE_MEMBER_BYTES,
            )
            if confirmed != payload or (
                not _regular_stat_metadata_matches(os.fstat(file_fd), named)
            ):
                raise SyncError(
                    f"managed regular-file source changed during read: {source}"
                )
            if not _regular_stat_metadata_matches(os.lstat(source), named):
                raise SyncError(
                    f"managed regular-file source changed during read: {source}"
                )
            return payload
        finally:
            if file_fd >= 0:
                _close_fd_quietly(file_fd)
    parent_fd = _open_directory_beneath(home, source.parent)
    try:
        snapshot = _read_managed_state_file_snapshot(
            home,
            source,
            parent_fd,
            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        )
        if not snapshot.exists or snapshot.payload is None:
            raise SyncError(f"managed regular-file source is missing: {source}")
        if snapshot.file_type != stat.S_IFREG:
            raise SyncError(f"managed regular-file source is not regular: {source}")
        return snapshot.payload
    finally:
        _close_fd_quietly(parent_fd)


def _evacuate_created_regular_leaf_after_failure(
    home: Path,
    target: Path,
    parent_fd: int,
    parent_identity: tuple[int, int],
    created_identity: tuple[int, int] | None,
    payload: bytes,
) -> tuple[Path, RegularFileSnapshot]:
    """Retain a failed create outside its canonical TOML pathname.

    The protected properties are the observed leaf's content stability and
    access policy, the identity of the already-bound parent, and the created
    leaf's object identity when the initial descriptor stat succeeded. A
    descriptor-stat failure cannot authorize leaving a loadable
    ``agents/*.toml`` behind, so the first operation is an identity-agnostic,
    no-replace rename to a high-entropy non-TOML alias in that bound parent.
    Identity/content/access validation happens only after the observed leaf is
    moved into a mode-0700 private quarantine. Parent timestamps and link-count
    churn are not mutation signals; parent object replacement, an unreadable or
    changed leaf, alias reappearance, or canonical-name reappearance all retain
    evidence and fail closed. An unbound replacement can therefore be retained,
    but is never deleted as though it were the created object. Before the first
    private move, an allocation-time binding over the batch, metadata and leaf
    authorizes reclamation only while that scaffold remains exact and empty.
    """
    active_name: str | None = None
    for _attempt in range(128):
        candidate = (
            f".codex-created-leaf-{os.getpid()}-{secrets.token_hex(16)}.evidence"
        )
        try:
            _rename_noreplace_at(
                parent_fd,
                target.name,
                parent_fd,
                candidate,
            )
        except FileExistsError:
            continue
        except FileNotFoundError as error:
            raise SyncError(
                f"created managed regular file disappeared before evacuation: {target}"
            ) from error
        active_name = candidate
        break
    if active_name is None:
        raise SyncError(
            f"could not allocate a non-loadable created-leaf alias: {target}"
        )
    active_path = target.with_name(active_name)
    try:
        os.fsync(parent_fd)
    except BaseException as error:
        raise SyncError(
            "created managed regular file was retained under a non-loadable "
            f"alias after evacuation sync failed: {active_path}: {error}"
        ) from error

    allocation: EphemeralQuarantineBatchAllocation | None = None
    destination: Path | None = None
    quarantine_setup_complete = False
    try:
        try:
            allocated = _quarantine_batch_root(
                home,
                [],
                retain_binding=True,
                retain_scaffold_binding=True,
            )
            assert isinstance(allocated, EphemeralQuarantineBatchAllocation)
            allocation = allocated
            batch_root = allocation.batch_root
            metadata = allocation.binding.metadata
            if (
                not _managed_state_snapshot_has_complete_file_evidence(metadata)
                or metadata.file_type != stat.S_IFREG
                or metadata.mode != 0o600
                or metadata.uid != os.geteuid()
            ):
                raise SyncError(
                    f"ephemeral quarantine metadata is unsafe: {batch_root}"
                )
            current_metadata = _read_managed_state_file_snapshot(
                home,
                batch_root / "metadata.json",
                allocation.batch_fd,
                expected_identity=metadata.file_identity,
                maximum_bytes=MAX_MANAGED_STATE_BYTES,
            )
            if not _managed_state_snapshot_matches_bound_file_evidence(
                current_metadata,
                metadata,
            ):
                raise SyncError(f"ephemeral quarantine metadata changed: {batch_root}")
            _require_pending_cleanup_file_snapshot_access_policy(
                home,
                batch_root / "metadata.json",
                allocation.batch_fd,
                current_metadata,
            )
            quarantine_parent = batch_root / "leaf"
            allocation.create_leaf()
            quarantine_setup_complete = True
        except BaseException as error:
            raise SyncError(
                "created managed regular file was retained under a non-loadable "
                "alias because private quarantine setup failed: "
                f"{active_path}: {error}"
            ) from error

        assert allocation is not None
        _require_ephemeral_quarantine_private_boundary(allocation)
        if _directory_identity(parent_fd) != parent_identity:
            raise SyncError(
                f"created managed regular-file parent binding changed: {target.parent}"
            )
        for _attempt in range(128):
            destination_name = (
                f"created-leaf-{os.getpid()}-{time.time_ns()}-"
                f"{secrets.token_hex(16)}.evidence"
            )
            try:
                _require_ephemeral_quarantine_private_boundary(allocation)
                allocation.revoke_reclaim()
                _rename_noreplace_at(
                    parent_fd,
                    active_name,
                    allocation.leaf_fd,
                    destination_name,
                )
            except FileExistsError:
                continue
            except FileNotFoundError as error:
                raise SyncError(
                    "created managed regular-file non-loadable alias disappeared "
                    f"before private isolation: {active_path}"
                ) from error
            destination = quarantine_parent / destination_name
            break
        if destination is None:
            raise SyncError(
                f"could not allocate private created-leaf evidence for {active_path}"
            )
        try:
            os.fsync(parent_fd)
            os.fsync(allocation.leaf_fd)
            moved = _regular_file_snapshot_at(
                allocation.leaf_fd,
                destination.name,
                destination,
            )
            _require_ephemeral_quarantine_private_boundary(
                allocation,
                expected_leaf_members=(destination.name,),
            )
        except BaseException as error:
            raise SyncError(
                "created managed regular-file evidence was retained in private "
                f"quarantine after validation failed: {destination}: {error}"
            ) from error

        if (
            (created_identity is not None and moved.file_identity != created_identity)
            or moved.sha256 != hashlib.sha256(payload).hexdigest()
            or moved.size != len(payload)
            or moved.mode != 0o600
            or moved.uid != os.geteuid()
            or moved.link_count != 1
        ):
            raise SyncError(
                "created managed regular file changed during evacuation and was "
                f"retained as private evidence: {target} -> {destination}"
            )
        try:
            canonical_identity = _named_entry_identity(parent_fd, target.name)
            active_identity = _named_entry_identity(parent_fd, active_name)
        except OSError as error:
            raise SyncError(
                "created managed regular-file public names became unreadable; "
                f"private evidence was retained: {destination}"
            ) from error
        if canonical_identity is not None:
            raise SyncError(
                "created managed regular-file canonical name reappeared; private "
                f"evidence was retained: {target} -> {destination}"
            )
        if active_identity is not None:
            raise SyncError(
                "created managed regular-file evacuation alias reappeared; private "
                f"evidence was retained: {active_path} -> {destination}"
            )
        if _directory_identity(
            parent_fd
        ) != parent_identity or not _bound_directory_matches(
            home, target.parent, parent_fd
        ):
            raise SyncError(
                "created managed regular-file parent changed during evacuation; "
                f"private evidence was retained: {destination}"
            )
        allocation.retire_allocation_fence_after_private_use(
            private_member_name=destination.name,
            private_member=moved,
        )
        return destination, moved
    except BaseException as original_error:
        if allocation is not None and allocation.reclaim_authorized:
            try:
                allocation.reclaim_empty()
            except (OSError, SyncError) as cleanup_error:
                cleanup_note = (
                    "created-leaf quarantine setup failed and its empty scaffold "
                    f"could not be safely reclaimed: {cleanup_error}"
                )
                add_note = getattr(original_error, "add_note", None)
                if callable(add_note):
                    add_note(cleanup_note)
                else:
                    raise SyncError(
                        f"{cleanup_note}; original setup failure: {original_error}"
                    ) from cleanup_error
        if quarantine_setup_complete and destination is None:
            raise SyncError(
                "created managed regular file remained under its non-loadable "
                "alias after private isolation failed: "
                f"{active_path}: {original_error}"
            ) from original_error
        raise
    finally:
        if allocation is not None:
            allocation.close()


def _create_regular_file_beneath(
    home: Path,
    source: Path,
    target: Path,
    expected_snapshot: ReconcileTargetSnapshot | None = None,
    created_parent_identities: dict[Path, tuple[int, int]] | None = None,
) -> RegularFileSnapshot:
    payload = _read_regular_source_payload(home, source)
    _ensure_safe_target_parent(home, target)
    if expected_snapshot is not None:
        if created_parent_identities is None:
            created_parent_identities = {}
        parent_fd = _open_reconcile_parent_for_create(
            home,
            target,
            expected_snapshot,
            created_parent_identities,
            require_managed_parent_access=True,
        )
    else:
        parent_fd = _open_or_create_directory_beneath(home, target.parent)
    file_fd = -1
    parent_identity: tuple[int, int] | None = None
    created = False
    created_identity: tuple[int, int] | None = None
    try:
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=parent_fd,
        )
        parent_identity = _directory_identity(parent_fd)
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        flags |= getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        file_fd = os.open(target.name, flags, 0o600, dir_fd=parent_fd)
        created = True
        opened = os.fstat(file_fd)
        created_identity = (opened.st_dev, opened.st_ino)
        os.fchmod(file_fd, 0o600)
        with os.fdopen(file_fd, "wb", closefd=True) as file:
            file_fd = -1
            file.write(payload)
            file.flush()
            os.fsync(file.fileno())
        os.fsync(parent_fd)
        snapshot = _regular_file_snapshot_at(parent_fd, target.name, target)
        if (
            snapshot.parent_identity != parent_identity
            or snapshot.file_identity != created_identity
            or snapshot.sha256 != hashlib.sha256(payload).hexdigest()
            or snapshot.mode != 0o600
            or snapshot.uid != os.geteuid()
            or snapshot.link_count != 1
        ):
            raise SyncError(f"created managed regular file changed: {target}")
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=parent_fd,
        )
        return snapshot
    except BaseException as error:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)
            file_fd = -1
        if created:
            assert parent_identity is not None
            try:
                _evacuate_created_regular_leaf_after_failure(
                    home,
                    target,
                    parent_fd,
                    parent_identity,
                    created_identity,
                    payload,
                )
            except (OSError, SyncError) as cleanup_error:
                raise SyncError(
                    "managed regular-file creation failed and exact cleanup "
                    f"could not be verified: {target}: {cleanup_error}"
                ) from error
        raise
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)
        _close_fd_quietly(parent_fd)


def _publish_symlink_hardlink_beneath(
    home: Path,
    source: Path,
    target: Path,
    source_snapshot: SymlinkSnapshot,
    expected_target_snapshot: ReconcileTargetSnapshot,
    created_parent_identities: dict[Path, tuple[int, int]],
) -> SymlinkSnapshot:
    source_parent_fd = _open_directory_beneath(home, source.parent)
    try:
        target_parent_fd = _open_reconcile_parent_for_create(
            home,
            target,
            expected_target_snapshot,
            created_parent_identities,
        )
    except BaseException:
        _close_fd_quietly(source_parent_fd)
        raise
    created = False
    created_identity: tuple[int, int] | None = None
    try:
        source_identity, source_target = _symlink_snapshot_at(
            source_parent_fd,
            source.name,
        )
        if (
            _directory_identity(source_parent_fd) != source_snapshot.parent_identity
            or source_identity != source_snapshot.link_identity
            or source_target != source_snapshot.link_target
            or not _bound_directory_matches(home, source.parent, source_parent_fd)
        ):
            raise SyncError(f"pending link stage changed: {source}")
        if not _bound_directory_matches(home, target.parent, target_parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        try:
            os.link(
                source.name,
                target.name,
                src_dir_fd=source_parent_fd,
                dst_dir_fd=target_parent_fd,
                follow_symlinks=False,
            )
        except OSError as error:
            raise SyncError(
                f"failed to publish inode-bound managed symlink {target}: {error}"
            ) from error
        created = True
        created_identity, created_target = _symlink_snapshot_at(
            target_parent_fd,
            target.name,
        )
        if (
            created_identity != source_snapshot.link_identity
            or created_target != source_snapshot.link_target
        ):
            raise SyncError(f"published managed symlink changed: {target}")
        os.fsync(target_parent_fd)
        if not _bound_directory_matches(
            home, source.parent, source_parent_fd
        ) or not _bound_directory_matches(home, target.parent, target_parent_fd):
            raise SyncError(f"managed link parent changed during publication: {target}")
        source_identity_after, source_target_after = _symlink_snapshot_at(
            source_parent_fd,
            source.name,
        )
        target_identity_after, target_value_after = _symlink_snapshot_at(
            target_parent_fd,
            target.name,
        )
        if (
            source_identity_after != source_snapshot.link_identity
            or source_target_after != source_snapshot.link_target
            or target_identity_after != source_snapshot.link_identity
            or target_value_after != source_snapshot.link_target
        ):
            raise SyncError(f"published managed symlink changed: {target}")
        return SymlinkSnapshot(
            parent_identity=_directory_identity(target_parent_fd),
            link_identity=target_identity_after,
            link_target=target_value_after,
        )
    except BaseException as error:
        if not created or created_identity is None:
            raise
        try:
            _remove_expected_symlink_beneath(
                home,
                target,
                source_snapshot.link_target,
                SymlinkSnapshot(
                    parent_identity=_directory_identity(target_parent_fd),
                    link_identity=created_identity,
                    link_target=source_snapshot.link_target,
                ),
            )
        except BaseException as cleanup_error:
            raise SyncError(
                "managed symlink publication failed and exact cleanup was "
                f"incomplete: {target}: {cleanup_error}"
            ) from error
        raise
    finally:
        _close_fd_quietly(target_parent_fd)
        _close_fd_quietly(source_parent_fd)


def _read_symlink_snapshot_beneath(
    home: Path,
    target: Path,
) -> SymlinkSnapshot:
    parent_fd = _open_directory_beneath(home, target.parent)
    try:
        parent_identity = _directory_identity(parent_fd)
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        link_identity, link_target = _symlink_snapshot_at(parent_fd, target.name)
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        return SymlinkSnapshot(
            parent_identity=parent_identity,
            link_identity=link_identity,
            link_target=link_target,
        )
    finally:
        _close_fd_quietly(parent_fd)


def _read_optional_symlink_snapshot_beneath(
    home: Path,
    target: Path,
) -> SymlinkSnapshot | None:
    try:
        parent_fd = _open_directory_beneath(home, target.parent)
    except FileNotFoundError:
        return None
    try:
        parent_identity = _directory_identity(parent_fd)
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        try:
            metadata = os.stat(
                target.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            if not _bound_directory_matches(home, target.parent, parent_fd):
                raise SyncError(f"managed target parent changed: {target.parent}")
            return None
        if not stat.S_ISLNK(metadata.st_mode):
            if not _bound_directory_matches(home, target.parent, parent_fd):
                raise SyncError(f"managed target parent changed: {target.parent}")
            return None
        link_identity, link_target = _symlink_snapshot_at(parent_fd, target.name)
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        return SymlinkSnapshot(
            parent_identity=parent_identity,
            link_identity=link_identity,
            link_target=link_target,
        )
    finally:
        _close_fd_quietly(parent_fd)


def _read_symlink_beneath(home: Path, target: Path) -> str:
    return _read_symlink_snapshot_beneath(home, target).link_target


def _remove_expected_symlink_beneath(
    home: Path,
    target: Path,
    expected_link_target: str,
    expected_snapshot: SymlinkSnapshot | None = None,
) -> None:
    parent_fd = _open_directory_beneath(home, target.parent)
    try:
        parent_identity = _directory_identity(parent_fd)
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
        identity, actual_target = _symlink_snapshot_at(parent_fd, target.name)
        actual_snapshot = SymlinkSnapshot(
            parent_identity=parent_identity,
            link_identity=identity,
            link_target=actual_target,
        )
        if actual_target != expected_link_target or (
            expected_snapshot is not None and actual_snapshot != expected_snapshot
        ):
            raise SyncError(f"refusing to remove changed managed symlink: {target}")
        quarantine_path, moved_identity, moved_target = (
            _move_symlink_leaf_to_unique_quarantine(
                home,
                parent_fd,
                target.name,
                label="remove",
                expected_identity=identity,
                expected_link_target=expected_link_target,
            )
        )
        if (
            moved_identity != identity
            or moved_target != expected_link_target
            or (
                expected_snapshot is not None
                and (
                    moved_identity != expected_snapshot.link_identity
                    or moved_target != expected_snapshot.link_target
                )
            )
        ):
            raise SyncError(
                "managed symlink changed during removal and was retained in "
                f"quarantine: {target} -> {quarantine_path}"
            )
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(
                "managed target parent changed during removal; symlink was retained "
                f"in quarantine: {quarantine_path}"
            )
        try:
            os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return
        raise SyncError(
            "managed target reappeared after removal and was left in place: "
            f"{target}; removed symlink retained in quarantine: {quarantine_path}"
        )
    finally:
        _close_fd_quietly(parent_fd)


def _ensure_safe_release_directory(
    home: Path,
    owner: str,
    sha: str,
    *,
    allow_missing: bool,
) -> bool:
    sha = _validate_release_sha(sha, f"release SHA for owner {owner}")
    releases_root = _releases_root(home, owner)
    if not _ensure_safe_internal_directory(
        home,
        releases_root,
        create=False,
        allow_missing=allow_missing,
    ):
        return False
    release_dir = releases_root / sha
    try:
        mode = os.lstat(release_dir).st_mode
    except FileNotFoundError:
        if allow_missing:
            return False
        raise SyncError(f"release directory is missing: {release_dir}")
    if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
        raise SyncError(f"refusing unsafe release directory: {release_dir}")
    return True


def _removed_link_key(removed: RemovedLink) -> str:
    return f"{removed.owner}:{removed.id}"


def _empty_managed_state() -> ManagedState:
    return ManagedState(owners={}, links={})


def _managed_state_metadata_snapshot(
    metadata: os.stat_result,
) -> tuple[int, int, int, int, int, int, int]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        stat.S_IFMT(metadata.st_mode),
        stat.S_IMODE(metadata.st_mode),
        metadata.st_uid,
        metadata.st_gid,
        metadata.st_size,
    )


def _managed_state_snapshot_has_complete_file_evidence(
    snapshot: ManagedStateFileSnapshot,
) -> bool:
    return (
        snapshot.exists
        and snapshot.payload is not None
        and snapshot.mode is not None
        and snapshot.file_identity is not None
        and snapshot.file_type is not None
        and snapshot.size is not None
        and snapshot.uid is not None
        and snapshot.gid is not None
        and snapshot.size == len(snapshot.payload)
    )


def _managed_state_snapshot_matches_file_evidence(
    actual: ManagedStateFileSnapshot,
    expected: ManagedStateFileSnapshot,
) -> bool:
    if not (
        _managed_state_snapshot_has_complete_file_evidence(actual)
        and _managed_state_snapshot_has_complete_file_evidence(expected)
    ):
        return False
    return (
        actual.payload == expected.payload
        and actual.mode == expected.mode
        and actual.file_identity == expected.file_identity
        and actual.file_type == expected.file_type
        and actual.size == expected.size
        and actual.uid == expected.uid
        and _gid_matches_regular_file_access_policy(
            actual.gid,
            expected.gid,
            expected.mode,
        )
    )


def _managed_state_snapshot_matches_bound_file_evidence(
    actual: ManagedStateFileSnapshot,
    expected: ManagedStateFileSnapshot,
) -> bool:
    return (
        actual.parent_identity == expected.parent_identity
        and _managed_state_snapshot_matches_file_evidence(actual, expected)
    )


def _pending_cleanup_ticket_matches(
    actual: PendingBatchCleanupTicket,
    expected: PendingBatchCleanupTicket,
) -> bool:
    return (
        actual.version == expected.version
        and actual.phase == expected.phase
        and actual.path == expected.path
        and _managed_state_snapshot_matches_bound_file_evidence(
            actual.snapshot,
            expected.snapshot,
        )
        and actual.batch_root == expected.batch_root
        and actual.batch_root_identity == expected.batch_root_identity
        and actual.marker_path == expected.marker_path
        and actual.marker_parent_identity == expected.marker_parent_identity
        and actual.marker_file_identity == expected.marker_file_identity
        and actual.marker_mode == expected.marker_mode
        and actual.marker_sha256 == expected.marker_sha256
        and actual.terminal_regular_targets == expected.terminal_regular_targets
        and actual.kind == expected.kind
        and actual.quarantine_root_identity == expected.quarantine_root_identity
        and actual.isolated_name == expected.isolated_name
        and actual.leaf_identity == expected.leaf_identity
        and actual.metadata_file_identity == expected.metadata_file_identity
        and actual.metadata_mode == expected.metadata_mode
        and actual.metadata_sha256 == expected.metadata_sha256
        and actual.metadata_size == expected.metadata_size
        and actual.public_target == expected.public_target
        and actual.public_parent_identity == expected.public_parent_identity
        and actual.payload_file_identity == expected.payload_file_identity
        and actual.payload_sha256 == expected.payload_sha256
        and actual.payload_size == expected.payload_size
        and actual.payload_mode == expected.payload_mode
        and actual.payload_uid == expected.payload_uid
        and actual.payload_gid == expected.payload_gid
        and actual.payload_link_count == expected.payload_link_count
    )


def _require_pending_cleanup_fd_access_policy(
    file_descriptor: int,
    display_path: Path,
    *,
    expected_mode: int,
) -> os.stat_result:
    """Prove owner-only access on the exact pending-control object.

    Object identity and type are stable signals and are revalidated by the
    generic exact-FD ACL admission. POSIX mode and Darwin ACL semantics are the
    protected access policy. ctime and directory link count are deliberately
    only resampling signals; neither is treated as mutation by itself.
    """
    expected_owner_uid = os.geteuid()
    try:
        metadata = _require_release_identity_fd_access_policy(
            file_descriptor,
            display_path,
            expected_owner_uid,
        )
    except SyncError as error:
        raise _PendingCleanupAccessPolicyError(str(error)) from error
    if metadata.st_uid != expected_owner_uid:
        raise _PendingCleanupAccessPolicyError(
            "pending cleanup access policy mismatch: "
            f"{display_path}: owner UID {metadata.st_uid} "
            f"!= expected UID {expected_owner_uid}"
        )
    if stat.S_IMODE(metadata.st_mode) != expected_mode:
        raise _PendingCleanupAccessPolicyError(
            "pending cleanup access policy mismatch: "
            f"{display_path}: mode {stat.S_IMODE(metadata.st_mode):04o} "
            f"!= {expected_mode:04o}"
        )
    return metadata


def _rmdir_bound_empty_pending_cleanup_directory(
    home: Path,
    parent_path: Path,
    parent_fd: int,
    expected_parent_identity: tuple[int, int],
    member_name: str,
    member_path: Path,
    member_fd: int,
    expected_member_identity: tuple[int, int],
    *,
    changed_message: str,
    mutation_revalidator: Callable[[], None],
) -> None:
    """Privately isolate and remove only the bound empty directory.

    The protected properties are the parent/member object identities, the
    member's empty contents, and owner-only access policy on both directories.
    Directory ctime and link count are intentionally not compared: child-entry
    churn can change both without replacing either protected object.  Portable
    Unix has no inode-conditional ``rmdir``, so atomically rename the current
    source to an identity-encoded, high-entropy private name first.  A source
    replacement observed before the final rebind is moved but retained as
    evidence; within the cooperative same-UID threat model, the expected object
    is then reopened with ``O_NOFOLLOW`` and removed.  This does not cover an
    excluded non-cooperating same-UID process actively replacing the
    high-entropy tombstone after that rebind.  No external mutation authority
    callback runs after isolation; the exact bound parent/member policies and
    pathname binding are revalidated before removal.
    """
    planned = (
        expected_member_identity[0],
        expected_member_identity[1],
        stat.S_IFDIR,
    )

    def require_parent_access_boundary() -> None:
        if _directory_identity(
            parent_fd
        ) != expected_parent_identity or not _bound_directory_matches(
            home, parent_path, parent_fd
        ):
            raise SyncError(changed_message)
        _require_pending_cleanup_fd_access_policy(
            parent_fd,
            parent_path,
            expected_mode=0o700,
        )

    boundary_fd = -1
    try:
        require_parent_access_boundary()
        if (
            _directory_identity(member_fd) != expected_member_identity
            or not _bound_directory_matches(home, member_path, member_fd)
            or _directory_member_names(member_fd, maximum_entries=1) != ()
        ):
            raise SyncError(changed_message)
        _require_pending_cleanup_fd_access_policy(
            member_fd,
            member_path,
            expected_mode=0o700,
        )

        private_name: str | None = None
        isolation_error: BaseException | None = None
        for _attempt in range(128):
            mutation_revalidator()
            # The callback may inspect mutable external authority. Reprove the
            # exact parent's binding and owner-only access policy after it
            # returns, before relying on this namespace for private isolation.
            require_parent_access_boundary()
            candidate = _pending_cleanup_entry_name(
                PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
                expected_parent_identity,
                planned,
            )
            try:
                _rename_noreplace_at(
                    parent_fd,
                    member_name,
                    parent_fd,
                    candidate,
                )
            except FileExistsError:
                continue
            except BaseException as error:
                source_identity = _named_entry_identity(parent_fd, member_name)
                candidate_identity = _named_entry_identity(parent_fd, candidate)
                if source_identity is None and candidate_identity is not None:
                    private_name = candidate
                    isolation_error = error
                    break
                if source_identity is None:
                    raise SyncError(
                        f"{changed_message}; directory disappeared during isolation"
                    ) from error
                raise SyncError(
                    f"{changed_message}; directory could not be privately isolated"
                ) from error
            private_name = candidate
            break
        if private_name is None:
            raise SyncError(
                f"{changed_message}; could not allocate a private isolation name"
            )
        os.fsync(parent_fd)

        private_path = parent_path / private_name
        try:
            boundary_fd = os.open(
                private_name,
                _directory_open_flags(nofollow=True),
                dir_fd=parent_fd,
            )
        except OSError:
            _retain_pending_cleanup_entry(
                parent_fd,
                private_name,
                expected_parent_identity,
                planned,
                label=f"{changed_message}; private evidence became unreadable",
            )
        if (
            _directory_identity(boundary_fd) != expected_member_identity
            or _directory_identity(member_fd) != expected_member_identity
            or _directory_identity(parent_fd) != expected_parent_identity
            or not _bound_directory_matches(home, parent_path, parent_fd)
            or not _bound_directory_matches(home, private_path, boundary_fd)
        ):
            _retain_pending_cleanup_entry(
                parent_fd,
                private_name,
                expected_parent_identity,
                planned,
                label=f"{changed_message}; private evidence changed identity",
            )
        # Reopening the private name rebinds the pathname to the expected
        # member descriptor, but identity alone does not preserve the parent's
        # owner-only namespace policy.
        require_parent_access_boundary()
        try:
            _require_pending_cleanup_fd_access_policy(
                boundary_fd,
                private_path,
                expected_mode=0o700,
            )
        except SyncError:
            _retain_pending_cleanup_entry(
                parent_fd,
                private_name,
                expected_parent_identity,
                planned,
                label=f"{changed_message}; private evidence changed access policy",
            )
        if (
            _directory_member_names(boundary_fd, maximum_entries=1) != ()
            or _named_entry_identity(parent_fd, private_name)
            != expected_member_identity
        ):
            _retain_pending_cleanup_entry(
                parent_fd,
                private_name,
                expected_parent_identity,
                planned,
                label=f"{changed_message}; private evidence changed contents",
            )
        if isolation_error is not None:
            raise isolation_error
        # Close the final pathname boundary in policy-before-binding order:
        # first prove that no non-owner can mutate the namespace, then rebind
        # the private name and contents to the still-open expected directory.
        require_parent_access_boundary()
        if (
            _directory_identity(boundary_fd) != expected_member_identity
            or _directory_identity(member_fd) != expected_member_identity
            or not _bound_directory_matches(home, private_path, boundary_fd)
            or _directory_member_names(boundary_fd, maximum_entries=1) != ()
            or _named_entry_identity(parent_fd, private_name)
            != expected_member_identity
        ):
            _retain_pending_cleanup_entry(
                parent_fd,
                private_name,
                expected_parent_identity,
                planned,
                label=f"{changed_message}; private evidence changed before removal",
            )
        # The verified private name is fresh, high entropy, and exists only in
        # this mode-0700 namespace.  Keep its exact descriptor live across the
        # only pathname-based destructive syscall available on portable Unix.
        os.rmdir(private_name, dir_fd=parent_fd)
        os.fsync(parent_fd)
        if _named_entry_identity(parent_fd, private_name) is not None:
            raise SyncError(f"{changed_message}; private name reappeared")
    except OSError as error:
        raise SyncError(changed_message) from error
    finally:
        _close_fd_quietly(boundary_fd)


def _require_current_user_cleanup_fd_access_policy(
    file_descriptor: int,
    display_path: Path,
) -> os.stat_result:
    """Prove a cleanup object has no non-owner write authority.

    The exact bound object, current-euid ownership, and absence of group/world
    POSIX write authority are protected on every platform. The generic policy
    additionally proves Darwin extended-ACL semantics without changing its
    intentionally metadata-only non-Darwin contract.
    """
    expected_owner_uid = os.geteuid()
    metadata = _require_release_identity_fd_access_policy(
        file_descriptor,
        display_path,
        expected_owner_uid,
    )
    if metadata.st_uid != expected_owner_uid:
        raise _release_identity_policy_error(
            display_path,
            f"owner UID {metadata.st_uid} != expected UID {expected_owner_uid}",
            mismatch=True,
        )
    mode = stat.S_IMODE(metadata.st_mode)
    if mode & 0o022:
        raise _release_identity_policy_error(
            display_path,
            f"mode {mode:04o} grants group or world write authority",
            mismatch=True,
        )
    return metadata


def _require_pending_cleanup_file_snapshot_access_policy(
    home: Path,
    path: Path,
    parent_fd: int,
    snapshot: ManagedStateFileSnapshot,
) -> None:
    if not snapshot.exists or snapshot.file_identity is None:
        raise SyncError(f"pending cleanup authority is missing: {path}")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    file_fd = -1
    try:
        file_fd = os.open(path.name, flags, dir_fd=parent_fd)
        before = _require_pending_cleanup_fd_access_policy(
            file_fd,
            path,
            expected_mode=0o600,
        )
        if (
            not stat.S_ISREG(before.st_mode)
            or (before.st_dev, before.st_ino) != snapshot.file_identity
            or before.st_uid != snapshot.uid
            or before.st_size != snapshot.size
        ):
            raise SyncError(f"pending cleanup authority changed: {path}")
        rebound = os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            (rebound.st_dev, rebound.st_ino) != snapshot.file_identity
            or stat.S_IFMT(rebound.st_mode) != stat.S_IFREG
            or not _bound_directory_matches(home, path.parent, parent_fd)
        ):
            raise SyncError(f"pending cleanup authority rebound: {path}")
        after = _require_pending_cleanup_fd_access_policy(
            file_fd,
            path,
            expected_mode=0o600,
        )
        if (after.st_dev, after.st_ino, after.st_size) != (
            before.st_dev,
            before.st_ino,
            before.st_size,
        ):
            raise SyncError(f"pending cleanup authority changed: {path}")
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)


def _require_pending_cleanup_file_snapshot_unchanged(
    home: Path,
    path: Path,
    parent_fd: int,
    expected: ManagedStateFileSnapshot,
    *,
    label: str,
    maximum_bytes: int = MAX_MANAGED_STATE_BYTES,
) -> ManagedStateFileSnapshot:
    """Rebind one exact control file's identity, bytes, and access policy."""
    current = _read_managed_state_file_snapshot(
        home,
        path,
        parent_fd,
        expected_identity=expected.file_identity,
        maximum_bytes=maximum_bytes,
    )
    if not _managed_state_snapshot_matches_bound_file_evidence(current, expected):
        raise SyncError(f"{label} changed")
    _require_pending_cleanup_file_snapshot_access_policy(
        home,
        path,
        parent_fd,
        current,
    )
    return current


def _read_managed_state_bytes(
    file_fd: int,
    path: Path,
    maximum_bytes: int = MAX_MANAGED_STATE_BYTES,
) -> bytes:
    payload = bytearray()
    try:
        while len(payload) <= maximum_bytes:
            chunk = os.read(
                file_fd,
                min(1024 * 1024, maximum_bytes + 1 - len(payload)),
            )
            if not chunk:
                break
            payload.extend(chunk)
    except OSError as error:
        raise SyncError(f"Failed to read {path}: {error}") from error
    if len(payload) > maximum_bytes:
        raise SyncError(
            f"Failed to read {path}: managed link state exceeds {maximum_bytes} bytes"
        )
    return bytes(payload)


def _decode_managed_state_json(payload: bytes, path: Path) -> dict[str, Any]:
    try:
        data = json.loads(
            payload.decode("utf-8"),
            parse_int=_bounded_json_integer,
            parse_constant=_reject_json_constant,
        )
    except (UnicodeDecodeError, ValueError, RecursionError) as error:
        raise SyncError(f"Invalid JSON in {path}: {error}") from error
    if not isinstance(data, dict):
        raise SyncError(f"Expected JSON object in {path}")
    return data


def _read_managed_state_file_snapshot(
    home: Path,
    path: Path,
    parent_fd: int,
    *,
    expected_identity: tuple[int, int] | None = None,
    maximum_bytes: int = MAX_MANAGED_STATE_BYTES,
) -> ManagedStateFileSnapshot:
    if not _bound_directory_matches(home, path.parent, parent_fd):
        raise SyncError(f"managed sync state parent changed before read: {path}")
    parent_identity = _directory_identity(parent_fd)
    try:
        named_metadata = os.stat(
            path.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError:
        if not _bound_directory_matches(home, path.parent, parent_fd):
            raise SyncError(f"managed sync state parent changed before read: {path}")
        return ManagedStateFileSnapshot(
            exists=False,
            parent_identity=parent_identity,
        )
    except OSError as error:
        raise SyncError(f"Failed to read {path}: {error}") from error
    if not stat.S_ISREG(named_metadata.st_mode):
        raise SyncError(f"refusing non-file sync state: {path}")
    if (
        expected_identity is not None
        and (named_metadata.st_dev, named_metadata.st_ino) != expected_identity
    ):
        raise SyncError(f"managed sync state changed before read: {path}")
    if named_metadata.st_size > maximum_bytes:
        raise SyncError(
            f"Failed to read {path}: managed link state exceeds {maximum_bytes} bytes"
        )

    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    file_fd = -1
    try:
        try:
            file_fd = os.open(path.name, flags, dir_fd=parent_fd)
        except OSError as error:
            raise SyncError(f"Failed to read {path}: {error}") from error
        opened_metadata = os.fstat(file_fd)
        if not stat.S_ISREG(opened_metadata.st_mode):
            raise SyncError(f"refusing non-file sync state: {path}")
        if not _regular_stat_metadata_matches(opened_metadata, named_metadata):
            raise SyncError(f"managed sync state changed before read: {path}")
        if (
            expected_identity is not None
            and (opened_metadata.st_dev, opened_metadata.st_ino) != expected_identity
        ):
            raise SyncError(f"managed sync state changed before read: {path}")
        if not _bound_directory_matches(home, path.parent, parent_fd):
            raise SyncError(f"managed sync state parent changed before read: {path}")

        payload = (
            _read_managed_state_bytes(file_fd, path)
            if maximum_bytes == MAX_MANAGED_STATE_BYTES
            else _read_managed_state_bytes(file_fd, path, maximum_bytes)
        )
        try:
            os.lseek(file_fd, 0, os.SEEK_SET)
        except OSError as error:
            raise SyncError(f"Failed to revalidate {path}: {error}") from error
        confirmed_payload = (
            _read_managed_state_bytes(file_fd, path)
            if maximum_bytes == MAX_MANAGED_STATE_BYTES
            else _read_managed_state_bytes(file_fd, path, maximum_bytes)
        )
        if confirmed_payload != payload:
            raise SyncError(f"managed sync state content changed during read: {path}")
        if not _regular_stat_metadata_matches(os.fstat(file_fd), named_metadata):
            raise SyncError(f"managed sync state changed during read: {path}")
        try:
            current_metadata = os.stat(
                path.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except OSError as error:
            raise SyncError(
                f"managed sync state changed during read: {path}"
            ) from error
        if not _regular_stat_metadata_matches(current_metadata, named_metadata):
            raise SyncError(f"managed sync state changed during read: {path}")
        if not _bound_directory_matches(home, path.parent, parent_fd):
            raise SyncError(f"managed sync state parent changed during read: {path}")
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)

    return ManagedStateFileSnapshot(
        exists=True,
        payload=payload,
        mode=stat.S_IMODE(opened_metadata.st_mode),
        parent_identity=parent_identity,
        file_identity=(opened_metadata.st_dev, opened_metadata.st_ino),
        file_type=stat.S_IFMT(opened_metadata.st_mode),
        size=opened_metadata.st_size,
        uid=opened_metadata.st_uid,
        gid=opened_metadata.st_gid,
    )


def _load_managed_state_payload_with_snapshot(
    home: Path,
    path: Path,
) -> tuple[dict[str, Any] | None, ManagedStateFileSnapshot]:
    if not _ensure_safe_internal_parent(
        home,
        path,
        create=False,
        allow_missing=True,
    ):
        return None, ManagedStateFileSnapshot(exists=False)

    try:
        parent_fd = _open_directory_beneath(home, path.parent)
    except (OSError, SyncError) as error:
        raise SyncError(f"Failed to read {path}: {error}") from error
    try:
        snapshot = _read_managed_state_file_snapshot(
            home,
            path,
            parent_fd,
        )
    finally:
        _close_fd_quietly(parent_fd)

    if not snapshot.exists:
        return None, snapshot
    assert snapshot.payload is not None
    return _decode_managed_state_json(snapshot.payload, path), snapshot


def _load_managed_state_payload(home: Path, path: Path) -> dict[str, Any] | None:
    data, _snapshot = _load_managed_state_payload_with_snapshot(home, path)
    return data


def _managed_state_from_payload(
    home: Path,
    data: dict[str, Any],
    manifest_entry_indexes: (
        dict[
            tuple[str, str],
            dict[tuple[PurePosixPath, PurePosixPath, str, str], LinkEntry],
        ]
        | None
    ) = None,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> ManagedState:
    version = data.get("version")
    if type(version) is not int or version != 1:
        raise SyncError("managed link state version must be 1")

    raw_owners = data.get("owners", {})
    if not isinstance(raw_owners, dict):
        raise SyncError("managed link state owners must be an object")
    owners: dict[str, str] = {}
    for raw_owner, raw_sha in raw_owners.items():
        owner = _validate_owner(raw_owner, "managed link owner")
        if not isinstance(raw_sha, str) or RELEASE_DIR_RE.fullmatch(raw_sha) is None:
            raise SyncError(f"managed link owner {owner} has invalid release SHA")
        owners[owner] = raw_sha
    _validate_portable_owner_spellings(list(owners))

    raw_links = data.get("links", [])
    if not isinstance(raw_links, list):
        raise SyncError("managed link state links must be an array")
    links: dict[PurePosixPath, ManagedLinkRecord] = {}
    for index, raw_link in enumerate(raw_links):
        if not isinstance(raw_link, dict):
            raise SyncError(f"managed link state entry #{index + 1} must be an object")
        source = _validate_relative_path(raw_link.get("source"), "managed link source")
        target = _validate_relative_path(raw_link.get("target"), "managed link target")
        kind = raw_link.get("kind")
        if kind not in {"file", "directory", "skill"}:
            raise SyncError(f"managed link {target} has unsupported kind: {kind}")
        owner = _validate_owner(raw_link.get("owner"), "managed link owner")
        link_target = raw_link.get("link_target")
        if not isinstance(link_target, str) or not link_target:
            raise SyncError(f"managed link {target} has invalid link_target")
        release_sha = raw_link.get("release_sha")
        if (
            not isinstance(release_sha, str)
            or RELEASE_DIR_RE.fullmatch(release_sha) is None
        ):
            raise SyncError(f"managed link {target} has invalid release SHA")
        if target in links:
            raise SyncError(f"duplicate managed link target: {target}")
        links[target] = ManagedLinkRecord(
            source=source,
            target=target,
            kind=kind,
            owner=owner,
            link_target=link_target,
            release_sha=release_sha,
        )

    if manifest_entry_indexes is None:
        manifest_entry_indexes = {}
    if manifest_cache is None:
        manifest_cache = {}
    for owner, sha in owners.items():
        _ensure_safe_release_directory(
            home,
            owner,
            sha,
            allow_missing=False,
        )
        try:
            manifest = _load_installed_manifest_data(
                home,
                owner,
                sha,
                manifest_cache=manifest_cache,
            )
        except SyncError as error:
            raise SyncError(
                f"managed link state references invalid release {owner}@{sha}: {error}",
                code=error.code,
            ) from error
        if manifest.owner != owner:
            raise SyncError(
                f"managed link state release owner mismatch: expected {owner}, "
                f"got {manifest.owner}"
            )
        manifest_entry_indexes[(owner, sha)] = {
            (entry.source, entry.target, entry.kind, entry.owner): entry
            for entry in manifest.entries
        }

    for record in links.values():
        owner_sha = owners.get(record.owner)
        if owner_sha != record.release_sha:
            raise SyncError(
                f"managed link {record.target} owner/release does not match state owners"
            )
        matching_entry = manifest_entry_indexes[(record.owner, record.release_sha)].get(
            (
                record.source,
                record.target,
                record.kind,
                record.owner,
            )
        )
        if matching_entry is None:
            raise SyncError(
                f"managed link {record.target} is not declared by "
                f"{record.owner}@{record.release_sha}"
            )
        expected_link_target = _desired_link_target(home, matching_entry)
        if record.link_target != expected_link_target:
            raise SyncError(f"managed link {record.target} has unexpected link_target")

    return ManagedState(owners=owners, links=links)


def _load_managed_state_with_snapshot(
    home: Path,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> tuple[ManagedState, ManagedStateFileSnapshot]:
    path = _state_path(home)
    data, snapshot = _load_managed_state_payload_with_snapshot(home, path)
    if data is None:
        return _empty_managed_state(), snapshot
    return _managed_state_from_payload(
        home,
        data,
        manifest_cache=manifest_cache,
    ), snapshot


def _load_managed_state(
    home: Path,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> ManagedState:
    state, _snapshot = _load_managed_state_with_snapshot(
        home,
        manifest_cache=manifest_cache,
    )
    return state


def _managed_state_payload(state: ManagedState) -> dict[str, Any]:
    return {
        "version": 1,
        "owners": dict(sorted(state.owners.items())),
        "links": [
            {
                "source": record.source.as_posix(),
                "target": record.target.as_posix(),
                "kind": record.kind,
                "owner": record.owner,
                "link_target": record.link_target,
                "release_sha": record.release_sha,
            }
            for record in sorted(
                state.links.values(), key=lambda item: item.target.as_posix()
            )
        ],
    }


def _managed_state_bytes(state: ManagedState) -> bytes:
    payload = (
        json.dumps(_managed_state_payload(state), indent=2, sort_keys=False) + "\n"
    )
    return payload.encode("utf-8")


def _snapshot_managed_state_file(home: Path) -> ManagedStateFileSnapshot:
    path = _state_path(home)
    if not _ensure_safe_internal_parent(
        home,
        path,
        create=False,
        allow_missing=True,
    ):
        return ManagedStateFileSnapshot(exists=False)
    try:
        parent_fd = _open_directory_beneath(home, path.parent)
    except (OSError, SyncError) as error:
        raise SyncError(f"refusing unsafe sync state: {path}") from error
    try:
        return _read_managed_state_file_snapshot(home, path, parent_fd)
    finally:
        _close_fd_quietly(parent_fd)


def _managed_state_file_matches(
    home: Path,
    path: Path,
    snapshot: ManagedStateFileSnapshot,
    expected_identity: tuple[int, int] | None = None,
    parent_fd: int | None = None,
) -> bool:
    effective_identity = expected_identity
    if effective_identity is None:
        effective_identity = snapshot.file_identity
    owns_parent_fd = parent_fd is None
    if parent_fd is None:
        try:
            parent_fd = _open_directory_beneath(home, path.parent)
        except (OSError, SyncError):
            return False
    assert parent_fd is not None
    try:
        current = _read_managed_state_file_snapshot(
            home,
            path,
            parent_fd,
            expected_identity=effective_identity,
        )
    except (OSError, SyncError):
        return False
    finally:
        if owns_parent_fd:
            _close_fd_quietly(parent_fd)
    if current.exists != snapshot.exists:
        return False
    if not snapshot.exists:
        return True
    assert current.payload is not None
    assert current.mode is not None
    return (
        current.mode == snapshot.mode
        and current.payload == snapshot.payload
        and (snapshot.file_type is None or current.file_type == snapshot.file_type)
        and (snapshot.size is None or current.size == snapshot.size)
        and (snapshot.uid is None or current.uid == snapshot.uid)
        and (
            snapshot.gid is None
            or _gid_matches_regular_file_access_policy(
                current.gid,
                snapshot.gid,
                snapshot.mode,
            )
        )
        and (effective_identity is None or current.file_identity == effective_identity)
    )


def _canonical_managed_state_matches_snapshot(
    home: Path,
    snapshot: ManagedStateFileSnapshot,
) -> bool:
    path = _state_path(home)
    if not _ensure_safe_internal_parent(
        home,
        path,
        create=False,
        allow_missing=True,
    ):
        return not snapshot.exists and snapshot.parent_identity is None
    try:
        with _managed_state_directory_fd(home, path.parent) as parent_fd:
            if (
                snapshot.parent_identity is not None
                and _directory_identity(parent_fd) != snapshot.parent_identity
            ):
                return False
            return _managed_state_file_matches(
                home,
                path,
                snapshot,
                snapshot.file_identity,
                parent_fd=parent_fd,
            )
    except (OSError, SyncError):
        return False


def _prepare_managed_state_transaction(
    home: Path,
    state: ManagedState,
    before_snapshot: ManagedStateFileSnapshot | None = None,
) -> ManagedStateFileTransaction:
    if before_snapshot is None:
        before_snapshot = _snapshot_managed_state_file(home)
    if before_snapshot.exists and (
        before_snapshot.parent_identity is None or before_snapshot.file_identity is None
    ):
        raise SyncError("managed state planning snapshot lacks canonical identity")
    if not _canonical_managed_state_matches_snapshot(home, before_snapshot):
        raise SyncError(f"sync state changed after planning: {_state_path(home)}")
    after_payload = _managed_state_bytes(state)
    return ManagedStateFileTransaction(
        before=before_snapshot,
        after=ManagedStateFileSnapshot(
            exists=True,
            payload=after_payload,
            mode=0o600,
            file_type=stat.S_IFREG,
            size=len(after_payload),
            uid=os.geteuid(),
        ),
    )


def _fsync_directory(path: Path, directory_fd: int | None = None) -> None:
    if directory_fd is not None:
        os.fsync(directory_fd)
        return
    directory_fd = os.open(path, os.O_RDONLY)
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)


@contextlib.contextmanager
def _managed_state_directory_fd(home: Path, directory: Path):
    directory_fd = _open_directory_beneath(home, directory)
    try:
        yield directory_fd
    finally:
        _close_fd_quietly(directory_fd)


def _managed_state_identity(file_fd: int) -> tuple[int, int]:
    metadata = os.fstat(file_fd)
    return metadata.st_dev, metadata.st_ino


def _write_managed_state_temp(
    parent_fd: int,
    path: Path,
    snapshot: ManagedStateFileSnapshot,
    label: str,
) -> tuple[str, tuple[int, int]]:
    assert snapshot.exists
    assert snapshot.payload is not None
    assert snapshot.mode is not None
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    flags |= getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    file_fd = -1
    temp_name = ""
    for attempt in range(100):
        temp_name = f".{path.name}.{label}.{os.getpid()}.{time.time_ns()}.{attempt}.tmp"
        try:
            file_fd = os.open(
                temp_name,
                flags,
                snapshot.mode,
                dir_fd=parent_fd,
            )
        except FileExistsError:
            continue
        break
    else:
        raise SyncError(f"could not allocate managed state temporary file for {path}")

    try:
        identity = _managed_state_identity(file_fd)
        file_object = os.fdopen(file_fd, "wb", closefd=True)
        file_fd = -1
        with file_object as file:
            os.fchmod(file.fileno(), snapshot.mode)
            file.write(snapshot.payload)
            file.flush()
            os.fsync(file.fileno())
    except BaseException:
        if file_fd >= 0:
            with contextlib.suppress(OSError):
                os.close(file_fd)
        raise
    return temp_name, identity


@contextlib.contextmanager
def _managed_state_quarantine_directory_fd(
    home: Path,
    transaction: ManagedStateFileTransaction,
):
    if transaction.batch_root is None:
        transaction.batch_root = _quarantine_batch_root(home, [])
    assert transaction.batch_root is not None
    state_fd = _open_or_create_directory_beneath(
        home,
        transaction.batch_root / "state",
        mode=0o700,
    )
    try:
        yield state_fd
    finally:
        _close_fd_quietly(state_fd)


def _move_managed_state_entry_to_quarantine(
    home: Path,
    transaction: ManagedStateFileTransaction,
    source_parent_fd: int,
    source_name: str,
    label: str,
    *,
    destination_name: str | None = None,
    expected_identity: tuple[int, int] | None = None,
    expected_snapshot: ManagedStateFileSnapshot | None = None,
) -> tuple[Path, bool]:
    source_metadata = os.stat(
        source_name,
        dir_fd=source_parent_fd,
        follow_symlinks=False,
    )
    source_identity = (source_metadata.st_dev, source_metadata.st_ino)
    if expected_identity is not None and source_identity != expected_identity:
        raise SyncError(f"managed state entry changed before quarantine: {source_name}")

    with _managed_state_quarantine_directory_fd(home, transaction) as quarantine_fd:
        selected_name = destination_name
        for attempt in range(100):
            if selected_name is None:
                selected_name = f"{label}-{time.time_ns()}-{attempt}"
            try:
                _rename_noreplace_at(
                    source_parent_fd,
                    source_name,
                    quarantine_fd,
                    selected_name,
                )
            except FileExistsError:
                if destination_name is not None:
                    raise
                selected_name = None
                continue
            break
        else:
            raise SyncError(
                f"could not allocate quarantine path for managed state {source_name}"
            )

        os.fsync(quarantine_fd)
        os.fsync(source_parent_fd)

        moved_metadata = os.stat(
            selected_name,
            dir_fd=quarantine_fd,
            follow_symlinks=False,
        )
        moved_identity = (moved_metadata.st_dev, moved_metadata.st_ino)
        matches = moved_identity == source_identity
        if expected_identity is not None:
            matches = matches and moved_identity == expected_identity
        if expected_snapshot is not None:
            assert transaction.batch_root is not None
            matches = matches and _managed_state_file_matches(
                home,
                transaction.batch_root / "state" / selected_name,
                expected_snapshot,
                moved_identity,
                parent_fd=quarantine_fd,
            )
        if not matches:
            assert selected_name is not None
            assert transaction.batch_root is not None
            quarantine_path = transaction.batch_root / "state" / selected_name
            try:
                _rename_noreplace_at(
                    quarantine_fd,
                    selected_name,
                    source_parent_fd,
                    source_name,
                )
            except BaseException as restore_error:
                raise SyncError(
                    "managed state entry changed during quarantine and the moved "
                    f"replacement was retained at {quarantine_path}: {restore_error}"
                ) from restore_error
            os.fsync(source_parent_fd)
            os.fsync(quarantine_fd)
            restored_metadata = os.stat(
                source_name,
                dir_fd=source_parent_fd,
                follow_symlinks=False,
            )
            if (restored_metadata.st_dev, restored_metadata.st_ino) != moved_identity:
                raise SyncError(
                    "managed state entry changed during quarantine and its exact "
                    f"restoration could not be verified: {source_name}"
                )
            if _managed_state_name_exists(quarantine_fd, selected_name):
                raise SyncError(
                    "managed state entry changed during quarantine and the "
                    f"destination still exists: {quarantine_path}"
                )
            raise SyncError(
                "managed state entry changed during quarantine; the moved "
                f"replacement was restored without replacement: {source_name}"
            )

    assert transaction.batch_root is not None
    return transaction.batch_root / "state" / selected_name, matches


def _managed_state_quarantine_file_matches(
    home: Path,
    transaction: ManagedStateFileTransaction,
    path: Path,
    snapshot: ManagedStateFileSnapshot,
) -> bool:
    if transaction.batch_root is None:
        return False
    expected_parent = transaction.batch_root / "state"
    if path.parent != expected_parent:
        return False
    try:
        with _managed_state_quarantine_directory_fd(home, transaction) as parent_fd:
            return _managed_state_file_matches(
                home,
                path,
                snapshot,
                parent_fd=parent_fd,
            )
    except (OSError, SyncError):
        return False


def _canonical_managed_state_matches(
    home: Path,
    path: Path,
    snapshot: ManagedStateFileSnapshot,
    parent_identity: tuple[int, int],
    file_identity: tuple[int, int],
) -> bool:
    try:
        with _managed_state_directory_fd(home, path.parent) as canonical_parent_fd:
            if _directory_identity(canonical_parent_fd) != parent_identity:
                return False
            return _managed_state_file_matches(
                home,
                path,
                snapshot,
                file_identity,
                parent_fd=canonical_parent_fd,
            )
    except (OSError, SyncError):
        return False


def _managed_state_name_exists(parent_fd: int, name: str) -> bool:
    try:
        os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        return False
    return True


def _apply_managed_state_transaction(
    home: Path,
    transaction: ManagedStateFileTransaction,
) -> None:
    path = _state_path(home)
    state_dir = path.parent
    _ensure_safe_internal_parent(home, path, create=True)
    with _managed_state_directory_fd(home, state_dir) as state_dir_fd:
        parent_identity = _directory_identity(state_dir_fd)
        transaction.state_parent_identity = parent_identity
        try:
            if (
                transaction.before.parent_identity is not None
                and parent_identity != transaction.before.parent_identity
            ):
                raise SyncError(
                    f"sync state parent changed after planning: {state_dir}"
                )
            if transaction.before.exists:
                if not _managed_state_file_matches(
                    home,
                    path,
                    transaction.before,
                    transaction.before.file_identity,
                    parent_fd=state_dir_fd,
                ):
                    raise SyncError(f"sync state changed before write: {path}")
                if transaction.before_evidence is not None:
                    evidence_parent_fd = _open_directory_beneath(
                        home,
                        transaction.before_evidence.parent,
                    )
                    try:
                        evidence_snapshot = _read_managed_state_file_snapshot(
                            home,
                            transaction.before_evidence,
                            evidence_parent_fd,
                            expected_identity=transaction.before.file_identity,
                        )
                    finally:
                        _close_fd_quietly(evidence_parent_fd)
                    if (
                        evidence_snapshot.file_identity
                        != transaction.before.file_identity
                        or evidence_snapshot.payload != transaction.before.payload
                        or evidence_snapshot.mode != transaction.before.mode
                    ):
                        raise SyncError("managed state before evidence changed")
                backup, backup_matches = _move_managed_state_entry_to_quarantine(
                    home,
                    transaction,
                    state_dir_fd,
                    path.name,
                    "original",
                    destination_name=path.name,
                    expected_identity=transaction.before.file_identity,
                    expected_snapshot=transaction.before,
                )
                transaction.backup = backup
                if not backup_matches:
                    raise SyncError(
                        "sync state changed before write and was retained in quarantine: "
                        f"{path} -> {backup}"
                    )
            elif not _managed_state_file_matches(
                home,
                path,
                transaction.before,
                parent_fd=state_dir_fd,
            ):
                raise SyncError(f"unexpected sync state appeared before write: {path}")

            if transaction.after_evidence is None:
                temp_name, publication_identity = _write_managed_state_temp(
                    state_dir_fd,
                    path,
                    transaction.after,
                    "publish",
                )
                _rename_noreplace_at(
                    state_dir_fd,
                    temp_name,
                    state_dir_fd,
                    path.name,
                )
            else:
                if transaction.after_evidence_identity is None:
                    raise SyncError("managed state after evidence has no identity")
                evidence_parent_fd = _open_directory_beneath(
                    home,
                    transaction.after_evidence.parent,
                )
                try:
                    evidence_snapshot = _read_managed_state_file_snapshot(
                        home,
                        transaction.after_evidence,
                        evidence_parent_fd,
                        expected_identity=transaction.after_evidence_identity,
                    )
                    if (
                        evidence_snapshot.payload != transaction.after.payload
                        or evidence_snapshot.mode != transaction.after.mode
                    ):
                        raise SyncError("managed state after evidence changed")
                    os.link(
                        transaction.after_evidence.name,
                        path.name,
                        src_dir_fd=evidence_parent_fd,
                        dst_dir_fd=state_dir_fd,
                        follow_symlinks=False,
                    )
                finally:
                    _close_fd_quietly(evidence_parent_fd)
                publication_identity = transaction.after_evidence_identity
            transaction.published = True
            transaction.published_identity = publication_identity
            if not _managed_state_file_matches(
                home,
                path,
                transaction.after,
                publication_identity,
                parent_fd=state_dir_fd,
            ):
                raise SyncError(
                    f"published sync state changed before verification: {path}"
                )
            _fsync_directory(state_dir, state_dir_fd)
            if not _canonical_managed_state_matches(
                home,
                path,
                transaction.after,
                parent_identity,
                publication_identity,
            ):
                raise SyncError(
                    f"published sync state changed after fsync or its parent changed: {path}"
                )
        except BaseException as error:
            retained_path: Path | None = None
            cleanup_error: BaseException | None = None
            if transaction.published and transaction.published_identity is not None:
                try:
                    retained_path, retained_matches = (
                        _move_managed_state_entry_to_quarantine(
                            home,
                            transaction,
                            state_dir_fd,
                            path.name,
                            "publish-error",
                            expected_identity=transaction.published_identity,
                        )
                    )
                    transaction.published = False
                    transaction.published_identity = None
                    if not retained_matches:
                        cleanup_error = SyncError(
                            "published sync state changed while being quarantined"
                        )
                except (OSError, SyncError) as quarantine_error:
                    cleanup_error = quarantine_error
            if cleanup_error is not None:
                raise SyncError(
                    "managed state publication failed and its bound published path "
                    f"could not be safely quarantined: {cleanup_error}"
                ) from error
            if retained_path is not None:
                raise SyncError(
                    f"managed state publication failed: {error}; "
                    f"retained in quarantine: {retained_path}"
                ) from error
            raise


def _restore_managed_state_file(
    home: Path,
    transaction: ManagedStateFileTransaction | None,
) -> None:
    if transaction is None:
        return
    path = _state_path(home)
    if not _ensure_safe_internal_parent(
        home,
        path,
        create=False,
        allow_missing=True,
    ):
        raise SyncError(f"sync state parent disappeared during rollback: {path.parent}")

    with _managed_state_directory_fd(home, path.parent) as state_dir_fd:
        parent_identity = _directory_identity(state_dir_fd)
        if (
            transaction.state_parent_identity is not None
            and parent_identity != transaction.state_parent_identity
        ):
            raise SyncError(
                f"sync state parent changed during rollback and was left in place: {path.parent}"
            )

        if transaction.published:
            if transaction.published_identity is None:
                raise SyncError(
                    f"published sync state identity is missing during rollback: {path}"
                )
            if not _managed_state_name_exists(state_dir_fd, path.name):
                raise SyncError(
                    f"published sync state disappeared during rollback: {path}"
                )
            rollback_backup, rollback_matches = _move_managed_state_entry_to_quarantine(
                home,
                transaction,
                state_dir_fd,
                path.name,
                "rollback-current",
                expected_identity=transaction.published_identity,
                expected_snapshot=transaction.after,
            )
            transaction.published = False
            transaction.published_identity = None
            if not rollback_matches:
                raise SyncError(
                    "changed sync state was retained in quarantine during rollback: "
                    f"{path} -> {rollback_backup}"
                )
        elif transaction.backup is None:
            if _managed_state_file_matches(
                home,
                path,
                transaction.before,
                parent_fd=state_dir_fd,
            ):
                return
            raise SyncError(
                f"sync state changed before rollback and was left in place: {path}"
            )
        elif _managed_state_name_exists(state_dir_fd, path.name):
            raise SyncError(
                f"changed sync state was left in place during rollback: {path}"
            )

        if not transaction.before.exists:
            return
        if transaction.backup is None:
            raise SyncError("managed state rollback has no original backup")
        if not _managed_state_quarantine_file_matches(
            home,
            transaction,
            transaction.backup,
            transaction.before,
        ):
            raise SyncError(
                "original sync state changed and was retained in quarantine: "
                f"{path} -> {transaction.backup}"
            )

        restored_created = False
        restored_identity: tuple[int, int] | None = None
        try:
            if transaction.before_evidence is None:
                temp_name, restored_identity = _write_managed_state_temp(
                    state_dir_fd,
                    path,
                    transaction.before,
                    "restore",
                )
                _rename_noreplace_at(
                    state_dir_fd,
                    temp_name,
                    state_dir_fd,
                    path.name,
                )
            else:
                if transaction.before.file_identity is None:
                    raise SyncError("managed state before evidence has no identity")
                evidence_parent_fd = _open_directory_beneath(
                    home,
                    transaction.before_evidence.parent,
                )
                try:
                    evidence_snapshot = _read_managed_state_file_snapshot(
                        home,
                        transaction.before_evidence,
                        evidence_parent_fd,
                        expected_identity=transaction.before.file_identity,
                    )
                    if (
                        evidence_snapshot.payload != transaction.before.payload
                        or evidence_snapshot.mode != transaction.before.mode
                    ):
                        raise SyncError("managed state before evidence changed")
                    os.link(
                        transaction.before_evidence.name,
                        path.name,
                        src_dir_fd=evidence_parent_fd,
                        dst_dir_fd=state_dir_fd,
                        follow_symlinks=False,
                    )
                finally:
                    _close_fd_quietly(evidence_parent_fd)
                restored_identity = transaction.before.file_identity
            restored_created = True
            if not _managed_state_file_matches(
                home,
                path,
                transaction.before,
                restored_identity,
                parent_fd=state_dir_fd,
            ):
                raise SyncError(
                    f"restored sync state changed before verification: {path}"
                )
            _fsync_directory(path.parent, state_dir_fd)
            if not _canonical_managed_state_matches(
                home,
                path,
                transaction.before,
                parent_identity,
                restored_identity,
            ):
                raise SyncError(
                    f"restored sync state changed after fsync or its parent changed: {path}"
                )
            if not _managed_state_quarantine_file_matches(
                home,
                transaction,
                transaction.backup,
                transaction.before,
            ):
                raise SyncError(
                    "original sync state changed and was retained in quarantine: "
                    f"{path} -> {transaction.backup}"
                )
        except BaseException as error:
            retained_path: Path | None = None
            cleanup_error: BaseException | None = None
            if restored_created and restored_identity is not None:
                try:
                    retained_path, retained_matches = (
                        _move_managed_state_entry_to_quarantine(
                            home,
                            transaction,
                            state_dir_fd,
                            path.name,
                            "restore-error",
                            expected_identity=restored_identity,
                        )
                    )
                    if not retained_matches:
                        cleanup_error = SyncError(
                            "restored sync state changed while being quarantined"
                        )
                except (OSError, SyncError) as quarantine_error:
                    cleanup_error = quarantine_error
            if cleanup_error is not None:
                raise SyncError(
                    "managed state restore failed and its bound restored path "
                    f"could not be safely quarantined: {cleanup_error}"
                ) from error
            if retained_path is not None:
                raise SyncError(
                    f"managed state restore failed: {error}; "
                    f"retained in quarantine: {retained_path}"
                ) from error
            if isinstance(error, FileExistsError):
                raise SyncError(
                    f"refusing to overwrite changed sync state during rollback: {path}"
                ) from error
            raise


def _commit_managed_state_transaction(
    transaction: ManagedStateFileTransaction | None,
) -> None:
    if transaction is None:
        return
    # Generic commit helpers never delete evidence by pathname. Committed pending
    # batches are removed separately through their durable cleanup ticket after
    # the active transaction pointer has been cleared.


def _write_managed_state(
    home: Path,
    state: ManagedState,
    transaction: ManagedStateFileTransaction | None = None,
) -> ManagedStateFileTransaction:
    owns_transaction = transaction is None
    if transaction is None:
        transaction = _prepare_managed_state_transaction(home, state)
    expected_payload = _managed_state_bytes(state)
    expected_after = ManagedStateFileSnapshot(
        exists=True,
        payload=expected_payload,
        mode=0o600,
        file_type=stat.S_IFREG,
        size=len(expected_payload),
        uid=os.geteuid(),
    )
    if transaction.after != expected_after:
        raise SyncError(
            "managed state transaction payload does not match requested state"
        )
    try:
        _apply_managed_state_transaction(home, transaction)
    except BaseException as error:
        if owns_transaction:
            try:
                _restore_managed_state_file(home, transaction)
            except (OSError, SyncError) as rollback_error:
                raise SyncError(
                    "managed state write failed and rollback was incomplete: "
                    f"{rollback_error}"
                ) from error
        raise
    if owns_transaction:
        _commit_managed_state_transaction(transaction)
    return transaction


def _current_manifest_data(
    home: Path,
    owner: str,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> ManifestData:
    sha = _current_sha(home, owner)
    if sha is None:
        return ManifestData(owner=owner, entries=[], removed_links=[])
    _ensure_safe_release_directory(
        home,
        owner,
        sha,
        allow_missing=False,
    )
    try:
        manifest = _load_installed_manifest_data(
            home,
            owner,
            sha,
            manifest_cache=manifest_cache,
        )
    except SyncError as error:
        raise SyncError(
            f"current pointer references invalid release {owner}@{sha}: {error}"
        ) from error
    if manifest.owner != owner:
        raise SyncError(
            f"current manifest owner mismatch: expected {owner}, got {manifest.owner}"
        )
    return manifest


def _read_optional_symlink_target_beneath(
    home: Path,
    target: Path,
) -> str | None:
    snapshot = _read_optional_symlink_snapshot_beneath(home, target)
    return None if snapshot is None else snapshot.link_target


def _is_optional_desired_entry(entry: LinkEntry) -> bool:
    return entry.owner == PUBLIC_OWNER and entry.target in OPTIONAL_PUBLIC_TARGETS


def _allows_optional_claim_relinquishment(
    target: PurePosixPath,
    desired_entry: LinkEntry | None,
) -> bool:
    return target in OPTIONAL_PUBLIC_TARGETS and (
        desired_entry is None or _is_optional_desired_entry(desired_entry)
    )


def _refresh_managed_state_from_current(
    home: Path,
    state: ManagedState,
    *,
    bootstrap_history: bool,
) -> ManagedState:
    manifest_cache: dict[tuple[str, str], ManifestData | None] = {}
    refreshed = ManagedState(
        owners=dict(state.owners),
        links=dict(state.links),
    )
    known_owners = _known_owners(home)
    for owner in sorted(known_owners):
        sha = _current_sha(home, owner)
        if sha is None:
            continue
        manifest = _current_manifest_data(
            home,
            owner,
            manifest_cache=manifest_cache,
        )
        refreshed.owners[owner] = sha
        for entry in manifest.entries:
            if not bootstrap_history and entry.target not in refreshed.links:
                continue
            target = _entry_target_path(home, entry)
            desired = _desired_link_target(home, entry)
            if _read_optional_symlink_target_beneath(home, target) == desired:
                refreshed.links[entry.target] = ManagedLinkRecord(
                    source=entry.source,
                    target=entry.target,
                    kind=entry.kind,
                    owner=entry.owner,
                    link_target=desired,
                    release_sha=sha,
                )
    if bootstrap_history:
        for owner in sorted(known_owners):
            releases_root = _releases_root(home, owner)
            if not _ensure_safe_internal_directory(
                home,
                releases_root,
                create=False,
                allow_missing=True,
            ):
                continue
            for release_root in _valid_release_dirs(
                home,
                owner,
                manifest_cache=manifest_cache,
            ):
                sha = release_root.name
                manifest = _load_installed_manifest_data(
                    home,
                    owner,
                    sha,
                    manifest_cache=manifest_cache,
                )
                if manifest.owner != owner:
                    continue
                for entry in manifest.entries:
                    if entry.target in refreshed.links:
                        continue
                    target = _entry_target_path(home, entry)
                    desired = _desired_link_target(home, entry)
                    if _read_optional_symlink_target_beneath(home, target) == desired:
                        refreshed.links[entry.target] = ManagedLinkRecord(
                            source=entry.source,
                            target=entry.target,
                            kind=entry.kind,
                            owner=entry.owner,
                            link_target=desired,
                            release_sha=sha,
                        )
    return refreshed


def _verify_managed_state_current_owner_claims(
    home: Path,
    state: ManagedState,
) -> None:
    for owner, release_sha in state.owners.items():
        current = _current_link(home, owner)
        actual_snapshot = _capture_reconcile_target_snapshot(home, current)
        expected_target = f"releases/{release_sha}"
        if actual_snapshot.link_identity is None:
            continue
        if actual_snapshot.link_target != expected_target:
            raise SyncError(
                "managed state/current release mismatch for "
                f"{owner}: state={release_sha}, "
                f"current={actual_snapshot.link_target}"
            )


def _regular_alias_identity_beneath(
    home: Path,
    path: Path,
) -> tuple[int, int] | None:
    try:
        parent_fd = _open_directory_beneath(home, path.parent)
    except FileNotFoundError:
        return None
    try:
        try:
            metadata = os.stat(
                path.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            return None
        if not _bound_directory_matches(home, path.parent, parent_fd):
            raise SyncError(f"pending regular-file alias parent changed: {path.parent}")
        return metadata.st_dev, metadata.st_ino
    finally:
        _close_fd_quietly(parent_fd)


def _verify_pending_regular_alias_batch_root(
    home: Path,
    batch: PendingLinkBatch,
) -> None:
    batch_fd = _open_directory_beneath(home, batch.batch_root)
    try:
        if _directory_identity(
            batch_fd
        ) != batch.batch_root_identity or not _bound_directory_matches(
            home, batch.batch_root, batch_fd
        ):
            raise SyncError(
                f"pending regular-file batch root changed: {batch.batch_root}"
            )
    finally:
        _close_fd_quietly(batch_fd)


def _build_pending_regular_alias_authority_index(
    home: Path,
    batch: PendingLinkBatch,
) -> _PendingRegularAliasAuthorityIndex:
    _verify_pending_regular_alias_batch_root(home, batch)
    mutable_authorities: dict[tuple[int, int], tuple[set[Path], set[Path]]] = {}

    def authority_for(
        identity: tuple[int, int],
    ) -> tuple[set[Path], set[Path]]:
        return mutable_authorities.setdefault(identity, (set(), set()))

    for record in batch.records:
        if not record.has_regular_authority():
            continue
        target = home / Path(*record.target.parts)
        if record.is_regular() and record.evidence_identity is not None:
            if record.stage is None or record.evidence is None:
                raise SyncError(
                    f"pending regular-file alias authority is incomplete: {record.target}"
                )
            authorized_paths, required_paths = authority_for(record.evidence_identity)
            stage = batch.batch_root / Path(*record.stage.parts)
            evidence = batch.batch_root / Path(*record.evidence.parts)
            authorized_paths.update((stage, evidence, target))
            required_paths.update((stage, evidence))
        if record.before_is_regular() and record.before_evidence_identity is not None:
            if record.before_evidence is None:
                raise SyncError(
                    f"pending regular-file preimage authority is incomplete: {record.target}"
                )
            authorized_paths, required_paths = authority_for(
                record.before_evidence_identity
            )
            before = batch.batch_root / Path(*record.before_evidence.parts)
            authorized_paths.update((before, target))
            required_paths.add(before)
            if record.backup is not None:
                authorized_paths.add(batch.batch_root / Path(*record.backup.parts))

    return _PendingRegularAliasAuthorityIndex(
        batch_root=batch.batch_root,
        batch_root_identity=batch.batch_root_identity,
        by_identity={
            identity: _PendingRegularAliasAuthority(
                authorized_paths=frozenset(authorized_paths),
                required_paths=frozenset(required_paths),
            )
            for identity, (
                authorized_paths,
                required_paths,
            ) in mutable_authorities.items()
        },
    )


def _pending_regular_alias_authority_index(
    home: Path,
    batch: PendingLinkBatch,
) -> _PendingRegularAliasAuthorityIndex:
    index = batch.regular_alias_authority_index
    if index is None:
        index = _build_pending_regular_alias_authority_index(home, batch)
        batch.regular_alias_authority_index = index
    elif (
        index.batch_root != batch.batch_root
        or index.batch_root_identity != batch.batch_root_identity
    ):
        raise SyncError("pending regular-file alias authority index is invalid")
    _verify_pending_regular_alias_batch_root(home, batch)
    return index


def _verify_pending_regular_aliases(
    home: Path,
    batch: PendingLinkBatch | None,
    observed_path: Path,
    snapshot: RegularFileSnapshot,
) -> None:
    if batch is None:
        if snapshot.link_count != 1:
            raise SyncError(
                f"managed regular file has an unauthorized hard link: {observed_path}"
            )
        return

    identity = snapshot.file_identity
    authority = _pending_regular_alias_authority_index(home, batch).by_identity.get(
        identity
    )
    if authority is None:
        if snapshot.link_count != 1:
            raise SyncError(
                "managed regular file has no transaction record authorizing its "
                f"hard links: {observed_path}"
            )
        return

    observed_aliases: set[Path] = set()
    for path in authority.authorized_paths | {observed_path}:
        alias_identity = _regular_alias_identity_beneath(home, path)
        if path in authority.required_paths and alias_identity != identity:
            raise SyncError(f"pending regular-file authority changed: {path}")
        if alias_identity == identity:
            observed_aliases.add(path)
    if observed_path not in observed_aliases:
        raise SyncError(f"pending regular-file observed alias changed: {observed_path}")
    if snapshot.link_count != len(observed_aliases):
        raise SyncError(
            "pending regular file has an unauthorized hard-link alias: "
            f"{observed_path} (links={snapshot.link_count}, "
            f"authorized={len(observed_aliases)})"
        )


def _verify_managed_state_link_claims(
    home: Path,
    state: ManagedState,
    planned_actions: list[ReconcileAction] | None = None,
    *,
    pending_batch: PendingLinkBatch | None = None,
) -> None:
    relinquishments: dict[PurePosixPath, ReconcileAction] = {}
    for action in planned_actions or []:
        if action.action != PENDING_RELINQUISH_FOREIGN_ACTION:
            continue
        try:
            target = PurePosixPath(*action.target.relative_to(home).parts)
        except ValueError as error:
            raise SyncError(
                f"managed relinquishment target is outside home: {action.target}"
            ) from error
        if target in relinquishments:
            raise SyncError(f"duplicate managed claim relinquishment: {target}")
        relinquishments[target] = action

    matched_relinquishments: set[PurePosixPath] = set()
    for target, record in state.links.items():
        relinquishment = relinquishments.get(target)
        actual_snapshot = _capture_reconcile_target_snapshot(
            home,
            home / Path(*target.parts),
            capture_regular_content=(
                relinquishment is None
                or relinquishment.planned_snapshot.regular_sha256 is not None
            ),
        )
        if actual_snapshot.link_identity is None:
            continue
        actual_regular = _regular_snapshot_from_reconcile(actual_snapshot)
        if _record_materializes_regular_file(record) and actual_regular is not None:
            _verify_pending_regular_aliases(
                home,
                pending_batch,
                home / Path(*target.parts),
                actual_regular,
            )
            if actual_regular.mode != 0o600 or actual_regular.uid != os.geteuid():
                raise SyncError(
                    f"managed regular file access policy mismatch: {target}"
                )
            expected_source = _record_regular_source_path(home, record)
            if actual_regular.sha256 == _regular_source_sha256(home, expected_source):
                continue
            raise SyncError(f"managed state/regular-file content mismatch for {target}")
        if actual_snapshot.link_target == record.link_target:
            continue
        if relinquishment is not None and _reconcile_target_snapshot_matches(
            actual_snapshot,
            relinquishment.planned_snapshot,
        ):
            matched_relinquishments.add(target)
            continue
        raise SyncError(
            "managed state/link target mismatch for "
            f"{target}: state={record.link_target}, "
            f"current={actual_snapshot.link_target}"
        )
    unmatched = set(relinquishments).difference(matched_relinquishments)
    if unmatched:
        raise SyncError(
            "managed claim relinquishment is not an exact state transition: "
            + ", ".join(target.as_posix() for target in sorted(unmatched))
        )


def _verify_managed_state_current_claims(
    home: Path,
    state: ManagedState,
    planned_actions: list[ReconcileAction] | None = None,
) -> None:
    _verify_managed_state_current_owner_claims(home, state)
    _verify_managed_state_link_claims(home, state, planned_actions)


def _entries_owner(entries: list[LinkEntry]) -> str:
    owners = {entry.owner for entry in entries}
    if not owners:
        return PUBLIC_OWNER
    if len(owners) != 1:
        raise SyncError("sync manifest entries must use a single owner")
    return next(iter(owners))


def _install_lock_binding_matches(
    home: Path,
    lock_path: Path,
    parent_fd: int,
    expected_parent_identity: tuple[int, int],
    lock_fd: int,
    expected_lock_identity: tuple[int, int],
) -> bool:
    try:
        parent_metadata = os.fstat(parent_fd)
        lock_metadata = os.fstat(lock_fd)
    except OSError:
        return False
    if (
        not stat.S_ISDIR(parent_metadata.st_mode)
        or (parent_metadata.st_dev, parent_metadata.st_ino) != expected_parent_identity
        or not stat.S_ISREG(lock_metadata.st_mode)
        or (lock_metadata.st_dev, lock_metadata.st_ino) != expected_lock_identity
    ):
        return False
    if not _bound_directory_matches(home, lock_path.parent, parent_fd):
        return False
    try:
        named_metadata = os.stat(
            lock_path.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
    except OSError:
        return False
    if (
        not stat.S_ISREG(named_metadata.st_mode)
        or (named_metadata.st_dev, named_metadata.st_ino) != expected_lock_identity
    ):
        return False
    return _bound_directory_matches(home, lock_path.parent, parent_fd)


@contextlib.contextmanager
def installation_lock(home: Path, *, create: bool = True):
    """Serialize cooperative installers on a stable local sync-home inode."""
    lock_path = _install_lock_path(home)
    sync_root = lock_path.parent
    home_fd = _open_or_create_sync_home(home) if create else _open_sync_home(home)
    directory_fd = -1
    lock_fd = -1
    home_lock_acquired = False
    lock_acquired = False
    binding_token = None
    lock_flags = os.O_RDWR
    if create:
        lock_flags |= os.O_CREAT
    lock_flags |= getattr(os, "O_CLOEXEC", 0)
    lock_flags |= getattr(os, "O_NOFOLLOW", 0)
    lock_flags |= getattr(os, "O_NONBLOCK", 0)
    try:
        # Cooperative peers may rotate sync_root or install.lock, but the local
        # sync-home directory inode is the stable serialization anchor.
        home_identity = _directory_identity(home_fd)
        fcntl.flock(home_fd, fcntl.LOCK_EX)
        home_lock_acquired = True
        if _directory_identity(
            home_fd
        ) != home_identity or not _bound_directory_matches(home, home, home_fd):
            raise SyncError(f"install lock stable home changed: {home}")
        directory_fd = (
            _open_or_create_directory_beneath(
                home,
                sync_root,
                mode=0o700,
                home_fd=home_fd,
            )
            if create
            else _open_directory_beneath(
                home,
                sync_root,
                home_fd=home_fd,
            )
        )
        parent_identity = _directory_identity(directory_fd)
        if not _bound_directory_matches(home, sync_root, directory_fd):
            raise SyncError(f"install lock parent changed before open: {sync_root}")
        try:
            lock_fd = os.open(
                lock_path.name,
                lock_flags,
                0o600,
                dir_fd=directory_fd,
            )
        except FileNotFoundError:
            if create:
                raise
            lock_fd = -1
        except OSError as error:
            raise SyncError(
                f"refusing unsafe install lock: {lock_path}: {error}"
            ) from error
        if lock_fd >= 0:
            lock_metadata = os.fstat(lock_fd)
            if not stat.S_ISREG(lock_metadata.st_mode):
                raise SyncError(f"refusing non-file install lock: {lock_path}")
            lock_identity = (lock_metadata.st_dev, lock_metadata.st_ino)
            fcntl.flock(lock_fd, fcntl.LOCK_EX)
            lock_acquired = True
            if not _install_lock_binding_matches(
                home,
                lock_path,
                directory_fd,
                parent_identity,
                lock_fd,
                lock_identity,
            ):
                raise SyncError(
                    f"install lock binding changed after acquisition: {lock_path}"
                )
            if not _install_lock_binding_matches(
                home,
                lock_path,
                directory_fd,
                parent_identity,
                lock_fd,
                lock_identity,
            ):
                raise SyncError(
                    f"install lock binding changed before transaction: {lock_path}"
                )
        binding_token = _LOCKED_SYNC_HOME_BINDINGS.set(
            _LOCKED_SYNC_HOME_BINDINGS.get()
            + ((_sync_home_binding_key(home), home_fd),)
        )
        try:
            _revalidate_active_scheduler_attempt_unlocked(home)
            yield
        finally:
            if _directory_identity(
                home_fd
            ) != home_identity or not _bound_directory_matches(home, home, home_fd):
                raise SyncError(
                    f"install lock stable home changed during transaction: {home}"
                )
            if lock_fd >= 0:
                if not _install_lock_binding_matches(
                    home,
                    lock_path,
                    directory_fd,
                    parent_identity,
                    lock_fd,
                    lock_identity,
                ):
                    raise SyncError(
                        f"install lock binding changed during transaction: {lock_path}"
                    )
                fcntl.flock(lock_fd, fcntl.LOCK_UN)
                lock_acquired = False
    finally:
        if binding_token is not None:
            _LOCKED_SYNC_HOME_BINDINGS.reset(binding_token)
        if lock_acquired:
            try:
                fcntl.flock(lock_fd, fcntl.LOCK_UN)
            except OSError:
                pass
        if lock_fd >= 0:
            _close_fd_quietly(lock_fd)
        if directory_fd >= 0:
            _close_fd_quietly(directory_fd)
        if home_lock_acquired:
            try:
                fcntl.flock(home_fd, fcntl.LOCK_UN)
            except OSError:
                pass
        _close_fd_quietly(home_fd)


def _entry_target_path(home: Path, entry: LinkEntry) -> Path:
    return home / Path(*entry.target.parts)


def _desired_link_target(home: Path, entry: LinkEntry) -> str:
    del home
    return _relative_managed_link_target(
        entry.source,
        entry.target,
        entry.owner,
    )


def _entry_materializes_regular_file(entry: LinkEntry) -> bool:
    """Keep Codex custom-agent TOML files independent from release symlinks."""
    portable_parts = _portable_target_key(entry.target)
    return (
        entry.kind == "file"
        and len(portable_parts) == 2
        and portable_parts[0] == "agents"
        and portable_parts[1].endswith(".toml")
    )


def _record_materializes_regular_file(record: ManagedLinkRecord) -> bool:
    return _entry_materializes_regular_file(
        LinkEntry(
            source=record.source,
            target=record.target,
            kind=record.kind,
            owner=record.owner,
        )
    )


def _entry_regular_source_path(
    home: Path,
    entry: LinkEntry,
    owner_shas: dict[str, str] | None = None,
) -> Path:
    if not _entry_materializes_regular_file(entry):
        raise SyncError(f"entry is not a managed regular file: {entry.target}")
    sha = (owner_shas or {}).get(entry.owner)
    if sha is None:
        sha = _current_sha(home, entry.owner)
    if sha is None:
        raise SyncError(
            f"managed regular file has no installed release: {entry.target}"
        )
    sha = _validate_release_sha(sha)
    _ensure_safe_release_directory(home, entry.owner, sha, allow_missing=False)
    return _releases_root(home, entry.owner) / sha / Path(*entry.source.parts)


def _record_regular_source_path(home: Path, record: ManagedLinkRecord) -> Path:
    if not _record_materializes_regular_file(record):
        raise SyncError(f"record is not a managed regular file: {record.target}")
    sha = _validate_release_sha(record.release_sha)
    _ensure_safe_release_directory(home, record.owner, sha, allow_missing=False)
    return _releases_root(home, record.owner) / sha / Path(*record.source.parts)


def _regular_source_sha256(home: Path, source: Path) -> str:
    return hashlib.sha256(_read_regular_source_payload(home, source)).hexdigest()


def _regular_snapshot_has_managed_access(snapshot: RegularFileSnapshot) -> bool:
    return (
        snapshot.mode == 0o600
        and snapshot.uid == os.geteuid()
        and snapshot.link_count == 1
    )


def _regular_snapshot_from_reconcile(
    snapshot: ReconcileTargetSnapshot,
) -> RegularFileSnapshot | None:
    if snapshot.regular_sha256 is None:
        return None
    assert snapshot.parent_identity is not None
    assert snapshot.link_identity is not None
    assert snapshot.regular_size is not None
    assert snapshot.regular_mode is not None
    assert snapshot.regular_uid is not None
    assert snapshot.regular_gid is not None
    assert snapshot.regular_link_count is not None
    return RegularFileSnapshot(
        parent_identity=snapshot.parent_identity,
        file_identity=snapshot.link_identity,
        sha256=snapshot.regular_sha256,
        size=snapshot.regular_size,
        mode=snapshot.regular_mode,
        uid=snapshot.regular_uid,
        gid=snapshot.regular_gid,
        link_count=snapshot.regular_link_count,
    )


def _path_exists_or_is_link(path: Path) -> bool:
    return os.path.lexists(path)


def _ensure_safe_target_parent(home: Path, target: Path) -> None:
    try:
        relative_target = target.relative_to(home)
    except ValueError as error:
        raise SyncError(f"managed target is outside home: {target}") from error
    current = home
    for part in relative_target.parts[:-1]:
        current = current / part
        if current.is_symlink():
            raise SyncError(f"refusing managed target below symlink parent: {current}")
        if _path_exists_or_is_link(current) and not current.is_dir():
            raise SyncError(f"link parent exists but is not a directory: {current}")


def _require_managed_regular_directory_fd_access(
    home: Path,
    directory: Path,
    directory_fd: int,
) -> os.stat_result:
    """Prove an exact directory FD remains owner-controlled and path-bound.

    The protected properties are directory object identity and access policy.
    Child-entry churn is intentionally absent from the evidence: directory
    link counts and timestamps are not compared.
    """
    try:
        metadata = _require_release_identity_fd_access_policy(
            directory_fd,
            directory,
            os.geteuid(),
        )
    except SyncError as error:
        classification = (
            "mismatch"
            if " access policy mismatch:" in str(error)
            else "cannot be verified"
        )
        raise SyncError(
            f"managed regular-file parent access policy {classification}: "
            f"{directory}: {error}"
        ) from error
    mode = stat.S_IMODE(metadata.st_mode)
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or metadata.st_uid != os.geteuid()
        or mode & 0o022
    ):
        raise SyncError(
            "managed regular-file parent access policy mismatch: "
            f"{directory} (mode={mode:04o}, uid={metadata.st_uid})"
        )
    if not _bound_directory_matches(home, directory, directory_fd):
        raise SyncError(f"managed regular-file parent changed: {directory}")
    return metadata


def _require_managed_regular_parent_chain_access(
    home: Path,
    directory: Path,
    *,
    bound_parent_fd: int | None = None,
) -> None:
    parts = _directory_parts_beneath(home, directory)
    current_fd = _bound_sync_home_anchor(home, None)
    current_path = home
    try:
        metadata = _require_managed_regular_directory_fd_access(
            home,
            current_path,
            current_fd,
        )
        for part in parts:
            try:
                next_fd = os.open(
                    part,
                    _directory_open_flags(nofollow=True),
                    dir_fd=current_fd,
                )
            except OSError as error:
                raise SyncError(
                    f"managed regular-file parent chain is unreadable: {directory}"
                ) from error
            _close_fd_quietly(current_fd)
            current_fd = next_fd
            current_path /= part
            metadata = _require_managed_regular_directory_fd_access(
                home,
                current_path,
                current_fd,
            )
        if bound_parent_fd is None:
            return
        bound_metadata = _require_managed_regular_directory_fd_access(
            home,
            directory,
            bound_parent_fd,
        )
        if (bound_metadata.st_dev, bound_metadata.st_ino) != (
            metadata.st_dev,
            metadata.st_ino,
        ):
            raise SyncError(f"managed regular-file parent changed: {directory}")
    finally:
        _close_fd_quietly(current_fd)


def _known_owners(home: Path, extra_owners: set[str] | None = None) -> set[str]:
    owners = {PUBLIC_OWNER}
    if extra_owners:
        owners.update(extra_owners)
    overlays_root = _personal_sync_root(home) / "overlays"
    if not _ensure_safe_internal_directory(
        home,
        overlays_root,
        create=False,
        allow_missing=True,
    ):
        _validate_portable_owner_spellings(list(owners))
        return owners
    for path in overlays_root.iterdir():
        if not _owner_is_valid(path.name):
            continue
        mode = os.lstat(path).st_mode
        if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
            raise SyncError(f"refusing unsafe overlay directory: {path}")
        owners.add(path.name)
    _validate_portable_owner_spellings(list(owners))
    return owners


def _link_managed_owner(
    home: Path, link: Path, owners: set[str] | None = None
) -> str | None:
    link_target = _read_symlink_beneath(home, link)
    linked_path = (link.parent / link_target).resolve(strict=False)
    for owner in sorted(
        _known_owners(home, owners),
        key=lambda value: (value != PUBLIC_OWNER, value),
    ):
        releases_root = _releases_root(home, owner).resolve(strict=False)
        try:
            linked_path.relative_to(releases_root)
        except ValueError:
            continue
        return owner
    return None


def _removed_link_target(home: Path, removed: RemovedLink) -> str:
    entry = LinkEntry(
        source=removed.source,
        target=removed.target,
        kind=removed.kind,
        owner=removed.owner,
    )
    return _desired_link_target(home, entry)


def _removed_link_exactly_matches_managed_record(
    removed: RemovedLink,
    record: ManagedLinkRecord,
) -> bool:
    return (
        removed.source == record.source
        and removed.target == record.target
        and removed.kind == record.kind
        and removed.owner == record.owner
    )


def _same_target_regular_to_symlink_removal(
    removed_links: list[RemovedLink] | tuple[RemovedLink, ...],
    record: ManagedLinkRecord,
    desired_entry: LinkEntry,
    *,
    removed_link_key: str | None = None,
) -> RemovedLink | None:
    if (
        not _record_materializes_regular_file(record)
        or _entry_materializes_regular_file(desired_entry)
        or desired_entry.kind not in {"directory", "skill"}
        or desired_entry.target != record.target
    ):
        return None
    matches = [
        removed
        for removed in removed_links
        if _removed_link_exactly_matches_managed_record(removed, record)
        and removed.replacement_target == desired_entry.target
        and (removed_link_key is None or _removed_link_key(removed) == removed_link_key)
    ]
    if len(matches) != 1:
        return None
    return matches[0]


def _regular_to_symlink_reconcile_action_is_typed(
    action: ReconcileAction,
) -> bool:
    return (
        action.action == "quarantine-replace"
        and action.materialization == "symlink"
        and action.kind in {"directory", "skill"}
        and action.regular_source is None
        and action.regular_size is None
        and action.expected_link_target is not None
        and action.removed_link_key is not None
        and bool(action.link_target)
        and action.planned_snapshot is not None
        and _regular_snapshot_from_reconcile(action.planned_snapshot) is not None
    )


def _pending_release_removal_authority(
    home: Path,
    expectation: PendingReleaseExpectation,
) -> dict[str, RemovedLink]:
    """Return removal authority from one exact receipt-bound release snapshot."""
    identity, directory_identity = _installed_release_identity_and_directory_identity(
        home,
        expectation.owner,
        expectation.sha,
    )
    if (
        directory_identity != expectation.directory_identity
        or identity[2] != expectation.tree_sha256
    ):
        raise SyncError(
            "pending removal-authority release tree changed: "
            f"{expectation.owner}@{expectation.sha}"
        )
    removal_by_key: dict[str, RemovedLink] = {}
    for removed in identity[1].removed_links:
        key = _removed_link_key(removed)
        if key in removal_by_key:
            raise SyncError(f"pending release has duplicate removal authority: {key}")
        removal_by_key[key] = removed
    return removal_by_key


@dataclass(frozen=True)
class _PendingRegularSourceEvidence:
    sha256: str
    size: int
    source_receipt: tuple[int, int, int, int, int, int, int, int, int]
    release_receipt: _PendingRegularReleaseReceipt


@dataclass(frozen=True)
class _PendingRegularReleaseReceipt:
    source_snapshots: dict[PurePosixPath, _ReleaseSourceSnapshot]
    source_members: dict[PurePosixPath, tuple[str, ...]]
    expected_owner_uid: int | None


def _pending_regular_source_receipt(
    metadata: os.stat_result,
) -> tuple[int, int, int, int, int, int, int, int, int]:
    """Capture the signals that keep cached content evidence usable.

    Device/inode protect object identity; mode/owner/group/link count protect
    access and alias policy; size plus mtime/ctime keep the prior content digest
    current. A mismatch invalidates the cached proof without claiming that every
    metadata transition was itself a content mutation. The bound source and
    release-directory FDs separately prove pathname and release-root identity;
    directory timestamps and child-entry churn are intentionally not compared.
    """
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
        metadata.st_nlink,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


def _read_pending_regular_source_payload(
    file_fd: int,
    source: Path,
    size: int,
) -> bytes:
    payload = bytearray()
    remaining = size
    try:
        while remaining:
            chunk = os.read(file_fd, min(1024 * 1024, remaining))
            if not chunk:
                raise SyncError(
                    f"pending regular-file source ended early while reading: {source}"
                )
            payload.extend(chunk)
            remaining -= len(chunk)
    except OSError as error:
        raise SyncError(
            f"pending regular-file source is unreadable: {source}: {error}"
        ) from error
    return bytes(payload)


def _require_pending_regular_source_receipt(
    file_fd: int,
    source: Path,
    expected: tuple[int, int, int, int, int, int, int, int, int],
) -> None:
    try:
        actual = _pending_regular_source_receipt(os.fstat(file_fd))
    except OSError as error:
        raise SyncError(
            "pending regular-file source evidence receipt cannot be revalidated: "
            f"{source}: {error}"
        ) from error
    if actual != expected:
        raise SyncError(
            f"pending regular-file source evidence receipt no longer matches: {source}"
        )


def _require_pending_regular_cached_source_evidence(
    home: Path,
    source: Path,
    parent_fd: int,
    file_fd: int,
    metadata: os.stat_result,
    evidence: _PendingRegularSourceEvidence,
) -> None:
    _require_pending_regular_source_receipt(
        file_fd,
        source,
        evidence.source_receipt,
    )
    _require_bounded_regular_file_unchanged(
        source,
        parent_fd,
        file_fd,
        metadata,
        "pending regular-file source evidence",
    )
    _require_managed_regular_parent_chain_access(
        home,
        source.parent,
        bound_parent_fd=parent_fd,
    )
    _require_pending_regular_source_receipt(
        file_fd,
        source,
        evidence.source_receipt,
    )


def _capture_pending_regular_release_receipt(
    release_fd: int,
    release_root: Path,
    expectation: PendingReleaseExpectation,
) -> _PendingRegularReleaseReceipt:
    expected_owner_uid = _effective_release_identity_owner_uid(None)
    with _release_identity_owner_uid_scope(expected_owner_uid):
        (
            manifest_payload,
            tree_digest,
            path_kinds,
            source_snapshots,
            source_members,
            _captured_files,
        ) = _release_tree_snapshot_from_directory_fd(
            release_fd,
            release_root,
            require_sanitized_modes=True,
            expected_owner_uid=expected_owner_uid,
            capture_limits={},
        )
    manifest_data = _decode_manifest_payload(
        manifest_payload,
        release_root / MANIFEST_RELATIVE_PATH,
    )
    manifest = _parse_manifest_data(manifest_data, path_kinds.get)
    if manifest.owner != expectation.owner or tree_digest != expectation.tree_sha256:
        raise SyncError(
            "pending regular-file source release tree changed: "
            f"{expectation.owner}@{expectation.sha}"
        )
    _verify_release_source_snapshot(
        release_fd,
        release_root,
        source_snapshots,
        source_members,
        operation="pending regular-file source evidence validation",
        expected_owner_uid=expected_owner_uid,
    )
    return _PendingRegularReleaseReceipt(
        source_snapshots=source_snapshots,
        source_members=source_members,
        expected_owner_uid=expected_owner_uid,
    )


def _require_pending_regular_release_receipt(
    release_fd: int,
    release_root: Path,
    receipt: _PendingRegularReleaseReceipt,
) -> None:
    _verify_release_source_snapshot(
        release_fd,
        release_root,
        receipt.source_snapshots,
        receipt.source_members,
        operation="pending regular-file source evidence cache revalidation",
        expected_owner_uid=receipt.expected_owner_uid,
    )


@dataclass
class _PendingRegularSourceEvidenceBudget:
    evidence_by_source: dict[
        tuple[str, str, PurePosixPath, tuple[int, int], str],
        _PendingRegularSourceEvidence,
    ] = dataclass_field(default_factory=dict)
    release_receipt_by_authority: dict[
        tuple[str, str, tuple[int, int], str],
        _PendingRegularReleaseReceipt,
    ] = dataclass_field(default_factory=dict)
    evidence_read_bytes: int = 0
    sealed: bool = False

    def evidence(
        self,
        home: Path,
        record: ManagedLinkRecord,
        expectation: PendingReleaseExpectation,
    ) -> _PendingRegularSourceEvidence:
        if self.sealed:
            raise SyncError("pending regular-file source evidence budget is sealed")
        if expectation.owner != record.owner or expectation.sha != record.release_sha:
            raise SyncError(
                "pending regular-file source release binding changed: "
                f"{record.owner}@{record.release_sha}:{record.source}"
            )
        source = _record_regular_source_path(home, record)
        release_root = _releases_root(home, expectation.owner) / expectation.sha
        cache_key = (
            record.owner,
            record.release_sha,
            record.source,
            expectation.directory_identity,
            expectation.tree_sha256,
        )
        release_cache_key = (
            expectation.owner,
            expectation.sha,
            expectation.directory_identity,
            expectation.tree_sha256,
        )
        release_receipt = self.release_receipt_by_authority.get(release_cache_key)
        release_fd = _open_installed_release_directory_fd(
            home,
            expectation.owner,
            expectation.sha,
        )
        parent_fd = -1
        file_fd = -1
        try:
            if _directory_identity(release_fd) != expectation.directory_identity:
                raise SyncError(
                    "pending regular-file source release directory changed: "
                    f"{expectation.owner}@{expectation.sha}"
                )
            parent_fd, file_fd, metadata = _open_bounded_regular_file(
                source,
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                description="pending regular-file source evidence",
            )
            cached = self.evidence_by_source.get(cache_key)
            if cached is not None:
                if release_receipt is not cached.release_receipt:
                    raise SyncError(
                        "pending regular-file source evidence cache is incomplete"
                    )
                _require_pending_regular_cached_source_evidence(
                    home,
                    source,
                    parent_fd,
                    file_fd,
                    metadata,
                    cached,
                )
                if _directory_identity(
                    release_fd
                ) != expectation.directory_identity or not _bound_directory_matches(
                    home, release_root, release_fd
                ):
                    raise SyncError(
                        "pending regular-file source release directory changed: "
                        f"{expectation.owner}@{expectation.sha}"
                    )
                return cached

            size = metadata.st_size
            if (
                size
                > MAX_PENDING_REGULAR_EVIDENCE_READ_BYTES - self.evidence_read_bytes
            ):
                raise SyncError(
                    "pending regular-file source evidence reads exceed the aggregate "
                    f"size limit: {source}"
                )
            payload = _read_pending_regular_source_payload(file_fd, source, size)
            _require_bounded_regular_file_unchanged(
                source,
                parent_fd,
                file_fd,
                metadata,
                "pending regular-file source evidence",
            )
            if release_receipt is None:
                release_receipt = _capture_pending_regular_release_receipt(
                    release_fd,
                    release_root,
                    expectation,
                )
            _require_bounded_regular_file_unchanged(
                source,
                parent_fd,
                file_fd,
                metadata,
                "pending regular-file source evidence",
            )
            _require_managed_regular_parent_chain_access(
                home,
                source.parent,
                bound_parent_fd=parent_fd,
            )
            source_receipt = _pending_regular_source_receipt(metadata)
            _require_pending_regular_source_receipt(
                file_fd,
                source,
                source_receipt,
            )
            if _directory_identity(
                release_fd
            ) != expectation.directory_identity or not _bound_directory_matches(
                home, release_root, release_fd
            ):
                raise SyncError(
                    "pending regular-file source release directory changed: "
                    f"{expectation.owner}@{expectation.sha}"
                )
        finally:
            _close_fd_quietly(file_fd)
            _close_fd_quietly(parent_fd)
            _close_fd_quietly(release_fd)
        if release_receipt is None:
            raise SyncError("pending regular-file source evidence cache is incomplete")
        evidence = _PendingRegularSourceEvidence(
            sha256=hashlib.sha256(payload).hexdigest(),
            size=len(payload),
            source_receipt=source_receipt,
            release_receipt=release_receipt,
        )
        self.evidence_read_bytes += len(payload)
        self.release_receipt_by_authority.setdefault(
            release_cache_key,
            release_receipt,
        )
        self.evidence_by_source[cache_key] = evidence
        return evidence

    def finalize(self, home: Path) -> None:
        if self.sealed:
            raise SyncError("pending regular-file source evidence budget is sealed")
        try:
            for (
                owner,
                sha,
                source_relative,
                directory_identity,
                tree_sha256,
            ), evidence in self.evidence_by_source.items():
                release_cache_key = (
                    owner,
                    sha,
                    directory_identity,
                    tree_sha256,
                )
                if (
                    self.release_receipt_by_authority.get(release_cache_key)
                    is not evidence.release_receipt
                ):
                    raise SyncError(
                        "pending regular-file source evidence cache is incomplete"
                    )
                release_root = _releases_root(home, owner) / sha
                source = release_root / Path(*source_relative.parts)
                release_fd = _open_installed_release_directory_fd(home, owner, sha)
                parent_fd = -1
                file_fd = -1
                try:
                    if _directory_identity(release_fd) != directory_identity:
                        raise SyncError(
                            "pending regular-file source release directory changed: "
                            f"{owner}@{sha}"
                        )
                    parent_fd, file_fd, metadata = _open_bounded_regular_file(
                        source,
                        maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                        description="pending regular-file source evidence",
                    )
                    _require_pending_regular_cached_source_evidence(
                        home,
                        source,
                        parent_fd,
                        file_fd,
                        metadata,
                        evidence,
                    )
                    if _directory_identity(
                        release_fd
                    ) != directory_identity or not _bound_directory_matches(
                        home, release_root, release_fd
                    ):
                        raise SyncError(
                            "pending regular-file source release directory changed: "
                            f"{owner}@{sha}"
                        )
                finally:
                    _close_fd_quietly(file_fd)
                    _close_fd_quietly(parent_fd)
                    _close_fd_quietly(release_fd)
            for (
                owner,
                sha,
                directory_identity,
                _tree_sha256,
            ), receipt in self.release_receipt_by_authority.items():
                release_root = _releases_root(home, owner) / sha
                release_fd = _open_installed_release_directory_fd(home, owner, sha)
                try:
                    if _directory_identity(
                        release_fd
                    ) != directory_identity or not _bound_directory_matches(
                        home, release_root, release_fd
                    ):
                        raise SyncError(
                            "pending regular-file source release directory changed: "
                            f"{owner}@{sha}"
                        )
                    _require_pending_regular_release_receipt(
                        release_fd,
                        release_root,
                        receipt,
                    )
                    if _directory_identity(
                        release_fd
                    ) != directory_identity or not _bound_directory_matches(
                        home, release_root, release_fd
                    ):
                        raise SyncError(
                            "pending regular-file source release directory changed: "
                            f"{owner}@{sha}"
                        )
                finally:
                    _close_fd_quietly(release_fd)
        finally:
            self.sealed = True


def _pending_regular_to_symlink_transition_is_authorized(
    home: Path,
    record: PendingLinkRecord,
    state_before: ManagedState,
    state_after: ManagedState,
    before_expectations_by_owner: dict[str, PendingReleaseExpectation],
    after_expectations_by_owner: dict[str, PendingReleaseExpectation],
    removal_authority_by_release: dict[tuple[str, str], dict[str, RemovedLink]],
    regular_source_evidence: _PendingRegularSourceEvidenceBudget,
) -> bool:
    if (
        record.scope != "managed"
        or record.action != "quarantine-replace"
        or record.before_materialization != "regular"
        or record.materialization != "symlink"
        or record.kind not in {"directory", "skill"}
        or record.removed_link_key is None
        or record.link_target is None
        or any(
            value is not None
            for value in (
                record.regular_sha256,
                record.regular_size,
                record.regular_mode,
                record.regular_uid,
                record.regular_gid,
                record.regular_link_count,
            )
        )
    ):
        return False
    before_record = state_before.links.get(record.target)
    after_record = state_after.links.get(record.target)
    planned = _regular_snapshot_from_reconcile(record.planned_snapshot)
    if (
        before_record is None
        or after_record is None
        or planned is None
        or not _record_materializes_regular_file(before_record)
        or _record_materializes_regular_file(after_record)
        or after_record.kind != record.kind
        or after_record.source != record.source
        or after_record.owner != record.owner
        or after_record.release_sha != record.release_sha
        or after_record.link_target != record.link_target
        or planned.mode != 0o600
        or planned.uid != os.geteuid()
        or planned.link_count != 2
    ):
        return False
    removal_owner, _removed_id = record.removed_link_key.split(":", 1)
    if (
        removal_owner != before_record.owner
        or state_before.owners.get(removal_owner) != before_record.release_sha
    ):
        return False
    removal_expectation = (
        after_expectations_by_owner.get(removal_owner)
        if removal_owner in state_after.owners
        else before_expectations_by_owner.get(removal_owner)
    )
    source_expectation = before_expectations_by_owner.get(before_record.owner)
    if removal_expectation is None or source_expectation is None:
        return False
    try:
        if (
            planned.sha256
            != regular_source_evidence.evidence(
                home,
                before_record,
                source_expectation,
            ).sha256
        ):
            return False
        desired_entry = LinkEntry(
            source=after_record.source,
            target=after_record.target,
            kind=after_record.kind,
            owner=after_record.owner,
        )
        cache_key = (removal_expectation.owner, removal_expectation.sha)
        removal_by_key = removal_authority_by_release.get(cache_key)
        if removal_by_key is None:
            removal_by_key = _pending_release_removal_authority(
                home,
                removal_expectation,
            )
            removal_authority_by_release[cache_key] = removal_by_key
    except OSError as error:
        raise SyncError(
            "cannot revalidate pending regular-to-symlink removal authority: "
            f"{record.target}: {error}"
        ) from error
    removed = removal_by_key.get(record.removed_link_key)
    return (
        removed is not None
        and _removed_link_exactly_matches_managed_record(removed, before_record)
        and removed.replacement_target == desired_entry.target
    )


def _combine_entries(
    public_entries: list[LinkEntry],
    overlay_manifests: list[ManifestData],
) -> list[LinkEntry]:
    final_by_target: dict[PurePosixPath, LinkEntry] = {}
    for entry in public_entries:
        if entry.owner != PUBLIC_OWNER:
            raise SyncError(
                "public base manifest must contain only public-owned entries"
            )
        final_by_target[entry.target] = entry

    for manifest in overlay_manifests:
        if manifest.owner == PUBLIC_OWNER:
            raise SyncError("overlay manifest owner must not be public")
        for entry in manifest.entries:
            existing = final_by_target.get(entry.target)
            if existing is not None and existing.owner != PUBLIC_OWNER:
                raise SyncError(
                    f"target {_display_path(Path(*entry.target.parts))} is declared by "
                    f"multiple overlays: {existing.owner}, {entry.owner}"
                )
            if existing is not None:
                if not entry.override and entry.target not in OPTIONAL_PUBLIC_TARGETS:
                    raise SyncError(
                        f"overlay target {entry.target} must declare override=true"
                    )
            elif entry.override and entry.target not in OPTIONAL_PUBLIC_TARGETS:
                raise SyncError(
                    f"override target has no public base target: {entry.target}"
                )
            final_by_target[entry.target] = entry
    final_entries = list(final_by_target.values())
    _validate_non_overlapping_targets([entry.target for entry in final_entries])
    return final_entries


def _combine_removed_links(manifests: list[ManifestData]) -> list[RemovedLink]:
    removed_links: list[RemovedLink] = []
    keys: set[str] = set()
    for manifest in manifests:
        for removed in manifest.removed_links:
            key = _removed_link_key(removed)
            if key in keys:
                raise SyncError(f"duplicate removed link key: {key}")
            keys.add(key)
            removed_links.append(removed)
    return removed_links


def _validate_replacement_retirement_graph(
    graph: dict[str, tuple[str, ...]],
) -> None:
    try:
        TopologicalSorter(graph).prepare()
    except CycleError as error:
        cycle_keys = error.args[1] if len(error.args) > 1 else ()
        cycle = " -> ".join(str(key) for key in cycle_keys)
        detail = f": {cycle}" if cycle else ""
        raise SyncError(f"replacement retirement cycle detected{detail}") from None


def _validate_active_replacements(
    _home: Path,
    _current_manifests: dict[str, ManifestData],
    next_manifests: dict[str, ManifestData],
    desired_entries: list[LinkEntry],
) -> None:
    desired_targets = _entries_by_target(desired_entries)
    all_removed = [
        removed
        for manifest in next_manifests.values()
        for removed in manifest.removed_links
    ]
    removed_by_key = {_removed_link_key(removed): removed for removed in all_removed}
    for retirement in all_removed:
        retirement_key = _removed_link_key(retirement)
        for retired_key in retirement.retires_replacements:
            if retired_key == retirement_key:
                raise SyncError(
                    f"removed link {retirement_key} must not retire its own replacement"
                )
            retired = removed_by_key.get(retired_key)
            if retired is None:
                retired_owner, _retired_id = retired_key.split(":", 1)
                if retired_owner not in next_manifests:
                    continue
                raise SyncError(
                    f"removed link {_removed_link_key(retirement)} retires unknown "
                    f"replacement {retired_key}"
                )
            if retired.replacement_target != retirement.target:
                raise SyncError(
                    f"removed link {_removed_link_key(retirement)} target "
                    f"{retirement.target} does not match replacement for {retired_key}"
                )
    retirement_graph = {
        key: tuple(
            retired_key
            for retired_key in removed.retires_replacements
            if retired_key in removed_by_key
        )
        for key, removed in removed_by_key.items()
    }
    _validate_replacement_retirement_graph(retirement_graph)
    for owner, manifest in next_manifests.items():
        for removed in manifest.removed_links:
            replacement = removed.replacement_target
            if replacement is None:
                continue
            replacement_has_removal_history = any(
                _removed_link_key(removed) in candidate.retires_replacements
                for candidate in all_removed
            )
            if (
                replacement not in desired_targets
                and not replacement_has_removal_history
            ):
                raise SyncError(
                    f"replacement target {replacement} is unavailable for active removal "
                    f"{owner}:{removed.id}"
                )


def _required_replacements_for_removals(
    home: Path,
    actions: list[ReconcileAction],
    removed_links: list[RemovedLink],
    desired_entries: list[LinkEntry],
) -> dict[Path, list[LinkEntry]]:
    destructive_actions: dict[PurePosixPath, list[ReconcileAction]] = {}
    for action in actions:
        if action.action not in {
            "replace",
            "quarantine-replace",
            "remove",
            "quarantine-remove",
        }:
            continue
        try:
            relative_target = action.target.relative_to(home)
        except ValueError as error:
            raise SyncError(
                f"managed target is outside home: {action.target}"
            ) from error
        destructive_actions.setdefault(
            PurePosixPath(*relative_target.parts),
            [],
        ).append(action)

    desired_by_target = _entries_by_target(desired_entries)
    retired_keys = {
        retired_key
        for retirement in removed_links
        for retired_key in retirement.retires_replacements
    }
    required: dict[Path, dict[PurePosixPath, LinkEntry]] = {}
    for removed in removed_links:
        removed_key = _removed_link_key(removed)
        replacement = removed.replacement_target
        if replacement is None or removed_key in retired_keys:
            continue
        matching_actions = [
            action
            for action in destructive_actions.get(removed.target, [])
            if action.expected_link_target == _removed_link_target(home, removed)
        ]
        if not matching_actions:
            continue
        replacement_entry = desired_by_target.get(replacement)
        if replacement_entry is None:
            raise SyncError(
                f"replacement target {replacement} is unavailable for active removal "
                f"{removed_key}"
            )
        for action in matching_actions:
            required.setdefault(action.target, {})[replacement] = replacement_entry
    return {
        action_target: [
            entries[target] for target in sorted(entries, key=PurePosixPath.as_posix)
        ]
        for action_target, entries in required.items()
    }


def _plan_reconciliation(
    home: Path,
    desired_entries: list[LinkEntry],
    previous_entries: list[LinkEntry],
    removed_links: list[RemovedLink],
    state: ManagedState,
    *,
    allow_cross_owner: bool,
    allow_unledgered_removed_links: bool = False,
    owner_shas: dict[str, str] | None = None,
    incoming_regular_sources: dict[tuple[str, PurePosixPath], Path] | None = None,
) -> list[ReconcileAction]:
    regular_budget = _RegularPlanningSourceBudget()
    desired_by_target = _entries_by_target(desired_entries)
    previous_targets: dict[PurePosixPath, set[str]] = {}
    previous_regular_entries: dict[PurePosixPath, list[LinkEntry]] = {}
    for entry in previous_entries:
        previous_targets.setdefault(entry.target, set()).add(
            _desired_link_target(home, entry)
        )
        if _entry_materializes_regular_file(entry):
            previous_regular_entries.setdefault(entry.target, []).append(entry)
    removed_by_target: dict[PurePosixPath, list[RemovedLink]] = {}
    for removed in removed_links:
        removed_by_target.setdefault(removed.target, []).append(removed)

    candidate_targets = set(desired_by_target)
    candidate_targets.update(state.links)
    candidate_targets.update(previous_targets)
    if allow_unledgered_removed_links:
        candidate_targets.update(removed_by_target)
    actions: list[ReconcileAction] = []

    for relative_target in sorted(candidate_targets, key=PurePosixPath.as_posix):
        target = home / Path(*relative_target.parts)
        desired_entry = desired_by_target.get(relative_target)
        if desired_entry is None and any(
            ancestor in desired_by_target for ancestor in relative_target.parents
        ):
            continue
        _ensure_safe_target_parent(home, target)
        record = state.links.get(relative_target)
        require_managed_parent_access = bool(
            (
                desired_entry is not None
                and _entry_materializes_regular_file(desired_entry)
            )
            or (record is not None and _record_materializes_regular_file(record))
            or previous_regular_entries.get(relative_target)
        )
        capture_regular_content = not (
            record is not None
            and not _record_materializes_regular_file(record)
            and _allows_optional_claim_relinquishment(
                relative_target,
                desired_entry,
            )
        )
        planned_snapshot = (
            _capture_reconcile_target_snapshot(
                home,
                target,
                capture_regular_content=capture_regular_content,
                require_managed_parent_access=require_managed_parent_access,
            )
            if home.is_dir() and not home.is_symlink()
            else None
        )
        removed_candidates = (
            removed_by_target.get(relative_target, [])
            if allow_unledgered_removed_links
            else []
        )
        if (
            record is not None
            and planned_snapshot is not None
            and planned_snapshot.link_identity is not None
            and (
                not _record_materializes_regular_file(record)
                or planned_snapshot.regular_sha256 is None
            )
            and planned_snapshot.link_target != record.link_target
        ):
            if _allows_optional_claim_relinquishment(
                relative_target,
                desired_entry,
            ):
                actions.append(
                    ReconcileAction(
                        PENDING_RELINQUISH_FOREIGN_ACTION,
                        target,
                        "",
                        record.kind,
                        planned_snapshot=planned_snapshot,
                    )
                )
                continue
            raise SyncError(
                "managed state/link target mismatch for "
                f"{relative_target}: state={record.link_target}, "
                f"current={planned_snapshot.link_target}"
            )
        if desired_entry is not None:
            desired = _desired_link_target(home, desired_entry)
            regular_source = (
                (incoming_regular_sources or {}).get(
                    (desired_entry.owner, desired_entry.target)
                )
                or _entry_regular_source_path(home, desired_entry, owner_shas)
                if _entry_materializes_regular_file(desired_entry)
                else None
            )
            materialization = "regular" if regular_source is not None else "symlink"
            obvious_regular_create = regular_source is not None and (
                planned_snapshot is None or planned_snapshot.link_identity is None
            )
            if obvious_regular_create:
                desired_regular_size = regular_budget.reserve_materialization(
                    regular_source,
                    target,
                )
            else:
                desired_regular_size = (
                    regular_budget.source_size(regular_source)
                    if regular_source is not None
                    else None
                )
            desired_regular_sha256 = (
                regular_budget.digest(home, regular_source)
                if regular_source is not None
                else None
            )
            if planned_snapshot is None or planned_snapshot.link_identity is None:
                actions.append(
                    ReconcileAction(
                        "create",
                        target,
                        desired,
                        desired_entry.kind,
                        planned_snapshot=planned_snapshot,
                        materialization=materialization,
                        regular_source=regular_source,
                        regular_size=desired_regular_size,
                    )
                )
                continue
            planned_regular = _regular_snapshot_from_reconcile(planned_snapshot)
            legacy_managed_symlink_to_regular = (
                regular_source is not None
                and planned_snapshot.link_target is not None
                and record is not None
                and planned_snapshot.link_target == record.link_target
            )
            if (
                record is not None
                and _record_materializes_regular_file(record)
                and planned_regular is None
                and not legacy_managed_symlink_to_regular
            ):
                raise SyncError(
                    f"managed state target type mismatch for regular file: {target}"
                )
            if regular_source is not None and planned_regular is not None:
                if record is None:
                    raise SyncError(
                        f"refusing to adopt unproven regular-file target: {target}"
                    )
                if not _record_materializes_regular_file(record):
                    raise SyncError(
                        f"managed state target type mismatch for regular file: {target}"
                    )
                if not _regular_snapshot_has_managed_access(planned_regular):
                    raise SyncError(
                        f"managed regular file access policy mismatch: {target}"
                    )
                assert desired_regular_sha256 is not None
                if planned_regular.sha256 == desired_regular_sha256:
                    continue
                assert regular_source is not None
                regular_budget.reserve_materialization(regular_source, target)
                prior_source = _record_regular_source_path(home, record)
                if planned_regular.sha256 != regular_budget.digest(home, prior_source):
                    raise SyncError(
                        f"refusing to replace modified managed regular file: {target}"
                    )
                actions.append(
                    ReconcileAction(
                        "replace",
                        target,
                        desired,
                        desired_entry.kind,
                        expected_link_target=record.link_target,
                        planned_snapshot=planned_snapshot,
                        materialization="regular",
                        regular_source=regular_source,
                        regular_size=desired_regular_size,
                    )
                )
                continue
            if regular_source is None and planned_regular is not None:
                if record is None:
                    if _allows_optional_claim_relinquishment(
                        relative_target,
                        desired_entry,
                    ):
                        continue
                    raise SyncError(
                        "refusing to migrate unproven regular-file non-symlink "
                        f"target: {target}"
                    )
                if not _record_materializes_regular_file(record):
                    raise SyncError(
                        f"managed state target type mismatch for regular file: {target}"
                    )
                if not _regular_snapshot_has_managed_access(planned_regular):
                    raise SyncError(
                        f"managed regular file access policy mismatch: {target}"
                    )
                prior_source = _record_regular_source_path(home, record)
                if planned_regular.sha256 != regular_budget.digest(home, prior_source):
                    raise SyncError(
                        f"refusing to replace modified managed regular file: {target}"
                    )
                removed_match = _same_target_regular_to_symlink_removal(
                    removed_by_target.get(relative_target, []),
                    record,
                    desired_entry,
                )
                if removed_match is None:
                    raise SyncError(
                        "refusing to migrate managed regular file without an exact "
                        f"same-target removal: {target}"
                    )
                if removed_match.owner != desired_entry.owner and not allow_cross_owner:
                    raise SyncError(
                        f"cross-owner migration requires install-private: {target}"
                    )
                actions.append(
                    ReconcileAction(
                        "quarantine-replace",
                        target,
                        desired,
                        desired_entry.kind,
                        expected_link_target=record.link_target,
                        removed_link_key=_removed_link_key(removed_match),
                        planned_snapshot=planned_snapshot,
                        materialization="symlink",
                    )
                )
                continue
            if regular_source is not None and planned_snapshot.link_target is not None:
                existing = planned_snapshot.link_target
                proven = record is not None and record.link_target == existing
                if not proven:
                    existing_owner = _link_managed_owner(home, target)
                    proven = (
                        existing_owner == desired_entry.owner and existing == desired
                    )
                if not proven:
                    raise SyncError(
                        f"refusing to migrate unproven symlink target: {target}"
                    )
                regular_budget.reserve_materialization(regular_source, target)
                actions.append(
                    ReconcileAction(
                        "replace",
                        target,
                        desired,
                        desired_entry.kind,
                        expected_link_target=existing,
                        planned_snapshot=planned_snapshot,
                        materialization="regular",
                        regular_source=regular_source,
                        regular_size=desired_regular_size,
                    )
                )
                continue
            if planned_snapshot.link_target is None:
                if (
                    desired_entry.owner == PUBLIC_OWNER
                    and desired_entry.target in OPTIONAL_PUBLIC_TARGETS
                ):
                    continue
                raise SyncError(f"refusing to replace non-symlink target: {target}")
            assert planned_snapshot.link_target is not None
            existing = planned_snapshot.link_target
            if existing == desired:
                continue

            proven = record is not None and record.link_target == existing
            removed_match = next(
                (
                    removed
                    for removed in removed_candidates
                    if _removed_link_target(home, removed) == existing
                ),
                None,
            )
            if proven:
                actions.append(
                    ReconcileAction(
                        "replace",
                        target,
                        desired,
                        desired_entry.kind,
                        expected_link_target=existing,
                        planned_snapshot=planned_snapshot,
                    )
                )
                continue
            if removed_match is not None:
                if removed_match.owner != desired_entry.owner and not allow_cross_owner:
                    raise SyncError(
                        f"cross-owner migration requires install-private: {target}"
                    )
                actions.append(
                    ReconcileAction(
                        "quarantine-replace",
                        target,
                        desired,
                        desired_entry.kind,
                        expected_link_target=existing,
                        removed_link_key=_removed_link_key(removed_match),
                        planned_snapshot=planned_snapshot,
                    )
                )
                continue
            if (
                desired_entry.owner == PUBLIC_OWNER
                and desired_entry.target in OPTIONAL_PUBLIC_TARGETS
            ):
                continue
            raise SyncError(f"refusing to replace unproven symlink target: {target}")

        if planned_snapshot is None or planned_snapshot.link_identity is None:
            continue
        planned_regular = _regular_snapshot_from_reconcile(planned_snapshot)
        if planned_regular is not None:
            if record is None:
                previous_regular = previous_regular_entries.get(relative_target, [])
                if previous_regular:
                    claim_kind = (
                        "overlay"
                        if any(
                            entry.owner != PUBLIC_OWNER for entry in previous_regular
                        )
                        else "managed"
                    )
                    raise SyncError(
                        f"missing {claim_kind} regular claim for existing target: "
                        f"{target}"
                    )
                continue
            if not _record_materializes_regular_file(record):
                continue
            if not _regular_snapshot_has_managed_access(planned_regular):
                raise SyncError(
                    f"managed regular file access policy mismatch: {target}"
                )
            prior_source = _record_regular_source_path(home, record)
            if planned_regular.sha256 != regular_budget.digest(home, prior_source):
                raise SyncError(
                    f"refusing to remove modified managed regular file: {target}"
                )
            actions.append(
                ReconcileAction(
                    "remove",
                    target,
                    "",
                    record.kind,
                    expected_link_target=record.link_target,
                    planned_snapshot=planned_snapshot,
                    materialization="regular",
                )
            )
            continue
        if planned_snapshot.link_target is None:
            continue
        assert planned_snapshot.link_target is not None
        existing = planned_snapshot.link_target
        if record is not None and record.link_target == existing:
            actions.append(
                ReconcileAction(
                    "remove",
                    target,
                    "",
                    record.kind,
                    expected_link_target=existing,
                    planned_snapshot=planned_snapshot,
                )
            )
            continue
        removed_match = next(
            (
                removed
                for removed in removed_candidates
                if _removed_link_target(home, removed) == existing
            ),
            None,
        )
        if removed_match is not None:
            actions.append(
                ReconcileAction(
                    "quarantine-remove",
                    target,
                    "",
                    removed_match.kind,
                    expected_link_target=existing,
                    removed_link_key=_removed_link_key(removed_match),
                    planned_snapshot=planned_snapshot,
                )
            )
    return actions


def _snapshot_ephemeral_quarantine_metadata_fd(
    home: Path,
    batch_root: Path,
    batch_fd: int,
    metadata_fd: int,
) -> ManagedStateFileSnapshot:
    """Capture stable cleanup evidence from the allocator's retained file FD."""
    metadata_path = batch_root / "metadata.json"
    original_offset = 0
    try:
        original_offset = os.lseek(metadata_fd, 0, os.SEEK_CUR)
        before = _require_pending_cleanup_fd_access_policy(
            metadata_fd,
            metadata_path,
            expected_mode=0o600,
        )
        os.lseek(metadata_fd, 0, os.SEEK_SET)
        payload = _read_managed_state_bytes(
            metadata_fd,
            metadata_path,
            MAX_MANAGED_STATE_BYTES,
        )
        os.lseek(metadata_fd, 0, os.SEEK_SET)
        confirmed_payload = _read_managed_state_bytes(
            metadata_fd,
            metadata_path,
            MAX_MANAGED_STATE_BYTES,
        )
        after = _require_pending_cleanup_fd_access_policy(
            metadata_fd,
            metadata_path,
            expected_mode=0o600,
        )
        named = os.stat(
            "metadata.json",
            dir_fd=batch_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISREG(before.st_mode)
            or not _regular_stat_metadata_matches(after, before)
            or not _regular_stat_metadata_matches(named, before)
            or payload != confirmed_payload
            or after.st_size != len(payload)
            or not _bound_directory_matches(home, batch_root, batch_fd)
        ):
            raise SyncError(
                f"ephemeral quarantine metadata changed while binding: {batch_root}"
            )
        return ManagedStateFileSnapshot(
            exists=True,
            payload=payload,
            mode=stat.S_IMODE(after.st_mode),
            parent_identity=_directory_identity(batch_fd),
            file_identity=(after.st_dev, after.st_ino),
            file_type=stat.S_IFMT(after.st_mode),
            size=after.st_size,
            uid=after.st_uid,
            gid=after.st_gid,
        )
    except (OSError, SyncError) as error:
        raise SyncError(
            f"ephemeral quarantine metadata is unreadable while binding: {batch_root}"
        ) from error
    finally:
        try:
            os.lseek(metadata_fd, original_offset, os.SEEK_SET)
        except OSError:
            pass


def _quarantine_batch_root(
    home: Path,
    actions: list[ReconcileAction],
    *,
    retain_binding: bool = False,
    retain_scaffold_binding: bool = False,
) -> Path | tuple[Path, int, tuple[int, int]] | EphemeralQuarantineBatchAllocation:
    if retain_scaffold_binding and not retain_binding:
        raise ValueError("scaffold binding requires a retained batch binding")
    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    batch_name = f"{stamp}-{os.getpid()}-{time.time_ns()}"
    if len(batch_name.encode("utf-8")) > MAX_PENDING_LINK_BATCH_NAME_BYTES:
        raise SyncError("quarantine batch name exceeds the size limit")
    batch_root = quarantine_root / batch_name
    metadata = {
        "version": 1,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "actions": [
            {
                "action": action.action,
                "target": str(action.target),
                "link_target": action.expected_link_target,
                "replacement": action.link_target or None,
                "removed_link": action.removed_link_key,
            }
            for action in actions
        ],
    }
    metadata_payload = (json.dumps(metadata, indent=2, sort_keys=False) + "\n").encode(
        "utf-8"
    )
    quarantine_fd = _open_or_create_directory_beneath(
        home,
        quarantine_root,
        mode=0o700,
    )
    batch_fd = -1
    metadata_fd = -1
    created_batch = False
    batch_identity: tuple[int, int] | None = None
    metadata_snapshot: ManagedStateFileSnapshot | None = None
    metadata_cleanup_snapshot: ManagedStateFileSnapshot | None = None
    metadata_stage_path: Path | None = None
    metadata_stage_snapshot: ManagedStateFileSnapshot | None = None
    metadata_stage_parent_fd = -1
    quarantine_root_identity: tuple[int, int] | None = None
    allocation_ticket: PendingQuarantineAllocationTicket | None = None
    scaffold_allocation: EphemeralQuarantineBatchAllocation | None = None
    try:
        quarantine_root_identity = _directory_identity(quarantine_fd)
        if not _bound_directory_matches(home, quarantine_root, quarantine_fd):
            raise SyncError(f"quarantine root changed: {quarantine_root}")
        retained_batches = _quarantine_capacity_batch_count(home, quarantine_fd)
        if retained_batches >= MAX_RETAINED_QUARANTINE_BATCHES:
            raise SyncError(
                "quarantine retains too many transaction batches: "
                f"{retained_batches} >= {MAX_RETAINED_QUARANTINE_BATCHES}",
                code="quarantine-saturated",
            )
        if retain_scaffold_binding:
            index_root = _pending_cleanup_index_path(home)
            index_fd = _open_or_create_directory_beneath(home, index_root, mode=0o700)
            _close_fd_quietly(index_fd)
            metadata_stage_parent_fd = _open_directory_beneath(home, index_root)
            metadata_stage_path = _pending_quarantine_metadata_stage_path(
                home,
                batch_name,
            )
            metadata_flags = os.O_RDWR | os.O_CREAT | os.O_EXCL
            metadata_flags |= getattr(os, "O_CLOEXEC", 0)
            metadata_flags |= getattr(os, "O_NOFOLLOW", 0)
            metadata_fd = os.open(
                metadata_stage_path.name,
                metadata_flags,
                0o600,
                dir_fd=metadata_stage_parent_fd,
            )
            try:
                os.fchmod(metadata_fd, 0o600)
                _require_pending_cleanup_fd_access_policy(
                    metadata_fd,
                    metadata_stage_path,
                    expected_mode=0o600,
                )
                written = 0
                while written < len(metadata_payload):
                    count = os.write(metadata_fd, metadata_payload[written:])
                    if count <= 0:
                        raise OSError(
                            "quarantine metadata stage write made no progress"
                        )
                    written += count
                os.fsync(metadata_fd)
                os.fsync(metadata_stage_parent_fd)
                metadata_fd_stat = os.fstat(metadata_fd)
                metadata_stage_snapshot = _read_managed_state_file_snapshot(
                    home,
                    metadata_stage_path,
                    metadata_stage_parent_fd,
                    expected_identity=(
                        metadata_fd_stat.st_dev,
                        metadata_fd_stat.st_ino,
                    ),
                    maximum_bytes=MAX_MANAGED_STATE_BYTES,
                )
                if (
                    metadata_stage_snapshot.payload != metadata_payload
                    or metadata_stage_snapshot.mode != 0o600
                    or metadata_stage_snapshot.uid != os.geteuid()
                ):
                    raise SyncError(
                        f"quarantine metadata stage write was incomplete: {batch_root}"
                    )
            except BaseException:
                try:
                    metadata_fd_stat = os.fstat(metadata_fd)
                    metadata_stage_snapshot = _read_managed_state_file_snapshot(
                        home,
                        metadata_stage_path,
                        metadata_stage_parent_fd,
                        expected_identity=(
                            metadata_fd_stat.st_dev,
                            metadata_fd_stat.st_ino,
                        ),
                        maximum_bytes=MAX_MANAGED_STATE_BYTES,
                    )
                except (OSError, SyncError):
                    metadata_stage_snapshot = None
                raise
            allocation_ticket = _publish_pending_quarantine_allocation_ticket(
                home,
                quarantine_root,
                quarantine_fd,
                batch_name,
                metadata_payload,
            )
        os.mkdir(batch_root.name, mode=0o700, dir_fd=quarantine_fd)
        created_batch = True
        os.fsync(quarantine_fd)
        directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        directory_flags |= getattr(os, "O_CLOEXEC", 0)
        directory_flags |= getattr(os, "O_NOFOLLOW", 0)
        batch_fd = os.open(batch_root.name, directory_flags, dir_fd=quarantine_fd)
        batch_identity = _directory_identity(batch_fd)
        if retain_scaffold_binding:
            assert metadata_stage_path is not None
            assert metadata_stage_snapshot is not None
            assert allocation_ticket is not None
            current_stage = _require_pending_cleanup_file_snapshot_unchanged(
                home,
                metadata_stage_path,
                metadata_stage_parent_fd,
                metadata_stage_snapshot,
                label=f"quarantine metadata stage {batch_name}",
            )
            _require_pending_quarantine_allocation_ticket_unchanged(
                home,
                allocation_ticket,
            )
            if (
                _directory_identity(batch_fd) != batch_identity
                or not _bound_directory_matches(home, batch_root, batch_fd)
                or _directory_member_names(batch_fd, maximum_entries=1) != ()
            ):
                raise SyncError(
                    f"quarantine batch changed before metadata: {batch_root}"
                )
            _rename_noreplace_at(
                metadata_stage_parent_fd,
                metadata_stage_path.name,
                batch_fd,
                "metadata.json",
            )
            metadata_stage_path = None
            metadata_stage_snapshot = None
            os.fsync(batch_fd)
            os.fsync(metadata_stage_parent_fd)
            named_metadata = os.stat(
                "metadata.json",
                dir_fd=batch_fd,
                follow_symlinks=False,
            )
            if current_stage.file_identity != (
                named_metadata.st_dev,
                named_metadata.st_ino,
            ) or _directory_member_names(batch_fd, maximum_entries=2) != (
                "metadata.json",
            ):
                raise SyncError(
                    f"quarantine metadata changed during publication: {batch_root}"
                )
        else:
            metadata_flags = os.O_RDWR | os.O_CREAT | os.O_EXCL
            metadata_flags |= getattr(os, "O_CLOEXEC", 0)
            metadata_flags |= getattr(os, "O_NOFOLLOW", 0)
            metadata_fd = os.open(
                "metadata.json",
                metadata_flags,
                0o600,
                dir_fd=batch_fd,
            )
            os.fchmod(metadata_fd, 0o600)
            written = 0
            while written < len(metadata_payload):
                count = os.write(metadata_fd, metadata_payload[written:])
                if count <= 0:
                    raise OSError("quarantine metadata write made no progress")
                written += count
            os.fsync(metadata_fd)
        metadata_snapshot = _snapshot_ephemeral_quarantine_metadata_fd(
            home,
            batch_root,
            batch_fd,
            metadata_fd,
        )
        if metadata_snapshot.payload != metadata_payload:
            raise SyncError(f"quarantine metadata write was incomplete: {batch_root}")
        metadata_cleanup_snapshot = metadata_snapshot
        os.fsync(batch_fd)
        if not _bound_directory_matches(home, batch_root, batch_fd):
            raise SyncError(f"quarantine batch changed: {batch_root}")
        if retain_scaffold_binding:
            assert metadata_snapshot is not None
            assert allocation_ticket is not None
            current_metadata = _read_managed_state_file_snapshot(
                home,
                batch_root / "metadata.json",
                batch_fd,
                expected_identity=metadata_snapshot.file_identity,
                maximum_bytes=MAX_MANAGED_STATE_BYTES,
            )
            if not _managed_state_snapshot_matches_bound_file_evidence(
                current_metadata,
                metadata_snapshot,
            ):
                raise SyncError(
                    f"quarantine metadata changed before binding: {batch_root}"
                )
            _require_pending_quarantine_allocation_ticket_unchanged(
                home,
                allocation_ticket,
            )
            assert quarantine_root_identity is not None
            retained_quarantine_fd = os.dup(quarantine_fd)
            retained_batch_fd = -1
            retained_metadata_fd = -1
            try:
                retained_batch_fd = os.dup(batch_fd)
                retained_metadata_fd = os.dup(metadata_fd)
                scaffold_allocation = EphemeralQuarantineBatchAllocation(
                    home=home,
                    quarantine_root=quarantine_root,
                    quarantine_fd=retained_quarantine_fd,
                    batch_fd=retained_batch_fd,
                    metadata_fd=retained_metadata_fd,
                    binding=EphemeralQuarantineBatchBinding(
                        batch_root=batch_root,
                        quarantine_root_identity=quarantine_root_identity,
                        batch_identity=batch_identity,
                        leaf_identity=None,
                        metadata=metadata_snapshot,
                        allocation_ticket=allocation_ticket,
                    ),
                )
            except BaseException:
                _close_fd_quietly(retained_metadata_fd)
                _close_fd_quietly(retained_batch_fd)
                _close_fd_quietly(retained_quarantine_fd)
                raise
    except BaseException as original_error:
        if metadata_stage_path is not None:
            try:
                if metadata_stage_snapshot is None:
                    raise SyncError(
                        "quarantine metadata stage could not be rebound for cleanup: "
                        f"{batch_name}"
                    )
                _discard_incomplete_pending_cleanup_ticket(
                    home,
                    metadata_stage_path,
                    expected_snapshot=metadata_stage_snapshot,
                )
                metadata_stage_path = None
                metadata_stage_snapshot = None
            except (OSError, SyncError) as cleanup_error:
                cleanup_note = (
                    "quarantine metadata staging failed and its exact temporary "
                    f"file was retained: {cleanup_error}"
                )
                add_note = getattr(original_error, "add_note", None)
                if callable(add_note):
                    add_note(cleanup_note)
                else:
                    raise SyncError(
                        f"{cleanup_note}; original allocation failure: {original_error}"
                    ) from cleanup_error
        cleanup_binding: EphemeralQuarantineBatchBinding | None = None
        if (
            created_batch
            and batch_fd >= 0
            and quarantine_root_identity is not None
            and batch_identity is not None
            and metadata_cleanup_snapshot is not None
            and _managed_state_snapshot_has_complete_file_evidence(
                metadata_cleanup_snapshot
            )
            and metadata_cleanup_snapshot.parent_identity == batch_identity
            and metadata_cleanup_snapshot.file_type == stat.S_IFREG
            and metadata_cleanup_snapshot.mode == 0o600
            and metadata_cleanup_snapshot.uid == os.geteuid()
        ):
            cleanup_binding = EphemeralQuarantineBatchBinding(
                batch_root=batch_root,
                quarantine_root_identity=quarantine_root_identity,
                batch_identity=batch_identity,
                leaf_identity=None,
                metadata=metadata_cleanup_snapshot,
                allocation_ticket=allocation_ticket,
            )
        try:
            if scaffold_allocation is not None:
                try:
                    scaffold_allocation.reclaim_empty()
                except (OSError, SyncError) as cleanup_error:
                    cleanup_note = (
                        "quarantine allocation handoff failed and its bound empty "
                        f"scaffold was retained: {cleanup_error}"
                    )
                    add_note = getattr(original_error, "add_note", None)
                    if callable(add_note):
                        add_note(cleanup_note)
                    else:
                        raise SyncError(
                            f"{cleanup_note}; original allocation failure: "
                            f"{original_error}"
                        ) from cleanup_error
                cleanup_binding = None
            if cleanup_binding is not None:
                try:
                    # Keep the allocator's original batch and metadata
                    # descriptors live through the direct cleanup's durable
                    # ticket publication and final removal, preventing identity
                    # reuse while the cleanup helper independently rebinds.
                    _discard_empty_ephemeral_quarantine_batch(home, cleanup_binding)
                except (OSError, SyncError) as cleanup_error:
                    cleanup_note = (
                        "quarantine allocation failed and its bound empty scaffold "
                        f"was retained: {cleanup_error}"
                    )
                    add_note = getattr(original_error, "add_note", None)
                    if callable(add_note):
                        add_note(cleanup_note)
                    else:
                        raise SyncError(
                            f"{cleanup_note}; original allocation failure: "
                            f"{original_error}"
                        ) from cleanup_error
        finally:
            if metadata_fd >= 0:
                _close_fd_quietly(metadata_fd)
                metadata_fd = -1
            if batch_fd >= 0:
                _close_fd_quietly(batch_fd)
                batch_fd = -1
        raise
    finally:
        _close_fd_quietly(metadata_fd)
        _close_fd_quietly(metadata_stage_parent_fd)
        if batch_fd >= 0 and (not retain_binding or retain_scaffold_binding):
            _close_fd_quietly(batch_fd)
        _close_fd_quietly(quarantine_fd)
    if retain_binding:
        assert batch_fd >= 0
        assert batch_identity is not None
        if retain_scaffold_binding:
            assert scaffold_allocation is not None
            return scaffold_allocation
        return batch_root, batch_fd, batch_identity
    return batch_root


def _create_quarantine_batch_directory_at(
    batch_root_fd: int,
    relative_parts: tuple[str, ...],
) -> int:
    directory_fd = os.dup(batch_root_fd)
    child_flags = _directory_open_flags(nofollow=True)
    try:
        for part in relative_parts:
            created = False
            next_fd = -1
            try:
                try:
                    next_fd = os.open(part, child_flags, dir_fd=directory_fd)
                except FileNotFoundError:
                    try:
                        os.mkdir(part, mode=0o700, dir_fd=directory_fd)
                        created = True
                    except FileExistsError:
                        pass
                    next_fd = os.open(part, child_flags, dir_fd=directory_fd)
                if created:
                    os.fsync(next_fd)
                    os.fsync(directory_fd)
            except BaseException:
                if next_fd >= 0:
                    _close_fd_quietly(next_fd)
                raise
            _close_fd_quietly(directory_fd)
            directory_fd = next_fd
        return directory_fd
    except BaseException:
        _close_fd_quietly(directory_fd)
        raise


def _create_ephemeral_quarantine_leaf_at(
    allocation: EphemeralQuarantineBatchAllocation,
) -> None:
    """Exclusively create and transfer the fallback leaf to its owner.

    ``mkdir`` cannot return a directory descriptor.  Capture the new named
    directory's identity and store it in the allocation before the first fsync
    or open that can raise.  Once the descriptor exists, transfer it to the
    allocation before validating it.  Before returning, publish durable v5
    authority over the exact batch, metadata, and leaf identities.  Thus a
    crash after successful publication is recoverable without promoting a v8
    reservation into deletion authority.  A physical crash before publication
    intentionally leaves the present entity fail-closed.
    """
    batch_fd = allocation.batch_fd
    if _directory_member_names(batch_fd, maximum_entries=2) != ("metadata.json",):
        raise SyncError("ephemeral quarantine batch changed before leaf creation")
    os.mkdir("leaf", mode=0o700, dir_fd=batch_fd)
    leaf_stat = os.stat("leaf", dir_fd=batch_fd, follow_symlinks=False)
    if not stat.S_ISDIR(leaf_stat.st_mode):
        raise SyncError("ephemeral quarantine leaf changed during creation")
    leaf_identity = (leaf_stat.st_dev, leaf_stat.st_ino)
    allocation.binding = replace(allocation.binding, leaf_identity=leaf_identity)
    os.fsync(batch_fd)
    leaf_fd = os.open(
        "leaf",
        _directory_open_flags(nofollow=True),
        dir_fd=batch_fd,
    )
    # Transfer descriptor ownership before validation/fsync.  The allocation's
    # error path, rather than this helper, then has the complete v5 authority.
    allocation.leaf_fd = leaf_fd
    if (
        _directory_identity(leaf_fd) != leaf_identity
        or _named_entry_identity(batch_fd, "leaf") != leaf_identity
        or _directory_member_names(batch_fd, maximum_entries=3)
        != ("leaf", "metadata.json")
    ):
        raise SyncError("ephemeral quarantine leaf changed during creation")
    os.fsync(leaf_fd)
    os.fsync(batch_fd)
    cleanup_ticket = _publish_pending_ephemeral_quarantine_cleanup_ticket(
        allocation.home,
        allocation.binding,
    )
    allocation.binding = replace(
        allocation.binding,
        cleanup_ticket=cleanup_ticket,
    )
    _require_ephemeral_quarantine_private_boundary(allocation)
    _require_pending_cleanup_ticket_unchanged(allocation.home, cleanup_ticket)


def _snapshot_payload_digest(snapshot: ManagedStateFileSnapshot) -> str | None:
    if not snapshot.exists:
        return None
    assert snapshot.payload is not None
    return hashlib.sha256(snapshot.payload).hexdigest()


def _identity_payload(identity: tuple[int, int] | None) -> list[int] | None:
    return list(identity) if identity is not None else None


def _planned_snapshot_payload(snapshot: ReconcileTargetSnapshot) -> dict[str, Any]:
    return {
        "parent_identity": _identity_payload(snapshot.parent_identity),
        "link_identity": _identity_payload(snapshot.link_identity),
        "link_target": snapshot.link_target,
        "ancestor_identity": _identity_payload(snapshot.ancestor_identity),
        "missing_parent_parts": list(snapshot.missing_parent_parts),
        "regular_sha256": snapshot.regular_sha256,
        "regular_size": snapshot.regular_size,
        "regular_mode": snapshot.regular_mode,
        "regular_uid": snapshot.regular_uid,
        "regular_gid": snapshot.regular_gid,
        "regular_link_count": snapshot.regular_link_count,
    }


def _state_evidence_payload(
    snapshot: ManagedStateFileSnapshot,
    evidence: PurePosixPath | None,
) -> dict[str, Any]:
    return {
        "exists": snapshot.exists,
        "mode": snapshot.mode if snapshot.exists else None,
        "sha256": _snapshot_payload_digest(snapshot),
        "identity": _identity_payload(snapshot.file_identity),
        "uid": snapshot.uid if snapshot.exists else None,
        "gid": snapshot.gid if snapshot.exists else None,
        "evidence": evidence.as_posix() if evidence is not None else None,
    }


def _pending_claim_payload(claim: PendingLinkClaim) -> dict[str, Any]:
    return {
        "index": claim.index,
        "scope": claim.scope,
        "target": claim.target.as_posix(),
        "kind": claim.kind,
        "source": claim.source.as_posix() if claim.source is not None else None,
        "owner": claim.owner,
        "link_target": claim.link_target,
        "release_sha": claim.release_sha,
        "parent_identity": _identity_payload(claim.parent_identity),
        "link_identity": _identity_payload(claim.link_identity),
        "evidence": claim.evidence.as_posix(),
    }


def _pending_release_payload(
    expectation: PendingReleaseExpectation,
) -> dict[str, Any]:
    return {
        "owner": expectation.owner,
        "sha": expectation.sha,
        "directory_identity": _identity_payload(expectation.directory_identity),
        "tree_sha256": expectation.tree_sha256,
    }


def _pending_regular_target_expectation_payload(
    expectation: PendingRegularTargetExpectation,
) -> dict[str, Any]:
    return {
        "target": expectation.target.as_posix(),
        "parent_identity": _identity_payload(expectation.parent_identity),
        "file_identity": _identity_payload(expectation.file_identity),
        "sha256": expectation.sha256,
        "size": expectation.size,
        "mode": expectation.mode,
        "uid": expectation.uid,
    }


def _terminal_regular_state_items(
    state: ManagedState,
    records: tuple[PendingLinkRecord, ...],
    *,
    phase: str,
) -> tuple[tuple[PurePosixPath, ManagedLinkRecord, PendingLinkRecord | None], ...]:
    if phase not in {"before", "after"}:
        raise SyncError("pending terminal regular phase is invalid")
    records_by_target = {
        record.target: record for record in records if record.scope == "managed"
    }
    items: list[tuple[PurePosixPath, ManagedLinkRecord, PendingLinkRecord | None]] = []
    for target, state_record in sorted(
        state.links.items(),
        key=lambda item: item[0].as_posix(),
    ):
        if not _record_materializes_regular_file(state_record):
            continue
        pending_record = records_by_target.get(target)
        if phase == "before" and pending_record is not None:
            if (
                pending_record.action
                not in {
                    "replace",
                    "quarantine-replace",
                    "remove",
                    "quarantine-remove",
                }
                or _regular_snapshot_from_reconcile(pending_record.planned_snapshot)
                is None
            ):
                continue
        items.append((target, state_record, pending_record))
    return tuple(items)


def _require_pending_terminal_regular_group_size_budget(
    sizes: tuple[int | None, ...],
    *,
    phase: str,
) -> None:
    total = 0
    for size in sizes:
        if not isinstance(size, int) or isinstance(size, bool) or size < 0:
            raise SyncError(
                f"pending terminal regular {phase} group has incomplete size evidence"
            )
        if size > MAX_PENDING_REGULAR_MATERIALIZATION_BYTES - total:
            raise SyncError(
                f"pending terminal regular {phase} group exceeds the aggregate "
                "size limit"
            )
        total += size


def _stable_regular_source_size_evidence(source: Path) -> int:
    parent_fd, file_fd, metadata = _open_bounded_regular_file(
        source,
        maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        description="managed regular-file source",
    )
    try:
        _require_bounded_regular_file_unchanged(
            source,
            parent_fd,
            file_fd,
            metadata,
            "managed regular-file source",
        )
        return metadata.st_size
    finally:
        _close_fd_quietly(file_fd)
        _close_fd_quietly(parent_fd)


def _stable_managed_regular_target_size_evidence(
    home: Path,
    target: Path,
) -> int:
    parent_fd = _open_directory_beneath(home, target.parent)
    file_fd = -1
    try:
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed regular-file parent changed: {target.parent}")
        try:
            named = os.stat(
                target.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except OSError as error:
            raise SyncError(
                f"managed regular file is unreadable: {target}: {error}"
            ) from error
        if not stat.S_ISREG(named.st_mode):
            raise SyncError(f"managed target is not a regular file: {target}")
        if named.st_size > MAX_ARCHIVE_MEMBER_BYTES:
            raise SyncError(
                f"managed regular file exceeds {MAX_ARCHIVE_MEMBER_BYTES} bytes: "
                f"{target}"
            )
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        flags |= getattr(os, "O_NONBLOCK", 0)
        try:
            file_fd = os.open(target.name, flags, dir_fd=parent_fd)
        except OSError as error:
            raise SyncError(
                f"managed regular file is unreadable: {target}: {error}"
            ) from error
        opened = os.fstat(file_fd)
        rebound = os.stat(
            target.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            not _regular_stat_metadata_matches(opened, named)
            or not _regular_stat_metadata_matches(rebound, named)
            or not _bound_directory_matches(home, target.parent, parent_fd)
        ):
            raise SyncError(f"managed regular file changed before read: {target}")
        if (
            stat.S_IMODE(opened.st_mode) != 0o600
            or opened.st_uid != os.geteuid()
            or opened.st_nlink != 1
        ):
            raise SyncError(
                "managed regular file access policy mismatch: "
                f"{target} (mode={stat.S_IMODE(opened.st_mode):o}, "
                f"uid={opened.st_uid}, links={opened.st_nlink})"
            )
        return opened.st_size
    finally:
        _close_fd_quietly(file_fd)
        _close_fd_quietly(parent_fd)


def _pending_terminal_regular_group_size_evidence(
    home: Path,
    state_items: tuple[
        tuple[PurePosixPath, ManagedLinkRecord, PendingLinkRecord | None], ...
    ],
    *,
    phase: str,
) -> tuple[int | None, ...]:
    sizes: list[int | None] = []
    for target, state_record, pending_record in state_items:
        if (
            phase == "after"
            and pending_record is not None
            and pending_record.action in {"create", "replace", "quarantine-replace"}
        ):
            size = pending_record.regular_size
        elif (
            phase == "before"
            and pending_record is not None
            and pending_record.action
            in {"replace", "quarantine-replace", "remove", "quarantine-remove"}
        ):
            planned = _regular_snapshot_from_reconcile(pending_record.planned_snapshot)
            size = planned.size if planned is not None else None
        else:
            source_size = _stable_regular_source_size_evidence(
                _record_regular_source_path(home, state_record)
            )
            target_size = _stable_managed_regular_target_size_evidence(
                home,
                home / Path(*target.parts),
            )
            if target_size != source_size:
                raise SyncError(
                    f"pending terminal regular target size changed: {target}"
                )
            size = source_size
        sizes.append(size)
    return tuple(sizes)


def _stage_pending_terminal_regular_targets(
    home: Path,
    state: ManagedState,
    records: tuple[PendingLinkRecord, ...],
    *,
    phase: str,
) -> tuple[PendingRegularTargetExpectation, ...]:
    state_items = _terminal_regular_state_items(
        state,
        records,
        phase=phase,
    )
    _require_pending_terminal_regular_group_size_budget(
        _pending_terminal_regular_group_size_evidence(
            home,
            state_items,
            phase=phase,
        ),
        phase=phase,
    )
    expectations: list[PendingRegularTargetExpectation] = []
    for target, state_record, pending_record in state_items:
        snapshot: RegularFileSnapshot | None = None
        if (
            phase == "after"
            and pending_record is not None
            and pending_record.action in {"create", "replace", "quarantine-replace"}
        ):
            parent_identity = pending_record.planned_snapshot.parent_identity
            file_identity = pending_record.evidence_identity
            digest = pending_record.regular_sha256
            size = pending_record.regular_size
            mode = pending_record.regular_mode
            uid = pending_record.regular_uid
        elif (
            phase == "before"
            and pending_record is not None
            and pending_record.action
            in {"replace", "quarantine-replace", "remove", "quarantine-remove"}
        ):
            snapshot = _regular_snapshot_from_reconcile(pending_record.planned_snapshot)
            if snapshot is None:
                raise SyncError(
                    f"pending terminal regular preimage is missing: {target}"
                )
            parent_identity = snapshot.parent_identity
            file_identity = snapshot.file_identity
            digest = snapshot.sha256
            size = snapshot.size
            mode = snapshot.mode
            uid = snapshot.uid
        else:
            snapshot = _read_regular_file_snapshot_beneath(
                home,
                home / Path(*target.parts),
                require_managed_access=True,
            )
            expected_digest = _regular_source_sha256(
                home,
                _record_regular_source_path(home, state_record),
            )
            if snapshot.sha256 != expected_digest:
                raise SyncError(
                    f"pending terminal regular target content changed: {target}"
                )
            parent_identity = snapshot.parent_identity
            file_identity = snapshot.file_identity
            digest = snapshot.sha256
            size = snapshot.size
            mode = snapshot.mode
            uid = snapshot.uid
        if (
            parent_identity is None
            or file_identity is None
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
            or not isinstance(size, int)
            or isinstance(size, bool)
            or size < 0
            or mode != 0o600
            or uid != os.geteuid()
        ):
            raise SyncError(f"pending terminal regular target is incomplete: {target}")
        expectations.append(
            PendingRegularTargetExpectation(
                target=target,
                parent_identity=parent_identity,
                file_identity=file_identity,
                sha256=digest,
                size=size,
                mode=mode,
                uid=uid,
            )
        )
    return tuple(expectations)


def _pending_commit_evidence_payload(
    batch_root: Path,
    state_after: ManagedStateFileSnapshot,
) -> bytes:
    if (
        state_after.parent_identity is None
        or state_after.file_identity is None
        or state_after.payload is None
    ):
        raise SyncError("pending state-after evidence is not fully bound")
    payload = {
        "version": 1,
        "batch": batch_root.name,
        "state_parent_identity": _identity_payload(state_after.parent_identity),
        "state_after_identity": _identity_payload(state_after.file_identity),
        "state_after_sha256": hashlib.sha256(state_after.payload).hexdigest(),
    }
    return (json.dumps(payload, indent=2, sort_keys=False) + "\n").encode("utf-8")


def _pending_rollback_marker_payload(batch: PendingLinkBatch) -> bytes:
    state_before = batch.state_before
    if state_before.parent_identity is None:
        raise SyncError("pending state-before parent is not fully bound")
    payload = {
        "version": 1,
        "batch": batch.batch_root.name,
        "phase": "before",
        "state_parent_identity": _identity_payload(state_before.parent_identity),
        "state_before_exists": state_before.exists,
        "state_before_identity": _identity_payload(state_before.file_identity),
        "state_before_sha256": _snapshot_payload_digest(state_before),
    }
    return _bounded_json_document(
        payload,
        max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        overflow_error="pending rollback marker exceeds the size limit",
    )


def _bounded_json_document(
    payload: object,
    *,
    max_bytes: int,
    overflow_error: str,
) -> bytes:
    encoded = bytearray()
    encoder = json.JSONEncoder(indent=2, sort_keys=False)
    try:
        for chunk in encoder.iterencode(payload):
            raw_chunk = chunk.encode("utf-8")
            if len(encoded) + len(raw_chunk) + 1 > max_bytes:
                raise SyncError(overflow_error)
            encoded.extend(raw_chunk)
    except (TypeError, ValueError, RecursionError, UnicodeEncodeError) as error:
        raise SyncError(f"failed to encode bounded JSON document: {error}") from error
    if len(encoded) + 1 > max_bytes:
        raise SyncError(overflow_error)
    encoded.extend(b"\n")
    return bytes(encoded)


def _pending_link_metadata_payload(
    batch_root: Path,
    records: tuple[PendingLinkRecord, ...],
    claims_before: tuple[PendingLinkClaim, ...],
    claims_after: tuple[PendingLinkClaim, ...],
    state_before: ManagedStateFileSnapshot,
    state_after: ManagedStateFileSnapshot,
    state_before_evidence: PurePosixPath | None,
    state_after_evidence: PurePosixPath,
    releases_before: tuple[PendingReleaseExpectation, ...],
    releases_after: tuple[PendingReleaseExpectation, ...],
    terminal_regular_before: tuple[PendingRegularTargetExpectation, ...],
    terminal_regular_after: tuple[PendingRegularTargetExpectation, ...],
    commit_evidence: ManagedStateFileSnapshot,
) -> bytes:
    payload = {
        "version": PENDING_LINK_METADATA_VERSION,
        "batch": batch_root.name,
        "state_parent_identity": _identity_payload(state_before.parent_identity),
        "state_before": _state_evidence_payload(
            state_before,
            state_before_evidence,
        ),
        "state_after": _state_evidence_payload(state_after, state_after_evidence),
        "releases_before": [
            _pending_release_payload(expectation) for expectation in releases_before
        ],
        "releases_after": [
            _pending_release_payload(expectation) for expectation in releases_after
        ],
        "terminal_regular_before": [
            _pending_regular_target_expectation_payload(expectation)
            for expectation in terminal_regular_before
        ],
        "terminal_regular_after": [
            _pending_regular_target_expectation_payload(expectation)
            for expectation in terminal_regular_after
        ],
        "commit_evidence": _state_evidence_payload(
            commit_evidence,
            PENDING_STATE_COMMIT_EVIDENCE,
        ),
        "commit_marker": PENDING_STATE_COMMIT_MARKER.as_posix(),
        "claims_before": [_pending_claim_payload(claim) for claim in claims_before],
        "claims_after": [_pending_claim_payload(claim) for claim in claims_after],
        "records": [
            {
                "index": record.index,
                "scope": record.scope,
                "action": record.action,
                "target": record.target.as_posix(),
                "kind": record.kind,
                "planned_before": _planned_snapshot_payload(record.planned_snapshot),
                "source": record.source.as_posix()
                if record.source is not None
                else None,
                "owner": record.owner,
                "link_target": record.link_target,
                "release_sha": record.release_sha,
                "before_materialization": record.before_materialization,
                "materialization": record.materialization,
                "removed_link": record.removed_link_key,
                "regular_sha256": record.regular_sha256,
                "regular_size": record.regular_size,
                "regular_mode": record.regular_mode,
                "regular_uid": record.regular_uid,
                "regular_gid": record.regular_gid,
                "regular_link_count": record.regular_link_count,
                "before_evidence": (
                    record.before_evidence.as_posix()
                    if record.before_evidence is not None
                    else None
                ),
                "before_evidence_identity": _identity_payload(
                    record.before_evidence_identity
                ),
                "backup": record.backup.as_posix()
                if record.backup is not None
                else None,
                "stage": record.stage.as_posix() if record.stage is not None else None,
                "stage_identity": _identity_payload(record.stage_identity),
                "evidence": (
                    record.evidence.as_posix() if record.evidence is not None else None
                ),
                "evidence_identity": _identity_payload(record.evidence_identity),
                "publication_cleanup": (
                    record.publication_cleanup.as_posix()
                    if record.publication_cleanup is not None
                    else None
                ),
            }
            for record in records
        ],
    }
    return _bounded_json_document(
        payload,
        max_bytes=MAX_MANAGED_STATE_BYTES,
        overflow_error="pending link transaction metadata exceeds the size limit",
    )


def _write_exclusive_internal_file(
    home: Path,
    path: Path,
    payload: bytes,
) -> ManagedStateFileSnapshot:
    parent_fd = _open_directory_beneath(home, path.parent)
    file_fd = -1
    parent_identity: tuple[int, int] | None = None
    created_identity: tuple[int, int, int] | None = None
    try:
        parent_identity = _directory_identity(parent_fd)
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        flags |= getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        file_fd = os.open(path.name, flags, 0o600, dir_fd=parent_fd)
        created = os.fstat(file_fd)
        created_identity = _exclusive_internal_object_identity(created)
        if created_identity[2] != stat.S_IFREG:
            raise SyncError(f"exclusive internal authority is not regular: {path}")
        os.fchmod(file_fd, 0o600)
        _require_pending_cleanup_fd_access_policy(
            file_fd,
            path,
            expected_mode=0o600,
        )
        with os.fdopen(file_fd, "wb", closefd=False) as file:
            file.write(payload)
            file.flush()
            os.fsync(file.fileno())
            _require_pending_cleanup_fd_access_policy(
                file.fileno(),
                path,
                expected_mode=0o600,
            )
        os.fsync(parent_fd)
        return _read_managed_state_file_snapshot(home, path, parent_fd)
    except BaseException as original_error:
        if (
            file_fd >= 0
            and parent_identity is not None
            and created_identity is not None
        ):
            try:
                _cleanup_created_exclusive_internal_file(
                    home,
                    path,
                    parent_fd,
                    file_fd,
                    parent_identity,
                    created_identity,
                    label="exclusive internal authority",
                )
            except (OSError, SyncError) as cleanup_error:
                cleanup_note = (
                    "exclusive internal authority creation failed and its "
                    "final name could not be safely cleared: "
                    f"{cleanup_error}"
                )
                add_note = getattr(original_error, "add_note", None)
                if callable(add_note):
                    add_note(cleanup_note)
                else:
                    raise SyncError(
                        f"{cleanup_note}; original creation failure: {original_error}"
                    ) from cleanup_error
        raise
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)
        _close_fd_quietly(parent_fd)


def _publish_atomic_exclusive_internal_file(
    home: Path,
    path: Path,
    payload: bytes,
) -> ManagedStateFileSnapshot:
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        existing = _read_managed_state_file_snapshot(
            home,
            path,
            parent_fd,
        )
        if existing.exists:
            if (
                existing.file_type != stat.S_IFREG
                or existing.mode != 0o600
                or existing.uid != os.geteuid()
                or existing.payload != payload
                or not _managed_state_snapshot_has_complete_file_evidence(existing)
            ):
                raise SyncError(
                    f"atomic internal authority is incomplete or changed: {path}"
                )
            os.fsync(parent_fd)
            return existing
    finally:
        _close_fd_quietly(parent_fd)

    temp_path = path.with_name(path.name + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX)
    _discard_incomplete_pending_cleanup_ticket(home, temp_path)
    if _pending_cleanup_temp_residue_is_observed(home, temp_path):
        raise SyncError(
            f"atomic internal authority temp backlog was retained: {temp_path}"
        )
    try:
        staged = _write_exclusive_internal_file(home, temp_path, payload)
    except _PendingCleanupAccessPolicyError as error:
        raise SyncError(
            f"atomic internal authority appeared with changed content: {path}"
        ) from error
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        current_temp = _read_managed_state_file_snapshot(
            home,
            temp_path,
            parent_fd,
            expected_identity=staged.file_identity,
        )
        if (
            not _managed_state_snapshot_matches_bound_file_evidence(
                current_temp,
                staged,
            )
            or current_temp.payload != payload
        ):
            raise SyncError(f"atomic internal authority temp changed: {temp_path}")
        try:
            _rename_noreplace_at(
                parent_fd,
                temp_path.name,
                parent_fd,
                path.name,
            )
        except FileExistsError:
            existing = _read_managed_state_file_snapshot(home, path, parent_fd)
            if (
                not existing.exists
                or existing.file_type != stat.S_IFREG
                or existing.mode != 0o600
                or existing.uid != os.geteuid()
                or existing.payload != payload
            ):
                raise SyncError(
                    f"atomic internal authority appeared with changed content: {path}"
                )
            current_temp = _read_managed_state_file_snapshot(
                home,
                temp_path,
                parent_fd,
                expected_identity=staged.file_identity,
            )
            if not _managed_state_snapshot_matches_bound_file_evidence(
                current_temp,
                staged,
            ):
                raise SyncError(
                    f"atomic internal authority temp changed after race: {temp_path}"
                )
            _isolate_and_delete_pending_cleanup_file(
                home,
                temp_path,
                parent_fd,
                staged,
                label="atomic internal authority temp",
            )
            os.fsync(parent_fd)
            return existing
        os.fsync(parent_fd)
        published = _read_managed_state_file_snapshot(
            home,
            path,
            parent_fd,
            expected_identity=staged.file_identity,
        )
        if (
            published.payload != payload
            or published.mode != 0o600
            or published.uid != os.geteuid()
        ):
            raise SyncError(
                f"atomic internal authority changed during publication: {path}"
            )
        return published
    finally:
        _close_fd_quietly(parent_fd)


def _publish_regular_hardlink_beneath(
    home: Path,
    source: Path,
    destination: Path,
    expected_source: ManagedStateFileSnapshot,
    *,
    maximum_bytes: int | None = None,
) -> ManagedStateFileSnapshot:
    if maximum_bytes is None:
        pending_parent = destination.parent
        maximum_bytes = (
            MAX_ARCHIVE_MEMBER_BYTES
            if pending_parent.name in {"before", "evidence"}
            and pending_parent.parent.name == "pending"
            else MAX_MANAGED_STATE_BYTES
        )
    if not expected_source.exists or expected_source.file_identity is None:
        raise SyncError(f"regular-file evidence has no source identity: {source}")
    source_parent_fd = _open_directory_beneath(home, source.parent)
    destination_parent_fd = _open_directory_beneath(home, destination.parent)
    published = False
    try:
        try:
            source_snapshot = _read_managed_state_file_snapshot(
                home,
                source,
                source_parent_fd,
                expected_identity=expected_source.file_identity,
                maximum_bytes=maximum_bytes,
            )
        except (OSError, SyncError) as error:
            raise SyncError(
                f"regular-file evidence source changed: {source}: {error}",
                code=PENDING_REGULAR_PUBLICATION_RETAINED_CODE,
            ) from error
        if not _managed_state_snapshot_matches_bound_file_evidence(
            source_snapshot,
            expected_source,
        ):
            raise SyncError(
                f"regular-file evidence source changed: {source}",
                code=PENDING_REGULAR_PUBLICATION_RETAINED_CODE,
            )
        try:
            os.link(
                source.name,
                destination.name,
                src_dir_fd=source_parent_fd,
                dst_dir_fd=destination_parent_fd,
                follow_symlinks=False,
            )
        except OSError as error:
            raise SyncError(
                "regular-file evidence namespace changed before publication; "
                f"the batch was retained without deletion: {destination}",
                code=PENDING_REGULAR_PUBLICATION_RETAINED_CODE,
            ) from error
        published = True
        rebound_source = _read_managed_state_file_snapshot(
            home,
            source,
            source_parent_fd,
            expected_identity=expected_source.file_identity,
            maximum_bytes=maximum_bytes,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            rebound_source,
            expected_source,
        ):
            raise SyncError(
                "regular-file evidence source changed after publication; the "
                "source and destination leaves were retained without deletion: "
                f"{source}, {destination}",
                code=PENDING_REGULAR_PUBLICATION_RETAINED_CODE,
            )
        destination_snapshot = _read_managed_state_file_snapshot(
            home,
            destination,
            destination_parent_fd,
            expected_identity=expected_source.file_identity,
            maximum_bytes=maximum_bytes,
        )
        if not _managed_state_snapshot_matches_file_evidence(
            destination_snapshot,
            expected_source,
        ):
            raise SyncError(
                f"regular-file evidence changed: {destination}",
                code=PENDING_REGULAR_PUBLICATION_RETAINED_CODE,
            )
        os.fsync(destination_parent_fd)
        if not _bound_directory_matches(
            home, source.parent, source_parent_fd
        ) or not _bound_directory_matches(
            home,
            destination.parent,
            destination_parent_fd,
        ):
            raise SyncError(f"regular-file evidence parent changed: {destination}")
        return destination_snapshot
    except BaseException as error:
        if published:
            if (
                isinstance(error, SyncError)
                and error.code == PENDING_REGULAR_PUBLICATION_RETAINED_CODE
            ):
                raise
            # Once link(2) succeeds, the destination may already be the last
            # exact alias. A pathname revalidation of source cannot authorize a
            # later destination unlink because source can be replaced between
            # those operations. Retain every post-publication destination;
            # batch recovery can classify it without risking evidence loss.
            raise SyncError(
                "regular-file evidence publication failed after link creation; "
                "the destination leaf was retained without deletion: "
                f"{destination}",
                code=PENDING_REGULAR_PUBLICATION_RETAINED_CODE,
            ) from error
        raise
    finally:
        _close_fd_quietly(destination_parent_fd)
        _close_fd_quietly(source_parent_fd)


def _publish_regular_reconcile_hardlink_beneath(
    home: Path,
    source: Path,
    target: Path,
    source_snapshot: RegularFileSnapshot,
    expected_target_snapshot: ReconcileTargetSnapshot,
    created_parent_identities: dict[Path, tuple[int, int]],
    *,
    pending_batch: PendingLinkBatch | None = None,
    pending_record: PendingLinkRecord | None = None,
    cleanup_phase: str = "produced",
) -> RegularFileSnapshot:
    source_parent_fd = _open_directory_beneath(home, source.parent)
    try:
        target_parent_fd = _open_reconcile_parent_for_create(
            home,
            target,
            expected_target_snapshot,
            created_parent_identities,
            require_managed_parent_access=True,
        )
    except BaseException:
        _close_fd_quietly(source_parent_fd)
        raise
    published = False
    published_snapshot: RegularFileSnapshot | None = None
    expected_publication: RegularFileSnapshot | None = None
    try:
        actual_source = _regular_file_snapshot_at(
            source_parent_fd,
            source.name,
            source,
        )
        if not _regular_snapshot_matches(
            actual_source,
            source_snapshot.parent_identity,
            source_snapshot,
            expected_link_count=source_snapshot.link_count,
        ) or not _bound_directory_matches(home, source.parent, source_parent_fd):
            raise SyncError(f"pending regular-file stage changed: {source}")
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=target_parent_fd,
        )
        os.link(
            source.name,
            target.name,
            src_dir_fd=source_parent_fd,
            dst_dir_fd=target_parent_fd,
            follow_symlinks=False,
        )
        published = True
        expected_publication = RegularFileSnapshot(
            parent_identity=_directory_identity(target_parent_fd),
            file_identity=source_snapshot.file_identity,
            sha256=source_snapshot.sha256,
            size=source_snapshot.size,
            mode=source_snapshot.mode,
            uid=source_snapshot.uid,
            gid=source_snapshot.gid,
            link_count=source_snapshot.link_count + 1,
        )
        published_snapshot = _regular_file_snapshot_at(
            target_parent_fd,
            target.name,
            target,
            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        )
        if not _regular_snapshot_leaf_matches(
            published_snapshot,
            source_snapshot,
        ) or (published_snapshot.link_count != source_snapshot.link_count + 1):
            raise SyncError(f"published managed regular file changed: {target}")
        os.fsync(target_parent_fd)
        rebound_source = _regular_file_snapshot_at(
            source_parent_fd,
            source.name,
            source,
            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        )
        if (
            not _regular_snapshot_leaf_matches(
                rebound_source,
                source_snapshot,
            )
            or rebound_source.link_count != source_snapshot.link_count + 1
        ):
            raise SyncError(f"pending regular-file stage changed: {source}")
        if not _bound_directory_matches(home, source.parent, source_parent_fd):
            raise SyncError(f"managed regular-file parent changed: {target}")
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=target_parent_fd,
        )
        return published_snapshot
    except BaseException as error:
        if published:
            assert expected_publication is not None
            try:
                if pending_batch is None or pending_record is None:
                    _delete_exact_regular_publication_beneath(
                        home,
                        target,
                        expected_publication,
                    )
                else:
                    _delete_pending_regular_publication_beneath(
                        home,
                        pending_batch,
                        pending_record,
                        target,
                        expected_publication,
                        phase=cleanup_phase,
                    )
            except BaseException as cleanup_error:
                raise SyncError(
                    "managed regular-file publication failed and exact cleanup "
                    f"could not be verified: {target}: {cleanup_error}",
                    code=PENDING_REGULAR_PUBLICATION_RETAINED_CODE,
                ) from error
        raise
    finally:
        _close_fd_quietly(target_parent_fd)
        _close_fd_quietly(source_parent_fd)


def _delete_exact_regular_publication_beneath(
    home: Path,
    target: Path,
    expected: RegularFileSnapshot,
    *,
    pending_batch: PendingLinkBatch | None = None,
    pending_record: PendingLinkRecord | None = None,
    cleanup_phase: str | None = None,
) -> None:
    if pending_batch is None:
        _delete_exact_regular_publication_without_pending_receipt(
            home,
            target,
            expected,
        )
        return
    if pending_record is None or cleanup_phase is None:
        raise SyncError("pending regular publication cleanup authority is incomplete")
    parent_fd = _open_directory_beneath(home, target.parent)
    try:
        planned = (
            expected.file_identity[0],
            expected.file_identity[1],
            stat.S_IFREG,
        )
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=parent_fd,
        )
        active_name, isolated = _isolate_pending_cleanup_entry(
            parent_fd,
            target.name,
            expected.parent_identity,
            planned,
        )
        try:
            isolated_snapshot = _regular_file_snapshot_at(
                parent_fd,
                active_name,
                target.with_name(active_name),
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
        except BaseException:
            _retain_pending_cleanup_entry(
                parent_fd,
                active_name,
                expected.parent_identity,
                planned,
                label=(
                    "published regular-file destination became unreadable after "
                    f"isolation: {target}"
                ),
            )
        if (
            not _regular_snapshot_matches(
                isolated_snapshot,
                expected.parent_identity,
                expected,
                expected_link_count=expected.link_count,
            )
            or _pending_cleanup_entry_plan(isolated) != planned
        ):
            _retain_pending_cleanup_entry(
                parent_fd,
                active_name,
                expected.parent_identity,
                planned,
                label=(
                    "published regular-file destination changed during cleanup; "
                    f"the isolated replacement was retained: {target}"
                ),
            )
        _isolate_and_delete_pending_regular_publication_candidate(
            home,
            pending_batch,
            pending_record,
            cleanup_phase,
            target.parent,
            parent_fd,
            active_name,
            expected,
            expected_link_count=expected.link_count,
            label="published regular-file destination",
        )
        if _named_entry_identity(parent_fd, active_name) is not None:
            raise SyncError(f"published regular-file cleanup name reappeared: {target}")
        if not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(f"managed target parent changed: {target.parent}")
    finally:
        _close_fd_quietly(parent_fd)


def _pending_ephemeral_public_alias_name(batch_name: str) -> str:
    return f".codex-publication-cleanup-{batch_name}"


def _pending_ephemeral_public_alias_names(batch_name: str) -> tuple[str, ...]:
    primary = _pending_ephemeral_public_alias_name(batch_name)
    return (primary,) + tuple(f"{primary}-retained-{index}" for index in range(8))


def _pending_ephemeral_quarantine_leaf_name(batch_name: str) -> str:
    return f".codex-ephemeral-cleanup-{batch_name}"


def _pending_ephemeral_quarantine_evidence_names(
    batch_name: str,
) -> tuple[str, ...]:
    primary = _pending_ephemeral_quarantine_leaf_name(batch_name)
    return (primary,) + tuple(f"{primary}-retained-{index}" for index in range(8))


def _pending_ephemeral_quarantine_retained_private_name(batch_name: str) -> str:
    """Return a collision-resistant private evidence name for foreign data."""
    primary = _pending_ephemeral_quarantine_leaf_name(batch_name)
    return f"{primary}-retained-{os.urandom(16).hex()}"


def _pending_ephemeral_quarantine_final_private_name(private_name: str) -> str:
    return f"{private_name}.delete-{os.urandom(16).hex()}"


def _pending_ephemeral_quarantine_final_private_base(
    batch_name: str,
    name: str,
) -> str | None:
    for private_name in _pending_ephemeral_quarantine_evidence_names(batch_name):
        prefix = f"{private_name}.delete-"
        if not name.startswith(prefix):
            continue
        token = name[len(prefix) :]
        if len(token) == 32 and re.fullmatch(r"[0-9a-f]{32}", token) is not None:
            return private_name
    return None


def _pending_ephemeral_quarantine_private_name_is_related(
    batch_name: str,
    name: str,
) -> bool:
    """Recognize the v6 private namespace without granting deletion authority.

    Exact evidence slots and exact tombstones are authorized elsewhere. Their
    malformed or suffixed descendants remain related evidence, while unrelated
    quarantine-root child churn remains outside this batch's inventory.
    """
    primary = _pending_ephemeral_quarantine_leaf_name(batch_name)
    return (
        name == primary
        or name.startswith(f"{primary}-retained-")
        or name.startswith(f"{primary}.delete-")
    )


def _pending_ephemeral_quarantine_private_inventory(
    quarantine_fd: int,
    batch_name: str,
) -> tuple[tuple[str, tuple[int, int]], ...]:
    names = _directory_member_names(
        quarantine_fd,
        maximum_entries=MAX_PENDING_CLEANUP_BATCH_SCAN,
        overflow_message="ephemeral quarantine evidence scan exceeds the limit",
    )
    private: list[tuple[str, tuple[int, int]]] = []
    for name in names:
        if not _pending_ephemeral_quarantine_private_name_is_related(
            batch_name,
            name,
        ):
            continue
        identity = _named_entry_identity(quarantine_fd, name)
        if identity is not None:
            private.append((name, identity))
    return tuple(private)


def _require_pending_ephemeral_terminal_names_absent(
    home: Path,
    target: Path,
    public_parent_fd: int,
    public_parent_identity: tuple[int, int],
    quarantine_root: Path,
    quarantine_fd: int,
    quarantine_root_identity: tuple[int, int],
    batch_name: str,
) -> None:
    """Reprove the exact parent policy and derived-name absence boundary.

    The protected directory property is identity plus owner-only access policy;
    ordinary child-entry churn is allowed.  Every public alias, deterministic
    private evidence name, and high-entropy final-private tombstone derived from
    this batch must remain absent before its terminal receipt can disappear.
    """
    _require_managed_regular_parent_chain_access(
        home,
        target.parent,
        bound_parent_fd=public_parent_fd,
    )
    if _directory_identity(
        public_parent_fd
    ) != public_parent_identity or not _bound_directory_matches(
        home,
        target.parent,
        public_parent_fd,
    ):
        raise SyncError(
            f"pending ephemeral cleanup public parent changed: {target.parent}"
        )
    _require_pending_cleanup_fd_access_policy(
        quarantine_fd,
        quarantine_root,
        expected_mode=0o700,
    )
    if _directory_identity(
        quarantine_fd
    ) != quarantine_root_identity or not _bound_directory_matches(
        home,
        quarantine_root,
        quarantine_fd,
    ):
        raise SyncError("pending cleanup quarantine root changed")
    public_names = (target.name,) + _pending_ephemeral_public_alias_names(batch_name)
    if any(
        _named_entry_identity(public_parent_fd, name) is not None
        for name in public_names
    ):
        raise SyncError(
            "pending ephemeral cleanup public entry was retained in place: "
            f"{batch_name}"
        )
    if _pending_ephemeral_quarantine_private_inventory(quarantine_fd, batch_name):
        raise SyncError(
            f"pending ephemeral cleanup private evidence was retained: {batch_name}"
        )
    _require_managed_regular_parent_chain_access(
        home,
        target.parent,
        bound_parent_fd=public_parent_fd,
    )
    _require_pending_cleanup_fd_access_policy(
        quarantine_fd,
        quarantine_root,
        expected_mode=0o700,
    )
    if (
        _directory_identity(public_parent_fd) != public_parent_identity
        or not _bound_directory_matches(home, target.parent, public_parent_fd)
        or _directory_identity(quarantine_fd) != quarantine_root_identity
        or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
    ):
        raise SyncError("pending ephemeral cleanup parent changed during name audit")


def _require_pending_ephemeral_ticket_representations_absent(
    home: Path,
    index_root: Path,
    index_fd: int,
    batch_name: str,
) -> None:
    """Reject every recoverable representation of one cleanup ticket."""
    _require_pending_cleanup_fd_access_policy(
        index_fd,
        index_root,
        expected_mode=0o700,
    )
    if not _bound_directory_matches(home, index_root, index_fd):
        raise SyncError("pending ephemeral cleanup index changed")
    names = _directory_member_names(
        index_fd,
        maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
        overflow_message="pending cleanup control scan exceeds the size limit",
    )
    for name in names:
        if _pending_cleanup_ticket_representation_batch_name(name) == batch_name:
            raise SyncError(
                "pending ephemeral cleanup ticket representation remained before "
                f"terminal receipt deletion: {batch_name}: {name}"
            )
    _require_pending_cleanup_fd_access_policy(
        index_fd,
        index_root,
        expected_mode=0o700,
    )
    if not _bound_directory_matches(home, index_root, index_fd):
        raise SyncError("pending ephemeral cleanup index changed")


def _new_pending_ephemeral_cleanup_batch_name() -> str:
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    batch_name = f"{stamp}-{os.getpid()}-{time.time_ns()}"
    if len(batch_name.encode("utf-8")) > MAX_PENDING_LINK_BATCH_NAME_BYTES:
        raise SyncError("ephemeral cleanup batch name exceeds the size limit")
    return batch_name


def _publish_pending_ephemeral_quarantine_leaf_cleanup_ticket(
    home: Path,
    target: Path,
    expected: RegularFileSnapshot,
) -> PendingBatchCleanupTicket:
    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    quarantine_fd = _open_or_create_directory_beneath(
        home,
        quarantine_root,
        mode=0o700,
    )
    try:
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        if not _bound_directory_matches(home, quarantine_root, quarantine_fd):
            raise SyncError(f"ephemeral quarantine root changed: {quarantine_root}")
        quarantine_root_identity = _directory_identity(quarantine_fd)
        for _attempt in range(128):
            batch_name = _new_pending_ephemeral_cleanup_batch_name()
            alias_names = _pending_ephemeral_public_alias_names(batch_name)
            evidence_names = _pending_ephemeral_quarantine_evidence_names(batch_name)
            if any(
                _named_entry_identity(quarantine_fd, name) is not None
                for name in evidence_names
            ):
                continue
            ticket_path = _pending_cleanup_ticket_path(home, batch_name)
            temp_path = ticket_path.with_name(ticket_path.name + ".tmp")
            if ticket_path.exists() or temp_path.exists():
                continue
            break
        else:
            raise SyncError("could not allocate an ephemeral cleanup ticket name")
    finally:
        _close_fd_quietly(quarantine_fd)

    parent_fd = _open_directory_beneath(home, target.parent)
    try:
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=parent_fd,
        )
        if _directory_identity(
            parent_fd
        ) != expected.parent_identity or not _bound_directory_matches(
            home, target.parent, parent_fd
        ):
            raise SyncError(f"published regular-file parent changed: {target.parent}")
        if any(
            _named_entry_identity(parent_fd, name) is not None for name in alias_names
        ):
            raise SyncError(f"published regular-file cleanup alias exists: {target}")
    finally:
        _close_fd_quietly(parent_fd)

    payload = _pending_ephemeral_quarantine_leaf_cleanup_ticket_payload(
        home,
        batch_name,
        quarantine_root_identity,
        target,
        expected,
    )
    pseudo_batch_root = quarantine_root / batch_name
    _publish_pending_batch_cleanup_ticket_for_root(
        home,
        pseudo_batch_root,
        payload,
    )
    ticket = _read_pending_cleanup_ticket(
        home,
        _pending_cleanup_ticket_path(home, batch_name),
    )
    if ticket is None or ticket.snapshot.payload != payload:
        raise SyncError(f"ephemeral cleanup ticket changed: {batch_name}")
    return ticket


def _delete_exact_regular_publication_without_pending_receipt(
    home: Path,
    target: Path,
    expected: RegularFileSnapshot,
) -> None:
    """Delete an exact publication under durable v6 cleanup authority.

    The ticket is durable before either the public canonical name or the
    private quarantine name is mutated. Recovery can therefore resume the
    exact inode through canonical, non-loadable alias, and private states.
    Foreign or replaced entries are never cleanup authority.
    """
    ticket = _publish_pending_ephemeral_quarantine_leaf_cleanup_ticket(
        home,
        target,
        expected,
    )
    if not _remove_pending_ephemeral_quarantine_leaf(home, ticket):
        raise SyncError(
            f"ephemeral quarantine leaf cleanup was not completed: "
            f"{ticket.batch_root.name}"
        )


def _publish_pending_ephemeral_quarantine_cleanup_ticket(
    home: Path,
    binding: EphemeralQuarantineBatchBinding,
) -> PendingBatchCleanupTicket:
    _require_quarantine_allocation_matches_binding(home, binding)
    if binding.leaf_identity is None:
        raise SyncError("ephemeral quarantine cleanup leaf identity is missing")
    batch_root = binding.batch_root
    quarantine_root = batch_root.parent
    leaf_path = batch_root / "leaf"
    batch_name = batch_root.name
    directory_flags = _directory_open_flags(nofollow=True)
    quarantine_fd = _open_directory_beneath(home, quarantine_root)
    batch_fd = -1
    leaf_fd = -1
    try:
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        if _directory_identity(
            quarantine_fd
        ) != binding.quarantine_root_identity or not _bound_directory_matches(
            home, quarantine_root, quarantine_fd
        ):
            raise SyncError(f"ephemeral quarantine root changed: {quarantine_root}")
        batch_fd = os.open(batch_name, directory_flags, dir_fd=quarantine_fd)
        if _directory_identity(
            batch_fd
        ) != binding.batch_identity or not _bound_directory_matches(
            home, batch_root, batch_fd
        ):
            raise SyncError(f"ephemeral quarantine batch changed: {batch_root}")
        _require_pending_cleanup_fd_access_policy(
            batch_fd,
            batch_root,
            expected_mode=0o700,
        )
        if _directory_member_names(
            batch_fd,
            maximum_entries=3,
            overflow_message="ephemeral quarantine batch has too many entries",
        ) != ("leaf", "metadata.json"):
            raise SyncError(f"ephemeral quarantine batch changed: {batch_root}")
        current_metadata = _read_managed_state_file_snapshot(
            home,
            batch_root / "metadata.json",
            batch_fd,
            expected_identity=binding.metadata.file_identity,
            maximum_bytes=MAX_MANAGED_STATE_BYTES,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            current_metadata,
            binding.metadata,
        ):
            raise SyncError(f"ephemeral quarantine metadata changed: {batch_root}")
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            batch_root / "metadata.json",
            batch_fd,
            current_metadata,
        )
        leaf_fd = os.open("leaf", directory_flags, dir_fd=batch_fd)
        if _directory_identity(
            leaf_fd
        ) != binding.leaf_identity or not _bound_directory_matches(
            home, leaf_path, leaf_fd
        ):
            raise SyncError(f"ephemeral quarantine leaf changed: {leaf_path}")
        _require_pending_cleanup_fd_access_policy(
            leaf_fd,
            leaf_path,
            expected_mode=0o700,
        )
        payload = _pending_ephemeral_quarantine_cleanup_ticket_payload(
            replace(binding, metadata=current_metadata),
            binding.quarantine_root_identity,
        )
        _publish_pending_batch_cleanup_ticket_for_root(
            home,
            batch_root,
            payload,
        )
        ticket = _read_pending_cleanup_ticket(
            home,
            _pending_cleanup_ticket_path(home, batch_name),
        )
        if ticket is None or ticket.snapshot.payload != payload:
            raise SyncError(
                f"ephemeral quarantine cleanup ticket changed: {batch_name}"
            )
        return ticket
    finally:
        _close_fd_quietly(leaf_fd)
        _close_fd_quietly(batch_fd)
        _close_fd_quietly(quarantine_fd)


def _pending_private_use_control_evidence(
    name: str,
    snapshot: ManagedStateFileSnapshot,
) -> PendingPrivateUseControlEvidence:
    if (
        not _managed_state_snapshot_has_complete_file_evidence(snapshot)
        or snapshot.payload is None
        or snapshot.file_identity is None
        or snapshot.file_type != stat.S_IFREG
        or snapshot.mode != 0o600
        or snapshot.uid != os.geteuid()
        or snapshot.gid is None
        or snapshot.size is None
    ):
        raise SyncError(f"private-use retirement control is incomplete: {name}")
    return PendingPrivateUseControlEvidence(
        name=name,
        file_identity=snapshot.file_identity,
        sha256=hashlib.sha256(snapshot.payload).hexdigest(),
        size=snapshot.size,
        mode=snapshot.mode,
        uid=snapshot.uid,
        gid=snapshot.gid,
    )


def _pending_private_use_directory_evidence(
    descriptor: int,
    path: Path,
) -> PendingPrivateUseDirectoryEvidence:
    metadata = _require_pending_cleanup_fd_access_policy(
        descriptor, path, expected_mode=0o700
    )
    return PendingPrivateUseDirectoryEvidence(
        identity=_directory_identity(descriptor),
        mode=stat.S_IMODE(metadata.st_mode),
        uid=metadata.st_uid,
        gid=metadata.st_gid,
    )


def _pending_private_use_control_matches(
    snapshot: ManagedStateFileSnapshot,
    expected: PendingPrivateUseControlEvidence,
) -> bool:
    return (
        _managed_state_snapshot_has_complete_file_evidence(snapshot)
        and snapshot.payload is not None
        and snapshot.file_type == stat.S_IFREG
        and snapshot.file_identity == expected.file_identity
        and hashlib.sha256(snapshot.payload).hexdigest() == expected.sha256
        and snapshot.size == expected.size
        and snapshot.mode == expected.mode
        and snapshot.uid == expected.uid
        and _gid_matches_regular_file_access_policy(
            snapshot.gid, expected.gid, expected.mode
        )
    )


def _pending_private_use_retirement_control_state(
    home: Path,
    receipt: PendingPrivateUseRetirementReceipt,
    *,
    receipt_member: str,
) -> tuple[PendingBatchCleanupTicket | None, PendingQuarantineAllocationTicket | None]:
    """Bind the complete same-batch control namespace at a mutation boundary."""
    index_root = _pending_cleanup_index_path(home)
    index_fd = _open_directory_beneath(home, index_root)
    try:
        _require_pending_cleanup_fd_access_policy(
            index_fd, index_root, expected_mode=0o700
        )
        if _directory_identity(
            index_fd
        ) != receipt.cleanup_index.identity or not _bound_directory_matches(
            home, index_root, index_fd
        ):
            raise SyncError("private-use retirement cleanup index changed")
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="private-use retirement control scan exceeds the limit",
        )
        batch_name = receipt.batch_root.name
        expected_receipt_canonical = batch_name + PENDING_PRIVATE_USE_RETIREMENT_SUFFIX
        expected_receipt_temp = (
            expected_receipt_canonical + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX
        )
        cleanup_representations: list[str] = []
        allocation_representations: list[str] = []
        receipt_representations: list[str] = []
        for name in names:
            related_batch = _pending_quarantine_allocation_cleanup_control_batch_name(
                name
            )
            receipt_related = _pending_private_use_retirement_representation_batch_name(
                name
            )
            if related_batch != batch_name and receipt_related != batch_name:
                continue
            retained_canonical = _pending_cleanup_retained_canonical_name(name)
            canonical = retained_canonical or name
            if canonical == receipt.cleanup_control.name:
                cleanup_representations.append(name)
            elif canonical == receipt.allocation_control.name:
                allocation_representations.append(name)
            elif canonical in {expected_receipt_canonical, expected_receipt_temp}:
                receipt_representations.append(name)
            else:
                raise SyncError(
                    "private-use retirement has competing control evidence: "
                    f"{batch_name}: {name}"
                )
        if len(cleanup_representations) > 1 or len(allocation_representations) > 1:
            raise SyncError(
                f"private-use retirement has overlapping controls: {batch_name}"
            )
        if receipt_representations != [receipt_member]:
            raise SyncError(
                f"private-use retirement receipt representation changed: {batch_name}"
            )
        current_receipt = _read_managed_state_file_snapshot(
            home,
            index_root / receipt_member,
            index_fd,
            expected_identity=receipt.snapshot.file_identity,
            maximum_bytes=MAX_PENDING_TERMINAL_CLEANUP_TICKET_BYTES,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            current_receipt, receipt.snapshot
        ):
            raise SyncError(f"private-use retirement receipt changed: {batch_name}")
        _require_pending_cleanup_file_snapshot_access_policy(
            home, index_root / receipt_member, index_fd, current_receipt
        )

        cleanup: PendingBatchCleanupTicket | None = None
        if cleanup_representations:
            cleanup_name = cleanup_representations[0]
            cleanup_snapshot = _read_managed_state_file_snapshot(
                home,
                index_root / cleanup_name,
                index_fd,
                expected_identity=receipt.cleanup_control.file_identity,
                maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
            )
            if not _pending_private_use_control_matches(
                cleanup_snapshot, receipt.cleanup_control
            ):
                raise SyncError(
                    f"private-use retirement cleanup control changed: {batch_name}"
                )
            _require_pending_cleanup_file_snapshot_access_policy(
                home, index_root / cleanup_name, index_fd, cleanup_snapshot
            )
            if cleanup_name == receipt.cleanup_control.name:
                cleanup = _read_pending_cleanup_ticket(
                    home,
                    index_root / cleanup_name,
                    expected_ticket_identity=receipt.cleanup_control.file_identity,
                )
            else:
                cleanup = _read_pending_cleanup_ticket(
                    home,
                    index_root / (batch_name + PENDING_CLEANUP_TICKET_TEMP_SUFFIX),
                    expected_ticket_identity=receipt.cleanup_control.file_identity,
                    allow_temporary=True,
                    _captured_snapshot=cleanup_snapshot,
                )
            if cleanup is None or cleanup.version != 5:
                raise SyncError(
                    f"private-use retirement cleanup authority changed: {batch_name}"
                )

        allocation: PendingQuarantineAllocationTicket | None = None
        if allocation_representations:
            allocation_name = allocation_representations[0]
            allocation_snapshot = _read_managed_state_file_snapshot(
                home,
                index_root / allocation_name,
                index_fd,
                expected_identity=receipt.allocation_control.file_identity,
                maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
            )
            if not _pending_private_use_control_matches(
                allocation_snapshot, receipt.allocation_control
            ):
                raise SyncError(
                    f"private-use retirement allocation control changed: {batch_name}"
                )
            _require_pending_cleanup_file_snapshot_access_policy(
                home, index_root / allocation_name, index_fd, allocation_snapshot
            )
            if allocation_name == receipt.allocation_control.name:
                allocation = _read_pending_quarantine_allocation_ticket(
                    home,
                    index_root / allocation_name,
                    expected_identity=receipt.allocation_control.file_identity,
                )
            else:
                # The immutable receipt binds the exact v8 bytes and inode.  A
                # retained tombstone is not promoted here because the deletion
                # helper may be between its rename and unlink boundaries.
                original = _read_pending_quarantine_allocation_ticket(
                    home,
                    index_root / receipt.allocation_control.name,
                )
                if original is not None:
                    raise SyncError(
                        f"private-use retirement allocation overlaps: {batch_name}"
                    )
                allocation = PendingQuarantineAllocationTicket(
                    path=index_root / receipt.allocation_control.name,
                    snapshot=allocation_snapshot,
                    batch_root=receipt.batch_root,
                    quarantine_root_identity=receipt.quarantine_root.identity,
                    isolated_name=receipt.isolated_name,
                    batch_mode=receipt.batch.mode,
                    metadata_sha256=receipt.metadata_sha256,
                    metadata_size=receipt.metadata_size,
                    metadata_mode=receipt.metadata_mode,
                    leaf_mode=receipt.leaf.mode,
                )
        if cleanup is not None:
            if (
                cleanup.batch_root != receipt.batch_root
                or cleanup.quarantine_root_identity != receipt.quarantine_root.identity
                or cleanup.isolated_name != receipt.isolated_name
                or cleanup.batch_root_identity != receipt.batch.identity
                or cleanup.leaf_identity != receipt.leaf.identity
                or cleanup.metadata_file_identity != receipt.metadata_file_identity
                or cleanup.metadata_sha256 != receipt.metadata_sha256
                or cleanup.metadata_mode != receipt.metadata_mode
            ):
                raise SyncError(
                    f"private-use retirement cleanup authority changed: {batch_name}"
                )
        if allocation is not None and (
            allocation.batch_root != receipt.batch_root
            or allocation.quarantine_root_identity != receipt.quarantine_root.identity
            or allocation.isolated_name != receipt.isolated_name
            or allocation.batch_mode != receipt.batch.mode
            or allocation.metadata_sha256 != receipt.metadata_sha256
            or allocation.metadata_size != receipt.metadata_size
            or allocation.metadata_mode != receipt.metadata_mode
            or allocation.leaf_mode != receipt.leaf.mode
        ):
            raise SyncError(
                f"private-use retirement allocation authority changed: {batch_name}"
            )
        _require_pending_cleanup_fd_access_policy(
            index_fd, index_root, expected_mode=0o700
        )
        if _directory_identity(
            index_fd
        ) != receipt.cleanup_index.identity or not _bound_directory_matches(
            home, index_root, index_fd
        ):
            raise SyncError("private-use retirement cleanup index changed")
        return cleanup, allocation
    finally:
        _close_fd_quietly(index_fd)


def _require_pending_private_use_retirement_boundary(
    home: Path,
    receipt: PendingPrivateUseRetirementReceipt,
    *,
    receipt_member: str,
) -> tuple[PendingBatchCleanupTicket | None, PendingQuarantineAllocationTicket | None]:
    quarantine_root = receipt.batch_root.parent
    leaf_path = receipt.batch_root / "leaf"
    directory_flags = _directory_open_flags(nofollow=True)
    quarantine_fd = _open_directory_beneath(home, quarantine_root)
    batch_fd = -1
    leaf_fd = -1
    try:
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd, quarantine_root, expected_mode=receipt.quarantine_root.mode
        )
        if (
            _directory_identity(quarantine_fd) != receipt.quarantine_root.identity
            or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
            or _named_entry_identity(quarantine_fd, receipt.canonical_name)
            != receipt.batch.identity
            or _named_entry_identity(quarantine_fd, receipt.isolated_name) is not None
        ):
            raise SyncError("private-use retirement quarantine namespace changed")
        batch_fd = os.open(
            receipt.canonical_name, directory_flags, dir_fd=quarantine_fd
        )
        _require_pending_cleanup_fd_access_policy(
            batch_fd, receipt.batch_root, expected_mode=receipt.batch.mode
        )
        if (
            _directory_identity(batch_fd) != receipt.batch.identity
            or not _bound_directory_matches(home, receipt.batch_root, batch_fd)
            or _directory_member_names(batch_fd, maximum_entries=3)
            != ("leaf", "metadata.json")
            or _named_entry_identity(batch_fd, "leaf") != receipt.leaf.identity
        ):
            raise SyncError("private-use retirement batch changed")
        metadata = _read_managed_state_file_snapshot(
            home,
            receipt.batch_root / "metadata.json",
            batch_fd,
            expected_identity=receipt.metadata_file_identity,
            maximum_bytes=MAX_MANAGED_STATE_BYTES,
        )
        if (
            not _managed_state_snapshot_has_complete_file_evidence(metadata)
            or metadata.payload is None
            or metadata.file_identity != receipt.metadata_file_identity
            or hashlib.sha256(metadata.payload).hexdigest() != receipt.metadata_sha256
            or metadata.size != receipt.metadata_size
            or metadata.mode != receipt.metadata_mode
            or metadata.uid != receipt.metadata_uid
            or not _gid_matches_regular_file_access_policy(
                metadata.gid, receipt.metadata_gid, receipt.metadata_mode
            )
        ):
            raise SyncError("private-use retirement metadata changed")
        _require_pending_cleanup_file_snapshot_access_policy(
            home, receipt.batch_root / "metadata.json", batch_fd, metadata
        )
        leaf_fd = os.open("leaf", directory_flags, dir_fd=batch_fd)
        _require_pending_cleanup_fd_access_policy(
            leaf_fd, leaf_path, expected_mode=receipt.leaf.mode
        )
        if (
            _directory_identity(leaf_fd) != receipt.leaf.identity
            or not _bound_directory_matches(home, leaf_path, leaf_fd)
            or _directory_member_names(leaf_fd, maximum_entries=2)
            != (receipt.private_member_name,)
        ):
            raise SyncError("private-use retirement leaf changed")
        private = _regular_file_snapshot_at(
            leaf_fd,
            receipt.private_member_name,
            leaf_path / receipt.private_member_name,
        )
        if not _regular_snapshot_matches(
            private,
            receipt.leaf.identity,
            receipt.private_member,
            expected_link_count=receipt.private_member.link_count,
        ):
            raise SyncError("private-use retirement private member changed")
        controls = _pending_private_use_retirement_control_state(
            home, receipt, receipt_member=receipt_member
        )
        # Repeat the complete private namespace after the index scan.  The
        # receipt is about to authorize a control mutation, so its protected
        # object identity, content stability, and access policy must still
        # hold—not merely the identities of the held directory descriptors.
        # Benign 0700 gid transitions are not identity or access-policy
        # changes, while replacement, mode/owner/ACL drift and extra members
        # remain protected properties.
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd, quarantine_root, expected_mode=receipt.quarantine_root.mode
        )
        if (
            _directory_identity(quarantine_fd) != receipt.quarantine_root.identity
            or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
            or _named_entry_identity(quarantine_fd, receipt.canonical_name)
            != receipt.batch.identity
            or _named_entry_identity(quarantine_fd, receipt.isolated_name) is not None
        ):
            raise SyncError("private-use retirement quarantine namespace changed")
        _require_pending_cleanup_fd_access_policy(
            batch_fd, receipt.batch_root, expected_mode=receipt.batch.mode
        )
        if (
            _directory_identity(batch_fd) != receipt.batch.identity
            or not _bound_directory_matches(home, receipt.batch_root, batch_fd)
            or _directory_member_names(batch_fd, maximum_entries=3)
            != ("leaf", "metadata.json")
            or _named_entry_identity(batch_fd, "leaf") != receipt.leaf.identity
        ):
            raise SyncError("private-use retirement batch changed")
        metadata_after = _read_managed_state_file_snapshot(
            home,
            receipt.batch_root / "metadata.json",
            batch_fd,
            expected_identity=receipt.metadata_file_identity,
            maximum_bytes=MAX_MANAGED_STATE_BYTES,
        )
        if (
            not _managed_state_snapshot_has_complete_file_evidence(metadata_after)
            or metadata_after.payload is None
            or metadata_after.file_identity != receipt.metadata_file_identity
            or hashlib.sha256(metadata_after.payload).hexdigest()
            != receipt.metadata_sha256
            or metadata_after.size != receipt.metadata_size
            or metadata_after.mode != receipt.metadata_mode
            or metadata_after.uid != receipt.metadata_uid
            or not _gid_matches_regular_file_access_policy(
                metadata_after.gid, receipt.metadata_gid, receipt.metadata_mode
            )
        ):
            raise SyncError("private-use retirement metadata changed")
        _require_pending_cleanup_file_snapshot_access_policy(
            home, receipt.batch_root / "metadata.json", batch_fd, metadata_after
        )
        _require_pending_cleanup_fd_access_policy(
            leaf_fd, leaf_path, expected_mode=receipt.leaf.mode
        )
        if (
            _directory_identity(leaf_fd) != receipt.leaf.identity
            or not _bound_directory_matches(home, leaf_path, leaf_fd)
            or _directory_member_names(leaf_fd, maximum_entries=2)
            != (receipt.private_member_name,)
        ):
            raise SyncError("private-use retirement leaf changed")
        private_after = _regular_file_snapshot_at(
            leaf_fd,
            receipt.private_member_name,
            leaf_path / receipt.private_member_name,
        )
        if not _regular_snapshot_matches(
            private_after,
            receipt.leaf.identity,
            receipt.private_member,
            expected_link_count=receipt.private_member.link_count,
        ):
            raise SyncError("private-use retirement private member changed")
        return controls
    finally:
        _close_fd_quietly(leaf_fd)
        _close_fd_quietly(batch_fd)
        _close_fd_quietly(quarantine_fd)


def _publish_pending_private_use_retirement_receipt(
    allocation: EphemeralQuarantineBatchAllocation,
    private_member_name: str,
    private_member: RegularFileSnapshot,
) -> PendingPrivateUseRetirementReceipt:
    """Publish control-only retirement authority from caller-captured evidence."""
    binding = allocation.binding
    cleanup_ticket = binding.cleanup_ticket
    allocation_ticket = binding.allocation_ticket
    if (
        cleanup_ticket is None
        or cleanup_ticket.version != 5
        or allocation_ticket is None
        or binding.leaf_identity is None
        or private_member.parent_identity != binding.leaf_identity
    ):
        raise SyncError("private-use retirement authority is incomplete")
    _require_ephemeral_quarantine_private_boundary(
        allocation, expected_leaf_members=(private_member_name,)
    )
    current_cleanup = _read_pending_cleanup_ticket(
        allocation.home,
        cleanup_ticket.path,
        expected_ticket_identity=cleanup_ticket.snapshot.file_identity,
    )
    current_allocation = _read_pending_quarantine_allocation_ticket(
        allocation.home,
        allocation_ticket.path,
        expected_identity=allocation_ticket.snapshot.file_identity,
    )
    if (
        current_cleanup is None
        or current_cleanup.version != 5
        or not _managed_state_snapshot_matches_bound_file_evidence(
            current_cleanup.snapshot, cleanup_ticket.snapshot
        )
        or current_allocation is None
        or not _pending_quarantine_allocation_ticket_matches(
            current_allocation, allocation_ticket
        )
        or not _cleanup_ticket_matches_quarantine_allocation(
            current_cleanup, current_allocation
        )
    ):
        raise SyncError("private-use retirement controls changed before publication")
    current_private = _regular_file_snapshot_at(
        allocation.leaf_fd,
        private_member_name,
        binding.batch_root / "leaf" / private_member_name,
    )
    if not _regular_snapshot_matches(
        current_private,
        binding.leaf_identity,
        private_member,
        expected_link_count=private_member.link_count,
    ):
        raise SyncError("private-use retirement private member changed")
    current_metadata = _read_managed_state_file_snapshot(
        allocation.home,
        binding.batch_root / "metadata.json",
        allocation.batch_fd,
        expected_identity=binding.metadata.file_identity,
        maximum_bytes=MAX_MANAGED_STATE_BYTES,
    )
    if (
        not _managed_state_snapshot_matches_bound_file_evidence(
            current_metadata, binding.metadata
        )
        or current_metadata.payload is None
        or current_metadata.file_identity is None
        or current_metadata.size is None
        or current_metadata.mode is None
        or current_metadata.uid is None
        or current_metadata.gid is None
    ):
        raise SyncError("private-use retirement metadata changed")
    index_root = _pending_cleanup_index_path(allocation.home)
    index_fd = _open_directory_beneath(allocation.home, index_root)
    try:
        cleanup_index = _pending_private_use_directory_evidence(index_fd, index_root)
        if (
            cleanup_ticket.snapshot.parent_identity != cleanup_index.identity
            or allocation_ticket.snapshot.parent_identity != cleanup_index.identity
        ):
            raise SyncError("private-use retirement cleanup index changed")
    finally:
        _close_fd_quietly(index_fd)
    prototype = PendingPrivateUseRetirementReceipt(
        path=_pending_private_use_retirement_path(
            allocation.home, binding.batch_root.name
        ),
        snapshot=ManagedStateFileSnapshot(exists=False),
        batch_root=binding.batch_root,
        canonical_name=binding.batch_root.name,
        isolated_name=_pending_cleanup_isolated_batch_name(binding.batch_root.name),
        cleanup_control=_pending_private_use_control_evidence(
            cleanup_ticket.path.name, cleanup_ticket.snapshot
        ),
        allocation_control=_pending_private_use_control_evidence(
            allocation_ticket.path.name, allocation_ticket.snapshot
        ),
        cleanup_index=cleanup_index,
        quarantine_root=_pending_private_use_directory_evidence(
            allocation.quarantine_fd, allocation.quarantine_root
        ),
        batch=_pending_private_use_directory_evidence(
            allocation.batch_fd, binding.batch_root
        ),
        leaf=_pending_private_use_directory_evidence(
            allocation.leaf_fd, binding.batch_root / "leaf"
        ),
        metadata_file_identity=current_metadata.file_identity,
        metadata_sha256=hashlib.sha256(current_metadata.payload).hexdigest(),
        metadata_size=current_metadata.size,
        metadata_mode=current_metadata.mode,
        metadata_uid=current_metadata.uid,
        metadata_gid=current_metadata.gid,
        private_member_name=private_member_name,
        # This must remain the caller's pre-publication snapshot.  The current
        # read above is only a comparison and never becomes recovery authority.
        private_member=private_member,
    )
    payload = _pending_private_use_retirement_receipt_payload(prototype)
    _require_ephemeral_quarantine_private_boundary(
        allocation, expected_leaf_members=(private_member_name,)
    )
    published = _publish_atomic_exclusive_internal_file(
        allocation.home, prototype.path, payload
    )
    receipt = _read_pending_private_use_retirement_receipt(
        allocation.home,
        prototype.path,
        expected_identity=published.file_identity,
    )
    if receipt is None or receipt.snapshot.payload != payload:
        raise SyncError("private-use retirement receipt changed during publication")
    _require_pending_private_use_retirement_boundary(
        allocation.home, receipt, receipt_member=receipt.path.name
    )
    return receipt


def _publish_pending_ephemeral_quarantine_scaffold_cleanup_ticket(
    home: Path,
    binding: EphemeralQuarantineBatchBinding,
) -> PendingBatchCleanupTicket:
    """Durably bind an allocation whose ``leaf`` member is proven absent."""
    _require_quarantine_allocation_matches_binding(home, binding)
    if binding.leaf_identity is not None:
        raise SyncError("ephemeral quarantine scaffold leaf must be absent")
    batch_root = binding.batch_root
    quarantine_root = batch_root.parent
    batch_name = batch_root.name
    directory_flags = _directory_open_flags(nofollow=True)
    quarantine_fd = _open_directory_beneath(home, quarantine_root)
    batch_fd = -1
    try:
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        if (
            _directory_identity(quarantine_fd) != binding.quarantine_root_identity
            or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
            or _named_entry_identity(quarantine_fd, batch_name)
            != binding.batch_identity
        ):
            raise SyncError(f"ephemeral quarantine root changed: {quarantine_root}")
        batch_fd = os.open(batch_name, directory_flags, dir_fd=quarantine_fd)
        _require_pending_cleanup_fd_access_policy(
            batch_fd,
            batch_root,
            expected_mode=0o700,
        )
        if (
            _directory_identity(batch_fd) != binding.batch_identity
            or not _bound_directory_matches(home, batch_root, batch_fd)
            or _directory_member_names(batch_fd, maximum_entries=2)
            != ("metadata.json",)
        ):
            raise SyncError(f"ephemeral quarantine batch changed: {batch_root}")
        current_metadata = _read_managed_state_file_snapshot(
            home,
            batch_root / "metadata.json",
            batch_fd,
            expected_identity=binding.metadata.file_identity,
            maximum_bytes=MAX_MANAGED_STATE_BYTES,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            current_metadata,
            binding.metadata,
        ):
            raise SyncError(f"ephemeral quarantine metadata changed: {batch_root}")
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            batch_root / "metadata.json",
            batch_fd,
            current_metadata,
        )
        # Repeat root/batch/path/member checks immediately before ticket
        # publication.  Root or batch replacement is a namespace change, while
        # ordinary directory timestamps are deliberately not compared.
        if (
            _directory_identity(quarantine_fd) != binding.quarantine_root_identity
            or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
            or _named_entry_identity(quarantine_fd, batch_name)
            != binding.batch_identity
            or _directory_identity(batch_fd) != binding.batch_identity
            or not _bound_directory_matches(home, batch_root, batch_fd)
            or _directory_member_names(batch_fd, maximum_entries=2)
            != ("metadata.json",)
        ):
            raise SyncError(
                f"ephemeral quarantine scaffold changed before ticket: {batch_root}"
            )
        payload = _pending_ephemeral_quarantine_scaffold_cleanup_ticket_payload(
            replace(binding, metadata=current_metadata)
        )
        _publish_pending_batch_cleanup_ticket_for_root(home, batch_root, payload)
        ticket = _read_pending_cleanup_ticket(
            home,
            _pending_cleanup_ticket_path(home, batch_name),
        )
        if ticket is None or ticket.snapshot.payload != payload:
            raise SyncError(
                f"ephemeral quarantine scaffold ticket changed: {batch_name}"
            )
        return ticket
    finally:
        _close_fd_quietly(batch_fd)
        _close_fd_quietly(quarantine_fd)


def _require_ephemeral_quarantine_private_boundary(
    allocation: EphemeralQuarantineBatchAllocation,
    *,
    expected_leaf_members: tuple[str, ...] = (),
) -> None:
    """Reprove one exact empty leaf immediately before a private rename.

    Protected properties are root/batch/leaf object identity, canonical path
    membership, metadata object and byte stability, exact member sets, and
    current-euid access policy.  Directory timestamp or link-count churn is not
    compared because it does not change any of those properties.
    """
    binding = allocation.binding
    if binding.leaf_identity is None or allocation.leaf_fd < 0:
        raise SyncError("ephemeral quarantine private leaf is not bound")
    batch_root = binding.batch_root
    quarantine_root = allocation.quarantine_root
    leaf_path = batch_root / "leaf"
    # Establish the complete namespace first.  Metadata content and every
    # access policy are then sampled last, immediately before the caller's
    # rename.  The old ordering ended on member checks, leaving a final window
    # in which already-sampled policy/content could become unsafe unnoticed.
    if (
        _directory_identity(allocation.quarantine_fd)
        != binding.quarantine_root_identity
        or not _bound_directory_matches(
            allocation.home,
            quarantine_root,
            allocation.quarantine_fd,
        )
        or _named_entry_identity(allocation.quarantine_fd, batch_root.name)
        != binding.batch_identity
        or _directory_identity(allocation.batch_fd) != binding.batch_identity
        or not _bound_directory_matches(
            allocation.home,
            batch_root,
            allocation.batch_fd,
        )
        or _directory_member_names(allocation.batch_fd, maximum_entries=3)
        != ("leaf", "metadata.json")
        or _named_entry_identity(allocation.batch_fd, "leaf") != binding.leaf_identity
        or _directory_identity(allocation.leaf_fd) != binding.leaf_identity
        or not _bound_directory_matches(
            allocation.home,
            leaf_path,
            allocation.leaf_fd,
        )
        or _directory_member_names(
            allocation.leaf_fd,
            maximum_entries=len(expected_leaf_members) + 1,
        )
        != expected_leaf_members
    ):
        raise SyncError(
            f"ephemeral quarantine namespace changed before private rename: "
            f"{batch_root}"
        )
    current_metadata = _read_managed_state_file_snapshot(
        allocation.home,
        batch_root / "metadata.json",
        allocation.batch_fd,
        expected_identity=binding.metadata.file_identity,
        maximum_bytes=MAX_MANAGED_STATE_BYTES,
    )
    if not _managed_state_snapshot_matches_bound_file_evidence(
        current_metadata,
        binding.metadata,
    ):
        raise SyncError(f"ephemeral quarantine metadata changed: {batch_root}")
    _require_pending_cleanup_file_snapshot_access_policy(
        allocation.home,
        batch_root / "metadata.json",
        allocation.batch_fd,
        current_metadata,
    )
    _require_pending_cleanup_fd_access_policy(
        allocation.quarantine_fd,
        quarantine_root,
        expected_mode=0o700,
    )
    _require_pending_cleanup_fd_access_policy(
        allocation.batch_fd,
        batch_root,
        expected_mode=0o700,
    )
    _require_pending_cleanup_fd_access_policy(
        allocation.leaf_fd,
        leaf_path,
        expected_mode=0o700,
    )


def _discard_empty_ephemeral_quarantine_batch(
    home: Path,
    binding: EphemeralQuarantineBatchBinding,
) -> None:
    """Reclaim only the exact empty scaffold allocated for fallback cleanup.

    The quarantine root, batch and leaf directory identities plus the object
    identity, content stability and access policy of ``metadata.json`` are
    bound at allocation time and independently rebound before deletion.
    Child-entry churn is not itself a mutation signal, but any extra entry
    prevents reclamation and leaves the private batch intact for inspection.
    Durable v5 (empty leaf) or v7 (leaf proven absent) authority is published
    before any destructive cleanup, so every later mutation can be resumed by
    the ordinary pending-cleanup scanner. This is deliberately not an orphan
    sweep: no batch without an exact ticket or this in-process binding is
    eligible for removal.
    """
    batch_root = binding.batch_root
    leaf_path = batch_root / "leaf"
    quarantine_root = batch_root.parent
    batch_name = batch_root.name
    if _pending_cleanup_batch_name_from_quarantine_entry(batch_name) != batch_name:
        raise SyncError(f"ephemeral quarantine batch name is invalid: {batch_root}")
    _require_quarantine_allocation_matches_binding(home, binding)
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_CLOEXEC", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    quarantine_fd = _open_directory_beneath(home, quarantine_root)
    batch_fd = -1
    leaf_fd = -1
    ticket: PendingBatchCleanupTicket | None = None
    try:
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        if _directory_identity(
            quarantine_fd
        ) != binding.quarantine_root_identity or not _bound_directory_matches(
            home, quarantine_root, quarantine_fd
        ):
            raise SyncError(f"ephemeral quarantine root changed: {quarantine_root}")
        batch_fd = os.open(batch_name, directory_flags, dir_fd=quarantine_fd)
        if _directory_identity(
            batch_fd
        ) != binding.batch_identity or not _bound_directory_matches(
            home, batch_root, batch_fd
        ):
            raise SyncError(f"ephemeral quarantine batch changed: {batch_root}")
        _require_pending_cleanup_fd_access_policy(
            batch_fd,
            batch_root,
            expected_mode=0o700,
        )
        expected_batch_members = (
            ("metadata.json",)
            if binding.leaf_identity is None
            else ("leaf", "metadata.json")
        )
        if (
            _directory_member_names(
                batch_fd,
                maximum_entries=3,
                overflow_message="ephemeral quarantine batch has too many entries",
            )
            != expected_batch_members
        ):
            raise SyncError(f"ephemeral quarantine batch is not empty: {batch_root}")
        current_metadata = _read_managed_state_file_snapshot(
            home,
            batch_root / "metadata.json",
            batch_fd,
            expected_identity=binding.metadata.file_identity,
            maximum_bytes=MAX_MANAGED_STATE_BYTES,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            current_metadata,
            binding.metadata,
        ):
            raise SyncError(f"ephemeral quarantine metadata changed: {batch_root}")
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            batch_root / "metadata.json",
            batch_fd,
            current_metadata,
        )
        if binding.leaf_identity is not None:
            leaf_fd = os.open("leaf", directory_flags, dir_fd=batch_fd)
            if _directory_identity(
                leaf_fd
            ) != binding.leaf_identity or not _bound_directory_matches(
                home, leaf_path, leaf_fd
            ):
                raise SyncError(f"ephemeral quarantine leaf changed: {leaf_path}")
            _require_pending_cleanup_fd_access_policy(
                leaf_fd,
                leaf_path,
                expected_mode=0o700,
            )
            if _directory_member_names(leaf_fd, maximum_entries=1) != ():
                raise SyncError(f"ephemeral quarantine leaf is not empty: {leaf_path}")
            _close_fd_quietly(leaf_fd)
            leaf_fd = -1
            leaf_stat = os.stat("leaf", dir_fd=batch_fd, follow_symlinks=False)
            if (
                not stat.S_ISDIR(leaf_stat.st_mode)
                or (leaf_stat.st_dev, leaf_stat.st_ino) != binding.leaf_identity
                or _directory_member_names(
                    batch_fd,
                    maximum_entries=3,
                    overflow_message="ephemeral quarantine batch has too many entries",
                )
                != ("leaf", "metadata.json")
            ):
                raise SyncError(
                    f"ephemeral quarantine leaf changed before cleanup: {leaf_path}"
                )
            cleanup_binding = replace(binding, metadata=current_metadata)
            if binding.cleanup_ticket is None:
                ticket = _publish_pending_ephemeral_quarantine_cleanup_ticket(
                    home,
                    cleanup_binding,
                )
            else:
                ticket = binding.cleanup_ticket
                if (
                    ticket.version != 5
                    or ticket.snapshot.payload
                    != _pending_ephemeral_quarantine_cleanup_ticket_payload(
                        cleanup_binding,
                        binding.quarantine_root_identity,
                    )
                ):
                    raise SyncError(
                        f"ephemeral quarantine cleanup authority changed: {batch_name}"
                    )
                _require_pending_cleanup_ticket_unchanged(home, ticket)
        else:
            # Leaf absence is itself a protected property.  Publish v7 durable
            # authority before metadata isolation, batch isolation, or rmdir so
            # every post-mutation crash can resume from the ticket/tombstone,
            # deterministic isolated name, and empty-proof protocol.
            if (
                _directory_identity(quarantine_fd) != binding.quarantine_root_identity
                or not _bound_directory_matches(
                    home,
                    quarantine_root,
                    quarantine_fd,
                )
                or _directory_identity(batch_fd) != binding.batch_identity
                or not _bound_directory_matches(home, batch_root, batch_fd)
                or _directory_member_names(batch_fd, maximum_entries=2)
                != ("metadata.json",)
            ):
                raise SyncError(
                    "ephemeral quarantine namespace changed before cleanup: "
                    f"{batch_root}"
                )
            ticket = _publish_pending_ephemeral_quarantine_scaffold_cleanup_ticket(
                home,
                replace(binding, metadata=current_metadata),
            )
    finally:
        _close_fd_quietly(leaf_fd)
        _close_fd_quietly(batch_fd)
        _close_fd_quietly(quarantine_fd)
    if ticket is not None and not _remove_cleanup_ready_batch(home, ticket):
        raise SyncError(f"ephemeral quarantine cleanup was not completed: {batch_name}")


def _isolate_and_delete_pending_regular_publication_candidate(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    source_parent: Path,
    source_parent_fd: int,
    source_name: str,
    expected: RegularFileSnapshot,
    *,
    public_names: tuple[str, ...] | None = None,
    expected_link_count: int,
    label: str,
) -> None:
    """Delete an exact regular leaf only after private batch isolation.

    The protected leaf properties are object identity, stable content and
    access policy. Parent directory timestamps and link counts are deliberately
    ignored so ordinary child-entry churn remains valid. The public source
    parent's complete access policy is revalidated after the final leaf
    snapshot and immediately before the rename. After that atomic boundary,
    only the mode-0700 batch cleanup namespace is mutated.
    """
    cleanup_parent = batch.batch_root / "pending" / "cleanup"
    if public_names is None:
        public_names = (source_name,)
    cleanup_parent_fd = _open_directory_beneath(home, cleanup_parent)
    planned = (
        expected.file_identity[0],
        expected.file_identity[1],
        stat.S_IFREG,
    )
    try:
        cleanup_parent_identity = _directory_identity(cleanup_parent_fd)
        _require_pending_cleanup_fd_access_policy(
            cleanup_parent_fd,
            cleanup_parent,
            expected_mode=0o700,
        )
        if not _bound_directory_matches(
            home,
            cleanup_parent,
            cleanup_parent_fd,
        ):
            raise SyncError("pending regular publication cleanup namespace changed")
        isolated_name = _pending_regular_publication_private_alias_name(
            cleanup_parent_identity,
            planned,
            record.index,
            phase,
        )
        if _named_entry_identity(cleanup_parent_fd, isolated_name) is not None:
            raise SyncError(
                "pending regular publication cleanup has both public and private "
                "active aliases"
            )
        source_snapshot = _regular_file_snapshot_at(
            source_parent_fd,
            source_name,
            source_parent / source_name,
            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        )
        if (
            not _regular_snapshot_matches(
                source_snapshot,
                expected.parent_identity,
                expected,
                expected_link_count=expected_link_count,
            )
            or _pending_cleanup_internal_entry_plan(
                source_name,
                PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
                expected.parent_identity,
            )
            != planned
        ):
            raise SyncError(f"{label} active entry changed")
        _require_managed_regular_parent_chain_access(
            home,
            source_parent,
            bound_parent_fd=source_parent_fd,
        )
        _require_pending_cleanup_fd_access_policy(
            cleanup_parent_fd,
            cleanup_parent,
            expected_mode=0o700,
        )
        _rename_noreplace_at(
            source_parent_fd,
            source_name,
            cleanup_parent_fd,
            isolated_name,
        )
        os.fsync(source_parent_fd)
        os.fsync(cleanup_parent_fd)
        if not _pending_regular_publication_uses_receiptless_cleanup(
            batch,
            record,
            phase,
        ):
            _advance_pending_regular_publication_private_authority(
                home,
                batch,
                record,
                phase,
                expected,
                source_name,
                cleanup_parent_fd=cleanup_parent_fd,
                cleanup_parent_identity=cleanup_parent_identity,
            )
        if _named_entry_identity(source_parent_fd, source_name) is not None:
            raise SyncError(
                f"{label} public active name reappeared; exact private evidence "
                "was retained"
            )
        try:
            _delete_pending_regular_publication_private_alias(
                home,
                batch,
                record,
                phase,
                cleanup_parent_fd,
                cleanup_parent_identity,
                expected,
                public_parent=source_parent,
                public_parent_fd=source_parent_fd,
                public_names=public_names,
                expected_link_count=expected_link_count,
                label=label,
            )
        except BaseException:
            # Modern cleanup advances an independent private-authority anchor
            # and never restores this inode to a public name. Receiptless
            # legacy cleanup retains its original best-effort restoration.
            if _named_entry_identity(cleanup_parent_fd, isolated_name) is not None:
                try:
                    restored_snapshot = _regular_file_snapshot_at(
                        cleanup_parent_fd,
                        isolated_name,
                        cleanup_parent / isolated_name,
                        maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                    )
                except BaseException:
                    _retain_pending_cleanup_entry(
                        cleanup_parent_fd,
                        isolated_name,
                        cleanup_parent_identity,
                        planned,
                        label=f"{label} private evidence became unreadable",
                    )
                if (
                    not _regular_snapshot_leaf_matches(restored_snapshot, expected)
                    or restored_snapshot.link_count != expected_link_count
                    or _pending_cleanup_internal_entry_plan(
                        isolated_name,
                        PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
                        cleanup_parent_identity,
                    )
                    != planned
                ):
                    _retain_pending_cleanup_entry(
                        cleanup_parent_fd,
                        isolated_name,
                        cleanup_parent_identity,
                        planned,
                        label=f"{label} private evidence changed before restoration",
                    )
                if not _pending_regular_publication_uses_receiptless_cleanup(
                    batch,
                    record,
                    phase,
                ):
                    journal = _read_pending_regular_publication_cleanup(
                        home,
                        batch,
                        record,
                        phase,
                    )
                    if journal is None:
                        _retain_pending_cleanup_entry(
                            cleanup_parent_fd,
                            isolated_name,
                            cleanup_parent_identity,
                            planned,
                            label=f"{label} cleanup journal disappeared",
                        )
                    _journal, active_name, _journal_phase, _expected = journal
                    _advance_pending_regular_publication_private_authority(
                        home,
                        batch,
                        record,
                        phase,
                        expected,
                        active_name,
                        cleanup_parent_fd=cleanup_parent_fd,
                        cleanup_parent_identity=cleanup_parent_identity,
                    )
                    # The durable anchor makes this private-only authority.
                    # Moving the same inode back to a public alias would make
                    # a later retry indistinguishable from hostile replay.
                    raise
                if any(
                    name != source_name
                    and _named_entry_identity(source_parent_fd, name) is not None
                    for name in public_names
                ):
                    _retain_pending_cleanup_entry(
                        cleanup_parent_fd,
                        isolated_name,
                        cleanup_parent_identity,
                        planned,
                        label=(
                            f"{label} public canonical name reappeared while "
                            "private evidence was retained"
                        ),
                    )
                try:
                    _require_managed_regular_parent_chain_access(
                        home,
                        source_parent,
                        bound_parent_fd=source_parent_fd,
                    )
                    _rename_noreplace_at(
                        cleanup_parent_fd,
                        isolated_name,
                        source_parent_fd,
                        source_name,
                    )
                    os.fsync(source_parent_fd)
                    os.fsync(cleanup_parent_fd)
                except BaseException:
                    _retain_pending_cleanup_entry(
                        cleanup_parent_fd,
                        isolated_name,
                        cleanup_parent_identity,
                        planned,
                        label=f"{label} private evidence could not be restored",
                    )
            raise
    finally:
        _close_fd_quietly(cleanup_parent_fd)


def _pending_regular_publication_private_alias_name(
    cleanup_parent_identity: tuple[int, int],
    planned: tuple[int, int, int],
    record_index: int,
    phase: str,
) -> str:
    if phase not in {"produced", "before"}:
        raise SyncError("pending regular publication cleanup phase is invalid")
    token = hashlib.sha256(f"{record_index}:{phase}".encode("ascii")).hexdigest()[:16]
    return (
        f"{PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX}"
        f"{cleanup_parent_identity[0]:x}-{cleanup_parent_identity[1]:x}-"
        f"{planned[0]:x}-{planned[1]:x}-{planned[2]:x}-{token}"
    )


def _pending_regular_publication_private_deletion_alias_name(
    private_name: str,
) -> str:
    return f"{private_name}.delete-{os.urandom(16).hex()}"


def _pending_regular_publication_private_deletion_alias_base(
    name: str,
) -> str | None:
    match = re.fullmatch(r"(.+)\.delete-[0-9a-f]{32}", name)
    if match is None:
        return None
    return match.group(1)


def _pending_regular_publication_private_alias_binding(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    file_identity: tuple[int, int],
) -> tuple[str, RegularFileSnapshot] | None:
    """Locate exactly one canonical or final-isolation private alias."""
    cleanup_parent = batch.batch_root / "pending" / "cleanup"
    cleanup_parent_fd = _open_directory_beneath(home, cleanup_parent)
    try:
        cleanup_parent_identity = _directory_identity(cleanup_parent_fd)
        _require_pending_cleanup_fd_access_policy(
            cleanup_parent_fd,
            cleanup_parent,
            expected_mode=0o700,
        )
        if not _bound_directory_matches(
            home,
            cleanup_parent,
            cleanup_parent_fd,
        ):
            raise SyncError("pending regular publication cleanup namespace changed")
        planned = (file_identity[0], file_identity[1], stat.S_IFREG)
        canonical_name = _pending_regular_publication_private_alias_name(
            cleanup_parent_identity,
            planned,
            record.index,
            phase,
        )
        deletion_prefix = f"{canonical_name}.delete-"
        candidates: list[str] = []
        with os.scandir(cleanup_parent_fd) as entries:
            for scanned, entry in enumerate(entries, start=1):
                if scanned > MAX_PENDING_CLEANUP_CONTROL_ENTRIES:
                    raise SyncError(
                        "pending regular publication private alias scan exceeds "
                        "the batch limit"
                    )
                if entry.name == canonical_name:
                    candidates.append(entry.name)
                elif entry.name.startswith(deletion_prefix) and (
                    _pending_regular_publication_private_deletion_alias_base(entry.name)
                    == canonical_name
                ):
                    candidates.append(entry.name)
        if not _bound_directory_matches(
            home,
            cleanup_parent,
            cleanup_parent_fd,
        ):
            raise SyncError("pending regular publication cleanup namespace changed")
        if not candidates:
            return None
        if len(candidates) != 1:
            raise SyncError("pending regular publication private cleanup is ambiguous")
        private_name = candidates[0]
        return private_name, _regular_file_snapshot_at(
            cleanup_parent_fd,
            private_name,
            cleanup_parent / private_name,
            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        )
    finally:
        _close_fd_quietly(cleanup_parent_fd)


def _pending_regular_publication_private_alias_snapshot(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    file_identity: tuple[int, int],
) -> RegularFileSnapshot | None:
    binding = _pending_regular_publication_private_alias_binding(
        home,
        batch,
        record,
        phase,
        file_identity,
    )
    return None if binding is None else binding[1]


def _pending_regular_publication_public_name_is_allowed(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    public_parent: Path,
    public_parent_fd: int,
    name: str,
) -> bool:
    if _named_entry_identity(public_parent_fd, name) is None:
        return True
    target = home / Path(*record.target.parts)
    if (
        phase != "produced"
        or record.action not in {"replace", "quarantine-replace"}
        or not record.before_is_regular()
        or public_parent != target.parent
        or name != target.name
    ):
        return False
    before = _pending_record_before_evidence_snapshot(home, batch, record)
    if not isinstance(before, RegularFileSnapshot):
        return False
    target_snapshot = _regular_file_snapshot_at(
        public_parent_fd,
        name,
        target,
        maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
    )
    return _regular_snapshot_matches(
        target_snapshot,
        record.planned_snapshot.parent_identity,
        before,
        expected_link_count=before.link_count,
    )


def _pending_regular_publication_public_names_are_allowed(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    public_parent: Path,
    public_parent_fd: int,
    public_names: tuple[str, ...],
) -> bool:
    """Validate public absence or the exact produced-phase before preimage.

    The protected properties are canonical object identity, stable content,
    access policy, parent binding, and the batch-authorized hard-link set.
    Parent child-entry churn is deliberately allowed.
    """
    return all(
        _pending_regular_publication_public_name_is_allowed(
            home,
            batch,
            record,
            phase,
            public_parent,
            public_parent_fd,
            name,
        )
        for name in public_names
    )


def _delete_pending_regular_publication_private_alias(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    cleanup_parent_fd: int,
    cleanup_parent_identity: tuple[int, int],
    expected: RegularFileSnapshot,
    *,
    public_parent: Path,
    public_parent_fd: int,
    public_names: tuple[str, ...],
    expected_link_count: int,
    label: str,
    private_name: str | None = None,
) -> None:
    cleanup_parent = batch.batch_root / "pending" / "cleanup"
    planned = (
        expected.file_identity[0],
        expected.file_identity[1],
        stat.S_IFREG,
    )
    canonical_private_name = _pending_regular_publication_private_alias_name(
        cleanup_parent_identity,
        planned,
        record.index,
        phase,
    )
    isolated_name = private_name or canonical_private_name
    if (
        isolated_name != canonical_private_name
        and _pending_regular_publication_private_deletion_alias_base(isolated_name)
        != canonical_private_name
    ):
        raise SyncError(f"{label} private isolation name is invalid")
    isolated_path = cleanup_parent / isolated_name
    try:
        isolated_snapshot = _regular_file_snapshot_at(
            cleanup_parent_fd,
            isolated_name,
            isolated_path,
            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        )
    except BaseException:
        _retain_pending_cleanup_entry(
            cleanup_parent_fd,
            isolated_name,
            cleanup_parent_identity,
            planned,
            label=f"{label} became unreadable after private isolation",
        )
    if (
        not _regular_snapshot_leaf_matches(isolated_snapshot, expected)
        or isolated_snapshot.link_count != expected_link_count
        or _pending_cleanup_internal_entry_plan(
            canonical_private_name,
            PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
            cleanup_parent_identity,
        )
        != planned
    ):
        _retain_pending_cleanup_entry(
            cleanup_parent_fd,
            isolated_name,
            cleanup_parent_identity,
            planned,
            label=f"{label} changed during private isolation",
        )
    if not _pending_regular_publication_uses_receiptless_cleanup(
        batch,
        record,
        phase,
    ):
        journal = _read_pending_regular_publication_cleanup(
            home,
            batch,
            record,
            phase,
        )
        if journal is None:
            raise SyncError("pending regular publication cleanup journal is missing")
        _journal_snapshot, active_name, _journal_phase, _journal_expected = journal
        _advance_pending_regular_publication_private_authority(
            home,
            batch,
            record,
            phase,
            expected,
            active_name,
            cleanup_parent_fd=cleanup_parent_fd,
            cleanup_parent_identity=cleanup_parent_identity,
        )
    _require_managed_regular_parent_chain_access(
        home,
        public_parent,
        bound_parent_fd=public_parent_fd,
    )
    if not _pending_regular_publication_public_names_are_allowed(
        home,
        batch,
        record,
        phase,
        public_parent,
        public_parent_fd,
        public_names,
    ):
        raise SyncError(
            f"{label} public name reappeared; exact private evidence was retained"
        )
    _require_pending_cleanup_fd_access_policy(
        cleanup_parent_fd,
        cleanup_parent,
        expected_mode=0o700,
    )

    deletion_name: str | None = None
    isolation_error: BaseException | None = None
    for _attempt in range(128):
        candidate = _pending_regular_publication_private_deletion_alias_name(
            canonical_private_name
        )
        try:
            _rename_noreplace_at(
                cleanup_parent_fd,
                isolated_name,
                cleanup_parent_fd,
                candidate,
            )
        except FileExistsError:
            continue
        except BaseException as error:
            source_identity = _named_entry_identity(
                cleanup_parent_fd,
                isolated_name,
            )
            candidate_identity = _named_entry_identity(
                cleanup_parent_fd,
                candidate,
            )
            if source_identity is None and candidate_identity is not None:
                deletion_name = candidate
                isolation_error = error
                break
            if source_identity is None:
                raise SyncError(
                    f"{label} private evidence disappeared during final isolation"
                ) from error
            raise SyncError(
                f"{label} private evidence could not be finally isolated; "
                f"retained as {isolated_name}"
            ) from error
        deletion_name = candidate
        break
    if deletion_name is None:
        raise SyncError(f"{label} could not allocate a final private isolation name")
    os.fsync(cleanup_parent_fd)

    deletion_path = cleanup_parent / deletion_name
    try:
        deletion_snapshot = _regular_file_snapshot_at(
            cleanup_parent_fd,
            deletion_name,
            deletion_path,
            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        )
    except BaseException:
        _retain_pending_cleanup_entry(
            cleanup_parent_fd,
            deletion_name,
            cleanup_parent_identity,
            planned,
            label=f"{label} became unreadable after final private isolation",
        )
    if (
        not _regular_snapshot_leaf_matches(deletion_snapshot, expected)
        or deletion_snapshot.link_count != expected_link_count
        or _pending_regular_publication_private_deletion_alias_base(deletion_name)
        != canonical_private_name
        or _directory_identity(cleanup_parent_fd) != cleanup_parent_identity
        or not _bound_directory_matches(home, cleanup_parent, cleanup_parent_fd)
    ):
        _retain_pending_cleanup_entry(
            cleanup_parent_fd,
            deletion_name,
            cleanup_parent_identity,
            planned,
            label=f"{label} changed during final private isolation",
        )
    if isolation_error is not None:
        raise isolation_error

    private_fd = -1
    private_flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    private_flags |= getattr(os, "O_NOFOLLOW", 0)
    private_flags |= getattr(os, "O_NONBLOCK", 0)
    try:
        try:
            private_fd = os.open(
                deletion_name,
                private_flags,
                dir_fd=cleanup_parent_fd,
            )
        except OSError as error:
            raise SyncError(
                f"{label} final private evidence became unreadable"
            ) from error

        def require_open_private_unchanged(stage: str) -> None:
            try:
                before = _require_release_identity_fd_access_policy(
                    private_fd,
                    deletion_path,
                    expected.uid,
                )
                os.lseek(private_fd, 0, os.SEEK_SET)
                payload = _read_managed_state_bytes(
                    private_fd,
                    deletion_path,
                    MAX_ARCHIVE_MEMBER_BYTES,
                )
                os.lseek(private_fd, 0, os.SEEK_SET)
                confirmed_payload = _read_managed_state_bytes(
                    private_fd,
                    deletion_path,
                    MAX_ARCHIVE_MEMBER_BYTES,
                )
                after = _require_release_identity_fd_access_policy(
                    private_fd,
                    deletion_path,
                    expected.uid,
                )
                named = os.stat(
                    deletion_name,
                    dir_fd=cleanup_parent_fd,
                    follow_symlinks=False,
                )
            except (OSError, SyncError) as error:
                raise SyncError(
                    f"{label} final private evidence changed {stage}"
                ) from error
            if (
                not stat.S_ISREG(before.st_mode)
                or not _regular_stat_metadata_matches(after, before)
                or not _regular_stat_metadata_matches(named, before)
                or (before.st_dev, before.st_ino) != expected.file_identity
                or stat.S_IMODE(before.st_mode) != expected.mode
                or before.st_uid != expected.uid
                or not _gid_matches_regular_file_access_policy(
                    before.st_gid,
                    expected.gid,
                    expected.mode,
                )
                or before.st_size != expected.size
                or before.st_nlink != expected_link_count
                or hashlib.sha256(payload).hexdigest() != expected.sha256
                or hashlib.sha256(confirmed_payload).hexdigest() != expected.sha256
                or _pending_regular_publication_private_deletion_alias_base(
                    deletion_name
                )
                != canonical_private_name
                or _directory_identity(cleanup_parent_fd) != cleanup_parent_identity
                or not _bound_directory_matches(
                    home,
                    cleanup_parent,
                    cleanup_parent_fd,
                )
            ):
                raise SyncError(f"{label} final private evidence changed {stage}")

        require_open_private_unchanged("before boundary revalidation")
        if not _pending_regular_publication_uses_receiptless_cleanup(
            batch,
            record,
            phase,
        ):
            journal = _read_pending_regular_publication_cleanup(
                home,
                batch,
                record,
                phase,
            )
            if journal is None:
                raise SyncError(
                    f"{label} cleanup journal disappeared after final isolation"
                )
            _journal_snapshot, active_name, _journal_phase, _journal_expected = journal
            _advance_pending_regular_publication_private_authority(
                home,
                batch,
                record,
                phase,
                expected,
                active_name,
                cleanup_parent_fd=cleanup_parent_fd,
                cleanup_parent_identity=cleanup_parent_identity,
            )
        _require_managed_regular_parent_chain_access(
            home,
            public_parent,
            bound_parent_fd=public_parent_fd,
        )
        if not _pending_regular_publication_public_names_are_allowed(
            home,
            batch,
            record,
            phase,
            public_parent,
            public_parent_fd,
            public_names,
        ):
            raise SyncError(
                f"{label} public name reappeared; exact private evidence was retained"
            )
        _require_pending_cleanup_fd_access_policy(
            cleanup_parent_fd,
            cleanup_parent,
            expected_mode=0o700,
        )
        # Boundary probes above can race with the final pathname. Rebind the
        # name to the still-open exact descriptor and repeat identity,
        # content, access-policy, and link-count validation immediately before
        # the irreversible unlink.
        require_open_private_unchanged("after boundary revalidation")
        os.unlink(deletion_name, dir_fd=cleanup_parent_fd)
        os.fsync(cleanup_parent_fd)
        if _named_entry_identity(cleanup_parent_fd, deletion_name) is not None:
            raise SyncError(f"{label} private name reappeared after deletion")
    finally:
        _close_fd_quietly(private_fd)
    _require_managed_regular_parent_chain_access(
        home,
        public_parent,
        bound_parent_fd=public_parent_fd,
    )
    if not _pending_regular_publication_public_names_are_allowed(
        home,
        batch,
        record,
        phase,
        public_parent,
        public_parent_fd,
        public_names,
    ):
        raise SyncError(
            f"{label} public name reappeared while private cleanup completed"
        )


def _recover_pending_regular_publication_private_alias(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    public_parent: Path,
    public_parent_fd: int,
    public_names: tuple[str, ...],
    expected: RegularFileSnapshot,
    *,
    expected_link_count: int,
    label: str,
) -> bool:
    private_binding = _pending_regular_publication_private_alias_binding(
        home,
        batch,
        record,
        phase,
        expected.file_identity,
    )
    if private_binding is None:
        return False
    private_name, private_snapshot = private_binding
    if (
        not _regular_snapshot_leaf_matches(private_snapshot, expected)
        or private_snapshot.link_count != expected_link_count
    ):
        raise SyncError(f"{label} private active entry changed")
    _require_managed_regular_parent_chain_access(
        home,
        public_parent,
        bound_parent_fd=public_parent_fd,
    )
    if not _pending_regular_publication_public_names_are_allowed(
        home,
        batch,
        record,
        phase,
        public_parent,
        public_parent_fd,
        public_names,
    ):
        raise SyncError(
            f"{label} public name reappeared; exact private evidence was retained"
        )
    cleanup_parent = batch.batch_root / "pending" / "cleanup"
    cleanup_parent_fd = _open_directory_beneath(home, cleanup_parent)
    try:
        cleanup_parent_identity = _directory_identity(cleanup_parent_fd)
        if cleanup_parent_identity != private_snapshot.parent_identity:
            raise SyncError("pending regular publication cleanup namespace changed")
        _delete_pending_regular_publication_private_alias(
            home,
            batch,
            record,
            phase,
            cleanup_parent_fd,
            cleanup_parent_identity,
            expected,
            public_parent=public_parent,
            public_parent_fd=public_parent_fd,
            public_names=public_names,
            expected_link_count=expected_link_count,
            label=label,
            private_name=private_name,
        )
    finally:
        _close_fd_quietly(cleanup_parent_fd)
    return True


def _pending_regular_publication_cleanup_payload(
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    expected: RegularFileSnapshot,
    phase: str,
    active_name: str,
    *,
    version: int = 2,
    cleanup_parent_identity: tuple[int, int] | None = None,
) -> bytes:
    if (
        batch.metadata_version < 8
        or record.publication_cleanup is None
        or record.planned_snapshot.parent_identity is None
    ):
        raise SyncError("pending regular publication cleanup authority is incomplete")
    planned_regular = _regular_snapshot_from_reconcile(record.planned_snapshot)
    if phase == "produced":
        if not _pending_regular_publication_snapshot_matches(
            expected,
            record,
            expected_link_count=(record.regular_link_count or 0) + 1,
        ):
            raise SyncError("pending regular publication cleanup target changed")
    elif phase == "before":
        if (
            planned_regular is None
            or not _regular_snapshot_leaf_matches(
                expected,
                planned_regular,
            )
            or expected.parent_identity != record.planned_snapshot.parent_identity
            or expected.link_count != planned_regular.link_count + 1
        ):
            raise SyncError("pending regular restoration cleanup target changed")
    else:
        raise SyncError("pending regular publication cleanup phase is invalid")
    planned = (
        expected.file_identity[0],
        expected.file_identity[1],
        stat.S_IFREG,
    )
    if (
        _pending_cleanup_internal_entry_plan(
            active_name,
            PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
            record.planned_snapshot.parent_identity,
        )
        != planned
    ):
        raise SyncError("pending regular publication cleanup name is invalid")
    if version not in {1, 2, 3}:
        raise SyncError(
            "pending regular publication cleanup journal version is invalid"
        )
    if version == 3 and cleanup_parent_identity is None:
        raise SyncError(
            "pending regular publication private cleanup authority is incomplete"
        )
    private_name = None
    if cleanup_parent_identity is not None:
        private_name = _pending_regular_publication_private_alias_name(
            cleanup_parent_identity,
            planned,
            record.index,
            phase,
        )
    payload: dict[str, object] = {
        "version": version,
        "record": record.index,
        "phase": phase,
        "target": record.target.as_posix(),
        "parent_identity": _identity_payload(expected.parent_identity),
        "file_identity": _identity_payload(expected.file_identity),
        "sha256": expected.sha256,
        "size": expected.size,
        "mode": expected.mode,
        "uid": expected.uid,
        "link_count": expected.link_count,
        "active": active_name,
    }
    if version >= 2:
        payload.update(
            {
                "batch": batch.batch_root.name,
                "batch_root_identity": _identity_payload(batch.batch_root_identity),
                "lifecycle": (
                    "public-authorized" if version == 2 else "private-authority"
                ),
            }
        )
    if version == 3:
        payload.update(
            {
                "cleanup_parent_identity": _identity_payload(cleanup_parent_identity),
                "private": private_name,
            }
        )
    return _bounded_json_document(
        payload,
        max_bytes=4096,
        overflow_error="pending regular publication cleanup journal exceeds the size limit",
    )


def _pending_regular_publication_cleanup_path(
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
) -> Path:
    if batch.metadata_version < 8 or record.publication_cleanup is None:
        raise SyncError("pending regular publication cleanup is unavailable")
    if phase == "produced":
        relative_path = record.publication_cleanup
    elif phase == "before":
        relative_path = record.publication_cleanup.with_name(
            record.publication_cleanup.stem + ".before.json"
        )
    else:
        raise SyncError("pending regular publication cleanup phase is invalid")
    return batch.batch_root / Path(*relative_path.parts)


def _pending_regular_publication_snapshot_matches(
    snapshot: RegularFileSnapshot,
    record: PendingLinkRecord,
    *,
    expected_link_count: int,
) -> bool:
    return (
        record.planned_snapshot.parent_identity is not None
        and record.evidence_identity is not None
        and snapshot.parent_identity == record.planned_snapshot.parent_identity
        and snapshot.file_identity == record.evidence_identity
        and snapshot.sha256 == record.regular_sha256
        and snapshot.size == record.regular_size
        and snapshot.mode == record.regular_mode
        and snapshot.uid == record.regular_uid
        and snapshot.link_count == expected_link_count
    )


def _read_pending_regular_publication_cleanup(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    requested_phase: str,
) -> tuple[ManagedStateFileSnapshot, str, str, RegularFileSnapshot] | None:
    path = _pending_regular_publication_cleanup_path(batch, record, requested_phase)
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        snapshot = _read_managed_state_file_snapshot(
            home,
            path,
            parent_fd,
            maximum_bytes=4096,
        )
    finally:
        _close_fd_quietly(parent_fd)
    if not snapshot.exists:
        return None
    if (
        not _managed_state_snapshot_has_complete_file_evidence(snapshot)
        or snapshot.file_type != stat.S_IFREG
        or snapshot.mode != 0o600
        or snapshot.uid != os.geteuid()
    ):
        raise SyncError("pending regular publication cleanup journal changed")
    data = _decode_managed_state_json(snapshot.payload, path)
    journal_version = data.get("version")
    if (
        not isinstance(journal_version, int)
        or isinstance(journal_version, bool)
        or journal_version not in {1, 2, 3}
    ):
        raise SyncError("pending regular publication cleanup journal changed")
    expected_fields = {
        "version",
        "record",
        "phase",
        "target",
        "parent_identity",
        "file_identity",
        "sha256",
        "size",
        "mode",
        "uid",
        "link_count",
        "active",
    }
    if journal_version in {2, 3}:
        expected_fields.update({"batch", "batch_root_identity", "lifecycle"})
    if journal_version == 3:
        expected_fields.update({"cleanup_parent_identity", "private"})
    if set(data) != expected_fields:
        raise SyncError("pending regular publication cleanup journal changed")
    parent_identity = _parse_pending_identity(
        data.get("parent_identity"),
        "pending regular publication cleanup parent identity",
    )
    file_identity = _parse_pending_identity(
        data.get("file_identity"),
        "pending regular publication cleanup file identity",
    )
    journal_phase = data.get("phase")
    active_name = data.get("active")
    link_count = data.get("link_count")
    batch_root_identity = (
        _parse_pending_identity(
            data.get("batch_root_identity"),
            "pending regular publication cleanup batch identity",
        )
        if journal_version in {2, 3}
        else None
    )
    cleanup_parent_identity = (
        _parse_pending_identity(
            data.get("cleanup_parent_identity"),
            "pending regular publication cleanup namespace identity",
        )
        if journal_version == 3
        else None
    )
    if (
        parent_identity is None
        or file_identity is None
        or not isinstance(journal_phase, str)
        or journal_phase not in {"produced", "before"}
        or not isinstance(data.get("sha256"), str)
        or not isinstance(data.get("size"), int)
        or isinstance(data.get("size"), bool)
        or not isinstance(data.get("mode"), int)
        or isinstance(data.get("mode"), bool)
        or not isinstance(data.get("uid"), int)
        or isinstance(data.get("uid"), bool)
        or not isinstance(link_count, int)
        or isinstance(link_count, bool)
    ):
        raise SyncError("pending regular publication cleanup journal changed")
    expected = RegularFileSnapshot(
        parent_identity=parent_identity,
        file_identity=file_identity,
        sha256=data["sha256"],
        size=data["size"],
        mode=data["mode"],
        uid=data["uid"],
        gid=0,
        link_count=link_count,
    )
    if journal_version == 3:
        if (
            cleanup_parent_identity is None
            or cleanup_parent_identity != snapshot.parent_identity
            or data.get("private")
            != _pending_regular_publication_private_alias_name(
                cleanup_parent_identity,
                (file_identity[0], file_identity[1], stat.S_IFREG),
                record.index,
                journal_phase,
            )
        ):
            raise SyncError("pending regular publication cleanup journal changed")
    if (
        data.get("record") != record.index
        or data.get("target") != record.target.as_posix()
        or journal_phase != requested_phase
        or not isinstance(active_name, str)
        or (
            journal_version in {2, 3}
            and (
                data.get("batch") != batch.batch_root.name
                or batch_root_identity != batch.batch_root_identity
                or data.get("lifecycle")
                != (
                    "public-authorized" if journal_version == 2 else "private-authority"
                )
            )
        )
        or _pending_regular_publication_cleanup_payload(
            batch,
            record,
            expected,
            journal_phase,
            active_name,
            version=journal_version,
            cleanup_parent_identity=cleanup_parent_identity,
        )
        != snapshot.payload
    ):
        raise SyncError("pending regular publication cleanup journal changed")
    return snapshot, active_name, journal_phase, expected


def _pending_regular_publication_cleanup_lifecycle(
    journal: ManagedStateFileSnapshot,
) -> str | None:
    if journal.payload is None:
        raise SyncError("pending regular publication cleanup journal changed")
    data = _decode_managed_state_json(
        journal.payload,
        Path("pending regular publication cleanup journal"),
    )
    version = data.get("version")
    if not isinstance(version, int) or isinstance(version, bool):
        raise SyncError("pending regular publication cleanup journal changed")
    if version == 1:
        return None
    lifecycle = data.get("lifecycle")
    if version not in {2, 3} or lifecycle not in {
        "public-authorized",
        "private-authority",
    }:
        raise SyncError("pending regular publication cleanup journal changed")
    return lifecycle


def _pending_regular_publication_private_authority_path(
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
) -> Path:
    journal_path = _pending_regular_publication_cleanup_path(batch, record, phase)
    return journal_path.with_name(journal_path.stem + ".private-authority.json")


def _read_pending_regular_publication_private_authority(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    expected: RegularFileSnapshot,
    active_name: str,
    cleanup_parent_identity: tuple[int, int],
) -> ManagedStateFileSnapshot | None:
    path = _pending_regular_publication_private_authority_path(
        batch,
        record,
        phase,
    )
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        snapshot = _read_managed_state_file_snapshot(
            home,
            path,
            parent_fd,
            maximum_bytes=4096,
        )
        if not snapshot.exists:
            return None
        if (
            not _managed_state_snapshot_has_complete_file_evidence(snapshot)
            or snapshot.file_type != stat.S_IFREG
            or snapshot.mode != 0o600
            or snapshot.uid != os.geteuid()
            or snapshot.parent_identity != cleanup_parent_identity
            or _directory_identity(parent_fd) != cleanup_parent_identity
            or not _bound_directory_matches(home, path.parent, parent_fd)
            or snapshot.payload
            != _pending_regular_publication_cleanup_payload(
                batch,
                record,
                expected,
                phase,
                active_name,
                version=3,
                cleanup_parent_identity=cleanup_parent_identity,
            )
        ):
            raise SyncError(
                "pending regular publication private authority anchor changed"
            )
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            path,
            parent_fd,
            snapshot,
        )
        return snapshot
    finally:
        _close_fd_quietly(parent_fd)


def _publish_pending_regular_publication_private_authority(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    expected: RegularFileSnapshot,
    active_name: str,
    cleanup_parent_identity: tuple[int, int],
) -> ManagedStateFileSnapshot:
    path = _pending_regular_publication_private_authority_path(
        batch,
        record,
        phase,
    )
    published = _publish_atomic_exclusive_internal_file(
        home,
        path,
        _pending_regular_publication_cleanup_payload(
            batch,
            record,
            expected,
            phase,
            active_name,
            version=3,
            cleanup_parent_identity=cleanup_parent_identity,
        ),
    )
    verified = _read_pending_regular_publication_private_authority(
        home,
        batch,
        record,
        phase,
        expected,
        active_name,
        cleanup_parent_identity,
    )
    if verified is None or not _managed_state_snapshot_matches_bound_file_evidence(
        verified,
        published,
    ):
        raise SyncError("pending regular publication private authority anchor changed")
    return verified


def _advance_pending_regular_publication_private_authority(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    expected: RegularFileSnapshot,
    active_name: str,
    cleanup_parent_fd: int,
    cleanup_parent_identity: tuple[int, int],
) -> ManagedStateFileSnapshot:
    """Durably revoke public cleanup authority before private deletion.

    The protected property is the monotonic cleanup-authority lifecycle for
    the exact batch, record phase and regular-file inode. The original journal
    identity and payload prove content stability; the exclusive v3 anchor,
    bound cleanup-parent identity and access-policy checks prove private-only
    authority. Ordinary child-entry churn is not compared. Missing or
    unreadable evidence remains distinct from an identity or payload mismatch,
    and every such failure occurs before the private inode can be unlinked.
    """
    current = _read_pending_regular_publication_cleanup(home, batch, record, phase)
    if current is None:
        raise SyncError("pending regular publication cleanup journal is missing")
    current_snapshot, current_active_name, _journal_phase, current_expected = current
    if (
        current_active_name != active_name
        or not _regular_snapshot_leaf_matches(current_expected, expected)
        or current_expected.link_count != expected.link_count
        or current_snapshot.parent_identity != cleanup_parent_identity
    ):
        raise SyncError("pending regular publication cleanup journal changed")
    _publish_pending_regular_publication_private_authority(
        home,
        batch,
        record,
        phase,
        expected,
        active_name,
        cleanup_parent_identity,
    )
    # The exclusive v3 anchor is the durable monotonic revocation record.
    # Keeping the original journal inode and payload avoids an overwrite race
    # entirely; recovery already treats either a private lifecycle journal or
    # this independently validated anchor as private authority.
    return current_snapshot


def _delete_pending_regular_publication_beneath(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    target: Path,
    expected: RegularFileSnapshot,
    *,
    phase: str,
) -> None:
    produced_authority = (
        phase == "produced"
        and record.is_regular()
        and record.action in {"create", "replace", "quarantine-replace"}
    )
    before_authority = (
        phase == "before"
        and record.before_is_regular()
        and record.action
        in {"replace", "quarantine-replace", "remove", "quarantine-remove"}
    )
    if not (produced_authority or before_authority):
        raise SyncError("pending regular publication cleanup has an invalid record")
    if _pending_regular_publication_uses_receiptless_cleanup(
        batch,
        record,
        phase,
    ):
        # Metadata v6/v7 predates the durable publication receipt. Preserve its
        # exact deletion protocol for those versions and for the v8/v9 managed
        # regular-removal shape whose closed writers emitted a null receipt.
        _delete_exact_regular_publication_beneath(
            home,
            target,
            expected,
            pending_batch=batch,
            pending_record=record,
            cleanup_phase=phase,
        )
        return
    existing = _read_pending_regular_publication_cleanup(home, batch, record, phase)
    if existing is not None:
        _recover_pending_regular_publication_cleanup(
            home,
            batch,
            record,
            phase,
        )
        return
    parent_fd = _open_directory_beneath(home, target.parent)
    try:
        parent_identity = _directory_identity(parent_fd)
        if parent_identity != expected.parent_identity or not _bound_directory_matches(
            home, target.parent, parent_fd
        ):
            raise SyncError("pending regular publication cleanup parent changed")
        planned = (expected.file_identity[0], expected.file_identity[1], stat.S_IFREG)
        active_name = _pending_cleanup_entry_name(
            PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
            parent_identity,
            planned,
        )
        journal_path = _pending_regular_publication_cleanup_path(batch, record, phase)
        cleanup_parent_fd = _open_directory_beneath(home, journal_path.parent)
        try:
            cleanup_parent_identity = _directory_identity(cleanup_parent_fd)
            _require_pending_cleanup_fd_access_policy(
                cleanup_parent_fd,
                journal_path.parent,
                expected_mode=0o700,
            )
            if not _bound_directory_matches(
                home,
                journal_path.parent,
                cleanup_parent_fd,
            ):
                raise SyncError("pending regular publication cleanup namespace changed")
        finally:
            _close_fd_quietly(cleanup_parent_fd)
        if (
            _read_pending_regular_publication_private_authority(
                home,
                batch,
                record,
                phase,
                expected,
                active_name,
                cleanup_parent_identity,
            )
            is not None
        ):
            raise SyncError(
                "pending regular publication public cleanup authority was revoked"
            )
        prepared_journal = _publish_atomic_exclusive_internal_file(
            home,
            journal_path,
            _pending_regular_publication_cleanup_payload(
                batch, record, expected, phase, active_name
            ),
        )
        current_journal = _read_pending_regular_publication_cleanup(
            home,
            batch,
            record,
            phase,
        )
        if (
            current_journal is None
            or not _managed_state_snapshot_matches_bound_file_evidence(
                current_journal[0],
                prepared_journal,
            )
            or _pending_regular_publication_cleanup_lifecycle(current_journal[0])
            != "public-authorized"
        ):
            raise SyncError(
                "pending regular publication public cleanup authority changed"
            )
        # Publish the complete public-authorized phase before removing a
        # Codex-loadable canonical name. The same receipt is advanced atomically
        # to private-authority before the private alias can be deleted.
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=parent_fd,
        )
        _rename_noreplace_at(parent_fd, target.name, parent_fd, active_name)
        os.fsync(parent_fd)
        try:
            active = _regular_file_snapshot_at(
                parent_fd,
                active_name,
                target.with_name(active_name),
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
        except BaseException:
            _retain_pending_cleanup_entry(
                parent_fd,
                active_name,
                parent_identity,
                planned,
                label=(
                    "pending regular publication became unreadable after "
                    f"isolation: {target}"
                ),
            )
        if not _regular_snapshot_matches(
            active,
            expected.parent_identity,
            expected,
            expected_link_count=expected.link_count,
        ):
            _retain_pending_cleanup_entry(
                parent_fd,
                active_name,
                parent_identity,
                planned,
                label=f"pending regular publication active entry changed: {target}",
            )
        _isolate_and_delete_pending_regular_publication_candidate(
            home,
            batch,
            record,
            phase,
            target.parent,
            parent_fd,
            active_name,
            expected,
            public_names=(target.name, active_name),
            expected_link_count=expected.link_count,
            label="pending regular publication",
        )
        # Keep this lifecycle receipt until whole-batch finalization.
    finally:
        _close_fd_quietly(parent_fd)


def _pending_regular_publication_uses_receiptless_cleanup(
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
) -> bool:
    if batch.metadata_version < 8:
        return True
    return (
        phase == "before"
        and batch.metadata_version in {8, 9}
        and record.publication_cleanup is None
    )


def _legacy_pending_regular_publication_phase_authority(
    record: PendingLinkRecord,
    phase: str,
) -> tuple[
    tuple[int, int],
    tuple[int, int],
    PurePosixPath,
    tuple[PurePosixPath | None, ...],
    RegularFileSnapshot | None,
]:
    parent_identity = record.planned_snapshot.parent_identity
    planned_regular = _regular_snapshot_from_reconcile(record.planned_snapshot)
    if phase == "produced":
        file_identity = record.evidence_identity
        evidence_path = record.evidence
        other_alias_paths = (record.stage,)
    elif phase == "before":
        file_identity = record.before_evidence_identity
        evidence_path = record.before_evidence
        other_alias_paths = (record.backup,)
    else:
        raise SyncError("pending legacy regular publication phase is invalid")
    if (
        parent_identity is None
        or file_identity is None
        or evidence_path is None
        or (phase == "produced" and record.regular_link_count is None)
        or (phase == "before" and planned_regular is None)
    ):
        raise SyncError("pending legacy regular publication evidence is incomplete")
    return (
        parent_identity,
        file_identity,
        evidence_path,
        other_alias_paths,
        planned_regular,
    )


def _build_legacy_pending_regular_publication_active_entry_index(
    home: Path,
    batch: PendingLinkBatch,
) -> _LegacyPendingRegularPublicationActiveEntryIndex:
    if batch.metadata_version not in {6, 7, 8, 9}:
        return _LegacyPendingRegularPublicationActiveEntryIndex({})
    planned_by_parent: dict[
        tuple[Path, tuple[int, int]], set[tuple[int, int, int]]
    ] = {}
    for record in batch.records:
        phases: list[str] = []
        if (
            record.is_regular()
            and record.action in {"create", "replace", "quarantine-replace"}
            and _pending_regular_publication_uses_receiptless_cleanup(
                batch, record, "produced"
            )
        ):
            phases.append("produced")
        if (
            record.before_is_regular()
            and record.action
            in {"replace", "quarantine-replace", "remove", "quarantine-remove"}
            and _pending_regular_publication_uses_receiptless_cleanup(
                batch, record, "before"
            )
        ):
            phases.append("before")
        if not phases:
            continue
        target = home / Path(*record.target.parts)
        for phase in phases:
            (
                parent_identity,
                file_identity,
                _evidence_path,
                _other_alias_paths,
                _planned,
            ) = _legacy_pending_regular_publication_phase_authority(record, phase)
            planned_by_parent.setdefault((target.parent, parent_identity), set()).add(
                (file_identity[0], file_identity[1], stat.S_IFREG)
            )

    names_by_parent_plan: dict[
        tuple[Path, tuple[int, int], tuple[int, int, int]], set[str]
    ] = {}
    scanned_entries = 0
    for (parent, parent_identity), plans in sorted(
        planned_by_parent.items(),
        key=lambda item: (str(item[0][0]), item[0][1]),
    ):
        parent_fd = _open_directory_beneath(home, parent)
        try:
            if _directory_identity(
                parent_fd
            ) != parent_identity or not _bound_directory_matches(
                home, parent, parent_fd
            ):
                raise SyncError("pending legacy regular publication parent changed")
            _require_managed_regular_parent_chain_access(
                home,
                parent,
                bound_parent_fd=parent_fd,
            )
            with os.scandir(parent_fd) as entries:
                for entry in entries:
                    scanned_entries += 1
                    if scanned_entries > MAX_PENDING_CLEANUP_CONTROL_ENTRIES:
                        raise SyncError(
                            "pending legacy regular publication active-entry scan "
                            "exceeds the batch limit"
                        )
                    planned = _pending_cleanup_internal_entry_plan(
                        entry.name,
                        PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
                        parent_identity,
                    )
                    if planned in plans:
                        names_by_parent_plan.setdefault(
                            (parent, parent_identity, planned), set()
                        ).add(entry.name)
            _require_managed_regular_parent_chain_access(
                home,
                parent,
                bound_parent_fd=parent_fd,
            )
            if not _bound_directory_matches(home, parent, parent_fd):
                raise SyncError("pending legacy regular publication parent changed")
        finally:
            _close_fd_quietly(parent_fd)
    return _LegacyPendingRegularPublicationActiveEntryIndex(names_by_parent_plan)


def _recover_legacy_pending_regular_publication_active_entry(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    *,
    active_entry_index: _LegacyPendingRegularPublicationActiveEntryIndex | None = None,
) -> None:
    if not _pending_regular_publication_uses_receiptless_cleanup(
        batch,
        record,
        phase,
    ):
        return
    (
        parent_identity,
        file_identity,
        evidence_path,
        other_alias_paths,
        planned_regular,
    ) = _legacy_pending_regular_publication_phase_authority(record, phase)
    target = home / Path(*record.target.parts)
    planned = (file_identity[0], file_identity[1], stat.S_IFREG)
    if active_entry_index is None:
        active_entry_index = (
            _build_legacy_pending_regular_publication_active_entry_index(home, batch)
        )
    candidates = active_entry_index.names(target.parent, parent_identity, planned)
    parent_fd = _open_directory_beneath(home, target.parent)
    try:
        if _directory_identity(
            parent_fd
        ) != parent_identity or not _bound_directory_matches(
            home, target.parent, parent_fd
        ):
            raise SyncError("pending legacy regular publication parent changed")
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=parent_fd,
        )
        private_snapshot = _pending_regular_publication_private_alias_snapshot(
            home,
            batch,
            record,
            phase,
            file_identity,
        )
        if not candidates and private_snapshot is None:
            return
        target_identity = _named_entry_identity(parent_fd, target.name)
        if (
            len(candidates) + (private_snapshot is not None) != 1
            or target_identity == file_identity
        ):
            raise SyncError("pending legacy regular publication cleanup is ambiguous")
        evidence = batch.batch_root / Path(*evidence_path.parts)
        evidence_snapshot = _read_regular_file_snapshot_beneath(
            home,
            evidence,
            require_managed_access=False,
        )
        if phase == "produced":
            evidence_matches = (
                evidence_snapshot.file_identity == record.evidence_identity
                and evidence_snapshot.sha256 == record.regular_sha256
                and evidence_snapshot.size == record.regular_size
                and evidence_snapshot.mode == record.regular_mode
                and evidence_snapshot.uid == record.regular_uid
            )
        else:
            assert planned_regular is not None
            evidence_matches = _regular_snapshot_leaf_matches(
                evidence_snapshot,
                planned_regular,
            )
        if evidence_snapshot.file_identity != file_identity or not evidence_matches:
            raise SyncError("pending legacy regular publication evidence changed")
        bound_alias_count = 1
        for relative_alias in other_alias_paths:
            if relative_alias is None:
                continue
            alias = batch.batch_root / Path(*relative_alias.parts)
            if _regular_alias_identity_beneath(home, alias) == file_identity:
                bound_alias_count += 1
        if phase == "produced" and bound_alias_count != record.regular_link_count:
            raise SyncError("pending legacy regular publication aliases changed")
        expected_link_count = bound_alias_count + 1
        if evidence_snapshot.link_count != expected_link_count:
            raise SyncError("pending legacy regular publication link count changed")
        if private_snapshot is not None:
            active_name = None
            active = private_snapshot
            if phase == "produced":
                matches = (
                    _regular_snapshot_leaf_matches(active, evidence_snapshot)
                    and active.link_count == expected_link_count
                )
            else:
                assert planned_regular is not None
                matches = (
                    _regular_snapshot_leaf_matches(active, planned_regular)
                    and active.link_count == expected_link_count
                )
        else:
            active_name = candidates[0]
            active = _regular_file_snapshot_at(
                parent_fd,
                active_name,
                target.with_name(active_name),
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
            if phase == "produced":
                matches = _pending_regular_publication_snapshot_matches(
                    active,
                    record,
                    expected_link_count=expected_link_count,
                )
            else:
                assert planned_regular is not None
                matches = _regular_snapshot_matches(
                    active,
                    parent_identity,
                    planned_regular,
                    expected_link_count=expected_link_count,
                )
        if not matches:
            raise SyncError("pending legacy regular publication active entry changed")
        if private_snapshot is not None:
            if not _recover_pending_regular_publication_private_alias(
                home,
                batch,
                record,
                phase,
                target.parent,
                parent_fd,
                (target.name, *candidates),
                active,
                expected_link_count=expected_link_count,
                label="pending legacy regular publication",
            ):
                raise SyncError(
                    "pending legacy regular publication private active entry "
                    "disappeared"
                )
            return
        # Child-entry churn is allowed. Move the exact active leaf out of the
        # public managed parent before deleting it so a pathname replacement at
        # the final boundary is preserved instead of unlinked.
        destructive_snapshot = _regular_file_snapshot_at(
            parent_fd,
            active_name,
            target.with_name(active_name),
            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
        )
        if phase == "produced":
            destructive_matches = _pending_regular_publication_snapshot_matches(
                destructive_snapshot,
                record,
                expected_link_count=expected_link_count,
            )
        else:
            assert planned_regular is not None
            destructive_matches = _regular_snapshot_matches(
                destructive_snapshot,
                parent_identity,
                planned_regular,
                expected_link_count=expected_link_count,
            )
        if (
            not destructive_matches
            or _pending_cleanup_internal_entry_plan(
                active_name,
                PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
                parent_identity,
            )
            != planned
        ):
            raise SyncError("pending legacy regular publication active entry changed")
        _isolate_and_delete_pending_regular_publication_candidate(
            home,
            batch,
            record,
            phase,
            target.parent,
            parent_fd,
            active_name,
            destructive_snapshot,
            expected_link_count=expected_link_count,
            label="pending legacy regular publication",
        )
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=parent_fd,
        )
        if _named_entry_identity(
            parent_fd, active_name
        ) is not None or not _bound_directory_matches(home, target.parent, parent_fd):
            raise SyncError(
                "pending legacy regular publication active entry reappeared"
            )
        active_entry_index.consume(
            target.parent,
            parent_identity,
            planned,
            active_name,
        )
    finally:
        _close_fd_quietly(parent_fd)


def _recover_pending_regular_publication_cleanup(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    phase: str,
    *,
    legacy_active_entry_index: _LegacyPendingRegularPublicationActiveEntryIndex
    | None = None,
) -> None:
    produced_authority = (
        phase == "produced"
        and record.is_regular()
        and record.action in {"create", "replace", "quarantine-replace"}
    )
    before_authority = (
        phase == "before"
        and record.before_is_regular()
        and record.action
        in {"replace", "quarantine-replace", "remove", "quarantine-remove"}
    )
    if not (produced_authority or before_authority):
        return
    if _pending_regular_publication_uses_receiptless_cleanup(
        batch,
        record,
        phase,
    ):
        _recover_legacy_pending_regular_publication_active_entry(
            home,
            batch,
            record,
            phase,
            active_entry_index=legacy_active_entry_index,
        )
        return
    journal = _read_pending_regular_publication_cleanup(home, batch, record, phase)
    if journal is None:
        return
    journal_snapshot, active_name, journal_phase, expected = journal
    lifecycle = _pending_regular_publication_cleanup_lifecycle(journal_snapshot)
    if journal_snapshot.parent_identity is None:
        raise SyncError("pending regular publication cleanup journal changed")
    private_authority_anchor = _read_pending_regular_publication_private_authority(
        home,
        batch,
        record,
        phase,
        expected,
        active_name,
        journal_snapshot.parent_identity,
    )
    private_authority = (
        lifecycle == "private-authority" or private_authority_anchor is not None
    )

    def verify_completed_cleanup(*, expected_evidence_link_count: int) -> None:
        evidence_path = (
            record.evidence if journal_phase == "produced" else record.before_evidence
        )
        if evidence_path is None:
            raise SyncError("pending regular publication cleanup evidence is missing")
        evidence = batch.batch_root / Path(*evidence_path.parts)
        evidence_snapshot = _read_regular_file_snapshot_beneath(
            home, evidence, require_managed_access=False
        )
        if (
            not _regular_snapshot_leaf_matches(
                evidence_snapshot,
                expected,
            )
            or evidence_snapshot.link_count != expected_evidence_link_count
        ):
            raise SyncError("pending regular publication cleanup evidence changed")

    target = home / Path(*record.target.parts)
    parent_fd = _open_directory_beneath(home, target.parent)
    try:
        if (
            record.planned_snapshot.parent_identity is None
            or _directory_identity(parent_fd) != record.planned_snapshot.parent_identity
            or not _bound_directory_matches(home, target.parent, parent_fd)
        ):
            raise SyncError("pending regular publication cleanup parent changed")
        if _recover_pending_regular_publication_private_alias(
            home,
            batch,
            record,
            phase,
            target.parent,
            parent_fd,
            (target.name, active_name),
            expected,
            expected_link_count=expected.link_count,
            label="pending regular publication",
        ):
            return
        if lifecycle != "public-authorized" or private_authority:
            _require_managed_regular_parent_chain_access(
                home,
                target.parent,
                bound_parent_fd=parent_fd,
            )
            if (
                private_authority
                and journal_phase == "before"
                and _named_entry_identity(parent_fd, active_name) is None
            ):
                restored_before = None
                if _named_entry_identity(parent_fd, target.name) is not None:
                    restored_before = _regular_file_snapshot_at(
                        parent_fd,
                        target.name,
                        target,
                        maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                    )
                if _regular_snapshot_matches(
                    restored_before,
                    expected.parent_identity,
                    expected,
                    expected_link_count=expected.link_count,
                ):
                    # Private authority proves the journal's destructive phase
                    # already completed. A later rollback step may then have
                    # relinked the receipt-bound before preimage at its canonical
                    # name before crashing. Accept only that exact identity,
                    # content, access policy, parent binding, and restored
                    # hard-link count; all other occupants remain fail-closed.
                    verify_completed_cleanup(
                        expected_evidence_link_count=expected.link_count,
                    )
                    confirmed_before = _regular_file_snapshot_at(
                        parent_fd,
                        target.name,
                        target,
                        maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                    )
                    if (
                        not _regular_snapshot_matches(
                            confirmed_before,
                            expected.parent_identity,
                            expected,
                            expected_link_count=expected.link_count,
                        )
                        or _named_entry_identity(parent_fd, active_name) is not None
                        or not _bound_directory_matches(
                            home,
                            target.parent,
                            parent_fd,
                        )
                    ):
                        raise SyncError(
                            "pending regular publication restored preimage changed"
                        )
                    return
            if not _pending_regular_publication_public_names_are_allowed(
                home,
                batch,
                record,
                phase,
                target.parent,
                parent_fd,
                (target.name, active_name),
            ):
                raise SyncError(
                    "pending regular publication public cleanup authority was "
                    "revoked; the public object was retained"
                )
            # Version 1 receipts predate the monotonic lifecycle. With no
            # surviving private alias they cannot distinguish an untouched
            # public candidate from evidence relinked after private deletion.
            # Only absence or the independently recorded rollback preimage is
            # therefore admissible, and neither is mutated here.
            verify_completed_cleanup(
                expected_evidence_link_count=expected.link_count - 1,
            )
            return
        target_snapshot: RegularFileSnapshot | None
        active_snapshot: RegularFileSnapshot | None
        try:
            os.stat(target.name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            target_snapshot = None
        else:
            target_snapshot = _regular_file_snapshot_at(
                parent_fd, target.name, target, maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES
            )
        try:
            os.stat(active_name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            active_snapshot = None
        else:
            active_snapshot = _regular_file_snapshot_at(
                parent_fd,
                active_name,
                target.with_name(active_name),
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
        if target_snapshot is not None and active_snapshot is not None:
            raise SyncError("pending regular publication cleanup is ambiguous")
        if target_snapshot is not None:
            if not _regular_snapshot_matches(
                target_snapshot,
                expected.parent_identity,
                expected,
                expected_link_count=expected.link_count,
            ):
                if journal_phase == "produced" and active_snapshot is None:
                    # A completed publication deletion can be followed by
                    # restoration of a replace preimage before the whole batch
                    # finalizer consumes this durable receipt. Leave the
                    # current target for the normal rollback state machine to
                    # validate; it has no authority to delete it here.
                    verify_completed_cleanup(
                        expected_evidence_link_count=expected.link_count - 1,
                    )
                    return
                raise SyncError("pending regular publication target changed")
            destructive_target_snapshot = _regular_file_snapshot_at(
                parent_fd,
                target.name,
                target,
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
            if not _regular_snapshot_matches(
                destructive_target_snapshot,
                expected.parent_identity,
                expected,
                expected_link_count=expected.link_count,
            ):
                raise SyncError("pending regular publication target changed")
            _require_managed_regular_parent_chain_access(
                home,
                target.parent,
                bound_parent_fd=parent_fd,
            )
            current_journal = _read_pending_regular_publication_cleanup(
                home,
                batch,
                record,
                phase,
            )
            if (
                current_journal is None
                or not _managed_state_snapshot_matches_bound_file_evidence(
                    current_journal[0],
                    journal_snapshot,
                )
                or _pending_regular_publication_cleanup_lifecycle(current_journal[0])
                != "public-authorized"
            ):
                raise SyncError(
                    "pending regular publication public cleanup authority changed"
                )
            _rename_noreplace_at(parent_fd, target.name, parent_fd, active_name)
            os.fsync(parent_fd)
            active_snapshot = _regular_file_snapshot_at(
                parent_fd,
                active_name,
                target.with_name(active_name),
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
        if active_snapshot is not None:
            if not _regular_snapshot_matches(
                active_snapshot,
                expected.parent_identity,
                expected,
                expected_link_count=expected.link_count,
            ):
                raise SyncError("pending regular publication active entry changed")
            _isolate_and_delete_pending_regular_publication_candidate(
                home,
                batch,
                record,
                phase,
                target.parent,
                parent_fd,
                active_name,
                expected,
                public_names=(target.name, active_name),
                expected_link_count=expected.link_count,
                label="pending regular publication",
            )
        else:
            verify_completed_cleanup(
                expected_evidence_link_count=expected.link_count - 1,
            )
    finally:
        _close_fd_quietly(parent_fd)
    # Keep this lifecycle receipt until whole-batch finalization.


def _pending_current_owner(
    home: Path,
    target: Path,
    owner_shas: dict[str, str],
    state_before_value: ManagedState,
) -> str:
    candidates = set(owner_shas) | set(state_before_value.owners)
    matches = sorted(
        owner for owner in candidates if _current_link(home, owner) == target
    )
    if len(matches) != 1:
        raise SyncError(f"pending current action has ambiguous owner: {target}")
    return matches[0]


def _managed_state_value_from_snapshot(
    home: Path,
    snapshot: ManagedStateFileSnapshot,
    manifest_entry_indexes: (
        dict[
            tuple[str, str],
            dict[tuple[PurePosixPath, PurePosixPath, str, str], LinkEntry],
        ]
        | None
    ) = None,
) -> ManagedState:
    if not snapshot.exists:
        return _empty_managed_state()
    assert snapshot.payload is not None
    return _managed_state_from_payload(
        home,
        _decode_managed_state_json(snapshot.payload, _state_path(home)),
        manifest_entry_indexes,
    )


def _pending_state_claim_semantics(
    home: Path,
    state: ManagedState,
    *,
    metadata_version: int,
) -> list[tuple[str, PurePosixPath, str, PurePosixPath | None, str, str, str]]:
    claims: list[
        tuple[str, PurePosixPath, str, PurePosixPath | None, str, str, str]
    ] = []
    for owner, release_sha in state.owners.items():
        target = PurePosixPath(*_current_link(home, owner).relative_to(home).parts)
        claims.append(
            (
                "current",
                target,
                "directory",
                None,
                owner,
                f"releases/{release_sha}",
                release_sha,
            )
        )
    for record in state.links.values():
        if metadata_version >= 6 and _record_materializes_regular_file(record):
            # Regular-file preimages are carried by the action record's exact
            # before evidence. Since pending metadata v6, they intentionally do
            # not masquerade as symlink claims. Legacy v4/v5 metadata still
            # describes every managed agents/*.toml target as a symlink claim.
            continue
        claims.append(
            (
                "managed",
                record.target,
                record.kind,
                record.source,
                record.owner,
                record.link_target,
                record.release_sha,
            )
        )
    return sorted(claims, key=lambda claim: (claim[0], claim[1].as_posix()))


def _pending_record_has_bound_create_absence(
    record: PendingLinkRecord,
) -> bool:
    snapshot = record.planned_snapshot
    return (
        record.action == "create"
        and snapshot.parent_identity is not None
        and snapshot.link_identity is None
        and snapshot.link_target is None
        and snapshot.ancestor_identity == snapshot.parent_identity
        and not snapshot.missing_parent_parts
    )


def _require_pending_record_bound_create_absence(
    record: PendingLinkRecord,
) -> None:
    if not _pending_record_has_bound_create_absence(record):
        raise SyncError(
            f"pending create target does not have a bound absence: {record.target}"
        )


def _verify_pending_record_bound_create_absence(
    home: Path,
    record: PendingLinkRecord,
    *,
    phase: str,
) -> None:
    _require_pending_record_bound_create_absence(record)
    target = home / Path(*record.target.parts)
    try:
        actual = _capture_reconcile_target_snapshot(home, target)
    except (OSError, SyncError) as error:
        raise SyncError(
            f"pending {phase} create absence could not be verified: {record.target}"
        ) from error
    if actual != record.planned_snapshot:
        raise SyncError(f"pending {phase} create absence changed: {record.target}")


def _pending_record_has_bound_retired_absence(
    record: PendingLinkRecord,
) -> bool:
    snapshot = record.planned_snapshot
    if (
        record.scope not in {"current", "managed"}
        or record.action != "retire-absent"
        or snapshot.link_identity is not None
        or snapshot.link_target is not None
    ):
        return False
    if snapshot.parent_identity is not None:
        return (
            snapshot.ancestor_identity == snapshot.parent_identity
            and not snapshot.missing_parent_parts
        )
    return snapshot.ancestor_identity is not None and bool(
        snapshot.missing_parent_parts
    )


def _require_pending_record_bound_retired_absence(
    record: PendingLinkRecord,
) -> None:
    if not _pending_record_has_bound_retired_absence(record):
        raise SyncError(
            f"pending retired target does not have a bound absence: {record.target}"
        )


def _verify_pending_record_bound_retired_absence(
    home: Path,
    record: PendingLinkRecord,
    *,
    phase: str,
) -> None:
    _require_pending_record_bound_retired_absence(record)
    target = home / Path(*record.target.parts)
    try:
        actual = _capture_reconcile_target_snapshot(home, target)
    except (OSError, SyncError) as error:
        raise SyncError(
            f"pending {phase} retired absence could not be verified: {record.target}"
        ) from error
    if actual != record.planned_snapshot:
        raise SyncError(f"pending {phase} retired absence changed: {record.target}")


def _pending_record_has_bound_foreign_relinquishment(
    record: PendingLinkRecord,
) -> bool:
    snapshot = record.planned_snapshot
    return (
        record.scope == "managed"
        and record.action == PENDING_RELINQUISH_FOREIGN_ACTION
        and snapshot.parent_identity is not None
        and snapshot.link_identity is not None
        and snapshot.ancestor_identity == snapshot.parent_identity
        and not snapshot.missing_parent_parts
    )


def _require_pending_record_bound_foreign_relinquishment(
    record: PendingLinkRecord,
) -> None:
    if not _pending_record_has_bound_foreign_relinquishment(record):
        raise SyncError(
            "pending foreign relinquishment is not bound to an occupied target: "
            f"{record.target}"
        )


def _verify_pending_record_bound_foreign_relinquishment(
    home: Path,
    record: PendingLinkRecord,
    *,
    phase: str,
) -> None:
    _require_pending_record_bound_foreign_relinquishment(record)
    target = home / Path(*record.target.parts)
    try:
        actual = _capture_reconcile_target_snapshot(
            home,
            target,
            capture_regular_content=(
                record.planned_snapshot.regular_sha256 is not None
            ),
        )
    except (OSError, SyncError) as error:
        raise SyncError(
            f"pending {phase} foreign relinquishment could not be verified: "
            f"{record.target}"
        ) from error
    if not _reconcile_target_snapshot_matches(
        actual,
        record.planned_snapshot,
    ):
        raise SyncError(
            f"pending {phase} foreign relinquishment changed: {record.target}"
        )


def _stage_pending_link_claims(
    home: Path,
    batch_root: Path,
    phase: str,
    state: ManagedState,
    records: tuple[PendingLinkRecord, ...],
    created_parent_identities: dict[Path, tuple[int, int]],
) -> tuple[PendingLinkClaim, ...]:
    if phase not in {"before", "after"}:
        raise SyncError(f"unsupported pending claim phase: {phase}")
    record_by_target = {(record.scope, record.target): record for record in records}
    claims: list[PendingLinkClaim] = []
    for semantic in _pending_state_claim_semantics(
        home,
        state,
        metadata_version=PENDING_LINK_METADATA_VERSION,
    ):
        (
            scope,
            target,
            kind,
            source,
            owner,
            link_target,
            release_sha,
        ) = semantic
        record = record_by_target.get((scope, target))
        if (
            phase == "before"
            and record is not None
            and record.action
            in {
                "create",
                "retire-absent",
                PENDING_RELINQUISH_FOREIGN_ACTION,
            }
        ):
            if record.action == "create":
                _verify_pending_record_bound_create_absence(
                    home,
                    record,
                    phase="before-state",
                )
            elif record.action == "retire-absent":
                _verify_pending_record_bound_retired_absence(
                    home,
                    record,
                    phase="before-state",
                )
            else:
                _verify_pending_record_bound_foreign_relinquishment(
                    home,
                    record,
                    phase="before-state",
                )
            continue
        canonical_target = home / Path(*target.parts)
        if phase == "after" and record is not None:
            if record.action not in {"create", "replace", "quarantine-replace"}:
                raise SyncError(
                    f"pending after-state still claims a removed target: {target}"
                )
            if (
                record.kind != kind
                or record.source != source
                or record.owner != owner
                or record.link_target != link_target
                or record.release_sha != release_sha
                or record.evidence is None
            ):
                raise SyncError(f"pending after-state claim changed: {target}")
            source_path = batch_root / Path(*record.evidence.parts)
            source_snapshot = _read_symlink_snapshot_beneath(home, source_path)
            parent_identity = record.planned_snapshot.parent_identity
            if parent_identity is None:
                raise SyncError(f"pending after-state parent is unbound: {target}")
        else:
            source_path = canonical_target
            source_snapshot = _read_symlink_snapshot_beneath(home, source_path)
            parent_identity = source_snapshot.parent_identity
            if phase == "before" and record is not None:
                if not _symlink_snapshot_matches(
                    source_snapshot,
                    record.planned_snapshot.parent_identity,
                    record.planned_snapshot.link_identity,
                    record.planned_snapshot.link_target,
                ):
                    raise SyncError(
                        f"pending before-state claim changed after planning: {target}"
                    )
        if source_snapshot.link_target != link_target:
            raise SyncError(f"pending {phase}-state claim target changed: {target}")
        index = len(claims)
        evidence = PurePosixPath("pending", "claims", phase, f"{index:08d}")
        evidence_path = batch_root / Path(*evidence.parts)
        evidence_plan = _capture_reconcile_target_snapshot(home, evidence_path)
        evidence_snapshot = _publish_symlink_hardlink_beneath(
            home,
            source_path,
            evidence_path,
            source_snapshot,
            evidence_plan,
            created_parent_identities,
        )
        if evidence_snapshot.link_identity != source_snapshot.link_identity:
            raise SyncError(f"pending {phase}-state claim evidence changed: {target}")
        claims.append(
            PendingLinkClaim(
                index=index,
                scope=scope,
                target=target,
                kind=kind,
                source=source,
                owner=owner,
                link_target=link_target,
                release_sha=release_sha,
                parent_identity=parent_identity,
                link_identity=source_snapshot.link_identity,
                evidence=evidence,
            )
        )
    return tuple(claims)


def _pending_link_record_for_action(
    home: Path,
    scope: str,
    action: ReconcileAction,
    desired_by_target: dict[PurePosixPath, LinkEntry],
    owner_shas: dict[str, str],
    current_owner_state: ManagedState,
    index: int,
) -> PendingLinkRecord:
    if scope not in {"current", "managed"}:
        raise SyncError(f"unsupported pending transaction scope: {scope}")
    if action.planned_snapshot is None:
        raise SyncError(f"pending action has no planning snapshot: {action.target}")
    try:
        relative_target = action.target.relative_to(home)
    except ValueError as error:
        raise SyncError(f"pending target is outside home: {action.target}") from error
    target = PurePosixPath(*relative_target.parts)
    producing = action.action in {"create", "replace", "quarantine-replace"}
    destructive = action.action in {
        "replace",
        "quarantine-replace",
        "remove",
        "quarantine-remove",
    }
    relinquishing_foreign = action.action == PENDING_RELINQUISH_FOREIGN_ACTION
    if not producing and not destructive and not relinquishing_foreign:
        raise SyncError(f"unsupported pending action: {action.action}")
    source: PurePosixPath | None = None
    owner: str | None = None
    release_sha: str | None = None
    link_target = action.link_target if producing else None
    materialization = action.materialization if producing or destructive else "symlink"
    if materialization not in {"symlink", "regular"}:
        raise SyncError(f"unsupported pending materialization: {materialization}")
    if materialization == "regular" and scope != "managed":
        raise SyncError("only managed targets may materialize as regular files")
    removed_link_key = action.removed_link_key
    if removed_link_key is not None:
        removed_link_key = _validate_removed_link_key(
            removed_link_key,
            "pending removed link",
        )
    planned_regular = _regular_snapshot_from_reconcile(action.planned_snapshot)
    before_materialization = (
        ("regular" if planned_regular is not None else "symlink")
        if destructive
        else None
    )
    if (
        before_materialization == "regular"
        and materialization == "symlink"
        and not _regular_to_symlink_reconcile_action_is_typed(action)
    ):
        raise SyncError(
            f"regular-file preimage has an untyped symlink action: {target}"
        )
    if scope == "managed" and relinquishing_foreign:
        entry = desired_by_target.get(target)
        state_record = current_owner_state.links.get(target)
        if (
            not _allows_optional_claim_relinquishment(target, entry)
            or state_record is None
            or state_record.kind != action.kind
            or target != state_record.target
            or action.planned_snapshot.link_identity is None
            or action.planned_snapshot.link_target == state_record.link_target
        ):
            raise SyncError(
                f"pending foreign relinquishment is not an optional state claim: "
                f"{target}"
            )
    elif scope == "managed" and producing:
        entry = desired_by_target.get(target)
        if entry is None:
            raise SyncError(f"pending managed action has no desired entry: {target}")
        source = entry.source
        owner = entry.owner
        release_sha = owner_shas.get(owner)
        if release_sha is None:
            raise SyncError(f"pending managed action has no release SHA: {owner}")
        release_sha = _validate_release_sha(release_sha)
        if (
            entry.target != target
            or entry.kind != action.kind
            or _desired_link_target(home, entry) != action.link_target
        ):
            raise SyncError(f"pending managed action changed after planning: {target}")
    elif scope == "current":
        if relinquishing_foreign:
            raise SyncError(
                f"pending current target cannot relinquish foreign ownership: {target}"
            )
        owner = _pending_current_owner(
            home,
            action.target,
            owner_shas,
            current_owner_state,
        )
        if producing:
            parts = action.link_target.split("/")
            if len(parts) != 2 or parts[0] != "releases":
                raise SyncError(
                    f"pending current target is invalid: {action.link_target}"
                )
            release_sha = _validate_release_sha(parts[1])
            if owner_shas.get(owner) != release_sha:
                raise SyncError(
                    f"pending current release SHA changed for owner {owner}"
                )

    leaf = f"{index:08d}"
    return PendingLinkRecord(
        index=index,
        scope=scope,
        action=action.action,
        target=target,
        kind=action.kind,
        planned_snapshot=action.planned_snapshot,
        source=source,
        owner=owner,
        link_target=link_target,
        release_sha=release_sha,
        before_materialization=before_materialization,
        materialization=materialization,
        removed_link_key=removed_link_key,
        regular_sha256=None,
        regular_size=None,
        regular_mode=None,
        regular_uid=None,
        regular_gid=None,
        regular_link_count=None,
        before_evidence=(
            PurePosixPath("pending", "before", leaf) if destructive else None
        ),
        before_evidence_identity=(
            action.planned_snapshot.link_identity if destructive else None
        ),
        backup=(PurePosixPath("links") / target if destructive else None),
        stage=(PurePosixPath("pending", "stage", leaf) if producing else None),
        stage_identity=None,
        evidence=(PurePosixPath("pending", "evidence", leaf) if producing else None),
        evidence_identity=None,
        publication_cleanup=(
            PurePosixPath("pending", "cleanup", leaf + ".json")
            if (producing and materialization == "regular")
            or (destructive and before_materialization == "regular")
            else None
        ),
    )


def _projected_pending_snapshot_payload(
    home: Path,
    target: Path,
    snapshot: ReconcileTargetSnapshot | None,
    *link_targets: str | None,
) -> dict[str, Any]:
    relative_parent = target.parent.relative_to(home)
    candidate_targets = [
        snapshot.link_target if snapshot is not None else None,
        *link_targets,
    ]
    link_target = max(
        candidate_targets,
        key=lambda value: len(json.dumps(value, sort_keys=False).encode("utf-8")),
    )
    projects_regular = snapshot is not None and snapshot.regular_sha256 is not None
    maximum_scalar = _MAX_PENDING_IDENTITY[0]
    return {
        "parent_identity": _identity_payload(_MAX_PENDING_IDENTITY),
        "link_identity": _identity_payload(_MAX_PENDING_IDENTITY),
        "link_target": link_target,
        "ancestor_identity": _identity_payload(_MAX_PENDING_IDENTITY),
        "missing_parent_parts": list(relative_parent.parts),
        "regular_sha256": _MAX_PENDING_DIGEST if projects_regular else None,
        "regular_size": MAX_ARCHIVE_MEMBER_BYTES if projects_regular else None,
        "regular_mode": 0o7777 if projects_regular else None,
        "regular_uid": maximum_scalar if projects_regular else None,
        "regular_gid": maximum_scalar if projects_regular else None,
        "regular_link_count": maximum_scalar if projects_regular else None,
    }


def _projected_pending_record_payload(
    home: Path,
    scope: str,
    action: ReconcileAction,
    state_before_value: ManagedState,
    planning_state_before: ManagedState,
    state_after_value: ManagedState,
    index: int,
) -> dict[str, Any]:
    target = PurePosixPath(*action.target.relative_to(home).parts)
    producing = action.action in {"create", "replace", "quarantine-replace"}
    destructive = action.action in {
        "replace",
        "quarantine-replace",
        "remove",
        "quarantine-remove",
    }
    source: PurePosixPath | None = None
    owner: str | None = None
    release_sha: str | None = None
    if scope == "managed" and producing:
        record = state_after_value.links.get(target)
        if record is None:
            raise SyncError(f"pending managed action has no projected state: {target}")
        source = record.source
        owner = record.owner
        release_sha = record.release_sha
    elif scope == "current":
        owner = _pending_current_owner(
            home,
            action.target,
            state_after_value.owners,
            planning_state_before,
        )
        if producing:
            release_sha = state_after_value.owners.get(owner)
            if release_sha is None:
                raise SyncError(
                    f"pending current action has no projected release: {owner}"
                )
    leaf = f"{index:08d}"
    return {
        "index": index,
        "scope": scope,
        "action": action.action,
        "target": target.as_posix(),
        "kind": action.kind,
        "planned_before": _projected_pending_snapshot_payload(
            home,
            action.target,
            action.planned_snapshot,
            action.expected_link_target,
            action.link_target,
        ),
        "source": source.as_posix() if source is not None else None,
        "owner": owner,
        "link_target": action.link_target if producing else None,
        "release_sha": release_sha if producing else None,
        "before_materialization": (
            "regular"
            if destructive
            and action.planned_snapshot is not None
            and _regular_snapshot_from_reconcile(action.planned_snapshot) is not None
            else "symlink"
            if destructive
            else None
        ),
        "materialization": (
            action.materialization if producing or destructive else "symlink"
        ),
        "removed_link": action.removed_link_key,
        "regular_sha256": "f" * 64
        if producing and action.materialization == "regular"
        else None,
        "regular_size": MAX_ARCHIVE_MEMBER_BYTES
        if producing and action.materialization == "regular"
        else None,
        "regular_mode": 0o600
        if producing and action.materialization == "regular"
        else None,
        "regular_uid": _MAX_PENDING_IDENTITY
        if producing and action.materialization == "regular"
        else None,
        "regular_gid": None,
        "regular_link_count": 2
        if producing and action.materialization == "regular"
        else None,
        "before_evidence": (
            PurePosixPath("pending", "before", leaf).as_posix() if destructive else None
        ),
        "before_evidence_identity": (
            _identity_payload(_MAX_PENDING_IDENTITY) if destructive else None
        ),
        "backup": (
            (PurePosixPath("links") / target).as_posix() if destructive else None
        ),
        "stage": (
            PurePosixPath("pending", "stage", leaf).as_posix() if producing else None
        ),
        "stage_identity": (
            _identity_payload(_MAX_PENDING_IDENTITY) if producing else None
        ),
        "evidence": (
            PurePosixPath("pending", "evidence", leaf).as_posix() if producing else None
        ),
        "evidence_identity": (
            _identity_payload(_MAX_PENDING_IDENTITY) if producing else None
        ),
        "publication_cleanup": (
            PurePosixPath("pending", "cleanup", leaf + ".json").as_posix()
            if (producing and action.materialization == "regular")
            or (
                destructive
                and action.planned_snapshot is not None
                and _regular_snapshot_from_reconcile(action.planned_snapshot)
                is not None
            )
            else None
        ),
    }


