def _pending_regular_staging_publication_guard_payload(
    batch_root: Path,
    batch_root_identity: tuple[int, int],
    record: PendingLinkRecord,
) -> bytes:
    if record.publication_cleanup is None or not record.is_regular():
        raise SyncError("pending regular staging guard has no record authority")
    return _bounded_json_document(
        {
            "version": 1,
            "phase": "staging-publication",
            "batch": batch_root.name,
            "batch_root_identity": _identity_payload(batch_root_identity),
            "record": record.index,
            "stage": record.stage.as_posix() if record.stage is not None else None,
            "evidence": (
                record.evidence.as_posix() if record.evidence is not None else None
            ),
        },
        max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        overflow_error="pending regular staging guard exceeds the size limit",
    )


def _publish_pending_regular_staging_publication_guard(
    home: Path,
    batch_root: Path,
    batch_root_identity: tuple[int, int],
    record: PendingLinkRecord,
) -> tuple[Path, ManagedStateFileSnapshot]:
    if record.publication_cleanup is None:
        raise SyncError("pending regular staging guard path is missing")
    guard_path = batch_root / Path(*record.publication_cleanup.parts)
    guard = _publish_atomic_exclusive_internal_file(
        home,
        guard_path,
        _pending_regular_staging_publication_guard_payload(
            batch_root,
            batch_root_identity,
            record,
        ),
    )
    parent_fd = _open_directory_beneath(home, guard_path.parent)
    try:
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            guard_path,
            parent_fd,
            guard,
        )
        os.fsync(parent_fd)
    finally:
        _close_fd_quietly(parent_fd)
    return guard_path, guard


def _delete_pending_regular_staging_publication_guard(
    home: Path,
    guard_path: Path,
    guard: ManagedStateFileSnapshot,
) -> None:
    parent_fd = _open_directory_beneath(home, guard_path.parent)
    try:
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            guard_path,
            parent_fd,
            guard,
        )
        _isolate_and_delete_pending_cleanup_file(
            home,
            guard_path,
            parent_fd,
            guard,
            label="pending regular staging publication guard",
        )
        os.fsync(parent_fd)
    finally:
        _close_fd_quietly(parent_fd)


def _pending_terminal_regular_targets_from_records(
    records: tuple[PendingLinkRecord, ...],
    *,
    phase: str,
) -> tuple[PendingRegularTargetExpectation, ...]:
    if phase not in {"before", "after"}:
        raise SyncError("pending terminal cleanup phase is invalid")
    targets: list[PendingRegularTargetExpectation] = []
    seen: set[PurePosixPath] = set()
    for record in records:
        if phase == "after":
            if not record.is_regular() or record.action not in {
                "create",
                "replace",
                "quarantine-replace",
            }:
                continue
            parent_identity = record.planned_snapshot.parent_identity
            file_identity = record.evidence_identity
            digest = record.regular_sha256
            size = record.regular_size
            mode = record.regular_mode
            uid = record.regular_uid
        else:
            planned = _regular_snapshot_from_reconcile(record.planned_snapshot)
            if planned is None or record.action not in {
                "replace",
                "quarantine-replace",
                "remove",
                "quarantine-remove",
            }:
                continue
            parent_identity = record.planned_snapshot.parent_identity
            file_identity = planned.file_identity
            digest = planned.sha256
            size = planned.size
            mode = planned.mode
            uid = planned.uid
        if (
            parent_identity is None
            or file_identity is None
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
            or not isinstance(size, int)
            or isinstance(size, bool)
            or size < 0
            or mode != 0o600
            or uid != os.geteuid()
        ):
            raise SyncError(
                f"pending terminal regular target is incomplete: {record.target}"
            )
        if record.target in seen:
            raise SyncError(
                f"pending terminal regular target is duplicated: {record.target}"
            )
        seen.add(record.target)
        targets.append(
            PendingRegularTargetExpectation(
                target=record.target,
                parent_identity=parent_identity,
                file_identity=file_identity,
                sha256=digest,
                size=size,
                mode=mode,
                uid=uid,
            )
        )
    return tuple(sorted(targets, key=lambda target: target.target.as_posix()))


def _pending_terminal_regular_targets(
    batch: PendingLinkBatch,
    *,
    phase: str,
) -> tuple[PendingRegularTargetExpectation, ...]:
    if phase == "before":
        return batch.terminal_regular_before
    if phase == "after":
        return batch.terminal_regular_after
    raise SyncError("pending terminal cleanup phase is invalid")


def _pending_terminal_cleanup_ticket_payload(
    batch: PendingLinkBatch,
    marker: ManagedStateFileSnapshot,
    *,
    phase: str,
) -> bytes:
    if (
        marker.parent_identity is None
        or marker.file_identity is None
        or marker.payload is None
        or marker.mode != 0o600
    ):
        raise SyncError("pending terminal cleanup marker is not fully bound")
    marker_path = (
        PENDING_STATE_COMMIT_MARKER
        if phase == "after"
        else PENDING_STATE_ROLLBACK_MARKER
    )
    targets = _pending_terminal_regular_targets(batch, phase=phase)
    return _bounded_json_document(
        {
            "version": 4,
            "batch": batch.batch_root.name,
            "batch_root_identity": _identity_payload(batch.batch_root_identity),
            "finalization_marker": {
                "phase": phase,
                "path": marker_path.as_posix(),
                "parent_identity": _identity_payload(marker.parent_identity),
                "file_identity": _identity_payload(marker.file_identity),
                "mode": marker.mode,
                "sha256": hashlib.sha256(marker.payload).hexdigest(),
            },
            "terminal_regular_targets": [
                {
                    "target": target.target.as_posix(),
                    "parent_identity": _identity_payload(target.parent_identity),
                    "file_identity": _identity_payload(target.file_identity),
                    "sha256": target.sha256,
                    "size": target.size,
                    "mode": target.mode,
                    "uid": target.uid,
                }
                for target in targets
            ],
        },
        max_bytes=MAX_PENDING_TERMINAL_CLEANUP_TICKET_BYTES,
        overflow_error="pending terminal cleanup ticket exceeds the size limit",
    )


def _parse_pending_terminal_regular_targets(
    raw_targets: object,
    *,
    batch_name: str,
) -> tuple[PendingRegularTargetExpectation, ...]:
    if not isinstance(raw_targets, list) or len(raw_targets) > MAX_PENDING_LINK_RECORDS:
        raise SyncError(f"pending terminal regular targets are invalid: {batch_name}")
    expected_fields = {
        "target",
        "parent_identity",
        "file_identity",
        "sha256",
        "size",
        "mode",
        "uid",
    }
    targets: list[PendingRegularTargetExpectation] = []
    previous_target: PurePosixPath | None = None
    for raw_target in raw_targets:
        if not isinstance(raw_target, dict) or set(raw_target) != expected_fields:
            raise SyncError(f"pending terminal regular target changed: {batch_name}")
        target = _validate_relative_path(
            raw_target.get("target"),
            "pending terminal regular target",
        )
        if (
            previous_target is not None
            and target.as_posix() <= previous_target.as_posix()
        ):
            raise SyncError(
                f"pending terminal regular target order changed: {batch_name}"
            )
        previous_target = target
        parent_identity = _parse_pending_identity(
            raw_target.get("parent_identity"),
            "pending terminal regular parent identity",
        )
        file_identity = _parse_pending_identity(
            raw_target.get("file_identity"),
            "pending terminal regular file identity",
        )
        digest = raw_target.get("sha256")
        size = raw_target.get("size")
        mode = raw_target.get("mode")
        uid = raw_target.get("uid")
        if (
            parent_identity is None
            or file_identity is None
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
            or not isinstance(size, int)
            or isinstance(size, bool)
            or size < 0
            or mode != 0o600
            or uid != os.geteuid()
        ):
            raise SyncError(f"pending terminal regular target changed: {batch_name}")
        targets.append(
            PendingRegularTargetExpectation(
                target=target,
                parent_identity=parent_identity,
                file_identity=file_identity,
                sha256=digest,
                size=size,
                mode=mode,
                uid=uid,
            )
        )
    return tuple(targets)


def _validate_pending_terminal_regular_targets_for_state(
    home: Path,
    expectations: tuple[PendingRegularTargetExpectation, ...],
    state: ManagedState,
    records: tuple[PendingLinkRecord, ...],
    *,
    phase: str,
    source_expectations_by_owner: (dict[str, PendingReleaseExpectation] | None) = None,
    regular_source_evidence: _PendingRegularSourceEvidenceBudget | None = None,
) -> None:
    if (source_expectations_by_owner is None) != (regular_source_evidence is None):
        raise SyncError("pending regular-file source evidence cache is incomplete")
    state_items = _terminal_regular_state_items(
        state,
        records,
        phase=phase,
    )
    expected_targets = tuple(target for target, _state_record, _record in state_items)
    if tuple(expectation.target for expectation in expectations) != expected_targets:
        raise SyncError("pending transaction lacks complete regular terminal authority")
    _require_pending_terminal_regular_group_size_budget(
        tuple(expectation.size for expectation in expectations),
        phase=phase,
    )
    file_identities: set[tuple[int, int]] = set()
    for expectation, (_target, state_record, pending_record) in zip(
        expectations,
        state_items,
    ):
        if expectation.file_identity in file_identities:
            raise SyncError(
                "pending transaction reuses a regular terminal file identity"
            )
        file_identities.add(expectation.file_identity)
        if regular_source_evidence is None:
            source_payload = _read_regular_source_payload(
                home,
                _record_regular_source_path(home, state_record),
            )
            source_digest = hashlib.sha256(source_payload).hexdigest()
            source_size = len(source_payload)
        else:
            assert source_expectations_by_owner is not None
            source_expectation = source_expectations_by_owner.get(state_record.owner)
            if source_expectation is None:
                raise SyncError(
                    "pending terminal regular target lacks source release binding: "
                    f"{expectation.target}"
                )
            source_evidence = regular_source_evidence.evidence(
                home,
                state_record,
                source_expectation,
            )
            source_digest = source_evidence.sha256
            source_size = source_evidence.size
        if expectation.sha256 != source_digest or expectation.size != source_size:
            raise SyncError(
                "pending terminal regular target does not match its immutable "
                f"release source: {expectation.target}"
            )
        if (
            phase == "after"
            and pending_record is not None
            and pending_record.action in {"create", "replace", "quarantine-replace"}
        ):
            expected = PendingRegularTargetExpectation(
                target=expectation.target,
                parent_identity=pending_record.planned_snapshot.parent_identity,
                file_identity=pending_record.evidence_identity,
                sha256=pending_record.regular_sha256,
                size=pending_record.regular_size,
                mode=pending_record.regular_mode,
                uid=pending_record.regular_uid,
            )
            if expectation != expected:
                raise SyncError(
                    "pending produced regular terminal authority changed: "
                    f"{expectation.target}"
                )
        elif (
            phase == "before"
            and pending_record is not None
            and pending_record.action
            in {"replace", "quarantine-replace", "remove", "quarantine-remove"}
        ):
            planned = _regular_snapshot_from_reconcile(pending_record.planned_snapshot)
            if planned is None:
                raise SyncError(
                    "pending regular terminal preimage is missing: "
                    f"{expectation.target}"
                )
            expected = PendingRegularTargetExpectation(
                target=expectation.target,
                parent_identity=planned.parent_identity,
                file_identity=planned.file_identity,
                sha256=planned.sha256,
                size=planned.size,
                mode=planned.mode,
                uid=planned.uid,
            )
            if expectation != expected:
                raise SyncError(
                    "pending regular terminal preimage authority changed: "
                    f"{expectation.target}"
                )


def _read_pending_cleanup_ticket(
    home: Path,
    ticket_path: Path,
    *,
    expected_ticket_identity: tuple[int, int] | None = None,
    allow_temporary: bool = False,
    _captured_snapshot: ManagedStateFileSnapshot | None = None,
) -> PendingBatchCleanupTicket | None:
    """Read and parse one ticket, or purely parse an admitted temp snapshot.

    ``_captured_snapshot`` is restricted to temp recovery.  Its caller must
    have already read the exact object and admitted its access policy.  This
    mode performs no filesystem revalidation, so a schema rejection can be
    distinguished from uncertain I/O or identity/policy drift during capture.
    """
    if allow_temporary:
        batch_name = _pending_cleanup_ticket_temp_batch_name(ticket_path.name)
        if batch_name is None:
            raise SyncError("pending cleanup ticket temp has an invalid file name")
    else:
        suffix = PENDING_CLEANUP_TICKET_SUFFIX
        if not ticket_path.name.endswith(suffix):
            raise SyncError("pending cleanup ticket has an invalid file name")
        batch_name = ticket_path.name[: -len(suffix)]
    if (
        len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
    ):
        raise SyncError("pending cleanup ticket has an invalid batch name")
    if _captured_snapshot is not None and not allow_temporary:
        raise ValueError("captured cleanup ticket parsing is limited to temp files")
    index_fd = -1
    try:
        if _captured_snapshot is None:
            index_fd = _open_directory_beneath(home, ticket_path.parent)
            snapshot = _read_managed_state_file_snapshot(
                home,
                ticket_path,
                index_fd,
                expected_identity=expected_ticket_identity,
            )
        else:
            snapshot = _captured_snapshot
            if (
                expected_ticket_identity is not None
                and snapshot.file_identity != expected_ticket_identity
            ):
                raise SyncError(
                    f"pending cleanup ticket identity changed: {batch_name}"
                )
        if not snapshot.exists:
            return None
        if snapshot.payload is None or (
            len(snapshot.payload) > MAX_PENDING_TERMINAL_CLEANUP_TICKET_BYTES
        ):
            raise SyncError(f"pending cleanup ticket exceeds its limit: {batch_name}")
        if snapshot.mode != 0o600:
            raise SyncError(f"pending cleanup ticket mode changed: {batch_name}")
        if snapshot.uid != os.geteuid():
            raise SyncError(f"pending cleanup ticket owner changed: {batch_name}")
        if _captured_snapshot is None:
            _require_pending_cleanup_file_snapshot_access_policy(
                home,
                ticket_path,
                index_fd,
                snapshot,
            )
        data = _decode_managed_state_json(snapshot.payload, ticket_path)
        version = data.get("version")
        if type(version) is not int or version not in {1, 2, 3, 4, 5, 6, 7}:
            raise SyncError(
                f"pending cleanup ticket has unsupported fields: {batch_name}"
            )
        if version == 1:
            expected_top_level_fields = {
                "version",
                "batch",
                "batch_root_identity",
                "commit_marker",
            }
        elif version in {2, 3, 4}:
            expected_top_level_fields = {
                "version",
                "batch",
                "batch_root_identity",
                "finalization_marker",
            }
            if version == 4:
                expected_top_level_fields.add("terminal_regular_targets")
        elif version in {5, 7}:
            expected_top_level_fields = {
                "version",
                "kind",
                "batch",
                "batch_root_identity",
                "quarantine_root_identity",
                "isolated_name",
                "leaf",
                "metadata",
            }
        else:
            expected_top_level_fields = {
                "version",
                "kind",
                "batch",
                "quarantine_root_identity",
                "public_target",
                "public_parent_identity",
                "payload",
            }
        if set(data) != expected_top_level_fields:
            raise SyncError(
                f"pending cleanup ticket has unsupported fields: {batch_name}"
            )
        if data.get("batch") != batch_name:
            raise SyncError(f"pending cleanup ticket batch changed: {batch_name}")
        if version == 6:
            if len(snapshot.payload) > MAX_PENDING_CLEANUP_TICKET_BYTES:
                raise SyncError(
                    f"pending cleanup ticket exceeds its limit: {batch_name}"
                )
            quarantine_root_identity = _parse_pending_identity(
                data.get("quarantine_root_identity"),
                "pending cleanup quarantine root identity",
            )
            public_target = _validate_relative_path(
                data.get("public_target"),
                "pending ephemeral cleanup target",
            )
            public_parent_identity = _parse_pending_identity(
                data.get("public_parent_identity"),
                "pending ephemeral cleanup public parent identity",
            )
            payload = data.get("payload")
            payload_fields = {
                "file_identity",
                "sha256",
                "size",
                "mode",
                "uid",
                "gid",
                "link_count",
            }
            if (
                data.get("kind") != "ephemeral-quarantine-leaf"
                or quarantine_root_identity is None
                or public_parent_identity is None
                or not isinstance(payload, dict)
                or set(payload) != payload_fields
            ):
                raise SyncError(
                    f"pending cleanup ephemeral leaf authority changed: {batch_name}"
                )
            payload_file_identity = _parse_pending_identity(
                payload.get("file_identity"),
                "pending cleanup ephemeral payload identity",
            )
            payload_sha256 = payload.get("sha256")
            payload_size = payload.get("size")
            payload_mode = payload.get("mode")
            payload_uid = payload.get("uid")
            payload_gid = payload.get("gid")
            payload_link_count = payload.get("link_count")
            if (
                payload_file_identity is None
                or not isinstance(payload_sha256, str)
                or re.fullmatch(r"[0-9a-f]{64}", payload_sha256) is None
                or type(payload_size) is not int
                or payload_size < 0
                or payload_size > MAX_ARCHIVE_MEMBER_BYTES
                or payload_mode != 0o600
                or payload_uid != os.geteuid()
                or type(payload_gid) is not int
                or payload_gid < 0
                or type(payload_link_count) is not int
                or payload_link_count < 1
            ):
                raise SyncError(
                    f"pending cleanup ephemeral leaf authority changed: {batch_name}"
                )
            expected_payload = _bounded_json_document(
                {
                    "version": 6,
                    "kind": "ephemeral-quarantine-leaf",
                    "batch": batch_name,
                    "quarantine_root_identity": _identity_payload(
                        quarantine_root_identity
                    ),
                    "public_target": public_target.as_posix(),
                    "public_parent_identity": _identity_payload(public_parent_identity),
                    "payload": {
                        "file_identity": _identity_payload(payload_file_identity),
                        "sha256": payload_sha256,
                        "size": payload_size,
                        "mode": payload_mode,
                        "uid": payload_uid,
                        "gid": payload_gid,
                        "link_count": payload_link_count,
                    },
                },
                max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
                overflow_error="pending cleanup ticket exceeds the size limit",
            )
            if snapshot.payload != expected_payload:
                raise SyncError(f"pending cleanup ticket changed: {batch_name}")
            if _captured_snapshot is None:
                _require_pending_cleanup_file_snapshot_access_policy(
                    home,
                    ticket_path,
                    index_fd,
                    snapshot,
                )
            quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
            return PendingBatchCleanupTicket(
                version=version,
                phase="ephemeral-quarantine-leaf",
                path=ticket_path,
                snapshot=snapshot,
                batch_root=quarantine_root / batch_name,
                batch_root_identity=quarantine_root_identity,
                marker_path=None,
                marker_parent_identity=None,
                marker_file_identity=None,
                marker_mode=None,
                marker_sha256=None,
                kind="ephemeral-quarantine-leaf",
                quarantine_root_identity=quarantine_root_identity,
                public_target=public_target,
                public_parent_identity=public_parent_identity,
                payload_file_identity=payload_file_identity,
                payload_sha256=payload_sha256,
                payload_size=payload_size,
                payload_mode=payload_mode,
                payload_uid=payload_uid,
                payload_gid=payload_gid,
                payload_link_count=payload_link_count,
            )
        batch_identity = _parse_pending_identity(
            data.get("batch_root_identity"),
            "pending cleanup batch root identity",
        )
        if batch_identity is None:
            raise SyncError(f"pending cleanup batch identity is missing: {batch_name}")
        batch_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH / batch_name
        if version in {5, 7}:
            if len(snapshot.payload) > MAX_PENDING_CLEANUP_TICKET_BYTES:
                raise SyncError(
                    f"pending cleanup ticket exceeds its limit: {batch_name}"
                )
            quarantine_root_identity = _parse_pending_identity(
                data.get("quarantine_root_identity"),
                "pending cleanup quarantine root identity",
            )
            leaf = data.get("leaf")
            metadata = data.get("metadata")
            expected_kind = (
                "ephemeral-quarantine"
                if version == 5
                else "ephemeral-quarantine-scaffold"
            )
            leaf_fields_valid = (
                isinstance(leaf, dict)
                and set(leaf) == {"path", "directory_identity"}
                and leaf.get("path") == "leaf"
                if version == 5
                else leaf is None
            )
            expected_metadata_fields = (
                {"path", "file_identity", "mode", "sha256"}
                if version == 5
                else {"path", "file_identity", "mode", "size", "sha256"}
            )
            if (
                data.get("kind") != expected_kind
                or quarantine_root_identity is None
                or data.get("isolated_name")
                != _pending_cleanup_isolated_batch_name(batch_name)
                or not leaf_fields_valid
                or not isinstance(metadata, dict)
                or set(metadata) != expected_metadata_fields
                or metadata.get("path") != "metadata.json"
            ):
                raise SyncError(
                    f"pending cleanup ephemeral authority changed: {batch_name}"
                )
            leaf_identity = (
                _parse_pending_identity(
                    leaf.get("directory_identity"),
                    "pending cleanup ephemeral leaf identity",
                )
                if isinstance(leaf, dict)
                else None
            )
            metadata_file_identity = _parse_pending_identity(
                metadata.get("file_identity"),
                "pending cleanup ephemeral metadata identity",
            )
            metadata_mode = metadata.get("mode")
            metadata_size = metadata.get("size") if version == 7 else None
            metadata_sha256 = metadata.get("sha256")
            if (
                (version == 5 and leaf_identity is None)
                or (version == 7 and leaf_identity is not None)
                or metadata_file_identity is None
                or metadata_mode != 0o600
                or (
                    version == 7
                    and (
                        type(metadata_size) is not int
                        or metadata_size < 0
                        or metadata_size > MAX_MANAGED_STATE_BYTES
                    )
                )
                or not isinstance(metadata_sha256, str)
                or re.fullmatch(r"[0-9a-f]{64}", metadata_sha256) is None
            ):
                raise SyncError(
                    f"pending cleanup ephemeral authority changed: {batch_name}"
                )
            expected_metadata: dict[str, object] = (
                {
                    "path": "metadata.json",
                    "file_identity": _identity_payload(metadata_file_identity),
                    "mode": metadata_mode,
                    "sha256": metadata_sha256,
                }
                if version == 5
                else {
                    "path": "metadata.json",
                    "file_identity": _identity_payload(metadata_file_identity),
                    "mode": metadata_mode,
                    "size": metadata_size,
                    "sha256": metadata_sha256,
                }
            )
            expected_payload = _bounded_json_document(
                {
                    "version": version,
                    "kind": expected_kind,
                    "batch": batch_name,
                    "batch_root_identity": _identity_payload(batch_identity),
                    "quarantine_root_identity": _identity_payload(
                        quarantine_root_identity
                    ),
                    "isolated_name": _pending_cleanup_isolated_batch_name(batch_name),
                    "leaf": (
                        {
                            "path": "leaf",
                            "directory_identity": _identity_payload(leaf_identity),
                        }
                        if version == 5
                        else None
                    ),
                    "metadata": expected_metadata,
                },
                max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
                overflow_error="pending cleanup ticket exceeds the size limit",
            )
            if snapshot.payload != expected_payload:
                raise SyncError(f"pending cleanup ticket changed: {batch_name}")
            if _captured_snapshot is None:
                _require_pending_cleanup_file_snapshot_access_policy(
                    home,
                    ticket_path,
                    index_fd,
                    snapshot,
                )
            return PendingBatchCleanupTicket(
                version=version,
                phase=expected_kind,
                path=ticket_path,
                snapshot=snapshot,
                batch_root=batch_root,
                batch_root_identity=batch_identity,
                marker_path=None,
                marker_parent_identity=None,
                marker_file_identity=None,
                marker_mode=None,
                marker_sha256=None,
                kind=expected_kind,
                quarantine_root_identity=quarantine_root_identity,
                isolated_name=_pending_cleanup_isolated_batch_name(batch_name),
                leaf_identity=leaf_identity,
                metadata_file_identity=metadata_file_identity,
                metadata_mode=metadata_mode,
                metadata_sha256=metadata_sha256,
                metadata_size=metadata_size,
            )
        marker = data.get("commit_marker" if version == 1 else "finalization_marker")
        expected_marker_fields = {
            "path",
            "parent_identity",
            "file_identity",
            "mode",
            "sha256",
        }
        if version in {2, 3, 4}:
            expected_marker_fields.add("phase")
        if not isinstance(marker, dict) or set(marker) != expected_marker_fields:
            raise SyncError(
                f"pending cleanup finalization marker changed: {batch_name}"
            )
        phase = "after" if version == 1 else marker.get("phase")
        if version == 4:
            if phase not in {"before", "after"}:
                raise SyncError(
                    f"pending cleanup finalization marker changed: {batch_name}"
                )
            marker_path = (
                PENDING_STATE_COMMIT_MARKER
                if phase == "after"
                else PENDING_STATE_ROLLBACK_MARKER
            )
            expected_phase = phase
        else:
            marker_path = {
                1: PENDING_STATE_COMMIT_MARKER,
                2: PENDING_STATE_ROLLBACK_MARKER,
                3: PENDING_STATE_STAGING_MARKER,
            }[version]
            expected_phase = {1: "after", 2: "before", 3: "staging"}[version]
        if phase != expected_phase or marker.get("path") != marker_path.as_posix():
            raise SyncError(
                f"pending cleanup finalization marker changed: {batch_name}"
            )
        marker_parent_identity = _parse_pending_identity(
            marker.get("parent_identity"),
            "pending cleanup finalization marker parent identity",
        )
        marker_file_identity = _parse_pending_identity(
            marker.get("file_identity"),
            "pending cleanup finalization marker file identity",
        )
        if marker_parent_identity is None or marker_file_identity is None:
            raise SyncError(
                f"pending cleanup finalization marker identity is missing: {batch_name}"
            )
        marker_mode = marker.get("mode")
        marker_sha256 = marker.get("sha256")
        if marker_mode != 0o600:
            raise SyncError(
                f"pending cleanup finalization marker mode changed: {batch_name}"
            )
        if (
            not isinstance(marker_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", marker_sha256) is None
        ):
            raise SyncError(
                f"pending cleanup finalization marker digest changed: {batch_name}"
            )
        terminal_regular_targets = (
            _parse_pending_terminal_regular_targets(
                data.get("terminal_regular_targets"),
                batch_name=batch_name,
            )
            if version == 4
            else ()
        )
        if version == 1:
            expected_payload = _pending_cleanup_ticket_payload(
                batch_root,
                batch_identity,
                marker_parent_identity,
                marker_file_identity,
                marker_mode,
                marker_sha256,
            )
        else:
            payload_data: dict[str, Any] = {
                "version": version,
                "batch": batch_name,
                "batch_root_identity": _identity_payload(batch_identity),
                "finalization_marker": {
                    "phase": phase,
                    "path": marker_path.as_posix(),
                    "parent_identity": _identity_payload(marker_parent_identity),
                    "file_identity": _identity_payload(marker_file_identity),
                    "mode": marker_mode,
                    "sha256": marker_sha256,
                },
            }
            if version == 4:
                payload_data["terminal_regular_targets"] = [
                    {
                        "target": target.target.as_posix(),
                        "parent_identity": _identity_payload(target.parent_identity),
                        "file_identity": _identity_payload(target.file_identity),
                        "sha256": target.sha256,
                        "size": target.size,
                        "mode": target.mode,
                        "uid": target.uid,
                    }
                    for target in terminal_regular_targets
                ]
            expected_payload = _bounded_json_document(
                payload_data,
                max_bytes=(
                    MAX_PENDING_TERMINAL_CLEANUP_TICKET_BYTES
                    if version == 4
                    else MAX_PENDING_CLEANUP_TICKET_BYTES
                ),
                overflow_error="pending cleanup ticket exceeds the size limit",
            )
        if snapshot.payload != expected_payload:
            raise SyncError(f"pending cleanup ticket changed: {batch_name}")
        if _captured_snapshot is None:
            _require_pending_cleanup_file_snapshot_access_policy(
                home,
                ticket_path,
                index_fd,
                snapshot,
            )
        return PendingBatchCleanupTicket(
            version=version,
            phase=phase,
            path=ticket_path,
            snapshot=snapshot,
            batch_root=batch_root,
            batch_root_identity=batch_identity,
            marker_path=marker_path,
            marker_parent_identity=marker_parent_identity,
            marker_file_identity=marker_file_identity,
            marker_mode=marker_mode,
            marker_sha256=marker_sha256,
            terminal_regular_targets=terminal_regular_targets,
        )
    finally:
        _close_fd_quietly(index_fd)


def _discard_incomplete_pending_cleanup_ticket(
    home: Path,
    temp_path: Path,
    *,
    max_actions: int = MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
    expected_snapshot: ManagedStateFileSnapshot | None = None,
) -> int:
    if max_actions < 0:
        raise SyncError("pending cleanup temp action budget is invalid")
    index_fd = _open_directory_beneath(home, temp_path.parent)
    discarded = 0
    try:
        label = f"incomplete pending cleanup ticket {temp_path.name}"
        while discarded < max_actions:
            snapshot = _read_managed_state_file_snapshot(
                home,
                temp_path,
                index_fd,
                expected_identity=(
                    expected_snapshot.file_identity
                    if expected_snapshot is not None
                    else None
                ),
            )
            if expected_snapshot is not None and (
                not snapshot.exists
                or not _managed_state_snapshot_matches_bound_file_evidence(
                    snapshot,
                    expected_snapshot,
                )
            ):
                raise SyncError(
                    "incomplete pending cleanup ticket changed after "
                    f"classification: {temp_path.name}"
                )
            if snapshot.exists:
                if (
                    snapshot.file_type != stat.S_IFREG
                    or snapshot.mode != 0o600
                    or snapshot.uid != os.geteuid()
                    or not _managed_state_snapshot_has_complete_file_evidence(snapshot)
                ):
                    raise SyncError(
                        f"incomplete pending cleanup ticket changed: {temp_path.name}"
                    )
                _require_pending_cleanup_file_snapshot_access_policy(
                    home,
                    temp_path,
                    index_fd,
                    snapshot,
                )
                _isolate_and_delete_pending_cleanup_file(
                    home,
                    temp_path,
                    index_fd,
                    snapshot,
                    label=label,
                )
                discarded += 1
                if expected_snapshot is not None:
                    # Classification authorized at most the exact captured
                    # object.  A new object that appears under the temp name is
                    # left for a fresh scanner pass rather than being consumed
                    # by this stale decision.
                    replacement = _read_managed_state_file_snapshot(
                        home,
                        temp_path,
                        index_fd,
                    )
                    if replacement.exists:
                        raise SyncError(
                            "pending cleanup ticket temp replacement appeared "
                            f"after classified discard: {temp_path.name}"
                        )
                    break
                continue
            if expected_snapshot is not None:
                raise SyncError(
                    "incomplete pending cleanup ticket disappeared after "
                    f"classification: {temp_path.name}"
                )
            retained_names = _retained_pending_cleanup_names_for_path(
                home,
                temp_path,
                index_fd,
                label=label,
            )
            if not retained_names:
                break
            retained_name = retained_names[0]
            retained_path = temp_path.with_name(retained_name)
            retained_snapshot = _read_managed_state_file_snapshot(
                home,
                retained_path,
                index_fd,
            )
            if (
                retained_snapshot.file_type != stat.S_IFREG
                or retained_snapshot.mode != 0o600
                or retained_snapshot.uid != os.geteuid()
                or not _managed_state_snapshot_has_complete_file_evidence(
                    retained_snapshot
                )
            ):
                raise SyncError(
                    f"incomplete pending cleanup retained temp changed: {retained_name}"
                )
            _require_pending_cleanup_file_snapshot_access_policy(
                home,
                retained_path,
                index_fd,
                retained_snapshot,
            )
            restored = _restore_exact_retained_pending_cleanup_file(
                home,
                temp_path,
                index_fd,
                retained_name,
                retained_snapshot,
                label=label,
            )
            _isolate_and_delete_pending_cleanup_file(
                home,
                temp_path,
                index_fd,
                restored,
                label=label,
            )
            discarded += 1
    finally:
        _close_fd_quietly(index_fd)
    return discarded


def _pending_cleanup_temp_residue_is_observed(
    home: Path,
    temp_path: Path,
) -> bool:
    index_fd = _open_directory_beneath(home, temp_path.parent)
    try:
        snapshot = _read_managed_state_file_snapshot(
            home,
            temp_path,
            index_fd,
        )
        if snapshot.exists:
            return True
        return bool(
            _retained_pending_cleanup_names_for_path(
                home,
                temp_path,
                index_fd,
                label=f"pending cleanup temp {temp_path.name}",
            )
        )
    finally:
        _close_fd_quietly(index_fd)


def _publish_pending_cleanup_ticket(
    home: Path,
    ticket_path: Path,
    payload: bytes,
) -> ManagedStateFileSnapshot:
    # The final ticket name is published only after a fully written temporary
    # file has been fsynced. A crash-truncated temp is not deletion authority
    # and can be discarded by the next lock holder before retrying publication.
    temp_path = ticket_path.with_name(ticket_path.name + ".tmp")
    _discard_incomplete_pending_cleanup_ticket(home, temp_path)
    if _pending_cleanup_temp_residue_is_observed(home, temp_path):
        raise SyncError(
            "incomplete pending cleanup ticket temp backlog was retained; retry"
        )
    try:
        staged = _write_exclusive_internal_file(home, temp_path, payload)
    except _PendingCleanupAccessPolicyError as error:
        raise SyncError(
            "pending cleanup ticket appeared with changed content"
        ) from error
    index_fd = _open_directory_beneath(home, ticket_path.parent)
    try:
        current_temp = _read_managed_state_file_snapshot(
            home,
            temp_path,
            index_fd,
            expected_identity=staged.file_identity,
        )
        if (
            not _managed_state_snapshot_matches_bound_file_evidence(
                current_temp,
                staged,
            )
            or current_temp.payload != payload
        ):
            raise SyncError("pending cleanup ticket changed before publication")
        try:
            _rename_noreplace_at(
                index_fd,
                temp_path.name,
                index_fd,
                ticket_path.name,
            )
        except FileExistsError:
            existing = _read_managed_state_file_snapshot(
                home,
                ticket_path,
                index_fd,
            )
            if (
                not existing.exists
                or existing.mode != 0o600
                or existing.uid != os.geteuid()
                or existing.payload != payload
            ):
                raise SyncError("pending cleanup ticket appeared with changed content")
            current_temp = _read_managed_state_file_snapshot(
                home,
                temp_path,
                index_fd,
                expected_identity=staged.file_identity,
            )
            if not _managed_state_snapshot_matches_bound_file_evidence(
                current_temp,
                staged,
            ):
                raise SyncError(
                    "pending cleanup ticket temp changed after publication race"
                )
            _isolate_and_delete_pending_cleanup_file(
                home,
                temp_path,
                index_fd,
                staged,
                label="pending cleanup ticket temp",
            )
            return existing
        os.fsync(index_fd)
        published = _read_managed_state_file_snapshot(
            home,
            ticket_path,
            index_fd,
            expected_identity=staged.file_identity,
        )
        if (
            published.payload != payload
            or published.mode != 0o600
            or published.uid != os.geteuid()
        ):
            raise SyncError("pending cleanup ticket changed during publication")
        return published
    finally:
        _close_fd_quietly(index_fd)


def _require_quarantine_allocation_root_absent(
    home: Path,
    quarantine_root: Path,
    quarantine_fd: int,
    batch_name: str,
    root_identity: tuple[int, int],
) -> None:
    _require_pending_cleanup_fd_access_policy(
        quarantine_fd,
        quarantine_root,
        expected_mode=0o700,
    )
    if (
        _directory_identity(quarantine_fd) != root_identity
        or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
        or _named_entry_identity(quarantine_fd, batch_name) is not None
        or _named_entry_identity(
            quarantine_fd,
            _pending_cleanup_isolated_batch_name(batch_name),
        )
        is not None
    ):
        raise SyncError(
            f"pending quarantine allocation reservation changed: {batch_name}"
        )


def _publish_pending_quarantine_allocation_ticket(
    home: Path,
    quarantine_root: Path,
    quarantine_fd: int,
    batch_name: str,
    metadata_payload: bytes,
) -> PendingQuarantineAllocationTicket:
    """Durably reserve an absent batch without granting deletion authority."""
    root_identity = _directory_identity(quarantine_fd)
    _require_quarantine_allocation_root_absent(
        home,
        quarantine_root,
        quarantine_fd,
        batch_name,
        root_identity,
    )
    expected_payload = _pending_quarantine_allocation_payload(
        batch_name,
        root_identity,
        metadata_payload,
    )
    index_root = _pending_cleanup_index_path(home)
    index_fd = _open_or_create_directory_beneath(home, index_root, mode=0o700)
    _close_fd_quietly(index_fd)
    path = _pending_quarantine_allocation_path(home, batch_name)
    index_fd = _open_directory_beneath(home, index_root)
    try:
        retained = _retained_pending_cleanup_file(
            home,
            path,
            index_fd,
            expected=None,
            label=f"pending quarantine allocation {batch_name}",
        )
        if retained is not None:
            raise SyncError(
                "pending quarantine allocation retained evidence must be "
                f"recovered before publication: {batch_name}"
            )
        existing = _read_pending_quarantine_allocation_ticket(home, path)
        if existing is not None:
            if existing.snapshot.payload != expected_payload:
                raise SyncError(
                    f"pending quarantine allocation payload changed: {batch_name}"
                )
            published = existing.snapshot
        else:
            published = _publish_pending_cleanup_ticket(
                home,
                path,
                expected_payload,
            )
        os.fsync(index_fd)
    finally:
        _close_fd_quietly(index_fd)
    index_parent_fd = _open_directory_beneath(home, index_root.parent)
    try:
        os.fsync(index_parent_fd)
    finally:
        _close_fd_quietly(index_parent_fd)
    verified = _read_pending_quarantine_allocation_ticket(
        home,
        path,
        expected_identity=published.file_identity,
    )
    if verified is None or verified.snapshot.payload != expected_payload:
        raise SyncError(
            f"pending quarantine allocation changed after fsync: {batch_name}"
        )
    # The durable ticket describes an initially absent reservation.  Reprove
    # both possible batch names after its durable reread before mkdir.
    _require_quarantine_allocation_root_absent(
        home,
        quarantine_root,
        quarantine_fd,
        batch_name,
        root_identity,
    )
    return verified


def _verify_pending_cleanup_ticket_durable(
    home: Path,
    ticket: PendingBatchCleanupTicket,
) -> None:
    index_fd = _open_directory_beneath(home, ticket.path.parent)
    index_parent_fd = -1
    try:
        index_parent_fd = _open_directory_beneath(
            home,
            ticket.path.parent.parent,
        )
        if not _bound_directory_matches(home, ticket.path.parent, index_fd):
            raise SyncError("pending cleanup index changed before fsync")
        if not _bound_directory_matches(
            home,
            ticket.path.parent.parent,
            index_parent_fd,
        ):
            raise SyncError("pending cleanup index parent changed before fsync")
        os.fsync(index_fd)
        os.fsync(index_parent_fd)
        durable = _read_pending_cleanup_ticket(
            home,
            ticket.path,
            expected_ticket_identity=ticket.snapshot.file_identity,
        )
        if durable is None or not _pending_cleanup_ticket_matches(
            durable,
            ticket,
        ):
            raise SyncError("pending cleanup ticket changed after fsync")
    finally:
        if index_parent_fd >= 0:
            _close_fd_quietly(index_parent_fd)
        _close_fd_quietly(index_fd)


def _publish_pending_batch_cleanup_ticket_for_root(
    home: Path,
    batch_root: Path,
    expected_payload: bytes,
) -> None:
    index_fd = _open_or_create_directory_beneath(
        home,
        _pending_cleanup_index_path(home),
        mode=0o700,
    )
    _close_fd_quietly(index_fd)
    ticket_path = _pending_cleanup_ticket_path(home, batch_root.name)
    index_fd = _open_directory_beneath(home, ticket_path.parent)
    try:
        retained = _retained_pending_cleanup_file(
            home,
            ticket_path,
            index_fd,
            expected=None,
            label=f"pending cleanup ticket {batch_root.name}",
        )
        if retained is not None:
            raise SyncError(
                "pending cleanup ticket retained evidence must be recovered before "
                f"publication: {batch_root.name}"
            )
    finally:
        _close_fd_quietly(index_fd)
    existing = _read_pending_cleanup_ticket(
        home,
        ticket_path,
    )
    if existing is not None:
        if existing.snapshot.payload != expected_payload:
            raise SyncError("pending cleanup ticket payload changed")
        _verify_pending_cleanup_ticket_durable(home, existing)
        return
    published = _publish_pending_cleanup_ticket(
        home,
        ticket_path,
        expected_payload,
    )
    if published.payload != expected_payload:
        raise SyncError("pending cleanup ticket changed during publication")
    verified = _read_pending_cleanup_ticket(
        home,
        ticket_path,
        expected_ticket_identity=published.file_identity,
    )
    if verified is None or not _managed_state_snapshot_matches_bound_file_evidence(
        verified.snapshot,
        published,
    ):
        raise SyncError("pending cleanup ticket changed after publication")
    _verify_pending_cleanup_ticket_durable(home, verified)


def _publish_pending_batch_cleanup_ticket(
    home: Path,
    batch: PendingLinkBatch,
    expected_payload: bytes,
) -> None:
    _publish_pending_batch_cleanup_ticket_for_root(
        home,
        batch.batch_root,
        expected_payload,
    )


def _pending_staging_marker_snapshot(
    home: Path,
    batch_root: Path,
    batch_root_identity: tuple[int, int],
) -> ManagedStateFileSnapshot | None:
    marker_path = batch_root / Path(*PENDING_STATE_STAGING_MARKER.parts)
    parent_fd = _open_directory_beneath(home, marker_path.parent)
    try:
        marker = _read_managed_state_file_snapshot(
            home,
            marker_path,
            parent_fd,
        )
        if not marker.exists:
            return None
        expected_payload = _pending_staging_marker_payload(
            batch_root,
            batch_root_identity,
        )
        if (
            marker.file_type != stat.S_IFREG
            or marker.mode != 0o600
            or marker.uid != os.geteuid()
            or marker.payload != expected_payload
            or marker.parent_identity != _directory_identity(parent_fd)
        ):
            raise SyncError("pending staging cleanup marker changed")
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            marker_path,
            parent_fd,
            marker,
        )
        return marker
    finally:
        _close_fd_quietly(parent_fd)


def _bound_directory_member_names_for_staging_recovery(
    home: Path,
    path: Path,
    *,
    expected_entries: int,
    expected_identity: tuple[int, int] | None = None,
) -> tuple[str, ...]:
    if expected_entries < 0:
        raise SyncError("pending staging expected entry count is invalid")
    directory_fd = _open_directory_beneath(home, path)
    try:
        before = os.fstat(directory_fd)
        before_identity = (before.st_dev, before.st_ino)
        if (
            not stat.S_ISDIR(before.st_mode)
            or stat.S_IMODE(before.st_mode) != 0o700
            or before.st_uid != os.geteuid()
            or (expected_identity is not None and before_identity != expected_identity)
        ):
            raise SyncError(
                f"pending staging directory owner, mode, or identity changed: {path}"
            )
        _require_pending_cleanup_fd_access_policy(
            directory_fd,
            path,
            expected_mode=0o700,
        )
        if not _bound_directory_matches(home, path, directory_fd):
            raise SyncError(f"pending staging directory changed: {path}")
        names = _directory_member_names(
            directory_fd,
            maximum_entries=expected_entries + 1,
            overflow_message="pending staging recovery exceeds the entry limit",
        )
        after = os.fstat(directory_fd)
        if (
            (after.st_dev, after.st_ino) != before_identity
            or not stat.S_ISDIR(after.st_mode)
            or stat.S_IMODE(after.st_mode) != 0o700
            or after.st_uid != os.geteuid()
            or not _bound_directory_matches(home, path, directory_fd)
        ):
            raise SyncError(f"pending staging directory changed: {path}")
        _require_pending_cleanup_fd_access_policy(
            directory_fd,
            path,
            expected_mode=0o700,
        )
        return names
    finally:
        _close_fd_quietly(directory_fd)


def _require_pending_staging_initial_skeleton(
    home: Path,
    batch_root: Path,
    batch_root_identity: tuple[int, int],
) -> None:
    if set(
        _bound_directory_member_names_for_staging_recovery(
            home,
            batch_root,
            expected_entries=2,
            expected_identity=batch_root_identity,
        )
    ) != {"metadata.json", "pending"}:
        raise SyncError(
            f"pending staging temp batch is not an initial skeleton: {batch_root.name}"
        )
    batch_fd = _open_directory_beneath(home, batch_root)
    try:
        if _directory_identity(
            batch_fd
        ) != batch_root_identity or not _bound_directory_matches(
            home, batch_root, batch_fd
        ):
            raise SyncError(f"pending staging batch changed: {batch_root.name}")
        metadata = _read_managed_state_file_snapshot(
            home,
            batch_root / "metadata.json",
            batch_fd,
            maximum_bytes=MAX_MANAGED_STATE_BYTES,
        )
        if (
            metadata.file_type != stat.S_IFREG
            or metadata.mode != 0o600
            or metadata.uid != os.geteuid()
            or metadata.payload is None
            or metadata.parent_identity != batch_root_identity
            or not _managed_state_snapshot_has_complete_file_evidence(metadata)
        ):
            raise SyncError(f"pending staging metadata changed: {batch_root.name}")
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            batch_root / "metadata.json",
            batch_fd,
            metadata,
        )
    finally:
        _close_fd_quietly(batch_fd)
    pending_root = batch_root / "pending"
    if set(
        _bound_directory_member_names_for_staging_recovery(
            home,
            pending_root,
            expected_entries=6,
        )
    ) != {"before", "stage", "evidence", "cleanup", "state", "claims"}:
        raise SyncError(
            f"pending staging temp batch already progressed: {batch_root.name}"
        )
    claims_root = pending_root / "claims"
    if set(
        _bound_directory_member_names_for_staging_recovery(
            home,
            claims_root,
            expected_entries=2,
        )
    ) != {"before", "after"}:
        raise SyncError(f"pending staging claim skeleton changed: {batch_root.name}")
    for empty_path in (
        pending_root / "before",
        pending_root / "stage",
        pending_root / "evidence",
        pending_root / "cleanup",
        claims_root / "before",
        claims_root / "after",
    ):
        if _bound_directory_member_names_for_staging_recovery(
            home,
            empty_path,
            expected_entries=0,
        ):
            raise SyncError(
                f"pending staging temp batch already contains evidence: "
                f"{batch_root.name}"
            )
    marker_path = batch_root / Path(*PENDING_STATE_STAGING_MARKER.parts)
    temp_name = marker_path.name + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX
    state_names = _bound_directory_member_names_for_staging_recovery(
        home,
        marker_path.parent,
        expected_entries=1,
    )
    if len(state_names) != 1 or any(
        name != temp_name
        and _pending_cleanup_retained_canonical_name(name) != temp_name
        for name in state_names
    ):
        raise SyncError(
            f"pending staging temp authority is ambiguous: {batch_root.name}"
        )
    temp_path = marker_path.parent / state_names[0]
    state_fd = _open_directory_beneath(home, marker_path.parent)
    try:
        temp = _read_managed_state_file_snapshot(
            home,
            temp_path,
            state_fd,
        )
        if (
            temp.file_type != stat.S_IFREG
            or temp.mode != 0o600
            or temp.uid != os.geteuid()
            or not _managed_state_snapshot_has_complete_file_evidence(temp)
        ):
            raise SyncError(
                f"pending staging temp authority owner or mode changed: "
                f"{batch_root.name}"
            )
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            temp_path,
            state_fd,
            temp,
        )
    finally:
        _close_fd_quietly(state_fd)


def _discover_pending_staging_marker_temps(
    home: Path,
) -> tuple[tuple[Path, tuple[int, int]], ...]:
    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    try:
        quarantine_fd = _open_directory_beneath(home, quarantine_root)
    except FileNotFoundError:
        return ()
    discovered: list[tuple[Path, tuple[int, int]]] = []
    try:
        if not _bound_directory_matches(home, quarantine_root, quarantine_fd):
            raise SyncError("pending staging quarantine root changed")
        with os.scandir(quarantine_fd) as iterator:
            for scanned, entry in enumerate(iterator, start=1):
                if scanned > MAX_PENDING_CLEANUP_BATCH_SCAN:
                    raise SyncError("pending staging batch scan exceeds the size limit")
                batch_name = _pending_cleanup_batch_name_from_quarantine_entry(
                    entry.name
                )
                if batch_name is None or entry.name != batch_name:
                    continue
                metadata = entry.stat(follow_symlinks=False)
                if not stat.S_ISDIR(metadata.st_mode):
                    continue
                batch_root = quarantine_root / batch_name
                batch_identity = (metadata.st_dev, metadata.st_ino)
                try:
                    existing_ticket = _read_pending_cleanup_ticket(
                        home,
                        _pending_cleanup_ticket_path(home, batch_name),
                    )
                except FileNotFoundError:
                    existing_ticket = None
                except (OSError, SyncError) as error:
                    raise _pending_cleanup_authority_classification_error(
                        batch_name,
                        error,
                    ) from error
                if existing_ticket is not None:
                    continue
                marker_path = batch_root / Path(*PENDING_STATE_STAGING_MARKER.parts)
                try:
                    marker = _pending_staging_marker_snapshot(
                        home,
                        batch_root,
                        batch_identity,
                    )
                except (FileNotFoundError, NotADirectoryError):
                    continue
                if marker is not None:
                    continue
                temp_path = marker_path.with_name(
                    marker_path.name + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX
                )
                try:
                    observed = _pending_cleanup_temp_residue_is_observed(
                        home,
                        temp_path,
                    )
                except FileNotFoundError:
                    continue
                if observed:
                    discovered.append((batch_root, batch_identity))
    finally:
        _close_fd_quietly(quarantine_fd)
    return tuple(discovered)


def _recover_pending_staging_marker_temps(
    home: Path,
    *,
    budget: PendingCleanupActionBudget,
) -> int:
    recovered = 0
    for batch_root, batch_identity in sorted(
        _discover_pending_staging_marker_temps(home),
        key=lambda item: item[0].name,
    ):
        if not budget.charge_batch(batch_root.name):
            continue
        _require_pending_staging_initial_skeleton(
            home,
            batch_root,
            batch_identity,
        )
        marker_path = batch_root / Path(*PENDING_STATE_STAGING_MARKER.parts)
        _publish_atomic_exclusive_internal_file(
            home,
            marker_path,
            _pending_staging_marker_payload(batch_root, batch_identity),
        )
        recovered += 1
    return recovered


def _discover_pending_staging_markers(
    home: Path,
) -> tuple[
    tuple[Path, tuple[int, int], ManagedStateFileSnapshot],
    ...,
]:
    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    try:
        quarantine_fd = _open_directory_beneath(home, quarantine_root)
    except FileNotFoundError:
        return ()
    discovered: list[tuple[Path, tuple[int, int], ManagedStateFileSnapshot]] = []
    try:
        if not _bound_directory_matches(home, quarantine_root, quarantine_fd):
            raise SyncError("pending staging quarantine root changed")
        with os.scandir(quarantine_fd) as iterator:
            for scanned, entry in enumerate(iterator, start=1):
                if scanned > MAX_PENDING_CLEANUP_BATCH_SCAN:
                    raise SyncError("pending staging batch scan exceeds the size limit")
                batch_name = _pending_cleanup_batch_name_from_quarantine_entry(
                    entry.name
                )
                if batch_name is None or entry.name != batch_name:
                    continue
                try:
                    existing_ticket = _read_pending_cleanup_ticket(
                        home,
                        _pending_cleanup_ticket_path(home, batch_name),
                    )
                except FileNotFoundError:
                    existing_ticket = None
                except (OSError, SyncError) as error:
                    raise _pending_cleanup_authority_classification_error(
                        batch_name,
                        error,
                    ) from error
                if existing_ticket is not None:
                    continue
                try:
                    metadata = entry.stat(follow_symlinks=False)
                except OSError as error:
                    raise SyncError(
                        f"pending staging batch changed: {entry.name}"
                    ) from error
                if not stat.S_ISDIR(metadata.st_mode):
                    raise SyncError(
                        f"pending staging batch is not a directory: {entry.name}"
                    )
                batch_root = quarantine_root / batch_name
                batch_identity = (metadata.st_dev, metadata.st_ino)
                try:
                    marker = _pending_staging_marker_snapshot(
                        home,
                        batch_root,
                        batch_identity,
                    )
                except FileNotFoundError:
                    continue
                except OSError as error:
                    raise SyncError(
                        f"pending staging marker changed: {batch_name}"
                    ) from error
                if marker is not None:
                    discovered.append((batch_root, batch_identity, marker))
        if not _bound_directory_matches(home, quarantine_root, quarantine_fd):
            raise SyncError("pending staging quarantine root changed")
    finally:
        _close_fd_quietly(quarantine_fd)
    return tuple(discovered)


def _publish_discovered_staging_cleanup_tickets(
    home: Path,
    *,
    limit: int = MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
    budget: PendingCleanupActionBudget | None = None,
) -> int:
    if limit < 0:
        raise SyncError("pending staging cleanup action budget is invalid")
    published = 0
    action_budget = budget or PendingCleanupActionBudget(limit)
    _recover_pending_staging_marker_temps(
        home,
        budget=action_budget,
    )
    discovered = sorted(
        _discover_pending_staging_markers(home),
        key=lambda item: item[0].name,
    )
    for batch_root, batch_identity, marker in discovered:
        ticket_path = _pending_cleanup_ticket_path(home, batch_root.name)
        try:
            existing = _read_pending_cleanup_ticket(home, ticket_path)
        except FileNotFoundError:
            existing = None
        except (OSError, SyncError) as error:
            raise _pending_cleanup_authority_classification_error(
                batch_root.name,
                error,
            ) from error
        if existing is not None:
            continue
        if not action_budget.charge_batch(batch_root.name):
            continue
        _publish_pending_batch_cleanup_ticket_for_root(
            home,
            batch_root,
            _pending_staging_cleanup_ticket_payload(
                batch_root,
                batch_identity,
                marker,
            ),
        )
        published += 1
    return published


def _mark_pending_batch_staging_cleanup_ready(
    home: Path,
    batch_root: Path,
    batch_root_identity: tuple[int, int],
) -> PendingBatchCleanupTicket:
    marker_path = batch_root / Path(*PENDING_STATE_STAGING_MARKER.parts)
    marker = _publish_atomic_exclusive_internal_file(
        home,
        marker_path,
        _pending_staging_marker_payload(batch_root, batch_root_identity),
    )
    verified_marker = _pending_staging_marker_snapshot(
        home,
        batch_root,
        batch_root_identity,
    )
    if (
        verified_marker is None
        or not _managed_state_snapshot_matches_bound_file_evidence(
            verified_marker,
            marker,
        )
    ):
        raise SyncError("pending staging cleanup marker changed after publication")
    expected_payload = _pending_staging_cleanup_ticket_payload(
        batch_root,
        batch_root_identity,
        verified_marker,
    )
    _publish_pending_batch_cleanup_ticket_for_root(
        home,
        batch_root,
        expected_payload,
    )
    ticket = _read_pending_cleanup_ticket(
        home,
        _pending_cleanup_ticket_path(home, batch_root.name),
    )
    if (
        ticket is None
        or ticket.version != 3
        or ticket.phase != "staging"
        or ticket.batch_root_identity != batch_root_identity
        or ticket.snapshot.payload != expected_payload
    ):
        raise SyncError("pending staging cleanup ticket changed after publication")
    return ticket


def _read_or_restore_active_pointer_cleanup_ticket(
    home: Path,
    batch: PendingLinkBatch,
) -> PendingBatchCleanupTicket | None:
    if batch.pointer_snapshot is None:
        raise SyncError(
            "refusing to recover pending cleanup ticket tombstone without an "
            "active pointer"
        )
    ticket_path = _pending_cleanup_ticket_path(home, batch.batch_root.name)
    try:
        index_fd = _open_directory_beneath(home, ticket_path.parent)
    except FileNotFoundError as error:
        if batch.metadata_version in {4, 5}:
            return None
        if batch.metadata_version == 6:
            # Early v6 batches predate staging cleanup authority. A missing
            # index proves that ticket, ticket-temp, and retained ticket forms
            # are absent. Accept that legacy state only when the bound batch
            # state directory also has no marker, marker-temp, or retained form.
            marker_path = batch.batch_root / Path(*PENDING_STATE_STAGING_MARKER.parts)
            marker_parent_fd = _open_directory_beneath(home, marker_path.parent)
            try:
                names = _directory_member_names(
                    marker_parent_fd,
                    maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
                    overflow_message=(
                        "active pending staging authority scan exceeds the limit"
                    ),
                )
                temp_name = marker_path.name + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX
                protected_names = {marker_path.name, temp_name}
                retained_prefixes = tuple(
                    f"{PENDING_CLEANUP_RETAINED_PREFIX}{name}-"
                    for name in protected_names
                )
                if any(
                    name in protected_names or name.startswith(retained_prefixes)
                    for name in names
                ):
                    raise SyncError(
                        "active pending transaction has partial legacy staging "
                        f"cleanup authority: {batch.batch_root.name}"
                    )
                if not _bound_directory_matches(
                    home,
                    marker_path.parent,
                    marker_parent_fd,
                ):
                    raise SyncError("active pending staging authority parent changed")
            finally:
                _close_fd_quietly(marker_parent_fd)
            return None
        raise SyncError(
            "active pending transaction cleanup index is missing: "
            f"metadata v{batch.metadata_version}"
        ) from error
    restored: ManagedStateFileSnapshot | None = None
    try:
        canonical = _read_managed_state_file_snapshot(
            home,
            ticket_path,
            index_fd,
        )
        retained = _retained_pending_cleanup_file(
            home,
            ticket_path,
            index_fd,
            expected=None,
            label=f"active pending cleanup ticket {batch.batch_root.name}",
        )
        if canonical.exists and retained is not None:
            raise SyncError(
                "active pending cleanup ticket overlaps retained evidence: "
                f"{batch.batch_root.name}"
            )
        if not canonical.exists and retained is not None:
            retained_name, retained_snapshot = retained
            if not _managed_state_snapshot_has_complete_file_evidence(
                retained_snapshot
            ):
                raise SyncError(
                    "active pending cleanup ticket retained evidence changed: "
                    f"{batch.batch_root.name}"
                )
            restored = _restore_exact_retained_pending_cleanup_file(
                home,
                ticket_path,
                index_fd,
                retained_name,
                retained_snapshot,
                label=f"active pending cleanup ticket {batch.batch_root.name}",
            )
    finally:
        _close_fd_quietly(index_fd)
    ticket = _read_pending_cleanup_ticket(
        home,
        ticket_path,
        expected_ticket_identity=(
            restored.file_identity if restored is not None else None
        ),
    )
    if restored is not None and (
        ticket is None
        or ticket.version != 3
        or ticket.phase != "staging"
        or ticket.batch_root_identity != batch.batch_root_identity
    ):
        raise SyncError(
            "active pending staging cleanup ticket tombstone changed during recovery"
        )
    return ticket


def _retire_pending_staging_cleanup_authority(
    home: Path,
    batch: PendingLinkBatch,
) -> None:
    if batch.pointer_snapshot is None:
        raise SyncError(
            "refusing to retire pending staging cleanup authority without an "
            "active pointer"
        )
    ticket = _read_or_restore_active_pointer_cleanup_ticket(home, batch)
    marker = _pending_staging_marker_snapshot(
        home,
        batch.batch_root,
        batch.batch_root_identity,
    )
    if ticket is not None and ticket.version != 3:
        if marker is not None:
            raise SyncError(
                "pending staging cleanup marker overlaps finalized cleanup authority"
            )
        return
    if ticket is None and marker is None:
        return
    if ticket is not None:
        if (
            ticket.version != 3
            or ticket.phase != "staging"
            or ticket.batch_root_identity != batch.batch_root_identity
            or marker is None
            or marker.parent_identity != ticket.marker_parent_identity
            or marker.file_identity != ticket.marker_file_identity
            or marker.mode != ticket.marker_mode
            or marker.payload is None
            or hashlib.sha256(marker.payload).hexdigest() != ticket.marker_sha256
        ):
            raise SyncError("pending staging cleanup authority changed")
        # The active pointer was fsynced before this deletion. Once the ticket
        # is gone, only the pointer may authorize transaction recovery. A crash
        # before marker deletion is recovered by the ticket-absent branch.
        _delete_pending_cleanup_ticket(home, ticket)
    if marker is None:
        return
    marker_path = batch.batch_root / Path(*PENDING_STATE_STAGING_MARKER.parts)
    parent_fd = _open_directory_beneath(home, marker_path.parent)
    try:
        current = _read_managed_state_file_snapshot(
            home,
            marker_path,
            parent_fd,
            expected_identity=marker.file_identity,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            current,
            marker,
        ):
            raise SyncError("pending staging cleanup marker changed before deletion")
        _isolate_and_delete_pending_cleanup_file(
            home,
            marker_path,
            parent_fd,
            marker,
            label="pending staging cleanup marker",
        )
    finally:
        _close_fd_quietly(parent_fd)


def _cleanup_failed_pending_staging_batch(
    home: Path,
    batch_root: Path,
    batch_root_identity: tuple[int, int],
) -> None:
    ticket = _read_pending_cleanup_ticket(
        home,
        _pending_cleanup_ticket_path(home, batch_root.name),
    )
    if (
        ticket is None
        or ticket.version != 3
        or ticket.phase != "staging"
        or ticket.batch_root_identity != batch_root_identity
    ):
        raise SyncError("pending staging cleanup ticket is missing or changed")
    if not _remove_cleanup_ready_batch(home, ticket):
        raise SyncError("pending staging cleanup was deferred")


def _mark_pending_batch_cleanup_ready(
    home: Path,
    batch: PendingLinkBatch,
) -> None:
    marker = _pending_commit_marker_snapshot(home, batch)
    if marker is None:
        raise SyncError("refusing to mark an uncommitted pending batch for cleanup")
    if (
        not marker.exists
        or marker.parent_identity is None
        or marker.file_identity is None
        or marker.payload is None
        or marker.mode != 0o600
    ):
        raise SyncError("pending cleanup commit marker is not fully bound")
    cleanup_batch = batch
    if batch.metadata_version == 6:
        # v6 records bind only regular targets acted on by the transaction.
        # A later terminal-cleanup ticket must still bind the entire after-state
        # regular target group, including unchanged targets. Reconstruct that
        # group from the committed state and immutable release sources instead
        # of treating an action-scoped record set as blanket alias authority.
        cleanup_batch = replace(
            batch,
            terminal_regular_after=_stage_pending_terminal_regular_targets(
                home,
                batch.state_after_value,
                batch.records,
                phase="after",
            ),
        )
    payload = (
        _pending_terminal_cleanup_ticket_payload(
            cleanup_batch,
            marker,
            phase="after",
        )
        if cleanup_batch.terminal_regular_after
        else _pending_cleanup_ticket_payload(
            batch.batch_root,
            batch.batch_root_identity,
            marker.parent_identity,
            marker.file_identity,
            marker.mode,
            hashlib.sha256(marker.payload).hexdigest(),
        )
    )
    _publish_pending_batch_cleanup_ticket(home, batch, payload)


def _mark_pending_batch_rollback_cleanup_ready(
    home: Path,
    batch: PendingLinkBatch,
) -> None:
    marker = _publish_pending_rollback_marker(home, batch)
    cleanup_batch = batch
    if batch.metadata_version == 6:
        # See the committed counterpart above. The same reconstruction is
        # required when an interrupted v6 transaction rolls back.
        cleanup_batch = replace(
            batch,
            terminal_regular_before=_stage_pending_terminal_regular_targets(
                home,
                batch.state_before_value,
                batch.records,
                phase="before",
            ),
        )
    payload = (
        _pending_terminal_cleanup_ticket_payload(
            cleanup_batch,
            marker,
            phase="before",
        )
        if cleanup_batch.terminal_regular_before
        else _pending_rollback_cleanup_ticket_payload(
            batch.batch_root,
            batch.batch_root_identity,
            marker,
        )
    )
    _publish_pending_batch_cleanup_ticket(home, batch, payload)


def _pending_link_pointer_is_absent(home: Path) -> bool:
    try:
        home_fd = _open_directory_beneath(home, home)
    except FileNotFoundError:
        return True
    try:
        snapshot = _read_managed_state_file_snapshot(
            home,
            _pending_link_pointer_path(home),
            home_fd,
        )
        return not snapshot.exists
    finally:
        _close_fd_quietly(home_fd)


def _directory_mount_identity(directory_fd: int) -> tuple[int, int | None]:
    device = os.fstat(directory_fd).st_dev
    if sys.platform == "darwin":
        # macOS has no Linux-style bind-mount primitive in the supported
        # installer environment. Pair st_dev with the filesystem id so other
        # mounted filesystems are still rejected before recursion.
        filesystem_id = getattr(os.fstatvfs(directory_fd), "f_fsid", None)
        if not isinstance(filesystem_id, int):
            raise SyncError("pending cleanup macOS filesystem id is missing")
        return device, filesystem_id
    if not sys.platform.startswith("linux"):
        raise SyncError(
            "pending cleanup mount identity is unsupported on this platform"
        )
    fdinfo_path = Path("/proc/self/fdinfo") / str(directory_fd)
    fdinfo_fd = -1
    try:
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        fdinfo_fd = os.open(fdinfo_path, flags)
        raw_payload = os.read(fdinfo_fd, 8193)
        if len(raw_payload) > 8192:
            raise SyncError("pending cleanup Linux fdinfo exceeds its limit")
        payload = raw_payload.decode("ascii")
    except (OSError, UnicodeError) as error:
        raise SyncError("pending cleanup cannot verify the Linux mount id") from error
    finally:
        if fdinfo_fd >= 0:
            _close_fd_quietly(fdinfo_fd)
    mount_id: int | None = None
    for line in payload.splitlines():
        if line.startswith("mnt_id:"):
            raw_mount_id = line.partition(":")[2].strip()
            if raw_mount_id.isdecimal():
                mount_id = int(raw_mount_id)
            break
    if mount_id is None:
        raise SyncError("pending cleanup Linux mount id is missing")
    return device, mount_id


def _pending_cleanup_entry_plan(
    metadata: os.stat_result,
) -> tuple[int, int, int]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        stat.S_IFMT(metadata.st_mode),
    )


def _pending_cleanup_entry_name(
    prefix: str,
    parent_identity: tuple[int, int],
    planned: tuple[int, int, int],
) -> str:
    return (
        f"{prefix}{parent_identity[0]:x}-{parent_identity[1]:x}-"
        f"{planned[0]:x}-{planned[1]:x}-{planned[2]:x}-"
        f"{os.urandom(8).hex()}"
    )


def _pending_cleanup_internal_entry_plan(
    name: str,
    prefix: str,
    parent_identity: tuple[int, int],
) -> tuple[int, int, int] | None:
    if not name.startswith(prefix):
        return None
    match = PENDING_CLEANUP_ENTRY_TOKEN_RE.fullmatch(name[len(prefix) :])
    if match is None:
        return None
    parsed_parent = (int(match.group(1), 16), int(match.group(2), 16))
    if parsed_parent != parent_identity:
        return None
    return (
        int(match.group(3), 16),
        int(match.group(4), 16),
        int(match.group(5), 16),
    )


def _retain_pending_cleanup_entry(
    directory_fd: int,
    name: str,
    parent_identity: tuple[int, int],
    planned: tuple[int, int, int],
    *,
    label: str,
) -> NoReturn:
    for _attempt in range(128):
        retained_name = _pending_cleanup_entry_name(
            PENDING_CLEANUP_RETAINED_ENTRY_PREFIX,
            parent_identity,
            planned,
        )
        try:
            _rename_noreplace_at(
                directory_fd,
                name,
                directory_fd,
                retained_name,
            )
        except FileExistsError:
            continue
        except FileNotFoundError as error:
            raise SyncError(f"{label}; isolated entry disappeared") from error
        os.fsync(directory_fd)
        raise SyncError(f"{label}; preserved as {retained_name}")
    raise SyncError("failed to allocate a retained pending cleanup entry name")


def _isolate_pending_cleanup_entry(
    directory_fd: int,
    name: str,
    parent_identity: tuple[int, int],
    planned: tuple[int, int, int],
    *,
    links_content_root: bool = False,
    retain_mismatch: bool = True,
) -> tuple[str, os.stat_result]:
    active_prefix = (
        PENDING_CLEANUP_ACTIVE_LINKS_ENTRY_PREFIX
        if links_content_root
        else PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX
    )
    for _attempt in range(128):
        active_name = _pending_cleanup_entry_name(
            active_prefix,
            parent_identity,
            planned,
        )
        if active_name == name:
            continue
        try:
            _rename_noreplace_at(
                directory_fd,
                name,
                directory_fd,
                active_name,
            )
        except FileExistsError:
            continue
        except FileNotFoundError as error:
            raise SyncError(
                f"pending cleanup entry disappeared before isolation: {name}"
            ) from error
        os.fsync(directory_fd)
        break
    else:
        raise SyncError("failed to allocate an active pending cleanup entry name")
    try:
        current = os.stat(
            active_name,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
    except OSError:
        if retain_mismatch:
            _retain_pending_cleanup_entry(
                directory_fd,
                active_name,
                parent_identity,
                planned,
                label=f"pending cleanup isolated entry changed: {name}",
            )
        raise SyncError(f"pending cleanup isolated entry changed: {active_name}")
    if _pending_cleanup_entry_plan(current) != planned:
        if retain_mismatch:
            _retain_pending_cleanup_entry(
                directory_fd,
                active_name,
                parent_identity,
                planned,
                label=f"pending cleanup entry changed before deletion: {name}",
            )
    # The verified active name is high entropy and exists only inside the
    # locked, mode-0700 sync quarantine. Portable Unix APIs do not offer an
    # inode-conditional unlink; a same-uid process deliberately observing and
    # replacing this internal name is outside the installer threat model
    # because it already has equivalent authority over sync state and releases.
    return active_name, current


def _pending_batch_cleanup_name_is_authorized(
    relative_parent: tuple[str, ...],
    name: str,
    parent_identity: tuple[int, int],
) -> bool:
    deletion_alias_base = _pending_regular_publication_private_deletion_alias_base(name)
    if deletion_alias_base is not None:
        return (
            relative_parent == ("pending", "cleanup")
            and _pending_cleanup_internal_entry_plan(
                deletion_alias_base,
                PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
                parent_identity,
            )
            is not None
        )
    active_links_plan = _pending_cleanup_internal_entry_plan(
        name,
        PENDING_CLEANUP_ACTIVE_LINKS_ENTRY_PREFIX,
        parent_identity,
    )
    if active_links_plan is not None:
        return not relative_parent
    if (
        _pending_cleanup_internal_entry_plan(
            name,
            PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
            parent_identity,
        )
        is not None
        or _pending_cleanup_internal_entry_plan(
            name,
            PENDING_CLEANUP_RETAINED_ENTRY_PREFIX,
            parent_identity,
        )
        is not None
    ):
        return True
    if not relative_parent:
        if (
            re.fullmatch(
                re.escape(PENDING_CLEANUP_TERMINAL_ALIAS_PREFIX) + r"[0-9]{8}",
                name,
            )
            is not None
        ):
            return True
        return name in {
            "metadata.json",
            "pending",
            "links",
            "state",
            PENDING_LINK_METADATA_NAME,
        }
    if relative_parent == ("pending",):
        return name in {
            "before",
            "stage",
            "evidence",
            "cleanup",
            "state",
            "claims",
        }
    if relative_parent == ("pending", "claims"):
        return name in {"before", "after"}
    if relative_parent in {
        ("pending", "before"),
        ("pending", "stage"),
        ("pending", "evidence"),
        ("pending", "claims", "before"),
        ("pending", "claims", "after"),
    }:
        return re.fullmatch(r"[0-9]{8}", name) is not None
    if relative_parent == ("pending", "cleanup"):
        canonical = re.fullmatch(
            r"[0-9]{8}(?:\.before)?(?:\.private-authority)?"
            r"\.json(?:\.publish-tmp)?",
            name,
        )
        if canonical is not None:
            return True
        retained_canonical = _pending_cleanup_retained_canonical_name(name)
        return (
            retained_canonical is not None
            and re.fullmatch(
                r"[0-9]{8}(?:\.before)?(?:\.private-authority)?"
                r"\.json(?:\.publish-tmp)?",
                retained_canonical,
            )
            is not None
        )
    if relative_parent == ("pending", "state"):
        canonical_names = {
            PENDING_STATE_BEFORE_EVIDENCE.name,
            PENDING_STATE_AFTER_EVIDENCE.name,
            PENDING_STATE_COMMIT_EVIDENCE.name,
            PENDING_STATE_COMMIT_MARKER.name,
            PENDING_STATE_ROLLBACK_MARKER.name,
            PENDING_STATE_STAGING_MARKER.name,
        }
        if name in canonical_names:
            return True
        if name.endswith(PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX):
            return (
                name[: -len(PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX)] in canonical_names
            )
        retained_canonical = _pending_cleanup_retained_canonical_name(name)
        return retained_canonical in canonical_names or retained_canonical in {
            canonical + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX
            for canonical in canonical_names
        }
    if relative_parent and relative_parent[0] == "links":
        return True
    if relative_parent and relative_parent[0] == "state":
        return True
    return False


def _require_no_pending_staging_manual_retention(
    home: Path,
    bound_batch_root: Path,
) -> None:
    cleanup_root = bound_batch_root / "pending" / "cleanup"
    try:
        names = _bound_directory_member_names_for_staging_recovery(
            home,
            cleanup_root,
            expected_entries=MAX_PENDING_LINK_RECORDS * 2,
        )
    except FileNotFoundError:
        return
    if names:
        raise SyncError(
            "pending staging regular-file evidence requires manual cleanup; "
            f"the batch was retained without deletion: {bound_batch_root.name}"
        )


def _cleanup_directory_expected_mode(
    configured_expected_mode: int | None,
    relative_parts: tuple[str, ...],
) -> int | None:
    """Select exact control-directory or flexible content access policy.

    A ``None`` configuration marks a release content tree, where current-euid
    ownership and no group/world write authority are protected while ordinary
    0755 directories remain valid. Pending cleanup defaults to exact 0700, but
    its ``links/**`` evidence namespace is ordinary content with the same
    flexible policy.
    """
    if configured_expected_mode is None:
        return None
    if relative_parts and relative_parts[0] == "links":
        return None
    return configured_expected_mode


def _cleanup_regular_file_expected_mode(
    configured_expected_mode: int | None,
    relative_parts: tuple[str, ...],
    *,
    links_content_root: bool,
) -> int | None:
    """Select exact control-file or flexible typed links-content policy."""
    if configured_expected_mode is None:
        return None
    if links_content_root or (relative_parts and relative_parts[0] == "links"):
        return None
    return configured_expected_mode


def _capture_pending_cleanup_identity_ledger(
    directory_fd: int,
    directory_identity: tuple[int, int],
    root_mount_identity: tuple[int, int | None],
    budget: list[int],
    ledger: dict[
        tuple[int, int],
        tuple[tuple[str, tuple[int, int, int], bool, bool], ...],
    ],
    *,
    depth: int,
    relative_parts: tuple[str, ...],
    skipped_names: frozenset[str],
    name_validator: (Callable[[tuple[str, ...], str, tuple[int, int]], bool] | None),
    directory_expected_mode: int | None,
) -> None:
    if depth > MAX_PENDING_CLEANUP_DEPTH:
        raise SyncError("pending cleanup directory depth exceeds the limit")
    display_path = Path("<pending-cleanup-scan>") / Path(*relative_parts)
    effective_expected_mode = _cleanup_directory_expected_mode(
        directory_expected_mode,
        relative_parts,
    )
    if effective_expected_mode is None:
        _require_current_user_cleanup_fd_access_policy(
            directory_fd,
            display_path,
        )
    else:
        _require_pending_cleanup_fd_access_policy(
            directory_fd,
            display_path,
            expected_mode=effective_expected_mode,
        )
    if _directory_identity(directory_fd) != directory_identity:
        raise SyncError("pending cleanup directory identity changed")
    if _directory_mount_identity(directory_fd) != root_mount_identity:
        raise SyncError("pending cleanup directory crosses a mount boundary")
    if directory_identity in ledger:
        raise SyncError("pending cleanup directory identity is duplicated")

    entries: list[tuple[str, tuple[int, int, int], bool, bool]] = []
    with os.scandir(directory_fd) as iterator:
        for entry in iterator:
            if entry.name in skipped_names:
                continue
            if budget[0] <= 0:
                raise SyncError("pending cleanup entry count exceeds the limit")
            budget[0] -= 1
            if name_validator is not None and not name_validator(
                relative_parts,
                entry.name,
                directory_identity,
            ):
                raise SyncError(
                    "pending cleanup found an unknown entry and retained the "
                    f"batch without deletion: {'/'.join((*relative_parts, entry.name))}"
                )
            retained_plan = _pending_cleanup_internal_entry_plan(
                entry.name,
                PENDING_CLEANUP_RETAINED_ENTRY_PREFIX,
                directory_identity,
            )
            if retained_plan is not None:
                raise SyncError(
                    "pending cleanup retained entry requires manual cleanup: "
                    f"{entry.name}"
                )
            if _pending_cleanup_retained_canonical_name(entry.name) is not None:
                raise SyncError(
                    "pending cleanup retained file requires manual cleanup: "
                    f"{entry.name}"
                )
            try:
                metadata = entry.stat(follow_symlinks=False)
            except OSError as error:
                raise SyncError(
                    f"pending cleanup entry changed: {entry.name}"
                ) from error
            if metadata.st_dev != root_mount_identity[0]:
                raise SyncError(
                    f"pending cleanup entry crosses a device boundary: {entry.name}"
                )
            planned = _pending_cleanup_entry_plan(metadata)
            if planned[2] not in {stat.S_IFDIR, stat.S_IFREG, stat.S_IFLNK}:
                raise SyncError(
                    f"pending cleanup found an unsupported entry: {entry.name}"
                )
            active_name = (
                _pending_regular_publication_private_deletion_alias_base(entry.name)
                or entry.name
            )
            active_plan = _pending_cleanup_internal_entry_plan(
                active_name,
                PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
                directory_identity,
            )
            active_links_plan = None
            if not relative_parts:
                active_links_plan = _pending_cleanup_internal_entry_plan(
                    entry.name,
                    PENDING_CLEANUP_ACTIVE_LINKS_ENTRY_PREFIX,
                    directory_identity,
                )
            links_content_root = not relative_parts and (
                entry.name == "links" or active_links_plan is not None
            )
            entries.append(
                (
                    entry.name,
                    active_links_plan or active_plan or planned,
                    active_links_plan is not None or active_plan is not None,
                    links_content_root,
                )
            )
    ledger[directory_identity] = tuple(entries)
    if effective_expected_mode is None:
        _require_current_user_cleanup_fd_access_policy(
            directory_fd,
            display_path,
        )
    else:
        _require_pending_cleanup_fd_access_policy(
            directory_fd,
            display_path,
            expected_mode=effective_expected_mode,
        )

    directory_flags = _directory_open_flags(nofollow=True)
    for name, planned, _already_active, links_content_root in entries:
        if planned[2] != stat.S_IFDIR:
            continue
        child_fd = -1
        try:
            child_fd = os.open(name, directory_flags, dir_fd=directory_fd)
            child_identity = _directory_identity(child_fd)
            if child_identity != planned[:2]:
                raise SyncError(f"pending cleanup child directory changed: {name}")
            _capture_pending_cleanup_identity_ledger(
                child_fd,
                child_identity,
                root_mount_identity,
                budget,
                ledger,
                depth=depth + 1,
                relative_parts=(
                    ("links",) if links_content_root else (*relative_parts, name)
                ),
                skipped_names=frozenset(),
                name_validator=name_validator,
                directory_expected_mode=directory_expected_mode,
            )
        finally:
            if child_fd >= 0:
                _close_fd_quietly(child_fd)


def _remove_pending_batch_directory_contents(
    directory_fd: int,
    directory_identity: tuple[int, int],
    root_mount_identity: tuple[int, int | None],
    budget: list[int],
    *,
    depth: int,
    skipped_names: frozenset[str] = frozenset(),
    relative_parts: tuple[str, ...] = (),
    identity_ledger: (
        dict[
            tuple[int, int],
            tuple[tuple[str, tuple[int, int, int], bool, bool], ...],
        ]
        | None
    ) = None,
    name_validator: (
        Callable[[tuple[str, ...], str, tuple[int, int]], bool] | None
    ) = None,
    directory_expected_mode: int | None = 0o700,
    regular_file_expected_mode: int | None = 0o600,
) -> None:
    if depth > MAX_PENDING_CLEANUP_DEPTH:
        raise SyncError("pending cleanup directory depth exceeds the limit")
    display_path = Path(
        f"<pending-cleanup-fd:{directory_identity[0]}:{directory_identity[1]}>"
    )
    effective_expected_mode = _cleanup_directory_expected_mode(
        directory_expected_mode,
        relative_parts,
    )
    if effective_expected_mode is None:
        _require_current_user_cleanup_fd_access_policy(
            directory_fd,
            display_path,
        )
    else:
        _require_pending_cleanup_fd_access_policy(
            directory_fd,
            display_path,
            expected_mode=effective_expected_mode,
        )
    if _directory_identity(directory_fd) != directory_identity:
        raise SyncError("pending cleanup directory identity changed")
    if _directory_mount_identity(directory_fd) != root_mount_identity:
        raise SyncError("pending cleanup directory crosses a mount boundary")
    owns_ledger = identity_ledger is None
    if identity_ledger is None:
        identity_ledger = {}
        _capture_pending_cleanup_identity_ledger(
            directory_fd,
            directory_identity,
            root_mount_identity,
            budget,
            identity_ledger,
            depth=depth,
            relative_parts=relative_parts,
            skipped_names=skipped_names,
            name_validator=name_validator,
            directory_expected_mode=directory_expected_mode,
        )
    planned_entries = identity_ledger.pop(directory_identity, None)
    if planned_entries is None:
        raise SyncError("pending cleanup directory is absent from the identity ledger")
    entries = list(planned_entries)
    current_entries: dict[str, tuple[int, int, int]] = {}
    with os.scandir(directory_fd) as iterator:
        for entry in iterator:
            if entry.name in skipped_names:
                continue
            try:
                metadata = entry.stat(follow_symlinks=False)
            except OSError as error:
                raise SyncError(
                    f"pending cleanup entry changed: {entry.name}"
                ) from error
            active_name = (
                _pending_regular_publication_private_deletion_alias_base(entry.name)
                or entry.name
            )
            active_plan = _pending_cleanup_internal_entry_plan(
                active_name,
                PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
                directory_identity,
            )
            active_links_plan = None
            if not relative_parts:
                active_links_plan = _pending_cleanup_internal_entry_plan(
                    entry.name,
                    PENDING_CLEANUP_ACTIVE_LINKS_ENTRY_PREFIX,
                    directory_identity,
                )
            current_entries[entry.name] = (
                active_links_plan
                or active_plan
                or _pending_cleanup_entry_plan(metadata)
            )
    expected_entries = {
        name: planned for name, planned, _active, _links_root in entries
    }
    if current_entries != expected_entries:
        raise SyncError(
            "pending cleanup directory changed after identity-ledger capture; "
            "the batch was retained without deleting unknown entries"
        )
    if effective_expected_mode is None:
        _require_current_user_cleanup_fd_access_policy(
            directory_fd,
            display_path,
        )
    else:
        _require_pending_cleanup_fd_access_policy(
            directory_fd,
            display_path,
            expected_mode=effective_expected_mode,
        )

    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_CLOEXEC", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    mutated = False
    for name, planned, already_active, links_content_root in entries:
        if planned[2] not in {
            stat.S_IFDIR,
            stat.S_IFREG,
            stat.S_IFLNK,
        }:
            raise SyncError(f"pending cleanup found an unsupported entry: {name}")
        if planned[2] == stat.S_IFDIR and not already_active:
            preflight_fd = -1
            try:
                preflight_fd = os.open(
                    name,
                    directory_flags,
                    dir_fd=directory_fd,
                )
            except OSError:
                pass
            else:
                try:
                    if (
                        _directory_identity(preflight_fd) == planned[:2]
                        and _directory_mount_identity(preflight_fd)
                        != root_mount_identity
                    ):
                        raise SyncError(
                            f"pending cleanup child crosses a mount boundary: {name}"
                        )
                finally:
                    _close_fd_quietly(preflight_fd)
        active_name, current = _isolate_pending_cleanup_entry(
            directory_fd,
            name,
            directory_identity,
            planned,
            links_content_root=links_content_root,
        )
        mutated = True
        if stat.S_ISDIR(current.st_mode):
            try:
                child_fd = os.open(
                    active_name,
                    directory_flags,
                    dir_fd=directory_fd,
                )
            except OSError:
                _retain_pending_cleanup_entry(
                    directory_fd,
                    active_name,
                    directory_identity,
                    planned,
                    label=f"pending cleanup child directory changed: {name}",
                )
            try:
                child_identity = _directory_identity(child_fd)
                if child_identity != planned[:2]:
                    _retain_pending_cleanup_entry(
                        directory_fd,
                        active_name,
                        directory_identity,
                        planned,
                        label=f"pending cleanup child directory changed: {name}",
                    )
                if _directory_mount_identity(child_fd) != root_mount_identity:
                    _retain_pending_cleanup_entry(
                        directory_fd,
                        active_name,
                        directory_identity,
                        planned,
                        label=(
                            f"pending cleanup child crosses a mount boundary: {name}"
                        ),
                    )
                _remove_pending_batch_directory_contents(
                    child_fd,
                    child_identity,
                    root_mount_identity,
                    budget,
                    depth=depth + 1,
                    relative_parts=(
                        ("links",) if links_content_root else (*relative_parts, name)
                    ),
                    identity_ledger=identity_ledger,
                    name_validator=name_validator,
                    directory_expected_mode=directory_expected_mode,
                    regular_file_expected_mode=regular_file_expected_mode,
                )
                try:
                    current = os.stat(
                        active_name,
                        dir_fd=directory_fd,
                        follow_symlinks=False,
                    )
                except OSError:
                    _retain_pending_cleanup_entry(
                        directory_fd,
                        active_name,
                        directory_identity,
                        planned,
                        label=f"pending cleanup child directory changed: {name}",
                    )
                if (
                    not stat.S_ISDIR(current.st_mode)
                    or _pending_cleanup_entry_plan(current) != planned
                    or _directory_identity(child_fd) != child_identity
                ):
                    _retain_pending_cleanup_entry(
                        directory_fd,
                        active_name,
                        directory_identity,
                        planned,
                        label=f"pending cleanup child directory changed: {name}",
                    )
                try:
                    os.rmdir(active_name, dir_fd=directory_fd)
                except OSError:
                    _retain_pending_cleanup_entry(
                        directory_fd,
                        active_name,
                        directory_identity,
                        planned,
                        label=f"pending cleanup child deletion changed: {name}",
                    )
            finally:
                _close_fd_quietly(child_fd)
        elif stat.S_ISREG(current.st_mode) or stat.S_ISLNK(current.st_mode):
            if stat.S_ISREG(current.st_mode):
                file_flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
                file_flags |= getattr(os, "O_NOFOLLOW", 0)
                file_flags |= getattr(os, "O_NONBLOCK", 0)
                file_fd = -1
                try:
                    file_fd = os.open(
                        active_name,
                        file_flags,
                        dir_fd=directory_fd,
                    )
                    display_path = (
                        Path("<pending-cleanup-file>") / Path(*relative_parts) / name
                    )
                    effective_regular_file_expected_mode = (
                        _cleanup_regular_file_expected_mode(
                            regular_file_expected_mode,
                            relative_parts,
                            links_content_root=links_content_root,
                        )
                    )
                    if effective_regular_file_expected_mode is None:
                        opened = _require_current_user_cleanup_fd_access_policy(
                            file_fd,
                            display_path,
                        )
                    else:
                        opened = _require_pending_cleanup_fd_access_policy(
                            file_fd,
                            display_path,
                            expected_mode=effective_regular_file_expected_mode,
                        )
                    if _pending_cleanup_entry_plan(opened) != planned:
                        raise SyncError(f"pending cleanup regular file changed: {name}")
                except BaseException:
                    _retain_pending_cleanup_entry(
                        directory_fd,
                        active_name,
                        directory_identity,
                        planned,
                        label=f"pending cleanup regular file changed: {name}",
                    )
                finally:
                    if file_fd >= 0:
                        _close_fd_quietly(file_fd)
            try:
                os.unlink(active_name, dir_fd=directory_fd)
            except OSError:
                _retain_pending_cleanup_entry(
                    directory_fd,
                    active_name,
                    directory_identity,
                    planned,
                    label=f"pending cleanup entry deletion changed: {name}",
                )
        try:
            os.stat(
                active_name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        else:
            _retain_pending_cleanup_entry(
                directory_fd,
                active_name,
                directory_identity,
                planned,
                label=f"pending cleanup entry reappeared: {name}",
            )

    with os.scandir(directory_fd) as iterator:
        for entry in iterator:
            if entry.name in skipped_names:
                continue
            retained_plan = _pending_cleanup_internal_entry_plan(
                entry.name,
                PENDING_CLEANUP_RETAINED_ENTRY_PREFIX,
                directory_identity,
            )
            if retained_plan is not None:
                raise SyncError(
                    "pending cleanup retained entry requires manual cleanup: "
                    f"{entry.name}"
                )
            try:
                metadata = entry.stat(follow_symlinks=False)
            except OSError as error:
                raise SyncError(
                    f"pending cleanup directory gained an entry: {entry.name}"
                ) from error
            raise SyncError(
                "pending cleanup directory gained an unknown entry; the batch "
                f"was retained without deletion: {entry.name}"
            )
    if mutated:
        os.fsync(directory_fd)
    if effective_expected_mode is None:
        _require_current_user_cleanup_fd_access_policy(
            directory_fd,
            display_path,
        )
    else:
        _require_pending_cleanup_fd_access_policy(
            directory_fd,
            display_path,
            expected_mode=effective_expected_mode,
        )
    if owns_ledger and identity_ledger:
        raise SyncError("pending cleanup identity ledger was not fully consumed")


def _pending_terminal_snapshot_matches_expectation(
    snapshot: RegularFileSnapshot,
    expectation: PendingRegularTargetExpectation,
    *,
    expected_parent_identity: tuple[int, int],
) -> bool:
    return (
        snapshot.parent_identity == expected_parent_identity
        and snapshot.file_identity == expectation.file_identity
        and snapshot.sha256 == expectation.sha256
        and snapshot.size == expectation.size
        and snapshot.mode == expectation.mode
        and snapshot.uid == expectation.uid
        and snapshot.link_count >= 1
    )


def _pending_terminal_recovery_alias_name(index: int) -> str:
    if index < 0 or index >= MAX_PENDING_LINK_RECORDS:
        raise SyncError("pending terminal recovery alias index is invalid")
    return f"{PENDING_CLEANUP_TERMINAL_ALIAS_PREFIX}{index:08d}"


def _validate_pending_terminal_target_and_alias(
    home: Path,
    bound_batch_root: Path,
    batch_root_identity: tuple[int, int],
    expectation: PendingRegularTargetExpectation,
    alias_name: str,
) -> None:
    target = home / Path(*expectation.target.parts)
    target_snapshot = _read_regular_file_snapshot_beneath(
        home,
        target,
        require_managed_access=False,
    )
    if not _pending_terminal_snapshot_matches_expectation(
        target_snapshot,
        expectation,
        expected_parent_identity=expectation.parent_identity,
    ):
        raise SyncError(f"final managed regular file changed: {expectation.target}")
    alias = bound_batch_root / alias_name
    alias_snapshot = _read_regular_file_snapshot_beneath(
        home,
        alias,
        require_managed_access=False,
    )
    if not _pending_terminal_snapshot_matches_expectation(
        alias_snapshot,
        expectation,
        expected_parent_identity=batch_root_identity,
    ):
        raise SyncError(
            f"pending terminal recovery alias changed: {expectation.target}"
        )


def _ensure_pending_terminal_validation_receipt(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    bound_batch_root: Path,
    batch_fd: int,
    quarantine_root_identity: tuple[int, int],
) -> None:
    if ticket.version != 4 or not ticket.terminal_regular_targets:
        return
    existing_receipt = _read_pending_cleanup_terminal_validation(
        home,
        ticket,
        quarantine_root_identity,
    )
    if existing_receipt is not None:
        return

    for index, expectation in enumerate(ticket.terminal_regular_targets):
        alias_name = _pending_terminal_recovery_alias_name(index)
        alias_identity = _named_entry_identity(batch_fd, alias_name)
        target = home / Path(*expectation.target.parts)
        if alias_identity is None:
            target_parent_fd = _open_directory_beneath(home, target.parent)
            try:
                target_state = _read_managed_state_file_snapshot(
                    home,
                    target,
                    target_parent_fd,
                    expected_identity=expectation.file_identity,
                    maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                )
            finally:
                _close_fd_quietly(target_parent_fd)
            _publish_regular_hardlink_beneath(
                home,
                target,
                bound_batch_root / alias_name,
                target_state,
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
        elif alias_identity != expectation.file_identity:
            raise SyncError(
                f"pending terminal recovery alias changed: {expectation.target}"
            )
        _validate_pending_terminal_target_and_alias(
            home,
            bound_batch_root,
            ticket.batch_root_identity,
            expectation,
            alias_name,
        )

    os.fsync(batch_fd)
    current_ticket = _read_pending_cleanup_ticket(
        home,
        ticket.path,
        expected_ticket_identity=ticket.snapshot.file_identity,
    )
    if current_ticket is None or not _pending_cleanup_ticket_matches(
        current_ticket,
        ticket,
    ):
        raise SyncError(f"pending cleanup ticket changed: {ticket.batch_root.name}")
    _publish_pending_cleanup_terminal_validation(
        home,
        ticket,
        quarantine_root_identity,
    )
    for index, expectation in enumerate(ticket.terminal_regular_targets):
        _validate_pending_terminal_target_and_alias(
            home,
            bound_batch_root,
            ticket.batch_root_identity,
            expectation,
            _pending_terminal_recovery_alias_name(index),
        )


def _pending_cleanup_terminal_validation_payload(
    ticket: PendingBatchCleanupTicket,
    quarantine_root_identity: tuple[int, int],
) -> bytes:
    if ticket.snapshot.file_identity is None or ticket.snapshot.payload is None:
        raise SyncError("pending cleanup ticket has no validation identity")
    if ticket.version == 6:
        if (
            ticket.kind != "ephemeral-quarantine-leaf"
            or ticket.public_target is None
            or ticket.public_parent_identity is None
            or ticket.payload_file_identity is None
            or ticket.quarantine_root_identity != quarantine_root_identity
        ):
            raise SyncError("pending ephemeral cleanup has no private-phase authority")
        return _bounded_json_document(
            {
                "version": 1,
                "phase": "ephemeral-private-isolated",
                "batch": ticket.batch_root.name,
                "quarantine_root_identity": _identity_payload(quarantine_root_identity),
                "public_target": ticket.public_target.as_posix(),
                "public_parent_identity": _identity_payload(
                    ticket.public_parent_identity
                ),
                "payload_file_identity": _identity_payload(
                    ticket.payload_file_identity
                ),
                "ticket_identity": _identity_payload(ticket.snapshot.file_identity),
                "ticket_sha256": hashlib.sha256(ticket.snapshot.payload).hexdigest(),
            },
            max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
            overflow_error="pending cleanup validation receipt exceeds the size limit",
        )
    return _bounded_json_document(
        {
            "version": 1,
            "phase": "terminal-validation",
            "batch": ticket.batch_root.name,
            "batch_root_identity": _identity_payload(ticket.batch_root_identity),
            "quarantine_root_identity": _identity_payload(quarantine_root_identity),
            "ticket_identity": _identity_payload(ticket.snapshot.file_identity),
            "ticket_sha256": hashlib.sha256(ticket.snapshot.payload).hexdigest(),
        },
        max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        overflow_error="pending cleanup validation receipt exceeds the size limit",
    )


def _read_pending_cleanup_terminal_validation(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    quarantine_root_identity: tuple[int, int],
) -> ManagedStateFileSnapshot | None:
    receipt_path = _pending_cleanup_terminal_validation_path(
        home,
        ticket.batch_root.name,
    )
    index_fd = _open_directory_beneath(home, receipt_path.parent)
    try:
        receipt = _read_managed_state_file_snapshot(
            home,
            receipt_path,
            index_fd,
        )
        if not receipt.exists:
            return None
        if (
            receipt.file_type != stat.S_IFREG
            or receipt.mode != 0o600
            or receipt.uid != os.geteuid()
            or receipt.payload
            != _pending_cleanup_terminal_validation_payload(
                ticket,
                quarantine_root_identity,
            )
            or receipt.parent_identity != _directory_identity(index_fd)
        ):
            raise SyncError(
                f"pending cleanup terminal validation changed: {ticket.batch_root.name}"
            )
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            receipt_path,
            index_fd,
            receipt,
        )
        return receipt
    finally:
        _close_fd_quietly(index_fd)


def _publish_pending_cleanup_terminal_validation(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    quarantine_root_identity: tuple[int, int],
) -> ManagedStateFileSnapshot:
    existing = _read_pending_cleanup_terminal_validation(
        home,
        ticket,
        quarantine_root_identity,
    )
    if existing is not None:
        return existing
    receipt_path = _pending_cleanup_terminal_validation_path(
        home,
        ticket.batch_root.name,
    )
    receipt = _publish_atomic_exclusive_internal_file(
        home,
        receipt_path,
        _pending_cleanup_terminal_validation_payload(
            ticket,
            quarantine_root_identity,
        ),
    )
    verified = _read_pending_cleanup_terminal_validation(
        home,
        ticket,
        quarantine_root_identity,
    )
    if verified is None or not _managed_state_snapshot_matches_bound_file_evidence(
        verified,
        receipt,
    ):
        raise SyncError(
            "pending cleanup terminal validation changed after publication: "
            f"{ticket.batch_root.name}"
        )
    return verified


def _delete_pending_cleanup_terminal_validation(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    quarantine_root_identity: tuple[int, int],
    *,
    mutation_revalidator: Callable[[str, int], None] | None = None,
) -> None:
    receipt = _read_pending_cleanup_terminal_validation(
        home,
        ticket,
        quarantine_root_identity,
    )
    if receipt is None:
        return
    receipt_path = _pending_cleanup_terminal_validation_path(
        home,
        ticket.batch_root.name,
    )
    index_fd = _open_directory_beneath(home, receipt_path.parent)
    try:

        def revalidate_mutation(receipt_member: str) -> None:
            if mutation_revalidator is not None:
                mutation_revalidator(receipt_member, index_fd)

        label = f"pending cleanup terminal validation {ticket.batch_root.name}"
        if mutation_revalidator is None:
            # Preserve the historical generic-helper call shape for v4 and
            # test/mirror compatibility; only v6 needs the expanded boundary.
            _isolate_and_delete_pending_cleanup_file(
                home,
                receipt_path,
                index_fd,
                receipt,
                label=label,
            )
        else:
            _isolate_and_delete_pending_cleanup_file(
                home,
                receipt_path,
                index_fd,
                receipt,
                label=label,
                mutation_revalidator=revalidate_mutation,
            )
    finally:
        _close_fd_quietly(index_fd)


def _pending_cleanup_empty_proof_payload(
    ticket: PendingBatchCleanupTicket,
    quarantine_root_identity: tuple[int, int],
) -> bytes:
    if ticket.snapshot.file_identity is None or ticket.snapshot.payload is None:
        raise SyncError("pending cleanup ticket has no empty-proof identity")
    return _bounded_json_document(
        {
            "version": 1,
            "batch": ticket.batch_root.name,
            "batch_root_identity": _identity_payload(ticket.batch_root_identity),
            "quarantine_root_identity": _identity_payload(quarantine_root_identity),
            "isolated_name": _pending_cleanup_isolated_batch_name(
                ticket.batch_root.name
            ),
            "ticket_identity": _identity_payload(ticket.snapshot.file_identity),
            "ticket_sha256": hashlib.sha256(ticket.snapshot.payload).hexdigest(),
        },
        max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        overflow_error="pending cleanup empty proof exceeds the size limit",
    )


def _read_pending_cleanup_empty_proof(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    quarantine_root_identity: tuple[int, int],
) -> ManagedStateFileSnapshot | None:
    proof_path = _pending_cleanup_empty_proof_path(
        home,
        ticket.batch_root.name,
    )
    index_fd = _open_directory_beneath(home, proof_path.parent)
    try:
        proof = _read_managed_state_file_snapshot(
            home,
            proof_path,
            index_fd,
        )
        if not proof.exists:
            return None
        expected_payload = _pending_cleanup_empty_proof_payload(
            ticket,
            quarantine_root_identity,
        )
        if (
            proof.file_type != stat.S_IFREG
            or proof.mode != 0o600
            or proof.uid != os.geteuid()
            or proof.payload != expected_payload
            or proof.parent_identity != _directory_identity(index_fd)
        ):
            raise SyncError(
                f"pending cleanup empty proof changed: {ticket.batch_root.name}"
            )
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            proof_path,
            index_fd,
            proof,
        )
        return proof
    finally:
        _close_fd_quietly(index_fd)


def _publish_pending_cleanup_empty_proof(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    quarantine_root_identity: tuple[int, int],
) -> ManagedStateFileSnapshot:
    existing = _read_pending_cleanup_empty_proof(
        home,
        ticket,
        quarantine_root_identity,
    )
    if existing is not None:
        return existing
    proof_path = _pending_cleanup_empty_proof_path(
        home,
        ticket.batch_root.name,
    )
    proof = _publish_atomic_exclusive_internal_file(
        home,
        proof_path,
        _pending_cleanup_empty_proof_payload(
            ticket,
            quarantine_root_identity,
        ),
    )
    verified = _read_pending_cleanup_empty_proof(
        home,
        ticket,
        quarantine_root_identity,
    )
    if verified is None or not _managed_state_snapshot_matches_bound_file_evidence(
        verified,
        proof,
    ):
        raise SyncError(
            f"pending cleanup empty proof changed after publication: "
            f"{ticket.batch_root.name}"
        )
    return verified


def _delete_pending_cleanup_empty_proof(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    quarantine_root_identity: tuple[int, int],
) -> None:
    proof_path = _pending_cleanup_empty_proof_path(
        home,
        ticket.batch_root.name,
    )
    index_fd = _open_directory_beneath(home, proof_path.parent)
    try:
        joined_allocation = (
            _read_joined_quarantine_allocation_for_cleanup(home, ticket)
            if ticket.version in {5, 7}
            else None
        )
        # v5/v7 retire an allocation after the proof is gone.  A canonical
        # ticket may have just been deleted while a retained or suffix-added
        # representation of its exact bytes remains.  Such a representation is
        # blocking evidence only: it must never gain recovery or deletion
        # authority, but the proof must survive so canonical recovery does not
        # lose its exact empty-batch evidence.
        mutation_revalidator: Callable[[str], None] | None = None
        if ticket.version in {5, 7}:

            def revalidate_ticket_representations(_proof_member: str) -> None:
                _require_pending_ephemeral_ticket_representations_absent(
                    home,
                    proof_path.parent,
                    index_fd,
                    ticket.batch_root.name,
                )
                _require_joined_quarantine_allocation_unchanged(
                    home,
                    ticket,
                    joined_allocation,
                )

            mutation_revalidator = revalidate_ticket_representations
            mutation_revalidator(proof_path.name)

        proof = _read_pending_cleanup_empty_proof(
            home,
            ticket,
            quarantine_root_identity,
        )
        if proof is None:
            return
        _isolate_and_delete_pending_cleanup_file(
            home,
            proof_path,
            index_fd,
            proof,
            label=f"pending cleanup empty proof {ticket.batch_root.name}",
            mutation_revalidator=mutation_revalidator,
        )
    finally:
        _close_fd_quietly(index_fd)


def _read_pending_ephemeral_metadata_snapshot(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    bound_batch_root: Path,
    batch_fd: int,
    name: str,
) -> ManagedStateFileSnapshot:
    if (
        ticket.metadata_file_identity is None
        or ticket.metadata_mode != 0o600
        or ticket.metadata_sha256 is None
    ):
        raise SyncError("pending ephemeral cleanup authority is incomplete")
    path = bound_batch_root / name
    snapshot = _read_managed_state_file_snapshot(
        home,
        path,
        batch_fd,
        expected_identity=ticket.metadata_file_identity,
        maximum_bytes=MAX_MANAGED_STATE_BYTES,
    )
    if (
        not _managed_state_snapshot_has_complete_file_evidence(snapshot)
        or snapshot.parent_identity != ticket.batch_root_identity
        or snapshot.file_type != stat.S_IFREG
        or snapshot.mode != ticket.metadata_mode
        or (ticket.metadata_size is not None and snapshot.size != ticket.metadata_size)
        or snapshot.uid != os.geteuid()
        or snapshot.payload is None
        or hashlib.sha256(snapshot.payload).hexdigest() != ticket.metadata_sha256
    ):
        raise SyncError(
            f"pending ephemeral quarantine metadata changed: {ticket.batch_root.name}"
        )
    _require_pending_cleanup_file_snapshot_access_policy(
        home,
        path,
        batch_fd,
        snapshot,
    )
    return snapshot


def _pending_ephemeral_batch_members(
    batch_fd: int,
    batch_name: str,
) -> tuple[tuple[str, ...], str | None]:
    names = _directory_member_names(
        batch_fd,
        maximum_entries=4,
        overflow_message="pending ephemeral quarantine batch has too many entries",
    )
    retained_metadata = tuple(
        name
        for name in names
        if _pending_cleanup_retained_canonical_name(name) == "metadata.json"
    )
    if len(retained_metadata) > 1:
        raise SyncError(
            f"pending ephemeral quarantine metadata has multiple retained names: "
            f"{batch_name}"
        )
    batch_identity = _directory_identity(batch_fd)
    active_directories: list[str] = []
    for name in names:
        if name.startswith(PENDING_CLEANUP_RETAINED_ENTRY_PREFIX):
            raise SyncError(
                "pending ephemeral quarantine has retained directory evidence: "
                f"{batch_name}: {name}"
            )
        if not name.startswith(PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX):
            continue
        active_plan = _pending_cleanup_internal_entry_plan(
            name,
            PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX,
            batch_identity,
        )
        if active_plan is None or active_plan[2] != stat.S_IFDIR:
            raise SyncError(
                "pending ephemeral quarantine has malformed directory evidence: "
                f"{batch_name}: {name}"
            )
        active_directories.append(name)
    if len(active_directories) > 1:
        raise SyncError(
            "pending ephemeral quarantine has ambiguous directory evidence: "
            f"{batch_name}"
        )
    retained_name = retained_metadata[0] if retained_metadata else None
    allowed = {"leaf", "metadata.json"}
    if retained_name is not None:
        allowed.add(retained_name)
    allowed.update(active_directories)
    unknown = tuple(name for name in names if name not in allowed)
    if unknown:
        raise SyncError(
            "pending ephemeral quarantine batch has an unknown member and was "
            f"retained: {batch_name}: {unknown[0]}"
        )
    if "metadata.json" in names and retained_name is not None:
        raise SyncError(
            f"pending ephemeral quarantine metadata has canonical and retained "
            f"names: {batch_name}"
        )
    return names, retained_name


def _pending_cleanup_directory_tombstone_name(
    parent_fd: int,
    names: tuple[str, ...],
    expected_identity: tuple[int, int],
    *,
    reject_unrelated: bool,
    label: str,
) -> str | None:
    """Resolve one exact active-directory tombstone or fail on competition."""
    parent_identity = _directory_identity(parent_fd)
    expected_plan = (expected_identity[0], expected_identity[1], stat.S_IFDIR)
    matches: list[str] = []
    for name in names:
        is_active = name.startswith(PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX)
        is_retained = name.startswith(PENDING_CLEANUP_RETAINED_ENTRY_PREFIX)
        if not is_active and not is_retained:
            continue
        prefix = (
            PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX
            if is_active
            else PENDING_CLEANUP_RETAINED_ENTRY_PREFIX
        )
        encoded_plan = _pending_cleanup_internal_entry_plan(
            name,
            prefix,
            parent_identity,
        )
        actual_identity = _named_entry_identity(parent_fd, name)
        if encoded_plan is None:
            raise SyncError(f"{label} has malformed private directory evidence")
        if is_retained and (
            encoded_plan == expected_plan or actual_identity == expected_identity
        ):
            raise SyncError(f"{label} has retained private directory evidence")
        if is_active and encoded_plan == expected_plan:
            if actual_identity != expected_identity:
                raise SyncError(f"{label} private directory evidence changed")
            matches.append(name)
            continue
        if actual_identity == expected_identity or reject_unrelated:
            raise SyncError(f"{label} has competing private directory evidence")
    if len(matches) > 1:
        raise SyncError(f"{label} has ambiguous private directory evidence")
    return matches[0] if matches else None


def _pending_ephemeral_batch_root_binding(
    quarantine_fd: int,
    batch_name: str,
    isolated_name: str,
    expected_identity: tuple[int, int],
) -> tuple[str, tuple[int, int]] | None:
    names = _directory_member_names(
        quarantine_fd,
        maximum_entries=MAX_PENDING_CLEANUP_BATCH_SCAN,
        overflow_message="pending cleanup quarantine root exceeds the scan limit",
    )
    private_name = _pending_cleanup_directory_tombstone_name(
        quarantine_fd,
        names,
        expected_identity,
        reject_unrelated=False,
        label=f"pending ephemeral quarantine batch {batch_name}",
    )
    candidates: list[tuple[str, tuple[int, int]]] = []
    for name in (batch_name, isolated_name):
        identity = _named_entry_identity(quarantine_fd, name)
        if identity is not None:
            candidates.append((name, identity))
    if len(candidates) == 2:
        raise SyncError(
            "pending ephemeral quarantine has canonical and isolated roots: "
            f"{batch_name}"
        )
    if private_name is not None:
        candidates.append((private_name, expected_identity))
    if len(candidates) > 1:
        raise SyncError(
            "pending ephemeral quarantine batch changed before removal: "
            f"{batch_name}: namespace is ambiguous"
        )
    return candidates[0] if candidates else None


def _pending_ephemeral_leaf_binding(
    batch_fd: int,
    names: tuple[str, ...],
    batch_name: str,
    expected_identity: tuple[int, int],
) -> tuple[str, tuple[int, int]] | None:
    private_name = _pending_cleanup_directory_tombstone_name(
        batch_fd,
        names,
        expected_identity,
        reject_unrelated=True,
        label=f"pending ephemeral quarantine leaf {batch_name}",
    )
    candidates: list[tuple[str, tuple[int, int]]] = []
    canonical_identity = _named_entry_identity(batch_fd, "leaf")
    if canonical_identity is not None:
        candidates.append(("leaf", canonical_identity))
    if private_name is not None:
        candidates.append((private_name, expected_identity))
    if len(candidates) > 1:
        raise SyncError(
            f"pending ephemeral quarantine leaf namespace is ambiguous: {batch_name}"
        )
    return candidates[0] if candidates else None


def _require_pending_ephemeral_metadata_cleanup_boundary(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    quarantine_root: Path,
    quarantine_fd: int,
    bound_batch_root: Path,
    bound_name: str,
    batch_fd: int,
    metadata_name: str,
) -> None:
    """Reprove v5/v7 authority at a metadata rename or unlink boundary.

    Protected properties are ticket identity/content, root and batch identity,
    canonical-or-isolated path membership, owner-only access policy, and exact
    batch members.  In particular, leaf absence is rechecked here rather than
    only by the recovery caller before entering the generic deletion helper.
    """
    batch_name = ticket.batch_root.name
    isolated_name = ticket.isolated_name
    if isolated_name is None:
        raise SyncError("pending ephemeral cleanup isolated name is missing")
    _require_pending_cleanup_ticket_unchanged(home, ticket)
    _require_pending_cleanup_fd_access_policy(
        quarantine_fd,
        quarantine_root,
        expected_mode=0o700,
    )
    _require_pending_cleanup_fd_access_policy(
        batch_fd,
        bound_batch_root,
        expected_mode=0o700,
    )
    canonical_identity = _named_entry_identity(quarantine_fd, batch_name)
    isolated_identity = _named_entry_identity(quarantine_fd, isolated_name)
    expected_root_names = (
        canonical_identity == ticket.batch_root_identity and isolated_identity is None
        if bound_name == batch_name
        else canonical_identity is None
        and isolated_identity == ticket.batch_root_identity
    )
    names, retained_metadata_name = _pending_ephemeral_batch_members(
        batch_fd,
        batch_name,
    )
    expected_retained_name = None if metadata_name == "metadata.json" else metadata_name
    if any(
        name == "leaf" or name.startswith(PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX)
        for name in names
    ):
        raise SyncError(
            f"pending ephemeral scaffold leaf appeared before metadata mutation: "
            f"{batch_name}"
        )
    if (
        not expected_root_names
        or _directory_identity(quarantine_fd) != ticket.quarantine_root_identity
        or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
        or _directory_identity(batch_fd) != ticket.batch_root_identity
        or not _bound_directory_matches(home, bound_batch_root, batch_fd)
        or names != (metadata_name,)
        or retained_metadata_name != expected_retained_name
    ):
        raise SyncError(
            "pending ephemeral quarantine namespace changed before metadata "
            f"mutation: {batch_name}"
        )
    # Ticket policy/content may change while the filesystem namespace is being
    # sampled.  Make its exact second read the final external authority check.
    _require_pending_cleanup_ticket_unchanged(home, ticket)


def _require_pending_cleanup_ticket_unchanged(
    home: Path,
    ticket: PendingBatchCleanupTicket,
) -> None:
    current = _read_pending_cleanup_ticket(
        home,
        ticket.path,
        expected_ticket_identity=ticket.snapshot.file_identity,
    )
    if current is None or not _pending_cleanup_ticket_matches(current, ticket):
        raise SyncError(f"pending cleanup ticket changed: {ticket.batch_root.name}")


def _pending_ephemeral_quarantine_leaf_expectation(
    ticket: PendingBatchCleanupTicket,
) -> RegularFileSnapshot:
    if (
        ticket.public_parent_identity is None
        or ticket.payload_file_identity is None
        or ticket.payload_sha256 is None
        or ticket.payload_size is None
        or ticket.payload_mode is None
        or ticket.payload_uid is None
        or ticket.payload_gid is None
        or ticket.payload_link_count is None
    ):
        raise SyncError("pending ephemeral leaf cleanup authority is incomplete")
    return RegularFileSnapshot(
        parent_identity=ticket.public_parent_identity,
        file_identity=ticket.payload_file_identity,
        sha256=ticket.payload_sha256,
        size=ticket.payload_size,
        mode=ticket.payload_mode,
        uid=ticket.payload_uid,
        gid=ticket.payload_gid,
        link_count=ticket.payload_link_count,
    )


def _remove_pending_ephemeral_quarantine_leaf(
    home: Path,
    ticket: PendingBatchCleanupTicket,
) -> bool:
    """Resume one exact receiptless publication cleanup.

    Object identity, content stability, link count and access policy are bound
    in the durable ticket before mutation. Before the exact inode is unlinked,
    an immutable private-phase receipt binds that ticket and inode after private
    isolation. Its continued presence makes a crash after unlink distinguishable
    from the initial public state. A foreign canonical or alias observed before
    exact private isolation is evacuated from a loadable pathname and retained
    as private evidence; once exact private isolation is observable, later
    public entries are outside cleanup authority and remain in place.
    """
    if (
        ticket.version != 6
        or ticket.kind != "ephemeral-quarantine-leaf"
        or ticket.quarantine_root_identity is None
        or ticket.public_target is None
    ):
        raise SyncError("pending ephemeral leaf cleanup authority is incomplete")
    expected = _pending_ephemeral_quarantine_leaf_expectation(ticket)
    batch_name = ticket.batch_root.name
    alias_names = _pending_ephemeral_public_alias_names(batch_name)
    evidence_names = _pending_ephemeral_quarantine_evidence_names(batch_name)
    target = home / Path(*ticket.public_target.parts)
    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    public_parent_fd = -1
    quarantine_fd = -1

    def require_bound_parents() -> None:
        _require_managed_regular_parent_chain_access(
            home,
            target.parent,
            bound_parent_fd=public_parent_fd,
        )
        if _directory_identity(
            public_parent_fd
        ) != expected.parent_identity or not _bound_directory_matches(
            home, target.parent, public_parent_fd
        ):
            raise SyncError(
                f"pending ephemeral cleanup public parent changed: {target.parent}"
            )
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        if _directory_identity(
            quarantine_fd
        ) != ticket.quarantine_root_identity or not _bound_directory_matches(
            home, quarantine_root, quarantine_fd
        ):
            raise SyncError("pending cleanup quarantine root changed")

    def public_inventory() -> tuple[
        tuple[int, int] | None,
        tuple[tuple[str, tuple[int, int]], ...],
    ]:
        canonical = _named_entry_identity(public_parent_fd, target.name)
        aliases = tuple(
            (name, identity)
            for name in alias_names
            if (identity := _named_entry_identity(public_parent_fd, name)) is not None
        )
        return canonical, aliases

    def private_inventory() -> tuple[tuple[str, tuple[int, int]], ...]:
        return _pending_ephemeral_quarantine_private_inventory(
            quarantine_fd,
            batch_name,
        )

    def require_phase_receipt_unchanged(
        expected_receipt: ManagedStateFileSnapshot,
    ) -> None:
        current_receipt = _read_pending_cleanup_terminal_validation(
            home,
            ticket,
            ticket.quarantine_root_identity,
        )
        if current_receipt is None or not (
            _managed_state_snapshot_matches_bound_file_evidence(
                current_receipt,
                expected_receipt,
            )
        ):
            raise SyncError(
                "pending ephemeral cleanup private-phase receipt changed before "
                f"payload deletion: {batch_name}"
            )

    def public_evacuation_snapshot(
        name: str,
        identity: tuple[int, int],
        *,
        label: str,
        exact: bool,
    ) -> RegularFileSnapshot:
        """Capture complete, descriptor-bound evidence before a public rename.

        The protected leaf properties are object identity, regular-file type,
        content digest and size, mode/UID access policy, policy-relevant GID,
        and exact link count. The parent property is its bound identity and
        owner-controlled access policy; directory ctime and child-entry churn
        are deliberately not mutation evidence.
        """
        path = target.with_name(name)
        try:
            current = _regular_file_snapshot_at(
                public_parent_fd,
                name,
                path,
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
        except (OSError, SyncError) as error:
            raise SyncError(
                f"pending ephemeral cleanup {label} payload cannot be verified "
                f"before evacuation: {batch_name}"
            ) from error
        if (
            current.parent_identity != expected.parent_identity
            or current.file_identity != identity
            or current.uid != os.geteuid()
            or current.mode & 0o022
            or (
                exact
                and not _regular_snapshot_matches(
                    current,
                    expected.parent_identity,
                    expected,
                    expected_link_count=expected.link_count,
                )
            )
        ):
            raise SyncError(
                f"pending ephemeral cleanup {label} payload changed before "
                f"evacuation: {batch_name}"
            )
        return current

    def require_public_evacuation_unchanged(
        name: str,
        identity: tuple[int, int],
        captured: RegularFileSnapshot,
        *,
        label: str,
        exact: bool,
    ) -> RegularFileSnapshot:
        current = public_evacuation_snapshot(
            name,
            identity,
            label=label,
            exact=exact,
        )
        if not _regular_snapshot_matches(
            current,
            expected.parent_identity,
            captured,
            expected_link_count=captured.link_count,
        ):
            raise SyncError(
                f"pending ephemeral cleanup {label} payload changed before "
                f"evacuation: {batch_name}"
            )
        return current

    def require_evacuation_destination(
        destination_parent_fd: int,
        destination_parent_identity: tuple[int, int],
        destination: str,
        captured: RegularFileSnapshot,
        *,
        label: str,
        allow_public_alias_recovery: bool = False,
    ) -> bool:
        destination_path = (
            target.with_name(destination)
            if destination_parent_fd == public_parent_fd
            else quarantine_root / destination
        )
        try:
            moved = _regular_file_snapshot_at(
                destination_parent_fd,
                destination,
                destination_path,
                maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
            )
        except (OSError, SyncError) as error:
            raise SyncError(
                f"pending ephemeral cleanup {label} evacuation cannot be "
                f"verified: {batch_name}"
            ) from error
        if moved.parent_identity != destination_parent_identity:
            raise SyncError(
                f"pending ephemeral cleanup {label} evacuation changed: {batch_name}"
            )
        if (
            not _regular_snapshot_leaf_matches(moved, captured)
            or moved.link_count != captured.link_count
        ):
            if allow_public_alias_recovery:
                # The caller moved into a non-loadable public alias. Keep the
                # replacement intact, then re-inventory it so the ordinary
                # alias-to-private path can preserve it as private evidence.
                # A changed destination parent is never recoverable here.
                return False
            raise SyncError(
                f"pending ephemeral cleanup {label} replacement was retained as "
                f"isolated evidence: {batch_name}"
            )
        return True

    def move_canonical_to_safe_name(
        identity: tuple[int, int],
        *,
        exact: bool,
    ) -> None:
        for _evacuation_attempt in range(128):
            destination_parent_fd = public_parent_fd
            destination_parent_identity = expected.parent_identity
            destination = next(
                (
                    name
                    for name in alias_names
                    if _named_entry_identity(public_parent_fd, name) is None
                ),
                None,
            )
            if destination is None:
                # Every bounded non-loadable public alias may legitimately be
                # occupied by foreign evidence. Never overwrite or delete it:
                # move the exact ticket-bound canonical directly into a
                # collision-resistant final-private name. That name is already
                # recognized by v6 recovery after a crash before receipt
                # publication.
                destination_parent_fd = quarantine_fd
                destination_parent_identity = ticket.quarantine_root_identity
                destination = _pending_ephemeral_quarantine_final_private_name(
                    evidence_names[0]
                )

            captured = public_evacuation_snapshot(
                target.name,
                identity,
                label="canonical",
                exact=exact,
            )
            _require_pending_cleanup_ticket_unchanged(home, ticket)
            require_bound_parents()
            captured = require_public_evacuation_unchanged(
                target.name,
                identity,
                captured,
                label="canonical",
                exact=exact,
            )
            # Hashing the full descriptor-bound leaf can take time. Rebind
            # both authority parents and the ticket immediately before the
            # namespace mutation rather than relying on the pre-hash sample.
            _require_pending_cleanup_ticket_unchanged(home, ticket)
            require_bound_parents()
            try:
                _rename_noreplace_at(
                    public_parent_fd,
                    target.name,
                    destination_parent_fd,
                    destination,
                )
            except FileExistsError:
                # A same-UID competitor may reserve the selected public alias
                # or private evidence name after the last scan. Preserve that
                # entry and choose a fresh bounded no-replace destination.
                continue
            except FileNotFoundError as error:
                raise SyncError(
                    "pending ephemeral cleanup canonical payload disappeared "
                    f"during evacuation: {batch_name}"
                ) from error

            if destination_parent_fd != public_parent_fd:
                # Persist the private addition before the public removal. If
                # the second fsync reports an error, recovery can observe a
                # durable private exact inode (and safely retain any replayed
                # public duplicate) rather than losing both names.
                os.fsync(quarantine_fd)
            os.fsync(public_parent_fd)
            require_bound_parents()
            destination_matches = require_evacuation_destination(
                destination_parent_fd,
                destination_parent_identity,
                destination,
                captured,
                label="canonical",
                allow_public_alias_recovery=(destination_parent_fd == public_parent_fd),
            )
            if not destination_matches:
                # The replacement is safely non-loadable at this point. The
                # outer reconciliation loop will snapshot it afresh and move
                # it to private quarantine without deleting any evidence.
                return
            return
        raise SyncError(
            "pending ephemeral cleanup could not allocate a safe canonical "
            f"evacuation name: {batch_name}"
        )

    def move_alias_to_private(name: str, identity: tuple[int, int]) -> None:
        for _evacuation_attempt in range(128):
            destination = next(
                (
                    candidate
                    for candidate in evidence_names
                    if _named_entry_identity(quarantine_fd, candidate) is None
                ),
                None,
            )
            if destination is None:
                destination = _pending_ephemeral_quarantine_retained_private_name(
                    batch_name
                )
            captured = public_evacuation_snapshot(
                name,
                identity,
                label="alias",
                exact=False,
            )
            _require_pending_cleanup_ticket_unchanged(home, ticket)
            require_bound_parents()
            captured = require_public_evacuation_unchanged(
                name,
                identity,
                captured,
                label="alias",
                exact=False,
            )
            _require_pending_cleanup_ticket_unchanged(home, ticket)
            require_bound_parents()
            try:
                _rename_noreplace_at(
                    public_parent_fd,
                    name,
                    quarantine_fd,
                    destination,
                )
            except FileExistsError:
                continue
            except FileNotFoundError as error:
                raise SyncError(
                    "pending ephemeral cleanup alias payload disappeared during "
                    f"evacuation: {batch_name}"
                ) from error
            os.fsync(quarantine_fd)
            os.fsync(public_parent_fd)
            require_bound_parents()
            require_evacuation_destination(
                quarantine_fd,
                ticket.quarantine_root_identity,
                destination,
                captured,
                label="alias",
            )
            return
        raise SyncError(
            "pending ephemeral cleanup could not allocate private evidence: "
            f"{batch_name}"
        )

    def private_expected_snapshots(
        private: tuple[tuple[str, tuple[int, int]], ...],
    ) -> tuple[tuple[str, RegularFileSnapshot], ...]:
        snapshots: list[tuple[str, RegularFileSnapshot]] = []
        for name, identity in private:
            if identity != expected.file_identity:
                continue
            try:
                current = _regular_file_snapshot_at(
                    quarantine_fd,
                    name,
                    quarantine_root / name,
                    maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                )
            except (OSError, SyncError) as error:
                raise SyncError(
                    "pending ephemeral cleanup private payload cannot be verified: "
                    f"{batch_name}"
                ) from error
            if (
                current.parent_identity != ticket.quarantine_root_identity
                or not _regular_snapshot_leaf_matches(current, expected)
            ):
                raise SyncError(
                    f"pending ephemeral cleanup private payload changed: {batch_name}"
                )
            snapshots.append((name, current))
        return tuple(snapshots)

    def receipt_private_snapshots(
        private: tuple[tuple[str, tuple[int, int]], ...],
    ) -> tuple[tuple[str, RegularFileSnapshot], ...]:
        return tuple(
            (name, snapshot)
            for name, snapshot in private_expected_snapshots(private)
            if (
                name in evidence_names
                or _pending_ephemeral_quarantine_final_private_base(batch_name, name)
                is not None
            )
            and snapshot.link_count == expected.link_count
        )

    def no_public_exact_payload(
        canonical_identity: tuple[int, int] | None,
        aliases: tuple[tuple[str, tuple[int, int]], ...],
    ) -> bool:
        return canonical_identity != expected.file_identity and all(
            identity != expected.file_identity for _name, identity in aliases
        )

    try:
        public_parent_fd = _open_directory_beneath(home, target.parent)
        quarantine_fd = _open_directory_beneath(home, quarantine_root)
        for _attempt in range(32):
            require_bound_parents()
            _require_pending_cleanup_ticket_unchanged(home, ticket)
            private = private_inventory()
            canonical_identity, aliases = public_inventory()
            phase_receipt = _read_pending_cleanup_terminal_validation(
                home,
                ticket,
                ticket.quarantine_root_identity,
            )

            # A crash can land after the cross-directory rename and before the
            # receipt publication. Before acknowledging private authority,
            # prove the complete ticket snapshot and link count from the
            # private descriptor and prove that its inode is absent from every
            # derived public name. Foreign public evidence may remain, but it
            # never supplies ticket authority.
            receipt_private = (
                receipt_private_snapshots(private) if phase_receipt is None else ()
            )
            if (
                phase_receipt is None
                and len(receipt_private) == 1
                and no_public_exact_payload(canonical_identity, aliases)
            ):
                _require_pending_cleanup_ticket_unchanged(home, ticket)
                require_bound_parents()
                refreshed_private = private_inventory()
                refreshed_receipt_private = receipt_private_snapshots(refreshed_private)
                refreshed_canonical, refreshed_aliases = public_inventory()
                _require_pending_cleanup_ticket_unchanged(home, ticket)
                require_bound_parents()
                if len(refreshed_receipt_private) == 1 and no_public_exact_payload(
                    refreshed_canonical,
                    refreshed_aliases,
                ):
                    _publish_pending_cleanup_terminal_validation(
                        home,
                        ticket,
                        ticket.quarantine_root_identity,
                    )
                    continue
                private = refreshed_private
                canonical_identity, aliases = (
                    refreshed_canonical,
                    refreshed_aliases,
                )
            if phase_receipt is not None:
                if canonical_identity is not None:
                    raise SyncError(
                        "pending ephemeral cleanup public canonical reappeared "
                        "after private isolation and was retained in place: "
                        f"{target}"
                    )
                if aliases:
                    raise SyncError(
                        "pending ephemeral cleanup public alias reappeared after "
                        "private isolation and was retained in place: "
                        f"{target.with_name(aliases[0][0])}"
                    )
                if len(private) > 1 or (
                    private
                    and (
                        private[0][1] != expected.file_identity
                        or (
                            private[0][0] not in evidence_names
                            and _pending_ephemeral_quarantine_final_private_base(
                                batch_name,
                                private[0][0],
                            )
                            is None
                        )
                    )
                ):
                    raise SyncError(
                        "pending ephemeral cleanup retained replacement as isolated "
                        f"evidence after private isolation: {batch_name}"
                    )
                if not private:
                    break

                quarantine_name, _private_identity = private[0]
                quarantine_path = quarantine_root / quarantine_name
                current = _regular_file_snapshot_at(
                    quarantine_fd,
                    quarantine_name,
                    quarantine_path,
                    maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                )
                if (
                    not _regular_snapshot_leaf_matches(current, expected)
                    or current.link_count != expected.link_count
                ):
                    raise SyncError(
                        f"pending ephemeral cleanup private payload changed: "
                        f"{batch_name}"
                    )
                final_private_base = _pending_ephemeral_quarantine_final_private_base(
                    batch_name,
                    quarantine_name,
                )
                if final_private_base is None:
                    deletion_name: str | None = None
                    for _isolation_attempt in range(128):
                        candidate = _pending_ephemeral_quarantine_final_private_name(
                            quarantine_name
                        )
                        require_bound_parents()
                        final_snapshot = _regular_file_snapshot_at(
                            quarantine_fd,
                            quarantine_name,
                            quarantine_path,
                            maximum_bytes=MAX_ARCHIVE_MEMBER_BYTES,
                        )
                        if (
                            not _regular_snapshot_leaf_matches(
                                final_snapshot,
                                expected,
                            )
                            or final_snapshot.link_count != expected.link_count
                            or public_inventory() != (None, ())
                            or private_inventory()
                            != ((quarantine_name, expected.file_identity),)
                        ):
                            raise SyncError(
                                "pending ephemeral cleanup private payload changed "
                                f"before final isolation: {batch_name}"
                            )
                        require_bound_parents()
                        _require_pending_cleanup_ticket_unchanged(home, ticket)
                        require_phase_receipt_unchanged(phase_receipt)
                        try:
                            _rename_noreplace_at(
                                quarantine_fd,
                                quarantine_name,
                                quarantine_fd,
                                candidate,
                            )
                        except FileExistsError:
                            continue
                        except FileNotFoundError as error:
                            raise SyncError(
                                "pending ephemeral cleanup private payload "
                                f"disappeared during final isolation: {batch_name}"
                            ) from error
                        deletion_name = candidate
                        break
                    if deletion_name is None:
                        raise SyncError(
                            "pending ephemeral cleanup could not allocate a final "
                            f"private isolation name: {batch_name}"
                        )
                    os.fsync(quarantine_fd)
                    continue

                private_fd = -1
                flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
                flags |= getattr(os, "O_NOFOLLOW", 0)
                flags |= getattr(os, "O_NONBLOCK", 0)
                try:
                    try:
                        private_fd = os.open(
                            quarantine_name,
                            flags,
                            dir_fd=quarantine_fd,
                        )
                    except OSError as error:
                        raise SyncError(
                            "pending ephemeral cleanup final private payload "
                            f"became unreadable: {batch_name}"
                        ) from error

                    def require_open_private_unchanged(stage: str) -> None:
                        try:
                            before = _require_release_identity_fd_access_policy(
                                private_fd,
                                quarantine_path,
                                os.geteuid(),
                            )
                            os.lseek(private_fd, 0, os.SEEK_SET)
                            payload = _read_managed_state_bytes(
                                private_fd,
                                quarantine_path,
                                MAX_ARCHIVE_MEMBER_BYTES,
                            )
                            os.lseek(private_fd, 0, os.SEEK_SET)
                            confirmed_payload = _read_managed_state_bytes(
                                private_fd,
                                quarantine_path,
                                MAX_ARCHIVE_MEMBER_BYTES,
                            )
                            after = _require_release_identity_fd_access_policy(
                                private_fd,
                                quarantine_path,
                                os.geteuid(),
                            )
                            named = os.stat(
                                quarantine_name,
                                dir_fd=quarantine_fd,
                                follow_symlinks=False,
                            )
                        except (OSError, SyncError) as error:
                            raise SyncError(
                                "pending ephemeral cleanup final private payload "
                                f"changed {stage}: {batch_name}"
                            ) from error
                        expected_mode = stat.S_IMODE(before.st_mode)
                        if (
                            not stat.S_ISREG(before.st_mode)
                            or not _regular_stat_metadata_matches(after, before)
                            or not _regular_stat_metadata_matches(named, before)
                            or (before.st_dev, before.st_ino) != expected.file_identity
                            or expected_mode != expected.mode
                            or before.st_uid != expected.uid
                            or not _gid_matches_regular_file_access_policy(
                                before.st_gid,
                                expected.gid,
                                expected.mode,
                            )
                            or before.st_size != expected.size
                            or before.st_nlink != expected.link_count
                            or hashlib.sha256(payload).hexdigest() != expected.sha256
                            or hashlib.sha256(confirmed_payload).hexdigest()
                            != expected.sha256
                            or _pending_ephemeral_quarantine_final_private_base(
                                batch_name,
                                quarantine_name,
                            )
                            != final_private_base
                            or not _bound_directory_matches(
                                home,
                                quarantine_root,
                                quarantine_fd,
                            )
                        ):
                            raise SyncError(
                                "pending ephemeral cleanup final private payload "
                                f"changed {stage}: {batch_name}"
                            )

                    require_open_private_unchanged("before deletion")
                    require_bound_parents()
                    if public_inventory() != (None, ()) or private_inventory() != (
                        (quarantine_name, expected.file_identity),
                    ):
                        continue
                    # Close the namespace sample by proving both live bound
                    # parents again after walking their child entries.
                    require_bound_parents()
                    _require_pending_cleanup_ticket_unchanged(home, ticket)
                    require_phase_receipt_unchanged(phase_receipt)
                    # The broader boundary probes can race with the final
                    # pathname.  Rebind it to the still-open exact descriptor,
                    # and repeat content/access/link-count validation, before
                    # issuing the irreversible unlink.
                    require_open_private_unchanged("after boundary revalidation")
                    os.unlink(quarantine_name, dir_fd=quarantine_fd)
                    os.fsync(quarantine_fd)
                    if (
                        _named_entry_identity(quarantine_fd, quarantine_name)
                        is not None
                    ):
                        raise SyncError(
                            "pending ephemeral cleanup final private name "
                            f"reappeared: {batch_name}"
                        )
                finally:
                    _close_fd_quietly(private_fd)
                continue

            if canonical_identity == expected.file_identity:
                # Retire the loadable canonical name before preserving a
                # competing derived alias.  A same-UID creator can publish an
                # alias after ticket creation but before this first scan; if
                # that alias reached private evidence first, the recovery
                # would fail closed while leaving the ticket-bound canonical
                # publication loadable.
                move_canonical_to_safe_name(canonical_identity, exact=True)
                continue
            # Preserve every observed foreign alias before advancing the
            # ticket-bound inode to exact private isolation.  Selecting by
            # identity, rather than alias-slot order, keeps a foreign creator
            # from remaining in the public namespace when the canonical
            # evacuation happened to take an earlier slot.
            foreign_alias = next(
                (item for item in aliases if item[1] != expected.file_identity),
                None,
            )
            if foreign_alias is not None:
                alias_name, alias_identity = foreign_alias
                move_alias_to_private(alias_name, alias_identity)
                continue
            if len(private) > 1 or private:
                raise SyncError(
                    "pending ephemeral cleanup retained replacement as isolated "
                    f"evidence while attempting private isolation: {batch_name}"
                )
            if aliases:
                alias_name, alias_identity = aliases[0]
                move_alias_to_private(alias_name, alias_identity)
                continue
            if canonical_identity is not None:
                move_canonical_to_safe_name(canonical_identity, exact=False)
                continue
            raise SyncError(
                "pending ephemeral cleanup exact payload disappeared before "
                f"private isolation: {batch_name}"
            )
        else:
            raise SyncError(
                "pending ephemeral cleanup did not reach a stable private state: "
                f"{batch_name}"
            )

        _require_pending_cleanup_ticket_unchanged(home, ticket)
        require_bound_parents()
        if public_inventory() != (None, ()) or private_inventory():
            raise SyncError(
                f"pending ephemeral cleanup payload reappeared: {batch_name}"
            )
        # Delete the ticket first. The private-phase receipt remains durable
        # across this boundary, so a crash cannot turn a completed private
        # unlink into an apparent initial public state. Keep both bound parent
        # descriptors live through receipt retirement and reprove every derived
        # public/private name at each mutation boundary.
        _delete_pending_cleanup_ticket(home, ticket)

        def require_terminal_receipt_boundary(
            _receipt_member: str,
            index_fd: int,
        ) -> None:
            _require_pending_ephemeral_terminal_names_absent(
                home,
                target,
                public_parent_fd,
                expected.parent_identity,
                quarantine_root,
                quarantine_fd,
                ticket.quarantine_root_identity,
                batch_name,
            )
            _require_pending_ephemeral_ticket_representations_absent(
                home,
                ticket.path.parent,
                index_fd,
                batch_name,
            )

        _delete_pending_cleanup_terminal_validation(
            home,
            ticket,
            ticket.quarantine_root_identity,
            mutation_revalidator=require_terminal_receipt_boundary,
        )
    finally:
        _close_fd_quietly(quarantine_fd)
        _close_fd_quietly(public_parent_fd)
    return True


def _remove_pending_ephemeral_quarantine_batch(
    home: Path,
    ticket: PendingBatchCleanupTicket,
) -> bool:
    """Resume only the exact empty scaffold authorized by a v5/v7 ticket."""
    expected_kind = (
        "ephemeral-quarantine"
        if ticket.version == 5
        else "ephemeral-quarantine-scaffold"
    )
    if (
        ticket.version not in {5, 7}
        or ticket.kind != expected_kind
        or ticket.quarantine_root_identity is None
        or ticket.isolated_name
        != _pending_cleanup_isolated_batch_name(ticket.batch_root.name)
        or (ticket.version == 5 and ticket.leaf_identity is None)
        or (ticket.version == 7 and ticket.leaf_identity is not None)
    ):
        raise SyncError("pending ephemeral cleanup authority is incomplete")
    joined_allocation = _read_joined_quarantine_allocation_for_cleanup(home, ticket)

    def require_allocation_join() -> None:
        _require_joined_quarantine_allocation_unchanged(
            home,
            ticket,
            joined_allocation,
        )

    require_allocation_join()
    quarantine_root = ticket.batch_root.parent
    try:
        quarantine_fd = _open_directory_beneath(home, quarantine_root)
    except FileNotFoundError as error:
        raise SyncError("pending cleanup quarantine root is missing") from error
    batch_fd = -1
    leaf_fd = -1
    quarantine_root_identity = ticket.quarantine_root_identity
    batch_name = ticket.batch_root.name
    isolated_name = ticket.isolated_name
    assert isolated_name is not None
    bound_batch_root = ticket.batch_root
    directory_flags = _directory_open_flags(nofollow=True)

    def current_batch_root_binding() -> tuple[str, tuple[int, int]] | None:
        return _pending_ephemeral_batch_root_binding(
            quarantine_fd,
            batch_name,
            isolated_name,
            ticket.batch_root_identity,
        )

    try:
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        if _directory_identity(
            quarantine_fd
        ) != quarantine_root_identity or not _bound_directory_matches(
            home, quarantine_root, quarantine_fd
        ):
            raise SyncError("pending cleanup quarantine root changed")
        root_binding = current_batch_root_binding()
        if root_binding is None:
            proof = _read_pending_cleanup_empty_proof(
                home,
                ticket,
                quarantine_root_identity,
            )
            if proof is None:
                raise SyncError(
                    "pending cleanup batch root is missing without an exact "
                    f"empty proof: {batch_name}"
                )
            _delete_pending_cleanup_ticket(home, ticket)
            _delete_pending_cleanup_empty_proof(
                home,
                ticket,
                quarantine_root_identity,
            )
            require_allocation_join()
            _retire_joined_quarantine_allocation(
                home,
                ticket,
                joined_allocation,
            )
            return True
        bound_name, observed_identity = root_binding
        bound_batch_root = ticket.batch_root.with_name(bound_name)
        if observed_identity != ticket.batch_root_identity:
            raise SyncError(f"pending ephemeral quarantine batch changed: {batch_name}")
        batch_fd = os.open(bound_name, directory_flags, dir_fd=quarantine_fd)
        if _directory_identity(
            batch_fd
        ) != ticket.batch_root_identity or not _bound_directory_matches(
            home, bound_batch_root, batch_fd
        ):
            raise SyncError(f"pending ephemeral quarantine batch changed: {batch_name}")
        _require_pending_cleanup_fd_access_policy(
            batch_fd,
            bound_batch_root,
            expected_mode=0o700,
        )
        _require_pending_cleanup_ticket_unchanged(home, ticket)
        names, retained_metadata_name = _pending_ephemeral_batch_members(
            batch_fd,
            batch_name,
        )
        leaf_binding = (
            None
            if ticket.leaf_identity is None
            else _pending_ephemeral_leaf_binding(
                batch_fd,
                names,
                batch_name,
                ticket.leaf_identity,
            )
        )
        if ticket.version == 7 and any(
            name == "leaf" or name.startswith(PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX)
            for name in names
        ):
            raise SyncError(f"pending ephemeral scaffold leaf appeared: {batch_name}")
        if leaf_binding is not None:
            leaf_name, observed_leaf_identity = leaf_binding
            if observed_leaf_identity != ticket.leaf_identity:
                raise SyncError(
                    f"pending ephemeral quarantine leaf changed: {batch_name}"
                )
            leaf_path = bound_batch_root / leaf_name
            leaf_fd = os.open(leaf_name, directory_flags, dir_fd=batch_fd)
            if _directory_identity(
                leaf_fd
            ) != ticket.leaf_identity or not _bound_directory_matches(
                home, leaf_path, leaf_fd
            ):
                raise SyncError(
                    f"pending ephemeral quarantine leaf changed: {batch_name}"
                )
            _require_pending_cleanup_fd_access_policy(
                leaf_fd,
                leaf_path,
                expected_mode=0o700,
            )
            if _directory_member_names(leaf_fd, maximum_entries=1) != ():
                raise SyncError(
                    f"pending ephemeral quarantine leaf is not empty: {batch_name}"
                )
            names, retained_metadata_name = _pending_ephemeral_batch_members(
                batch_fd,
                batch_name,
            )
            current_leaf_binding = _pending_ephemeral_leaf_binding(
                batch_fd,
                names,
                batch_name,
                ticket.leaf_identity,
            )
            if current_leaf_binding != (leaf_name, ticket.leaf_identity):
                raise SyncError(
                    f"pending ephemeral quarantine leaf changed: {batch_name}"
                )
            _require_pending_cleanup_ticket_unchanged(home, ticket)
            _require_pending_cleanup_fd_access_policy(
                batch_fd,
                bound_batch_root,
                expected_mode=0o700,
            )
            _require_pending_cleanup_fd_access_policy(
                leaf_fd,
                leaf_path,
                expected_mode=0o700,
            )
            if (
                current_batch_root_binding() != (bound_name, ticket.batch_root_identity)
                or _directory_identity(quarantine_fd) != quarantine_root_identity
                or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
                or _directory_identity(batch_fd) != ticket.batch_root_identity
                or not _bound_directory_matches(home, bound_batch_root, batch_fd)
                or _directory_identity(leaf_fd) != ticket.leaf_identity
                or not _bound_directory_matches(home, leaf_path, leaf_fd)
                or _directory_member_names(leaf_fd, maximum_entries=1) != ()
                or current_leaf_binding != (leaf_name, ticket.leaf_identity)
            ):
                raise SyncError(
                    f"pending ephemeral quarantine leaf changed before removal: "
                    f"{batch_name}"
                )
            _rmdir_bound_empty_pending_cleanup_directory(
                home,
                bound_batch_root,
                batch_fd,
                ticket.batch_root_identity,
                leaf_name,
                leaf_path,
                leaf_fd,
                ticket.leaf_identity,
                changed_message=(
                    "pending ephemeral quarantine leaf changed before removal: "
                    f"{batch_name}"
                ),
                mutation_revalidator=require_allocation_join,
            )
            os.fsync(batch_fd)
            names, _retained_metadata_name = _pending_ephemeral_batch_members(
                batch_fd,
                batch_name,
            )
            if any(
                name == "leaf" or name.startswith(PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX)
                for name in names
            ):
                raise SyncError(
                    f"pending ephemeral quarantine leaf reappeared: {batch_name}"
                )
        names, retained_metadata_name = _pending_ephemeral_batch_members(
            batch_fd,
            batch_name,
        )
        if any(
            name == "leaf" or name.startswith(PENDING_CLEANUP_ACTIVE_ENTRY_PREFIX)
            for name in names
        ):
            raise SyncError(
                f"pending ephemeral quarantine leaf reappeared: {batch_name}"
            )
        metadata_name = (
            "metadata.json" if "metadata.json" in names else retained_metadata_name
        )
        if metadata_name is not None:
            _require_pending_cleanup_ticket_unchanged(home, ticket)
            _require_pending_cleanup_fd_access_policy(
                quarantine_fd,
                quarantine_root,
                expected_mode=0o700,
            )
            _require_pending_cleanup_fd_access_policy(
                batch_fd,
                bound_batch_root,
                expected_mode=0o700,
            )
            metadata = _read_pending_ephemeral_metadata_snapshot(
                home,
                ticket,
                bound_batch_root,
                batch_fd,
                metadata_name,
            )
            if metadata_name != "metadata.json":
                require_allocation_join()
                metadata = _restore_exact_retained_pending_cleanup_file(
                    home,
                    bound_batch_root / "metadata.json",
                    batch_fd,
                    metadata_name,
                    metadata,
                    label=f"pending ephemeral quarantine metadata {batch_name}",
                )
                names = tuple(
                    "metadata.json" if name == metadata_name else name for name in names
                )
                retained_metadata_name = None
            current_names, current_retained_metadata = _pending_ephemeral_batch_members(
                batch_fd, batch_name
            )
            if (
                current_batch_root_binding() != (bound_name, ticket.batch_root_identity)
                or _directory_identity(quarantine_fd) != quarantine_root_identity
                or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
                or _directory_identity(batch_fd) != ticket.batch_root_identity
                or not _bound_directory_matches(home, bound_batch_root, batch_fd)
                or current_names != names
                or current_retained_metadata != retained_metadata_name
            ):
                raise SyncError(
                    "pending ephemeral quarantine namespace changed before "
                    f"metadata removal: {batch_name}"
                )

            def require_metadata_mutation_boundary(metadata_member: str) -> None:
                _require_pending_ephemeral_metadata_cleanup_boundary(
                    home,
                    ticket,
                    quarantine_root,
                    quarantine_fd,
                    bound_batch_root,
                    bound_name,
                    batch_fd,
                    metadata_member,
                )
                require_allocation_join()

            _isolate_and_delete_pending_cleanup_file(
                home,
                bound_batch_root / "metadata.json",
                batch_fd,
                metadata,
                label=f"pending ephemeral quarantine metadata {batch_name}",
                mutation_revalidator=require_metadata_mutation_boundary,
            )
        names, _retained_metadata_name = _pending_ephemeral_batch_members(
            batch_fd,
            batch_name,
        )
        if names:
            raise SyncError(
                f"pending ephemeral quarantine batch is not empty: {batch_name}"
            )
        _require_pending_cleanup_ticket_unchanged(home, ticket)
        _require_pending_cleanup_fd_access_policy(
            batch_fd,
            bound_batch_root,
            expected_mode=0o700,
        )
        if bound_name == batch_name:
            if (
                _directory_identity(quarantine_fd) != quarantine_root_identity
                or not _bound_directory_matches(
                    home,
                    quarantine_root,
                    quarantine_fd,
                )
                or _directory_identity(batch_fd) != ticket.batch_root_identity
                or not _bound_directory_matches(home, bound_batch_root, batch_fd)
                or _directory_member_names(batch_fd, maximum_entries=1) != ()
                or current_batch_root_binding()
                != (batch_name, ticket.batch_root_identity)
            ):
                raise SyncError(
                    f"pending ephemeral quarantine batch changed: {batch_name}"
                )
            # Identity alone does not preserve the root's access policy.  Recheck
            # the exact bound FD immediately before the canonical namespace is
            # renamed so same-inode mode, UID, or Darwin ACL drift cannot create
            # an isolated root or a terminal empty proof.
            _require_pending_cleanup_fd_access_policy(
                quarantine_fd,
                quarantine_root,
                expected_mode=0o700,
            )
            require_allocation_join()
            _rename_noreplace_at(
                quarantine_fd,
                batch_name,
                quarantine_fd,
                isolated_name,
            )
            os.fsync(quarantine_fd)
            bound_name = isolated_name
            bound_batch_root = ticket.batch_root.with_name(isolated_name)
        elif current_batch_root_binding() != (
            bound_name,
            ticket.batch_root_identity,
        ):
            raise SyncError(f"pending ephemeral quarantine batch changed: {batch_name}")
        if (
            _directory_identity(batch_fd) != ticket.batch_root_identity
            or not _bound_directory_matches(home, bound_batch_root, batch_fd)
            or _directory_member_names(batch_fd, maximum_entries=1) != ()
        ):
            raise SyncError(
                f"pending ephemeral quarantine batch changed after isolation: "
                f"{batch_name}"
            )
        require_allocation_join()
        _publish_pending_cleanup_empty_proof(
            home,
            ticket,
            quarantine_root_identity,
        )
        _require_pending_cleanup_ticket_unchanged(home, ticket)
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        _require_pending_cleanup_fd_access_policy(
            batch_fd,
            bound_batch_root,
            expected_mode=0o700,
        )
        batch_removal_changed_message = (
            f"pending ephemeral quarantine batch changed before removal: {batch_name}"
        )

        def require_batch_rmdir_mutation_boundary() -> None:
            require_allocation_join()
            try:
                root_binding = current_batch_root_binding()
            except SyncError as error:
                raise SyncError(batch_removal_changed_message) from error
            if root_binding != (bound_name, ticket.batch_root_identity):
                raise SyncError(batch_removal_changed_message)

        try:
            final_root_binding = current_batch_root_binding()
        except SyncError as error:
            raise SyncError(batch_removal_changed_message) from error
        if (
            _directory_identity(quarantine_fd) != quarantine_root_identity
            or not _bound_directory_matches(home, quarantine_root, quarantine_fd)
            or final_root_binding != (bound_name, ticket.batch_root_identity)
            or _directory_identity(batch_fd) != ticket.batch_root_identity
            or not _bound_directory_matches(home, bound_batch_root, batch_fd)
            or _directory_member_names(batch_fd, maximum_entries=1) != ()
        ):
            raise SyncError(batch_removal_changed_message)
        _rmdir_bound_empty_pending_cleanup_directory(
            home,
            quarantine_root,
            quarantine_fd,
            quarantine_root_identity,
            bound_name,
            bound_batch_root,
            batch_fd,
            ticket.batch_root_identity,
            changed_message=batch_removal_changed_message,
            mutation_revalidator=require_batch_rmdir_mutation_boundary,
        )
        os.fsync(quarantine_fd)
        if current_batch_root_binding() is not None:
            raise SyncError(
                f"pending ephemeral quarantine batch reappeared: {batch_name}"
            )
    finally:
        _close_fd_quietly(leaf_fd)
        _close_fd_quietly(batch_fd)
        _close_fd_quietly(quarantine_fd)
    _delete_pending_cleanup_ticket(home, ticket)
    _delete_pending_cleanup_empty_proof(
        home,
        ticket,
        quarantine_root_identity,
    )
    require_allocation_join()
    _retire_joined_quarantine_allocation(
        home,
        ticket,
        joined_allocation,
    )
    return True


def _remove_cleanup_ready_batch(
    home: Path,
    ticket: PendingBatchCleanupTicket,
) -> bool:
    if not _pending_link_pointer_is_absent(home):
        raise SyncError("refusing pending cleanup while an active pointer exists")
    current_ticket = _read_pending_cleanup_ticket(
        home,
        ticket.path,
        expected_ticket_identity=ticket.snapshot.file_identity,
    )
    if current_ticket is None or not _pending_cleanup_ticket_matches(
        current_ticket,
        ticket,
    ):
        raise SyncError(f"pending cleanup ticket changed: {ticket.batch_root.name}")
    if ticket.version in {5, 7}:
        return _remove_pending_ephemeral_quarantine_batch(home, ticket)
    if ticket.version == 6:
        return _remove_pending_ephemeral_quarantine_leaf(home, ticket)
    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    try:
        quarantine_fd = _open_directory_beneath(home, quarantine_root)
    except FileNotFoundError as error:
        raise SyncError("pending cleanup quarantine root is missing") from error
    batch_fd = -1
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_CLOEXEC", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    try:
        if not _bound_directory_matches(home, quarantine_root, quarantine_fd):
            raise SyncError("pending cleanup quarantine root changed")
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        quarantine_root_identity = _directory_identity(quarantine_fd)
        batch_name = ticket.batch_root.name
        isolated_name = _pending_cleanup_isolated_batch_name(batch_name)
        bound_batch_root = ticket.batch_root
        try:
            batch_fd = os.open(
                batch_name,
                directory_flags,
                dir_fd=quarantine_fd,
            )
        except FileNotFoundError:
            bound_batch_root = ticket.batch_root.with_name(isolated_name)
            try:
                batch_fd = os.open(
                    isolated_name,
                    directory_flags,
                    dir_fd=quarantine_fd,
                )
            except FileNotFoundError:
                proof = _read_pending_cleanup_empty_proof(
                    home,
                    ticket,
                    quarantine_root_identity,
                )
                if proof is None:
                    if ticket.version in {1, 2}:
                        _delete_pending_cleanup_ticket(home, ticket)
                        return True
                    raise SyncError(
                        "pending cleanup batch root is missing without an exact "
                        f"empty proof: {batch_name}"
                    )
                _verify_final_regular_targets(home, ticket)
                _delete_pending_cleanup_terminal_validation(
                    home,
                    ticket,
                    quarantine_root_identity,
                )
                _delete_pending_cleanup_ticket(home, ticket)
                _delete_pending_cleanup_empty_proof(
                    home,
                    ticket,
                    quarantine_root_identity,
                )
                return True
        if _directory_identity(
            batch_fd
        ) != ticket.batch_root_identity or not _bound_directory_matches(
            home, bound_batch_root, batch_fd
        ):
            raise SyncError(f"pending cleanup batch root changed: {batch_name}")
        _require_pending_cleanup_fd_access_policy(
            batch_fd,
            bound_batch_root,
            expected_mode=0o700,
        )
        if ticket.version == 3:
            _require_no_pending_staging_manual_retention(
                home,
                bound_batch_root,
            )
        _ensure_pending_terminal_validation_receipt(
            home,
            ticket,
            bound_batch_root,
            batch_fd,
            quarantine_root_identity,
        )
        _remove_pending_batch_directory_contents(
            batch_fd,
            ticket.batch_root_identity,
            _directory_mount_identity(batch_fd),
            [MAX_PENDING_CLEANUP_ENTRIES],
            depth=0,
            name_validator=_pending_batch_cleanup_name_is_authorized,
        )
        with os.scandir(batch_fd) as iterator:
            if next(iterator, None) is not None:
                raise SyncError(f"pending cleanup batch is not empty: {batch_name}")
        if bound_batch_root == ticket.batch_root:
            _rename_noreplace_at(
                quarantine_fd,
                batch_name,
                quarantine_fd,
                isolated_name,
            )
            os.fsync(quarantine_fd)
            bound_batch_root = ticket.batch_root.with_name(isolated_name)
        current_root = os.stat(
            isolated_name,
            dir_fd=quarantine_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISDIR(current_root.st_mode)
            or (current_root.st_dev, current_root.st_ino) != ticket.batch_root_identity
            or _directory_identity(batch_fd) != ticket.batch_root_identity
            or not _bound_directory_matches(home, bound_batch_root, batch_fd)
        ):
            raise SyncError(f"pending cleanup batch root changed: {batch_name}")
        _require_pending_cleanup_fd_access_policy(
            batch_fd,
            bound_batch_root,
            expected_mode=0o700,
        )
        _publish_pending_cleanup_empty_proof(
            home,
            ticket,
            quarantine_root_identity,
        )
        os.rmdir(isolated_name, dir_fd=quarantine_fd)
        os.fsync(quarantine_fd)
        if _named_entry_identity(quarantine_fd, isolated_name) is not None:
            raise SyncError(f"pending cleanup batch root reappeared: {batch_name}")
    finally:
        if batch_fd >= 0:
            _close_fd_quietly(batch_fd)
        _close_fd_quietly(quarantine_fd)
    _verify_final_regular_targets(home, ticket)
    _delete_pending_cleanup_terminal_validation(
        home,
        ticket,
        quarantine_root_identity,
    )
    _delete_pending_cleanup_ticket(home, ticket)
    _delete_pending_cleanup_empty_proof(
        home,
        ticket,
        quarantine_root_identity,
    )
    return True


def _delete_pending_cleanup_ticket(
    home: Path,
    ticket: PendingBatchCleanupTicket,
    *,
    boundary_revalidator: Callable[[], None] | None = None,
) -> None:
    index_fd = _open_directory_beneath(home, ticket.path.parent)
    try:
        joined_allocation = (
            _read_joined_quarantine_allocation_for_cleanup(home, ticket)
            if ticket.version in {5, 7}
            else None
        )
        current = _read_managed_state_file_snapshot(
            home,
            ticket.path,
            index_fd,
            expected_identity=ticket.snapshot.file_identity,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            current,
            ticket.snapshot,
        ):
            raise SyncError(f"pending cleanup ticket changed: {ticket.batch_root.name}")
        mutation_revalidator: Callable[[str], None] | None = None
        if ticket.version in {5, 7}:

            def revalidate_allocation_join(_ticket_member: str) -> None:
                _require_joined_quarantine_allocation_unchanged(
                    home,
                    ticket,
                    joined_allocation,
                )
                if boundary_revalidator is not None:
                    boundary_revalidator()

            mutation_revalidator = revalidate_allocation_join
            mutation_revalidator(ticket.path.name)
        elif boundary_revalidator is not None:

            def revalidate_boundary(_ticket_member: str) -> None:
                boundary_revalidator()

            mutation_revalidator = revalidate_boundary
            mutation_revalidator(ticket.path.name)
        label = f"pending cleanup ticket {ticket.batch_root.name}"
        if mutation_revalidator is None:
            _isolate_and_delete_pending_cleanup_file(
                home,
                ticket.path,
                index_fd,
                ticket.snapshot,
                label=label,
            )
        else:
            _isolate_and_delete_pending_cleanup_file(
                home,
                ticket.path,
                index_fd,
                ticket.snapshot,
                label=label,
                mutation_revalidator=mutation_revalidator,
            )
        remaining = _read_managed_state_file_snapshot(
            home,
            ticket.path,
            index_fd,
        )
        if remaining.exists:
            raise SyncError(
                f"pending cleanup ticket reappeared: {ticket.batch_root.name}"
            )
    finally:
        _close_fd_quietly(index_fd)


def _try_cleanup_finalized_pending_batch(
    home: Path,
    batch: PendingLinkBatch,
) -> bool:
    if batch.pointer_snapshot is not None:
        print("warning: committed pending transaction still has an active pointer")
        return False
    try:
        ticket = _read_pending_cleanup_ticket(
            home,
            _pending_cleanup_ticket_path(home, batch.batch_root.name),
        )
        if ticket is None:
            raise SyncError("committed pending cleanup ticket is missing")
        if ticket.batch_root_identity != batch.batch_root_identity:
            raise SyncError("committed pending cleanup batch identity changed")
        return _remove_cleanup_ready_batch(home, ticket)
    except (OSError, SyncError) as error:
        print(
            "warning: committed pending transaction cleanup was deferred: "
            f"{batch.batch_root.name}: {error}"
        )
        return False


def _read_pending_cleanup_cursor(home: Path, index_root: Path) -> str | None:
    cursor_path = index_root / PENDING_CLEANUP_CURSOR_NAME
    try:
        index_fd = _open_directory_beneath(home, index_root)
        try:
            snapshot = _read_managed_state_file_snapshot(
                home,
                cursor_path,
                index_fd,
            )
        finally:
            _close_fd_quietly(index_fd)
    except (OSError, SyncError) as error:
        print(f"warning: ignoring invalid pending cleanup scan cursor: {error}")
        return None
    if not snapshot.exists:
        return None
    if snapshot.mode != 0o600 or snapshot.payload is None:
        print("warning: ignoring invalid pending cleanup scan cursor mode")
        return None
    try:
        cursor_name = snapshot.payload.decode("ascii").removesuffix("\n")
    except UnicodeDecodeError as error:
        print(f"warning: ignoring invalid pending cleanup scan cursor: {error}")
        return None
    if snapshot.payload != (cursor_name + "\n").encode("ascii"):
        print("warning: ignoring non-canonical pending cleanup scan cursor")
        return None
    if not cursor_name.endswith(PENDING_CLEANUP_TICKET_SUFFIX):
        print("warning: ignoring invalid pending cleanup scan cursor ticket")
        return None
    batch_name = cursor_name[: -len(PENDING_CLEANUP_TICKET_SUFFIX)]
    if (
        len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
    ):
        print("warning: ignoring invalid pending cleanup scan cursor batch")
        return None
    return cursor_name


def _write_pending_cleanup_cursor(
    home: Path,
    index_root: Path,
    ticket_name: str,
    *,
    max_temp_cleanup_actions: int = MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
) -> int:
    if max_temp_cleanup_actions < 0:
        raise SyncError("pending cleanup scan cursor temp action budget is invalid")
    cursor_path = index_root / PENDING_CLEANUP_CURSOR_NAME
    temp_path = index_root / PENDING_CLEANUP_CURSOR_TEMP_NAME
    payload = (ticket_name + "\n").encode("ascii")
    if max_temp_cleanup_actions == 0 and _pending_cleanup_temp_residue_is_observed(
        home, temp_path
    ):
        return 0
    discarded = _cleanup_pending_cleanup_cursor_temp(
        home,
        index_root,
        limit=max_temp_cleanup_actions,
    )
    if _pending_cleanup_temp_residue_is_observed(home, temp_path):
        return discarded
    staged = _write_exclusive_internal_file(home, temp_path, payload)
    index_fd = _open_directory_beneath(home, index_root)
    try:
        current_temp = _read_managed_state_file_snapshot(
            home,
            temp_path,
            index_fd,
            expected_identity=staged.file_identity,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(
            current_temp,
            staged,
        ):
            raise SyncError("pending cleanup scan cursor temp changed")
        os.rename(
            temp_path.name,
            cursor_path.name,
            src_dir_fd=index_fd,
            dst_dir_fd=index_fd,
        )
        os.fsync(index_fd)
        published = _read_managed_state_file_snapshot(
            home,
            cursor_path,
            index_fd,
            expected_identity=staged.file_identity,
        )
        if published.payload != payload or published.mode != 0o600:
            raise SyncError("pending cleanup scan cursor changed during publication")
    finally:
        _close_fd_quietly(index_fd)
    return discarded


def _cleanup_pending_cleanup_cursor_temp(
    home: Path,
    index_root: Path,
    *,
    limit: int,
) -> int:
    if limit < 0:
        raise SyncError("pending cleanup scan cursor temp action budget is invalid")
    return _discard_incomplete_pending_cleanup_ticket(
        home,
        index_root / PENDING_CLEANUP_CURSOR_TEMP_NAME,
        max_actions=limit,
    )


def _pending_cleanup_retained_canonical_name(name: str) -> str | None:
    if not name.startswith(PENDING_CLEANUP_RETAINED_PREFIX):
        return None
    retained = name[len(PENDING_CLEANUP_RETAINED_PREFIX) :]
    match = re.fullmatch(r"(.+)-[0-9]+-[0-9a-f]{16}", retained)
    if match is None:
        return None
    return match.group(1)


def _pending_cleanup_ticket_representation_batch_name(name: str) -> str | None:
    """Classify ticket-derived residue as blocking evidence, never authority.

    A canonical ticket or its normal retained form has a strict parser elsewhere
    that may restore only the exact, bound object.  This classifier is
    intentionally broader: a suffix-added or otherwise malformed descendant of
    a syntactically valid ``<batch>.json`` name retains recoverable ticket bytes
    and must block terminal receipt retirement and subsequent mutations.  It is
    not a recovery parser and callers must never use its result to authorize a
    destructive action.
    """
    candidate = name
    if candidate.startswith(PENDING_CLEANUP_RETAINED_PREFIX):
        candidate = candidate[len(PENDING_CLEANUP_RETAINED_PREFIX) :]
    marker_index = candidate.find(PENDING_CLEANUP_TICKET_SUFFIX)
    if marker_index <= 0:
        return None
    batch_name = candidate[:marker_index]
    if (
        len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
    ):
        return None
    return batch_name


def _pending_cleanup_ticket_temp_batch_name(name: str) -> str | None:
    if not name.endswith(PENDING_CLEANUP_TICKET_TEMP_SUFFIX):
        return None
    batch_name = name[: -len(PENDING_CLEANUP_TICKET_TEMP_SUFFIX)]
    if (
        len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
    ):
        return None
    return batch_name


def _pending_private_use_retirement_batch_name(name: str) -> str | None:
    if not name.endswith(PENDING_PRIVATE_USE_RETIREMENT_SUFFIX):
        return None
    batch_name = name[: -len(PENDING_PRIVATE_USE_RETIREMENT_SUFFIX)]
    if (
        len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
    ):
        return None
    return batch_name


def _pending_private_use_retirement_temp_batch_name(name: str) -> str | None:
    suffix = (
        PENDING_PRIVATE_USE_RETIREMENT_SUFFIX + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX
    )
    if not name.endswith(suffix):
        return None
    batch_name = name[: -len(suffix)]
    if (
        len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
    ):
        return None
    return batch_name


def _pending_private_use_retirement_representation_batch_name(
    name: str,
) -> str | None:
    candidate = name
    if candidate.startswith(PENDING_CLEANUP_RETAINED_PREFIX):
        candidate = candidate[len(PENDING_CLEANUP_RETAINED_PREFIX) :]
    marker_index = candidate.find(PENDING_PRIVATE_USE_RETIREMENT_SUFFIX)
    if marker_index <= 0:
        return None
    batch_name = candidate[:marker_index]
    if (
        len(batch_name) <= MAX_PENDING_LINK_BATCH_NAME_BYTES
        and PENDING_LINK_BATCH_RE.fullmatch(batch_name) is not None
    ):
        return batch_name
    return None


def _pending_private_use_retirement_unresolved_representation(
    name: str,
) -> tuple[str, str] | None:
    batch_name = _pending_private_use_retirement_representation_batch_name(name)
    if batch_name is None:
        return None
    canonical = batch_name + PENDING_PRIVATE_USE_RETIREMENT_SUFFIX
    temporary = canonical + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX
    if name in {canonical, temporary}:
        return None
    retained = _pending_cleanup_retained_control_name(name)
    if retained is not None and retained[1] == batch_name and retained[0] == canonical:
        return None
    retained_canonical = _pending_cleanup_retained_canonical_name(name)
    if retained_canonical == temporary:
        return None
    return batch_name, name


def _pending_cleanup_retained_ticket_temp_name(
    name: str,
) -> tuple[str, str] | None:
    canonical = _pending_cleanup_retained_canonical_name(name)
    if canonical is None:
        return None
    batch_name = _pending_cleanup_ticket_temp_batch_name(canonical)
    if batch_name is None:
        return None
    return canonical, batch_name


def _pending_cleanup_cursor_temp_canonical_name(name: str) -> str | None:
    if name == PENDING_CLEANUP_CURSOR_TEMP_NAME:
        return name
    canonical = _pending_cleanup_retained_canonical_name(name)
    if canonical == PENDING_CLEANUP_CURSOR_TEMP_NAME:
        return canonical
    return None


def _pending_cleanup_retained_control_name(
    name: str,
) -> tuple[str, str] | None:
    canonical = _pending_cleanup_retained_canonical_name(name)
    if canonical is None:
        return None
    for suffix in (
        PENDING_QUARANTINE_ALLOCATION_SUFFIX,
        PENDING_CLEANUP_TICKET_SUFFIX,
        PENDING_CLEANUP_EMPTY_PROOF_SUFFIX,
        PENDING_CLEANUP_TERMINAL_VALIDATION_SUFFIX,
        PENDING_PRIVATE_USE_RETIREMENT_SUFFIX,
    ):
        if not canonical.endswith(suffix):
            continue
        batch_name = canonical[: -len(suffix)]
        if (
            len(batch_name) <= MAX_PENDING_LINK_BATCH_NAME_BYTES
            and PENDING_LINK_BATCH_RE.fullmatch(batch_name) is not None
        ):
            return canonical, batch_name
    return None


def _pending_cleanup_unresolved_ticket_representation(
    name: str,
) -> tuple[str, str] | None:
    """Return only ticket-derived residue that cannot enter auto-recovery.

    The broad representation classifier deliberately recognizes suffix-added
    descendants, because their bytes can be the only surviving ticket evidence.
    Exact canonical tickets, their exact temporary form, and strict retained
    forms remain eligible for the existing bound recovery protocol.  Every
    other related name is a blocking ambiguity, never recovery authority.
    """
    batch_name = _pending_cleanup_ticket_representation_batch_name(name)
    if batch_name is None:
        return None
    canonical_ticket_name = batch_name + PENDING_CLEANUP_TICKET_SUFFIX
    if name in {
        canonical_ticket_name,
        batch_name + PENDING_CLEANUP_TICKET_TEMP_SUFFIX,
    }:
        return None
    retained_control = _pending_cleanup_retained_control_name(name)
    if (
        retained_control is not None
        and retained_control[1] == batch_name
        and retained_control[0] == canonical_ticket_name
    ):
        return None
    retained_temp = _pending_cleanup_retained_ticket_temp_name(name)
    if retained_temp is not None and retained_temp[1] == batch_name:
        return None
    return batch_name, name


def _pending_cleanup_unresolved_ticket_representation_issue(
    home: Path,
) -> tuple[str, str] | None:
    """Observe blocking ticket residue without granting it any authority."""
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return None
    try:
        if not _bound_directory_matches(home, index_root, index_fd):
            raise SyncError("pending cleanup index changed")
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="pending cleanup authority scan exceeds the size limit",
        )
        for name in names:
            unresolved = _pending_cleanup_unresolved_ticket_representation(name)
            if unresolved is not None:
                return unresolved
        return None
    finally:
        _close_fd_quietly(index_fd)


def _pending_cleanup_unresolved_ticket_representation_error(
    unresolved: tuple[str, str],
) -> SyncError:
    batch_name, name = unresolved
    return SyncError(
        "pending cleanup ticket representation must be reconciled before new "
        f"mutation: {batch_name}: {name}"
    )


def _require_no_pending_unresolved_ticket_representations(home: Path) -> None:
    unresolved = _pending_cleanup_unresolved_ticket_representation_issue(home)
    if unresolved is not None:
        raise _pending_cleanup_unresolved_ticket_representation_error(unresolved)
    allocation_unresolved = (
        _pending_quarantine_unresolved_allocation_representation_issue(home)
    )
    if allocation_unresolved is not None:
        raise _pending_quarantine_unresolved_allocation_representation_error(
            allocation_unresolved
        )
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return
    try:
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="private-use retirement scan exceeds the size limit",
        )
        for name in names:
            unresolved_receipt = (
                _pending_private_use_retirement_unresolved_representation(name)
            )
            if unresolved_receipt is not None:
                batch_name, representation = unresolved_receipt
                raise SyncError(
                    "private-use retirement receipt representation must be "
                    f"reconciled before new mutation: {batch_name}: {representation}"
                )
    finally:
        _close_fd_quietly(index_fd)


def _restore_pending_cleanup_control_tombstones(
    home: Path,
    *,
    limit: int = MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
    budget: PendingCleanupActionBudget | None = None,
) -> int:
    if limit < 0:
        raise SyncError("pending cleanup control action budget is invalid")
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return 0
    restored = 0
    try:
        if not _bound_directory_matches(home, index_root, index_fd):
            raise SyncError("pending cleanup index changed")
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="pending cleanup control scan exceeds the size limit",
        )
        retained_by_canonical: dict[str, list[str]] = {}
        for name in names:
            parsed = _pending_cleanup_retained_control_name(name)
            if parsed is None:
                continue
            canonical, _batch_name = parsed
            retained_by_canonical.setdefault(canonical, []).append(name)
        ordered = sorted(
            retained_by_canonical,
            key=lambda name: (
                not name.endswith(PENDING_CLEANUP_TICKET_SUFFIX),
                name,
            ),
        )
        for canonical in ordered:
            retained_names = retained_by_canonical[canonical]
            if len(retained_names) != 1:
                raise SyncError(
                    f"pending cleanup control has multiple retained files: {canonical}"
                )
            canonical_path = index_root / canonical
            canonical_snapshot = _read_managed_state_file_snapshot(
                home,
                canonical_path,
                index_fd,
            )
            if canonical_snapshot.exists:
                raise SyncError(
                    f"pending cleanup control overlaps retained evidence: {canonical}"
                )
        action_budget = budget or PendingCleanupActionBudget(limit)
        for canonical in ordered:
            retained_names = retained_by_canonical[canonical]
            parsed = _pending_cleanup_retained_control_name(retained_names[0])
            assert parsed is not None
            _parsed_canonical, batch_name = parsed
            if not action_budget.charge_batch(batch_name):
                continue
            canonical_path = index_root / canonical
            retained_path = index_root / retained_names[0]
            retained_snapshot = _read_managed_state_file_snapshot(
                home,
                retained_path,
                index_fd,
            )
            if not retained_snapshot.exists:
                raise SyncError(
                    f"pending cleanup retained control disappeared: {canonical}"
                )
            if retained_snapshot.uid != os.geteuid():
                raise SyncError(
                    f"pending cleanup retained control owner changed: {canonical}"
                )
            _require_pending_cleanup_file_snapshot_access_policy(
                home,
                retained_path,
                index_fd,
                retained_snapshot,
            )
            retirement = _read_current_private_use_retirement_authority(
                home, batch_name
            )
            if retirement is not None:
                _require_pending_private_use_retirement_boundary(
                    home,
                    retirement,
                    receipt_member=retirement.path.name,
                )
            recovered = _restore_retained_pending_cleanup_file(
                home,
                canonical_path,
                index_fd,
                retained_snapshot,
                label=f"pending cleanup control {canonical}",
            )
            if recovered is None:
                raise SyncError(
                    f"pending cleanup retained control disappeared: {canonical}"
                )
            retirement = _read_current_private_use_retirement_authority(
                home, batch_name
            )
            if retirement is not None:
                _require_pending_private_use_retirement_boundary(
                    home,
                    retirement,
                    receipt_member=retirement.path.name,
                )
            if canonical.endswith(PENDING_QUARANTINE_ALLOCATION_SUFFIX):
                allocation = _read_pending_quarantine_allocation_ticket(
                    home,
                    canonical_path,
                    expected_identity=recovered.file_identity,
                )
                if allocation is None:
                    raise SyncError(
                        f"pending quarantine allocation recovery failed: {canonical}"
                    )
            elif canonical.endswith(PENDING_CLEANUP_TICKET_SUFFIX):
                ticket = _read_pending_cleanup_ticket(
                    home,
                    canonical_path,
                    expected_ticket_identity=recovered.file_identity,
                )
                if ticket is None:
                    raise SyncError(
                        f"pending cleanup ticket recovery failed: {canonical}"
                    )
            elif canonical.endswith(PENDING_PRIVATE_USE_RETIREMENT_SUFFIX):
                receipt = _read_pending_private_use_retirement_receipt(
                    home,
                    canonical_path,
                    expected_identity=recovered.file_identity,
                )
                if receipt is None:
                    raise SyncError(
                        f"private-use retirement recovery failed: {canonical}"
                    )
            restored += 1
        if not _bound_directory_matches(home, index_root, index_fd):
            raise SyncError("pending cleanup index changed")
    finally:
        _close_fd_quietly(index_fd)
    return restored


def _promote_pending_ephemeral_cleanup_ticket_temp(
    home: Path,
    temp_path: Path,
    *,
    classified_snapshot: ManagedStateFileSnapshot | None = None,
) -> bool:
    """Promote a canonical v5/v6/v7 ticket temp instead of discarding authority."""
    batch_name = _pending_cleanup_ticket_temp_batch_name(temp_path.name)
    if batch_name is None:
        return False
    index_fd = _open_directory_beneath(home, temp_path.parent)
    try:
        staged = (
            classified_snapshot
            if classified_snapshot is not None
            else _read_managed_state_file_snapshot(
                home,
                temp_path,
                index_fd,
                maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
            )
        )
        if not staged.exists:
            return False
        if (
            not _managed_state_snapshot_has_complete_file_evidence(staged)
            or staged.file_type != stat.S_IFREG
            or staged.payload is None
        ):
            raise SyncError(
                "pending cleanup ticket temp could not be safely classified: "
                f"{batch_name}"
            )
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            temp_path,
            index_fd,
            staged,
        )
        try:
            staged_ticket = _read_pending_cleanup_ticket(
                home,
                temp_path,
                expected_ticket_identity=staged.file_identity,
                allow_temporary=True,
                _captured_snapshot=staged,
            )
        except SyncError:
            # Only the pure parser runs inside this catch.  A rejection proves
            # the already captured bytes are noncanonical residue.  Capture,
            # identity/content revalidation and policy failures occur outside
            # it and must propagate so recovery retains durable authority.
            return False
        if (
            staged_ticket is None
            or staged_ticket.version not in {5, 6, 7}
            or not _managed_state_snapshot_matches_bound_file_evidence(
                staged_ticket.snapshot,
                staged,
            )
        ):
            return False
        ticket_path = _pending_cleanup_ticket_path(home, batch_name)
        existing = _read_managed_state_file_snapshot(
            home,
            ticket_path,
            index_fd,
        )
        if existing.exists:
            ticket = _read_pending_cleanup_ticket(
                home,
                ticket_path,
                expected_ticket_identity=existing.file_identity,
            )
            if (
                ticket is None
                or not _managed_state_snapshot_matches_bound_file_evidence(
                    ticket.snapshot,
                    existing,
                )
                or ticket.snapshot.payload != staged.payload
            ):
                raise SyncError(
                    f"pending cleanup ticket temp conflicts with its canonical "
                    f"ticket: {batch_name}"
                )

            def require_canonical_unchanged(_temp_member: str) -> None:
                _require_pending_cleanup_file_snapshot_unchanged(
                    home,
                    ticket_path,
                    index_fd,
                    existing,
                    label=f"pending cleanup canonical ticket {batch_name}",
                    maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
                )

            _isolate_and_delete_pending_cleanup_file(
                home,
                temp_path,
                index_fd,
                staged,
                label=f"published pending cleanup ticket temp {batch_name}",
                mutation_revalidator=require_canonical_unchanged,
            )
            return True
        current = _read_managed_state_file_snapshot(
            home,
            temp_path,
            index_fd,
            expected_identity=staged.file_identity,
            maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(current, staged):
            raise SyncError(
                f"pending cleanup ticket temp changed before promotion: {batch_name}"
            )
        _rename_noreplace_at(
            index_fd,
            temp_path.name,
            index_fd,
            ticket_path.name,
        )
        os.fsync(index_fd)
        ticket = _read_pending_cleanup_ticket(
            home,
            ticket_path,
            expected_ticket_identity=staged.file_identity,
        )
        if ticket is None or ticket.snapshot.payload != staged.payload:
            raise SyncError(
                f"pending cleanup ticket changed after temp promotion: {batch_name}"
            )
        _verify_pending_cleanup_ticket_durable(home, ticket)
        return True
    finally:
        _close_fd_quietly(index_fd)


def _promote_pending_quarantine_allocation_temp(
    home: Path,
    temp_path: Path,
    *,
    classified_snapshot: ManagedStateFileSnapshot | None = None,
) -> bool:
    """Promote only a complete v8 reservation while its batch is absent."""
    batch_name = _pending_quarantine_allocation_temp_batch_name(temp_path.name)
    if batch_name is None:
        return False
    index_fd = _open_directory_beneath(home, temp_path.parent)
    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    quarantine_fd = -1
    try:
        staged = (
            classified_snapshot
            if classified_snapshot is not None
            else _read_managed_state_file_snapshot(
                home,
                temp_path,
                index_fd,
                maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
            )
        )
        if (
            not _managed_state_snapshot_has_complete_file_evidence(staged)
            or staged.file_type != stat.S_IFREG
            or staged.payload is None
        ):
            raise SyncError(
                "pending quarantine allocation temp could not be safely "
                f"classified: {batch_name}"
            )
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            temp_path,
            index_fd,
            staged,
        )
        try:
            data = _decode_managed_state_json(staged.payload, temp_path)
            metadata = data.get("metadata")
            root_identity = _parse_pending_identity(
                data.get("quarantine_root_identity"),
                "pending quarantine allocation root identity",
            )
            metadata_sha256 = (
                metadata.get("sha256") if isinstance(metadata, dict) else None
            )
            metadata_size = metadata.get("size") if isinstance(metadata, dict) else None
            expected = (
                _pending_quarantine_allocation_payload_from_plan(
                    batch_name,
                    root_identity,
                    metadata_sha256,
                    metadata_size,
                )
                if root_identity is not None
                and isinstance(metadata_sha256, str)
                and re.fullmatch(r"[0-9a-f]{64}", metadata_sha256) is not None
                and type(metadata_size) is int
                and 0 <= metadata_size <= MAX_MANAGED_STATE_BYTES
                else None
            )
        except SyncError:
            return False
        if staged.payload != expected:
            return False
        path = _pending_quarantine_allocation_path(home, batch_name)
        existing = _read_managed_state_file_snapshot(home, path, index_fd)
        if existing.exists:
            allocation = _read_pending_quarantine_allocation_ticket(
                home,
                path,
                expected_identity=existing.file_identity,
            )
            if (
                allocation is None
                or not _managed_state_snapshot_matches_bound_file_evidence(
                    allocation.snapshot,
                    existing,
                )
                or allocation.snapshot.payload != staged.payload
            ):
                raise SyncError(
                    "pending quarantine allocation temp conflicts with canonical "
                    f"ticket: {batch_name}"
                )

            def require_canonical_unchanged(_temp_member: str) -> None:
                _require_pending_cleanup_file_snapshot_unchanged(
                    home,
                    path,
                    index_fd,
                    existing,
                    label=f"pending quarantine allocation {batch_name}",
                    maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
                )

            _isolate_and_delete_pending_cleanup_file(
                home,
                temp_path,
                index_fd,
                staged,
                label=f"published pending quarantine allocation temp {batch_name}",
                mutation_revalidator=require_canonical_unchanged,
            )
            return True
        quarantine_fd = _open_directory_beneath(home, quarantine_root)
        _require_quarantine_allocation_root_absent(
            home,
            quarantine_root,
            quarantine_fd,
            batch_name,
            root_identity,
        )
        current = _read_managed_state_file_snapshot(
            home,
            temp_path,
            index_fd,
            expected_identity=staged.file_identity,
            maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(current, staged):
            raise SyncError(f"pending quarantine allocation temp changed: {batch_name}")
        _rename_noreplace_at(index_fd, temp_path.name, index_fd, path.name)
        os.fsync(index_fd)
        index_parent_fd = _open_directory_beneath(home, path.parent.parent)
        try:
            os.fsync(index_parent_fd)
        finally:
            _close_fd_quietly(index_parent_fd)
        allocation = _read_pending_quarantine_allocation_ticket(
            home,
            path,
            expected_identity=staged.file_identity,
        )
        if allocation is None or allocation.snapshot.payload != staged.payload:
            raise SyncError(
                f"pending quarantine allocation changed after promotion: {batch_name}"
            )
        _require_quarantine_allocation_root_absent(
            home,
            quarantine_root,
            quarantine_fd,
            batch_name,
            root_identity,
        )
        return True
    finally:
        _close_fd_quietly(quarantine_fd)
        _close_fd_quietly(index_fd)


def _promote_pending_private_use_retirement_temp(
    home: Path,
    temp_path: Path,
    *,
    classified_snapshot: ManagedStateFileSnapshot | None = None,
) -> bool:
    batch_name = _pending_private_use_retirement_temp_batch_name(temp_path.name)
    if batch_name is None:
        return False
    index_fd = _open_directory_beneath(home, temp_path.parent)
    try:
        staged = (
            classified_snapshot
            if classified_snapshot is not None
            else _read_managed_state_file_snapshot(
                home,
                temp_path,
                index_fd,
                maximum_bytes=MAX_PENDING_TERMINAL_CLEANUP_TICKET_BYTES,
            )
        )
        if not staged.exists:
            return False
        _require_pending_cleanup_file_snapshot_access_policy(
            home, temp_path, index_fd, staged
        )
        receipt = _read_pending_private_use_retirement_receipt(
            home,
            temp_path,
            expected_identity=staged.file_identity,
            allow_temporary=True,
            _captured_snapshot=staged,
        )
        if receipt is None:
            return False
        _require_pending_private_use_retirement_boundary(
            home, receipt, receipt_member=temp_path.name
        )
        canonical_path = _pending_private_use_retirement_path(home, batch_name)
        canonical = _read_managed_state_file_snapshot(home, canonical_path, index_fd)
        if canonical.exists:
            raise SyncError(
                f"private-use retirement temp overlaps canonical receipt: {batch_name}"
            )
        current = _read_managed_state_file_snapshot(
            home,
            temp_path,
            index_fd,
            expected_identity=staged.file_identity,
            maximum_bytes=MAX_PENDING_TERMINAL_CLEANUP_TICKET_BYTES,
        )
        if not _managed_state_snapshot_matches_bound_file_evidence(current, staged):
            raise SyncError(
                f"private-use retirement temp changed before promotion: {batch_name}"
            )
        _require_pending_private_use_retirement_boundary(
            home, receipt, receipt_member=temp_path.name
        )
        _rename_noreplace_at(index_fd, temp_path.name, index_fd, canonical_path.name)
        os.fsync(index_fd)
        promoted = _read_pending_private_use_retirement_receipt(
            home,
            canonical_path,
            expected_identity=staged.file_identity,
        )
        if promoted is None or promoted.snapshot.payload != staged.payload:
            raise SyncError(
                f"private-use retirement receipt changed after promotion: {batch_name}"
            )
        _require_pending_private_use_retirement_boundary(
            home, promoted, receipt_member=canonical_path.name
        )
        return True
    finally:
        _close_fd_quietly(index_fd)


def _cleanup_pending_cleanup_ticket_temps(
    home: Path,
    *,
    limit: int = MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
    budget: PendingCleanupActionBudget | None = None,
) -> int:
    if limit < 0:
        raise SyncError("pending cleanup temp action budget is invalid")
    if limit == 0 and budget is None:
        return 0
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return 0
    temp_names: set[str] = set()
    try:
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="pending cleanup control scan exceeds the size limit",
        )
        for name in names:
            if _pending_private_use_retirement_temp_batch_name(name) is not None:
                temp_names.add(name)
                continue
            if _pending_cleanup_ticket_temp_batch_name(name) is not None:
                temp_names.add(name)
                continue
            if _pending_quarantine_allocation_temp_batch_name(name) is not None:
                temp_names.add(name)
                continue
            if _pending_quarantine_metadata_stage_batch_name(name) is not None:
                temp_names.add(name)
                continue
            retained = _pending_cleanup_retained_ticket_temp_name(name)
            if retained is not None:
                temp_names.add(retained[0])
                continue
            retained_allocation = _pending_quarantine_retained_allocation_temp_name(
                name
            )
            if retained_allocation is not None:
                temp_names.add(retained_allocation[0])
                continue
            retained_metadata_stage = _pending_quarantine_retained_metadata_stage_name(
                name
            )
            if retained_metadata_stage is not None:
                temp_names.add(retained_metadata_stage[0])
                continue
            retained_canonical = _pending_cleanup_retained_canonical_name(name)
            if (
                retained_canonical is not None
                and _pending_private_use_retirement_temp_batch_name(retained_canonical)
                is not None
            ):
                temp_names.add(retained_canonical)
    finally:
        _close_fd_quietly(index_fd)
    action_budget = budget or PendingCleanupActionBudget(limit)
    discarded = 0
    for temp_name in sorted(temp_names):
        batch_name = _pending_cleanup_ticket_temp_batch_name(temp_name)
        allocation_batch_name = _pending_quarantine_allocation_temp_batch_name(
            temp_name
        )
        metadata_stage_batch_name = _pending_quarantine_metadata_stage_batch_name(
            temp_name
        )
        retirement_batch_name = _pending_private_use_retirement_temp_batch_name(
            temp_name
        )
        if batch_name is None:
            batch_name = allocation_batch_name
        if batch_name is None:
            batch_name = metadata_stage_batch_name
        if batch_name is None:
            batch_name = retirement_batch_name
        assert batch_name is not None
        if not action_budget.charge_batch(batch_name):
            continue
        temp_path = index_root / temp_name
        index_fd = _open_directory_beneath(home, index_root)
        try:
            current = _read_managed_state_file_snapshot(
                home,
                temp_path,
                index_fd,
            )
            retained = _retained_pending_cleanup_file(
                home,
                temp_path,
                index_fd,
                expected=None,
                label=f"pending cleanup ticket temp {batch_name}",
            )
            if retained is not None:
                if current.exists:
                    raise SyncError(
                        "pending cleanup ticket temp overlaps retained evidence: "
                        f"{batch_name}"
                    )
                retained_name, retained_snapshot = retained
                if retirement_batch_name is not None:
                    retained_receipt = _read_pending_private_use_retirement_receipt(
                        home,
                        temp_path,
                        expected_identity=retained_snapshot.file_identity,
                        allow_temporary=True,
                        _captured_snapshot=retained_snapshot,
                    )
                    if retained_receipt is None:
                        raise SyncError(
                            "private-use retirement retained temp disappeared: "
                            f"{batch_name}"
                        )
                    retained_receipt = replace(
                        retained_receipt,
                        path=temp_path.with_name(retained_name),
                    )
                    _require_pending_private_use_retirement_boundary(
                        home,
                        retained_receipt,
                        receipt_member=retained_name,
                    )
                _restore_exact_retained_pending_cleanup_file(
                    home,
                    temp_path,
                    index_fd,
                    retained_name,
                    retained_snapshot,
                    label=f"pending cleanup ticket temp {batch_name}",
                )
                if retirement_batch_name is not None:
                    restored_receipt = _read_pending_private_use_retirement_receipt(
                        home,
                        temp_path,
                        expected_identity=retained_snapshot.file_identity,
                        allow_temporary=True,
                    )
                    if restored_receipt is None:
                        raise SyncError(
                            "private-use retirement temp restoration failed: "
                            f"{batch_name}"
                        )
                    _require_pending_private_use_retirement_boundary(
                        home,
                        restored_receipt,
                        receipt_member=temp_path.name,
                    )
            classified = _read_managed_state_file_snapshot(
                home,
                temp_path,
                index_fd,
                maximum_bytes=(
                    MAX_MANAGED_STATE_BYTES
                    if metadata_stage_batch_name is not None
                    else (
                        MAX_PENDING_TERMINAL_CLEANUP_TICKET_BYTES
                        if retirement_batch_name is not None
                        else MAX_PENDING_CLEANUP_TICKET_BYTES
                    )
                ),
            )
            if not classified.exists:
                raise SyncError(
                    "pending cleanup ticket temp disappeared before "
                    f"classification: {batch_name}"
                )
        finally:
            _close_fd_quietly(index_fd)
        if metadata_stage_batch_name is not None:
            discarded_for_batch = _discard_incomplete_pending_cleanup_ticket(
                home,
                temp_path,
                max_actions=MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
                expected_snapshot=classified,
            )
            discarded += discarded_for_batch
            if discarded_for_batch > 0:
                action_budget.mark_batch_completed(batch_name)
            continue
        if retirement_batch_name is not None:
            if not _promote_pending_private_use_retirement_temp(
                home,
                temp_path,
                classified_snapshot=classified,
            ):
                raise SyncError(
                    "private-use retirement temp could not be safely classified: "
                    f"{batch_name}"
                )
            continue
        if _promote_pending_ephemeral_cleanup_ticket_temp(
            home,
            temp_path,
            classified_snapshot=classified,
        ):
            continue
        if _promote_pending_quarantine_allocation_temp(
            home,
            temp_path,
            classified_snapshot=classified,
        ):
            continue
        discarded_for_batch = _discard_incomplete_pending_cleanup_ticket(
            home,
            temp_path,
            max_actions=MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
            expected_snapshot=classified,
        )
        discarded += discarded_for_batch
        if discarded_for_batch > 0:
            action_budget.mark_batch_completed(batch_name)
    return discarded


def _read_orphan_pending_cleanup_empty_proof(
    home: Path,
    proof_path: Path,
) -> ManagedStateFileSnapshot:
    suffix = PENDING_CLEANUP_EMPTY_PROOF_SUFFIX
    if not proof_path.name.endswith(suffix):
        raise SyncError("pending cleanup empty proof has an invalid file name")
    batch_name = proof_path.name[: -len(suffix)]
    if (
        len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
    ):
        raise SyncError("pending cleanup empty proof has an invalid batch name")
    index_fd = _open_directory_beneath(home, proof_path.parent)
    try:
        proof = _read_managed_state_file_snapshot(
            home,
            proof_path,
            index_fd,
        )
        if (
            not proof.exists
            or proof.payload is None
            or proof.mode != 0o600
            or proof.uid != os.geteuid()
        ):
            raise SyncError(f"pending cleanup empty proof changed: {batch_name}")
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            proof_path,
            index_fd,
            proof,
        )
    finally:
        _close_fd_quietly(index_fd)
    data = _decode_managed_state_json(proof.payload, proof_path)
    if (
        set(data)
        != {
            "version",
            "batch",
            "batch_root_identity",
            "quarantine_root_identity",
            "isolated_name",
            "ticket_identity",
            "ticket_sha256",
        }
        or data.get("version") != 1
    ):
        raise SyncError(f"pending cleanup empty proof changed: {batch_name}")
    batch_identity = _parse_pending_identity(
        data.get("batch_root_identity"),
        "pending cleanup empty-proof batch identity",
    )
    quarantine_identity = _parse_pending_identity(
        data.get("quarantine_root_identity"),
        "pending cleanup empty-proof quarantine identity",
    )
    ticket_identity = _parse_pending_identity(
        data.get("ticket_identity"),
        "pending cleanup empty-proof ticket identity",
    )
    ticket_sha256 = data.get("ticket_sha256")
    isolated_name = _pending_cleanup_isolated_batch_name(batch_name)
    if (
        data.get("batch") != batch_name
        or batch_identity is None
        or quarantine_identity is None
        or ticket_identity is None
        or data.get("isolated_name") != isolated_name
        or not isinstance(ticket_sha256, str)
        or re.fullmatch(r"[0-9a-f]{64}", ticket_sha256) is None
    ):
        raise SyncError(f"pending cleanup empty proof changed: {batch_name}")
    expected_payload = _bounded_json_document(
        {
            "version": 1,
            "batch": batch_name,
            "batch_root_identity": _identity_payload(batch_identity),
            "quarantine_root_identity": _identity_payload(quarantine_identity),
            "isolated_name": isolated_name,
            "ticket_identity": _identity_payload(ticket_identity),
            "ticket_sha256": ticket_sha256,
        },
        max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        overflow_error="pending cleanup empty proof exceeds the size limit",
    )
    if proof.payload != expected_payload:
        raise SyncError(f"pending cleanup empty proof changed: {batch_name}")
    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    quarantine_fd = _open_directory_beneath(home, quarantine_root)
    try:
        if _directory_identity(
            quarantine_fd
        ) != quarantine_identity or not _bound_directory_matches(
            home, quarantine_root, quarantine_fd
        ):
            raise SyncError("pending cleanup quarantine root changed")
        if (
            _named_entry_identity(quarantine_fd, batch_name) is not None
            or _named_entry_identity(quarantine_fd, isolated_name) is not None
        ):
            raise SyncError(
                f"pending cleanup empty proof still has a batch root: {batch_name}"
            )
    finally:
        _close_fd_quietly(quarantine_fd)
    return proof


def _cleanup_orphan_pending_cleanup_empty_proofs(
    home: Path,
    *,
    limit: int = MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
    budget: PendingCleanupActionBudget | None = None,
) -> int:
    if limit < 0:
        raise SyncError("pending cleanup proof action budget is invalid")
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return 0
    proof_names: list[str] = []
    try:
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="pending cleanup control scan exceeds the size limit",
        )
        name_inventory = frozenset(names)
        for name in names:
            if not name.endswith(PENDING_CLEANUP_EMPTY_PROOF_SUFFIX):
                continue
            batch_name = name[: -len(PENDING_CLEANUP_EMPTY_PROOF_SUFFIX)]
            if (
                len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
                or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
            ):
                continue
            ticket_name = batch_name + PENDING_CLEANUP_TICKET_SUFFIX
            if ticket_name not in name_inventory:
                proof_names.append(name)
    finally:
        _close_fd_quietly(index_fd)
    action_budget = budget or PendingCleanupActionBudget(limit)
    cleaned = 0
    for proof_name in sorted(proof_names):
        batch_name = proof_name[: -len(PENDING_CLEANUP_EMPTY_PROOF_SUFFIX)]
        if not action_budget.charge_batch(batch_name):
            continue
        try:
            ticket = _read_pending_cleanup_ticket(
                home,
                _pending_cleanup_ticket_path(home, batch_name),
            )
        except (FileNotFoundError, OSError, SyncError) as error:
            raise _pending_cleanup_authority_classification_error(
                batch_name,
                error,
            ) from error
        if ticket is not None:
            continue
        proof_path = index_root / proof_name
        proof = _read_orphan_pending_cleanup_empty_proof(home, proof_path)
        index_fd = _open_directory_beneath(home, index_root)
        try:

            def revalidate_ticket_representations(_proof_member: str) -> None:
                # A recovered canonical, retained, or suffix-added ticket can
                # make this proof the only durable empty-batch evidence. Keep
                # the proof unless every representation remains absent at both
                # irreversible deletion boundaries on this exact index FD.
                _require_pending_ephemeral_ticket_representations_absent(
                    home,
                    index_root,
                    index_fd,
                    batch_name,
                )

            revalidate_ticket_representations(proof_path.name)
            _isolate_and_delete_pending_cleanup_file(
                home,
                proof_path,
                index_fd,
                proof,
                label=f"orphan pending cleanup empty proof {batch_name}",
                mutation_revalidator=revalidate_ticket_representations,
            )
        finally:
            _close_fd_quietly(index_fd)
        cleaned += 1
        action_budget.mark_batch_completed(batch_name)
    return cleaned


def _read_orphan_pending_ephemeral_private_phase(
    home: Path,
    receipt_path: Path,
) -> tuple[
    ManagedStateFileSnapshot,
    str,
    PurePosixPath,
    tuple[int, int],
    tuple[int, int],
    tuple[int, int],
]:
    suffix = PENDING_CLEANUP_TERMINAL_VALIDATION_SUFFIX
    if not receipt_path.name.endswith(suffix):
        raise SyncError("pending cleanup private phase has an invalid file name")
    batch_name = receipt_path.name[: -len(suffix)]
    if (
        len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
    ):
        raise SyncError("pending cleanup private phase has an invalid batch name")
    index_fd = _open_directory_beneath(home, receipt_path.parent)
    try:
        receipt = _read_managed_state_file_snapshot(
            home,
            receipt_path,
            index_fd,
            maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        )
        if (
            not _managed_state_snapshot_has_complete_file_evidence(receipt)
            or receipt.file_type != stat.S_IFREG
            or receipt.mode != 0o600
            or receipt.uid != os.geteuid()
            or receipt.payload is None
            or receipt.parent_identity != _directory_identity(index_fd)
        ):
            raise SyncError(
                f"orphan pending cleanup private phase changed: {batch_name}"
            )
        _require_pending_cleanup_file_snapshot_access_policy(
            home,
            receipt_path,
            index_fd,
            receipt,
        )
    finally:
        _close_fd_quietly(index_fd)
    data = _decode_managed_state_json(receipt.payload, receipt_path)
    expected_fields = {
        "version",
        "phase",
        "batch",
        "quarantine_root_identity",
        "public_target",
        "public_parent_identity",
        "payload_file_identity",
        "ticket_identity",
        "ticket_sha256",
    }
    quarantine_identity = _parse_pending_identity(
        data.get("quarantine_root_identity"),
        "orphan pending cleanup quarantine root identity",
    )
    public_target = _validate_relative_path(
        data.get("public_target"),
        "orphan pending ephemeral cleanup target",
    )
    public_parent_identity = _parse_pending_identity(
        data.get("public_parent_identity"),
        "orphan pending cleanup public parent identity",
    )
    payload_identity = _parse_pending_identity(
        data.get("payload_file_identity"),
        "orphan pending cleanup payload identity",
    )
    ticket_identity = _parse_pending_identity(
        data.get("ticket_identity"),
        "orphan pending cleanup ticket identity",
    )
    ticket_sha256 = data.get("ticket_sha256")
    if (
        set(data) != expected_fields
        or data.get("version") != 1
        or data.get("phase") != "ephemeral-private-isolated"
        or data.get("batch") != batch_name
        or quarantine_identity is None
        or public_parent_identity is None
        or payload_identity is None
        or ticket_identity is None
        or not isinstance(ticket_sha256, str)
        or re.fullmatch(r"[0-9a-f]{64}", ticket_sha256) is None
    ):
        raise SyncError(f"orphan pending cleanup private phase changed: {batch_name}")
    expected_payload = _bounded_json_document(
        {
            "version": 1,
            "phase": "ephemeral-private-isolated",
            "batch": batch_name,
            "quarantine_root_identity": _identity_payload(quarantine_identity),
            "public_target": public_target.as_posix(),
            "public_parent_identity": _identity_payload(public_parent_identity),
            "payload_file_identity": _identity_payload(payload_identity),
            "ticket_identity": _identity_payload(ticket_identity),
            "ticket_sha256": ticket_sha256,
        },
        max_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        overflow_error="pending cleanup validation receipt exceeds the size limit",
    )
    if receipt.payload != expected_payload:
        raise SyncError(f"orphan pending cleanup private phase changed: {batch_name}")
    return (
        receipt,
        batch_name,
        public_target,
        public_parent_identity,
        quarantine_identity,
        payload_identity,
    )


def _cleanup_orphan_pending_ephemeral_private_phases(
    home: Path,
    *,
    limit: int = MAX_PENDING_CLEANUP_BATCHES_PER_RUN,
    budget: PendingCleanupActionBudget | None = None,
) -> int:
    """Remove only a terminal v6 phase whose bound names remain empty.

    The receipt protects the ticket/payload object identities and ticket
    content hash. Recovery additionally revalidates the bound public-parent and
    quarantine-root identities plus their access policy, then requires every
    ticket-derived public and private name to be absent. Directory timestamps
    and link counts are deliberately not compared because ordinary child-entry
    churn changes them without replacing either protected directory object.
    """
    if limit < 0:
        raise SyncError("pending cleanup private-phase action budget is invalid")
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return 0
    receipt_names: list[str] = []
    try:
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="pending cleanup control scan exceeds the size limit",
        )
        name_inventory = frozenset(names)
        suffix = PENDING_CLEANUP_TERMINAL_VALIDATION_SUFFIX
        for name in names:
            if not name.endswith(suffix):
                continue
            batch_name = name[: -len(suffix)]
            if (
                len(batch_name) <= MAX_PENDING_LINK_BATCH_NAME_BYTES
                and PENDING_LINK_BATCH_RE.fullmatch(batch_name) is not None
                and batch_name + PENDING_CLEANUP_TICKET_SUFFIX not in name_inventory
            ):
                receipt_names.append(name)
    finally:
        _close_fd_quietly(index_fd)

    action_budget = budget or PendingCleanupActionBudget(limit)
    cleaned = 0
    for receipt_name in sorted(receipt_names):
        batch_name = receipt_name[: -len(PENDING_CLEANUP_TERMINAL_VALIDATION_SUFFIX)]
        if not action_budget.charge_batch(batch_name):
            continue
        receipt_path = index_root / receipt_name
        try:
            (
                receipt,
                _parsed_batch_name,
                public_target,
                public_parent_identity,
                quarantine_identity,
                _payload_identity,
            ) = _read_orphan_pending_ephemeral_private_phase(home, receipt_path)
            target = home / Path(*public_target.parts)
            quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
            public_parent_fd = -1
            quarantine_fd = -1
            index_fd = -1
            try:
                public_parent_fd = _open_directory_beneath(home, target.parent)
                quarantine_fd = _open_directory_beneath(home, quarantine_root)
                index_fd = _open_directory_beneath(home, index_root)

                def require_orphan_receipt_boundary(_receipt_member: str) -> None:
                    _require_pending_ephemeral_terminal_names_absent(
                        home,
                        target,
                        public_parent_fd,
                        public_parent_identity,
                        quarantine_root,
                        quarantine_fd,
                        quarantine_identity,
                        batch_name,
                    )
                    _require_pending_ephemeral_ticket_representations_absent(
                        home,
                        index_root,
                        index_fd,
                        batch_name,
                    )

                require_orphan_receipt_boundary(receipt_path.name)
                _isolate_and_delete_pending_cleanup_file(
                    home,
                    receipt_path,
                    index_fd,
                    receipt,
                    label=f"orphan pending cleanup private phase {batch_name}",
                    mutation_revalidator=require_orphan_receipt_boundary,
                )
            finally:
                _close_fd_quietly(index_fd)
                _close_fd_quietly(public_parent_fd)
                _close_fd_quietly(quarantine_fd)
        except (FileNotFoundError, OSError, SyncError) as error:
            raise _pending_cleanup_authority_classification_error(
                batch_name,
                error,
            ) from error
        cleaned += 1
        action_budget.mark_batch_completed(batch_name)
    return cleaned


def _read_recoverable_joined_cleanup_representation(
    home: Path,
    allocation: PendingQuarantineAllocationTicket,
) -> PendingBatchCleanupTicket | None:
    """Strictly parse a v5/v7 temp or retained ticket before v8 classification."""
    batch_name = allocation.batch_root.name
    index_root = _pending_cleanup_index_path(home)
    index_fd = _open_directory_beneath(home, index_root)
    try:
        _require_pending_cleanup_fd_access_policy(
            index_fd, index_root, expected_mode=0o700
        )
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="pending cleanup authority scan exceeds the size limit",
        )
        candidates: list[str] = []
        canonical_name = batch_name + PENDING_CLEANUP_TICKET_SUFFIX
        temp_name = batch_name + PENDING_CLEANUP_TICKET_TEMP_SUFFIX
        for name in names:
            retained = _pending_cleanup_retained_canonical_name(name)
            represented = retained or name
            if represented in {canonical_name, temp_name}:
                candidates.append(name)
        if canonical_name in candidates:
            if len(candidates) != 1:
                raise SyncError(
                    "pending cleanup authority has overlapping representations: "
                    f"{batch_name}"
                )
            return None
        if not candidates:
            return None
        if len(candidates) != 1:
            raise SyncError(
                f"pending cleanup authority has overlapping representations: {batch_name}"
            )
        representation = candidates[0]
        snapshot = _read_managed_state_file_snapshot(
            home,
            index_root / representation,
            index_fd,
            maximum_bytes=MAX_PENDING_CLEANUP_TICKET_BYTES,
        )
        if (
            not _managed_state_snapshot_has_complete_file_evidence(snapshot)
            or snapshot.payload is None
            or snapshot.file_type != stat.S_IFREG
        ):
            raise SyncError(
                f"pending cleanup authority representation changed: {batch_name}"
            )
        _require_pending_cleanup_file_snapshot_access_policy(
            home, index_root / representation, index_fd, snapshot
        )
        cleanup = _read_pending_cleanup_ticket(
            home,
            index_root / temp_name,
            expected_ticket_identity=snapshot.file_identity,
            allow_temporary=True,
            _captured_snapshot=snapshot,
        )
        if (
            cleanup is None
            or cleanup.version not in {5, 7}
            or not _cleanup_ticket_matches_quarantine_allocation(cleanup, allocation)
        ):
            raise SyncError(
                "pending quarantine allocation does not join cleanup authority: "
                f"{batch_name}"
            )
        _require_pending_cleanup_fd_access_policy(
            index_fd, index_root, expected_mode=0o700
        )
        if _directory_identity(
            index_fd
        ) != allocation.snapshot.parent_identity or not _bound_directory_matches(
            home, index_root, index_fd
        ):
            raise SyncError("pending quarantine allocation index changed")
        return cleanup
    finally:
        _close_fd_quietly(index_fd)


def _read_recoverable_private_use_receipt_representation(
    home: Path,
    batch_name: str,
) -> PendingPrivateUseRetirementReceipt | None:
    index_root = _pending_cleanup_index_path(home)
    index_fd = _open_directory_beneath(home, index_root)
    try:
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="private-use retirement scan exceeds the size limit",
        )
        canonical = batch_name + PENDING_PRIVATE_USE_RETIREMENT_SUFFIX
        temporary = canonical + PENDING_ATOMIC_PUBLICATION_TEMP_SUFFIX
        candidates = []
        for name in names:
            retained = _pending_cleanup_retained_canonical_name(name)
            if (retained or name) in {canonical, temporary}:
                candidates.append(name)
        if canonical in candidates:
            return None
        if not candidates:
            return None
        if len(candidates) != 1:
            raise SyncError(
                f"private-use retirement has overlapping receipts: {batch_name}"
            )
        representation = candidates[0]
        snapshot = _read_managed_state_file_snapshot(
            home,
            index_root / representation,
            index_fd,
            maximum_bytes=MAX_PENDING_TERMINAL_CLEANUP_TICKET_BYTES,
        )
        _require_pending_cleanup_file_snapshot_access_policy(
            home, index_root / representation, index_fd, snapshot
        )
        receipt = _read_pending_private_use_retirement_receipt(
            home,
            index_root / temporary,
            expected_identity=snapshot.file_identity,
            allow_temporary=True,
            _captured_snapshot=snapshot,
        )
        if receipt is None:
            raise SyncError(f"private-use retirement receipt disappeared: {batch_name}")
        represented = replace(receipt, path=index_root / representation)
        _require_pending_private_use_retirement_boundary(
            home, represented, receipt_member=representation
        )
        return represented
    finally:
        _close_fd_quietly(index_fd)


def _read_current_private_use_retirement_authority(
    home: Path,
    batch_name: str,
) -> PendingPrivateUseRetirementReceipt | None:
    receipt = _read_pending_private_use_retirement_receipt(
        home, _pending_private_use_retirement_path(home, batch_name)
    )
    if receipt is not None:
        return receipt
    return _read_recoverable_private_use_receipt_representation(home, batch_name)


def _pending_quarantine_allocation_recovery_state(
    home: Path,
    allocation: PendingQuarantineAllocationTicket,
) -> tuple[
    str,
    EphemeralQuarantineBatchBinding | None,
    str | None,
    tuple[int, int] | None,
]:
    """Classify one reservation-only v8 fence without adopting an entity.

    V8 proves only that both candidate names were absent when the reservation
    was published.  It binds neither a later batch inode nor its metadata or
    leaf, so any present canonical or isolated entity is foreign unless an
    authoritative matching v5/v7 ticket owns cleanup.  Only double absence may
    retire v8 directly.
    """
    batch_name = allocation.batch_root.name
    quarantine_root = allocation.batch_root.parent
    quarantine_fd = _open_directory_beneath(home, quarantine_root)
    try:
        _require_pending_cleanup_fd_access_policy(
            quarantine_fd,
            quarantine_root,
            expected_mode=0o700,
        )
        if _directory_identity(
            quarantine_fd
        ) != allocation.quarantine_root_identity or not _bound_directory_matches(
            home,
            quarantine_root,
            quarantine_fd,
        ):
            raise SyncError(f"pending quarantine allocation root changed: {batch_name}")
        receipt = _read_pending_private_use_retirement_receipt(
            home, _pending_private_use_retirement_path(home, batch_name)
        )
        if receipt is not None:
            _require_pending_private_use_retirement_boundary(
                home, receipt, receipt_member=receipt.path.name
            )
            return "delegated", None, None, None
        represented_receipt = _read_recoverable_private_use_receipt_representation(
            home, batch_name
        )
        if represented_receipt is not None:
            return "delegated", None, None, None
        represented_cleanup = _read_recoverable_joined_cleanup_representation(
            home, allocation
        )
        if represented_cleanup is not None:
            return "delegated", None, None, None
        canonical = _named_entry_identity(quarantine_fd, batch_name)
        isolated = _named_entry_identity(
            quarantine_fd,
            allocation.isolated_name,
        )
        if canonical is not None and isolated is not None:
            raise SyncError(
                f"pending quarantine allocation has canonical and isolated "
                f"entities: {batch_name}"
            )
        cleanup = _read_pending_cleanup_ticket(
            home,
            _pending_cleanup_ticket_path(home, batch_name),
        )
        if cleanup is not None:
            if _cleanup_ticket_matches_quarantine_allocation(cleanup, allocation):
                return "delegated", None, None, None
            # The v8 fence has reserved this exact batch name.  A same-name
            # v5/v7 record that does not bind the identical root, metadata and
            # isolated-name authority is not an alternative cleanup plan.  In
            # particular, dry-run must not describe the scaffold as removable
            # when the real publisher would reject the conflicting ticket.
            raise SyncError(
                "pending quarantine allocation does not join cleanup authority: "
                f"{batch_name}"
            )
        if canonical is None and isolated is None:
            _require_pending_quarantine_allocation_ticket_unchanged(home, allocation)
            return "absent", None, None, None
        _require_pending_quarantine_allocation_ticket_unchanged(home, allocation)
        raise SyncError(
            "pending quarantine allocation has a present entity without exact "
            f"cleanup authority and was retained: {batch_name}"
        )
    finally:
        _close_fd_quietly(quarantine_fd)


def _pending_quarantine_allocation_fence_is_cleanup_ready(
    home: Path,
    allocation: PendingQuarantineAllocationTicket,
) -> bool:
    state, _binding, _current_name, _expected_identity = (
        _pending_quarantine_allocation_recovery_state(home, allocation)
    )
    return state == "absent"


def _pending_cleanup_ready_batch_is_observed(
    home: Path,
    *,
    allow_v8_control_recovery: bool = False,
) -> bool:
    if not _pending_link_pointer_is_absent(home):
        return False
    cleanup_ready = bool(_discover_pending_staging_markers(home))
    cleanup_ready = bool(_discover_pending_staging_marker_temps(home)) or cleanup_ready
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return cleanup_ready
    try:
        if not _bound_directory_matches(home, index_root, index_fd):
            raise SyncError("pending cleanup index changed")
        with os.scandir(index_fd) as iterator:
            for scanned, entry in enumerate(iterator, start=1):
                if scanned > MAX_PENDING_CLEANUP_CONTROL_ENTRIES:
                    raise SyncError(
                        "pending cleanup ticket scan exceeds the size limit"
                    )
                unresolved = _pending_cleanup_unresolved_ticket_representation(
                    entry.name
                )
                if unresolved is not None:
                    # Do not collapse unclassified ticket-derived bytes into a
                    # generic cleanup plan.  A caller may have checked moments
                    # earlier; this complete scan is the final observation
                    # before status or dry-run reports a recoverable action.
                    raise _pending_cleanup_unresolved_ticket_representation_error(
                        unresolved
                    )
                unresolved_allocation = (
                    _pending_quarantine_unresolved_allocation_representation(entry.name)
                )
                if unresolved_allocation is not None:
                    # The same final scan also closes the interval after an
                    # earlier preflight check. A malformed v8-derived name
                    # remains evidence only; it cannot turn a read-only
                    # observation into an automatic cleanup plan.
                    raise _pending_quarantine_unresolved_allocation_representation_error(
                        unresolved_allocation
                    )
                unresolved_receipt = (
                    _pending_private_use_retirement_unresolved_representation(
                        entry.name
                    )
                )
                if unresolved_receipt is not None:
                    receipt_batch, receipt_name = unresolved_receipt
                    raise SyncError(
                        "private-use retirement receipt representation must be "
                        f"reconciled before new mutation: {receipt_batch}: "
                        f"{receipt_name}"
                    )
                if _pending_private_use_retirement_batch_name(entry.name) is not None:
                    receipt = _read_pending_private_use_retirement_receipt(
                        home, index_root / entry.name
                    )
                    if receipt is None:
                        raise SyncError(
                            f"private-use retirement receipt disappeared: {entry.name}"
                        )
                    _require_pending_private_use_retirement_boundary(
                        home, receipt, receipt_member=entry.name
                    )
                    cleanup_ready = True
                    continue
                allocation_batch_name = _pending_quarantine_allocation_batch_name(
                    entry.name
                )
                if allocation_batch_name is not None:
                    allocation = _read_pending_quarantine_allocation_ticket(
                        home,
                        index_root / entry.name,
                    )
                    if allocation is not None:
                        cleanup_ready = (
                            _pending_quarantine_allocation_fence_is_cleanup_ready(
                                home,
                                allocation,
                            )
                            or cleanup_ready
                        )
                    continue
                allocation_temp_batch_name = (
                    _pending_quarantine_allocation_temp_batch_name(entry.name)
                )
                retained_allocation = _pending_quarantine_retained_allocation_name(
                    entry.name
                )
                retained_allocation_temp = (
                    _pending_quarantine_retained_allocation_temp_name(entry.name)
                )
                if (
                    allocation_temp_batch_name is not None
                    or retained_allocation is not None
                    or retained_allocation_temp is not None
                ):
                    blocked_batch_name = allocation_temp_batch_name
                    if blocked_batch_name is None and retained_allocation is not None:
                        blocked_batch_name = retained_allocation[1]
                    if blocked_batch_name is None:
                        assert retained_allocation_temp is not None
                        blocked_batch_name = retained_allocation_temp[1]
                    if not allow_v8_control_recovery:
                        raise SyncError(
                            "pending quarantine allocation control requires mutation "
                            "recovery before cleanup readiness can be classified: "
                            f"{blocked_batch_name}: {entry.name}"
                        )
                    cleanup_ready = True
                    continue
                retained = _pending_cleanup_retained_control_name(entry.name)
                if retained is not None:
                    cleanup_ready = True
                if (
                    _pending_cleanup_ticket_temp_batch_name(entry.name) is not None
                    or _pending_cleanup_retained_ticket_temp_name(entry.name)
                    is not None
                    or _pending_quarantine_metadata_stage_batch_name(entry.name)
                    is not None
                    or _pending_quarantine_retained_metadata_stage_name(entry.name)
                    is not None
                    or _pending_cleanup_cursor_temp_canonical_name(entry.name)
                    is not None
                    or _pending_private_use_retirement_temp_batch_name(entry.name)
                    is not None
                ):
                    cleanup_ready = True
                for suffix in (
                    PENDING_CLEANUP_TICKET_SUFFIX,
                    PENDING_CLEANUP_EMPTY_PROOF_SUFFIX,
                    PENDING_CLEANUP_TERMINAL_VALIDATION_SUFFIX,
                    PENDING_PRIVATE_USE_RETIREMENT_SUFFIX,
                ):
                    if not entry.name.endswith(suffix):
                        continue
                    batch_name = entry.name[: -len(suffix)]
                    if (
                        len(batch_name) <= MAX_PENDING_LINK_BATCH_NAME_BYTES
                        and PENDING_LINK_BATCH_RE.fullmatch(batch_name) is not None
                    ):
                        cleanup_ready = True
        return cleanup_ready
    finally:
        _close_fd_quietly(index_fd)


def _cleanup_pending_quarantine_allocations(
    home: Path,
    *,
    budget: PendingCleanupActionBudget,
) -> int:
    """Recover only exact v8 states with independently proven cleanup authority."""
    _require_no_pending_unresolved_ticket_representations(home)
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return 0
    try:
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="pending quarantine allocation scan exceeds the limit",
        )
        for name in names:
            unresolved = _pending_quarantine_unresolved_allocation_representation(name)
            if unresolved is not None:
                raise _pending_quarantine_unresolved_allocation_representation_error(
                    unresolved
                )
        allocation_names = sorted(
            name
            for name in names
            if _pending_quarantine_allocation_batch_name(name) is not None
        )
    finally:
        _close_fd_quietly(index_fd)
    cleaned = 0
    for name in allocation_names:
        batch_name = _pending_quarantine_allocation_batch_name(name)
        assert batch_name is not None
        if not budget.charge_batch(batch_name):
            continue
        allocation = _read_pending_quarantine_allocation_ticket(
            home,
            index_root / name,
        )
        if allocation is None:
            continue
        state, _binding, _current_name, _expected_identity = (
            _pending_quarantine_allocation_recovery_state(
                home,
                allocation,
            )
        )
        if state == "absent":
            _retire_quarantine_allocation_after_batch_absent(home, allocation)
            cleaned += 1
            budget.mark_batch_completed(batch_name)
            continue
        # The exact v5/v7 cleanup protocol owns the entity.  Its scanner may be
        # budget-deferred; v8 remains as a mutation fence until removal.
    return cleaned


def _cleanup_pending_private_use_retirements(
    home: Path,
    *,
    budget: PendingCleanupActionBudget,
) -> int:
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return 0
    try:
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="private-use retirement scan exceeds the size limit",
        )
        receipt_names = sorted(
            name
            for name in names
            if _pending_private_use_retirement_batch_name(name) is not None
        )
    finally:
        _close_fd_quietly(index_fd)
    cleaned = 0
    for name in receipt_names:
        batch_name = _pending_private_use_retirement_batch_name(name)
        assert batch_name is not None
        if not budget.charge_batch(batch_name):
            continue
        try:
            receipt = _read_pending_private_use_retirement_receipt(
                home, index_root / name
            )
            if receipt is None:
                continue
            _retire_pending_private_use_controls(home, receipt)
        except (FileNotFoundError, OSError, SyncError) as error:
            raise _pending_cleanup_authority_classification_error(
                batch_name, error
            ) from error
        cleaned += 1
        budget.mark_batch_completed(batch_name)
    return cleaned


def _cleanup_ready_pending_batches(
    home: Path,
    *,
    budget: PendingCleanupActionBudget | None = None,
) -> int:
    if not _pending_link_pointer_is_absent(home):
        return 0
    _require_no_pending_unresolved_ticket_representations(home)
    action_budget = budget or PendingCleanupActionBudget(
        MAX_PENDING_CLEANUP_BATCHES_PER_RUN
    )
    completed_before = action_budget.completed
    _restore_pending_cleanup_control_tombstones(
        home,
        budget=action_budget,
    )
    _cleanup_pending_cleanup_ticket_temps(
        home,
        budget=action_budget,
    )
    _cleanup_pending_private_use_retirements(
        home,
        budget=action_budget,
    )
    _publish_discovered_staging_cleanup_tickets(
        home,
        budget=action_budget,
    )
    _cleanup_orphan_pending_cleanup_empty_proofs(
        home,
        budget=action_budget,
    )
    _cleanup_orphan_pending_ephemeral_private_phases(
        home,
        budget=action_budget,
    )
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return action_budget.completed - completed_before
    _close_fd_quietly(index_fd)
    cursor_cleanup_actions = _cleanup_pending_cleanup_cursor_temp(
        home,
        index_root,
        limit=action_budget.remaining,
    )
    action_budget.consume_control_actions(cursor_cleanup_actions)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return action_budget.completed - completed_before
    candidates: list[str] = []
    try:
        if not _bound_directory_matches(home, index_root, index_fd):
            raise SyncError("pending cleanup index changed")
        with os.scandir(index_fd) as iterator:
            for scanned, entry in enumerate(iterator, start=1):
                if scanned > MAX_PENDING_CLEANUP_CONTROL_ENTRIES:
                    raise SyncError(
                        "pending cleanup ticket scan exceeds the size limit"
                    )
                if not entry.name.endswith(PENDING_CLEANUP_TICKET_SUFFIX):
                    continue
                batch_name = entry.name[: -len(PENDING_CLEANUP_TICKET_SUFFIX)]
                if (
                    len(batch_name) <= MAX_PENDING_LINK_BATCH_NAME_BYTES
                    and PENDING_LINK_BATCH_RE.fullmatch(batch_name) is not None
                ):
                    candidates.append(entry.name)
    finally:
        _close_fd_quietly(index_fd)

    ordered = sorted(candidates)
    if not ordered:
        _cleanup_pending_quarantine_allocations(home, budget=action_budget)
        return action_budget.completed - completed_before
    cursor = _read_pending_cleanup_cursor(home, index_root)
    start = 0
    if cursor is not None:
        start = next(
            (index for index, name in enumerate(ordered) if name > cursor),
            0,
        )
    rotated = ordered[start:] + ordered[:start]
    selected: list[str] = []
    for ticket_name in rotated:
        batch_name = ticket_name[: -len(PENDING_CLEANUP_TICKET_SUFFIX)]
        if action_budget.charge_batch(batch_name):
            selected.append(ticket_name)
    for ticket_name in selected:
        batch_name = ticket_name[: -len(PENDING_CLEANUP_TICKET_SUFFIX)]
        try:
            ticket = _read_pending_cleanup_ticket(
                home,
                index_root / ticket_name,
            )
        except (FileNotFoundError, OSError, SyncError) as error:
            raise _pending_cleanup_authority_classification_error(
                batch_name,
                error,
            ) from error
        if ticket is None:
            continue
        try:
            if _remove_cleanup_ready_batch(home, ticket):
                action_budget.mark_batch_completed(batch_name)
        except (FileNotFoundError, OSError, SyncError) as error:
            if ticket.version == 4:
                raise SyncError(
                    "pending terminal regular-file validation was retained: "
                    f"{batch_name}: {error}"
                ) from error
            if ticket.version in {5, 6, 7}:
                raise SyncError(
                    "pending ephemeral quarantine cleanup authority was retained: "
                    f"{batch_name}: {error}"
                ) from error
            print(
                "warning: deferred pending transaction cleanup was retained: "
                f"{batch_name}: {error}"
            )
    if selected:
        cursor_cleanup_actions = _write_pending_cleanup_cursor(
            home,
            index_root,
            selected[-1],
            max_temp_cleanup_actions=action_budget.remaining,
        )
        action_budget.consume_control_actions(cursor_cleanup_actions)
    _cleanup_pending_quarantine_allocations(home, budget=action_budget)
    return action_budget.completed - completed_before


def _try_cleanup_ready_pending_batches(home: Path) -> int:
    try:
        return _cleanup_ready_pending_batches(home)
    except (OSError, SyncError) as error:
        print(f"warning: pending transaction cleanup scan was deferred: {error}")
        return 0


def _require_no_pending_terminal_mutation_authority(home: Path) -> None:
    if not _pending_link_pointer_is_absent(home):
        raise SyncError(
            "active pending transaction must be recovered before new mutation"
        )
    _require_no_pending_unresolved_ticket_representations(home)
    index_root = _pending_cleanup_index_path(home)
    try:
        index_fd = _open_directory_beneath(home, index_root)
    except FileNotFoundError:
        return
    try:
        if not _bound_directory_matches(home, index_root, index_fd):
            raise SyncError("pending cleanup index changed before mutation")
        names = _directory_member_names(
            index_fd,
            maximum_entries=MAX_PENDING_CLEANUP_CONTROL_ENTRIES,
            overflow_message="pending cleanup authority scan exceeds the size limit",
        )
    finally:
        _close_fd_quietly(index_fd)
    for name in names:
        retirement_batch_name = (
            _pending_private_use_retirement_representation_batch_name(name)
        )
        if retirement_batch_name is not None:
            raise SyncError(
                "private-use retirement authority must be reconciled before new "
                f"mutation: {retirement_batch_name}"
            )
        unresolved_allocation = (
            _pending_quarantine_unresolved_allocation_representation(name)
        )
        if unresolved_allocation is not None:
            raise _pending_quarantine_unresolved_allocation_representation_error(
                unresolved_allocation
            )
        allocation_batch_name = _pending_quarantine_allocation_batch_name(name)
        allocation_temp_batch_name = _pending_quarantine_allocation_temp_batch_name(
            name
        )
        retained_allocation = _pending_quarantine_retained_allocation_name(name)
        retained_allocation_temp = _pending_quarantine_retained_allocation_temp_name(
            name
        )
        metadata_stage_batch_name = _pending_quarantine_metadata_stage_batch_name(name)
        retained_metadata_stage = _pending_quarantine_retained_metadata_stage_name(name)
        if (
            allocation_batch_name is not None
            or allocation_temp_batch_name is not None
            or retained_allocation is not None
            or retained_allocation_temp is not None
            or metadata_stage_batch_name is not None
            or retained_metadata_stage is not None
        ):
            blocked_batch_name = allocation_batch_name or allocation_temp_batch_name
            if blocked_batch_name is None and retained_allocation is not None:
                blocked_batch_name = retained_allocation[1]
            if blocked_batch_name is None:
                if retained_allocation_temp is not None:
                    blocked_batch_name = retained_allocation_temp[1]
                elif metadata_stage_batch_name is not None:
                    blocked_batch_name = metadata_stage_batch_name
                else:
                    assert retained_metadata_stage is not None
                    blocked_batch_name = retained_metadata_stage[1]
            raise SyncError(
                "pending quarantine allocation must be reconciled before new "
                f"mutation: {blocked_batch_name}"
            )
        temp_batch_name = _pending_cleanup_ticket_temp_batch_name(name)
        retained_temp = _pending_cleanup_retained_ticket_temp_name(name)
        if temp_batch_name is not None or retained_temp is not None:
            # Complete v6/v7 temps are durable authority awaiting promotion;
            # incomplete or unreadable temps are unresolved state.  Neither is
            # safe to ignore merely because this run spent its cleanup budget.
            blocked_batch_name = (
                temp_batch_name if temp_batch_name is not None else retained_temp[1]
            )
            raise SyncError(
                "pending cleanup ticket temp must be reconciled before new "
                f"mutation: {blocked_batch_name}"
            )
        retained = _pending_cleanup_retained_control_name(name)
        if retained is not None and retained[0].endswith(
            (
                PENDING_CLEANUP_TICKET_SUFFIX,
                PENDING_CLEANUP_TERMINAL_VALIDATION_SUFFIX,
            )
        ):
            raise SyncError(
                "retained pending cleanup authority must be reconciled before "
                f"new mutation: {retained[1]}"
            )
        unresolved_ticket_representation = (
            _pending_cleanup_unresolved_ticket_representation(name)
        )
        if unresolved_ticket_representation is not None:
            related_ticket_batch_name, _related_ticket_name = (
                unresolved_ticket_representation
            )
            raise SyncError(
                "pending cleanup ticket representation must be reconciled before "
                f"new mutation: {related_ticket_batch_name}"
            )
        if name.endswith(PENDING_CLEANUP_TERMINAL_VALIDATION_SUFFIX):
            batch_name = name[: -len(PENDING_CLEANUP_TERMINAL_VALIDATION_SUFFIX)]
            if (
                len(batch_name) <= MAX_PENDING_LINK_BATCH_NAME_BYTES
                and PENDING_LINK_BATCH_RE.fullmatch(batch_name) is not None
            ):
                raise SyncError(
                    "pending cleanup private or terminal authority must be "
                    f"reconciled before new mutation: {batch_name}"
                )
        if not name.endswith(PENDING_CLEANUP_TICKET_SUFFIX):
            continue
        batch_name = name[: -len(PENDING_CLEANUP_TICKET_SUFFIX)]
        if (
            len(batch_name) > MAX_PENDING_LINK_BATCH_NAME_BYTES
            or PENDING_LINK_BATCH_RE.fullmatch(batch_name) is None
        ):
            continue
        try:
            ticket = _read_pending_cleanup_ticket(
                home,
                index_root / name,
            )
        except (FileNotFoundError, OSError, SyncError) as error:
            raise _pending_cleanup_authority_classification_error(
                batch_name,
                error,
            ) from error
        if ticket is not None and ticket.version in {3, 4, 5, 6, 7}:
            raise SyncError(
                "pending cleanup authority must reach terminal validation before "
                f"new mutation: {batch_name} (ticket v{ticket.version})"
            )


def _clear_pending_link_pointer(
    home: Path,
    batch: PendingLinkBatch,
    *,
    phase: str = "before",
) -> None:
    pointer_path = _pending_link_pointer_path(home)
    parent_fd = _open_directory_beneath(home, home)
    try:
        current = _read_managed_state_file_snapshot(home, pointer_path, parent_fd)
        if not current.exists:
            raise SyncError("pending link pointer disappeared and was not finalized")
        expected = batch.pointer_snapshot
        if expected is None or not _managed_state_snapshot_exact(current, expected):
            raise SyncError("pending link pointer changed and was left in place")
        committed = _pending_commit_decision(home, batch)
        if phase == "before" and committed:
            raise SyncError(
                "refusing to clear committed pending transaction as precommit"
            )
        if phase == "after" and not committed:
            raise SyncError(
                "refusing to clear pending transaction without commit marker"
            )
        _verify_pending_link_phase(home, batch, phase)
        _quarantine_pending_link_pointer(
            home,
            batch,
            expected,
            parent_fd,
            label="complete",
        )
        batch.pointer_snapshot = None
    finally:
        _close_fd_quietly(parent_fd)


def _prepare_pending_managed_state_transaction(
    home: Path,
    batch: PendingLinkBatch,
    state: ManagedState,
) -> ManagedStateFileTransaction:
    if state != batch.state_after_value:
        raise SyncError("planned managed state changed before publication")
    transaction = _prepare_managed_state_transaction(home, state, batch.state_before)
    if (
        transaction.after.payload != batch.state_after.payload
        or transaction.after.mode != batch.state_after.mode
        or batch.state_after.file_identity is None
    ):
        raise SyncError("pending managed state evidence does not match planned state")
    transaction.batch_root = batch.batch_root
    transaction.before_evidence = (
        batch.batch_root / Path(*batch.state_before_evidence.parts)
        if batch.state_before_evidence is not None
        else None
    )
    transaction.after_evidence = batch.batch_root / Path(
        *batch.state_after_evidence.parts
    )
    transaction.after_evidence_identity = batch.state_after.file_identity
    return transaction


def _restore_pending_state_before(
    home: Path,
    batch: PendingLinkBatch,
) -> None:
    if not batch.state_before.exists:
        return
    if batch.state_before_evidence is None or batch.state_before.file_identity is None:
        raise SyncError("pending transaction state-before evidence is missing")
    evidence = batch.batch_root / Path(*batch.state_before_evidence.parts)
    evidence_parent_fd = _open_directory_beneath(home, evidence.parent)
    state_path = _state_path(home)
    state_parent_fd = _open_directory_beneath(home, state_path.parent)
    try:
        if _directory_identity(state_parent_fd) != batch.state_before.parent_identity:
            raise SyncError("pending transaction state parent changed")
        if _managed_state_name_exists(state_parent_fd, state_path.name):
            raise SyncError(
                "refusing to overwrite canonical managed state during recovery"
            )
        evidence_snapshot = _read_managed_state_file_snapshot(
            home,
            evidence,
            evidence_parent_fd,
            expected_identity=batch.state_before.file_identity,
        )
        if (
            not _managed_state_snapshot_matches_file_evidence(
                evidence_snapshot,
                batch.state_before,
            )
            or evidence_snapshot.payload != batch.state_before.payload
            or evidence_snapshot.mode != batch.state_before.mode
        ):
            raise SyncError("pending transaction state-before evidence changed")
        os.link(
            evidence.name,
            state_path.name,
            src_dir_fd=evidence_parent_fd,
            dst_dir_fd=state_parent_fd,
            follow_symlinks=False,
        )
        os.fsync(state_parent_fd)
        restored = _read_managed_state_file_snapshot(
            home,
            state_path,
            state_parent_fd,
            expected_identity=batch.state_before.file_identity,
        )
        if (
            not _managed_state_snapshot_matches_file_evidence(
                restored,
                batch.state_before,
            )
            or restored.file_identity != batch.state_before.file_identity
            or restored.payload != batch.state_before.payload
            or restored.mode != batch.state_before.mode
        ):
            raise SyncError("exact managed state restoration changed")
    finally:
        _close_fd_quietly(state_parent_fd)
        _close_fd_quietly(evidence_parent_fd)


def _rollback_pending_state_to_before(
    home: Path,
    batch: PendingLinkBatch,
    state_snapshot: ManagedStateFileSnapshot,
) -> tuple[ManagedState, ManagedStateFileSnapshot]:
    if _managed_state_snapshot_exact(state_snapshot, batch.state_before):
        return _load_managed_state_with_snapshot(home)
    if not state_snapshot.exists:
        _restore_pending_state_before(home, batch)
    elif _managed_state_snapshot_exact(state_snapshot, batch.state_after):
        state_path = _state_path(home)
        state_parent_fd = _open_directory_beneath(home, state_path.parent)
        try:
            if (
                _directory_identity(state_parent_fd)
                != batch.state_after.parent_identity
            ):
                raise SyncError("pending transaction state parent changed")
            transaction = ManagedStateFileTransaction(
                before=batch.state_after,
                after=ManagedStateFileSnapshot(exists=False),
                batch_root=batch.batch_root,
                state_parent_identity=batch.state_after.parent_identity,
            )
            moved, matches = _move_managed_state_entry_to_quarantine(
                home,
                transaction,
                state_parent_fd,
                state_path.name,
                "pending-precommit",
                expected_identity=batch.state_after.file_identity,
                expected_snapshot=batch.state_after,
            )
            if not matches:
                raise SyncError(
                    "pending precommit state changed and was retained in "
                    f"quarantine: {moved}"
                )
            if _managed_state_name_exists(state_parent_fd, state_path.name):
                raise SyncError(
                    "pending precommit canonical state reappeared during rollback"
                )
        finally:
            _close_fd_quietly(state_parent_fd)
        _restore_pending_state_before(home, batch)
    else:
        raise SyncError(
            "pending transaction found an ambiguous canonical managed state inode; "
            "the transaction and evidence were retained"
        )
    state, current_snapshot = _load_managed_state_with_snapshot(home)
    if (
        not _managed_state_snapshot_exact(current_snapshot, batch.state_before)
        or state != batch.state_before_value
    ):
        raise SyncError("pending precommit managed state restoration changed")
    return state, current_snapshot


def _pending_record_evidence_snapshot(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
) -> SymlinkSnapshot | RegularFileSnapshot:
    if (
        record.evidence is None
        or record.stage is None
        or record.link_target is None
        or record.evidence_identity is None
        or record.stage_identity is None
    ):
        raise SyncError(f"pending record has no produced evidence: {record.target}")
    evidence = batch.batch_root / Path(*record.evidence.parts)
    stage = batch.batch_root / Path(*record.stage.parts)
    if record.is_regular():
        expected_values = (
            record.regular_sha256,
            record.regular_size,
            record.regular_mode,
            record.regular_uid,
            record.regular_link_count,
        )
        if any(value is None for value in expected_values):
            raise SyncError(
                f"pending regular-file record is incomplete: {record.target}"
            )
        try:
            evidence_snapshot = _read_regular_file_snapshot_beneath(
                home,
                evidence,
                require_managed_access=False,
            )
            stage_snapshot = _read_regular_file_snapshot_beneath(
                home,
                stage,
                require_managed_access=False,
            )
        except (FileNotFoundError, OSError, SyncError) as error:
            raise SyncError(
                f"pending regular-file evidence is missing or unsafe: {record.target}"
            ) from error
        for snapshot in (stage_snapshot, evidence_snapshot):
            if (
                snapshot.file_identity != record.evidence_identity
                or snapshot.file_identity != record.stage_identity
                or snapshot.sha256 != record.regular_sha256
                or snapshot.size != record.regular_size
                or snapshot.mode != record.regular_mode
                or snapshot.uid != record.regular_uid
                or snapshot.link_count
                not in {
                    record.regular_link_count,
                    record.regular_link_count + 1,
                }
            ):
                raise SyncError(
                    f"pending regular-file evidence changed: {record.target}"
                )
        _verify_pending_regular_aliases(
            home,
            batch,
            evidence,
            evidence_snapshot,
        )
        return evidence_snapshot
    try:
        evidence_snapshot = _read_symlink_snapshot_beneath(home, evidence)
    except (FileNotFoundError, OSError, SyncError) as error:
        raise SyncError(
            f"pending link evidence is missing or unsafe: {record.target}"
        ) from error
    if (
        evidence_snapshot.link_target != record.link_target
        or evidence_snapshot.link_identity != record.evidence_identity
    ):
        raise SyncError(f"pending link evidence changed: {record.target}")
    stage_snapshot = _read_optional_symlink_snapshot_beneath(home, stage)
    if stage_snapshot is None or (
        stage_snapshot.link_identity != record.stage_identity
        or stage_snapshot.link_identity != evidence_snapshot.link_identity
        or stage_snapshot.link_target != evidence_snapshot.link_target
    ):
        raise SyncError(f"pending link stage changed: {record.target}")
    return evidence_snapshot


def _pending_record_before_evidence_snapshot(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
) -> SymlinkSnapshot | RegularFileSnapshot:
    if record.before_evidence is None or record.before_evidence_identity is None:
        raise SyncError(f"pending record has no before evidence: {record.target}")
    planned_regular = _regular_snapshot_from_reconcile(record.planned_snapshot)
    if planned_regular is not None:
        snapshot = _read_regular_file_snapshot_beneath(
            home,
            batch.batch_root / Path(*record.before_evidence.parts),
            require_managed_access=False,
        )
        if (
            snapshot.file_identity != record.before_evidence_identity
            or not _regular_snapshot_leaf_matches(snapshot, planned_regular)
        ):
            raise SyncError(f"pending before evidence changed: {record.target}")
        _verify_pending_regular_aliases(
            home,
            batch,
            batch.batch_root / Path(*record.before_evidence.parts),
            snapshot,
        )
        return snapshot
    if record.planned_snapshot.link_target is None:
        raise SyncError(f"pending record has no before evidence: {record.target}")
    snapshot = _read_symlink_snapshot_beneath(
        home,
        batch.batch_root / Path(*record.before_evidence.parts),
    )
    if (
        snapshot.link_identity != record.before_evidence_identity
        or snapshot.link_identity != record.planned_snapshot.link_identity
        or snapshot.link_target != record.planned_snapshot.link_target
    ):
        raise SyncError(f"pending before evidence changed: {record.target}")
    return snapshot


def _pending_record_backup_snapshot(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
) -> SymlinkSnapshot | RegularFileSnapshot | None:
    if record.backup is None:
        return None
    backup = batch.batch_root / Path(*record.backup.parts)
    try:
        parent_fd = _open_directory_beneath(home, backup.parent)
    except FileNotFoundError:
        return None
    except (OSError, SyncError) as error:
        raise SyncError(f"pending backup is unreadable: {record.target}") from error
    try:
        if not _bound_directory_matches(home, backup.parent, parent_fd):
            raise SyncError(f"pending backup parent changed: {record.target}")
        try:
            metadata = os.stat(
                backup.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            return None
        except OSError as error:
            raise SyncError(f"pending backup is unreadable: {record.target}") from error

        planned_regular = _regular_snapshot_from_reconcile(record.planned_snapshot)
        if planned_regular is not None:
            if not stat.S_ISREG(metadata.st_mode):
                raise SyncError(
                    f"pending backup is not a regular file: {record.target}"
                )
            snapshot = _regular_file_snapshot_at(
                parent_fd,
                backup.name,
                backup,
            )
            if (
                snapshot.file_identity != record.before_evidence_identity
                or not _regular_snapshot_leaf_matches(snapshot, planned_regular)
            ):
                raise SyncError(f"pending backup changed: {record.target}")
            _verify_pending_regular_aliases(
                home,
                batch,
                backup,
                snapshot,
            )
            if not _bound_directory_matches(home, backup.parent, parent_fd):
                raise SyncError(f"pending backup parent changed: {record.target}")
            return snapshot

        if not stat.S_ISLNK(metadata.st_mode):
            raise SyncError(f"pending backup is not a symlink: {record.target}")
        identity, link_target = _symlink_snapshot_at(parent_fd, backup.name)
        snapshot = SymlinkSnapshot(
            parent_identity=_directory_identity(parent_fd),
            link_identity=identity,
            link_target=link_target,
        )
        if (
            snapshot.link_identity != record.before_evidence_identity
            or snapshot.link_target != record.planned_snapshot.link_target
        ):
            raise SyncError(f"pending backup changed: {record.target}")
        if not _bound_directory_matches(home, backup.parent, parent_fd):
            raise SyncError(f"pending backup parent changed: {record.target}")
        return snapshot
    finally:
        _close_fd_quietly(parent_fd)


def _pending_target_snapshot(
    home: Path,
    target: Path,
) -> tuple[SymlinkSnapshot | RegularFileSnapshot | None, bool]:
    captured = _capture_reconcile_target_snapshot(home, target)
    regular = _regular_snapshot_from_reconcile(captured)
    if regular is not None:
        return regular, True
    if captured.link_target is not None:
        assert captured.parent_identity is not None
        assert captured.link_identity is not None
        return (
            SymlinkSnapshot(
                parent_identity=captured.parent_identity,
                link_identity=captured.link_identity,
                link_target=captured.link_target,
            ),
            True,
        )
    return None, captured.link_identity is not None


def _symlink_snapshot_matches(
    actual: SymlinkSnapshot | RegularFileSnapshot | None,
    expected_parent_identity: tuple[int, int] | None,
    expected_identity: tuple[int, int] | None,
    expected_target: str | None,
) -> bool:
    return (
        isinstance(actual, SymlinkSnapshot)
        and expected_parent_identity is not None
        and expected_identity is not None
        and expected_target is not None
        and actual.parent_identity == expected_parent_identity
        and actual.link_identity == expected_identity
        and actual.link_target == expected_target
    )


def _symlink_snapshot_leaf_matches(
    actual: SymlinkSnapshot | RegularFileSnapshot | None,
    expected_identity: tuple[int, int] | None,
    expected_target: str | None,
) -> bool:
    return (
        isinstance(actual, SymlinkSnapshot)
        and expected_identity is not None
        and expected_target is not None
        and actual.link_identity == expected_identity
        and actual.link_target == expected_target
    )


def _regular_snapshot_matches(
    actual: SymlinkSnapshot | RegularFileSnapshot | None,
    expected_parent_identity: tuple[int, int] | None,
    expected: RegularFileSnapshot,
    *,
    expected_link_count: int,
) -> bool:
    return (
        isinstance(actual, RegularFileSnapshot)
        and expected_parent_identity is not None
        and actual.parent_identity == expected_parent_identity
        and actual.file_identity == expected.file_identity
        and actual.sha256 == expected.sha256
        and actual.size == expected.size
        and actual.mode == expected.mode
        and actual.uid == expected.uid
        and _gid_matches_regular_file_access_policy(
            actual.gid,
            expected.gid,
            expected.mode,
        )
        and actual.link_count == expected_link_count
    )


def _regular_snapshot_leaf_matches(
    actual: SymlinkSnapshot | RegularFileSnapshot | None,
    expected: RegularFileSnapshot,
) -> bool:
    return (
        isinstance(actual, RegularFileSnapshot)
        and actual.file_identity == expected.file_identity
        and actual.sha256 == expected.sha256
        and actual.size == expected.size
        and actual.mode == expected.mode
        and actual.uid == expected.uid
        and _gid_matches_regular_file_access_policy(
            actual.gid,
            expected.gid,
            expected.mode,
        )
    )


def _restore_pending_record_before(
    home: Path,
    batch: PendingLinkBatch,
    record: PendingLinkRecord,
    before_evidence: SymlinkSnapshot | RegularFileSnapshot,
) -> None:
    assert record.before_evidence is not None
    target = home / Path(*record.target.parts)
    expected_target = ReconcileTargetSnapshot(
        parent_identity=record.planned_snapshot.parent_identity,
        ancestor_identity=record.planned_snapshot.parent_identity,
    )
    source = batch.batch_root / Path(*record.before_evidence.parts)
    if isinstance(before_evidence, RegularFileSnapshot):
        restored = _publish_regular_reconcile_hardlink_beneath(
            home,
            source,
            target,
            before_evidence,
            expected_target,
            {},
            pending_batch=batch,
            pending_record=record,
            cleanup_phase="before",
        )
        if not _regular_snapshot_leaf_matches(
            restored,
            before_evidence,
        ):
            raise SyncError(f"pending preimage restoration changed: {record.target}")
        return
    restored = _publish_symlink_hardlink_beneath(
        home,
        source,
        target,
        before_evidence,
        expected_target,
        {},
    )
    if (
        restored.link_identity != record.planned_snapshot.link_identity
        or restored.link_target != record.planned_snapshot.link_target
    ):
        raise SyncError(f"pending preimage restoration changed: {record.target}")


def _managed_state_snapshot_exact(
    actual: ManagedStateFileSnapshot,
    expected: ManagedStateFileSnapshot,
) -> bool:
    if actual.exists != expected.exists:
        return False
    if actual.parent_identity != expected.parent_identity:
        return False
    if not expected.exists:
        return True
    return (
        actual.file_identity == expected.file_identity
        and actual.mode == expected.mode
        and actual.payload == expected.payload
        and actual.uid == expected.uid
        and _gid_matches_regular_file_access_policy(
            actual.gid,
            expected.gid,
            expected.mode,
        )
    )


def _managed_state_staging_snapshot_transition_is_allowed(
    initial: ManagedStateFileSnapshot,
    current: ManagedStateFileSnapshot,
    bound_parent_identity: tuple[int, int],
) -> bool:
    if current.parent_identity != bound_parent_identity:
        return False
    if initial.exists or initial.parent_identity is not None:
        return _managed_state_snapshot_exact(current, initial)
    return not current.exists


def _bind_managed_state_parent_for_pending_staging(
    home: Path,
    initial_snapshot: ManagedStateFileSnapshot,
    expected_state: ManagedState,
) -> ManagedStateFileSnapshot:
    state_parent = _state_path(home).parent
    state_parent_fd = _open_or_create_directory_beneath(
        home,
        state_parent,
        mode=0o700,
    )
    try:
        bound_parent_identity = _directory_identity(state_parent_fd)
        if not _bound_directory_matches(home, state_parent, state_parent_fd):
            raise SyncError(
                "managed state parent changed before pending transaction staging"
            )
        current_state, current_snapshot = _load_managed_state_with_snapshot(home)
        if not _bound_directory_matches(
            home, state_parent, state_parent_fd
        ) or not _managed_state_staging_snapshot_transition_is_allowed(
            initial_snapshot,
            current_snapshot,
            bound_parent_identity,
        ):
            raise SyncError(
                "managed state snapshot changed before pending transaction staging"
            )
    finally:
        _close_fd_quietly(state_parent_fd)
    if current_state != expected_state:
        raise SyncError("managed state changed before pending transaction staging")
    return current_snapshot


def _verify_pending_link_claims(
    home: Path,
    batch: PendingLinkBatch,
    phase: str,
) -> None:
    if phase == "before":
        claims = batch.claims_before
    elif phase == "after":
        claims = batch.claims_after
    else:
        raise SyncError(f"unsupported pending claim phase: {phase}")
    for claim in claims:
        evidence_snapshot = _read_symlink_snapshot_beneath(
            home,
            batch.batch_root / Path(*claim.evidence.parts),
        )
        if (
            evidence_snapshot.link_identity != claim.link_identity
            or evidence_snapshot.link_target != claim.link_target
        ):
            raise SyncError(
                f"pending {phase}-state claim evidence changed: {claim.target}"
            )
        target = home / Path(*claim.target.parts)
        target_snapshot, target_exists = _pending_target_snapshot(home, target)
        if _symlink_snapshot_matches(
            target_snapshot,
            claim.parent_identity,
            claim.link_identity,
            claim.link_target,
        ):
            continue
        if _symlink_snapshot_leaf_matches(
            target_snapshot,
            claim.link_identity,
            claim.link_target,
        ):
            raise SyncError(
                f"pending {phase}-state claim parent changed: {claim.target}"
            )
        raise SyncError(
            f"pending {phase}-state claim is not the exact evidence inode: "
            f"{claim.target}"
        )


def _verify_pending_before_absences(
    home: Path,
    batch: PendingLinkBatch,
) -> None:
    before_semantic_keys = {
        (semantic[0], semantic[1])
        for semantic in _pending_state_claim_semantics(
            home,
            batch.state_before_value,
            metadata_version=batch.metadata_version,
        )
    }
    for record in batch.records:
        key = (record.scope, record.target)
        if record.action == "create":
            _verify_pending_record_bound_create_absence(
                home,
                record,
                phase="before-state",
            )
        elif record.action == "retire-absent" and key in before_semantic_keys:
            _verify_pending_record_bound_retired_absence(
                home,
                record,
                phase="before-state",
            )
        elif record.action == PENDING_RELINQUISH_FOREIGN_ACTION:
            _verify_pending_record_bound_foreign_relinquishment(
                home,
                record,
                phase="before-state",
            )


def _verify_pending_release_expectations(
    home: Path,
    expectations: tuple[PendingReleaseExpectation, ...],
    *,
    phase: str,
) -> None:
    for expectation in expectations:
        identity, directory_identity = (
            _installed_release_identity_and_directory_identity(
                home,
                expectation.owner,
                expectation.sha,
            )
        )
        if (
            directory_identity != expectation.directory_identity
            or identity[2] != expectation.tree_sha256
        ):
            raise SyncError(
                f"pending {phase}-state release tree changed: "
                f"{expectation.owner}@{expectation.sha}"
            )


def _verify_pending_link_phase(
    home: Path,
    batch: PendingLinkBatch,
    phase: str,
) -> None:
    if phase == "before":
        expected_snapshot = batch.state_before
        expected_state = batch.state_before_value
    elif phase == "after":
        expected_snapshot = batch.state_after
        expected_state = batch.state_after_value
    else:
        raise SyncError(f"unsupported pending transaction phase: {phase}")
    state, state_snapshot = _load_managed_state_with_snapshot(home)
    if not _managed_state_snapshot_exact(state_snapshot, expected_snapshot):
        raise SyncError(f"pending {phase}-state canonical managed state is not exact")
    if state != expected_state:
        raise SyncError(f"pending {phase}-state managed payload changed")
    expectations = batch.releases_before if phase == "before" else batch.releases_after
    _verify_pending_release_expectations(
        home,
        expectations,
        phase=phase,
    )
    _verify_pending_link_claims(home, batch, phase)
    if phase == "before":
        _verify_pending_before_absences(home, batch)


def _verify_committed_pending_link_records(
    home: Path,
    batch: PendingLinkBatch,
) -> None:
    for record in batch.records:
        if record.action in {
            "retire-absent",
            PENDING_RELINQUISH_FOREIGN_ACTION,
        }:
            # The committed state deliberately relinquishes this path. Its later
            # user-owned contents are outside the synchronizer's claim.
            continue
        producing = record.action in {
            "create",
            "replace",
            "quarantine-replace",
        }
        destructive = record.action in {
            "replace",
            "quarantine-replace",
            "remove",
            "quarantine-remove",
        }
        target = home / Path(*record.target.parts)
        target_snapshot, target_exists = _pending_target_snapshot(home, target)
        if destructive and _pending_record_backup_snapshot(home, batch, record) is None:
            raise SyncError(f"committed pending backup is missing: {record.target}")
        if producing:
            evidence = _pending_record_evidence_snapshot(home, batch, record)
            if isinstance(evidence, RegularFileSnapshot):
                target_matches = _regular_snapshot_matches(
                    target_snapshot,
                    record.planned_snapshot.parent_identity,
                    evidence,
                    expected_link_count=evidence.link_count,
                )
                leaf_matches = _regular_snapshot_leaf_matches(
                    target_snapshot,
                    evidence,
                )
            else:
                target_matches = _symlink_snapshot_matches(
                    target_snapshot,
                    record.planned_snapshot.parent_identity,
                    evidence.link_identity,
                    evidence.link_target,
                )
                leaf_matches = _symlink_snapshot_leaf_matches(
                    target_snapshot,
                    evidence.link_identity,
                    evidence.link_target,
                )
            if not target_matches and leaf_matches:
                raise SyncError(
                    f"committed pending target parent changed: {record.target}"
                )
            if not target_matches:
                raise SyncError(
                    "committed pending target is not the exact evidence inode: "
                    f"{record.target}"
                )
            continue
        if record.scope == "current":
            if target_exists:
                raise SyncError(
                    f"committed current removal target still exists: {record.target}"
                )
            continue
        before = _pending_record_before_evidence_snapshot(home, batch, record)
        if isinstance(before, RegularFileSnapshot):
            before_leaf_matches = _regular_snapshot_leaf_matches(
                target_snapshot,
                before,
            )
            before_matches = _regular_snapshot_matches(
                target_snapshot,
                record.planned_snapshot.parent_identity,
                before,
                expected_link_count=before.link_count,
            )
        else:
            before_leaf_matches = _symlink_snapshot_leaf_matches(
                target_snapshot,
                before.link_identity,
                before.link_target,
            )
            before_matches = _symlink_snapshot_matches(
                target_snapshot,
                record.planned_snapshot.parent_identity,
                before.link_identity,
                before.link_target,
            )
        if before_matches:
            raise SyncError(f"committed managed removal did not run: {record.target}")
        if before_leaf_matches:
            raise SyncError(
                f"committed managed removal target parent changed: {record.target}"
            )
        # A foreign replacement is unclaimed by the committed state and is
        # intentionally preserved.


def _batch_has_regular_records(batch: PendingLinkBatch) -> bool:
    return any(record.has_regular_authority() for record in batch.records)


def _verify_final_regular_targets(
    home: Path,
    ticket: PendingBatchCleanupTicket,
) -> None:
    if ticket.version != 4:
        return
    _require_pending_terminal_regular_group_size_budget(
        tuple(expected.size for expected in ticket.terminal_regular_targets),
        phase=ticket.phase,
    )
    for _pass in range(3):
        current_ticket = _read_pending_cleanup_ticket(
            home,
            ticket.path,
            expected_ticket_identity=ticket.snapshot.file_identity,
        )
        if current_ticket is None or not _pending_cleanup_ticket_matches(
            current_ticket,
            ticket,
        ):
            raise SyncError(f"pending cleanup ticket changed: {ticket.batch_root.name}")
        for expected in ticket.terminal_regular_targets:
            target = home / Path(*expected.target.parts)
            snapshot = _read_regular_file_snapshot_beneath(
                home,
                target,
                require_managed_access=True,
            )
            if (
                snapshot.parent_identity != expected.parent_identity
                or snapshot.file_identity != expected.file_identity
                or snapshot.sha256 != expected.sha256
                or snapshot.size != expected.size
                or snapshot.mode != expected.mode
                or snapshot.uid != expected.uid
                or snapshot.link_count != 1
            ):
                raise SyncError(
                    f"final managed regular file changed: {expected.target}"
                )
    current_ticket = _read_pending_cleanup_ticket(
        home,
        ticket.path,
        expected_ticket_identity=ticket.snapshot.file_identity,
    )
    if current_ticket is None or not _pending_cleanup_ticket_matches(
        current_ticket,
        ticket,
    ):
        raise SyncError(f"pending cleanup ticket changed: {ticket.batch_root.name}")


def _pending_relinquishment_actions(
    home: Path,
    batch: PendingLinkBatch,
) -> list[ReconcileAction]:
    return [
        ReconcileAction(
            action=record.action,
            target=home / Path(*record.target.parts),
            link_target="",
            kind=record.kind,
            planned_snapshot=record.planned_snapshot,
        )
        for record in batch.records
        if record.action == PENDING_RELINQUISH_FOREIGN_ACTION
    ]


def _finalize_rolled_back_pending_batch(
    home: Path,
    batch: PendingLinkBatch,
) -> None:
    _retire_pending_staging_cleanup_authority(home, batch)
    _verify_pending_link_phase(home, batch, "before")
    relinquishments = _pending_relinquishment_actions(home, batch)
    has_terminal_regular = bool(batch.terminal_regular_before)
    _verify_managed_state_link_claims(
        home,
        batch.state_before_value,
        relinquishments,
        pending_batch=batch,
    )
    if has_terminal_regular:
        _mark_pending_batch_rollback_cleanup_ready(home, batch)
    _clear_pending_link_pointer(home, batch, phase="before")
    if not has_terminal_regular:
        return
    if not _try_cleanup_finalized_pending_batch(home, batch):
        raise SyncError(
            "rolled-back pending regular-file evidence cleanup was deferred"
        )


def _recover_pending_link_transaction(
    home: Path,
    state: ManagedState,
    state_snapshot: ManagedStateFileSnapshot,
    *,
    dry_run: bool,
) -> tuple[ManagedState, ManagedStateFileSnapshot, bool]:
    if not dry_run:
        _recover_failed_move_isolation(home)
    batch = _load_pending_link_batch(home)
    if batch is None:
        return state, state_snapshot, False
    committed = _pending_commit_decision(home, batch)
    if dry_run:
        # Validate the pointer without mutation and let the caller report that
        # recovery must precede any requested new work.
        return state, state_snapshot, True
    _retire_pending_staging_cleanup_authority(home, batch)

    if committed:
        if (
            not _managed_state_snapshot_exact(state_snapshot, batch.state_after)
            or state != batch.state_after_value
        ):
            raise SyncError(
                "committed pending managed state is missing or changed; the "
                "transaction and evidence were retained"
            )
        _verify_committed_pending_link_records(home, batch)
        _mark_pending_batch_cleanup_ready(home, batch)
        _clear_pending_link_pointer(home, batch, phase="after")
        cleaned = _try_cleanup_finalized_pending_batch(home, batch)
        if batch.terminal_regular_after:
            if not cleaned:
                raise SyncError(
                    "committed pending regular-file evidence cleanup was deferred"
                )
        return state, state_snapshot, True

    state, state_snapshot = _rollback_pending_state_to_before(
        home,
        batch,
        state_snapshot,
    )
    legacy_active_entry_index: (
        _LegacyPendingRegularPublicationActiveEntryIndex | None
    ) = None
    if batch.metadata_version in {6, 7, 8, 9} and _batch_has_regular_records(batch):
        # The immutable batch metadata defines all legitimate hard-link aliases;
        # cache that authority once before any recovery mutation. Likewise, scan
        # each legacy active-entry parent once under one batch-wide budget.
        _pending_regular_alias_authority_index(home, batch)
        legacy_active_entry_index = (
            _build_legacy_pending_regular_publication_active_entry_index(home, batch)
        )
    for record in reversed(batch.records):
        if record.action == PENDING_RELINQUISH_FOREIGN_ACTION:
            _verify_pending_record_bound_foreign_relinquishment(
                home,
                record,
                phase="rollback",
            )
            continue
        producing = record.action in {
            "create",
            "replace",
            "quarantine-replace",
        }
        destructive = record.action in {
            "replace",
            "quarantine-replace",
            "remove",
            "quarantine-remove",
        }
        if record.has_regular_authority():
            if producing and record.is_regular():
                _recover_pending_regular_publication_cleanup(
                    home,
                    batch,
                    record,
                    "produced",
                    legacy_active_entry_index=legacy_active_entry_index,
                )
            if destructive and record.before_is_regular():
                _recover_pending_regular_publication_cleanup(
                    home,
                    batch,
                    record,
                    "before",
                    legacy_active_entry_index=legacy_active_entry_index,
                )
        target = home / Path(*record.target.parts)
        target_snapshot, target_exists = _pending_target_snapshot(home, target)
        produced_evidence = (
            _pending_record_evidence_snapshot(home, batch, record)
            if producing
            else None
        )
        before_evidence = (
            _pending_record_before_evidence_snapshot(home, batch, record)
            if destructive
            else None
        )
        if destructive:
            _pending_record_backup_snapshot(home, batch, record)
        if isinstance(produced_evidence, RegularFileSnapshot):
            target_has_produced_leaf = _regular_snapshot_leaf_matches(
                target_snapshot,
                produced_evidence,
            )
            target_is_produced = _regular_snapshot_matches(
                target_snapshot,
                record.planned_snapshot.parent_identity,
                produced_evidence,
                expected_link_count=produced_evidence.link_count,
            )
        elif isinstance(produced_evidence, SymlinkSnapshot):
            target_has_produced_leaf = _symlink_snapshot_leaf_matches(
                target_snapshot,
                produced_evidence.link_identity,
                produced_evidence.link_target,
            )
            target_is_produced = _symlink_snapshot_matches(
                target_snapshot,
                record.planned_snapshot.parent_identity,
                produced_evidence.link_identity,
                produced_evidence.link_target,
            )
        else:
            target_has_produced_leaf = False
            target_is_produced = False
        if isinstance(before_evidence, RegularFileSnapshot):
            target_is_before = _regular_snapshot_matches(
                target_snapshot,
                record.planned_snapshot.parent_identity,
                before_evidence,
                expected_link_count=before_evidence.link_count,
            )
        elif isinstance(before_evidence, SymlinkSnapshot):
            target_is_before = _symlink_snapshot_matches(
                target_snapshot,
                record.planned_snapshot.parent_identity,
                before_evidence.link_identity,
                before_evidence.link_target,
            )
        else:
            target_is_before = False
        if target_has_produced_leaf and not target_is_produced:
            raise SyncError(f"pending produced target parent changed: {record.target}")
        if target_is_produced:
            assert target_snapshot is not None
            assert produced_evidence is not None
            if isinstance(produced_evidence, RegularFileSnapshot):
                assert isinstance(target_snapshot, RegularFileSnapshot)
                _delete_pending_regular_publication_beneath(
                    home,
                    batch,
                    record,
                    target,
                    target_snapshot,
                    phase="produced",
                )
            else:
                assert isinstance(target_snapshot, SymlinkSnapshot)
                _remove_expected_symlink_beneath(
                    home,
                    target,
                    produced_evidence.link_target,
                    target_snapshot,
                )
            target_snapshot = None
            target_exists = False
        if destructive:
            assert before_evidence is not None
            if target_is_before:
                continue
            if target_exists:
                raise SyncError(
                    "pending rollback found a foreign target; evidence and pointer "
                    f"were retained: {record.target}"
                )
            _restore_pending_record_before(home, batch, record, before_evidence)
            continue
        if target_is_produced or not target_exists:
            continue
        if record.scope == "managed" and record.action == "create":
            if record.target in batch.state_before_value.links:
                raise SyncError(
                    "pending managed create absence changed during rollback: "
                    f"{record.target}"
                )
            # A genuinely new path was not owned by the before-state. Preserve a
            # foreign occupant without adopting it into managed state.
            continue
        if record.action == "retire-absent":
            raise SyncError(
                "pending retired absence found a foreign target; evidence and "
                f"pointer were retained: {record.target}"
            )
        raise SyncError(
            "pending current creation found a foreign target; evidence and pointer "
            f"were retained: {record.target}"
        )

    _finalize_rolled_back_pending_batch(home, batch)
    state, state_snapshot = _load_managed_state_with_snapshot(home)
    return state, state_snapshot, True


def _order_destructive_reconcile_actions(
    home: Path,
    actions: list[ReconcileAction],
    required_replacements: dict[Path, list[LinkEntry]],
) -> list[ReconcileAction]:
    producers = {
        action.target: action
        for action in actions
        if action.action in {"replace", "quarantine-replace"}
    }
    dependencies: dict[ReconcileAction, set[ReconcileAction]] = {
        action: set() for action in actions
    }
    order = {action: index for index, action in enumerate(actions)}
    for action in actions:
        for entry in required_replacements.get(action.target, []):
            replacement_target = _entry_target_path(home, entry)
            if replacement_target == action.target:
                if action.action not in {
                    "replace",
                    "quarantine-replace",
                } or action.link_target != _desired_link_target(home, entry):
                    raise SyncError(
                        "same-path replacement requires a matching replace action: "
                        f"{action.target}"
                    )
                continue
            producer = producers.get(replacement_target)
            if producer is not None:
                dependencies[action].add(producer)

    sorter = TopologicalSorter(dependencies)
    try:
        sorter.prepare()
    except CycleError as error:
        cycle_targets = (
            error.args[1]
            if len(error.args) > 1 and isinstance(error.args[1], list)
            else []
        )
        cycle = " -> ".join(str(action.target) for action in cycle_targets)
        detail = f": {cycle}" if cycle else ""
        raise SyncError(
            f"replacement action dependency cycle detected{detail}"
        ) from None

    ordered: list[ReconcileAction] = []
    while sorter.is_active():
        ready = sorted(sorter.get_ready(), key=order.__getitem__)
        ordered.extend(ready)
        sorter.done(*ready)
    return ordered


def _ordered_reconcile_actions(
    home: Path,
    actions: list[ReconcileAction],
    required_replacements: dict[Path, list[LinkEntry]] | None = None,
) -> list[ReconcileAction]:
    record_only_actions = [
        action
        for action in actions
        if action.action == PENDING_RELINQUISH_FOREIGN_ACTION
    ]
    create_actions = [action for action in actions if action.action == "create"]
    destructive_actions = _order_destructive_reconcile_actions(
        home,
        [
            action
            for action in actions
            if action.action
            in {"replace", "quarantine-replace", "remove", "quarantine-remove"}
        ],
        required_replacements or {},
    )
    ordered = record_only_actions + create_actions + destructive_actions
    if len(ordered) != len(actions):
        unknown = sorted(
            {action.action for action in actions}
            - {
                "create",
                "replace",
                "quarantine-replace",
                "remove",
                "quarantine-remove",
                PENDING_RELINQUISH_FOREIGN_ACTION,
            }
        )
        raise SyncError(f"unknown reconciliation action(s): {', '.join(unknown)}")
    return ordered


def _apply_reconcile_actions(
    home: Path,
    actions: list[ReconcileAction],
    *,
    dry_run: bool,
    required_replacements: dict[Path, list[LinkEntry]] | None = None,
    pending_batch: PendingLinkBatch | None = None,
    pending_scope: str | None = None,
    batch_root: Path | None = None,
    transaction: ReconcileTransaction | None = None,
) -> ReconcileTransaction | None:
    if any(action.action == PENDING_RELINQUISH_FOREIGN_ACTION for action in actions):
        raise SyncError(
            "foreign claim relinquishments must not enter filesystem reconciliation"
        )
    ordered_actions = _ordered_reconcile_actions(
        home,
        actions,
        required_replacements,
    )
    for action in ordered_actions:
        if (
            action.planned_snapshot is not None
            and _regular_snapshot_from_reconcile(action.planned_snapshot) is not None
            and action.materialization != "regular"
            and not _regular_to_symlink_reconcile_action_is_typed(action)
        ):
            raise SyncError(
                f"regular-file preimage has a symlink action: {action.target}"
            )

    if dry_run:
        if transaction is not None:
            raise SyncError("dry-run reconciliation cannot mutate a transaction")
        for action in ordered_actions:
            object_kind = (
                "regular file" if action.materialization == "regular" else "symlink"
            )
            if action.action.endswith("remove"):
                print(f"would {action.action} {object_kind} {action.target}")
            else:
                detail = (
                    ""
                    if action.materialization == "regular"
                    else f" -> {action.link_target}"
                )
                print(f"would {action.action} {object_kind} {action.target}{detail}")
        return None

    missing_snapshots = [
        str(action.target)
        for action in ordered_actions
        if action.planned_snapshot is None
    ]
    if missing_snapshots:
        raise SyncError(
            "reconciliation action has no planning snapshot: "
            + ", ".join(missing_snapshots)
        )

    pending_records: dict[PurePosixPath, PendingLinkRecord] = {}
    if pending_batch is not None:
        if pending_scope not in {"current", "managed"}:
            raise SyncError("pending reconciliation requires an explicit scope")
        if batch_root is not None and batch_root != pending_batch.batch_root:
            raise SyncError("reconciliation received conflicting quarantine batches")
        batch_root = pending_batch.batch_root
        expected_records = [
            record
            for record in pending_batch.records
            if record.scope == pending_scope
            and record.action
            not in {"retire-absent", PENDING_RELINQUISH_FOREIGN_ACTION}
        ]
        if len(expected_records) != len(ordered_actions):
            raise SyncError(f"pending {pending_scope} action count changed")
        pending_records = {record.target: record for record in expected_records}
        effective_actions: list[ReconcileAction] = []
        for record, action in zip(expected_records, ordered_actions):
            try:
                relative_target = PurePosixPath(*action.target.relative_to(home).parts)
            except ValueError as error:
                raise SyncError(
                    f"pending target is outside home: {action.target}"
                ) from error
            original_snapshot = action.planned_snapshot
            if record.planned_snapshot != original_snapshot:
                parent_refresh_is_valid = (
                    action.action == "create"
                    and original_snapshot is not None
                    and original_snapshot.parent_identity is None
                    and original_snapshot.link_identity is None
                    and original_snapshot.link_target is None
                    and bool(original_snapshot.missing_parent_parts)
                    and record.planned_snapshot.parent_identity is not None
                    and record.planned_snapshot.link_identity is None
                    and record.planned_snapshot.link_target is None
                    and record.planned_snapshot.ancestor_identity
                    == record.planned_snapshot.parent_identity
                    and not record.planned_snapshot.missing_parent_parts
                )
                original_regular = (
                    _regular_snapshot_from_reconcile(original_snapshot)
                    if original_snapshot is not None
                    else None
                )
                record_regular = _regular_snapshot_from_reconcile(
                    record.planned_snapshot
                )
                regular_evidence_refresh_is_valid = (
                    original_regular is not None
                    and record_regular is not None
                    and _regular_snapshot_matches(
                        record_regular,
                        original_regular.parent_identity,
                        original_regular,
                        expected_link_count=original_regular.link_count + 1,
                    )
                )
                if not (parent_refresh_is_valid or regular_evidence_refresh_is_valid):
                    raise SyncError(
                        f"pending {pending_scope} planning snapshot changed: "
                        f"{action.target}"
                    )
                action = replace(action, planned_snapshot=record.planned_snapshot)
            if (
                record.target != relative_target
                or record.action != action.action
                or record.kind != action.kind
                or record.planned_snapshot != action.planned_snapshot
                or record.materialization != action.materialization
                or record.removed_link_key != action.removed_link_key
                or record.link_target
                != (
                    action.link_target
                    if action.action in {"create", "replace", "quarantine-replace"}
                    else None
                )
            ):
                raise SyncError(
                    f"pending {pending_scope} action changed: {action.target}"
                )
            effective_actions.append(action)
        ordered_actions = effective_actions
    create_actions = [action for action in ordered_actions if action.action == "create"]
    destructive_actions = [
        action for action in ordered_actions if action.action != "create"
    ]
    if transaction is None:
        transaction = ReconcileTransaction(batch_root=batch_root, mutations=[])
    else:
        if transaction.mutations:
            raise SyncError("reconciliation transaction is not empty before apply")
        if (
            transaction.batch_root is not None
            and batch_root is not None
            and transaction.batch_root != batch_root
        ):
            raise SyncError("reconciliation transaction has a conflicting batch")
        if transaction.batch_root is None:
            transaction.batch_root = batch_root
    created_parent_identities: dict[Path, tuple[int, int]] = {}
    try:
        for action in create_actions:
            pending_record: PendingLinkRecord | None = None
            if pending_batch is not None:
                try:
                    relative_target = action.target.relative_to(home)
                except ValueError as error:
                    raise SyncError(
                        f"managed target is outside home: {action.target}"
                    ) from error
                pending_record = pending_records.get(
                    PurePosixPath(*relative_target.parts)
                )
                if pending_record is None:
                    raise SyncError(
                        f"pending create evidence is missing: {action.target}"
                    )
                if (
                    pending_record.link_target != action.link_target
                    or pending_record.kind != action.kind
                ):
                    raise SyncError(f"pending create evidence changed: {action.target}")
            if pending_record is None:
                if action.materialization == "regular":
                    if action.regular_source is None:
                        raise SyncError(
                            f"managed regular-file action has no source: {action.target}"
                        )
                    created_snapshot = _create_regular_file_beneath(
                        home,
                        action.regular_source,
                        action.target,
                        action.planned_snapshot,
                        created_parent_identities,
                    )
                else:
                    created_snapshot = _create_symlink_beneath(
                        home,
                        action.target,
                        action.link_target,
                        action.kind,
                        action.planned_snapshot,
                        created_parent_identities,
                    )
            else:
                assert pending_record.stage is not None
                stage = pending_batch.batch_root / Path(*pending_record.stage.parts)
                evidence_snapshot = _pending_record_evidence_snapshot(
                    home,
                    pending_batch,
                    pending_record,
                )
                assert action.planned_snapshot is not None
                if pending_record.is_regular():
                    assert isinstance(evidence_snapshot, RegularFileSnapshot)
                    stage_snapshot = _read_regular_file_snapshot_beneath(
                        home,
                        stage,
                        require_managed_access=False,
                    )
                    created_snapshot = _publish_regular_reconcile_hardlink_beneath(
                        home,
                        stage,
                        action.target,
                        stage_snapshot,
                        action.planned_snapshot,
                        created_parent_identities,
                        pending_batch=pending_batch,
                        pending_record=pending_record,
                    )
                else:
                    assert isinstance(evidence_snapshot, SymlinkSnapshot)
                    stage_snapshot = _read_symlink_snapshot_beneath(home, stage)
                    if (
                        stage_snapshot.link_identity != evidence_snapshot.link_identity
                        or stage_snapshot.link_target != evidence_snapshot.link_target
                    ):
                        raise SyncError(
                            f"pending create stage is not inode-bound: {action.target}"
                        )
                    created_snapshot = _publish_symlink_hardlink_beneath(
                        home,
                        stage,
                        action.target,
                        stage_snapshot,
                        action.planned_snapshot,
                        created_parent_identities,
                    )
            transaction.mutations.append(
                ReconcileMutation(
                    action=action,
                    created_snapshot=created_snapshot,
                )
            )
            _verify_created_reconcile_mutation(home, transaction.mutations[-1])
            if action.materialization == "regular":
                print(f"created regular file {action.target}")
            else:
                print(f"created symlink {action.target} -> {action.link_target}")
        if pending_batch is None:
            _verify_reconcile_action_targets(home, create_actions)
        else:
            _verify_reconcile_action_targets(
                home,
                create_actions,
                pending_batch=pending_batch,
            )

        if destructive_actions and transaction.batch_root is None:
            transaction.batch_root = _quarantine_batch_root(
                home,
                destructive_actions,
            )
        for action in destructive_actions:
            assert transaction.batch_root is not None
            _ensure_safe_target_parent(home, action.target)
            replacements = (required_replacements or {}).get(action.target, [])
            prior_replacements = [
                entry
                for entry in replacements
                if _entry_target_path(home, entry) != action.target
            ]
            if prior_replacements:
                _verify_required_replacement_targets(
                    home,
                    prior_replacements,
                    pending_batch=pending_batch,
                )
            try:
                relative_target = action.target.relative_to(home)
            except ValueError as error:
                raise SyncError(
                    f"quarantine target is outside home: {action.target}"
                ) from error
            pending_record = pending_records.get(PurePosixPath(*relative_target.parts))
            if pending_batch is not None:
                if pending_record is None or pending_record.backup is None:
                    raise SyncError(
                        f"pending destructive evidence is missing: {action.target}"
                    )
                _pending_record_before_evidence_snapshot(
                    home,
                    pending_batch,
                    pending_record,
                )
                backup = pending_batch.batch_root / Path(*pending_record.backup.parts)
            else:
                backup = transaction.batch_root / "links" / relative_target
            backup_parent_fd = _open_or_create_directory_beneath(
                home,
                backup.parent,
            )
            backup_parent_identity = _directory_identity(backup_parent_fd)
            _close_fd_quietly(backup_parent_fd)
            assert action.planned_snapshot is not None
            _atomic_move_beneath_home(
                home,
                action.target,
                backup,
                action.planned_snapshot,
                backup_parent_identity,
            )
            mutation = ReconcileMutation(action=action, backup=backup)
            transaction.mutations.append(mutation)
            _verify_reconcile_backup(home, action, backup)
            if prior_replacements:
                _verify_required_replacement_targets(
                    home,
                    prior_replacements,
                    pending_batch=pending_batch,
                )
            object_kind = (
                "regular file" if action.materialization == "regular" else "symlink"
            )
            print(f"quarantined {object_kind} {action.target} -> {backup}")

            if action.action in {"replace", "quarantine-replace"}:
                replacement_plan = ReconcileTargetSnapshot(
                    parent_identity=action.planned_snapshot.parent_identity,
                    ancestor_identity=action.planned_snapshot.parent_identity,
                )
                if pending_record is None:
                    if action.materialization == "regular":
                        if action.regular_source is None:
                            raise SyncError(
                                "managed regular-file action has no source: "
                                f"{action.target}"
                            )
                        mutation.created_snapshot = _create_regular_file_beneath(
                            home,
                            action.regular_source,
                            action.target,
                            replacement_plan,
                            created_parent_identities,
                        )
                    else:
                        mutation.created_snapshot = _create_symlink_beneath(
                            home,
                            action.target,
                            action.link_target,
                            action.kind,
                            replacement_plan,
                            created_parent_identities,
                        )
                else:
                    assert pending_record.stage is not None
                    stage = pending_batch.batch_root / Path(*pending_record.stage.parts)
                    evidence_snapshot = _pending_record_evidence_snapshot(
                        home,
                        pending_batch,
                        pending_record,
                    )
                    if pending_record.is_regular():
                        assert isinstance(evidence_snapshot, RegularFileSnapshot)
                        stage_snapshot = _read_regular_file_snapshot_beneath(
                            home,
                            stage,
                            require_managed_access=False,
                        )
                        mutation.created_snapshot = (
                            _publish_regular_reconcile_hardlink_beneath(
                                home,
                                stage,
                                action.target,
                                stage_snapshot,
                                replacement_plan,
                                created_parent_identities,
                                pending_batch=pending_batch,
                                pending_record=pending_record,
                            )
                        )
                    else:
                        assert isinstance(evidence_snapshot, SymlinkSnapshot)
                        stage_snapshot = _read_symlink_snapshot_beneath(home, stage)
                        if (
                            stage_snapshot.link_identity
                            != evidence_snapshot.link_identity
                            or stage_snapshot.link_target
                            != evidence_snapshot.link_target
                        ):
                            raise SyncError(
                                f"pending replacement stage changed: {action.target}"
                            )
                        mutation.created_snapshot = _publish_symlink_hardlink_beneath(
                            home,
                            stage,
                            action.target,
                            stage_snapshot,
                            replacement_plan,
                            created_parent_identities,
                        )
                _verify_created_reconcile_mutation(home, mutation)
                if pending_batch is None:
                    _verify_reconcile_action_targets(home, [action])
                else:
                    _verify_reconcile_action_targets(
                        home,
                        [action],
                        pending_batch=pending_batch,
                    )
                if replacements:
                    _verify_required_replacement_targets(
                        home,
                        replacements,
                        pending_batch=pending_batch,
                    )
                if action.materialization == "regular":
                    print(f"replaced regular file {action.target}")
                else:
                    print(f"replaced symlink {action.target} -> {action.link_target}")
            else:
                print(f"removed stale {object_kind} {action.target}")
    except BaseException as error:
        try:
            _rollback_reconcile_transaction(
                home,
                transaction,
                pending_batch=pending_batch,
            )
        except SyncError as rollback_error:
            raise SyncError(
                "reconciliation failed and link rollback was incomplete: "
                f"{rollback_error}"
            ) from error
        transaction.mutations.clear()
        raise _SafeReconcileApplyError(f"reconciliation failed: {error}") from error

    return transaction


def _verify_reconcile_backup(
    home: Path,
    action: ReconcileAction,
    backup: Path,
) -> None:
    if action.planned_snapshot is None:
        raise SyncError(f"destructive action has no expected target: {action.target}")
    planned_regular = _regular_snapshot_from_reconcile(action.planned_snapshot)
    if planned_regular is not None:
        try:
            backup_snapshot = _read_regular_file_snapshot_beneath(
                home,
                backup,
                require_managed_access=False,
            )
        except (FileNotFoundError, OSError, SyncError) as error:
            raise SyncError(f"reconciliation backup is missing: {backup}") from error
        if (
            not _regular_snapshot_leaf_matches(
                backup_snapshot,
                planned_regular,
            )
            or backup_snapshot.link_count != planned_regular.link_count
        ):
            raise SyncError(f"target changed after preflight: {action.target}")
        return
    if action.expected_link_target is None:
        raise SyncError(f"destructive action has no expected symlink: {action.target}")
    if (
        action.planned_snapshot.link_identity is None
        or action.planned_snapshot.link_target is None
    ):
        raise SyncError(f"destructive action planned an absent target: {action.target}")
    try:
        backup_snapshot = _read_symlink_snapshot_beneath(home, backup)
    except (FileNotFoundError, OSError, SyncError) as error:
        raise SyncError(f"reconciliation backup is missing: {backup}") from error
    if (
        backup_snapshot.link_identity != action.planned_snapshot.link_identity
        or backup_snapshot.link_target != action.planned_snapshot.link_target
        or backup_snapshot.link_target != action.expected_link_target
    ):
        raise SyncError(f"target changed after preflight: {action.target}")


def _rollback_reconcile_transaction(
    home: Path,
    transaction: ReconcileTransaction | None,
    *,
    pending_batch: PendingLinkBatch | None = None,
) -> None:
    if transaction is None:
        return
    errors: list[str] = []
    for mutation in reversed(transaction.mutations):
        action = mutation.action
        try:
            if _path_exists_or_is_link(action.target):
                if mutation.created_snapshot is None:
                    raise SyncError(
                        f"changed target was left in place during rollback: {action.target}"
                    )
                if isinstance(mutation.created_snapshot, RegularFileSnapshot):
                    if transaction.batch_root is None:
                        _remove_expected_regular_file_beneath(
                            home,
                            action.target,
                            mutation.created_snapshot,
                        )
                    elif pending_batch is None:
                        _delete_exact_regular_publication_beneath(
                            home,
                            action.target,
                            mutation.created_snapshot,
                        )
                    else:
                        # A pending regular publication already has exact,
                        # durable stage and evidence aliases. Quarantining the
                        # target would create an unrecorded third alias and
                        # defeat exact-alias recovery. Delete this one proven
                        # publication leaf atomically instead.
                        relative_target = PurePosixPath(
                            *action.target.relative_to(home).parts
                        )
                        record = next(
                            (
                                candidate
                                for candidate in pending_batch.records
                                if candidate.target == relative_target
                            ),
                            None,
                        )
                        if record is None:
                            raise SyncError(
                                "pending regular rollback record is missing"
                            )
                        _delete_pending_regular_publication_beneath(
                            home,
                            pending_batch,
                            record,
                            action.target,
                            mutation.created_snapshot,
                            phase="produced",
                        )
                else:
                    _remove_expected_symlink_beneath(
                        home,
                        action.target,
                        action.link_target,
                        mutation.created_snapshot,
                    )
            if mutation.backup is None:
                continue

            backup = mutation.backup
            try:
                _verify_reconcile_backup(home, action, backup)
            except SyncError as backup_error:
                raise SyncError(
                    "reconciliation backup changed and was retained in quarantine: "
                    f"{action.target} -> {backup}"
                ) from backup_error
            restore_snapshot = _capture_reconcile_target_snapshot(
                home,
                action.target,
            )
            if restore_snapshot.link_identity is not None:
                raise SyncError(
                    f"refusing to overwrite changed target during rollback: {action.target}"
                )
            if (
                action.planned_snapshot is None
                or restore_snapshot.parent_identity
                != action.planned_snapshot.parent_identity
            ):
                raise SyncError(
                    "refusing to restore through changed target parent during "
                    f"rollback: {action.target.parent}"
                )
            planned_regular = _regular_snapshot_from_reconcile(action.planned_snapshot)
            backup_snapshot = (
                _read_regular_file_snapshot_beneath(
                    home,
                    backup,
                    require_managed_access=False,
                )
                if planned_regular is not None
                else _read_symlink_snapshot_beneath(home, backup)
            )
            _atomic_move_beneath_home(
                home,
                backup,
                action.target,
                ReconcileTargetSnapshot(
                    parent_identity=backup_snapshot.parent_identity,
                    link_identity=action.planned_snapshot.link_identity,
                    link_target=action.planned_snapshot.link_target,
                    ancestor_identity=backup_snapshot.parent_identity,
                    regular_sha256=action.planned_snapshot.regular_sha256,
                    regular_size=action.planned_snapshot.regular_size,
                    regular_mode=action.planned_snapshot.regular_mode,
                    regular_uid=action.planned_snapshot.regular_uid,
                    regular_gid=action.planned_snapshot.regular_gid,
                    regular_link_count=action.planned_snapshot.regular_link_count,
                ),
                action.planned_snapshot.parent_identity,
            )
            if planned_regular is not None:
                restored_snapshot = _read_regular_file_snapshot_beneath(
                    home,
                    action.target,
                    require_managed_access=True,
                )
                if not _regular_snapshot_matches(
                    restored_snapshot,
                    action.planned_snapshot.parent_identity,
                    planned_regular,
                    expected_link_count=planned_regular.link_count,
                ):
                    raise SyncError(
                        "restored regular file changed during rollback: "
                        f"{action.target}"
                    )
            else:
                restored_snapshot = _read_symlink_snapshot_beneath(home, action.target)
                if (
                    restored_snapshot.parent_identity
                    != action.planned_snapshot.parent_identity
                    or restored_snapshot.link_identity
                    != action.planned_snapshot.link_identity
                    or restored_snapshot.link_target
                    != action.planned_snapshot.link_target
                ):
                    raise SyncError(
                        f"restored symlink changed during rollback: {action.target}"
                    )
        except (OSError, SyncError) as error:
            errors.append(f"{action.target}: {error}")

    if errors:
        raise SyncError("; ".join(errors))


def _commit_reconcile_transaction(
    transaction: ReconcileTransaction | None,
) -> None:
    """Leave evidence cleanup to the committed pending-batch ticket flow."""


def _verify_created_reconcile_mutation(
    home: Path,
    mutation: ReconcileMutation,
) -> None:
    if mutation.created_snapshot is None:
        raise SyncError(
            f"reconciliation mutation has no created snapshot: {mutation.action.target}"
        )
    try:
        actual_snapshot = (
            _read_regular_file_snapshot_beneath(
                home,
                mutation.action.target,
                require_managed_access=False,
            )
            if isinstance(mutation.created_snapshot, RegularFileSnapshot)
            else _read_symlink_snapshot_beneath(
                home,
                mutation.action.target,
            )
        )
    except (FileNotFoundError, OSError, SyncError) as error:
        raise SyncError(
            f"created symlink changed during reconciliation: {mutation.action.target}"
        ) from error
    created_matches = (
        _regular_snapshot_matches(
            actual_snapshot,
            mutation.created_snapshot.parent_identity,
            mutation.created_snapshot,
            expected_link_count=mutation.created_snapshot.link_count,
        )
        if isinstance(mutation.created_snapshot, RegularFileSnapshot)
        else actual_snapshot == mutation.created_snapshot
    )
    if not created_matches:
        raise SyncError(
            f"created symlink changed during reconciliation: {mutation.action.target}"
        )
    if isinstance(actual_snapshot, RegularFileSnapshot) and (
        actual_snapshot.mode != 0o600 or actual_snapshot.uid != os.geteuid()
    ):
        raise SyncError(
            f"created regular-file access policy changed: {mutation.action.target}"
        )


def _verify_reconcile_action_targets(
    home: Path,
    actions: list[ReconcileAction],
    *,
    pending_batch: PendingLinkBatch | None = None,
) -> None:
    for action in actions:
        if action.materialization == "regular":
            if action.regular_source is None:
                raise SyncError(
                    f"managed regular-file action has no source: {action.target}"
                )
            try:
                actual = _read_regular_file_snapshot_beneath(
                    home,
                    action.target,
                    require_managed_access=False,
                )
            except (FileNotFoundError, OSError, SyncError) as error:
                raise SyncError(
                    f"reconciled regular-file verification failed: {action.target}"
                ) from error
            try:
                _verify_pending_regular_aliases(
                    home,
                    pending_batch,
                    action.target,
                    actual,
                )
            except SyncError as error:
                raise SyncError(
                    f"reconciled regular-file verification failed: {action.target}"
                ) from error
            if (
                actual.sha256 != _regular_source_sha256(home, action.regular_source)
                or actual.mode != 0o600
                or actual.uid != os.geteuid()
            ):
                raise SyncError(
                    f"reconciled regular-file verification failed: {action.target}"
                )
            continue
        try:
            actual_target = _read_symlink_beneath(home, action.target)
        except (FileNotFoundError, OSError, SyncError) as error:
            raise SyncError(
                f"reconciled symlink verification failed: {action.target}"
            ) from error
        if actual_target != action.link_target:
            raise SyncError(f"reconciled symlink verification failed: {action.target}")


def _verify_required_replacement_targets(
    home: Path,
    required_replacements: list[LinkEntry],
    *,
    pending_batch: PendingLinkBatch | None = None,
) -> None:
    for entry in required_replacements:
        target = _entry_target_path(home, entry)
        if _entry_materializes_regular_file(entry):
            try:
                snapshot = _read_regular_file_snapshot_beneath(
                    home,
                    target,
                    require_managed_access=False,
                )
                source = _entry_regular_source_path(home, entry)
            except (FileNotFoundError, OSError, SyncError) as error:
                raise SyncError(
                    f"active replacement target changed before removal: {target}"
                ) from error
            try:
                _verify_pending_regular_aliases(
                    home,
                    pending_batch,
                    target,
                    snapshot,
                )
            except SyncError as error:
                raise SyncError(
                    f"active replacement target changed before removal: {target}"
                ) from error
            if (
                snapshot.sha256 != _regular_source_sha256(home, source)
                or snapshot.mode != 0o600
                or snapshot.uid != os.geteuid()
            ):
                raise SyncError(
                    f"active replacement target changed before removal: {target}"
                )
            continue
        expected = _desired_link_target(home, entry)
        try:
            actual = _read_symlink_beneath(home, target)
        except (FileNotFoundError, OSError, SyncError) as error:
            raise SyncError(
                f"active replacement target changed before removal: {target}"
            ) from error
        if actual != expected:
            raise SyncError(
                f"active replacement target changed before removal: {target}"
            )


def _verify_desired_entries(
    home: Path,
    desired_entries: list[LinkEntry],
    *,
    pending_batch: PendingLinkBatch | None = None,
) -> None:
    issues: list[str] = []
    for entry in desired_entries:
        target = _entry_target_path(home, entry)
        if _entry_materializes_regular_file(entry):
            try:
                regular = _read_regular_file_snapshot_beneath(
                    home,
                    target,
                    require_managed_access=False,
                )
                _verify_pending_regular_aliases(
                    home,
                    pending_batch,
                    target,
                    regular,
                )
                source = _entry_regular_source_path(home, entry)
                if (
                    regular.sha256 == _regular_source_sha256(home, source)
                    and regular.mode == 0o600
                    and regular.uid == os.geteuid()
                ):
                    continue
            except (FileNotFoundError, OSError, SyncError):
                pass
        else:
            desired = _desired_link_target(home, entry)
            actual = _read_optional_symlink_target_beneath(home, target)
            if actual == desired:
                continue
        if _is_optional_desired_entry(entry):
            continue
        if _entry_materializes_regular_file(entry):
            issues.append(f"managed regular file drift: {target}")
        elif actual is None:
            issues.append(f"missing managed symlink: {target}")
        else:
            issues.append(f"managed symlink drift: {target}")
    if issues:
        for issue in issues:
            print(f"sync issue: {issue}")
        raise SyncError(f"managed link verification failed with {len(issues)} issue(s)")


def _committed_state(
    home: Path,
    desired_entries: list[LinkEntry],
    owner_shas: dict[str, str],
    managed_targets: set[PurePosixPath] | None = None,
    *,
    pending_batch: PendingLinkBatch | None = None,
) -> ManagedState:
    links: dict[PurePosixPath, ManagedLinkRecord] = {}
    for entry in desired_entries:
        sha = owner_shas.get(entry.owner)
        if sha is None:
            raise SyncError(f"committed release is missing for owner {entry.owner}")
        if managed_targets is not None and entry.target not in managed_targets:
            continue
        target = _entry_target_path(home, entry)
        desired = _desired_link_target(home, entry)
        if _entry_materializes_regular_file(entry):
            regular_matches = False
            try:
                regular = _read_regular_file_snapshot_beneath(
                    home,
                    target,
                    require_managed_access=False,
                )
                _verify_pending_regular_aliases(
                    home,
                    pending_batch,
                    target,
                    regular,
                )
                regular_matches = (
                    regular.sha256
                    == _regular_source_sha256(
                        home,
                        _entry_regular_source_path(
                            home,
                            entry,
                            owner_shas,
                        ),
                    )
                    and regular.mode == 0o600
                    and regular.uid == os.geteuid()
                )
            except (FileNotFoundError, OSError, SyncError):
                regular_matches = False
            if not regular_matches:
                if _is_optional_desired_entry(entry):
                    continue
                raise SyncError(
                    f"mandatory desired regular file drifted before state commit: {target}"
                )
        else:
            actual = _read_optional_symlink_target_beneath(home, target)
            if actual != desired:
                if _is_optional_desired_entry(entry):
                    continue
                issue = "missing" if actual is None else "drifted"
                raise SyncError(
                    f"mandatory desired link {issue} before state commit: {target}"
                )
        links[entry.target] = ManagedLinkRecord(
            source=entry.source,
            target=entry.target,
            kind=entry.kind,
            owner=entry.owner,
            link_target=desired,
            release_sha=sha,
        )
    return ManagedState(owners=dict(owner_shas), links=links)


def _planned_committed_state(
    home: Path,
    desired_entries: list[LinkEntry],
    owner_shas: dict[str, str],
    managed_targets: set[PurePosixPath],
) -> ManagedState:
    links: dict[PurePosixPath, ManagedLinkRecord] = {}
    for entry in desired_entries:
        if entry.target not in managed_targets:
            continue
        sha = owner_shas.get(entry.owner)
        if sha is None:
            raise SyncError(f"planned release is missing for owner {entry.owner}")
        links[entry.target] = ManagedLinkRecord(
            source=entry.source,
            target=entry.target,
            kind=entry.kind,
            owner=entry.owner,
            link_target=_desired_link_target(home, entry),
            release_sha=_validate_release_sha(sha),
        )
    return ManagedState(owners=dict(owner_shas), links=links)


def _verify_published_state_matches_desired(
    home: Path,
    desired_entries: list[LinkEntry],
    expected_state: ManagedState,
) -> None:
    published_state = _load_managed_state(home)
    if published_state != expected_state:
        raise SyncError("managed link state changed after publication")
    observed_state = _committed_state(
        home,
        desired_entries,
        expected_state.owners,
        set(expected_state.links),
    )
    if observed_state != published_state:
        raise SyncError(
            "desired links no longer match managed link state after publication"
        )


def _verify_published_state_transaction(
    home: Path,
    transaction: ManagedStateFileTransaction | None,
) -> None:
    if (
        transaction is None
        or not transaction.published
        or transaction.state_parent_identity is None
        or transaction.published_identity is None
    ):
        raise SyncError("managed state publication is not bound to its transaction")
    if not _canonical_managed_state_matches(
        home,
        _state_path(home),
        transaction.after,
        transaction.state_parent_identity,
        transaction.published_identity,
    ):
        raise SyncError("published managed state changed after release validation")


def _capture_managed_state_link_snapshots(
    home: Path,
    state: ManagedState,
) -> dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot]:
    snapshots: dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot] = {}
    for relative_target, record in sorted(
        state.links.items(),
        key=lambda item: item[0].as_posix(),
    ):
        target = home / Path(*relative_target.parts)
        if _record_materializes_regular_file(record):
            try:
                snapshot = _read_regular_file_snapshot_beneath(
                    home,
                    target,
                    require_managed_access=True,
                )
            except (FileNotFoundError, OSError, SyncError):
                continue
            if snapshot.sha256 == _regular_source_sha256(
                home, _record_regular_source_path(home, record)
            ):
                snapshots[relative_target] = snapshot
        else:
            snapshot = _read_optional_symlink_snapshot_beneath(home, target)
            if snapshot is not None and snapshot.link_target == record.link_target:
                snapshots[relative_target] = snapshot
    return snapshots


def _created_reconcile_link_snapshots(
    home: Path,
    transaction: ReconcileTransaction | None,
) -> dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot]:
    snapshots: dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot] = {}
    if transaction is None:
        return snapshots
    for mutation in transaction.mutations:
        if mutation.created_snapshot is None:
            continue
        try:
            relative_target = mutation.action.target.relative_to(home)
        except ValueError as error:
            raise SyncError(
                f"managed target is outside home: {mutation.action.target}"
            ) from error
        key = PurePosixPath(*relative_target.parts)
        if key in snapshots:
            raise SyncError(f"duplicate created managed-link snapshot: {key}")
        snapshots[key] = mutation.created_snapshot
    return snapshots


def _trusted_managed_link_snapshots_for_state(
    home: Path,
    state: ManagedState,
    baseline_snapshots: dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot],
    transaction: ReconcileTransaction | None,
) -> dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot]:
    created_snapshots = _created_reconcile_link_snapshots(home, transaction)
    snapshots: dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot] = {}
    for relative_target, record in sorted(
        state.links.items(),
        key=lambda item: item[0].as_posix(),
    ):
        snapshot = created_snapshots.get(relative_target)
        if snapshot is None:
            snapshot = baseline_snapshots.get(relative_target)
        if snapshot is None:
            raise SyncError(
                f"managed link has no trusted identity snapshot: {relative_target}"
            )
        target = home / Path(*relative_target.parts)
        try:
            if _record_materializes_regular_file(record):
                if not isinstance(snapshot, RegularFileSnapshot):
                    raise SyncError(f"managed target type changed: {relative_target}")
                current_snapshot = _read_regular_file_snapshot_beneath(
                    home,
                    target,
                    require_managed_access=False,
                )
            else:
                if not isinstance(snapshot, SymlinkSnapshot):
                    raise SyncError(f"managed target type changed: {relative_target}")
                if snapshot.link_target != record.link_target:
                    raise SyncError(
                        "managed link target changed before publication: "
                        f"{relative_target}"
                    )
                current_snapshot = _read_symlink_snapshot_beneath(home, target)
        except (FileNotFoundError, OSError, SyncError) as error:
            raise SyncError(
                f"managed link changed before publication: {relative_target}"
            ) from error
        snapshot_matches = (
            _regular_snapshot_matches(
                current_snapshot,
                snapshot.parent_identity,
                snapshot,
                expected_link_count=snapshot.link_count,
            )
            if isinstance(snapshot, RegularFileSnapshot)
            else current_snapshot == snapshot
        )
        if not snapshot_matches:
            raise SyncError(
                f"managed link changed before publication: {relative_target}"
            )
        snapshots[relative_target] = snapshot
    return snapshots


def _verify_managed_link_snapshots(
    home: Path,
    state: ManagedState,
    snapshots: dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot],
) -> None:
    if set(snapshots) != set(state.links):
        raise SyncError("managed link snapshot targets changed after publication")
    for relative_target, record in sorted(
        state.links.items(),
        key=lambda item: item[0].as_posix(),
    ):
        expected_snapshot = snapshots[relative_target]
        target = home / Path(*relative_target.parts)
        try:
            if _record_materializes_regular_file(record):
                if not isinstance(expected_snapshot, RegularFileSnapshot):
                    raise SyncError(f"managed target type changed: {relative_target}")
                current_snapshot = _read_regular_file_snapshot_beneath(
                    home,
                    target,
                    require_managed_access=False,
                )
            else:
                if not isinstance(expected_snapshot, SymlinkSnapshot):
                    raise SyncError(f"managed target type changed: {relative_target}")
                if expected_snapshot.link_target != record.link_target:
                    raise SyncError(
                        "managed link target changed after publication: "
                        f"{relative_target}"
                    )
                current_snapshot = _read_symlink_snapshot_beneath(home, target)
        except (FileNotFoundError, OSError, SyncError) as error:
            raise SyncError(
                f"managed link identity changed after release validation: "
                f"{relative_target}"
            ) from error
        snapshot_matches = (
            _regular_snapshot_matches(
                current_snapshot,
                expected_snapshot.parent_identity,
                expected_snapshot,
                expected_link_count=expected_snapshot.link_count,
            )
            if isinstance(expected_snapshot, RegularFileSnapshot)
            else current_snapshot == expected_snapshot
        )
        if not snapshot_matches:
            raise SyncError(
                f"managed link identity changed after release validation: "
                f"{relative_target}"
            )


def _verify_published_transaction_matches_desired(
    home: Path,
    desired_entries: list[LinkEntry],
    expected_state: ManagedState,
    transaction: ManagedStateFileTransaction | None,
    managed_link_snapshots: dict[PurePosixPath, SymlinkSnapshot | RegularFileSnapshot],
) -> None:
    _verify_published_state_transaction(home, transaction)
    _verify_published_state_matches_desired(
        home,
        desired_entries,
        expected_state,
    )
    _verify_desired_entries(home, desired_entries)
    _verify_managed_link_snapshots(
        home,
        expected_state,
        managed_link_snapshots,
    )
    _verify_published_state_transaction(home, transaction)


def _managed_targets_after_reconciliation(
    home: Path,
    state: ManagedState,
    actions: list[ReconcileAction],
) -> set[PurePosixPath]:
    managed_targets = set(state.links)
    for action in actions:
        try:
            relative_target = action.target.relative_to(home)
        except ValueError as error:
            raise SyncError(
                f"managed target is outside home: {action.target}"
            ) from error
        if not relative_target.parts:
            raise SyncError(f"managed target must not be sync home: {action.target}")
        target = PurePosixPath(*relative_target.parts)
        if action.action == PENDING_RELINQUISH_FOREIGN_ACTION:
            managed_targets.discard(target)
            continue
        if action.action not in {"create", "replace", "quarantine-replace"}:
            continue
        managed_targets.add(target)
    return managed_targets


def plan_link_actions(
    home: Path,
    entries: list[LinkEntry],
    *,
    public_entries: list[LinkEntry] | None = None,
    pending_public_removals: set[Path] | None = None,
) -> list[LinkAction]:
    actions: list[LinkAction] = []
    pending_public_removals = pending_public_removals or set()
    entry_owners = {entry.owner for entry in entries}
    public_by_target = (
        _entries_by_target(
            public_entries
            if public_entries is not None
            else current_release_entries(home, PUBLIC_OWNER)
        )
        if any(owner != PUBLIC_OWNER for owner in entry_owners)
        else {}
    )
    for entry in entries:
        target = _entry_target_path(home, entry)
        desired = _desired_link_target(home, entry)
        regular_source = (
            _entry_regular_source_path(home, entry)
            if _entry_materializes_regular_file(entry)
            else None
        )
        materialization = "regular" if regular_source is not None else "symlink"
        parent = target.parent
        public_entry = public_by_target.get(entry.target)
        if entry.owner != PUBLIC_OWNER:
            if (
                public_entry is not None
                and not entry.override
                and entry.target not in OPTIONAL_PUBLIC_TARGETS
            ):
                raise SyncError(
                    f"target {target} exists in public manifest; "
                    f"manifest owner {entry.owner} must declare override=true"
                )
            if (
                public_entry is None
                and entry.override
                and entry.target not in OPTIONAL_PUBLIC_TARGETS
            ):
                raise SyncError(f"override target has no public base target: {target}")
        if _path_exists_or_is_link(parent) and not parent.is_dir():
            raise SyncError(f"link parent exists but is not a directory: {parent}")
        if _path_exists_or_is_link(target):
            if not target.is_symlink():
                if regular_source is not None and target.is_file():
                    snapshot = _read_regular_file_snapshot_beneath(
                        home,
                        target,
                        require_managed_access=True,
                    )
                    if snapshot.sha256 == _regular_source_sha256(home, regular_source):
                        continue
                    raise SyncError(
                        f"refusing to replace modified managed regular file: {target}"
                    )
                if (
                    entry.owner == PUBLIC_OWNER
                    and entry.target in OPTIONAL_PUBLIC_TARGETS
                ):
                    continue
                raise SyncError(f"refusing to replace non-symlink target: {target}")
            existing = os.readlink(target)
            if existing == desired and regular_source is None:
                continue
            existing_owner = _link_managed_owner(home, target, entry_owners)
            if existing_owner is None:
                if (
                    entry.owner == PUBLIC_OWNER
                    and entry.target in OPTIONAL_PUBLIC_TARGETS
                ):
                    continue
                raise SyncError(
                    f"refusing to replace unmanaged symlink target: {target}"
                )
            if existing_owner != entry.owner:
                if entry.owner == PUBLIC_OWNER:
                    continue
                if (
                    existing_owner == PUBLIC_OWNER
                    and public_entry is None
                    and target in pending_public_removals
                ):
                    actions.append(LinkAction("replace", target, desired, entry.kind))
                    continue
                if existing_owner != PUBLIC_OWNER or (
                    not entry.override and entry.target not in OPTIONAL_PUBLIC_TARGETS
                ):
                    raise SyncError(
                        f"target {target} is managed by {existing_owner}; "
                        f"manifest owner {entry.owner} must declare override=true"
                    )
            actions.append(
                LinkAction(
                    "replace",
                    target,
                    desired,
                    entry.kind,
                    materialization=materialization,
                    regular_source=regular_source,
                )
            )
        else:
            actions.append(
                LinkAction(
                    "create",
                    target,
                    desired,
                    entry.kind,
                    materialization=materialization,
                    regular_source=regular_source,
                )
            )
    return actions


def apply_link_actions(actions: list[LinkAction], *, dry_run: bool) -> None:
    for action in actions:
        if dry_run:
            if action.action == "remove":
                print(f"would remove stale symlink {action.target}")
            else:
                print(
                    f"would {action.action} symlink {action.target} -> {action.link_target}"
                )
            continue
        if action.action == "remove":
            if action.target.is_symlink():
                action.target.unlink()
                print(f"removed stale symlink {action.target}")
            continue
        action.target.parent.mkdir(parents=True, exist_ok=True)
        if action.target.is_symlink():
            action.target.unlink()
        if action.materialization == "regular":
            if action.regular_source is None:
                raise SyncError(
                    f"managed regular-file action has no source: {action.target}"
                )
            payload = action.regular_source.read_bytes()
            flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            fd = os.open(action.target, flags, 0o600)
            try:
                os.fchmod(fd, 0o600)
                with os.fdopen(fd, "wb", closefd=True) as file:
                    fd = -1
                    file.write(payload)
                    file.flush()
                    os.fsync(file.fileno())
            finally:
                if fd >= 0:
                    _close_fd_quietly(fd)
            print(f"{action.action}d regular file {action.target}")
            continue
        action.target.symlink_to(
            action.link_target,
            target_is_directory=action.kind in {"directory", "skill"},
        )
        print(f"{action.action}d symlink {action.target} -> {action.link_target}")


def validate_release_tree(release_root: Path) -> list[LinkEntry]:
    return load_manifest(release_root)


def current_release_entries(home: Path, owner: str = PUBLIC_OWNER) -> list[LinkEntry]:
    sha = _current_sha(home, owner)
    if sha is None:
        return []
    return _current_manifest_data(home, owner).entries


def plan_stale_link_removals(
    home: Path,
    previous_entries: list[LinkEntry],
    next_entries: list[LinkEntry],
    *,
    public_entries: list[LinkEntry] | None = None,
) -> list[LinkAction]:
    next_targets = {entry.target for entry in next_entries}
    public_by_target = _entries_by_target(
        public_entries
        if public_entries is not None
        else current_release_entries(home, PUBLIC_OWNER)
    )
    removals: list[LinkAction] = []
    for entry in previous_entries:
        if entry.target in next_targets:
            continue
        target = _entry_target_path(home, entry)
        public_entry = public_by_target.get(entry.target)
        if entry.owner != PUBLIC_OWNER and public_entry is not None:
            if not _path_exists_or_is_link(target) or (
                target.is_symlink()
                and os.readlink(target) == _desired_link_target(home, entry)
            ):
                removals.append(
                    LinkAction(
                        "restore",
                        target,
                        _desired_link_target(home, public_entry),
                        public_entry.kind,
                    )
                )
            continue
        if target.is_symlink() and os.readlink(target) == _desired_link_target(
            home, entry
        ):
            removals.append(LinkAction("remove", target, "", entry.kind))
    return removals


def _known_manifest_target_parents(
    home: Path,
    entries: list[LinkEntry],
    owner: str | None = None,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> set[Path]:
    parents = {home, home / "agents", home / "bin", home / "skills"}
    parents.update(_entry_target_path(home, entry).parent for entry in entries)
    manifest_owner = (
        _validate_owner(owner) if owner is not None else _entries_owner(entries)
    )
    releases_root = _releases_root(home, manifest_owner)
    if not _ensure_safe_internal_directory(
        home,
        releases_root,
        create=False,
        allow_missing=True,
    ):
        return parents
    for release_dir in releases_root.iterdir():
        if RELEASE_DIR_RE.fullmatch(release_dir.name) is None:
            continue
        mode = os.lstat(release_dir).st_mode
        if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
            raise SyncError(f"refusing unsafe release directory: {release_dir}")
        try:
            release_entries = _load_installed_manifest_data(
                home,
                manifest_owner,
                release_dir.name,
                manifest_cache=manifest_cache,
            ).entries
        except SyncError:
            continue
        parents.update(
            _entry_target_path(home, entry).parent for entry in release_entries
        )
    return parents


def _known_manifest_link_targets(
    home: Path,
    entries: list[LinkEntry],
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> dict[Path, set[str]]:
    targets: dict[Path, set[str]] = {}

    def add_entry(entry: LinkEntry) -> None:
        targets.setdefault(_entry_target_path(home, entry), set()).add(
            _desired_link_target(home, entry)
        )

    for entry in entries:
        add_entry(entry)

    owner = _entries_owner(entries)
    releases_root = _releases_root(home, owner)
    if not _ensure_safe_internal_directory(
        home,
        releases_root,
        create=False,
        allow_missing=True,
    ):
        return targets
    for release_dir in releases_root.iterdir():
        if RELEASE_DIR_RE.fullmatch(release_dir.name) is None:
            continue
        mode = os.lstat(release_dir).st_mode
        if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
            raise SyncError(f"refusing unsafe release directory: {release_dir}")
        try:
            release_entries = _load_installed_manifest_data(
                home,
                owner,
                release_dir.name,
                manifest_cache=manifest_cache,
            ).entries
        except SyncError:
            continue
        for entry in release_entries:
            add_entry(entry)
    return targets


def find_stale_current_symlinks(
    home: Path,
    entries: list[LinkEntry],
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> list[Path]:
    managed_targets = {_entry_target_path(home, entry) for entry in entries}
    candidates: list[Path] = []
    for parent in sorted(
        _known_manifest_target_parents(
            home,
            entries,
            manifest_cache=manifest_cache,
        )
    ):
        if parent.is_dir():
            candidates.extend(parent.iterdir())

    stale: list[Path] = []
    owner = _entries_owner(entries)
    current_root = _current_link(home, owner).resolve(strict=False)
    for candidate in candidates:
        if candidate in managed_targets or not candidate.is_symlink():
            continue
        linked_path = (candidate.parent / os.readlink(candidate)).resolve(strict=False)
        try:
            linked_path.relative_to(current_root)
        except ValueError:
            continue
        else:
            stale.append(candidate)
    return stale


def plan_stale_current_link_removals(
    home: Path,
    entries: list[LinkEntry],
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> list[LinkAction]:
    known_targets = _known_manifest_link_targets(
        home,
        entries,
        manifest_cache=manifest_cache,
    )
    removals: list[LinkAction] = []
    for stale_link in find_stale_current_symlinks(
        home,
        entries,
        manifest_cache=manifest_cache,
    ):
        expected_targets = known_targets.get(stale_link)
        if expected_targets is None or os.readlink(stale_link) not in expected_targets:
            continue
        removals.append(LinkAction("remove", stale_link, "", "directory"))
    return removals


def _dedupe_link_actions(actions: list[LinkAction]) -> list[LinkAction]:
    deduped: list[LinkAction] = []
    seen: set[tuple[str, Path]] = set()
    for action in actions:
        key = (action.action, action.target)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(action)
    return deduped


def _copy_bytes(
    source_fd: int,
    destination_fd: int,
    expected_size: int,
    display_path: Path,
) -> None:
    remaining = expected_size
    while remaining:
        chunk = os.read(source_fd, min(1024 * 1024, remaining))
        if not chunk:
            raise SyncError(
                f"release source ended before captured size during copy: {display_path}"
            )
        remaining -= len(chunk)
        view = memoryview(chunk)
        while view:
            written = os.write(destination_fd, view)
            if written <= 0:
                raise SyncError("release copy made no write progress")
            view = view[written:]
    if os.read(source_fd, 1):
        raise SyncError(f"release source grew during copy: {display_path}")


@dataclass(frozen=True)
class _ReleaseSourceSnapshot:
    device: int
    inode: int
    mode: int
    size: int
    mtime_ns: int
    ctime_ns: int
    content_identity: bytes | None = None


@dataclass(frozen=True)
class _DarwinExtendedAclApi:
    acl_get_fd_np: Any
    acl_valid: Any
    acl_get_entry: Any
    acl_get_tag_type: Any
    acl_get_qualifier: Any
    acl_free: Any
    mbr_uid_to_uuid: Any


@dataclass(frozen=True)
class _ReleaseIdentityDirectoryBinding:
    path: Path
    file_descriptor: int
    identity: tuple[int, int]


def _release_identity_policy_error(
    display_path: Path,
    detail: str,
    *,
    mismatch: bool,
) -> SyncError:
    classification = "mismatch" if mismatch else "cannot be verified"
    return SyncError(
        f"release identity access policy {classification}: {display_path}: {detail}",
        code="current-release-unverifiable",
    )


def _effective_release_identity_owner_uid(
    expected_owner_uid: int | None,
) -> int | None:
    if sys.platform != "darwin":
        return None
    if expected_owner_uid is not None:
        return expected_owner_uid
    return _RELEASE_IDENTITY_OWNER_UID.get()


@contextlib.contextmanager
def _release_identity_owner_uid_scope(
    expected_owner_uid: int | None,
) -> Iterator[None]:
    normalized_owner_uid = expected_owner_uid if sys.platform == "darwin" else None
    token = _RELEASE_IDENTITY_OWNER_UID.set(normalized_owner_uid)
    try:
        yield
    finally:
        _RELEASE_IDENTITY_OWNER_UID.reset(token)


def _load_darwin_extended_acl_api(display_path: Path) -> _DarwinExtendedAclApi:
    try:
        library = ctypes.CDLL(None, use_errno=True)
        acl_get_fd_np = library.acl_get_fd_np
        acl_valid = library.acl_valid
        acl_get_entry = library.acl_get_entry
        acl_get_tag_type = library.acl_get_tag_type
        acl_get_qualifier = library.acl_get_qualifier
        acl_free = library.acl_free
        mbr_uid_to_uuid = library.mbr_uid_to_uuid
    except (AttributeError, OSError) as error:
        raise _release_identity_policy_error(
            display_path,
            "Darwin extended ACL API is unavailable",
            mismatch=False,
        ) from error

    try:
        acl_get_fd_np.argtypes = [ctypes.c_int, ctypes.c_int]
        acl_get_fd_np.restype = ctypes.c_void_p
        acl_valid.argtypes = [ctypes.c_void_p]
        acl_valid.restype = ctypes.c_int
        acl_get_entry.argtypes = [
            ctypes.c_void_p,
            ctypes.c_int,
            ctypes.POINTER(ctypes.c_void_p),
        ]
        acl_get_entry.restype = ctypes.c_int
        acl_get_tag_type.argtypes = [
            ctypes.c_void_p,
            ctypes.POINTER(ctypes.c_int),
        ]
        acl_get_tag_type.restype = ctypes.c_int
        acl_get_qualifier.argtypes = [ctypes.c_void_p]
        acl_get_qualifier.restype = ctypes.c_void_p
        acl_free.argtypes = [ctypes.c_void_p]
        acl_free.restype = ctypes.c_int
        mbr_uid_to_uuid.argtypes = [
            ctypes.c_uint,
            ctypes.POINTER(ctypes.c_ubyte),
        ]
        mbr_uid_to_uuid.restype = ctypes.c_int
    except (AttributeError, TypeError, ValueError) as error:
        raise _release_identity_policy_error(
            display_path,
            "Darwin extended ACL API has an incompatible signature",
            mismatch=False,
        ) from error
    return _DarwinExtendedAclApi(
        acl_get_fd_np=acl_get_fd_np,
        acl_valid=acl_valid,
        acl_get_entry=acl_get_entry,
        acl_get_tag_type=acl_get_tag_type,
        acl_get_qualifier=acl_get_qualifier,
        acl_free=acl_free,
        mbr_uid_to_uuid=mbr_uid_to_uuid,
    )


def _darwin_extended_acl_entries(
    file_descriptor: int,
    display_path: Path,
    api: _DarwinExtendedAclApi,
) -> tuple[tuple[int, bytes | None], ...]:
    ctypes.set_errno(0)
    acl_pointer = api.acl_get_fd_np(
        file_descriptor,
        _DARWIN_ACL_TYPE_EXTENDED,
    )
    if not acl_pointer:
        error_number = ctypes.get_errno()
        if error_number == errno.ENOENT:
            return ()
        raise _release_identity_policy_error(
            display_path,
            f"acl_get_fd_np failed with errno {error_number}",
            mismatch=False,
        )

    entries: list[tuple[int, bytes | None]] = []
    acl_primary_error: BaseException | None = None
    try:
        ctypes.set_errno(0)
        if api.acl_valid(acl_pointer) != 0:
            error_number = ctypes.get_errno()
            raise _release_identity_policy_error(
                display_path,
                f"acl_valid failed with errno {error_number}",
                mismatch=False,
            )
        entry_selector = _DARWIN_ACL_FIRST_ENTRY
        while True:
            entry_pointer = ctypes.c_void_p()
            ctypes.set_errno(0)
            entry_result = api.acl_get_entry(
                acl_pointer,
                entry_selector,
                ctypes.byref(entry_pointer),
            )
            error_number = ctypes.get_errno()
            if (
                entry_selector == _DARWIN_ACL_NEXT_ENTRY
                and entry_result == -1
                and error_number == errno.EINVAL
            ):
                break
            if entry_result != 0 or not entry_pointer.value:
                raise _release_identity_policy_error(
                    display_path,
                    f"acl_get_entry failed with errno {error_number}",
                    mismatch=False,
                )

            tag_type = ctypes.c_int()
            ctypes.set_errno(0)
            if (
                api.acl_get_tag_type(
                    entry_pointer,
                    ctypes.byref(tag_type),
                )
                != 0
            ):
                error_number = ctypes.get_errno()
                raise _release_identity_policy_error(
                    display_path,
                    f"acl_get_tag_type failed with errno {error_number}",
                    mismatch=False,
                )

            qualifier: bytes | None = None
            if tag_type.value == _DARWIN_ACL_EXTENDED_ALLOW:
                ctypes.set_errno(0)
                qualifier_pointer = api.acl_get_qualifier(entry_pointer)
                if not qualifier_pointer:
                    error_number = ctypes.get_errno()
                    raise _release_identity_policy_error(
                        display_path,
                        f"acl_get_qualifier failed with errno {error_number}",
                        mismatch=False,
                    )
                qualifier_primary_error: BaseException | None = None
                try:
                    qualifier = ctypes.string_at(
                        qualifier_pointer,
                        _DARWIN_UUID_BYTES,
                    )
                except BaseException as error:
                    qualifier_primary_error = error
                    raise
                finally:
                    try:
                        ctypes.set_errno(0)
                        qualifier_free_result = api.acl_free(qualifier_pointer)
                        error_number = ctypes.get_errno()
                    except BaseException as cleanup_error:
                        if qualifier_primary_error is None:
                            raise _release_identity_policy_error(
                                display_path,
                                f"acl_free qualifier failed: {cleanup_error}",
                                mismatch=False,
                            ) from cleanup_error
                    else:
                        if (
                            qualifier_free_result != 0
                            and qualifier_primary_error is None
                        ):
                            raise _release_identity_policy_error(
                                display_path,
                                f"acl_free qualifier failed with errno {error_number}",
                                mismatch=False,
                            )
            entries.append((tag_type.value, qualifier))
            if len(entries) > 128:
                raise _release_identity_policy_error(
                    display_path,
                    "extended ACL exceeds the Darwin entry limit",
                    mismatch=False,
                )
            entry_selector = _DARWIN_ACL_NEXT_ENTRY
    except BaseException as error:
        acl_primary_error = error
        raise
    finally:
        try:
            ctypes.set_errno(0)
            acl_free_result = api.acl_free(acl_pointer)
            error_number = ctypes.get_errno()
        except BaseException as cleanup_error:
            if acl_primary_error is None:
                raise _release_identity_policy_error(
                    display_path,
                    f"acl_free ACL failed: {cleanup_error}",
                    mismatch=False,
                ) from cleanup_error
        else:
            if acl_free_result != 0 and acl_primary_error is None:
                raise _release_identity_policy_error(
                    display_path,
                    f"acl_free ACL failed with errno {error_number}",
                    mismatch=False,
                )
    return tuple(entries)


def _darwin_owner_uuid(
    owner_uid: int,
    display_path: Path,
    api: _DarwinExtendedAclApi,
) -> bytes:
    owner_uuid = (ctypes.c_ubyte * _DARWIN_UUID_BYTES)()
    result = api.mbr_uid_to_uuid(owner_uid, owner_uuid)
    if result != 0:
        raise _release_identity_policy_error(
            display_path,
            f"mbr_uid_to_uuid failed with error {result}",
            mismatch=False,
        )
    return bytes(owner_uuid)


def _require_darwin_acl_entries_owner_only(
    entries: tuple[tuple[int, bytes | None], ...],
    owner_uuid: bytes | None,
    display_path: Path,
) -> None:
    if owner_uuid is not None and len(owner_uuid) != _DARWIN_UUID_BYTES:
        raise _release_identity_policy_error(
            display_path,
            "owner UUID has an invalid size",
            mismatch=False,
        )
    for tag_type, qualifier in entries:
        if tag_type == _DARWIN_ACL_EXTENDED_DENY:
            continue
        if tag_type == _DARWIN_ACL_EXTENDED_ALLOW:
            if owner_uuid is None:
                raise _release_identity_policy_error(
                    display_path,
                    "owner UUID is unavailable for an ALLOW entry",
                    mismatch=False,
                )
            if qualifier != owner_uuid:
                raise _release_identity_policy_error(
                    display_path,
                    "extended ACL grants ALLOW access to a non-owner qualifier",
                    mismatch=True,
                )
            continue
        raise _release_identity_policy_error(
            display_path,
            f"extended ACL contains unknown tag {tag_type}",
            mismatch=False,
        )


def _require_release_identity_fd_access_policy(
    file_descriptor: int,
    display_path: Path,
    expected_owner_uid: int,
) -> os.stat_result:
    """Prove the release object is owner-controlled on this exact bound FD.

    Raw ACL bytes and entry order are deliberately not evidence. The protected
    property is a stable dev/inode/type, the expected UID, and the absence of
    non-owner write authority from POSIX mode bits or the extended ACL
    admission policy. Safe mode or ctime drift triggers one complete semantic
    reread instead of being treated as mutation evidence by itself.
    """
    try:
        initial_metadata = os.fstat(file_descriptor)
    except OSError as error:
        raise _release_identity_policy_error(
            display_path,
            f"fstat failed: {error}",
            mismatch=False,
        ) from error
    if sys.platform != "darwin":
        return initial_metadata

    expected_identity = (
        initial_metadata.st_dev,
        initial_metadata.st_ino,
        stat.S_IFMT(initial_metadata.st_mode),
    )
    api: _DarwinExtendedAclApi | None = None
    pre_metadata = initial_metadata
    for sample_index in range(2):
        if sample_index:
            try:
                pre_metadata = os.fstat(file_descriptor)
            except OSError as error:
                raise _release_identity_policy_error(
                    display_path,
                    f"revalidation fstat failed: {error}",
                    mismatch=False,
                ) from error

        pre_identity = (
            pre_metadata.st_dev,
            pre_metadata.st_ino,
            stat.S_IFMT(pre_metadata.st_mode),
        )
        if pre_identity != expected_identity:
            raise _release_identity_policy_error(
                display_path,
                "bound object identity changed during access-policy validation",
                mismatch=True,
            )
        if pre_metadata.st_uid != expected_owner_uid:
            raise _release_identity_policy_error(
                display_path,
                f"owner UID {pre_metadata.st_uid} != expected UID {expected_owner_uid}",
                mismatch=True,
            )
        pre_mode = stat.S_IMODE(pre_metadata.st_mode)
        if pre_mode & 0o022:
            raise _release_identity_policy_error(
                display_path,
                f"mode {pre_mode:04o} grants group or world write authority",
                mismatch=True,
            )

        try:
            if api is None:
                api = _load_darwin_extended_acl_api(display_path)
            entries = _darwin_extended_acl_entries(
                file_descriptor,
                display_path,
                api,
            )
        except SyncError:
            raise
        except (OSError, TypeError, ValueError, ctypes.ArgumentError) as error:
            raise _release_identity_policy_error(
                display_path,
                f"Darwin extended ACL API failed: {error}",
                mismatch=False,
            ) from error
        if any(
            tag_type == _DARWIN_ACL_EXTENDED_ALLOW for tag_type, _qualifier in entries
        ):
            try:
                owner_uuid = _darwin_owner_uuid(
                    pre_metadata.st_uid,
                    display_path,
                    api,
                )
                _require_darwin_acl_entries_owner_only(
                    entries,
                    owner_uuid,
                    display_path,
                )
            except SyncError:
                raise
            except (
                OSError,
                TypeError,
                ValueError,
                ctypes.ArgumentError,
            ) as error:
                raise _release_identity_policy_error(
                    display_path,
                    f"Darwin owner UUID API failed: {error}",
                    mismatch=False,
                ) from error
        else:
            _require_darwin_acl_entries_owner_only(
                entries,
                None,
                display_path,
            )

        try:
            post_metadata = os.fstat(file_descriptor)
        except OSError as error:
            raise _release_identity_policy_error(
                display_path,
                f"post-ACL fstat failed: {error}",
                mismatch=False,
            ) from error
        post_identity = (
            post_metadata.st_dev,
            post_metadata.st_ino,
            stat.S_IFMT(post_metadata.st_mode),
        )
        if post_identity != expected_identity:
            raise _release_identity_policy_error(
                display_path,
                "bound object identity changed during access-policy validation",
                mismatch=True,
            )
        if post_metadata.st_uid != expected_owner_uid:
            raise _release_identity_policy_error(
                display_path,
                "owner UID "
                f"{post_metadata.st_uid} != expected UID {expected_owner_uid}",
                mismatch=True,
            )
        post_mode = stat.S_IMODE(post_metadata.st_mode)
        if post_mode & 0o022:
            raise _release_identity_policy_error(
                display_path,
                f"mode {post_mode:04o} grants group or world write authority",
                mismatch=True,
            )
        if (
            pre_mode == post_mode
            and pre_metadata.st_ctime_ns == post_metadata.st_ctime_ns
        ):
            return post_metadata
        if sample_index:
            raise _release_identity_policy_error(
                display_path,
                "access policy did not stabilize during revalidation",
                mismatch=False,
            )

    raise AssertionError("unreachable Darwin access-policy sample state")


def _require_release_identity_directory_bindings(
    home: Path,
    bindings: list[_ReleaseIdentityDirectoryBinding],
    expected_owner_uid: int,
) -> None:
    for binding in bindings:
        metadata = _require_release_identity_fd_access_policy(
            binding.file_descriptor,
            binding.path,
            expected_owner_uid,
        )
        if (
            not stat.S_ISDIR(metadata.st_mode)
            or (metadata.st_dev, metadata.st_ino) != binding.identity
            or not _bound_directory_matches(
                home,
                binding.path,
                binding.file_descriptor,
            )
        ):
            raise _release_identity_policy_error(
                binding.path,
                "bound directory object changed",
                mismatch=True,
            )


def _open_release_identity_directory_chain(
    home: Path,
    directory: Path,
    expected_owner_uid: int,
) -> list[_ReleaseIdentityDirectoryBinding]:
    parts = _directory_parts_beneath(home, directory)
    bindings: list[_ReleaseIdentityDirectoryBinding] = []
    current_path = home
    try:
        current_fd = _bound_sync_home_anchor(home, None)
        try:
            metadata = _require_release_identity_fd_access_policy(
                current_fd,
                current_path,
                expected_owner_uid,
            )
            if not stat.S_ISDIR(metadata.st_mode):
                raise _release_identity_policy_error(
                    current_path,
                    "bound object is not a directory",
                    mismatch=True,
                )
        except BaseException:
            _close_fd_quietly(current_fd)
            raise
        bindings.append(
            _ReleaseIdentityDirectoryBinding(
                path=current_path,
                file_descriptor=current_fd,
                identity=(metadata.st_dev, metadata.st_ino),
            )
        )
        for part in parts:
            current_path /= part
            next_fd = os.open(
                part,
                _source_directory_flags(),
                dir_fd=bindings[-1].file_descriptor,
            )
            try:
                metadata = _require_release_identity_fd_access_policy(
                    next_fd,
                    current_path,
                    expected_owner_uid,
                )
                if not stat.S_ISDIR(metadata.st_mode):
                    raise _release_identity_policy_error(
                        current_path,
                        "bound object is not a directory",
                        mismatch=True,
                    )
            except BaseException:
                _close_fd_quietly(next_fd)
                raise
            bindings.append(
                _ReleaseIdentityDirectoryBinding(
                    path=current_path,
                    file_descriptor=next_fd,
                    identity=(metadata.st_dev, metadata.st_ino),
                )
            )
        _require_release_identity_directory_bindings(
            home,
            bindings,
            expected_owner_uid,
        )
        return bindings
    except BaseException as error:
        for binding in reversed(bindings):
            _close_fd_quietly(binding.file_descriptor)
        if isinstance(error, OSError):
            raise _release_identity_policy_error(
                current_path,
                f"cannot open directory chain: {error}",
                mismatch=False,
            ) from error
        raise


def _close_release_identity_directory_bindings(
    bindings: list[_ReleaseIdentityDirectoryBinding],
) -> None:
    for binding in reversed(bindings):
        _close_fd_quietly(binding.file_descriptor)


def _release_source_snapshot(metadata: os.stat_result) -> _ReleaseSourceSnapshot:
    return _ReleaseSourceSnapshot(
        device=metadata.st_dev,
        inode=metadata.st_ino,
        mode=metadata.st_mode,
        size=metadata.st_size,
        mtime_ns=metadata.st_mtime_ns,
        ctime_ns=metadata.st_ctime_ns,
    )


def _release_source_matches(
    snapshot: _ReleaseSourceSnapshot,
    metadata: os.stat_result,
    *,
    ignore_ctime: bool = False,
) -> bool:
    current = _release_source_snapshot(metadata)
    expected_metadata = (
        snapshot.device,
        snapshot.inode,
        snapshot.mode,
        snapshot.size,
        snapshot.mtime_ns,
    )
    current_metadata = (
        current.device,
        current.inode,
        current.mode,
        current.size,
        current.mtime_ns,
    )
    if expected_metadata != current_metadata:
        return False
    return ignore_ctime or snapshot.ctime_ns == current.ctime_ns


def _require_release_source_unchanged(
    snapshot: _ReleaseSourceSnapshot,
    metadata: os.stat_result,
    display_path: Path,
    *,
    ignore_ctime: bool = False,
    file_descriptor: int | None = None,
    expected_owner_uid: int | None = None,
    operation: str = "copy",
) -> _ReleaseSourceSnapshot:
    if _release_source_matches(snapshot, metadata):
        return snapshot
    if not (
        ignore_ctime and _release_source_matches(snapshot, metadata, ignore_ctime=True)
    ):
        raise SyncError(f"release source changed during {operation}: {display_path}")
    # ctime is only a revalidation trigger. Directory entry content is bound by
    # exact immediate-member identities; a regular file with ctime-only drift
    # must be rehashed from the same bound FD before safe metadata churn is
    # accepted. Callers with more than one terminal check for the same retained
    # file FD use _require_release_stage_source_unchanged to enforce one rehash
    # across that stage.
    if stat.S_ISREG(snapshot.mode):
        if file_descriptor is None or snapshot.content_identity is None:
            raise SyncError(
                "release source content cannot be revalidated after ctime drift "
                f"during {operation}: {display_path}"
            )
        terminal_metadata = _rehash_release_source_file_content(
            file_descriptor,
            snapshot,
            metadata,
            display_path,
            expected_owner_uid=expected_owner_uid,
            operation=operation,
        )
        return replace(snapshot, ctime_ns=terminal_metadata.st_ctime_ns)
    if not stat.S_ISDIR(snapshot.mode):
        raise SyncError(
            "release source type cannot be revalidated after ctime drift "
            f"during {operation}: {display_path}"
        )
    return replace(snapshot, ctime_ns=metadata.st_ctime_ns)


def _require_release_stage_source_unchanged(
    snapshot: _ReleaseSourceSnapshot,
    metadata: os.stat_result,
    display_path: Path,
    *,
    rehash_used: bool,
    ignore_ctime: bool,
    file_descriptor: int,
    expected_owner_uid: int | None,
    operation: str,
) -> tuple[_ReleaseSourceSnapshot, bool]:
    exact_match = _release_source_matches(snapshot, metadata)
    if rehash_used and stat.S_ISREG(snapshot.mode) and not exact_match:
        raise SyncError(f"release source changed during {operation}: {display_path}")
    updated_snapshot = _require_release_source_unchanged(
        snapshot,
        metadata,
        display_path,
        ignore_ctime=ignore_ctime,
        file_descriptor=file_descriptor,
        expected_owner_uid=expected_owner_uid,
        operation=operation,
    )
    return (
        updated_snapshot,
        rehash_used or (stat.S_ISREG(snapshot.mode) and not exact_match),
    )


def _source_directory_flags() -> int:
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    flags |= getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    return flags


def _source_regular_file_flags() -> int:
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    return flags


def _open_source_regular_file(
    parent_fd: int,
    name: str,
    named_snapshot: _ReleaseSourceSnapshot,
    display_path: Path,
    *,
    ignore_ctime: bool = False,
) -> tuple[int, _ReleaseSourceSnapshot]:
    file_fd = os.open(name, _source_regular_file_flags(), dir_fd=parent_fd)
    try:
        opened_metadata = os.fstat(file_fd)
        if not stat.S_ISREG(opened_metadata.st_mode):
            raise SyncError(f"release source is not a regular file: {display_path}")
        opened_snapshot = _release_source_snapshot(opened_metadata)
        if not _release_source_matches(
            named_snapshot,
            opened_metadata,
            ignore_ctime=ignore_ctime,
        ):
            raise SyncError(f"release source changed before open: {display_path}")
        return file_fd, opened_snapshot
    except BaseException:
        _close_fd_quietly(file_fd)
        raise


def _read_exact_regular_file(
    file_fd: int,
    snapshot: _ReleaseSourceSnapshot,
    display_path: Path,
    *,
    max_bytes: int | None = None,
) -> bytes:
    if max_bytes is not None and snapshot.size > max_bytes:
        raise SyncError(f"release manifest exceeds {max_bytes} bytes: {display_path}")
    chunks: list[bytes] = []
    remaining = snapshot.size
    while remaining:
        chunk = os.read(file_fd, min(1024 * 1024, remaining))
        if not chunk:
            raise SyncError(
                f"release source ended before captured size while reading: {display_path}"
            )
        chunks.append(chunk)
        remaining -= len(chunk)
    if os.read(file_fd, 1):
        raise SyncError(f"release source grew while reading: {display_path}")
    return b"".join(chunks)


def _hash_exact_regular_file(
    file_fd: int,
    snapshot: _ReleaseSourceSnapshot,
    display_path: Path,
    *,
    capture_payload: bool,
) -> tuple[bytes, bytes | None]:
    content_digest = hashlib.sha256()
    chunks: list[bytes] | None = [] if capture_payload else None
    remaining = snapshot.size
    while remaining:
        chunk = os.read(file_fd, min(1024 * 1024, remaining))
        if not chunk:
            raise SyncError(
                f"release source ended before captured size while hashing: {display_path}"
            )
        content_digest.update(chunk)
        if chunks is not None:
            chunks.append(chunk)
        remaining -= len(chunk)
    if os.read(file_fd, 1):
        raise SyncError(f"release source grew while hashing: {display_path}")
    content_identity = snapshot.size.to_bytes(8, "big") + content_digest.digest()
    payload = b"".join(chunks) if chunks is not None else None
    return content_identity, payload


def _rehash_release_source_file_content(
    file_descriptor: int,
    snapshot: _ReleaseSourceSnapshot,
    revalidation_metadata: os.stat_result,
    display_path: Path,
    *,
    expected_owner_uid: int | None,
    operation: str,
) -> os.stat_result:
    try:
        os.lseek(file_descriptor, 0, os.SEEK_SET)
    except OSError as error:
        raise SyncError(
            "release source content cannot be revalidated after ctime drift "
            f"during {operation}: {display_path}"
        ) from error
    observed_identity, _payload = _hash_exact_regular_file(
        file_descriptor,
        snapshot,
        display_path,
        capture_payload=False,
    )
    if observed_identity != snapshot.content_identity:
        raise SyncError(f"release source changed during {operation}: {display_path}")
    terminal_metadata = (
        _require_release_identity_fd_access_policy(
            file_descriptor,
            display_path,
            expected_owner_uid,
        )
        if expected_owner_uid is not None
        else os.fstat(file_descriptor)
    )
    if (
        not _release_source_matches(
            snapshot,
            terminal_metadata,
            ignore_ctime=True,
        )
        or terminal_metadata.st_ctime_ns != revalidation_metadata.st_ctime_ns
    ):
        raise SyncError(f"release source changed during {operation}: {display_path}")
    return terminal_metadata


def _open_release_source_root(
    source_root: Path,
) -> tuple[int, int, _ReleaseSourceSnapshot]:
    parent_fd = os.open(source_root.parent, _source_directory_flags())
    source_fd = -1
    try:
        named_metadata = os.stat(
            source_root.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if not stat.S_ISDIR(named_metadata.st_mode):
            raise SyncError(f"release source root is unsafe: {source_root}")
        source_fd = os.open(
            source_root.name,
            _source_directory_flags(),
            dir_fd=parent_fd,
        )
        source_metadata = os.fstat(source_fd)
        snapshot = _release_source_snapshot(source_metadata)
        _require_release_source_unchanged(snapshot, named_metadata, source_root)
        return parent_fd, source_fd, snapshot
    except BaseException as error:
        if source_fd >= 0:
            _close_fd_quietly(source_fd)
        _close_fd_quietly(parent_fd)
        if isinstance(error, OSError):
            raise SyncError(f"release source root is unsafe: {source_root}") from error
        raise


def _open_relative_parent_fd(
    root_fd: int,
    relative_path: PurePosixPath,
) -> tuple[int, str]:
    if not relative_path.parts:
        raise SyncError("release relative path must not be empty")
    parent_fd = os.dup(root_fd)
    try:
        for part in relative_path.parts[:-1]:
            next_fd = os.open(part, _source_directory_flags(), dir_fd=parent_fd)
            _close_fd_quietly(parent_fd)
            parent_fd = next_fd
        return parent_fd, relative_path.parts[-1]
    except BaseException:
        _close_fd_quietly(parent_fd)
        raise


def _release_path_kind_at_fd(
    root_fd: int,
    relative_path: PurePosixPath,
) -> str | None:
    parent_fd = -1
    try:
        parent_fd, name = _open_relative_parent_fd(root_fd, relative_path)
        metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except (FileNotFoundError, NotADirectoryError, OSError, SyncError):
        return None
    finally:
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)
    if stat.S_ISREG(metadata.st_mode):
        return "file"
    if stat.S_ISDIR(metadata.st_mode):
        return "directory"
    return None


def _read_regular_file_at(
    root_fd: int,
    relative_path: PurePosixPath,
    display_root: Path,
    *,
    max_bytes: int | None = None,
) -> bytes:
    parent_fd = -1
    file_fd = -1
    display_path = display_root / Path(*relative_path.parts)
    try:
        parent_fd, name = _open_relative_parent_fd(root_fd, relative_path)
        named_metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if not stat.S_ISREG(named_metadata.st_mode):
            raise SyncError(f"release source is not a regular file: {display_path}")
        named_snapshot = _release_source_snapshot(named_metadata)
        file_fd, snapshot = _open_source_regular_file(
            parent_fd,
            name,
            named_snapshot,
            display_path,
        )
        payload = _read_exact_regular_file(
            file_fd,
            snapshot,
            display_path,
            max_bytes=max_bytes,
        )
        _require_release_source_unchanged(snapshot, os.fstat(file_fd), display_path)
        current_metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        _require_release_source_unchanged(snapshot, current_metadata, display_path)
        return payload
    except OSError as error:
        raise SyncError(f"failed to read release source: {display_path}") from error
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)


def _load_manifest_payload_from_directory_fd(
    root_fd: int,
    display_root: Path,
) -> dict[str, Any]:
    relative_manifest = PurePosixPath(MANIFEST_RELATIVE_PATH.as_posix())
    payload = _read_regular_file_at(
        root_fd,
        relative_manifest,
        display_root,
        max_bytes=MAX_RELEASE_MANIFEST_BYTES,
    )
    manifest_path = display_root / MANIFEST_RELATIVE_PATH
    return _decode_manifest_payload(payload, manifest_path)


def _decode_manifest_payload(
    payload: bytes,
    manifest_path: Path,
) -> dict[str, Any]:
    try:
        data = json.loads(
            payload.decode("utf-8"),
            parse_int=_bounded_json_integer,
            parse_constant=_reject_json_constant,
        )
    except (UnicodeDecodeError, ValueError, RecursionError) as error:
        raise SyncError(f"Invalid JSON in {manifest_path}: {error}") from error
    if not isinstance(data, dict):
        raise SyncError(f"Expected JSON object in {manifest_path}")
    return data


def _load_manifest_data_from_directory_fd(
    root_fd: int,
    display_root: Path,
) -> tuple[dict[str, Any], ManifestData]:
    data = _load_manifest_payload_from_directory_fd(root_fd, display_root)
    manifest = _parse_manifest_data(
        data,
        lambda relative_path: _release_path_kind_at_fd(root_fd, relative_path),
    )
    return data, manifest


def _open_installed_release_directory_fd(
    home: Path,
    owner: str,
    sha: str,
) -> int:
    owner = _validate_owner(owner)
    sha = _validate_release_sha(sha, f"installed release SHA for owner {owner}")
    release_root = _releases_root(home, owner) / sha
    try:
        release_fd = _open_directory_beneath(home, release_root)
    except (OSError, SyncError) as error:
        raise SyncError(f"refusing unsafe release directory: {release_root}") from error
    if not _bound_directory_matches(home, release_root, release_fd):
        _close_fd_quietly(release_fd)
        raise SyncError(f"installed release directory changed: {release_root}")
    return release_fd


def _release_tree_identity_and_captured_files_from_directory_fd(
    root_fd: int,
    display_root: Path,
    *,
    require_sanitized_modes: bool = False,
    expected_owner_uid: int | None = None,
    capture_limits: dict[PurePosixPath, int],
) -> tuple[ReleaseTreeIdentity, dict[PurePosixPath, bytes]]:
    expected_owner_uid = _effective_release_identity_owner_uid(expected_owner_uid)
    with _release_identity_owner_uid_scope(expected_owner_uid):
        (
            manifest_payload,
            tree_digest,
            path_kinds,
            source_snapshots,
            source_members,
            captured_files,
        ) = _release_tree_snapshot_from_directory_fd(
            root_fd,
            display_root,
            require_sanitized_modes=require_sanitized_modes,
            capture_limits=capture_limits,
        )
    data = _decode_manifest_payload(
        manifest_payload,
        display_root / MANIFEST_RELATIVE_PATH,
    )
    manifest = _parse_manifest_data(data, path_kinds.get)
    _verify_release_source_snapshot(
        root_fd,
        display_root,
        source_snapshots,
        source_members,
        operation="identity validation",
        expected_owner_uid=expected_owner_uid,
    )
    return (data, manifest, tree_digest), captured_files


def _release_tree_identity_from_directory_fd(
    root_fd: int,
    display_root: Path,
    *,
    require_sanitized_modes: bool = False,
    expected_owner_uid: int | None = None,
) -> ReleaseTreeIdentity:
    expected_owner_uid = _effective_release_identity_owner_uid(expected_owner_uid)
    with _release_identity_owner_uid_scope(expected_owner_uid):
        identity, _captured_files = (
            _release_tree_identity_and_captured_files_from_directory_fd(
                root_fd,
                display_root,
                require_sanitized_modes=require_sanitized_modes,
                capture_limits={},
            )
        )
    return identity


def _release_tree_identity_with_owner_access_policy(
    root_fd: int,
    display_root: Path,
    *,
    require_sanitized_modes: bool = False,
    expected_owner_uid: int | None,
) -> ReleaseTreeIdentity:
    with _release_identity_owner_uid_scope(expected_owner_uid):
        return _release_tree_identity_from_directory_fd(
            root_fd,
            display_root,
            require_sanitized_modes=require_sanitized_modes,
        )


def _release_directory_identity_and_access_policy(
    directory_fd: int,
) -> tuple[tuple[int, int], tuple[int, int, int]]:
    metadata = os.fstat(directory_fd)
    if not stat.S_ISDIR(metadata.st_mode):
        raise SyncError("bound path is no longer a directory")
    return (
        (metadata.st_dev, metadata.st_ino),
        (stat.S_IMODE(metadata.st_mode), metadata.st_uid, metadata.st_gid),
    )


def _installed_release_identity_and_directory_evidence(
    home: Path,
    owner: str,
    sha: str,
    *,
    release_identity_owner_uid: int | None = None,
) -> ReleaseTreeDirectoryEvidence:
    owner = _validate_owner(owner)
    sha = _validate_release_sha(sha, f"installed release SHA for owner {owner}")
    release_root = _releases_root(home, owner) / sha
    expected_owner_uid = (
        release_identity_owner_uid if sys.platform == "darwin" else None
    )
    directory_bindings: list[_ReleaseIdentityDirectoryBinding] = []
    if expected_owner_uid is None:
        release_fd = _open_installed_release_directory_fd(home, owner, sha)
    else:
        directory_bindings = _open_release_identity_directory_chain(
            home,
            release_root,
            expected_owner_uid,
        )
        try:
            release_fd = os.dup(directory_bindings[-1].file_descriptor)
        except BaseException:
            _close_release_identity_directory_bindings(directory_bindings)
            raise
    try:
        directory_identity, directory_access_policy = (
            _release_directory_identity_and_access_policy(release_fd)
        )
        identity = _release_tree_identity_with_owner_access_policy(
            release_fd,
            release_root,
            require_sanitized_modes=True,
            expected_owner_uid=expected_owner_uid,
        )
        if identity[1].owner != owner:
            raise SyncError(
                f"release owner mismatch: expected {owner}, got {identity[1].owner}"
            )
        if not _bound_directory_matches(home, release_root, release_fd):
            raise SyncError(f"installed release directory changed: {release_root}")
        terminal_directory_evidence = _release_directory_identity_and_access_policy(
            release_fd
        )
        if terminal_directory_evidence != (
            directory_identity,
            directory_access_policy,
        ):
            raise SyncError(f"installed release directory changed: {release_root}")
        if expected_owner_uid is not None:
            _require_release_identity_directory_bindings(
                home,
                directory_bindings,
                expected_owner_uid,
            )
        return identity, directory_identity, directory_access_policy
    finally:
        _close_fd_quietly(release_fd)
        _close_release_identity_directory_bindings(directory_bindings)


def _installed_release_identity_and_directory_identity(
    home: Path,
    owner: str,
    sha: str,
) -> ReleaseTreeExpectation:
    identity, directory_identity, _directory_access_policy = (
        _installed_release_identity_and_directory_evidence(home, owner, sha)
    )
    return identity, directory_identity


def _pending_release_expectations_for_state(
    home: Path,
    state: ManagedState,
    cache: dict[tuple[str, str], PendingReleaseExpectation] | None = None,
) -> tuple[PendingReleaseExpectation, ...]:
    if len(state.owners) > MAX_PENDING_RELEASES:
        raise SyncError("pending transaction has too many release expectations")
    if cache is None:
        cache = {}
    expectations: list[PendingReleaseExpectation] = []
    for owner, sha in sorted(state.owners.items()):
        key = (owner, sha)
        expectation = cache.get(key)
        if expectation is None:
            release_identity, directory_identity = (
                _installed_release_identity_and_directory_identity(
                    home,
                    owner,
                    sha,
                )
            )
            tree_sha256 = release_identity[2]
            if re.fullmatch(r"[0-9a-f]{64}", tree_sha256) is None:
                raise SyncError(
                    f"installed release tree digest is invalid: {owner}@{sha}"
                )
            expectation = PendingReleaseExpectation(
                owner=owner,
                sha=sha,
                directory_identity=directory_identity,
                tree_sha256=tree_sha256,
            )
            cache[key] = expectation
        expectations.append(expectation)
    return tuple(expectations)


def _installed_release_identity(
    home: Path,
    owner: str,
    sha: str,
) -> ReleaseTreeIdentity:
    identity, _directory_identity_value = (
        _installed_release_identity_and_directory_identity(home, owner, sha)
    )
    return identity


def _load_installed_manifest_data(
    home: Path,
    owner: str,
    sha: str,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> ManifestData:
    owner = _validate_owner(owner)
    sha = _validate_release_sha(sha)
    cache_key = (owner, sha)
    if manifest_cache is not None and cache_key in manifest_cache:
        cached_manifest = manifest_cache[cache_key]
        if cached_manifest is None:
            raise SyncError(
                f"installed release already failed validation: {owner}@{sha}"
            )
        return cached_manifest
    try:
        _payload, manifest, _tree_digest = _installed_release_identity(
            home,
            owner,
            sha,
        )
    except SyncError:
        if manifest_cache is not None:
            manifest_cache[cache_key] = None
        raise
    if manifest_cache is not None:
        manifest_cache[cache_key] = manifest
    return manifest


def _sanitized_release_mode(metadata: os.stat_result) -> int:
    mode = stat.S_IMODE(metadata.st_mode)
    if stat.S_ISDIR(metadata.st_mode):
        return (mode & 0o755) | 0o700
    return mode & 0o755


def _release_tree_digest_field(digest: Any, payload: bytes) -> None:
    digest.update(len(payload).to_bytes(8, "big"))
    digest.update(payload)


@dataclass
class _ReleaseTreeResourceBudget:
    path_entries: int = 0
    expanded_bytes: int = 0

    @property
    def remaining_path_entries(self) -> int:
        return MAX_ARCHIVE_MEMBERS - self.path_entries

    def reserve_path_entries(self, count: int = 1) -> None:
        if count > self.remaining_path_entries:
            raise SyncError(
                f"release tree exceeds {MAX_ARCHIVE_MEMBERS} path entry limit"
            )
        self.path_entries += count

    def reserve_file_bytes(
        self,
        size: int,
        display_path: Path,
    ) -> None:
        if size < 0 or size > MAX_ARCHIVE_MEMBER_BYTES:
            raise SyncError(
                "release tree file exceeds expanded byte limit: "
                f"{display_path}: {size} > {MAX_ARCHIVE_MEMBER_BYTES}"
            )
        next_expanded_bytes = self.expanded_bytes + size
        if next_expanded_bytes > MAX_ARCHIVE_EXPANDED_BYTES:
            raise SyncError(
                "release tree exceeds total expanded byte limit: "
                f"{next_expanded_bytes} > {MAX_ARCHIVE_EXPANDED_BYTES}"
            )
        self.expanded_bytes = next_expanded_bytes


def _validated_release_tree_child_path(
    relative_root: PurePosixPath,
    name: str,
) -> PurePosixPath:
    release_relative_name = (
        f"{relative_root.as_posix()}/{name}" if relative_root.parts else name
    )
    archive_member_name = f"{CANONICAL_PACKAGE_ROOT_COMPONENT}/{release_relative_name}"
    try:
        archive_member_parts = _validated_archive_member_parts(archive_member_name)
    except SyncError as error:
        raise SyncError(f"invalid release tree path: {error}") from error
    return PurePosixPath(*archive_member_parts[1:])


def _release_tree_path_is_cache_artifact(path: PurePosixPath) -> bool:
    return (
        "__pycache__" in path.parts
        or path.name.endswith(".pyc")
        or path.name.endswith(".pyo")
    )


def _release_tree_snapshot_from_directory_fd(
    root_fd: int,
    display_root: Path,
    *,
    require_sanitized_modes: bool,
    expected_owner_uid: int | None = None,
    capture_limits: dict[PurePosixPath, int],
) -> tuple[
    bytes,
    str,
    dict[PurePosixPath, str],
    dict[PurePosixPath, _ReleaseSourceSnapshot],
    dict[PurePosixPath, tuple[str, ...]],
    dict[PurePosixPath, bytes],
]:
    """Capture one normalized release-tree identity without following symlinks."""
    expected_owner_uid = _effective_release_identity_owner_uid(expected_owner_uid)
    digest = hashlib.sha256(b"codex-personal-sync-release-tree-v1\0")
    manifest_relative = PurePosixPath(MANIFEST_RELATIVE_PATH.as_posix())
    manifest_payload: bytes | None = None
    path_kinds: dict[PurePosixPath, str] = {}
    source_snapshots: dict[PurePosixPath, _ReleaseSourceSnapshot] = {}
    source_members: dict[PurePosixPath, tuple[str, ...]] = {}
    captured_files: dict[PurePosixPath, bytes] = {}
    resource_budget = _ReleaseTreeResourceBudget()

    def normalized_mode(metadata: os.stat_result, display_path: Path) -> int:
        actual_mode = stat.S_IMODE(metadata.st_mode)
        expected_mode = _sanitized_release_mode(metadata)
        if require_sanitized_modes and actual_mode != expected_mode:
            raise SyncError(
                "release tree entry mode is not sanitized: "
                f"{display_path}: {actual_mode:#o} != {expected_mode:#o}"
            )
        return expected_mode

    def record(
        entry_type: bytes,
        relative_path: PurePosixPath,
        mode: int,
        content_digest: bytes = b"",
    ) -> None:
        relative_bytes = (
            relative_path.as_posix().encode("utf-8", "surrogateescape")
            if relative_path.parts
            else b""
        )
        _release_tree_digest_field(digest, entry_type)
        _release_tree_digest_field(digest, relative_bytes)
        _release_tree_digest_field(digest, mode.to_bytes(4, "big"))
        _release_tree_digest_field(digest, content_digest)

    def visit_directory(
        directory_fd: int,
        relative_root: PurePosixPath,
    ) -> None:
        nonlocal manifest_payload
        display_directory = display_root / Path(*relative_root.parts)
        directory_metadata = (
            _require_release_identity_fd_access_policy(
                directory_fd,
                display_directory,
                expected_owner_uid,
            )
            if expected_owner_uid is not None
            else os.fstat(directory_fd)
        )
        if not stat.S_ISDIR(directory_metadata.st_mode):
            raise SyncError(
                f"release tree entry is not a directory: {display_directory}"
            )
        directory_snapshot = _release_source_snapshot(directory_metadata)
        source_snapshots[relative_root] = directory_snapshot
        path_kinds[relative_root] = "directory"
        directory_mode = normalized_mode(directory_metadata, display_directory)
        record(
            b"directory",
            relative_root,
            # The release root is an installation container. Its safe 0700/0755
            # mode can vary by extractor without changing packaged content.
            0 if not relative_root.parts else directory_mode,
        )
        names = _directory_member_names(
            directory_fd,
            maximum_entries=resource_budget.remaining_path_entries,
            overflow_message=(
                f"release tree exceeds {MAX_ARCHIVE_MEMBERS} path entry limit"
            ),
        )
        resource_budget.reserve_path_entries(len(names))
        source_members[relative_root] = names
        for name in names:
            relative_path = _validated_release_tree_child_path(relative_root, name)
            display_path = display_root / Path(*relative_path.parts)
            if _release_tree_path_is_cache_artifact(relative_path):
                if require_sanitized_modes:
                    raise SyncError(
                        "immutable release drift: unexpected cache artifacts: "
                        f"{display_path}",
                        code="immutable-release-drift",
                    )
                raise SyncError(
                    f"release package contains unexpected cache artifacts: "
                    f"{display_path}"
                )
            try:
                named_metadata = os.stat(
                    name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
            except OSError as error:
                raise SyncError(
                    f"release tree changed while hashing: {display_path}"
                ) from error
            if (
                expected_owner_uid is not None
                and named_metadata.st_uid != expected_owner_uid
            ):
                raise _release_identity_policy_error(
                    display_path,
                    f"owner UID {named_metadata.st_uid} != expected UID "
                    f"{expected_owner_uid}",
                    mismatch=True,
                )
            snapshot = _release_source_snapshot(named_metadata)
            source_snapshots[relative_path] = snapshot
            if stat.S_ISDIR(named_metadata.st_mode):
                path_kinds[relative_path] = "directory"
                child_fd = -1
                try:
                    child_fd = os.open(
                        name,
                        _source_directory_flags(),
                        dir_fd=directory_fd,
                    )
                    snapshot = _require_release_source_unchanged(
                        snapshot,
                        os.fstat(child_fd),
                        display_path,
                        ignore_ctime=expected_owner_uid is not None,
                    )
                    visit_directory(child_fd, relative_path)
                    snapshot = _require_release_source_unchanged(
                        snapshot,
                        os.fstat(child_fd),
                        display_path,
                        ignore_ctime=expected_owner_uid is not None,
                    )
                    current_metadata = os.stat(
                        name,
                        dir_fd=directory_fd,
                        follow_symlinks=False,
                    )
                    if (
                        expected_owner_uid is not None
                        and current_metadata.st_uid != expected_owner_uid
                    ):
                        raise _release_identity_policy_error(
                            display_path,
                            f"owner UID {current_metadata.st_uid} != expected UID "
                            f"{expected_owner_uid}",
                            mismatch=True,
                        )
                    snapshot = _require_release_source_unchanged(
                        snapshot,
                        current_metadata,
                        display_path,
                        ignore_ctime=expected_owner_uid is not None,
                    )
                    source_snapshots[relative_path] = snapshot
                except OSError as error:
                    raise SyncError(
                        f"release tree changed while hashing: {display_path}"
                    ) from error
                finally:
                    if child_fd >= 0:
                        _close_fd_quietly(child_fd)
                continue
            if not stat.S_ISREG(named_metadata.st_mode):
                raise SyncError(f"refusing unsafe release tree entry: {display_path}")
            path_kinds[relative_path] = "file"
            file_fd = -1
            try:
                file_fd, opened_snapshot = _open_source_regular_file(
                    directory_fd,
                    name,
                    snapshot,
                    display_path,
                    ignore_ctime=expected_owner_uid is not None,
                )
                if expected_owner_uid is not None:
                    _require_release_identity_fd_access_policy(
                        file_fd,
                        display_path,
                        expected_owner_uid,
                    )
                resource_budget.reserve_file_bytes(
                    opened_snapshot.size,
                    display_path,
                )
                capture_limit = (
                    MAX_RELEASE_MANIFEST_BYTES
                    if relative_path == manifest_relative
                    else None
                )
                requested_limit = capture_limits.get(relative_path)
                if requested_limit is not None:
                    capture_limit = (
                        requested_limit
                        if capture_limit is None
                        else min(capture_limit, requested_limit)
                    )
                if capture_limit is not None and opened_snapshot.size > capture_limit:
                    description = (
                        "release manifest"
                        if relative_path == manifest_relative
                        else "release file"
                    )
                    raise SyncError(
                        f"{description} exceeds {capture_limit} bytes: {display_path}"
                    )
                file_identity, captured_payload = _hash_exact_regular_file(
                    file_fd,
                    opened_snapshot,
                    display_path,
                    capture_payload=capture_limit is not None,
                )
                opened_snapshot = replace(
                    opened_snapshot,
                    content_identity=file_identity,
                )
                source_snapshots[relative_path] = opened_snapshot
                if relative_path == manifest_relative:
                    assert captured_payload is not None
                    manifest_payload = captured_payload
                if relative_path in capture_limits:
                    assert captured_payload is not None
                    captured_files[relative_path] = captured_payload
                terminal_file_metadata = (
                    _require_release_identity_fd_access_policy(
                        file_fd,
                        display_path,
                        expected_owner_uid,
                    )
                    if expected_owner_uid is not None
                    else os.fstat(file_fd)
                )
                file_stage_rehash_used = False
                (
                    opened_snapshot,
                    file_stage_rehash_used,
                ) = _require_release_stage_source_unchanged(
                    opened_snapshot,
                    terminal_file_metadata,
                    display_path,
                    rehash_used=file_stage_rehash_used,
                    ignore_ctime=expected_owner_uid is not None,
                    file_descriptor=file_fd,
                    expected_owner_uid=expected_owner_uid,
                    operation="identity validation",
                )
                current_metadata = os.stat(
                    name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
                if (
                    expected_owner_uid is not None
                    and current_metadata.st_uid != expected_owner_uid
                ):
                    raise _release_identity_policy_error(
                        display_path,
                        f"owner UID {current_metadata.st_uid} != expected UID "
                        f"{expected_owner_uid}",
                        mismatch=True,
                    )
                (
                    opened_snapshot,
                    file_stage_rehash_used,
                ) = _require_release_stage_source_unchanged(
                    opened_snapshot,
                    current_metadata,
                    display_path,
                    rehash_used=file_stage_rehash_used,
                    ignore_ctime=expected_owner_uid is not None,
                    file_descriptor=file_fd,
                    expected_owner_uid=expected_owner_uid,
                    operation="identity validation",
                )
                source_snapshots[relative_path] = opened_snapshot
                record(
                    b"file",
                    relative_path,
                    normalized_mode(named_metadata, display_path),
                    file_identity,
                )
            except OSError as error:
                raise SyncError(
                    f"release tree changed while hashing: {display_path}"
                ) from error
            finally:
                if file_fd >= 0:
                    _close_fd_quietly(file_fd)
        current_names = _directory_member_names(
            directory_fd,
            maximum_entries=len(names),
            overflow_message=(
                f"release tree directory changed while hashing: {display_directory}"
            ),
        )
        if current_names != names:
            raise SyncError(
                f"release tree directory changed while hashing: {display_directory}"
            )
        terminal_directory_metadata = (
            _require_release_identity_fd_access_policy(
                directory_fd,
                display_directory,
                expected_owner_uid,
            )
            if expected_owner_uid is not None
            else os.fstat(directory_fd)
        )
        directory_snapshot = _require_release_source_unchanged(
            directory_snapshot,
            terminal_directory_metadata,
            display_directory,
            ignore_ctime=expected_owner_uid is not None,
        )
        if expected_owner_uid is not None:
            stable_names = _directory_member_names(
                directory_fd,
                maximum_entries=len(names),
                overflow_message=(
                    f"release tree directory changed while hashing: {display_directory}"
                ),
            )
            if stable_names != names:
                raise SyncError(
                    f"release tree directory changed while hashing: {display_directory}"
                )
            _require_release_directory_members_unchanged(
                directory_fd,
                relative_root,
                names,
                source_snapshots,
                (f"release tree directory changed while hashing: {display_directory}"),
            )
            stable_directory_metadata = _require_release_identity_fd_access_policy(
                directory_fd,
                display_directory,
                expected_owner_uid,
            )
            if not _release_source_matches(
                directory_snapshot,
                stable_directory_metadata,
            ):
                raise SyncError(
                    f"release tree changed while hashing: {display_directory}"
                )
        source_snapshots[relative_root] = directory_snapshot

    resource_budget.reserve_path_entries()
    try:
        visit_directory(root_fd, PurePosixPath())
    except RecursionError as error:
        raise SyncError("release tree exceeds safe traversal depth") from error
    if manifest_payload is None:
        raise SyncError(
            f"release manifest is missing: {display_root / MANIFEST_RELATIVE_PATH}"
        )
    return (
        manifest_payload,
        digest.hexdigest(),
        path_kinds,
        source_snapshots,
        source_members,
        captured_files,
    )


def _release_tree_digest_from_directory_fd(
    root_fd: int,
    display_root: Path,
    *,
    require_sanitized_modes: bool = False,
) -> str:
    _payload, _manifest, digest = _release_tree_identity_from_directory_fd(
        root_fd,
        display_root,
        require_sanitized_modes=require_sanitized_modes,
    )
    return digest


def _directory_member_names(
    directory_fd: int,
    *,
    maximum_entries: int | None = None,
    overflow_message: str = "directory exceeds entry limit",
) -> tuple[str, ...]:
    names: list[str] = []
    with os.scandir(directory_fd) as entries:
        for entry in entries:
            if maximum_entries is not None and len(names) >= maximum_entries:
                raise SyncError(overflow_message)
            names.append(entry.name)
    return tuple(sorted(names))


def _require_release_directory_members_unchanged(
    directory_fd: int,
    relative_root: PurePosixPath,
    expected_names: tuple[str, ...],
    source_snapshots: dict[PurePosixPath, _ReleaseSourceSnapshot],
    changed_message: str,
) -> None:
    for name in expected_names:
        relative_path = relative_root / name
        expected_snapshot = source_snapshots.get(relative_path)
        if expected_snapshot is None:
            raise SyncError(changed_message)
        try:
            current_metadata = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except OSError as error:
            raise SyncError(changed_message) from error
        if not _release_source_matches(expected_snapshot, current_metadata):
            raise SyncError(changed_message)


def _open_source_directory_entry(
    parent_fd: int,
    name: str,
    snapshot: _ReleaseSourceSnapshot,
    display_path: Path,
) -> int:
    child_fd = os.open(name, _source_directory_flags(), dir_fd=parent_fd)
    try:
        _require_release_source_unchanged(snapshot, os.fstat(child_fd), display_path)
        return child_fd
    except BaseException:
        _close_fd_quietly(child_fd)
        raise


def _copy_tree_from_directory_fd_with_budget(
    source_fd: int,
    destination_fd: int,
    display_root: Path,
    relative_root: PurePosixPath,
    source_snapshots: dict[PurePosixPath, _ReleaseSourceSnapshot],
    source_members: dict[PurePosixPath, tuple[str, ...]],
    resource_budget: _ReleaseTreeResourceBudget,
) -> None:
    display_directory = display_root / Path(*relative_root.parts)
    directory_metadata = os.fstat(source_fd)
    if not stat.S_ISDIR(directory_metadata.st_mode):
        raise SyncError(f"release source is not a directory: {display_directory}")
    directory_snapshot = _release_source_snapshot(directory_metadata)
    source_snapshots[relative_root] = directory_snapshot
    changed_message = (
        f"release source directory changed during copy: {display_directory}"
    )
    names = _directory_member_names(
        source_fd,
        maximum_entries=resource_budget.remaining_path_entries,
        overflow_message=(
            f"release tree exceeds {MAX_ARCHIVE_MEMBERS} path entry limit"
        ),
    )
    resource_budget.reserve_path_entries(len(names))
    source_members[relative_root] = names
    for name in names:
        relative_path = _validated_release_tree_child_path(relative_root, name)
        display_path = display_root / Path(*relative_path.parts)
        metadata = os.stat(name, dir_fd=source_fd, follow_symlinks=False)
        snapshot = _release_source_snapshot(metadata)
        source_snapshots[relative_path] = snapshot
        if stat.S_ISDIR(metadata.st_mode):
            child_source_fd = _open_source_directory_entry(
                source_fd,
                name,
                snapshot,
                display_path,
            )
            child_destination_fd = -1
            try:
                os.mkdir(name, mode=0o700, dir_fd=destination_fd)
                child_destination_fd = os.open(
                    name,
                    _source_directory_flags(),
                    dir_fd=destination_fd,
                )
                _copy_tree_from_directory_fd_with_budget(
                    child_source_fd,
                    child_destination_fd,
                    display_root,
                    relative_path,
                    source_snapshots,
                    source_members,
                    resource_budget,
                )
                os.fchmod(child_destination_fd, _sanitized_release_mode(metadata))
                os.fsync(child_destination_fd)
                _require_release_source_unchanged(
                    snapshot,
                    os.fstat(child_source_fd),
                    display_path,
                )
                current_metadata = os.stat(
                    name,
                    dir_fd=source_fd,
                    follow_symlinks=False,
                )
                _require_release_source_unchanged(
                    snapshot,
                    current_metadata,
                    display_path,
                )
            finally:
                _close_fd_quietly(child_source_fd)
                if child_destination_fd >= 0:
                    _close_fd_quietly(child_destination_fd)
            continue
        if not stat.S_ISREG(metadata.st_mode):
            raise SyncError(f"refusing unsafe release source entry: {display_path}")
        child_source_fd, opened_snapshot = _open_source_regular_file(
            source_fd,
            name,
            snapshot,
            display_path,
        )
        resource_budget.reserve_file_bytes(opened_snapshot.size, display_path)
        destination_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        destination_flags |= getattr(os, "O_CLOEXEC", 0)
        destination_flags |= getattr(os, "O_NOFOLLOW", 0)
        file_fd = -1
        try:
            file_fd = os.open(
                name,
                destination_flags,
                0o600,
                dir_fd=destination_fd,
            )
            _copy_bytes(
                child_source_fd,
                file_fd,
                opened_snapshot.size,
                display_path,
            )
            _require_release_source_unchanged(
                opened_snapshot,
                os.fstat(child_source_fd),
                display_path,
            )
            current_metadata = os.stat(
                name,
                dir_fd=source_fd,
                follow_symlinks=False,
            )
            _require_release_source_unchanged(
                opened_snapshot,
                current_metadata,
                display_path,
            )
            os.fchmod(file_fd, _sanitized_release_mode(metadata))
            os.fsync(file_fd)
        finally:
            _close_fd_quietly(child_source_fd)
            if file_fd >= 0:
                _close_fd_quietly(file_fd)
    if (
        _directory_member_names(
            source_fd,
            maximum_entries=len(names),
            overflow_message=changed_message,
        )
        != names
    ):
        raise SyncError(changed_message)
    _require_release_source_unchanged(
        directory_snapshot,
        os.fstat(source_fd),
        display_directory,
    )


def _copy_tree_from_directory_fd(
    source_fd: int,
    destination_fd: int,
    display_root: Path,
    relative_root: PurePosixPath,
    source_snapshots: dict[PurePosixPath, _ReleaseSourceSnapshot],
    source_members: dict[PurePosixPath, tuple[str, ...]],
) -> None:
    resource_budget = _ReleaseTreeResourceBudget()
    resource_budget.reserve_path_entries()
    try:
        _copy_tree_from_directory_fd_with_budget(
            source_fd,
            destination_fd,
            display_root,
            relative_root,
            source_snapshots,
            source_members,
            resource_budget,
        )
    except RecursionError as error:
        raise SyncError("release tree exceeds safe traversal depth") from error


def _source_metadata_at_relative(
    root_fd: int,
    relative_path: PurePosixPath,
) -> os.stat_result:
    if not relative_path.parts:
        return os.fstat(root_fd)
    parent_fd, name = _open_relative_parent_fd(root_fd, relative_path)
    try:
        return os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    finally:
        _close_fd_quietly(parent_fd)


def _source_directory_members_at_relative(
    root_fd: int,
    relative_path: PurePosixPath,
    *,
    maximum_entries: int | None = None,
    overflow_message: str = "directory exceeds entry limit",
) -> tuple[str, ...]:
    if not relative_path.parts:
        return _directory_member_names(
            root_fd,
            maximum_entries=maximum_entries,
            overflow_message=overflow_message,
        )
    parent_fd, name = _open_relative_parent_fd(root_fd, relative_path)
    directory_fd = -1
    try:
        directory_fd = os.open(name, _source_directory_flags(), dir_fd=parent_fd)
        return _directory_member_names(
            directory_fd,
            maximum_entries=maximum_entries,
            overflow_message=overflow_message,
        )
    finally:
        if directory_fd >= 0:
            _close_fd_quietly(directory_fd)
        _close_fd_quietly(parent_fd)


def _verify_release_source_snapshot(
    root_fd: int,
    display_root: Path,
    source_snapshots: dict[PurePosixPath, _ReleaseSourceSnapshot],
    source_members: dict[PurePosixPath, tuple[str, ...]],
    *,
    operation: str = "copy",
    expected_owner_uid: int | None = None,
) -> None:
    if sys.platform != "darwin":
        expected_owner_uid = None
    for relative_path, snapshot in source_snapshots.items():
        display_path = display_root / Path(*relative_path.parts)
        try:
            metadata = _source_metadata_at_relative(root_fd, relative_path)
        except OSError as error:
            raise SyncError(
                f"release source changed during {operation}: {display_path}"
            ) from error
        if expected_owner_uid is not None:
            if metadata.st_uid != expected_owner_uid:
                raise _release_identity_policy_error(
                    display_path,
                    f"owner UID {metadata.st_uid} != expected UID {expected_owner_uid}",
                    mismatch=True,
                )
            parent_fd = -1
            entry_fd = -1
            file_stage_rehash_used = False
            try:
                if not relative_path.parts:
                    entry_fd = os.dup(root_fd)
                else:
                    parent_fd, name = _open_relative_parent_fd(
                        root_fd,
                        relative_path,
                    )
                    flags = (
                        _source_directory_flags()
                        if stat.S_ISDIR(snapshot.mode)
                        else _source_regular_file_flags()
                    )
                    entry_fd = os.open(name, flags, dir_fd=parent_fd)
                opened_metadata = _require_release_identity_fd_access_policy(
                    entry_fd,
                    display_path,
                    expected_owner_uid,
                )
                (
                    snapshot,
                    file_stage_rehash_used,
                ) = _require_release_stage_source_unchanged(
                    snapshot,
                    opened_metadata,
                    display_path,
                    rehash_used=file_stage_rehash_used,
                    ignore_ctime=True,
                    file_descriptor=entry_fd,
                    expected_owner_uid=expected_owner_uid,
                    operation=operation,
                )
                if stat.S_ISDIR(snapshot.mode):
                    expected_names = source_members.get(relative_path)
                    if expected_names is None:
                        raise SyncError(
                            "release source directory identity is incomplete: "
                            f"{display_path}"
                        )
                    changed_message = (
                        "release source directory changed during "
                        f"{operation}: {display_path}"
                    )
                    current_names = _directory_member_names(
                        entry_fd,
                        maximum_entries=len(expected_names),
                        overflow_message=changed_message,
                    )
                    if current_names != expected_names:
                        raise SyncError(changed_message)
                terminal_opened_metadata = _require_release_identity_fd_access_policy(
                    entry_fd,
                    display_path,
                    expected_owner_uid,
                )
                (
                    snapshot,
                    file_stage_rehash_used,
                ) = _require_release_stage_source_unchanged(
                    snapshot,
                    terminal_opened_metadata,
                    display_path,
                    rehash_used=file_stage_rehash_used,
                    ignore_ctime=True,
                    file_descriptor=entry_fd,
                    expected_owner_uid=expected_owner_uid,
                    operation=operation,
                )
                if stat.S_ISDIR(snapshot.mode):
                    terminal_names = _directory_member_names(
                        entry_fd,
                        maximum_entries=len(expected_names),
                        overflow_message=changed_message,
                    )
                    if terminal_names != expected_names:
                        raise SyncError(changed_message)
                    stable_opened_metadata = _require_release_identity_fd_access_policy(
                        entry_fd,
                        display_path,
                        expected_owner_uid,
                    )
                    if not _release_source_matches(
                        snapshot,
                        stable_opened_metadata,
                    ):
                        raise SyncError(
                            f"release source changed during {operation}: {display_path}"
                        )
                terminal_named_metadata = (
                    os.fstat(entry_fd)
                    if not relative_path.parts
                    else os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                )
                if not _release_source_matches(
                    snapshot,
                    terminal_named_metadata,
                ):
                    raise SyncError(
                        f"release source changed during {operation}: {display_path}"
                    )
                source_snapshots[relative_path] = snapshot
            except OSError as error:
                raise SyncError(
                    f"release source changed during {operation}: {display_path}"
                ) from error
            finally:
                if entry_fd >= 0:
                    _close_fd_quietly(entry_fd)
                if parent_fd >= 0:
                    _close_fd_quietly(parent_fd)
        elif not _release_source_matches(snapshot, metadata):
            raise SyncError(
                f"release source changed during {operation}: {display_path}"
            )
    if expected_owner_uid is not None:
        for relative_path, expected_names in sorted(
            source_members.items(),
            key=lambda item: len(item[0].parts),
            reverse=True,
        ):
            snapshot = source_snapshots[relative_path]
            display_path = display_root / Path(*relative_path.parts)
            changed_message = (
                f"release source directory changed during {operation}: {display_path}"
            )
            parent_fd = -1
            entry_fd = -1
            try:
                if not relative_path.parts:
                    entry_fd = os.dup(root_fd)
                else:
                    parent_fd, name = _open_relative_parent_fd(
                        root_fd,
                        relative_path,
                    )
                    entry_fd = os.open(
                        name,
                        _source_directory_flags(),
                        dir_fd=parent_fd,
                    )
                opened_metadata = _require_release_identity_fd_access_policy(
                    entry_fd,
                    display_path,
                    expected_owner_uid,
                )
                snapshot = _require_release_source_unchanged(
                    snapshot,
                    opened_metadata,
                    display_path,
                    ignore_ctime=True,
                    operation=operation,
                )
                current_names = _directory_member_names(
                    entry_fd,
                    maximum_entries=len(expected_names),
                    overflow_message=changed_message,
                )
                if current_names != expected_names:
                    raise SyncError(changed_message)
                _require_release_directory_members_unchanged(
                    entry_fd,
                    relative_path,
                    expected_names,
                    source_snapshots,
                    changed_message,
                )
                stable_opened_metadata = _require_release_identity_fd_access_policy(
                    entry_fd,
                    display_path,
                    expected_owner_uid,
                )
                if not _release_source_matches(
                    snapshot,
                    stable_opened_metadata,
                ):
                    raise SyncError(changed_message)
                terminal_named_metadata = (
                    os.fstat(entry_fd)
                    if not relative_path.parts
                    else os.stat(
                        name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                )
                if not _release_source_matches(
                    snapshot,
                    terminal_named_metadata,
                ):
                    raise SyncError(changed_message)
                source_snapshots[relative_path] = snapshot
            except OSError as error:
                raise SyncError(changed_message) from error
            finally:
                if entry_fd >= 0:
                    _close_fd_quietly(entry_fd)
                if parent_fd >= 0:
                    _close_fd_quietly(parent_fd)
        return
    for relative_path, expected_names in source_members.items():
        display_path = display_root / Path(*relative_path.parts)
        changed_message = (
            f"release source directory changed during {operation}: {display_path}"
        )
        try:
            current_names = _source_directory_members_at_relative(
                root_fd,
                relative_path,
                maximum_entries=len(expected_names),
                overflow_message=changed_message,
            )
        except OSError as error:
            raise SyncError(changed_message) from error
        if current_names != expected_names:
            raise SyncError(changed_message)


def _named_entry_identity(parent_fd: int, name: str) -> tuple[int, int] | None:
    try:
        metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        return None
    return metadata.st_dev, metadata.st_ino


def _retain_named_entries(
    parent_fd: int,
    canonical_name: str,
    release_name: str,
) -> tuple[str, ...]:
    retained_entries: list[tuple[str, tuple[int, int]]] = []

    def verified_names() -> tuple[str, ...]:
        for retained_name, retained_identity in retained_entries:
            if _named_entry_identity(parent_fd, retained_name) != retained_identity:
                raise SyncError(
                    "retained release object changed during quarantine: "
                    f"{retained_name}"
                )
        return tuple(name for name, _identity in retained_entries)

    for attempt in range(100):
        identity = _named_entry_identity(parent_fd, canonical_name)
        if identity is None:
            return verified_names()
        retained_name = (
            f".retained-{release_name}-{os.getpid()}-{time.time_ns()}-{attempt}"
        )
        try:
            _rename_noreplace_at(
                parent_fd,
                canonical_name,
                parent_fd,
                retained_name,
            )
        except (FileExistsError, FileNotFoundError):
            continue
        retained_identity = _named_entry_identity(parent_fd, retained_name)
        if retained_identity is None:
            raise SyncError(
                f"retained release object disappeared during quarantine: {retained_name}"
            )
        # If the identity differs from the pre-rename observation, the canonical
        # name raced again. The atomic rename still preserved the object it moved;
        # record and revalidate that actual retained identity before returning.
        if (
            retained_identity != identity
            and _named_entry_identity(parent_fd, retained_name) != retained_identity
        ):
            raise SyncError(
                f"retained release object changed during quarantine: {retained_name}"
            )
        retained_entries.append((retained_name, retained_identity))
        if _named_entry_identity(parent_fd, canonical_name) is None:
            return verified_names()
    raise SyncError(
        f"could not conservatively clear changing release name: {canonical_name}"
    )


def _source_release_identity(
    source_root: Path,
    expected_manifest: ManifestData | None,
    expected_source: ReleaseTreeExpectation | None = None,
) -> ReleaseTreeExpectation:
    parent_fd, source_fd, source_root_snapshot = _open_release_source_root(source_root)
    try:
        identity = _release_tree_identity_from_directory_fd(source_fd, source_root)
        if expected_manifest is not None and identity[1] != expected_manifest:
            raise SyncError("release manifest changed after install preflight")
        source_expectation = (identity, _directory_identity(source_fd))
        if expected_source is not None and source_expectation != expected_source:
            raise SyncError("release source changed after its captured identity")
        _require_release_source_unchanged(
            source_root_snapshot,
            os.fstat(source_fd),
            source_root,
        )
        current_source_root = os.stat(
            source_root.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        _require_release_source_unchanged(
            source_root_snapshot,
            current_source_root,
            source_root,
        )
        return source_expectation
    except OSError as error:
        raise SyncError(
            f"release source changed during validation: {source_root}"
        ) from error
    finally:
        _close_fd_quietly(source_fd)
        _close_fd_quietly(parent_fd)


def read_expected_release_file(
    release_root: Path,
    relative_path: PurePosixPath,
    release_expectation: ReleaseTreeExpectation,
    *,
    maximum_bytes: int = MAX_ARCHIVE_MEMBER_BYTES,
) -> bytes:
    if isinstance(maximum_bytes, bool) or not isinstance(maximum_bytes, int):
        raise SyncError("release file byte limit must be an integer")
    if maximum_bytes < 0:
        raise SyncError("release file byte limit must be non-negative")
    if not isinstance(relative_path, PurePosixPath):
        raise SyncError("release file path must be a relative POSIX path")
    relative_path = _validate_relative_path(
        relative_path.as_posix(),
        "release file path",
    )
    parent_fd, release_fd, release_root_snapshot = _open_release_source_root(
        release_root
    )
    try:
        identity, captured_files = (
            _release_tree_identity_and_captured_files_from_directory_fd(
                release_fd,
                release_root,
                require_sanitized_modes=True,
                capture_limits={relative_path: maximum_bytes},
            )
        )
        observed_expectation = (identity, _directory_identity(release_fd))
        if observed_expectation != release_expectation:
            raise SyncError("release source changed after its captured identity")
        payload = captured_files.get(relative_path)
        if payload is None:
            raise SyncError(
                f"expected release file is missing: "
                f"{release_root / Path(*relative_path.parts)}"
            )
        _require_release_source_unchanged(
            release_root_snapshot,
            os.fstat(release_fd),
            release_root,
        )
        current_release_root = os.stat(
            release_root.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        _require_release_source_unchanged(
            release_root_snapshot,
            current_release_root,
            release_root,
        )
        return payload
    except OSError as error:
        raise SyncError(
            f"release source changed while reading expected file: {release_root}"
        ) from error
    finally:
        _close_fd_quietly(release_fd)
        _close_fd_quietly(parent_fd)


def _require_existing_release_matches_source(
    source_root: Path,
    home: Path,
    owner: str,
    sha: str,
    expected_manifest: ManifestData,
    expected_source: ReleaseTreeExpectation,
) -> ReleaseTreeExpectation:
    sha = _validate_release_sha(sha)
    release_root = _releases_root(home, owner) / sha
    if Path(os.path.abspath(source_root)) == Path(os.path.abspath(release_root)):
        source_expectation = _installed_release_identity_and_directory_identity(
            home,
            owner,
            sha,
        )
        if source_expectation != expected_source:
            raise SyncError("release source changed after its captured identity")
    else:
        source_expectation = _source_release_identity(
            source_root,
            expected_manifest,
            expected_source,
        )
    installed_identity, installed_directory_identity = (
        _installed_release_identity_and_directory_identity(home, owner, sha)
    )
    if Path(os.path.abspath(source_root)) == Path(os.path.abspath(release_root)):
        current_source_expectation = _installed_release_identity_and_directory_identity(
            home, owner, sha
        )
    else:
        current_source_expectation = _source_release_identity(
            source_root,
            expected_manifest,
            expected_source,
        )
    if (
        current_source_expectation != source_expectation
        or current_source_expectation != expected_source
    ):
        raise SyncError("incoming release source changed during identity validation")
    source_identity, _source_directory_identity = current_source_expectation
    current_installed_identity, current_directory_identity = (
        _installed_release_identity_and_directory_identity(home, owner, sha)
    )
    if (
        current_installed_identity != installed_identity
        or current_directory_identity != installed_directory_identity
    ):
        raise SyncError(
            "installed release changed during identity validation; "
            f"preserving installed release {owner}@{sha}"
        )
    installed_identity = current_installed_identity
    source_payload, source_manifest, source_tree_digest = source_identity
    installed_payload, installed_manifest, installed_tree_digest = installed_identity
    if source_manifest != expected_manifest:
        raise SyncError("release manifest changed after install preflight")
    if (
        installed_manifest != expected_manifest
        or installed_payload != source_payload
        or installed_tree_digest != source_tree_digest
    ):
        raise SyncError(
            "existing release tree does not match incoming source; "
            f"preserving installed release {owner}@{sha}",
            code="immutable-release-drift",
        )
    return source_identity, current_directory_identity


def _copy_release_tree(
    source_root: Path,
    release_dir: Path,
    home: Path,
    expected_manifest: ManifestData,
    expected_source: ReleaseTreeExpectation,
    expected_owner_uid: int | None,
) -> ReleaseTreeExpectation:
    source_parent_fd, source_fd, source_root_snapshot = _open_release_source_root(
        source_root
    )
    releases_root = release_dir.parent
    releases_fd = _open_or_create_directory_beneath(
        home,
        releases_root,
        mode=0o700,
    )
    temp_name = ""
    temp_fd = -1
    published = False
    try:
        if expected_owner_uid is not None:
            _require_release_identity_fd_access_policy(
                releases_fd,
                releases_root,
                expected_owner_uid,
            )
        (
            source_payload,
            source_manifest,
            source_tree_digest,
        ) = _release_tree_identity_from_directory_fd(
            source_fd,
            source_root,
        )
        current_source_expectation = (
            (source_payload, source_manifest, source_tree_digest),
            _directory_identity(source_fd),
        )
        if current_source_expectation != expected_source:
            raise SyncError("release source changed after its captured identity")
        if source_manifest != expected_manifest:
            raise SyncError("release manifest changed after install preflight")
        if not _bound_directory_matches(home, releases_root, releases_fd):
            raise SyncError(f"release parent changed before copy: {releases_root}")
        for attempt in range(100):
            temp_name = (
                f".tmp-{release_dir.name}-{os.getpid()}-{time.time_ns()}-{attempt}"
            )
            try:
                os.mkdir(temp_name, mode=0o700, dir_fd=releases_fd)
            except FileExistsError:
                continue
            break
        else:
            raise SyncError(
                f"could not allocate release staging directory: {release_dir}"
            )
        temp_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        temp_flags |= getattr(os, "O_CLOEXEC", 0)
        temp_flags |= getattr(os, "O_NOFOLLOW", 0)
        temp_fd = os.open(temp_name, temp_flags, dir_fd=releases_fd)
        staged_identity = _directory_identity(temp_fd)
        source_snapshots: dict[PurePosixPath, _ReleaseSourceSnapshot] = {}
        source_members: dict[PurePosixPath, tuple[str, ...]] = {}
        _copy_tree_from_directory_fd(
            source_fd,
            temp_fd,
            source_root,
            PurePosixPath(),
            source_snapshots,
            source_members,
        )
        _verify_release_source_snapshot(
            source_fd,
            source_root,
            source_snapshots,
            source_members,
        )
        _require_release_source_unchanged(
            source_root_snapshot,
            os.fstat(source_fd),
            source_root,
        )
        current_source_root = os.stat(
            source_root.name,
            dir_fd=source_parent_fd,
            follow_symlinks=False,
        )
        _require_release_source_unchanged(
            source_root_snapshot,
            current_source_root,
            source_root,
        )
        os.fchmod(temp_fd, _sanitized_release_mode(os.fstat(source_fd)))
        os.fsync(temp_fd)
        (
            staged_payload,
            staged_manifest,
            staged_tree_digest,
        ) = _release_tree_identity_with_owner_access_policy(
            temp_fd,
            release_dir,
            require_sanitized_modes=True,
            expected_owner_uid=expected_owner_uid,
        )
        if staged_payload != source_payload or staged_manifest != expected_manifest:
            raise SyncError("staged release manifest differs from install preflight")
        if staged_tree_digest != source_tree_digest:
            raise SyncError("staged release tree differs from install preflight")
        if not _bound_directory_matches(home, releases_root, releases_fd):
            raise SyncError(f"release parent changed during copy: {releases_root}")
        if _named_entry_identity(releases_fd, temp_name) != staged_identity:
            retained = _retain_named_entries(
                releases_fd,
                temp_name,
                release_dir.name,
            )
            temp_name = ""
            raise SyncError(
                "release staging changed before publication; canonical staging "
                f"was retained as {', '.join(retained) or 'an unknown name'}"
            )
        if expected_owner_uid is not None:
            _require_release_identity_fd_access_policy(
                releases_fd,
                releases_root,
                expected_owner_uid,
            )
        _rename_noreplace_at(
            releases_fd,
            temp_name,
            releases_fd,
            release_dir.name,
        )
        published = True
        temp_name = ""
        if _named_entry_identity(releases_fd, release_dir.name) != staged_identity:
            retained = _retain_named_entries(
                releases_fd,
                release_dir.name,
                release_dir.name,
            )
            os.fsync(releases_fd)
            raise SyncError(
                "published release changed during install; canonical object was "
                f"retained as {', '.join(retained) or 'an unknown name'}"
            )
        published_fd = -1
        try:
            published_fd = os.open(
                release_dir.name,
                _source_directory_flags(),
                dir_fd=releases_fd,
            )
            if _directory_identity(published_fd) != staged_identity:
                raise SyncError("published release identity differs from staging")
            if expected_owner_uid is not None:
                _require_release_identity_fd_access_policy(
                    releases_fd,
                    releases_root,
                    expected_owner_uid,
                )
            (
                published_payload,
                published_manifest,
                published_tree_digest,
            ) = _release_tree_identity_with_owner_access_policy(
                published_fd,
                release_dir,
                require_sanitized_modes=True,
                expected_owner_uid=expected_owner_uid,
            )
            if (
                published_payload != source_payload
                or published_manifest != expected_manifest
            ):
                raise SyncError(
                    "published release manifest differs from install preflight"
                )
            if published_tree_digest != source_tree_digest:
                raise SyncError("published release tree differs from install preflight")
        except OSError as error:
            raise SyncError("published release changed during validation") from error
        finally:
            if published_fd >= 0:
                _close_fd_quietly(published_fd)
        os.fsync(releases_fd)
        if not _bound_directory_matches(home, releases_root, releases_fd):
            retained = _retain_named_entries(
                releases_fd,
                release_dir.name,
                release_dir.name,
            )
            os.fsync(releases_fd)
            raise SyncError(
                "release parent changed during publication; staged tree was retained "
                f"as {', '.join(retained) or 'an unknown name'}"
            )
        if _named_entry_identity(releases_fd, release_dir.name) != staged_identity:
            retained = _retain_named_entries(
                releases_fd,
                release_dir.name,
                release_dir.name,
            )
            os.fsync(releases_fd)
            raise SyncError(
                "published release changed after verification; canonical object was "
                f"retained as {', '.join(retained) or 'an unknown name'}"
            )
        if expected_owner_uid is not None:
            _require_release_identity_fd_access_policy(
                releases_fd,
                releases_root,
                expected_owner_uid,
            )
        return (
            (source_payload, source_manifest, source_tree_digest),
            staged_identity,
        )
    except BaseException:
        if temp_name:
            try:
                _retain_named_entries(releases_fd, temp_name, release_dir.name)
            except (OSError, SyncError) as retain_error:
                raise SyncError(
                    "release installation failed and staging retention was incomplete"
                ) from retain_error
            temp_name = ""
        if published:
            try:
                _retain_named_entries(
                    releases_fd,
                    release_dir.name,
                    release_dir.name,
                )
            except (OSError, SyncError) as retain_error:
                raise SyncError(
                    "release installation failed and publication retention was incomplete"
                ) from retain_error
        raise
    finally:
        if temp_fd >= 0:
            _close_fd_quietly(temp_fd)
        _close_fd_quietly(releases_fd)
        _close_fd_quietly(source_fd)
        _close_fd_quietly(source_parent_fd)


def _ensure_install_roots(home: Path, owner: str) -> None:
    _ensure_safe_internal_directory(
        home,
        _releases_root(home, owner),
        create=True,
    )


def _ensure_current_can_switch(home: Path, owner: str) -> None:
    current = _current_link(home, owner)
    if not _ensure_safe_internal_parent(
        home,
        current,
        create=False,
        allow_missing=True,
    ):
        return
    if _path_exists_or_is_link(current) and not stat.S_ISLNK(os.lstat(current).st_mode):
        raise SyncError(f"refusing to replace non-symlink current pointer: {current}")


def _plan_current_switch_action(
    home: Path,
    sha: str,
    owner: str = PUBLIC_OWNER,
) -> ReconcileAction | None:
    sha = _validate_release_sha(sha)
    current = _current_link(home, owner)
    _ensure_current_can_switch(home, owner)
    next_target = f"releases/{sha}"
    planned_snapshot = _capture_reconcile_target_snapshot(home, current)
    if planned_snapshot.link_identity is None:
        return ReconcileAction(
            "create",
            current,
            next_target,
            "directory",
            planned_snapshot=planned_snapshot,
        )
    previous_target = planned_snapshot.link_target
    if previous_target is None:
        raise SyncError(f"refusing unsafe current pointer: {current}")
    if previous_target == next_target:
        return None
    return ReconcileAction(
        "replace",
        current,
        next_target,
        "directory",
        expected_link_target=previous_target,
        planned_snapshot=planned_snapshot,
    )


def _plan_current_switch_actions(
    home: Path,
    releases: list[tuple[Path, str, ManifestData, ReleaseTreeExpectation]],
) -> list[ReconcileAction]:
    actions: list[ReconcileAction] = []
    seen_owners: set[str] = set()
    for _source_root, sha, manifest, _source_expectation in releases:
        sha = _validate_release_sha(sha)
        if manifest.owner in seen_owners:
            raise SyncError(f"duplicate release owner in install set: {manifest.owner}")
        seen_owners.add(manifest.owner)
        action = _plan_current_switch_action(home, sha, manifest.owner)
        if action is not None:
            actions.append(action)
    return actions


def _plan_current_switch_capacity_actions(
    home: Path,
    releases: list[tuple[Path, str, ManifestData, ReleaseTreeExpectation]],
) -> list[ReconcileAction]:
    actions: list[ReconcileAction] = []
    seen_owners: set[str] = set()
    for _source_root, sha, manifest, _source_expectation in releases:
        sha = _validate_release_sha(sha)
        if manifest.owner in seen_owners:
            raise SyncError(f"duplicate release owner in install set: {manifest.owner}")
        seen_owners.add(manifest.owner)
        actions.append(
            ReconcileAction(
                "replace",
                _current_link(home, manifest.owner),
                f"releases/{sha}",
                "directory",
                expected_link_target=_MAX_PENDING_LINK_TARGET,
            )
        )
    return actions


def _switch_current(
    home: Path,
    sha: str,
    owner: str = PUBLIC_OWNER,
    *,
    dry_run: bool,
) -> None:
    current = _current_link(home, owner)
    if dry_run and not _path_exists_or_is_link(home):
        print(f"would switch {current} -> releases/{sha}")
        return
    action = _plan_current_switch_action(home, sha, owner)
    if action is None:
        print(f"current pointer already uses releases/{sha}: {current}")
        return
    if dry_run:
        print(f"would switch {current} -> releases/{sha}")
        return
    transaction = _apply_reconcile_actions(home, [action], dry_run=False)
    _commit_reconcile_transaction(transaction)
    print(f"switched {current} -> releases/{sha}")


def _installed_manifests(
    home: Path,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> dict[str, ManifestData]:
    manifests: dict[str, ManifestData] = {}
    for owner in sorted(_known_owners(home)):
        if _current_sha(home, owner) is None:
            continue
        manifests[owner] = _current_manifest_data(
            home,
            owner,
            manifest_cache=manifest_cache,
        )
    return manifests


def _capture_active_release_expectations(
    home: Path,
    manifests: dict[str, ManifestData],
) -> dict[str, ActiveReleaseExpectation]:
    active: dict[str, ActiveReleaseExpectation] = {}
    for owner, manifest in sorted(manifests.items()):
        sha = _current_sha(home, owner)
        if sha is None:
            raise SyncError(f"current release is missing for owner {owner}")
        expectation = _installed_release_identity_and_directory_identity(
            home,
            owner,
            sha,
        )
        current_sha = _current_sha(home, owner)
        if current_sha != sha:
            raise SyncError(
                f"current release changed during identity capture for owner {owner}"
            )
        if expectation[0][1] != manifest:
            raise SyncError(
                f"current release manifest changed during identity capture for owner {owner}"
            )
        active[owner] = ActiveReleaseExpectation(
            owner=owner,
            sha=sha,
            manifest=manifest,
            expectation=expectation,
        )
    return active


def _open_install_release_directory_chains(
    home: Path,
    bindings: dict[str, InstallReleaseBinding],
    expected_owner_uid: int,
) -> _InstallReleaseDirectoryChains:
    for owner, binding in bindings.items():
        if binding.owner != owner:
            raise SyncError(
                f"install release policy binding mismatch for owner {owner}"
            )
    ordered_bindings = tuple(binding for _owner, binding in sorted(bindings.items()))
    expected_ancestor_paths = _install_release_strict_ancestor_paths(
        home,
        ordered_bindings,
        expected_owner_uid,
    )
    ancestors: list[_ReleaseIdentityDirectoryBinding] = []
    ancestors_by_path: dict[Path, _ReleaseIdentityDirectoryBinding] = {}
    current_path = home
    try:
        for current_path in expected_ancestor_paths:
            if current_path == home:
                file_descriptor = _bound_sync_home_anchor(home, None)
            else:
                parent_binding = ancestors_by_path.get(current_path.parent)
                if parent_binding is None:
                    raise SyncError(
                        "install release ancestor set is not prefix-complete: "
                        f"{current_path}"
                    )
                file_descriptor = os.open(
                    current_path.name,
                    _source_directory_flags(),
                    dir_fd=parent_binding.file_descriptor,
                )
            try:
                metadata = _require_release_identity_fd_access_policy(
                    file_descriptor,
                    current_path,
                    expected_owner_uid,
                )
                if not stat.S_ISDIR(metadata.st_mode):
                    raise _release_identity_policy_error(
                        current_path,
                        "bound install ancestor is not a directory",
                        mismatch=True,
                    )
            except BaseException:
                _close_fd_quietly(file_descriptor)
                raise
            ancestor = _ReleaseIdentityDirectoryBinding(
                path=current_path,
                file_descriptor=file_descriptor,
                identity=(metadata.st_dev, metadata.st_ino),
            )
            ancestors.append(ancestor)
            ancestors_by_path[current_path] = ancestor
        _require_release_identity_directory_bindings(
            home,
            ancestors,
            expected_owner_uid,
        )
        return _InstallReleaseDirectoryChains(
            bindings=ordered_bindings,
            ancestors=tuple(ancestors),
        )
    except BaseException as error:
        _close_release_identity_directory_bindings(ancestors)
        if isinstance(error, OSError):
            raise _release_identity_policy_error(
                current_path,
                f"cannot open install release ancestor: {error}",
                mismatch=False,
            ) from error
        raise


def _install_release_strict_ancestor_paths(
    home: Path,
    bindings: tuple[InstallReleaseBinding, ...],
    expected_owner_uid: int,
) -> tuple[Path, ...]:
    expected_paths = {home}
    seen_owners: set[str] = set()
    for binding in bindings:
        if (
            binding.owner in seen_owners
            or binding.expected_owner_uid != expected_owner_uid
            or binding.releases_root != _releases_root(home, binding.owner)
        ):
            raise SyncError(
                f"install release policy binding mismatch for owner {binding.owner}"
            )
        seen_owners.add(binding.owner)
        release_root = binding.releases_root / binding.sha
        parts = _directory_parts_beneath(home, release_root)
        if len(parts) < 2 or parts[-2:] != ("releases", binding.sha):
            raise SyncError(f"install release path mismatch for owner {binding.owner}")
        current_path = home
        for part in parts[:-2]:
            current_path /= part
            expected_paths.add(current_path)
    return tuple(
        sorted(
            expected_paths,
            key=lambda path: (
                len(path.relative_to(home).parts),
                path.relative_to(home).parts,
            ),
        )
    )


def _require_install_release_directory_chains(
    home: Path,
    chains: _InstallReleaseDirectoryChains,
    expected_owner_uid: int,
) -> None:
    expected_paths = _install_release_strict_ancestor_paths(
        home,
        chains.bindings,
        expected_owner_uid,
    )
    actual_paths = tuple(ancestor.path for ancestor in chains.ancestors)
    if actual_paths != expected_paths or len(set(actual_paths)) != len(actual_paths):
        raise SyncError("install release ancestor binding set mismatch")
    _require_release_identity_directory_bindings(
        home,
        list(chains.ancestors),
        expected_owner_uid,
    )
    for binding in chains.bindings:
        _verify_install_release_canonical_binding(home, binding)


def _close_install_release_directory_chains(
    chains: _InstallReleaseDirectoryChains | None,
) -> None:
    if chains is None:
        return
    _close_release_identity_directory_bindings(list(chains.ancestors))


def _probe_install_release_fd_headroom(
    chains: _InstallReleaseDirectoryChains,
) -> None:
    if not chains.ancestors:
        raise SyncError("install release ancestor binding set is empty")
    probe_fds: list[int] = []
    try:
        for _index in range(MAX_ARCHIVE_MEMBER_PATH_DEPTH + 16):
            probe_fds.append(os.dup(chains.ancestors[0].file_descriptor))
    except OSError as error:
        raise SyncError(
            "insufficient file descriptor headroom for install transaction"
        ) from error
    finally:
        for file_descriptor in reversed(probe_fds):
            _close_fd_quietly(file_descriptor)


def _verify_install_release_canonical_binding(
    home: Path,
    binding: InstallReleaseBinding,
) -> None:
    if binding.expected_owner_uid is not None:
        _require_release_identity_fd_access_policy(
            binding.releases_fd,
            binding.releases_root,
            binding.expected_owner_uid,
        )
        _require_release_identity_fd_access_policy(
            binding.release_fd,
            binding.releases_root / binding.sha,
            binding.expected_owner_uid,
        )
    if not _bound_directory_matches(
        home,
        binding.releases_root,
        binding.releases_fd,
    ):
        raise SyncError("release parent identity mismatch")
    if (
        _named_entry_identity(binding.releases_fd, binding.sha)
        != binding.expected_directory_identity
    ):
        raise SyncError("canonical release directory identity mismatch")
    if _directory_identity(binding.release_fd) != binding.expected_directory_identity:
        raise SyncError("bound release directory identity mismatch")


def _current_release_binding_snapshot(
    home: Path,
    binding: InstallReleaseBinding,
) -> SymlinkSnapshot:
    current = _current_link(home, binding.owner)
    snapshot = _read_symlink_snapshot_beneath(home, current)
    if snapshot.link_target != f"releases/{binding.sha}":
        raise SyncError(f"current release mismatch for owner {binding.owner}")
    return snapshot


def _verify_install_release_binding(
    home: Path,
    binding: InstallReleaseBinding,
    *,
    phase: str,
    verify_current: bool,
) -> None:
    try:
        current_snapshot = (
            _current_release_binding_snapshot(home, binding) if verify_current else None
        )
        _verify_install_release_canonical_binding(home, binding)
        release_root = binding.releases_root / binding.sha
        current_identity = _release_tree_identity_with_owner_access_policy(
            binding.release_fd,
            release_root,
            require_sanitized_modes=True,
            expected_owner_uid=binding.expected_owner_uid,
        )
        if current_identity != binding.expected_identity:
            raise SyncError("complete release identity mismatch")
        if verify_current:
            assert current_snapshot is not None
            if _current_release_binding_snapshot(home, binding) != current_snapshot:
                raise SyncError(
                    f"current release changed during identity validation for owner "
                    f"{binding.owner}"
                )
        _verify_install_release_canonical_binding(home, binding)
    except (OSError, SyncError) as error:
        raise SyncError(
            f"release tree changed {phase}; raced release "
            f"{binding.owner}@{binding.sha} was left in place",
            code=error.code if isinstance(error, SyncError) else None,
        ) from error


def _verify_install_release_binding_lightweight(
    home: Path,
    binding: InstallReleaseBinding,
    *,
    phase: str,
    verify_current: bool,
) -> None:
    try:
        current_snapshot = (
            _current_release_binding_snapshot(home, binding) if verify_current else None
        )
        _verify_install_release_canonical_binding(home, binding)
        if binding.expected_owner_uid is not None:
            release_root = binding.releases_root / binding.sha
            current_identity = _release_tree_identity_with_owner_access_policy(
                binding.release_fd,
                release_root,
                require_sanitized_modes=True,
                expected_owner_uid=binding.expected_owner_uid,
            )
            if current_identity != binding.expected_identity:
                raise SyncError("complete release identity mismatch")
        if verify_current:
            assert current_snapshot is not None
            if _current_release_binding_snapshot(home, binding) != current_snapshot:
                raise SyncError(
                    f"current release changed during final validation for owner "
                    f"{binding.owner}"
                )
        _verify_install_release_canonical_binding(home, binding)
    except (OSError, SyncError) as error:
        raise SyncError(
            f"release tree changed {phase}; raced release "
            f"{binding.owner}@{binding.sha} was left in place",
            code=error.code if isinstance(error, SyncError) else None,
        ) from error


def _open_install_release_binding(
    home: Path,
    owner: str,
    sha: str,
    expectation: ReleaseTreeExpectation,
    expected_owner_uid: int | None = None,
) -> InstallReleaseBinding:
    expected_identity, expected_directory_identity = expectation
    releases_root = _releases_root(home, owner)
    releases_fd = _open_directory_beneath(home, releases_root)
    release_fd = -1
    try:
        release_fd = os.open(
            sha,
            _source_directory_flags(),
            dir_fd=releases_fd,
        )
        binding = InstallReleaseBinding(
            owner=owner,
            sha=sha,
            expected_identity=expected_identity,
            expected_directory_identity=expected_directory_identity,
            expected_owner_uid=expected_owner_uid,
            releases_root=releases_root,
            releases_fd=releases_fd,
            release_fd=release_fd,
        )
        _verify_install_release_binding(
            home,
            binding,
            phase="while binding staged release",
            verify_current=False,
        )
        return binding
    except BaseException:
        if release_fd >= 0:
            _close_fd_quietly(release_fd)
        _close_fd_quietly(releases_fd)
        raise


def _close_install_release_bindings(
    releases: list[InstallReleaseBinding],
) -> None:
    for binding in releases:
        if binding.release_fd >= 0:
            _close_fd_quietly(binding.release_fd)
            binding.release_fd = -1
        if binding.releases_fd >= 0:
            _close_fd_quietly(binding.releases_fd)
            binding.releases_fd = -1


def _open_active_release_bindings(
    home: Path,
    active: dict[str, ActiveReleaseExpectation],
    expected_owner_uid: int | None = None,
) -> dict[str, InstallReleaseBinding]:
    bindings: dict[str, InstallReleaseBinding] = {}
    try:
        for owner, release in sorted(active.items()):
            bindings[owner] = _open_install_release_binding(
                home,
                owner,
                release.sha,
                release.expectation,
                expected_owner_uid,
            )
        return bindings
    except BaseException:
        _close_install_release_bindings(list(bindings.values()))
        raise


def _verify_install_release_identities(
    home: Path,
    releases: list[InstallReleaseBinding],
    *,
    phase: str,
    verify_current: bool,
) -> None:
    for binding in releases:
        _verify_install_release_binding(
            home,
            binding,
            phase=phase,
            verify_current=verify_current,
        )


def _verify_install_release_bindings_lightweight(
    home: Path,
    releases: list[InstallReleaseBinding],
    *,
    phase: str,
    verify_current: bool,
) -> None:
    for binding in releases:
        _verify_install_release_binding_lightweight(
            home,
            binding,
            phase=phase,
            verify_current=verify_current,
        )


def _owner_shas_from_bound_current_releases(
    home: Path,
    next_manifests: dict[str, ManifestData],
    expected_shas: dict[str, str],
    bindings: dict[str, InstallReleaseBinding],
    *,
    phase: str,
) -> dict[str, str]:
    next_owners = set(next_manifests)
    owner_shas = {
        owner: expected_shas[owner]
        for owner in sorted(next_owners)
        if owner in expected_shas
    }
    if set(owner_shas) != next_owners:
        missing = next_owners.difference(owner_shas)
        raise SyncError(
            "trusted release SHA is missing for owner(s): " + ", ".join(sorted(missing))
        )
    if set(bindings) != next_owners:
        missing = next_owners.difference(bindings)
        unexpected = set(bindings).difference(next_owners)
        details: list[str] = []
        if missing:
            details.append("missing " + ", ".join(sorted(missing)))
        if unexpected:
            details.append("unexpected " + ", ".join(sorted(unexpected)))
        raise SyncError("current release binding owner mismatch: " + "; ".join(details))
    for owner in sorted(next_owners):
        binding = bindings[owner]
        expected_sha = owner_shas[owner]
        if binding.owner != owner or binding.sha != expected_sha:
            raise SyncError(
                f"current release binding mismatch for owner {owner}: "
                f"expected {expected_sha}, got {binding.owner}@{binding.sha}"
            )
        try:
            _verify_install_release_binding_lightweight(
                home,
                binding,
                phase=phase,
                verify_current=True,
            )
        except SyncError as error:
            raise SyncError(
                f"current release changed {phase} for owner {owner}",
                code=error.code,
            ) from error
    return owner_shas


def _normalize_install_releases(
    releases: list[
        tuple[Path, str, ManifestData]
        | tuple[
            Path,
            str,
            ManifestData,
            ReleaseTreeExpectation | None,
        ]
    ],
) -> list[tuple[Path, str, ManifestData, ReleaseTreeExpectation | None]]:
    normalized: list[tuple[Path, str, ManifestData, ReleaseTreeExpectation | None]] = []
    for release in releases:
        if len(release) == 3:
            source_root, sha, manifest = release
            source_expectation = None
        elif len(release) == 4:
            source_root, sha, manifest, source_expectation = release
        else:
            raise SyncError("install release tuple must contain three or four values")
        sha = _validate_release_sha(sha)
        normalized.append((source_root, sha, manifest, source_expectation))
    return normalized


def _resolve_install_release_expectations(
    releases: list[tuple[Path, str, ManifestData, ReleaseTreeExpectation | None]],
) -> list[tuple[Path, str, ManifestData, ReleaseTreeExpectation]]:
    resolved: list[tuple[Path, str, ManifestData, ReleaseTreeExpectation]] = []
    for source_root, sha, manifest, source_expectation in releases:
        if source_expectation is None:
            source_expectation = _source_release_identity(source_root, manifest)
        else:
            source_expectation = _source_release_identity(
                source_root,
                manifest,
                source_expectation,
            )
        resolved.append((source_root, sha, manifest, source_expectation))
    return resolved


def _preflight_pending_recovery(
    home: Path,
    *,
    dry_run: bool,
    cleanup_budget: PendingCleanupActionBudget | None = None,
) -> bool:
    home = home.expanduser()
    _require_no_pending_unresolved_ticket_representations(home)
    action_budget = cleanup_budget or PendingCleanupActionBudget(
        MAX_PENDING_CLEANUP_BATCHES_PER_RUN
    )
    observed_failed_move_isolation = _recover_failed_move_isolation(
        home,
        dry_run=True,
    )
    observed_retention_transaction = None
    observed_cleanup_ready_batch = False
    observed_pending_transaction = False
    if not observed_failed_move_isolation:
        observed_retention_transaction = _recover_release_retention_transaction(
            home,
            dry_run=True,
        )
        observed_cleanup_ready_batch = _pending_cleanup_ready_batch_is_observed(
            home,
            allow_v8_control_recovery=not dry_run,
        )
        loaded_state, initial_state_snapshot = _load_managed_state_with_snapshot(home)
        (
            _loaded_state,
            _initial_state_snapshot,
            observed_pending_transaction,
        ) = _recover_pending_link_transaction(
            home,
            loaded_state,
            initial_state_snapshot,
            dry_run=True,
        )
    if (
        not observed_failed_move_isolation
        and not observed_retention_transaction
        and not observed_pending_transaction
        and not observed_cleanup_ready_batch
    ):
        return False
    if dry_run:
        if observed_failed_move_isolation:
            print("would recover failed move isolation under the install lock")
            return True
        if observed_pending_transaction:
            print(
                "would recover pending personal sync transaction under the install lock"
            )
        if observed_cleanup_ready_batch:
            print(
                "would clean a finalized or interrupted pending transaction under "
                "the install lock"
            )
        return True
    with installation_lock(home):
        recovered_failed_move_isolation = _recover_failed_move_isolation(
            home,
            dry_run=False,
        )
        recovered_retention_transaction = _recover_release_retention_transaction(
            home,
            dry_run=False,
        )
        cleaned_pending_batches = _cleanup_ready_pending_batches(
            home,
            budget=action_budget,
        )
        loaded_state, initial_state_snapshot = _load_managed_state_with_snapshot(home)
        (
            _loaded_state,
            _initial_state_snapshot,
            recovered_pending_transaction,
        ) = _recover_pending_link_transaction(
            home,
            loaded_state,
            initial_state_snapshot,
            dry_run=False,
        )
    return bool(
        recovered_failed_move_isolation
        or recovered_retention_transaction is not None
        or recovered_pending_transaction
        or cleaned_pending_batches
    )


def _install_release_set_unlocked(
    home: Path,
    releases: list[
        tuple[Path, str, ManifestData]
        | tuple[
            Path,
            str,
            ManifestData,
            ReleaseTreeExpectation | None,
        ]
    ],
    *,
    dry_run: bool,
    allow_cross_owner: bool,
    preflight_only: bool = False,
    cleanup_budget: PendingCleanupActionBudget | None = None,
) -> None:
    releases = _normalize_install_releases(releases)
    home = home.expanduser()
    _require_no_pending_unresolved_ticket_representations(home)
    action_budget = cleanup_budget or PendingCleanupActionBudget(
        MAX_PENDING_CLEANUP_BATCHES_PER_RUN
    )
    expected_owner_uid = os.geteuid() if sys.platform == "darwin" else None
    recovered_retention_transaction = _recover_release_retention_transaction(
        home,
        dry_run=dry_run or preflight_only,
    )
    if recovered_retention_transaction and (dry_run or preflight_only):
        return
    observed_cleanup_ready_batch = _pending_cleanup_ready_batch_is_observed(
        home,
        allow_v8_control_recovery=not (dry_run or preflight_only),
    )
    if observed_cleanup_ready_batch and (dry_run or preflight_only):
        if not preflight_only:
            print(
                "would clean a finalized or interrupted pending transaction under "
                "the install lock"
            )
        return
    if not dry_run and not preflight_only:
        _cleanup_ready_pending_batches(home, budget=action_budget)
    loaded_state, initial_state_snapshot = _load_managed_state_with_snapshot(home)
    (
        loaded_state,
        initial_state_snapshot,
        recovered_pending_transaction,
    ) = _recover_pending_link_transaction(
        home,
        loaded_state,
        initial_state_snapshot,
        dry_run=dry_run or preflight_only,
    )
    if recovered_pending_transaction and (dry_run or preflight_only):
        if not preflight_only:
            print(
                "would recover pending personal sync transaction under the install lock"
            )
        return
    if not dry_run and not preflight_only:
        _require_no_pending_terminal_mutation_authority(home)
    install_owners = set(loaded_state.owners)
    install_owners.update(
        manifest.owner for _source_root, _sha, manifest, _source_expectation in releases
    )
    _known_owners(home, install_owners)
    _verify_managed_state_current_owner_claims(home, loaded_state)
    current_manifests = _installed_manifests(home)
    next_manifests = dict(current_manifests)
    for _source_root, _sha, manifest, _source_expectation in releases:
        next_manifests[manifest.owner] = manifest
    incoming_shas = {
        manifest.owner: sha
        for _source_root, sha, manifest, _source_expectation in releases
    }
    incoming_regular_sources = {
        (entry.owner, entry.target): source_root / Path(*entry.source.parts)
        for source_root, _sha, manifest, _source_expectation in releases
        for entry in manifest.entries
        if _entry_materializes_regular_file(entry)
    }
    _validate_install_target_portability(current_manifests, next_manifests)
    releases = _resolve_install_release_expectations(releases)
    active_expectations = _capture_active_release_expectations(
        home,
        current_manifests,
    )
    expected_next_shas = {
        owner: expectation.sha
        for owner, expectation in active_expectations.items()
        if owner in next_manifests
    }
    expected_next_shas.update(
        {owner: sha for owner, sha in incoming_shas.items() if owner in next_manifests}
    )
    _validate_planned_overlay_base_release_shas(
        next_manifests,
        expected_next_shas.get(PUBLIC_OWNER),
    )
    public_manifest = next_manifests.get(PUBLIC_OWNER)
    if public_manifest is None:
        if len(next_manifests) != 1:
            raise SyncError("overlay installation requires an installed public base")
        only_manifest = next(iter(next_manifests.values()))
        if only_manifest.owner != PUBLIC_OWNER:
            raise SyncError("overlay installation requires an installed public base")
        public_manifest = only_manifest
    overlay_manifests = [
        manifest
        for owner, manifest in sorted(next_manifests.items())
        if owner != PUBLIC_OWNER
    ]
    desired_entries = _combine_entries(public_manifest.entries, overlay_manifests)
    removed_links = _combine_removed_links(list(next_manifests.values()))
    _validate_active_replacements(
        home,
        current_manifests,
        next_manifests,
        desired_entries,
    )
    previous_entries = [
        entry for manifest in current_manifests.values() for entry in manifest.entries
    ]
    # Recovery returns the exact restored or committed state snapshot. If that
    # snapshot is absent, this remains a first bootstrap even when the pending
    # transaction appeared after the unlocked preflight.
    bootstrap_history = not initial_state_snapshot.exists
    state = _refresh_managed_state_from_current(
        home,
        loaded_state,
        bootstrap_history=bootstrap_history,
    )
    baseline_link_snapshots = _capture_managed_state_link_snapshots(home, state)
    actions = _plan_reconciliation(
        home,
        desired_entries,
        previous_entries,
        removed_links,
        state,
        allow_cross_owner=allow_cross_owner,
        allow_unledgered_removed_links=bootstrap_history,
        owner_shas=expected_next_shas,
        incoming_regular_sources=incoming_regular_sources,
    )
    _verify_managed_state_link_claims(home, state, actions)
    link_actions = [
        action
        for action in actions
        if action.action != PENDING_RELINQUISH_FOREIGN_ACTION
    ]
    required_replacements = _required_replacements_for_removals(
        home,
        link_actions,
        removed_links,
        desired_entries,
    )
    managed_targets = _managed_targets_after_reconciliation(home, state, actions)

    for source_root, sha, manifest, source_expectation in releases:
        _ensure_current_can_switch(home, manifest.owner)
        release_dir = _releases_root(home, manifest.owner) / sha
        if _path_exists_or_is_link(release_dir):
            _require_existing_release_matches_source(
                source_root,
                home,
                manifest.owner,
                sha,
                manifest,
                source_expectation,
            )
        if dry_run and not preflight_only:
            print(f"would install release {sha} into {release_dir}")
            _switch_current(home, sha, manifest.owner, dry_run=True)

    capacity_current_actions = _plan_current_switch_capacity_actions(
        home,
        releases,
    )
    planned_next_state = _planned_committed_state(
        home,
        desired_entries,
        expected_next_shas,
        managed_targets,
    )
    if not _canonical_managed_state_matches_snapshot(home, initial_state_snapshot):
        raise SyncError("managed state changed before install capacity validation")
    capacity_state_before = _managed_state_value_from_snapshot(
        home,
        initial_state_snapshot,
    )
    _build_pending_link_capacity_plan(
        home,
        [("current", capacity_current_actions), ("managed", actions)],
        initial_state_snapshot,
        capacity_state_before,
        state,
        planned_next_state,
        required_replacements_by_scope={
            "managed": required_replacements,
        },
    )

    if preflight_only:
        return
    if dry_run:
        for action in actions:
            if action.action == PENDING_RELINQUISH_FOREIGN_ACTION:
                print(f"would relinquish foreign managed claim {action.target}")
        _apply_reconcile_actions(
            home,
            link_actions,
            dry_run=True,
            required_replacements=required_replacements,
        )
        if not actions:
            print("all managed symlinks already point at current")
        return

    active_bindings = _open_active_release_bindings(
        home,
        active_expectations,
        expected_owner_uid,
    )
    held_bindings = list(active_bindings.values())
    staged_releases: list[InstallReleaseBinding] = []
    try:
        for source_root, sha, manifest, source_expectation in releases:
            release_dir = _releases_root(home, manifest.owner) / sha
            already_present = release_dir.exists()
            binding = _stage_release_tree_for_install_with_owner_access_policy(
                source_root,
                home,
                sha,
                manifest,
                source_expectation,
                expected_owner_uid=expected_owner_uid,
            )
            active_binding = active_bindings.get(manifest.owner)
            if active_binding is not None and active_binding.sha == sha:
                _close_install_release_bindings([binding])
            else:
                staged_releases.append(binding)
                held_bindings.append(binding)
            if already_present:
                print(f"release already present: {release_dir}")
            else:
                print(f"installed release tree: {release_dir}")
        current_actions = _plan_current_switch_actions(home, releases)
    except BaseException:
        _close_install_release_bindings(held_bindings)
        raise
    next_current_bindings = dict(active_bindings)
    next_current_bindings.update(
        {binding.owner: binding for binding in staged_releases}
    )
    active_still_current = [
        binding
        for owner, binding in active_bindings.items()
        if incoming_shas.get(owner, binding.sha) == binding.sha
    ]
    active_replaced = [
        binding
        for owner, binding in active_bindings.items()
        if incoming_shas.get(owner, binding.sha) != binding.sha
    ]
    pending_batch: PendingLinkBatch | None = None
    current_transaction: ReconcileTransaction | None = None
    link_transaction: ReconcileTransaction | None = None
    state_transaction: ManagedStateFileTransaction | None = None
    state_committed = False
    install_release_directory_chains: _InstallReleaseDirectoryChains | None = None
    try:
        initial_state_snapshot = _bind_managed_state_parent_for_pending_staging(
            home,
            initial_state_snapshot,
            loaded_state,
        )
        exact_noop = (
            not current_actions
            and not actions
            and planned_next_state == loaded_state
            and initial_state_snapshot.exists
            and initial_state_snapshot.mode == 0o600
            and initial_state_snapshot.payload
            == _managed_state_bytes(planned_next_state)
        )
        if exact_noop:
            try:
                _verify_install_release_identities(
                    home,
                    list(active_bindings.values()),
                    phase="before activation",
                    verify_current=True,
                )
                if expected_owner_uid is not None:
                    install_release_directory_chains = (
                        _open_install_release_directory_chains(
                            home,
                            next_current_bindings,
                            expected_owner_uid,
                        )
                    )
                    _require_install_release_directory_chains(
                        home,
                        install_release_directory_chains,
                        expected_owner_uid,
                    )
                _verify_desired_entries(home, desired_entries)
                _verify_install_release_identities(
                    home,
                    active_still_current,
                    phase="during final managed-state validation",
                    verify_current=True,
                )
                _verify_desired_entries(home, desired_entries)
                for manifest in overlay_manifests:
                    issues = _collect_overlay_issues(home, manifest.owner)
                    if issues:
                        raise SyncError(
                            "overlay no-op verification failed with "
                            f"{len(issues)} issue(s)"
                        )
                if install_release_directory_chains is not None:
                    _require_install_release_directory_chains(
                        home,
                        install_release_directory_chains,
                        expected_owner_uid,
                    )
            finally:
                _close_install_release_directory_chains(
                    install_release_directory_chains
                )
                install_release_directory_chains = None
                _close_install_release_bindings(held_bindings)
            print("all managed symlinks already point at current")
            return
        if expected_owner_uid is not None:
            try:
                install_release_directory_chains = (
                    _open_install_release_directory_chains(
                        home,
                        next_current_bindings,
                        expected_owner_uid,
                    )
                )
                _require_install_release_directory_chains(
                    home,
                    install_release_directory_chains,
                    expected_owner_uid,
                )
            except (OSError, SyncError) as error:
                raise SyncError(
                    "release tree changed before activation; raced release set "
                    f"was left in place: {error}",
                    code=error.code if isinstance(error, SyncError) else None,
                ) from error
            _probe_install_release_fd_headroom(
                install_release_directory_chains,
            )
        pending_batch = _stage_pending_link_batch(
            home,
            [("current", current_actions), ("managed", actions)],
            desired_entries,
            expected_next_shas,
            initial_state_snapshot,
            state,
            planned_next_state,
            required_replacements_by_scope={
                "managed": required_replacements,
            },
        )
        _publish_pending_link_pointer(home, pending_batch)
        _verify_install_release_identities(
            home,
            list(active_bindings.values()),
            phase="before activation",
            verify_current=True,
        )
        _verify_install_release_identities(
            home,
            staged_releases,
            phase="before activation",
            verify_current=False,
        )
        current_transaction = ReconcileTransaction(
            batch_root=pending_batch.batch_root,
            mutations=[],
        )
        if install_release_directory_chains is not None:
            _require_install_release_directory_chains(
                home,
                install_release_directory_chains,
                expected_owner_uid,
            )
        _apply_reconcile_actions(
            home,
            current_actions,
            dry_run=False,
            pending_batch=pending_batch,
            pending_scope="current",
            batch_root=pending_batch.batch_root,
            transaction=current_transaction,
        )
        if install_release_directory_chains is not None:
            _require_install_release_directory_chains(
                home,
                install_release_directory_chains,
                expected_owner_uid,
            )
        link_transaction = ReconcileTransaction(
            batch_root=pending_batch.batch_root,
            mutations=[],
        )
        _apply_reconcile_actions(
            home,
            link_actions,
            dry_run=False,
            required_replacements=required_replacements,
            pending_batch=pending_batch,
            pending_scope="managed",
            batch_root=pending_batch.batch_root,
            transaction=link_transaction,
        )
        _verify_desired_entries(home, desired_entries, pending_batch=pending_batch)
        for manifest in overlay_manifests:
            issues = _collect_overlay_issues(
                home,
                manifest.owner,
                pending_batch=pending_batch,
            )
            if issues:
                for issue in issues:
                    print(f"overlay issue: {issue}")
                raise SyncError(
                    f"overlay verification failed with {len(issues)} issue(s)"
                )
        owner_shas = _owner_shas_from_bound_current_releases(
            home,
            next_manifests,
            expected_next_shas,
            next_current_bindings,
            phase="before managed-state publication",
        )
        next_state = _committed_state(
            home,
            desired_entries,
            owner_shas,
            managed_targets,
            pending_batch=pending_batch,
        )
        if next_state != planned_next_state:
            raise SyncError("observed managed state differs from the pending plan")
        managed_link_snapshots = _trusted_managed_link_snapshots_for_state(
            home,
            next_state,
            baseline_link_snapshots,
            link_transaction,
        )
        _verify_install_release_bindings_lightweight(
            home,
            active_still_current,
            phase="during final managed-state validation",
            verify_current=True,
        )
        _verify_install_release_bindings_lightweight(
            home,
            active_replaced,
            phase="during final managed-state validation",
            verify_current=False,
        )
        _verify_install_release_bindings_lightweight(
            home,
            staged_releases,
            phase="during final managed-state validation",
            verify_current=True,
        )
        _verify_desired_entries(home, desired_entries, pending_batch=pending_batch)
        _verify_managed_link_snapshots(home, next_state, managed_link_snapshots)
        state_transaction = _prepare_pending_managed_state_transaction(
            home,
            pending_batch,
            next_state,
        )
        _verify_install_release_identities(
            home,
            active_still_current,
            phase="during final managed-state validation",
            verify_current=True,
        )
        _verify_install_release_identities(
            home,
            active_replaced,
            phase="during final managed-state validation",
            verify_current=False,
        )
        _verify_install_release_identities(
            home,
            staged_releases,
            phase="during final managed-state validation",
            verify_current=True,
        )
        _verify_desired_entries(home, desired_entries, pending_batch=pending_batch)
        _verify_managed_link_snapshots(home, next_state, managed_link_snapshots)
        _write_managed_state(home, next_state, state_transaction)
        _verify_published_state_transaction(home, state_transaction)
        _verify_install_release_identities(
            home,
            active_still_current,
            phase="after managed-state publication",
            verify_current=True,
        )
        _verify_install_release_identities(
            home,
            active_replaced,
            phase="after managed-state publication",
            verify_current=False,
        )
        _verify_install_release_identities(
            home,
            staged_releases,
            phase="after managed-state publication",
            verify_current=True,
        )
        _verify_desired_entries(home, desired_entries, pending_batch=pending_batch)
        _verify_managed_link_snapshots(home, next_state, managed_link_snapshots)
        _verify_committed_pending_link_records(home, pending_batch)
        _verify_published_state_transaction(home, state_transaction)
        if install_release_directory_chains is not None:
            _require_install_release_directory_chains(
                home,
                install_release_directory_chains,
                expected_owner_uid,
            )
        _publish_pending_commit_marker(home, pending_batch)
        state_committed = True
        _mark_pending_batch_cleanup_ready(home, pending_batch)
        _clear_pending_link_pointer(home, pending_batch, phase="after")
    except BaseException as error:
        _close_install_release_directory_chains(install_release_directory_chains)
        install_release_directory_chains = None
        if (
            not state_committed
            and pending_batch is not None
            and pending_batch.pointer_snapshot is not None
        ):
            try:
                state_committed = _pending_commit_decision(home, pending_batch)
            except (OSError, SyncError) as marker_error:
                _close_install_release_bindings(held_bindings)
                raise SyncError(
                    "installation failed with an ambiguous commit marker; the "
                    "pending transaction was retained: "
                    f"{marker_error}"
                ) from error
        if state_committed:
            _close_install_release_bindings(held_bindings)
            raise SyncError(
                "installation committed managed state but finalization failed; "
                "the pending transaction was retained for exact recovery"
            ) from error
        rollback_errors: list[str] = []
        try:
            _restore_managed_state_file(home, state_transaction)
        except (OSError, SyncError) as rollback_error:
            rollback_errors.append(f"state: {rollback_error}")
        try:
            _rollback_reconcile_transaction(
                home,
                link_transaction,
                pending_batch=pending_batch,
            )
        except (OSError, SyncError) as rollback_error:
            rollback_errors.append(f"links: {rollback_error}")
        try:
            _rollback_reconcile_transaction(home, current_transaction)
        except (OSError, SyncError) as rollback_error:
            rollback_errors.append(f"current: {rollback_error}")
        if (
            pending_batch is not None
            and pending_batch.pointer_snapshot is not None
            and not rollback_errors
        ):
            try:
                _finalize_rolled_back_pending_batch(home, pending_batch)
            except (OSError, SyncError) as rollback_error:
                rollback_errors.append(
                    f"pending rollback finalization: {rollback_error}"
                )
        if rollback_errors:
            _close_install_release_bindings(held_bindings)
            raise SyncError(
                f"installation failed: {error}; rollback was incomplete: "
                + "; ".join(rollback_errors)
            ) from error
        _close_install_release_bindings(held_bindings)
        raise
    try:
        _commit_managed_state_transaction(state_transaction)
        _commit_reconcile_transaction(link_transaction)
        _commit_reconcile_transaction(current_transaction)
        assert pending_batch is not None
        cleaned = _try_cleanup_finalized_pending_batch(home, pending_batch)
        if pending_batch.terminal_regular_after:
            if not cleaned:
                raise SyncError("committed regular-file evidence cleanup was deferred")
    finally:
        _close_install_release_directory_chains(install_release_directory_chains)
        _close_install_release_bindings(held_bindings)
    if not actions:
        print("all managed symlinks already point at current")


def install_release_tree(
    source_root: Path,
    home: Path,
    sha: str,
    *,
    dry_run: bool,
    release_expectation: ReleaseTreeExpectation | None = None,
    cleanup_budget: PendingCleanupActionBudget | None = None,
) -> None:
    sha = _validate_release_sha(sha)
    home = home.expanduser()
    action_budget = cleanup_budget or PendingCleanupActionBudget(
        MAX_PENDING_CLEANUP_BATCHES_PER_RUN
    )
    if (
        _preflight_pending_recovery(
            home,
            dry_run=dry_run,
            cleanup_budget=action_budget,
        )
        and dry_run
    ):
        return
    if release_expectation is None:
        release_expectation = _source_release_identity(source_root, None)
    else:
        release_expectation = _source_release_identity(
            source_root,
            release_expectation[0][1],
            release_expectation,
        )
    manifest = release_expectation[0][1]
    releases = [(source_root, sha, manifest, release_expectation)]
    if dry_run:
        _install_release_set_unlocked(
            home,
            releases,
            dry_run=True,
            allow_cross_owner=manifest.owner != PUBLIC_OWNER,
            cleanup_budget=action_budget,
        )
        return
    _install_release_set_unlocked(
        home,
        releases,
        dry_run=True,
        allow_cross_owner=manifest.owner != PUBLIC_OWNER,
        preflight_only=True,
        cleanup_budget=action_budget,
    )
    with installation_lock(home):
        _install_release_set_unlocked(
            home,
            releases,
            dry_run=False,
            allow_cross_owner=manifest.owner != PUBLIC_OWNER,
            cleanup_budget=action_budget,
        )


def _stage_release_tree_for_install(
    source_root: Path,
    home: Path,
    sha: str,
    manifest: ManifestData,
    source_expectation: ReleaseTreeExpectation | None = None,
    expected_owner_uid: int | None = None,
) -> InstallReleaseBinding:
    if sys.platform != "darwin":
        expected_owner_uid = None
    elif expected_owner_uid is None:
        expected_owner_uid = _INSTALL_RELEASE_OWNER_UID.get()
    sha = _validate_release_sha(sha)
    if source_expectation is None:
        source_expectation = _source_release_identity(source_root, manifest)
    owner = _entries_owner(manifest.entries)
    _ensure_install_roots(home, owner)
    release_dir = _releases_root(home, owner) / sha
    if _path_exists_or_is_link(release_dir):
        expectation = _require_existing_release_matches_source(
            source_root,
            home,
            owner,
            sha,
            manifest,
            source_expectation,
        )
    else:
        expectation = _copy_release_tree(
            source_root,
            release_dir,
            home,
            manifest,
            source_expectation,
            expected_owner_uid,
        )
    return _open_install_release_binding(
        home,
        owner,
        sha,
        expectation,
        expected_owner_uid,
    )


def _stage_release_tree_for_install_with_owner_access_policy(
    source_root: Path,
    home: Path,
    sha: str,
    manifest: ManifestData,
    source_expectation: ReleaseTreeExpectation | None,
    *,
    expected_owner_uid: int | None,
) -> InstallReleaseBinding:
    normalized_owner_uid = expected_owner_uid if sys.platform == "darwin" else None
    token = _INSTALL_RELEASE_OWNER_UID.set(normalized_owner_uid)
    try:
        return _stage_release_tree_for_install(
            source_root,
            home,
            sha,
            manifest,
            source_expectation,
        )
    finally:
        _INSTALL_RELEASE_OWNER_UID.reset(token)


@contextlib.contextmanager
def _gh_operation_deadline():
    existing = _GH_OPERATION_DEADLINE.get()
    if existing is not None:
        if time.monotonic() >= existing:
            raise SyncError(
                "gh operation exceeded its monotonic deadline",
                code="gh-timeout",
            )
        yield existing
        return
    deadline = time.monotonic() + GH_OPERATION_TIMEOUT_SECONDS
    token = _GH_OPERATION_DEADLINE.set(deadline)
    try:
        yield deadline
    finally:
        _GH_OPERATION_DEADLINE.reset(token)


def _read_guardian_ready_record(
    file_descriptor: int,
    *,
    deadline: float,
    process_label: str,
    timeout_code: str = "process-guardian-protocol",
    timeout_message: str | None = None,
) -> tuple[bytes, int, int]:
    selector: selectors.BaseSelector | None = None
    payload = bytearray()
    primary: BaseException | None = None
    close_failures: list[tuple[str, BaseException]] = []
    try:
        os.set_blocking(file_descriptor, False)
        selector = selectors.DefaultSelector()
        selector.register(file_descriptor, selectors.EVENT_READ)
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise SyncError(
                    timeout_message
                    or f"{process_label} guardian ready receipt timed out",
                    code=timeout_code,
                )
            events = selector.select(remaining)
            if not events:
                continue
            try:
                chunk = os.read(
                    file_descriptor,
                    PROCESS_GUARDIAN_READY_RECORD.size + 1 - len(payload),
                )
            except BlockingIOError:
                continue
            if not chunk:
                break
            payload.extend(chunk)
            if len(payload) > PROCESS_GUARDIAN_READY_RECORD.size:
                raise SyncError(
                    f"{process_label} guardian ready receipt exceeds its bound",
                    code="process-guardian-protocol",
                )
    except BaseException as error:
        primary = error
    finally:
        if selector is not None:
            try:
                selector.close()
            except BaseException as error:
                close_failures.append(
                    (
                        f"cannot close {process_label} guardian ready selector: {error}",
                        error,
                    )
                )
        try:
            os.close(file_descriptor)
        except BaseException as error:
            close_failures.append(
                (
                    f"cannot close {process_label} guardian ready descriptor: {error}",
                    error,
                )
            )
    if primary is not None:
        if close_failures:
            raise SyncError(
                f"{primary}; {process_label} guardian ready cleanup was "
                "inconclusive: "
                + "; ".join(detail for detail, _error in close_failures),
                code="process-guardian-protocol",
            ) from primary
        raise primary
    if close_failures:
        raise SyncError(
            f"{process_label} guardian ready cleanup was inconclusive: "
            + "; ".join(detail for detail, _error in close_failures),
            code="process-guardian-protocol",
        ) from close_failures[0][1]
    if len(payload) != PROCESS_GUARDIAN_READY_RECORD.size:
        raise SyncError(
            f"{process_label} guardian ready receipt is incomplete",
            code="process-guardian-protocol",
        )
    magic, guardian_pid, value = PROCESS_GUARDIAN_READY_RECORD.unpack(payload)
    if guardian_pid <= 0 or magic not in {
        PROCESS_GUARDIAN_READY_MAGIC,
        PROCESS_GUARDIAN_LAUNCH_FAILURE_MAGIC,
    }:
        raise SyncError(
            f"{process_label} guardian ready receipt is invalid",
            code="process-guardian-protocol",
        )
    return magic, guardian_pid, value


def _spawn_guarded_process(
    command: list[str],
    *,
    deadline: float,
    process_label: str,
    env: dict[str, str] | None = None,
    unavailable_code: str,
    unavailable_message: str,
) -> _GuardedProcess:
    if not command or any(
        not isinstance(argument, str) or not argument or "\0" in argument
        for argument in command
    ):
        raise SyncError(
            f"{process_label} argv is invalid",
            code=unavailable_code,
        )
    executable = command[0]
    if os.path.sep not in executable:
        resolved = shutil.which(
            executable,
            path=(env if env is not None else os.environ).get("PATH"),
        )
        if resolved is None:
            raise SyncError(unavailable_message, code=unavailable_code)
        command = [resolved, *command[1:]]
    elif not os.path.isabs(executable):
        raise SyncError(
            f"{process_label} executable must be absolute",
            code=unavailable_code,
        )
    if not sys.executable or not os.path.isabs(sys.executable):
        raise SyncError(
            f"{process_label} guardian interpreter is unavailable",
            code=unavailable_code,
        )

    ready_read_fd = -1
    ready_write_fd = -1
    status_read_fd = -1
    status_write_fd = -1
    guardian: subprocess.Popen[bytes] | None = None
    status_stream: Any | None = None
    try:
        try:
            ready_read_fd, ready_write_fd = os.pipe()
            status_read_fd, status_write_fd = os.pipe()
        except OSError as error:
            raise SyncError(
                f"cannot create {process_label} guardian control pipes: {error}",
                code="process-guardian-protocol",
            ) from error
        guardian_ready_deadline = (
            time.monotonic() + PROCESS_GUARDIAN_READY_TIMEOUT_SECONDS
        )
        guardian_deadline = min(deadline, guardian_ready_deadline)
        operation_deadline_limits_ready = deadline <= guardian_ready_deadline
        guardian = subprocess.Popen(
            [
                sys.executable,
                "-I",
                "-B",
                "-S",
                "-c",
                PROCESS_GUARDIAN_SOURCE,
                str(ready_write_fd),
                str(status_write_fd),
                *command,
            ],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=env,
            start_new_session=True,
            close_fds=True,
            pass_fds=(ready_write_fd, status_write_fd),
        )
        owned_ready_write_fd = ready_write_fd
        ready_write_fd = -1
        os.close(owned_ready_write_fd)
        owned_status_write_fd = status_write_fd
        status_write_fd = -1
        os.close(owned_status_write_fd)
        status_stream = os.fdopen(status_read_fd, "rb", buffering=0)
        status_read_fd = -1
        process = _GuardedProcess(
            guardian=guardian,
            target_pid=-1,
            status=status_stream,
        )
        owned_ready_read_fd = ready_read_fd
        ready_read_fd = -1
        ready_magic, receipt_guardian_pid, ready_value = _read_guardian_ready_record(
            owned_ready_read_fd,
            deadline=guardian_deadline,
            process_label=process_label,
            timeout_code=(
                "process-guardian-operation-timeout"
                if operation_deadline_limits_ready
                else "process-guardian-protocol"
            ),
            timeout_message=(
                f"{process_label} exceeded its monotonic deadline"
                if operation_deadline_limits_ready
                else None
            ),
        )
        if receipt_guardian_pid != process.pid:
            raise SyncError(
                f"{process_label} guardian ready receipt changed leader identity",
                code="process-guardian-protocol",
            )
        if ready_magic == PROCESS_GUARDIAN_LAUNCH_FAILURE_MAGIC:
            suffix = f" (errno {ready_value})" if ready_value > 0 else ""
            raise SyncError(
                unavailable_message + suffix,
                code=unavailable_code,
            )
        target_pid = ready_value
        if target_pid <= 0:
            raise SyncError(
                f"{process_label} guardian ready receipt has no target identity",
                code="process-guardian-protocol",
            )
        try:
            process_group_id = os.getpgid(process.pid)
            session_id = os.getsid(process.pid)
        except OSError as error:
            raise SyncError(
                f"cannot validate {process_label} guardian identity: {error}",
                code="process-guardian-protocol",
            ) from error
        if process_group_id != process.pid or session_id != process.pid:
            raise SyncError(
                f"{process_label} guardian is not its dedicated session leader",
                code="process-guardian-protocol",
            )
        process.target_pid = target_pid
        return process
    except BaseException as primary:
        if guardian is not None:
            process = _GuardedProcess(
                guardian=guardian,
                target_pid=-1,
                status=status_stream,
            )
            receipt = _terminalize_process_group_before_reap(
                process,
                deadline=time.monotonic() + GH_CLEANUP_TIMEOUT_SECONDS,
                process_label=f"{process_label} guardian",
            )
            descriptor_failure: BaseException | None = None
            if process.status is None and status_read_fd >= 0:
                try:
                    process.status = os.fdopen(status_read_fd, "rb", buffering=0)
                    status_read_fd = -1
                except BaseException as error:
                    descriptor_failure = error
            close_failures = _close_process_supervision_resources(
                process,
                None,
                process_label=f"{process_label} guardian spawn",
            )
            if not receipt.complete or descriptor_failure is not None or close_failures:
                details = list(receipt.errors)
                if descriptor_failure is not None:
                    details.append(
                        f"cannot bind guardian status stream: {descriptor_failure}"
                    )
                details.extend(detail for detail, _error in close_failures)
                raise SyncError(
                    f"{primary}; {process_label} guardian spawn cleanup was "
                    f"inconclusive: {'; '.join(details) or 'unknown failure'}",
                    code="process-guardian-cleanup-inconclusive",
                ) from primary
        elif isinstance(primary, OSError):
            raise SyncError(
                f"{unavailable_message}: {primary}",
                code=unavailable_code,
            ) from primary
        raise
    finally:
        for file_descriptor in (
            ready_read_fd,
            ready_write_fd,
            status_read_fd,
            status_write_fd,
        ):
            if file_descriptor >= 0:
                try:
                    os.close(file_descriptor)
                except OSError:
                    pass


def _terminalize_process_group_before_reap(
    process: _GuardedProcess,
    *,
    deadline: float,
    process_label: str,
) -> _ProcessTerminalizationReceipt:
    """Kill the live guardian group before the one final leader reap."""
    errors: list[str] = []
    if process.returncode is not None:
        return _ProcessTerminalizationReceipt(
            kill_sent=False,
            child_reaped=True,
            process_group_fenced=False,
            returncode=process.returncode,
            errors=(
                f"{process_label} leader was already reaped before its "
                "process group was fenced",
            ),
        )
    process_id = getattr(process, "pid", None)
    valid_process_id = (
        isinstance(process_id, int)
        and not isinstance(process_id, bool)
        and process_id > 0
    )
    kill_sent = False
    process_group_fenced = False
    if not valid_process_id:
        errors.append(f"{process_label} process has no valid process-group identity")
    else:
        assert isinstance(process_id, int)
        try:
            # start_new_session=True makes the unreaped leader PID the exact PGID.
            # No numeric PID/PGID operation is permitted after the wait below.
            os.killpg(process_id, signal.SIGKILL)
            kill_sent = True
            process_group_fenced = True
        except ProcessLookupError as error:
            errors.append(
                f"{process_label} live guardian group disappeared before its "
                f"fence: {error}"
            )
        except PermissionError as error:
            errors.append(f"cannot signal {process_label} process group: {error}")
        except OSError as error:
            errors.append(f"cannot signal {process_label} process group: {error}")

    returncode: int | None = None
    child_reaped = False
    try:
        returncode = process.wait(timeout=max(0.0, deadline - time.monotonic()))
        child_reaped = True
    except subprocess.TimeoutExpired as error:
        errors.append(f"{process_label} leader was not reaped: {error}")
    except BaseException as error:
        errors.append(f"cannot reap {process_label} leader: {error}")
    return _ProcessTerminalizationReceipt(
        kill_sent=kill_sent,
        child_reaped=child_reaped,
        process_group_fenced=process_group_fenced,
        returncode=returncode,
        errors=tuple(errors),
    )


def _terminalization_detail(receipt: _ProcessTerminalizationReceipt) -> str:
    incomplete: list[str] = []
    if not receipt.process_group_fenced:
        incomplete.append("process-group-not-fenced")
    if not receipt.kill_sent:
        incomplete.append("process-group-kill-not-sent")
    if not receipt.child_reaped:
        incomplete.append("guardian-not-reaped")
    if receipt.returncode != -signal.SIGKILL:
        incomplete.append(f"guardian-returncode-{receipt.returncode!r}")
    incomplete.extend(receipt.errors)
    return "; ".join(incomplete) or "unknown terminalization failure"


def _parse_guardian_status(
    process: _GuardedProcess,
    payload: bytes,
    *,
    process_label: str,
    error_code: str,
) -> int:
    if len(payload) != PROCESS_GUARDIAN_STATUS_RECORD.size:
        raise SyncError(
            f"{process_label} guardian status receipt is incomplete",
            code=error_code,
        )
    magic, guardian_pid, target_pid, target_returncode = (
        PROCESS_GUARDIAN_STATUS_RECORD.unpack(payload)
    )
    if (
        magic != PROCESS_GUARDIAN_STATUS_MAGIC
        or guardian_pid != process.pid
        or target_pid != process.target_pid
    ):
        raise SyncError(
            f"{process_label} guardian status receipt changed process identity",
            code=error_code,
        )
    if not (-(signal.NSIG - 1) <= target_returncode <= 255):
        raise SyncError(
            f"{process_label} guardian status has an invalid target return code",
            code=error_code,
        )
    return target_returncode


def _require_guardian_status_writer_live(
    process: _GuardedProcess,
    *,
    process_label: str,
    error_code: str,
) -> None:
    try:
        extra = os.read(process.status.fileno(), 1)
    except BlockingIOError:
        return
    except OSError as error:
        raise SyncError(
            f"cannot verify {process_label} guardian liveness: {error}",
            code=error_code,
        ) from error
    if extra:
        raise SyncError(
            f"{process_label} guardian status exceeds its bound",
            code=error_code,
        )
    raise SyncError(
        f"{process_label} guardian exited before process-group fencing",
        code=error_code,
    )


def _close_process_supervision_resources(
    process: _GuardedProcess,
    selector: selectors.BaseSelector | None,
    *,
    process_label: str,
) -> list[tuple[str, BaseException]]:
    failures: list[tuple[str, BaseException]] = []
    if selector is not None:
        try:
            selector.close()
        except BaseException as error:
            failures.append((f"cannot close {process_label} selector: {error}", error))
    for name, stream in (
        ("stdout", process.stdout),
        ("stderr", process.stderr),
        ("status", process.status),
    ):
        if stream is None:
            continue
        try:
            stream.close()
        except BaseException as error:
            failures.append(
                (f"cannot close {process_label} {name} stream: {error}", error)
            )
    return failures


def _cleanup_gh_process_group(
    process: _GuardedProcess,
    *,
    process_label: str = "gh",
) -> _GhCleanupReceipt:
    cleanup_deadline = time.monotonic() + GH_CLEANUP_TIMEOUT_SECONDS
    errors: list[str] = []
    drained = {"stdout": False, "stderr": False, "status": False}
    terminalization = _terminalize_process_group_before_reap(
        process,
        deadline=cleanup_deadline,
        process_label=process_label,
    )
    errors.extend(terminalization.errors)
    if not terminalization.complete:
        errors.append(
            f"{process_label} guardian terminalization was inconclusive: "
            f"{_terminalization_detail(terminalization)}"
        )

    selector: selectors.BaseSelector | None = None
    try:
        selector = selectors.DefaultSelector()
    except (OSError, ValueError) as error:
        errors.append(f"cannot create {process_label} cleanup selector: {error}")
    streams = {
        "stdout": process.stdout,
        "stderr": process.stderr,
        "status": process.status,
    }
    for name, stream in streams.items():
        if stream is None:
            errors.append(f"{name} pipe is missing")
            continue
        if selector is None:
            continue
        try:
            os.set_blocking(stream.fileno(), False)
            selector.register(stream, selectors.EVENT_READ, name)
        except (OSError, ValueError) as error:
            errors.append(f"cannot register {name} cleanup drain: {error}")
    try:
        while selector is not None and selector.get_map():
            remaining = cleanup_deadline - time.monotonic()
            if remaining <= 0:
                errors.append(f"{process_label} cleanup pipe drain exceeded deadline")
                break
            timeout = min(0.05, remaining)
            if selector.get_map():
                try:
                    events = selector.select(timeout)
                except OSError as error:
                    errors.append(
                        f"cannot drain {process_label} process pipes: {error}"
                    )
                    break
                for key, _mask in events:
                    name = key.data
                    try:
                        chunk = os.read(key.fileobj.fileno(), 64 * 1024)
                    except BlockingIOError:
                        continue
                    except OSError as error:
                        errors.append(f"cannot drain {process_label} {name}: {error}")
                        try:
                            selector.unregister(key.fileobj)
                        except (KeyError, OSError, ValueError):
                            pass
                        continue
                    if chunk:
                        continue
                    drained[name] = True
                    try:
                        selector.unregister(key.fileobj)
                    except (KeyError, OSError, ValueError):
                        pass
    finally:
        close_failures = _close_process_supervision_resources(
            process,
            selector,
            process_label=f"{process_label} cleanup",
        )
        errors.extend(detail for detail, _error in close_failures)
    return _GhCleanupReceipt(
        kill_sent=terminalization.kill_sent,
        child_reaped=terminalization.child_reaped,
        stdout_drained=drained["stdout"],
        stderr_drained=drained["stderr"],
        status_drained=drained["status"],
        process_group_fenced=terminalization.process_group_fenced,
        errors=tuple(errors),
    )


def _gh_cleanup_detail(receipt: _GhCleanupReceipt) -> str:
    incomplete: list[str] = []
    if not receipt.child_reaped:
        incomplete.append("child-not-reaped")
    if not receipt.stdout_drained:
        incomplete.append("stdout-not-drained")
    if not receipt.stderr_drained:
        incomplete.append("stderr-not-drained")
    if not receipt.status_drained:
        incomplete.append("status-not-drained")
    if not receipt.process_group_fenced:
        incomplete.append("process-group-not-fenced")
    incomplete.extend(receipt.errors)
    return "; ".join(incomplete) or "unknown cleanup failure"


def _raise_gh_failure_after_cleanup(
    process: _GuardedProcess,
    primary: BaseException,
) -> NoReturn:
    try:
        receipt = _cleanup_gh_process_group(process)
    except Exception as cleanup_error:
        raise SyncError(
            f"{primary}; gh process cleanup raised an exception: {cleanup_error}",
            code="gh-cleanup-inconclusive",
        ) from primary
    if not receipt.complete:
        raise SyncError(
            f"{primary}; gh process cleanup was inconclusive: "
            f"{_gh_cleanup_detail(receipt)}",
            code="gh-cleanup-inconclusive",
        ) from primary
    raise primary


def _run_bounded_gh_process(
    args: list[str],
    *,
    deadline: float,
    stdout_limit: int,
    stderr_limit: int,
    label: str,
    stdout_sink: Callable[[bytes], None] | None = None,
    stdout_overflow_message: str | None = None,
) -> _GhProcessResult:
    if stdout_limit < 0 or stderr_limit < 0:
        raise SyncError("gh process output limits must be nonnegative")
    if time.monotonic() >= deadline:
        raise SyncError(
            f"{label} exceeded its monotonic deadline",
            code="gh-timeout",
        )
    try:
        process = _spawn_guarded_process(
            ["gh", *args],
            deadline=deadline,
            process_label=label,
            unavailable_code="gh-command-unavailable",
            unavailable_message=(
                "GitHub CLI `gh` is not available; install it or make sure it is "
                "on PATH"
            ),
        )
    except SyncError as error:
        if error.code == "process-guardian-cleanup-inconclusive":
            raise SyncError(
                f"{label} guardian cleanup was inconclusive: {error}",
                code="gh-cleanup-inconclusive",
            ) from error
        if error.code == "process-guardian-operation-timeout":
            raise SyncError(
                f"{label} exceeded its monotonic deadline",
                code="gh-timeout",
            ) from error
        raise
    if process.stdout is None or process.stderr is None or process.status is None:
        _raise_gh_failure_after_cleanup(
            process,
            SyncError(
                f"{label} did not provide bounded process pipes",
                code="gh-process-io",
            ),
        )

    selector: selectors.BaseSelector | None = None
    buffers = {
        "stdout": bytearray(),
        "stderr": bytearray(),
        "status": bytearray(),
    }
    totals = {"stdout": 0, "stderr": 0}
    limits = {"stdout": stdout_limit, "stderr": stderr_limit}
    result: _GhProcessResult | None = None
    pending_error: BaseException | None = None
    pending_cause: BaseException | None = None
    terminalization_started = False
    close_failures: list[tuple[str, BaseException]] = []
    output_eof: set[str] = set()
    try:
        try:
            selector = selectors.DefaultSelector()
            for name, stream in (
                ("stdout", process.stdout),
                ("stderr", process.stderr),
                ("status", process.status),
            ):
                os.set_blocking(stream.fileno(), False)
                selector.register(stream, selectors.EVENT_READ, name)
            while True:
                if (
                    output_eof == {"stdout", "stderr"}
                    and len(buffers["status"]) == PROCESS_GUARDIAN_STATUS_RECORD.size
                ):
                    _require_guardian_status_writer_live(
                        process,
                        process_label=label,
                        error_code="gh-process-io",
                    )
                    break
                if not selector.get_map():
                    raise SyncError(
                        f"{label} guardian protocol ended before completion",
                        code="gh-process-io",
                    )
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise SyncError(
                        f"{label} exceeded its monotonic deadline",
                        code="gh-timeout",
                    )
                events = selector.select(remaining)
                if not events:
                    continue
                for key, _mask in events:
                    name = key.data
                    maximum_read = 64 * 1024
                    if name == "status":
                        maximum_read = (
                            PROCESS_GUARDIAN_STATUS_RECORD.size
                            + 1
                            - len(buffers["status"])
                        )
                    try:
                        chunk = os.read(key.fileobj.fileno(), maximum_read)
                    except BlockingIOError:
                        continue
                    except OSError as error:
                        raise SyncError(
                            f"cannot read {label} {name}: {error}",
                            code="gh-process-io",
                        ) from error
                    if not chunk:
                        if name == "status":
                            raise SyncError(
                                f"{label} guardian exited before process-group fencing",
                                code="gh-process-io",
                            )
                        output_eof.add(name)
                        selector.unregister(key.fileobj)
                        continue
                    if name == "status":
                        buffers["status"].extend(chunk)
                        if len(buffers["status"]) > (
                            PROCESS_GUARDIAN_STATUS_RECORD.size
                        ):
                            raise SyncError(
                                f"{label} guardian status exceeds its bound",
                                code="gh-process-io",
                            )
                        continue
                    totals[name] += len(chunk)
                    if totals[name] > limits[name]:
                        if name == "stdout" and stdout_overflow_message is not None:
                            message = stdout_overflow_message
                        else:
                            message = (
                                f"{label} {name} exceeds the {limits[name]}-byte limit"
                            )
                        raise SyncError(message, code=f"gh-{name}-limit")
                    if name == "stdout" and stdout_sink is not None:
                        stdout_sink(chunk)
                    else:
                        buffers[name].extend(chunk)
            target_returncode = _parse_guardian_status(
                process,
                bytes(buffers["status"]),
                process_label=label,
                error_code="gh-process-io",
            )
            if process.returncode is not None:
                raise SyncError(
                    f"{label} guardian exited before process-group fencing",
                    code="gh-process-io",
                )
            terminalization_started = True
            terminalization = _terminalize_process_group_before_reap(
                process,
                deadline=time.monotonic() + GH_CLEANUP_TIMEOUT_SECONDS,
                process_label=f"{label} guardian",
            )
            if not terminalization.complete:
                raise SyncError(
                    f"{label} guardian terminalization was inconclusive: "
                    f"{_terminalization_detail(terminalization)}",
                    code="gh-cleanup-inconclusive",
                )
            result = _GhProcessResult(
                returncode=target_returncode,
                stdout=bytes(buffers["stdout"]),
                stderr=bytes(buffers["stderr"]),
            )
        except SyncError as error:
            pending_error = error
        except (OSError, ValueError) as error:
            pending_error = SyncError(
                f"{label} bounded process supervision failed: {error}",
                code="gh-process-io",
            )
            pending_cause = error
        except BaseException as error:
            pending_error = error
        if pending_error is not None and not terminalization_started:
            cleanup_primary = pending_error
            try:
                _raise_gh_failure_after_cleanup(process, cleanup_primary)
            except BaseException as resolved_error:
                pending_error = resolved_error
                if resolved_error is not cleanup_primary:
                    pending_cause = None
    finally:
        close_failures = _close_process_supervision_resources(
            process,
            selector,
            process_label=label,
        )
    if close_failures:
        close_detail = "; ".join(detail for detail, _error in close_failures)
        if pending_error is not None:
            raise SyncError(
                f"{pending_error}; {label} cleanup was inconclusive: {close_detail}",
                code="gh-cleanup-inconclusive",
            ) from pending_error
        raise SyncError(
            f"{label} cleanup was inconclusive: {close_detail}",
            code="gh-cleanup-inconclusive",
        ) from close_failures[0][1]
    if pending_error is not None:
        if pending_cause is not None:
            raise pending_error from pending_cause
        raise pending_error.with_traceback(pending_error.__traceback__)
    if result is None:
        raise SyncError(
            f"{label} produced no terminal result",
            code="gh-process-io",
        )
    return result


def _run_gh_process(args: list[str]) -> subprocess.CompletedProcess[str]:
    with _gh_operation_deadline() as deadline:
        result = _run_bounded_gh_process(
            args,
            deadline=deadline,
            stdout_limit=MAX_GH_METADATA_STDOUT_BYTES,
            stderr_limit=MAX_GH_STDERR_BYTES,
            label="gh metadata command",
        )
    try:
        stdout = result.stdout.decode("utf-8", errors="strict")
    except UnicodeDecodeError as error:
        raise SyncError(
            "gh metadata stdout is not valid UTF-8",
            code="gh-output-invalid",
        ) from error
    stderr = result.stderr.decode("utf-8", errors="replace")
    return subprocess.CompletedProcess(
        args=["gh", *args],
        returncode=result.returncode,
        stdout=stdout,
        stderr=stderr,
    )


def _run_gh_json(args: list[str]) -> Any:
    completed = _run_gh_process(args)
    if completed.returncode != 0:
        raise SyncError(completed.stderr.strip() or "gh command failed")
    try:
        return json.loads(
            completed.stdout,
            parse_int=_bounded_json_integer,
            parse_constant=_reject_json_constant,
        )
    except (ValueError, RecursionError) as error:
        raise SyncError(f"gh returned invalid JSON: {error}") from error


def _run_gh_json_stream(args: list[str]) -> list[Any]:
    completed = _run_gh_process(args)
    if completed.returncode != 0:
        raise SyncError(completed.stderr.strip() or "gh command failed")
    decoder = json.JSONDecoder(
        parse_int=_bounded_json_integer,
        parse_constant=_reject_json_constant,
    )
    values: list[Any] = []
    text = completed.stdout
    index = 0
    while index < len(text):
        while index < len(text) and text[index].isspace():
            index += 1
        if index >= len(text):
            break
        try:
            value, index = decoder.raw_decode(text, index)
        except (ValueError, RecursionError) as error:
            raise SyncError(f"gh returned invalid paginated JSON: {error}") from error
        values.append(value)
    return values


def _run_gh(args: list[str]) -> None:
    completed = _run_gh_process(args)
    if completed.returncode != 0:
        raise SyncError(completed.stderr.strip() or "gh command failed")


def _require_immutable_release(
    release: dict[str, Any],
    tag_name: str,
    *,
    required: bool,
) -> None:
    if required and release.get("immutable") is not True:
        raise SyncError(f"release {tag_name} is not immutable")


def find_latest_release(
    repo: str,
    *,
    require_immutable: bool = True,
) -> dict[str, Any]:
    release_pages = _run_gh_json_stream(
        [
            "api",
            f"repos/{repo}/releases?per_page=100",
            "--paginate",
        ]
    )
    if release_pages is None:
        raise SyncError(f"no {TAG_PREFIX} release found in {repo}")
    if not isinstance(release_pages, list):
        raise SyncError("gh api releases returned an unexpected payload")
    for page in release_pages:
        if not isinstance(page, list):
            raise SyncError("gh api releases returned an unexpected payload")
        for release_data in page:
            if not isinstance(release_data, dict):
                continue
            tag_name = release_data.get("tag_name") or release_data.get("tagName")
            if (
                isinstance(tag_name, str)
                and tag_name.startswith(TAG_PREFIX)
                and not release_data.get("draft", False)
                and not release_data.get("prerelease", False)
            ):
                _require_immutable_release(
                    release_data,
                    tag_name,
                    required=require_immutable,
                )
                normalized = _normalize_release(release_data)
                select_release_assets(
                    normalized,
                    require_digests=require_immutable,
                )
                return normalized
    raise SyncError(f"no {TAG_PREFIX} release found in {repo}")


def find_release_by_asset_sha(
    repo: str,
    sha: str,
    *,
    require_immutable: bool = True,
) -> dict[str, Any]:
    sha = _validate_release_sha(sha)
    release_pages = _run_gh_json_stream(
        [
            "api",
            f"repos/{repo}/releases?per_page=100",
            "--paginate",
        ]
    )
    if not isinstance(release_pages, list):
        raise SyncError("gh api releases returned an unexpected payload")
    for page in release_pages:
        if not isinstance(page, list):
            raise SyncError("gh api releases returned an unexpected payload")
        for release_data in page:
            if not isinstance(release_data, dict):
                continue
            if release_data.get("draft", False) or release_data.get(
                "prerelease", False
            ):
                continue
            tag_name = release_data.get("tag_name") or release_data.get("tagName")
            if not isinstance(tag_name, str) or not tag_name.startswith(TAG_PREFIX):
                continue
            normalized = _normalize_release(release_data)
            if not _release_mentions_asset_sha(normalized, sha):
                continue
            _require_immutable_release(
                release_data,
                tag_name,
                required=require_immutable,
            )
            assets = select_release_assets(
                normalized,
                require_digests=require_immutable,
            )
            if assets.sha == sha:
                return normalized
    raise SyncError(f"no {TAG_PREFIX} release with asset SHA {sha} found in {repo}")


def _isolate_download_entry_for_cleanup(
    directory_fd: int,
    name: str,
    bound_fd: int,
    *,
    label: str,
) -> None:
    retained_name: str | None = None
    try:
        for candidate in _temporary_archive_entry_names("retained-download"):
            try:
                _rename_noreplace_at(
                    directory_fd,
                    name,
                    directory_fd,
                    candidate,
                )
            except FileExistsError:
                continue
            except FileNotFoundError:
                return
            retained_name = candidate
            break
    except OSError as error:
        raise SyncError(f"failed to isolate {label}: {error}") from error
    if retained_name is None:
        raise SyncError(f"failed to isolate {label}")
    try:
        os.fsync(directory_fd)
    except OSError as error:
        raise SyncError(
            f"failed to persist isolated {label}; left as {retained_name}"
        ) from error
    if not _archive_entry_matches_fd(directory_fd, retained_name, bound_fd):
        raise SyncError(f"{label} changed during cleanup; preserved as {retained_name}")
    try:
        os.unlink(retained_name, dir_fd=directory_fd)
    except OSError as error:
        raise SyncError(
            f"failed to remove {label}; preserved as {retained_name}"
        ) from error
    try:
        os.fsync(directory_fd)
    except OSError as error:
        raise SyncError(f"failed to persist removal of {label}") from error


def _download_release_asset(
    repo: str,
    asset_name: str,
    asset_id: int,
    expected_size: int,
    maximum_bytes: int,
    destination: Path,
    *,
    bound_destination_fd: int,
    expected_digest: str,
) -> None:
    _validated_release_asset_metadata(
        {"id": asset_id, "size": expected_size},
        asset_name,
        maximum_bytes=maximum_bytes,
    )
    _validated_release_asset_digest(
        {"digest": expected_digest},
        asset_name,
        required=True,
    )
    if Path(asset_name).name != asset_name or asset_name in {"", ".", ".."}:
        raise SyncError(f"release asset has an unsafe name: {asset_name}")
    destination_path = destination / asset_name
    destination_fd: int | None = None
    partial_name: str | None = None
    partial_fd = -1
    destination_linked = False
    completed = False
    try:
        destination_fd = os.dup(bound_destination_fd)
    except OSError as error:
        raise SyncError(
            f"release download directory is no longer bound {destination}: {error}"
        ) from error
    try:
        if not _archive_path_matches_fd(destination, destination_fd):
            raise SyncError(f"release download directory changed: {destination}")
        try:
            os.stat(asset_name, dir_fd=destination_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise SyncError(
                f"refusing to overwrite downloaded release asset: {destination_path}"
            )

        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        flags |= getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        flags |= getattr(os, "O_NONBLOCK", 0)
        for candidate in _temporary_archive_entry_names("download"):
            try:
                partial_fd = os.open(
                    candidate,
                    flags,
                    0o600,
                    dir_fd=destination_fd,
                )
            except FileExistsError:
                continue
            partial_name = candidate
            break
        if partial_name is None or partial_fd < 0:
            raise SyncError(
                f"failed to create partial download for release asset {asset_name}"
            )

        received = 0
        downloaded_digest = hashlib.sha256()

        def consume_download(chunk: bytes) -> None:
            nonlocal received
            downloaded_digest.update(chunk)
            view = memoryview(chunk)
            while view:
                try:
                    written = os.write(partial_fd, view)
                except OSError as error:
                    raise SyncError(
                        f"failed to write downloaded release asset "
                        f"{asset_name}: {error}"
                    ) from error
                if written <= 0:
                    raise SyncError(
                        f"failed to write downloaded release asset: {asset_name}"
                    )
                view = view[written:]
            received += len(chunk)

        with _gh_operation_deadline() as deadline:
            result = _run_bounded_gh_process(
                [
                    "api",
                    f"repos/{repo}/releases/assets/{asset_id}",
                    "-H",
                    "Accept: application/octet-stream",
                ],
                deadline=deadline,
                stdout_limit=expected_size,
                stderr_limit=MAX_GH_STDERR_BYTES,
                label=f"gh release asset download {asset_name}",
                stdout_sink=consume_download,
                stdout_overflow_message=(
                    f"downloaded release asset {asset_name} exceeds its "
                    f"advertised {expected_size} byte size"
                ),
            )
        if result.returncode != 0:
            message = result.stderr.decode(
                "utf-8",
                errors="replace",
            ).strip()
            raise SyncError(
                message or f"gh failed to download release asset {asset_name}"
            )
        if received != expected_size:
            raise SyncError(
                f"downloaded release asset {asset_name} size mismatch: "
                f"expected {expected_size}, got {received}"
            )
        actual_digest = f"sha256:{downloaded_digest.hexdigest()}"
        if actual_digest != expected_digest:
            raise SyncError(
                f"GitHub API digest mismatch for {asset_name}: "
                f"expected {expected_digest}, got {actual_digest}"
            )

        actual_size = os.fstat(partial_fd).st_size
        if actual_size != expected_size:
            raise SyncError(
                f"downloaded release asset {asset_name} file size mismatch: "
                f"expected {expected_size}, got {actual_size}"
            )
        os.fsync(partial_fd)
        if not _archive_entry_matches_fd(
            destination_fd,
            partial_name,
            partial_fd,
        ):
            raise SyncError(
                f"partial release asset changed before publication: {asset_name}"
            )
        try:
            os.link(
                partial_name,
                asset_name,
                src_dir_fd=destination_fd,
                dst_dir_fd=destination_fd,
                follow_symlinks=False,
            )
        except FileExistsError as error:
            raise SyncError(
                f"refusing to overwrite downloaded release asset: {destination_path}"
            ) from error
        destination_linked = True
        if not _archive_entry_matches_fd(
            destination_fd,
            asset_name,
            partial_fd,
        ):
            raise SyncError(
                f"downloaded release asset changed during publication: {asset_name}"
            )
        _isolate_download_entry_for_cleanup(
            destination_fd,
            partial_name,
            partial_fd,
            label="partial release asset",
        )
        partial_name = None
        if not _archive_path_matches_fd(destination, destination_fd):
            raise SyncError(f"release download directory changed: {destination}")
        if not _archive_entry_matches_fd(
            destination_fd,
            asset_name,
            partial_fd,
        ):
            raise SyncError(
                f"downloaded release asset changed after publication: {asset_name}"
            )
        completed = True
    except SyncError:
        raise
    except OSError as error:
        raise SyncError(
            f"failed to download release asset {asset_name}: {error}"
        ) from error
    finally:
        active_error = sys.exc_info()[0] is not None
        cleanup_errors: list[SyncError] = []
        try:
            if destination_fd is not None:
                if partial_fd >= 0 and not completed and destination_linked:
                    try:
                        _isolate_download_entry_for_cleanup(
                            destination_fd,
                            asset_name,
                            partial_fd,
                            label="published release asset",
                        )
                    except (OSError, SyncError) as error:
                        cleanup_errors.append(
                            error
                            if isinstance(error, SyncError)
                            else SyncError(
                                f"failed to clean published release asset: {error}"
                            )
                        )
                if partial_fd >= 0 and partial_name is not None:
                    try:
                        _isolate_download_entry_for_cleanup(
                            destination_fd,
                            partial_name,
                            partial_fd,
                            label="partial release asset",
                        )
                    except (OSError, SyncError) as error:
                        cleanup_errors.append(
                            error
                            if isinstance(error, SyncError)
                            else SyncError(
                                f"failed to clean partial release asset: {error}"
                            )
                        )
        finally:
            if destination_fd is not None:
                _close_fd_quietly(destination_fd)
            if partial_fd >= 0:
                _close_fd_quietly(partial_fd)
        if cleanup_errors and not active_error:
            raise cleanup_errors[0]


def download_release_assets(
    repo: str,
    assets: ReleaseAssets,
    destination: Path,
    *,
    workspace: BoundArchiveWorkspace,
) -> None:
    downloads = (
        (
            assets.archive_name,
            assets.archive_id,
            assets.archive_size,
            MAX_ARCHIVE_COMPRESSED_BYTES,
            assets.archive_digest,
        ),
        (
            assets.checksum_name,
            assets.checksum_id,
            assets.checksum_size,
            MAX_ARCHIVE_CHECKSUM_BYTES,
            assets.checksum_digest,
        ),
    )
    asset_ids: set[int] = set()
    for asset_name, asset_id, asset_size, maximum_bytes, asset_digest in downloads:
        _validated_release_asset_metadata(
            {"id": asset_id, "size": asset_size},
            asset_name,
            maximum_bytes=maximum_bytes,
        )
        _validated_release_asset_digest(
            {"digest": asset_digest},
            asset_name,
            required=True,
        )
        if asset_id in asset_ids:
            raise SyncError(
                "release archive and checksum must have distinct GitHub asset ids"
            )
        asset_ids.add(asset_id)
    destination_fd = _open_archive_directory_beneath(
        workspace,
        destination,
        create=True,
    )
    try:
        with _gh_operation_deadline():
            for (
                asset_name,
                asset_id,
                asset_size,
                maximum_bytes,
                asset_digest,
            ) in downloads:
                assert asset_digest is not None
                _download_release_asset(
                    repo,
                    asset_name,
                    asset_id,
                    asset_size,
                    maximum_bytes,
                    destination,
                    bound_destination_fd=destination_fd,
                    expected_digest=asset_digest,
                )
        if not _archive_path_matches_fd(destination, destination_fd):
            raise SyncError(f"release download directory changed: {destination}")
        workspace_check_fd = _duplicate_bound_archive_workspace(workspace)
        os.close(workspace_check_fd)
    finally:
        os.close(destination_fd)


def download_and_extract_release(
    repo: str,
    destination: Path,
    *,
    workspace: BoundArchiveWorkspace,
    sha: str | None = None,
) -> DownloadedRelease:
    with _gh_operation_deadline():
        return _download_and_extract_release_with_deadline(
            repo,
            destination,
            workspace=workspace,
            sha=sha,
        )


def _download_and_extract_release_with_deadline(
    repo: str,
    destination: Path,
    *,
    workspace: BoundArchiveWorkspace,
    sha: str | None = None,
) -> DownloadedRelease:
    release = (
        find_release_by_asset_sha(repo, sha)
        if sha is not None
        else find_latest_release(repo)
    )
    assets = select_release_assets(release, require_digests=True)
    destination_fd = _open_archive_directory_beneath(
        workspace,
        destination,
        create=True,
    )
    destination_workspace = BoundArchiveWorkspace(
        path=Path(os.path.abspath(destination)),
        fd=destination_fd,
        identity=_directory_identity(destination_fd),
        access_policy=_archive_workspace_access_policy(os.fstat(destination_fd)),
    )
    try:
        download_release_assets(
            repo,
            assets,
            destination,
            workspace=destination_workspace,
        )
        archive_path = destination / assets.archive_name
        checksum_path = destination / assets.checksum_name
        extract_root = destination / "extract"
        release_root, release_expectation = verify_and_extract_archive(
            archive_path,
            checksum_path,
            extract_root,
            workspace=destination_workspace,
            archive_api_digest=assets.archive_digest,
            checksum_api_digest=assets.checksum_digest,
        )
        return DownloadedRelease(
            repo=repo,
            assets=assets,
            release_root=release_root,
            release_expectation=release_expectation,
        )
    finally:
        os.close(destination_fd)


def install_from_github(repo: str, home: Path, *, dry_run: bool) -> None:
    home = home.expanduser()
    cleanup_budget = PendingCleanupActionBudget(MAX_PENDING_CLEANUP_BATCHES_PER_RUN)
    if (
        _preflight_pending_recovery(
            home,
            dry_run=dry_run,
            cleanup_budget=cleanup_budget,
        )
        and dry_run
    ):
        return
    with temporary_archive_workspace(prefix="codex-personal-sync.") as workspace:
        temp_dir = workspace.path
        release = download_and_extract_release(
            repo,
            temp_dir,
            workspace=workspace,
        )
        install_release_tree(
            release.release_root,
            home,
            release.assets.sha,
            dry_run=dry_run,
            release_expectation=release.release_expectation,
            cleanup_budget=cleanup_budget,
        )


def _validate_release_manifest_owner(
    release_root: Path,
    expected_owner: str,
    release_expectation: ReleaseTreeExpectation | None = None,
) -> ManifestData:
    expected_owner = _validate_owner(expected_owner)
    if release_expectation is None:
        release_expectation = _source_release_identity(release_root, None)
    else:
        release_expectation = _source_release_identity(
            release_root,
            release_expectation[0][1],
            release_expectation,
        )
    manifest = release_expectation[0][1]
    if manifest.owner != expected_owner:
        raise SyncError(
            f"release owner mismatch: expected {expected_owner}, got {manifest.owner}"
        )
    return manifest


def _validate_release_owner(release_root: Path, expected_owner: str) -> list[LinkEntry]:
    return _validate_release_manifest_owner(release_root, expected_owner).entries


def install_private_from_github(
    repo: str,
    home: Path,
    *,
    base_repo: str,
    owner: str,
    dry_run: bool,
) -> None:
    home = home.expanduser()
    cleanup_budget = PendingCleanupActionBudget(MAX_PENDING_CLEANUP_BATCHES_PER_RUN)
    if (
        _preflight_pending_recovery(
            home,
            dry_run=dry_run,
            cleanup_budget=cleanup_budget,
        )
        and dry_run
    ):
        return
    owner = _validate_owner(owner)
    if owner == PUBLIC_OWNER:
        raise SyncError("install-private owner must not be public")

    with temporary_archive_workspace(
        prefix="codex-personal-sync-private."
    ) as workspace:
        temp_dir = workspace.path
        with _gh_operation_deadline():
            overlay_release = download_and_extract_release(
                repo,
                temp_dir / "overlay",
                workspace=workspace,
            )
            overlay_manifest = _validate_release_manifest_owner(
                overlay_release.release_root,
                owner,
                overlay_release.release_expectation,
            )
            base_spec = _load_base_release_spec(overlay_manifest, base_repo)
            base_release = download_and_extract_release(
                base_spec.repo,
                temp_dir / "base",
                workspace=workspace,
                sha=base_spec.sha,
            )
        base_manifest = _validate_release_manifest_owner(
            base_release.release_root,
            PUBLIC_OWNER,
            base_release.release_expectation,
        )
        releases = [
            (
                base_release.release_root,
                base_release.assets.sha,
                base_manifest,
                base_release.release_expectation,
            ),
            (
                overlay_release.release_root,
                overlay_release.assets.sha,
                overlay_manifest,
                overlay_release.release_expectation,
            ),
        ]

        if dry_run:
            print(
                "would install private layered release: "
                f"base {base_spec.repo}@{base_release.assets.sha}, "
                f"overlay {repo}@{overlay_release.assets.sha}"
            )
            _install_release_set_unlocked(
                home,
                releases,
                dry_run=True,
                allow_cross_owner=True,
                cleanup_budget=cleanup_budget,
            )
            return

        with installation_lock(home):
            _install_release_set_unlocked(
                home,
                releases,
                dry_run=False,
                allow_cross_owner=True,
                cleanup_budget=cleanup_budget,
            )
        print(
            "private layered install ok: "
            f"base {base_spec.repo}@{base_release.assets.sha}, "
            f"overlay {repo}@{overlay_release.assets.sha}"
        )


def _current_sha(
    home: Path,
    owner: str = PUBLIC_OWNER,
    *,
    release_identity_owner_uid: int | None = None,
) -> str | None:
    current = _current_link(home, owner)
    current_parent = current.parent
    expected_owner_uid = (
        release_identity_owner_uid if sys.platform == "darwin" else None
    )
    directory_bindings: list[_ReleaseIdentityDirectoryBinding] = []
    try:
        if expected_owner_uid is None:
            current_parent_fd = _open_directory_beneath(home, current_parent)
        else:
            directory_bindings = _open_release_identity_directory_chain(
                home,
                current_parent,
                expected_owner_uid,
            )
            current_parent_fd = os.dup(directory_bindings[-1].file_descriptor)
    except FileNotFoundError:
        _close_release_identity_directory_bindings(directory_bindings)
        return None
    except OSError as error:
        _close_release_identity_directory_bindings(directory_bindings)
        raise SyncError(
            f"refusing unsafe current pointer parent: {current_parent}"
        ) from error
    releases_fd = -1
    release_fd = -1
    releases_identity: tuple[int, int] | None = None
    release_identity: tuple[int, int] | None = None
    try:
        if not _bound_directory_matches(home, current_parent, current_parent_fd):
            raise SyncError(f"current pointer parent changed: {current_parent}")
        try:
            current_metadata = os.stat(
                current.name,
                dir_fd=current_parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            if not _bound_directory_matches(
                home,
                current_parent,
                current_parent_fd,
            ):
                raise SyncError(f"current pointer parent changed: {current_parent}")
            return None
        if not stat.S_ISLNK(current_metadata.st_mode):
            raise SyncError(f"refusing non-symlink current pointer: {current}")

        raw_target_text = os.readlink(current.name, dir_fd=current_parent_fd)
        raw_parts = raw_target_text.split("/")
        if len(raw_parts) != 2 or raw_parts[0] != "releases":
            raise SyncError(
                f"current pointer must use releases/<sha> for owner {owner}"
            )
        try:
            sha = _validate_release_sha(raw_parts[1])
        except SyncError as error:
            raise SyncError(
                f"current pointer has invalid release SHA for owner {owner}"
            ) from error

        releases_root = _releases_root(home, owner)
        release_dir = releases_root / sha
        try:
            releases_fd = os.open(
                "releases",
                _source_directory_flags(),
                dir_fd=current_parent_fd,
            )
            release_metadata = os.stat(
                sha,
                dir_fd=releases_fd,
                follow_symlinks=False,
            )
            if stat.S_ISLNK(release_metadata.st_mode) or not stat.S_ISDIR(
                release_metadata.st_mode
            ):
                raise SyncError(
                    "current pointer must reference a non-symlink release "
                    f"directory: {release_dir}"
                )
            release_fd = os.open(
                sha,
                _source_directory_flags(),
                dir_fd=releases_fd,
            )
            if expected_owner_uid is not None:
                releases_metadata = _require_release_identity_fd_access_policy(
                    releases_fd,
                    releases_root,
                    expected_owner_uid,
                )
                opened_release_metadata = _require_release_identity_fd_access_policy(
                    release_fd,
                    release_dir,
                    expected_owner_uid,
                )
                releases_identity = (
                    releases_metadata.st_dev,
                    releases_metadata.st_ino,
                )
                release_identity = (
                    opened_release_metadata.st_dev,
                    opened_release_metadata.st_ino,
                )
        except SyncError:
            raise
        except OSError as error:
            raise SyncError(
                f"current pointer is invalid for owner {owner}: {current}"
            ) from error

        current_metadata_after = os.stat(
            current.name,
            dir_fd=current_parent_fd,
            follow_symlinks=False,
        )
        raw_target_after = os.readlink(current.name, dir_fd=current_parent_fd)
        if (
            not stat.S_ISLNK(current_metadata_after.st_mode)
            or (current_metadata_after.st_dev, current_metadata_after.st_ino)
            != (current_metadata.st_dev, current_metadata.st_ino)
            or raw_target_after != raw_target_text
            or not _archive_entry_matches_fd(
                current_parent_fd,
                "releases",
                releases_fd,
            )
            or not _archive_entry_matches_fd(releases_fd, sha, release_fd)
        ):
            raise SyncError(
                f"current pointer changed during validation for owner {owner}"
            )
        if not _bound_directory_matches(home, current_parent, current_parent_fd):
            raise SyncError(f"current pointer parent changed: {current_parent}")
        if expected_owner_uid is not None:
            terminal_releases_metadata = _require_release_identity_fd_access_policy(
                releases_fd,
                releases_root,
                expected_owner_uid,
            )
            terminal_release_metadata = _require_release_identity_fd_access_policy(
                release_fd,
                release_dir,
                expected_owner_uid,
            )
            if releases_identity != (
                terminal_releases_metadata.st_dev,
                terminal_releases_metadata.st_ino,
            ) or release_identity != (
                terminal_release_metadata.st_dev,
                terminal_release_metadata.st_ino,
            ):
                raise _release_identity_policy_error(
                    release_dir,
                    "bound current release object changed",
                    mismatch=True,
                )
            _require_release_identity_directory_bindings(
                home,
                directory_bindings,
                expected_owner_uid,
            )
        return sha
    except OSError as error:
        raise SyncError(
            f"current pointer changed during validation for owner {owner}"
        ) from error
    finally:
        if release_fd >= 0:
            _close_fd_quietly(release_fd)
        if releases_fd >= 0:
            _close_fd_quietly(releases_fd)
        _close_fd_quietly(current_parent_fd)
        _close_release_identity_directory_bindings(directory_bindings)


def status(home: Path, owner: str = PUBLIC_OWNER) -> bool:
    home = home.expanduser()
    owner = _validate_owner(owner)
    manifest_cache: dict[tuple[str, str], ManifestData | None] = {}
    pending_authority_issues: list[str] = []
    if not _pending_link_pointer_is_absent(home):
        pending_authority_issues.append("active pending transaction must be recovered")
    elif (
        unresolved_ticket_representation := (
            _pending_cleanup_unresolved_ticket_representation_issue(home)
        )
    ) is not None:
        batch_name, member_name = unresolved_ticket_representation
        pending_authority_issues.append(
            "pending cleanup ticket representation must be reconciled before new "
            f"mutation: {batch_name}: {member_name}"
        )
    elif (
        unresolved_allocation_representation := (
            _pending_quarantine_unresolved_allocation_representation_issue(home)
        )
    ) is not None:
        batch_name, member_name = unresolved_allocation_representation
        pending_authority_issues.append(
            "pending quarantine allocation representation must be reconciled "
            f"before new mutation: {batch_name}: {member_name}"
        )
    elif _pending_cleanup_ready_batch_is_observed(home):
        pending_authority_issues.append(
            "finalized or interrupted pending transaction must be cleaned"
        )
    sha = _current_sha(home, owner)
    if sha is None:
        skill_issues = audit_active_skills(
            home,
            manifest_cache=manifest_cache,
        )
        print(f"{owner} is not installed under {_display_path(home)}")
        if pending_authority_issues:
            print(f"managed link state drift: {len(pending_authority_issues)} issue(s)")
            for issue in pending_authority_issues:
                print(f"- {issue}")
        _print_doctor_issues(skill_issues)
        return False
    release_root = _releases_root(home, owner) / sha
    if pending_authority_issues:
        print(f"current owner: {owner}")
        print(f"current release: {sha}")
        print(f"release root: {release_root}")
        print(f"managed link state drift: {len(pending_authority_issues)} issue(s)")
        for issue in pending_authority_issues:
            print(f"- {issue}")
        skill_issues = audit_active_skills(
            home,
            manifest_cache=manifest_cache,
        )
        _print_doctor_issues(skill_issues)
        return False
    entries = _load_installed_manifest_data(
        home,
        owner,
        sha,
        manifest_cache=manifest_cache,
    ).entries
    checked_entries = entries
    checked_owners = {owner}
    if owner == PUBLIC_OWNER:
        installed_manifests = _installed_manifests(
            home,
            manifest_cache=manifest_cache,
        )
        overlays = [
            manifest
            for installed_owner, manifest in sorted(installed_manifests.items())
            if installed_owner != PUBLIC_OWNER
        ]
        if overlays:
            checked_entries = _combine_entries(entries, overlays)
            checked_owners.update(manifest.owner for manifest in overlays)
            public_entries = entries
        else:
            public_entries = None
    else:
        public_entries = _current_manifest_data(
            home,
            PUBLIC_OWNER,
            manifest_cache=manifest_cache,
        ).entries
    checked_targets = {entry.target for entry in checked_entries}
    actions = plan_link_actions(
        home,
        checked_entries,
        public_entries=public_entries,
    )
    stale_removals = plan_stale_current_link_removals(
        home,
        entries,
        manifest_cache=manifest_cache,
    )
    print(f"current owner: {owner}")
    print(f"current release: {sha}")
    print(f"release root: {release_root}")
    if actions:
        print(f"managed symlink drift: {len(actions)} update(s) needed")
        for action in actions:
            print(f"- {action.action}: {action.target} -> {action.link_target}")
    else:
        print("current manifest symlinks: ok")
    if stale_removals:
        print(f"stale managed symlinks: {len(stale_removals)}")
        for removal in stale_removals:
            print(f"- stale: {removal.target}")
    state_path = _state_path(home)
    if not _path_exists_or_is_link(state_path):
        skill_issues = audit_active_skills(
            home,
            manifest_cache=manifest_cache,
        )
        print("managed link state: not initialized")
        _print_doctor_issues(skill_issues)
        return False
    state = _load_managed_state(home, manifest_cache=manifest_cache)
    state_issues = list(pending_authority_issues)
    if owner == PUBLIC_OWNER:
        checked_owners.update(state.owners)
    checked_owner_shas: dict[str, str | None] = {}
    for checked_owner in sorted(checked_owners):
        checked_sha = _current_sha(home, checked_owner)
        checked_owner_shas[checked_owner] = checked_sha
        if state.owners.get(checked_owner) != checked_sha:
            state_issues.append(
                "release mismatch: "
                f"owner={checked_owner}, state={state.owners.get(checked_owner)}, "
                f"current={checked_sha}"
            )
    for entry in checked_entries:
        if not _entry_materializes_regular_file(entry) or _is_optional_desired_entry(
            entry
        ):
            continue
        record = state.links.get(entry.target)
        checked_sha = checked_owner_shas.get(entry.owner)
        if record is None:
            state_issues.append(
                "regular file is missing its managed state claim: "
                f"{_entry_target_path(home, entry)}"
            )
            continue
        if checked_sha is None:
            continue
        expected_record = ManagedLinkRecord(
            source=entry.source,
            target=entry.target,
            kind=entry.kind,
            owner=entry.owner,
            link_target=_desired_link_target(home, entry),
            release_sha=checked_sha,
        )
        if record != expected_record:
            state_issues.append(
                f"regular file winner claim conflict: {_entry_target_path(home, entry)}"
            )
    for record in state.links.values():
        if record.target not in checked_targets:
            continue
        target = home / Path(*record.target.parts)
        if _record_materializes_regular_file(record):
            try:
                actual_snapshot = _capture_reconcile_target_snapshot(home, target)
            except (OSError, SyncError) as error:
                raise SyncError(
                    "managed regular target could not be read during status "
                    f"validation: {target}"
                ) from error
            if actual_snapshot.link_identity is None:
                state_issues.append(f"regular file missing: {target}")
                continue
            actual_regular = _regular_snapshot_from_reconcile(actual_snapshot)
            if actual_regular is None:
                state_issues.append(f"regular file type mismatch: {target}")
                continue
            if not _regular_snapshot_has_managed_access(actual_regular):
                state_issues.append(f"regular file access policy mismatch: {target}")
                continue
            expected_source = _record_regular_source_path(home, record)
            if actual_regular.sha256 != _regular_source_sha256(
                home,
                expected_source,
            ):
                state_issues.append(f"regular file content mismatch: {target}")
            continue
        try:
            actual_target = _read_optional_symlink_target_beneath(home, target)
        except OSError as error:
            raise SyncError(
                f"managed target changed during status validation: {target}"
            ) from error
        if actual_target != record.link_target:
            state_issues.append(f"link mismatch: {target}")
    if state_issues:
        print(f"managed link state drift: {len(state_issues)} issue(s)")
        for issue in state_issues:
            print(f"- {issue}")
    else:
        print("managed link state: ok")
    skill_issues = audit_active_skills(
        home,
        manifest_cache=manifest_cache,
    )
    _print_doctor_issues(skill_issues)
    return not (actions or stale_removals or state_issues or skill_issues)


def _valid_release_dirs(
    home: Path,
    owner: str,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> list[Path]:
    releases_root = _releases_root(home, owner)
    releases: list[Path] = []
    releases_fd = _open_directory_beneath(home, releases_root)
    try:
        names = _directory_member_names(
            releases_fd,
            maximum_entries=MAX_RELEASE_RETENTION_CANDIDATES,
            overflow_message="release directory entry count exceeds the limit",
        )
        for name in names:
            if RELEASE_DIR_RE.fullmatch(name) is None:
                continue
            path = releases_root / name
            mode = os.stat(name, dir_fd=releases_fd, follow_symlinks=False).st_mode
            if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
                raise SyncError(f"refusing unsafe release directory: {path}")
            try:
                _load_installed_manifest_data(
                    home,
                    owner,
                    name,
                    manifest_cache=manifest_cache,
                )
            except SyncError:
                continue
            releases.append(path)
        if (
            _directory_member_names(
                releases_fd,
                maximum_entries=MAX_RELEASE_RETENTION_CANDIDATES,
                overflow_message="release directory entry count exceeds the limit",
            )
            != names
        ):
            raise SyncError(
                f"release directory changed during validation: {releases_root}"
            )
        if not _bound_directory_matches(home, releases_root, releases_fd):
            raise SyncError(
                f"release directory changed during validation: {releases_root}"
            )
        return releases
    finally:
        _close_fd_quietly(releases_fd)


def _resolve_release_for_rollback(
    home: Path,
    to_sha: str | None,
    owner: str = PUBLIC_OWNER,
) -> str:
    releases_root = _releases_root(home, owner)
    if not _ensure_safe_internal_directory(
        home,
        releases_root,
        create=False,
        allow_missing=True,
    ):
        raise SyncError(f"release root is missing: {releases_root}")
    releases = _valid_release_dirs(home, owner)
    if to_sha:
        matches = [path.name for path in releases if path.name.startswith(to_sha)]
        if not matches:
            raise SyncError(f"no release matches {to_sha}")
        if len(matches) > 1:
            raise SyncError(f"release prefix is ambiguous: {to_sha}")
        return matches[0]

    current = _current_sha(home, owner)
    candidates = sorted(releases, key=lambda path: path.stat().st_mtime, reverse=True)
    for candidate in candidates:
        if candidate.name != current:
            return candidate.name
    raise SyncError("no previous release is available")


def rollback(home: Path, to_sha: str | None, owner: str = PUBLIC_OWNER) -> None:
    home = home.expanduser()
    cleanup_budget = PendingCleanupActionBudget(MAX_PENDING_CLEANUP_BATCHES_PER_RUN)
    with installation_lock(home):
        _recover_release_retention_transaction(home, dry_run=False)
        loaded_state, initial_state_snapshot = _load_managed_state_with_snapshot(home)
        _recover_pending_link_transaction(
            home,
            loaded_state,
            initial_state_snapshot,
            dry_run=False,
        )
        owner = _validate_owner(owner)
        if owner != PUBLIC_OWNER:
            raise SyncError(
                "rollback currently supports only public releases; rerun install-private"
            )
        if not _ensure_safe_internal_directory(
            home,
            _releases_root(home, owner),
            create=False,
            allow_missing=True,
        ):
            raise SyncError(f"release root is missing: {_releases_root(home, owner)}")
        sha = _resolve_release_for_rollback(home, to_sha, owner)
        release_root = _releases_root(home, owner) / sha
        manifest = _load_installed_manifest_data(home, owner, sha)
        release_expectation = _installed_release_identity_and_directory_identity(
            home,
            owner,
            sha,
        )
        _install_release_set_unlocked(
            home,
            [(release_root, sha, manifest, release_expectation)],
            dry_run=False,
            allow_cross_owner=False,
            cleanup_budget=cleanup_budget,
        )


def _release_pin_path(home: Path, owner: str, sha: str) -> Path:
    owner = _validate_owner(owner)
    sha = _validate_release_sha(sha)
    return (
        _personal_sync_root(home) / RELEASE_PINS_RELATIVE_PATH / owner / f"{sha}.json"
    )


def _release_pin_payload(owner: str, sha: str) -> bytes:
    return _bounded_json_document(
        {
            "version": 1,
            "owner": _validate_owner(owner),
            "sha": _validate_release_sha(sha),
        },
        max_bytes=MAX_RELEASE_RETENTION_RECORD_BYTES,
        overflow_error="release pin exceeds the size limit",
    )


def _read_release_pin(
    home: Path,
    path: Path,
    *,
    expected_identity: tuple[int, int] | None = None,
) -> tuple[tuple[str, str], ManagedStateFileSnapshot]:
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        snapshot = _read_managed_state_file_snapshot(
            home,
            path,
            parent_fd,
            expected_identity=expected_identity,
        )
    finally:
        _close_fd_quietly(parent_fd)
    if not snapshot.exists or snapshot.payload is None:
        raise SyncError(f"release pin is missing: {path}")
    if snapshot.mode != 0o600:
        raise SyncError(f"release pin mode changed: {path}")
    return _parse_release_pin_snapshot(home, path, snapshot, display_path=path)


def _parse_release_pin_snapshot(
    home: Path,
    canonical_path: Path,
    snapshot: ManagedStateFileSnapshot,
    *,
    display_path: Path,
) -> tuple[tuple[str, str], ManagedStateFileSnapshot]:
    if (
        not _managed_state_snapshot_has_complete_file_evidence(snapshot)
        or snapshot.file_type != stat.S_IFREG
        or snapshot.mode != 0o600
    ):
        raise SyncError(f"release pin has incomplete evidence: {display_path}")
    assert snapshot.payload is not None
    data = _decode_managed_state_json(snapshot.payload, display_path)
    if set(data) != {"version", "owner", "sha"} or data.get("version") != 1:
        raise SyncError(f"release pin has unsupported fields: {display_path}")
    owner = _validate_owner(data.get("owner"), "release pin owner")
    sha = _validate_release_sha(data.get("sha"), "release pin SHA")
    if canonical_path != _release_pin_path(home, owner, sha):
        raise SyncError(f"release pin path does not match its payload: {display_path}")
    if snapshot.payload != _release_pin_payload(owner, sha):
        raise SyncError(f"release pin is not canonical: {display_path}")
    return (owner, sha), snapshot


def _recover_release_pin_tombstone(
    home: Path,
    owner: str,
    sha: str,
) -> bool:
    path = _release_pin_path(home, owner, sha)
    if not _ensure_safe_internal_parent(
        home,
        path,
        create=False,
        allow_missing=True,
    ):
        return False
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        canonical = _read_managed_state_file_snapshot(home, path, parent_fd)
        retained = _retained_pending_cleanup_file(
            home,
            path,
            parent_fd,
            expected=None,
            label=f"release pin {owner}@{sha}",
        )
        if retained is None:
            return False
        if canonical.exists:
            raise SyncError(
                f"release pin has canonical and retained copies: {owner}@{sha}"
            )
        retained_name, retained_snapshot = retained
        retained_path = path.with_name(retained_name)
        reference, validated = _parse_release_pin_snapshot(
            home,
            path,
            retained_snapshot,
            display_path=retained_path,
        )
        if reference != (owner, sha):
            raise SyncError(f"retained release pin changed: {retained_path}")
        restored = _restore_retained_pending_cleanup_file(
            home,
            path,
            parent_fd,
            validated,
            label=f"release pin {owner}@{sha}",
        )
        if restored is None:
            raise SyncError(f"retained release pin disappeared: {retained_path}")
        _isolate_and_delete_pending_cleanup_file(
            home,
            path,
            parent_fd,
            restored,
            label=f"release pin {owner}@{sha}",
        )
        return True
    finally:
        _close_fd_quietly(parent_fd)


def pin_release(home: Path, owner: str, sha: str) -> None:
    home = home.expanduser()
    owner = _validate_owner(owner)
    sha = _validate_release_sha(sha)
    with installation_lock(home):
        _recover_release_retention_transaction(home, dry_run=False)
        _recover_release_pin_tombstone(home, owner, sha)
        _ensure_safe_release_directory(
            home,
            owner,
            sha,
            allow_missing=False,
        )
        path = _release_pin_path(home, owner, sha)
        _ensure_safe_internal_directory(home, path.parent, create=True)
        if _path_exists_or_is_link(path):
            existing, _snapshot = _read_release_pin(home, path)
            if existing != (owner, sha):
                raise SyncError(f"release pin changed: {path}")
        else:
            _write_exclusive_internal_file(
                home,
                path,
                _release_pin_payload(owner, sha),
            )
    print(f"pinned release: {owner}@{sha}")


def unpin_release(home: Path, owner: str, sha: str) -> None:
    home = home.expanduser()
    owner = _validate_owner(owner)
    sha = _validate_release_sha(sha)
    with installation_lock(home):
        _recover_release_retention_transaction(home, dry_run=False)
        if _recover_release_pin_tombstone(home, owner, sha):
            print(f"unpinned release: {owner}@{sha}")
            return
        path = _release_pin_path(home, owner, sha)
        if not _ensure_safe_internal_parent(
            home,
            path,
            create=False,
            allow_missing=True,
        ):
            print(f"release pin is already absent: {owner}@{sha}")
            return
        parent_fd = _open_directory_beneath(home, path.parent)
        try:
            snapshot = _read_managed_state_file_snapshot(
                home,
                path,
                parent_fd,
            )
            if not snapshot.exists:
                print(f"release pin is already absent: {owner}@{sha}")
                return
            (pinned_owner, pinned_sha), validated = _read_release_pin(
                home,
                path,
                expected_identity=snapshot.file_identity,
            )
            if (pinned_owner, pinned_sha) != (owner, sha):
                raise SyncError(f"release pin changed: {path}")
            _isolate_and_delete_pending_cleanup_file(
                home,
                path,
                parent_fd,
                validated,
                label=f"release pin {owner}@{sha}",
            )
        finally:
            _close_fd_quietly(parent_fd)
    print(f"unpinned release: {owner}@{sha}")


def _release_pin_references(home: Path) -> set[tuple[str, str]]:
    pins_root = _personal_sync_root(home) / RELEASE_PINS_RELATIVE_PATH
    if not _ensure_safe_internal_directory(
        home,
        pins_root,
        create=False,
        allow_missing=True,
    ):
        return set()
    references: set[tuple[str, str]] = set()
    pins_fd = _open_directory_beneath(home, pins_root)
    try:
        owner_names = _directory_member_names(
            pins_fd,
            maximum_entries=MAX_RELEASE_RETENTION_CANDIDATES,
            overflow_message="release pin owner count exceeds the limit",
        )
        for owner_name in owner_names:
            owner = _validate_owner(owner_name, "release pin owner")
            owner_path = pins_root / owner
            owner_fd = _open_directory_beneath(home, owner_path)
            try:
                pin_names = _directory_member_names(
                    owner_fd,
                    maximum_entries=MAX_RELEASE_RETENTION_CANDIDATES,
                    overflow_message="release pin count exceeds the limit",
                )
                for pin_name in pin_names:
                    retained_match = RETAINED_RELEASE_PIN_RE.fullmatch(pin_name)
                    if retained_match is not None:
                        sha = _validate_release_sha(
                            retained_match.group(1),
                            "retained release pin SHA",
                        )
                        retained_path = owner_path / pin_name
                        retained_snapshot = _read_managed_state_file_snapshot(
                            home,
                            retained_path,
                            owner_fd,
                        )
                        reference, _snapshot = _parse_release_pin_snapshot(
                            home,
                            _release_pin_path(home, owner, sha),
                            retained_snapshot,
                            display_path=retained_path,
                        )
                    else:
                        if not pin_name.endswith(".json"):
                            raise SyncError(
                                f"unexpected release pin entry: {owner_path / pin_name}"
                            )
                        sha = _validate_release_sha(
                            pin_name[: -len(".json")],
                            "release pin SHA",
                        )
                        reference, _snapshot = _read_release_pin(
                            home,
                            _release_pin_path(home, owner, sha),
                        )
                    references.add(reference)
            finally:
                _close_fd_quietly(owner_fd)
        if not _bound_directory_matches(home, pins_root, pins_fd):
            raise SyncError("release pin root changed during scan")
    finally:
        _close_fd_quietly(pins_fd)
    return references


def _release_retention_pointer_path(home: Path) -> Path:
    return home / RELEASE_RETENTION_POINTER_NAME


def _release_retention_clear_marker_path(home: Path) -> Path:
    return home / RELEASE_RETENTION_CLEAR_MARKER_NAME


def _release_retention_deleted_clear_marker_path(home: Path) -> Path:
    return home / RELEASE_RETENTION_DELETED_CLEAR_MARKER_NAME


def _parse_release_retention_transaction(
    home: Path,
    pointer_snapshot: ManagedStateFileSnapshot,
    *,
    clearing: bool,
    clearing_deleted: bool = False,
) -> ReleaseRetentionTransaction:
    pointer_path = _release_retention_pointer_path(home)
    if not pointer_snapshot.exists or pointer_snapshot.payload is None:
        raise SyncError("release retention pointer has no durable payload")
    if (
        pointer_snapshot.file_identity is None
        or pointer_snapshot.mode != 0o600
        or len(pointer_snapshot.payload) > MAX_RELEASE_RETENTION_RECORD_BYTES
    ):
        raise SyncError("release retention pointer is invalid")
    data = _decode_managed_state_json(pointer_snapshot.payload, pointer_path)
    expected_fields = {
        "version",
        "batch",
        "owner",
        "sha",
        "source_parent_identity",
        "source_identity",
        "quarantine_parent_identity",
        "quarantine",
        "created_at",
    }
    if set(data) != expected_fields or data.get("version") != 1:
        raise SyncError("release retention pointer has unsupported fields")
    batch_name = data.get("batch")
    if (
        not isinstance(batch_name, str)
        or not batch_name.startswith(RELEASE_RETENTION_BATCH_PREFIX)
        or len(batch_name.encode("utf-8")) > MAX_PENDING_LINK_BATCH_NAME_BYTES
        or "/" in batch_name
    ):
        raise SyncError("release retention pointer has an invalid batch")
    owner = _validate_owner(data.get("owner"), "retention owner")
    sha = _validate_release_sha(data.get("sha"), "retention SHA")
    source_parent_identity = _parse_pending_identity(
        data.get("source_parent_identity"),
        "retention source parent identity",
    )
    source_identity = _parse_pending_identity(
        data.get("source_identity"),
        "retention source identity",
    )
    quarantine_parent_identity = _parse_pending_identity(
        data.get("quarantine_parent_identity"),
        "retention quarantine parent identity",
    )
    if (
        source_parent_identity is None
        or source_identity is None
        or quarantine_parent_identity is None
    ):
        raise SyncError("release retention pointer is missing object identity")
    batch_root = (
        _personal_sync_root(home)
        / RELEASE_RETENTION_QUARANTINE_RELATIVE_PATH
        / batch_name
    )
    destination = batch_root / "release" / sha
    try:
        expected_quarantine = destination.relative_to(home).as_posix()
    except ValueError as error:
        raise SyncError("release retention destination is outside home") from error
    if data.get("quarantine") != expected_quarantine:
        raise SyncError("release retention destination is not canonical")
    created_at = data.get("created_at")
    if not isinstance(created_at, str) or not created_at:
        raise SyncError("release retention timestamp is invalid")
    expected_payload = _retention_record_payload(
        home,
        batch_name,
        owner,
        sha,
        source_parent_identity,
        source_identity,
        quarantine_parent_identity,
        destination,
        created_at=created_at,
    )
    if pointer_snapshot.payload != expected_payload:
        raise SyncError("release retention pointer is not canonical")

    try:
        batch_fd = _open_directory_beneath(home, batch_root)
    except FileNotFoundError as error:
        if not clearing:
            raise SyncError(
                "release retention stable pointer has no quarantine batch"
            ) from error
        return ReleaseRetentionTransaction(
            batch_root=batch_root,
            batch_root_identity=None,
            owner=owner,
            sha=sha,
            source_parent_identity=source_parent_identity,
            source_identity=source_identity,
            quarantine_parent_identity=quarantine_parent_identity,
            destination=destination,
            record_snapshot=pointer_snapshot,
            pointer_snapshot=pointer_snapshot,
            committed=False,
            deletion_started=False,
            deletion_complete=False,
            clearing=True,
            clearing_deleted=clearing_deleted,
        )
    try:
        batch_root_identity = _directory_identity(batch_fd)
        if not _bound_directory_matches(home, batch_root, batch_fd):
            raise SyncError("release retention batch root changed")
        record_path = batch_root / RELEASE_RETENTION_RECORD_NAME
        record_snapshot = _read_managed_state_file_snapshot(
            home,
            record_path,
            batch_fd,
            expected_identity=pointer_snapshot.file_identity,
        )
        if not record_snapshot.exists and clearing:
            record_snapshot = pointer_snapshot
        elif not (
            _managed_state_snapshot_matches_file_evidence(
                record_snapshot,
                pointer_snapshot,
            )
            and record_snapshot.mode == 0o600
        ):
            raise SyncError(
                "release retention pointer is not bound to its batch record"
            )
        marker_path = batch_root / RELEASE_RETENTION_COMMIT_MARKER_NAME
        marker_snapshot = _read_managed_state_file_snapshot(
            home,
            marker_path,
            batch_fd,
        )
        if marker_snapshot.exists and not (
            _managed_state_snapshot_matches_file_evidence(
                marker_snapshot,
                pointer_snapshot,
            )
            and marker_snapshot.mode == 0o600
        ):
            raise SyncError("release retention commit marker changed")
        deletion_started_path = (
            batch_root / RELEASE_RETENTION_DELETE_STARTED_MARKER_NAME
        )
        deletion_started_snapshot = _read_managed_state_file_snapshot(
            home,
            deletion_started_path,
            batch_fd,
        )
        if deletion_started_snapshot.exists and not (
            _managed_state_snapshot_matches_file_evidence(
                deletion_started_snapshot,
                pointer_snapshot,
            )
            and deletion_started_snapshot.mode == 0o600
        ):
            raise SyncError("release retention deletion-start marker changed")
        deletion_marker_path = (
            batch_root / RELEASE_RETENTION_DELETE_COMPLETE_MARKER_NAME
        )
        deletion_marker_snapshot = _read_managed_state_file_snapshot(
            home,
            deletion_marker_path,
            batch_fd,
        )
        if deletion_marker_snapshot.exists and not (
            _managed_state_snapshot_matches_file_evidence(
                deletion_marker_snapshot,
                pointer_snapshot,
            )
            and deletion_marker_snapshot.mode == 0o600
        ):
            raise SyncError("release retention deletion marker changed")
        if (
            not clearing
            and deletion_started_snapshot.exists
            and not marker_snapshot.exists
        ):
            raise SyncError("release retention deletion started without commit marker")
        if (
            not clearing
            and deletion_marker_snapshot.exists
            and not (marker_snapshot.exists and deletion_started_snapshot.exists)
        ):
            raise SyncError(
                "release retention deletion marker exists without start marker"
            )
    finally:
        _close_fd_quietly(batch_fd)
    return ReleaseRetentionTransaction(
        batch_root=batch_root,
        batch_root_identity=batch_root_identity,
        owner=owner,
        sha=sha,
        source_parent_identity=source_parent_identity,
        source_identity=source_identity,
        quarantine_parent_identity=quarantine_parent_identity,
        destination=destination,
        record_snapshot=record_snapshot,
        pointer_snapshot=pointer_snapshot,
        committed=marker_snapshot.exists,
        deletion_started=deletion_started_snapshot.exists,
        deletion_complete=deletion_marker_snapshot.exists,
        clearing=clearing,
        clearing_deleted=clearing_deleted,
    )


def _load_release_retention_transaction(
    home: Path,
) -> ReleaseRetentionTransaction | None:
    pointer_path = _release_retention_pointer_path(home)
    clear_marker_path = _release_retention_clear_marker_path(home)
    deleted_clear_marker_path = _release_retention_deleted_clear_marker_path(home)
    try:
        home_fd = _open_directory_beneath(home, home)
    except FileNotFoundError:
        return None
    try:
        pointer_snapshot = _read_managed_state_file_snapshot(
            home,
            pointer_path,
            home_fd,
        )
        clear_marker_snapshot = _read_managed_state_file_snapshot(
            home,
            clear_marker_path,
            home_fd,
        )
        deleted_clear_marker_snapshot = _read_managed_state_file_snapshot(
            home,
            deleted_clear_marker_path,
            home_fd,
        )
        if not clear_marker_snapshot.exists:
            retained_clear = _retained_pending_cleanup_file(
                home,
                clear_marker_path,
                home_fd,
                expected=None,
                label="release retention clear marker",
            )
            if retained_clear is not None:
                _retained_name, clear_marker_snapshot = retained_clear
        if not deleted_clear_marker_snapshot.exists:
            retained_deleted_clear = _retained_pending_cleanup_file(
                home,
                deleted_clear_marker_path,
                home_fd,
                expected=None,
                label="deleted release retention clear marker",
            )
            if retained_deleted_clear is not None:
                (
                    _retained_name,
                    deleted_clear_marker_snapshot,
                ) = retained_deleted_clear
    finally:
        _close_fd_quietly(home_fd)
    if clear_marker_snapshot.exists and deleted_clear_marker_snapshot.exists:
        raise SyncError("release retention has multiple clear markers")
    selected_clear_snapshot = (
        deleted_clear_marker_snapshot
        if deleted_clear_marker_snapshot.exists
        else clear_marker_snapshot
    )
    if not pointer_snapshot.exists and not selected_clear_snapshot.exists:
        return None
    if selected_clear_snapshot.exists and (
        selected_clear_snapshot.payload is None
        or selected_clear_snapshot.file_identity is None
        or selected_clear_snapshot.mode != 0o600
        or (
            pointer_snapshot.exists
            and not (
                _managed_state_snapshot_matches_file_evidence(
                    selected_clear_snapshot,
                    pointer_snapshot,
                )
                and selected_clear_snapshot.mode == pointer_snapshot.mode
            )
        )
    ):
        raise SyncError("release retention clear marker changed")
    selected_snapshot = (
        pointer_snapshot if pointer_snapshot.exists else selected_clear_snapshot
    )
    return _parse_release_retention_transaction(
        home,
        selected_snapshot,
        clearing=selected_clear_snapshot.exists,
        clearing_deleted=deleted_clear_marker_snapshot.exists,
    )


def _recovery_record_references(
    home: Path,
    *,
    include_retention: bool = True,
) -> set[tuple[str, str]]:
    references: set[tuple[str, str]] = set()
    active_pending = _load_pending_link_batch(home)
    if active_pending is not None:
        for expectation in (
            *active_pending.releases_before,
            *active_pending.releases_after,
        ):
            references.add((expectation.owner, expectation.sha))

    quarantine_root = _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH
    if not _ensure_safe_internal_directory(
        home,
        quarantine_root,
        create=False,
        allow_missing=True,
    ):
        retention = _load_release_retention_transaction(home)
        if retention is not None and include_retention:
            references.add((retention.owner, retention.sha))
        return references
    quarantine_fd = _open_directory_beneath(home, quarantine_root)
    try:
        batch_names = _directory_member_names(
            quarantine_fd,
            maximum_entries=MAX_PENDING_CLEANUP_BATCH_SCAN,
            overflow_message="release recovery record scan exceeds the limit",
        )
        for batch_name in batch_names:
            batch_path = quarantine_root / batch_name
            try:
                batch_metadata = os.stat(
                    batch_name,
                    dir_fd=quarantine_fd,
                    follow_symlinks=False,
                )
            except OSError as error:
                raise SyncError(
                    f"release recovery batch changed: {batch_path}"
                ) from error
            if batch_name == "releases":
                continue
            if _pending_cleanup_batch_name_from_quarantine_entry(batch_name) is None:
                continue
            if not stat.S_ISDIR(batch_metadata.st_mode):
                raise SyncError(f"release recovery batch is unsafe: {batch_path}")
            batch_fd = _open_directory_beneath(home, batch_path)
            try:
                record_path = batch_path / PENDING_LINK_METADATA_NAME
                snapshot = _read_managed_state_file_snapshot(
                    home,
                    record_path,
                    batch_fd,
                )
                if not snapshot.exists:
                    continue
                if snapshot.payload is None:
                    raise SyncError(
                        f"release recovery record is unreadable: {record_path}"
                    )
                parsed = _parse_pending_link_batch(home, snapshot.payload, snapshot)
                for expectation in (
                    *parsed.releases_before,
                    *parsed.releases_after,
                ):
                    references.add((expectation.owner, expectation.sha))
            finally:
                _close_fd_quietly(batch_fd)
        if not _bound_directory_matches(home, quarantine_root, quarantine_fd):
            raise SyncError("release recovery record root changed during scan")
    finally:
        _close_fd_quietly(quarantine_fd)
    retention = _load_release_retention_transaction(home)
    retention_root = (
        _personal_sync_root(home) / RELEASE_RETENTION_QUARANTINE_RELATIVE_PATH
    )
    if _ensure_safe_internal_directory(
        home,
        retention_root,
        create=False,
        allow_missing=True,
    ):
        retention_fd = _open_directory_beneath(home, retention_root)
        try:
            names = _directory_member_names(
                retention_fd,
                maximum_entries=2,
                overflow_message="multiple release retention batches require recovery",
            )
            expected = (
                ()
                if retention is None or retention.batch_root_identity is None
                else (retention.batch_root.name,)
            )
            if names != expected:
                raise SyncError(
                    "release retention quarantine does not match the stable pointer"
                )
        finally:
            _close_fd_quietly(retention_fd)
    elif retention is not None:
        raise SyncError("release retention stable pointer has no quarantine root")
    if retention is not None and include_retention:
        references.add((retention.owner, retention.sha))
    return references


def _retained_release_references(
    home: Path,
    *,
    exclude_retention: tuple[str, str] | None = None,
) -> dict[tuple[str, str], set[str]]:
    references: dict[tuple[str, str], set[str]] = {}

    def retain(owner: str, sha: str, reason: str) -> None:
        references.setdefault((owner, sha), set()).add(reason)

    state = _load_managed_state(home)
    for owner, sha in state.owners.items():
        retain(owner, sha, "ledger")
    for record in state.links.values():
        retain(record.owner, record.release_sha, "ledger-link")
    for owner in _known_owners(home, set(state.owners)):
        sha = _current_sha(home, owner)
        if sha is not None:
            retain(owner, sha, "current")
    for owner, sha in _release_pin_references(home):
        retain(owner, sha, "user-pin")
    for owner, sha in _recovery_record_references(
        home,
        include_retention=exclude_retention is None,
    ):
        retain(owner, sha, "recovery-record")
    return references


def _retention_record_payload(
    home: Path,
    batch_name: str,
    owner: str,
    sha: str,
    source_parent_identity: tuple[int, int],
    source_identity: tuple[int, int],
    quarantine_parent_identity: tuple[int, int],
    destination: Path,
    *,
    created_at: str | None = None,
) -> bytes:
    if created_at is None:
        created_at = datetime.now(timezone.utc).isoformat()
    if not batch_name.startswith(RELEASE_RETENTION_BATCH_PREFIX) or "/" in batch_name:
        raise SyncError("release retention batch name is invalid")
    try:
        quarantine = destination.relative_to(home).as_posix()
    except ValueError as error:
        raise SyncError("release retention destination is outside home") from error
    return _bounded_json_document(
        {
            "version": 1,
            "batch": batch_name,
            "owner": _validate_owner(owner),
            "sha": _validate_release_sha(sha),
            "source_parent_identity": _identity_payload(source_parent_identity),
            "source_identity": _identity_payload(source_identity),
            "quarantine_parent_identity": _identity_payload(quarantine_parent_identity),
            "quarantine": quarantine,
            "created_at": created_at,
        },
        max_bytes=MAX_RELEASE_RETENTION_RECORD_BYTES,
        overflow_error="release retention record exceeds the size limit",
    )


def _create_release_retention_batch(home: Path) -> tuple[Path, int]:
    quarantine_root = (
        _personal_sync_root(home) / RELEASE_RETENTION_QUARANTINE_RELATIVE_PATH
    )
    quarantine_fd = _open_or_create_directory_beneath(
        home,
        quarantine_root,
        mode=0o700,
    )
    try:
        if not _bound_directory_matches(home, quarantine_root, quarantine_fd):
            raise SyncError("release retention quarantine root changed")
        for _attempt in range(128):
            stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
            batch_name = (
                f"{RELEASE_RETENTION_BATCH_PREFIX}{stamp}-"
                f"{os.getpid()}-{time.time_ns()}-{os.urandom(4).hex()}"
            )
            try:
                os.mkdir(batch_name, mode=0o700, dir_fd=quarantine_fd)
            except FileExistsError:
                continue
            os.fsync(quarantine_fd)
            batch_root = quarantine_root / batch_name
            batch_fd = _open_directory_beneath(home, batch_root)
            if not _bound_directory_matches(home, batch_root, batch_fd):
                _close_fd_quietly(batch_fd)
                raise SyncError("release retention batch changed after creation")
            return batch_root, batch_fd
    finally:
        _close_fd_quietly(quarantine_fd)
    raise SyncError("could not allocate a release retention quarantine batch")


def _delete_quarantined_release(
    home: Path,
    destination: Path,
    expected_identity: tuple[int, int],
    expected_parent_identity: tuple[int, int],
) -> None:
    release_parent = destination.parent
    release_parent_fd = _open_directory_beneath(home, release_parent)
    release_fd = -1
    try:
        if _directory_identity(release_parent_fd) != expected_parent_identity:
            raise SyncError(f"quarantined release parent changed: {release_parent}")
        current = os.stat(
            destination.name,
            dir_fd=release_parent_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISDIR(current.st_mode)
            or (current.st_dev, current.st_ino) != expected_identity
        ):
            raise SyncError(f"quarantined release object changed: {destination}")
        active_name = (
            f".cleanup-active-release-{expected_identity[0]:x}-"
            f"{expected_identity[1]:x}-{os.urandom(8).hex()}"
        )
        _rename_noreplace_at(
            release_parent_fd,
            destination.name,
            release_parent_fd,
            active_name,
        )
        os.fsync(release_parent_fd)
        active_path = release_parent / active_name
        release_fd = _open_directory_beneath(home, active_path)
        release_identity = _directory_identity(release_fd)
        if release_identity != expected_identity:
            raise SyncError(
                f"quarantined release changed after isolation: {destination}"
            )
        _remove_pending_batch_directory_contents(
            release_fd,
            release_identity,
            _directory_mount_identity(release_fd),
            [MAX_PENDING_CLEANUP_ENTRIES],
            depth=0,
            directory_expected_mode=None,
            regular_file_expected_mode=None,
        )
        isolated = os.stat(
            active_name,
            dir_fd=release_parent_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISDIR(isolated.st_mode)
            or (isolated.st_dev, isolated.st_ino) != expected_identity
            or _directory_identity(release_fd) != expected_identity
            or not _bound_directory_matches(home, active_path, release_fd)
            or _directory_identity(release_parent_fd) != expected_parent_identity
            or not _bound_directory_matches(
                home,
                release_parent,
                release_parent_fd,
            )
        ):
            raise SyncError(
                f"quarantined release changed before deletion: {destination}"
            )
        os.rmdir(active_name, dir_fd=release_parent_fd)
        os.fsync(release_parent_fd)
        if _named_entry_identity(release_parent_fd, active_name) is not None:
            raise SyncError(f"quarantined release reappeared: {destination}")
    finally:
        if release_fd >= 0:
            _close_fd_quietly(release_fd)
        _close_fd_quietly(release_parent_fd)


def _publish_release_retention_pointer(
    home: Path,
    batch_root: Path,
    record_snapshot: ManagedStateFileSnapshot,
) -> ManagedStateFileSnapshot:
    pointer_path = _release_retention_pointer_path(home)
    if _path_exists_or_is_link(pointer_path):
        raise SyncError("a release retention transaction is already active")
    return _publish_regular_hardlink_beneath(
        home,
        batch_root / RELEASE_RETENTION_RECORD_NAME,
        pointer_path,
        record_snapshot,
    )


def _publish_release_retention_commit_marker(
    home: Path,
    transaction: ReleaseRetentionTransaction,
) -> None:
    marker = transaction.batch_root / RELEASE_RETENTION_COMMIT_MARKER_NAME
    if _path_exists_or_is_link(marker):
        raise SyncError("release retention commit marker already exists")
    _publish_regular_hardlink_beneath(
        home,
        transaction.batch_root / RELEASE_RETENTION_RECORD_NAME,
        marker,
        transaction.record_snapshot,
    )


def _publish_release_retention_delete_complete_marker(
    home: Path,
    transaction: ReleaseRetentionTransaction,
) -> None:
    if not transaction.committed or not transaction.deletion_started:
        raise SyncError("release retention deletion cannot complete before it starts")
    marker = transaction.batch_root / RELEASE_RETENTION_DELETE_COMPLETE_MARKER_NAME
    if _path_exists_or_is_link(marker):
        raise SyncError("release retention deletion marker already exists")
    _publish_regular_hardlink_beneath(
        home,
        transaction.batch_root / RELEASE_RETENTION_RECORD_NAME,
        marker,
        transaction.record_snapshot,
    )


def _publish_release_retention_delete_started_marker(
    home: Path,
    transaction: ReleaseRetentionTransaction,
) -> None:
    if not transaction.committed or transaction.deletion_complete:
        raise SyncError("release retention deletion cannot start in its current phase")
    marker = transaction.batch_root / RELEASE_RETENTION_DELETE_STARTED_MARKER_NAME
    if _path_exists_or_is_link(marker):
        raise SyncError("release retention deletion-start marker already exists")
    _delete_retention_file(
        home,
        marker,
        transaction.pointer_snapshot,
        label="retained release retention deletion-start marker",
    )
    _publish_regular_hardlink_beneath(
        home,
        transaction.batch_root / RELEASE_RETENTION_RECORD_NAME,
        marker,
        transaction.record_snapshot,
    )


def _publish_release_retention_clear_marker(
    home: Path,
    transaction: ReleaseRetentionTransaction,
) -> None:
    marker = (
        _release_retention_deleted_clear_marker_path(home)
        if transaction.deletion_complete
        else _release_retention_clear_marker_path(home)
    )
    if _path_exists_or_is_link(marker):
        loaded = _load_release_retention_transaction(home)
        if (
            loaded is None
            or not loaded.clearing
            or loaded.clearing_deleted != transaction.deletion_complete
            or loaded.pointer_snapshot.file_identity
            != transaction.pointer_snapshot.file_identity
            or loaded.pointer_snapshot.payload != transaction.pointer_snapshot.payload
        ):
            raise SyncError("release retention clear marker changed")
        return
    if transaction.batch_root_identity is None:
        raise SyncError("release retention batch vanished before clear publication")
    _publish_regular_hardlink_beneath(
        home,
        transaction.batch_root / RELEASE_RETENTION_RECORD_NAME,
        marker,
        transaction.record_snapshot,
    )


def _release_entry_identity(path: Path) -> tuple[int, int] | None:
    try:
        metadata = path.lstat()
    except FileNotFoundError:
        return None
    except OSError as error:
        raise SyncError(f"failed to inspect retained release object: {path}") from error
    if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise SyncError(f"retained release object is not a safe directory: {path}")
    return metadata.st_dev, metadata.st_ino


def _quarantined_release_path(
    home: Path,
    transaction: ReleaseRetentionTransaction,
) -> Path | None:
    identity = _release_entry_identity(transaction.destination)
    if identity is not None:
        if identity != transaction.source_identity:
            raise SyncError("quarantined release object identity changed")
        return transaction.destination
    parent = transaction.destination.parent
    if not _ensure_safe_internal_directory(
        home,
        parent,
        create=False,
        allow_missing=True,
    ):
        return None
    parent_fd = _open_directory_beneath(home, parent)
    try:
        if _directory_identity(parent_fd) != transaction.quarantine_parent_identity:
            raise SyncError("release retention quarantine parent changed")
        matches: list[Path] = []
        prefix = (
            f".cleanup-active-release-{transaction.source_identity[0]:x}-"
            f"{transaction.source_identity[1]:x}-"
        )
        for name in _directory_member_names(
            parent_fd,
            maximum_entries=4,
            overflow_message="release retention directory has unexpected entries",
        ):
            if not name.startswith(prefix):
                raise SyncError(
                    f"release retention directory has an unexpected entry: {name}"
                )
            metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            if (
                stat.S_ISDIR(metadata.st_mode)
                and (metadata.st_dev, metadata.st_ino) == transaction.source_identity
            ):
                matches.append(parent / name)
        if len(matches) > 1:
            raise SyncError("release retention has multiple matching objects")
        return matches[0] if matches else None
    finally:
        _close_fd_quietly(parent_fd)


def _delete_retention_file(
    home: Path,
    path: Path,
    expected: ManagedStateFileSnapshot,
    *,
    label: str,
) -> None:
    if (
        not _managed_state_snapshot_has_complete_file_evidence(expected)
        or expected.file_type != stat.S_IFREG
        or expected.mode != 0o600
        or len(expected.payload) > MAX_RELEASE_RETENTION_RECORD_BYTES
    ):
        raise SyncError(f"{label} has incomplete expected evidence")
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        snapshot = _read_managed_state_file_snapshot(
            home,
            path,
            parent_fd,
        )
        if not snapshot.exists:
            restored = _restore_retained_pending_cleanup_file(
                home,
                path,
                parent_fd,
                expected,
                label=label,
            )
            if restored is None:
                return
            snapshot = restored
        if not _managed_state_snapshot_matches_file_evidence(snapshot, expected):
            raise SyncError(f"{label} changed before deletion")
        _isolate_and_delete_pending_cleanup_file(
            home,
            path,
            parent_fd,
            snapshot,
            label=label,
        )
    finally:
        _close_fd_quietly(parent_fd)


def _clear_release_retention_transaction(
    home: Path,
    transaction: ReleaseRetentionTransaction,
) -> None:
    if (
        not transaction.clearing
        and transaction.committed
        and not transaction.deletion_complete
    ):
        raise SyncError(
            "cannot clear committed release retention without durable deletion evidence"
        )
    if _quarantined_release_path(home, transaction) is not None:
        raise SyncError("cannot clear release retention while quarantine is occupied")
    release_parent = transaction.destination.parent
    if _ensure_safe_internal_directory(
        home,
        release_parent,
        create=False,
        allow_missing=True,
    ):
        release_parent_fd = _open_directory_beneath(home, release_parent)
        try:
            if _directory_member_names(release_parent_fd):
                raise SyncError("release retention directory is not empty")
        finally:
            _close_fd_quietly(release_parent_fd)

    if not transaction.clearing:
        _publish_release_retention_clear_marker(home, transaction)
    _delete_retention_file(
        home,
        _release_retention_pointer_path(home),
        transaction.pointer_snapshot,
        label="release retention stable pointer",
    )
    if transaction.batch_root_identity is not None:
        deletion_marker = (
            transaction.batch_root / RELEASE_RETENTION_DELETE_COMPLETE_MARKER_NAME
        )
        _delete_retention_file(
            home,
            deletion_marker,
            transaction.pointer_snapshot,
            label="release retention deletion marker",
        )
        deletion_started_marker = (
            transaction.batch_root / RELEASE_RETENTION_DELETE_STARTED_MARKER_NAME
        )
        _delete_retention_file(
            home,
            deletion_started_marker,
            transaction.pointer_snapshot,
            label="release retention deletion-start marker",
        )
        marker = transaction.batch_root / RELEASE_RETENTION_COMMIT_MARKER_NAME
        _delete_retention_file(
            home,
            marker,
            transaction.pointer_snapshot,
            label="release retention commit marker",
        )
        _delete_retention_file(
            home,
            transaction.batch_root / RELEASE_RETENTION_RECORD_NAME,
            transaction.pointer_snapshot,
            label="release retention batch record",
        )
        batch_fd = _open_directory_beneath(home, transaction.batch_root)
        try:
            if _path_exists_or_is_link(release_parent):
                os.rmdir(release_parent.name, dir_fd=batch_fd)
                os.fsync(batch_fd)
            if _directory_member_names(batch_fd):
                raise SyncError("release retention batch is not empty")
        finally:
            _close_fd_quietly(batch_fd)
        retention_root = transaction.batch_root.parent
        retention_fd = _open_directory_beneath(home, retention_root)
        try:
            current = os.stat(
                transaction.batch_root.name,
                dir_fd=retention_fd,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISDIR(current.st_mode)
                or (current.st_dev, current.st_ino) != transaction.batch_root_identity
            ):
                raise SyncError("release retention batch identity changed")
            os.rmdir(transaction.batch_root.name, dir_fd=retention_fd)
            os.fsync(retention_fd)
        finally:
            _close_fd_quietly(retention_fd)
    _delete_retention_file(
        home,
        (
            _release_retention_deleted_clear_marker_path(home)
            if transaction.clearing_deleted or transaction.deletion_complete
            else _release_retention_clear_marker_path(home)
        ),
        transaction.pointer_snapshot,
        label="release retention clear marker",
    )


def _abort_committed_release_retention(
    home: Path,
    transaction: ReleaseRetentionTransaction,
    quarantined: Path,
) -> None:
    if not transaction.committed or transaction.deletion_complete:
        raise SyncError("release retention cannot be aborted in its current phase")
    canonical = _releases_root(home, transaction.owner) / transaction.sha
    if _release_entry_identity(canonical) is not None:
        raise SyncError("release retention canonical object reappeared before abort")
    if transaction.deletion_started:
        _delete_retention_file(
            home,
            transaction.batch_root / RELEASE_RETENTION_DELETE_STARTED_MARKER_NAME,
            transaction.pointer_snapshot,
            label="release retention deletion-start marker",
        )
    _delete_retention_file(
        home,
        transaction.batch_root / RELEASE_RETENTION_COMMIT_MARKER_NAME,
        transaction.pointer_snapshot,
        label="release retention commit marker",
    )
    uncommitted = _load_release_retention_transaction(home)
    if (
        uncommitted is None
        or uncommitted.committed
        or uncommitted.deletion_started
        or uncommitted.deletion_complete
        or uncommitted.clearing
    ):
        raise SyncError("release retention abort did not durably revoke deletion")
    current_quarantine = _quarantined_release_path(home, uncommitted)
    if current_quarantine is None:
        raise SyncError("release retention quarantine disappeared during abort")
    _atomic_move_beneath_home(
        home,
        current_quarantine,
        canonical,
        expected_destination_parent_identity=(uncommitted.source_parent_identity),
        expected_entry_identity=uncommitted.source_identity,
    )
    if _release_entry_identity(canonical) != uncommitted.source_identity:
        raise SyncError("release retention abort restoration could not be verified")
    _clear_release_retention_transaction(home, uncommitted)


def _recover_release_retention_transaction(
    home: Path,
    *,
    dry_run: bool,
) -> ReleaseRetentionRecoveryOutcome | None:
    if not dry_run:
        _recover_failed_move_isolation(home)
    transaction = _load_release_retention_transaction(home)
    if transaction is None:
        return None
    canonical = _releases_root(home, transaction.owner) / transaction.sha
    canonical_identity = _release_entry_identity(canonical)
    quarantined = _quarantined_release_path(home, transaction)
    action: str
    references: dict[tuple[str, str], set[str]] = {}
    if transaction.clearing:
        if quarantined is not None:
            raise SyncError(
                "clearing release retention unexpectedly contains a release"
            )
        action = "finish durable cleanup"
    elif transaction.committed:
        references = _retained_release_references(
            home,
            exclude_retention=(transaction.owner, transaction.sha),
        )
        protected = (transaction.owner, transaction.sha) in references
        if canonical_identity is not None:
            raise SyncError(
                "committed release retention unexpectedly has a canonical release"
            )
        if protected:
            reasons = ", ".join(
                sorted(references[(transaction.owner, transaction.sha)])
            )
            if quarantined is None or transaction.deletion_complete:
                raise SyncError(
                    "committed release retention gained a protected reference "
                    "after deletion; recovery evidence was retained: "
                    f"{transaction.owner}@{transaction.sha} ({reasons})"
                )
            action = "restore a newly protected release"
        elif quarantined is not None:
            if transaction.deletion_complete:
                raise SyncError(
                    "release retention has deletion evidence while quarantine "
                    "is occupied"
                )
            action = "finish committed deletion"
        elif transaction.deletion_complete:
            action = "finish durable cleanup"
        elif transaction.deletion_started:
            action = "record and clean up the completed deletion"
        else:
            raise SyncError(
                "committed release retention deletion is ambiguous; "
                "stable evidence was retained"
            )
    elif canonical_identity == transaction.source_identity and quarantined is None:
        action = "clear the pre-move retention record"
    elif canonical_identity is None and quarantined is not None:
        action = "restore the quarantined release"
    else:
        raise SyncError(
            "release retention recovery is ambiguous; stable evidence was retained"
        )

    outcome = ReleaseRetentionRecoveryOutcome(
        owner=transaction.owner,
        sha=transaction.sha,
        action=action,
        deleted=bool(
            transaction.clearing_deleted
            or (
                transaction.committed
                and quarantined is None
                and (transaction.deletion_started or transaction.deletion_complete)
            )
        ),
    )
    if dry_run:
        print(
            "would recover release retention transaction: "
            f"{transaction.owner}@{transaction.sha} ({action})"
        )
        return outcome

    if transaction.clearing:
        _clear_release_retention_transaction(home, transaction)
        return outcome

    if transaction.committed:
        if (transaction.owner, transaction.sha) in references:
            assert quarantined is not None
            _abort_committed_release_retention(
                home,
                transaction,
                quarantined,
            )
            return outcome
        if quarantined is not None:
            if not transaction.deletion_started:
                _publish_release_retention_delete_started_marker(
                    home,
                    transaction,
                )
                transaction = _load_release_retention_transaction(home)
                if transaction is None or not transaction.deletion_started:
                    raise SyncError(
                        "release retention deletion-start marker was not durable"
                    )
            references_at_delete = _retained_release_references(
                home,
                exclude_retention=(transaction.owner, transaction.sha),
            )
            if (transaction.owner, transaction.sha) in references_at_delete:
                _abort_committed_release_retention(
                    home,
                    transaction,
                    quarantined,
                )
                reasons = ", ".join(
                    sorted(references_at_delete[(transaction.owner, transaction.sha)])
                )
                raise SyncError(
                    "release became referenced at recovery deletion: "
                    f"{transaction.owner}@{transaction.sha} ({reasons})"
                )
            _delete_quarantined_release(
                home,
                quarantined,
                transaction.source_identity,
                transaction.quarantine_parent_identity,
            )
            _publish_release_retention_delete_complete_marker(
                home,
                transaction,
            )
            transaction = _load_release_retention_transaction(home)
            if transaction is None or not transaction.deletion_complete:
                raise SyncError("release retention deletion marker was not durable")
            outcome = ReleaseRetentionRecoveryOutcome(
                owner=transaction.owner,
                sha=transaction.sha,
                action=action,
                deleted=True,
            )
        elif transaction.deletion_started and not transaction.deletion_complete:
            _publish_release_retention_delete_complete_marker(
                home,
                transaction,
            )
            transaction = _load_release_retention_transaction(home)
            if transaction is None or not transaction.deletion_complete:
                raise SyncError("release retention deletion marker was not durable")
            outcome = ReleaseRetentionRecoveryOutcome(
                owner=transaction.owner,
                sha=transaction.sha,
                action=action,
                deleted=True,
            )
        _clear_release_retention_transaction(home, transaction)
        return outcome

    if canonical_identity == transaction.source_identity and quarantined is None:
        _clear_release_retention_transaction(home, transaction)
        return outcome
    if canonical_identity is None and quarantined is not None:
        canonical_parent_fd = _open_directory_beneath(home, canonical.parent)
        try:
            if (
                _directory_identity(canonical_parent_fd)
                != transaction.source_parent_identity
            ):
                raise SyncError(
                    "release retention canonical parent changed before recovery"
                )
        finally:
            _close_fd_quietly(canonical_parent_fd)
        _atomic_move_beneath_home(
            home,
            quarantined,
            canonical,
            expected_destination_parent_identity=transaction.source_parent_identity,
            expected_entry_identity=transaction.source_identity,
        )
        if _release_entry_identity(canonical) != transaction.source_identity:
            raise SyncError("release retention exact restoration could not be verified")
        _clear_release_retention_transaction(home, transaction)
        return outcome
    raise AssertionError("release retention recovery action was not executable")


def _prune_release_candidate(
    home: Path,
    owner: str,
    sha: str,
    expected_identity: tuple[int, int],
) -> None:
    source = _releases_root(home, owner) / sha
    references = _retained_release_references(home)
    if (owner, sha) in references:
        reasons = ", ".join(sorted(references[(owner, sha)]))
        raise SyncError(
            f"release became referenced before retention: {owner}@{sha} ({reasons})"
        )
    batch_root, batch_fd = _create_release_retention_batch(home)
    pointer_published = False
    record_snapshot: ManagedStateFileSnapshot | None = None
    try:
        destination_parent = batch_root / "release"
        destination_parent_fd = _open_or_create_directory_beneath(
            home,
            destination_parent,
            mode=0o700,
        )
        try:
            quarantine_parent_identity = _directory_identity(destination_parent_fd)
        finally:
            _close_fd_quietly(destination_parent_fd)
        source_parent_fd = _open_directory_beneath(home, source.parent)
        try:
            source_parent_identity = _directory_identity(source_parent_fd)
        finally:
            _close_fd_quietly(source_parent_fd)
        destination = destination_parent / sha
        record_path = batch_root / RELEASE_RETENTION_RECORD_NAME
        record_snapshot = _write_exclusive_internal_file(
            home,
            record_path,
            _retention_record_payload(
                home,
                batch_root.name,
                owner,
                sha,
                source_parent_identity,
                expected_identity,
                quarantine_parent_identity,
                destination,
            ),
        )
        _publish_release_retention_pointer(
            home,
            batch_root,
            record_snapshot,
        )
        pointer_published = True
        transaction = _load_release_retention_transaction(home)
        if transaction is None:
            raise SyncError("release retention pointer disappeared after publication")
        _atomic_move_beneath_home(
            home,
            source,
            destination,
            expected_destination_parent_identity=quarantine_parent_identity,
            expected_entry_identity=expected_identity,
        )
        references_after_move = _retained_release_references(
            home,
            exclude_retention=(owner, sha),
        )
        if (owner, sha) in references_after_move:
            _atomic_move_beneath_home(
                home,
                destination,
                source,
                expected_destination_parent_identity=source_parent_identity,
                expected_entry_identity=expected_identity,
            )
            _clear_release_retention_transaction(home, transaction)
            reasons = ", ".join(sorted(references_after_move[(owner, sha)]))
            raise SyncError(
                f"release became referenced during retention: {owner}@{sha} ({reasons})"
            )
        _publish_release_retention_commit_marker(home, transaction)
        transaction = _load_release_retention_transaction(home)
        if transaction is None or not transaction.committed:
            raise SyncError("release retention commit marker was not durable")
        references_before_delete = _retained_release_references(
            home,
            exclude_retention=(owner, sha),
        )
        if (owner, sha) in references_before_delete:
            quarantined = _quarantined_release_path(home, transaction)
            if quarantined is None:
                raise SyncError(
                    "release became referenced after retention commit and "
                    "the quarantine disappeared"
                )
            _abort_committed_release_retention(
                home,
                transaction,
                quarantined,
            )
            reasons = ", ".join(sorted(references_before_delete[(owner, sha)]))
            raise SyncError(
                f"release became referenced before deletion: {owner}@{sha} ({reasons})"
            )
        _publish_release_retention_delete_started_marker(
            home,
            transaction,
        )
        transaction = _load_release_retention_transaction(home)
        if transaction is None or not transaction.deletion_started:
            raise SyncError("release retention deletion-start marker was not durable")
        references_at_delete = _retained_release_references(
            home,
            exclude_retention=(owner, sha),
        )
        if (owner, sha) in references_at_delete:
            quarantined = _quarantined_release_path(home, transaction)
            if quarantined is None:
                raise SyncError(
                    "release became referenced at the deletion boundary and "
                    "the quarantine disappeared"
                )
            _abort_committed_release_retention(
                home,
                transaction,
                quarantined,
            )
            reasons = ", ".join(sorted(references_at_delete[(owner, sha)]))
            raise SyncError(
                f"release became referenced at deletion: {owner}@{sha} ({reasons})"
            )
        _delete_quarantined_release(
            home,
            destination,
            expected_identity,
            quarantine_parent_identity,
        )
        _publish_release_retention_delete_complete_marker(
            home,
            transaction,
        )
        transaction = _load_release_retention_transaction(home)
        if transaction is None or not transaction.deletion_complete:
            raise SyncError("release retention deletion marker was not durable")
        _clear_release_retention_transaction(home, transaction)
    except BaseException:
        if not pointer_published:
            try:
                pointer_parent_fd = _open_directory_beneath(home, home)
                try:
                    published_snapshot = _read_managed_state_file_snapshot(
                        home,
                        _release_retention_pointer_path(home),
                        pointer_parent_fd,
                    )
                finally:
                    _close_fd_quietly(pointer_parent_fd)
                if published_snapshot.exists:
                    pointer_published = True
            except (OSError, SyncError):
                pointer_published = True
        if not pointer_published:
            try:
                record_path = batch_root / RELEASE_RETENTION_RECORD_NAME
                if (
                    record_snapshot is not None
                    and record_snapshot.file_identity is not None
                    and _path_exists_or_is_link(record_path)
                ):
                    _delete_retention_file(
                        home,
                        record_path,
                        record_snapshot,
                        label="unpublished release retention record",
                    )
                release_parent = batch_root / "release"
                if _path_exists_or_is_link(release_parent):
                    os.rmdir(release_parent)
                os.rmdir(batch_root)
            except (OSError, SyncError):
                pass
        raise
    finally:
        _close_fd_quietly(batch_fd)


def prune_releases(
    home: Path,
    owners: list[str] | None = None,
    *,
    dry_run: bool,
) -> list[tuple[str, str]]:
    home = home.expanduser()
    selected_owners = (
        sorted({_validate_owner(owner) for owner in owners}) if owners else None
    )
    removed: list[tuple[str, str]] = []
    if dry_run and not _path_exists_or_is_link(_personal_sync_root(home)):
        print(f"no installed personal sync releases under {_display_path(home)}")
        return removed
    with installation_lock(home, create=not dry_run):
        recovered_retention = _recover_release_retention_transaction(
            home,
            dry_run=dry_run,
        )
        if recovered_retention is not None and dry_run:
            return removed
        if recovered_retention is not None and recovered_retention.deleted:
            removed.append((recovered_retention.owner, recovered_retention.sha))
            print(
                "pruned release while recovering durable quarantine: "
                f"{recovered_retention.owner}@{recovered_retention.sha}"
            )
        references = _retained_release_references(home)
        owner_names = selected_owners or sorted(_known_owners(home))
        candidates: list[tuple[str, str, tuple[int, int]]] = []
        for owner in owner_names:
            releases_root = _releases_root(home, owner)
            if not _ensure_safe_internal_directory(
                home,
                releases_root,
                create=False,
                allow_missing=True,
            ):
                continue
            for release_path in _valid_release_dirs(home, owner):
                key = (owner, release_path.name)
                if key in references:
                    continue
                _identity, directory_identity = (
                    _installed_release_identity_and_directory_identity(
                        home,
                        owner,
                        release_path.name,
                    )
                )
                candidates.append(
                    (
                        owner,
                        release_path.name,
                        directory_identity,
                    )
                )
                if len(candidates) > MAX_RELEASE_RETENTION_CANDIDATES:
                    raise SyncError(
                        "release retention candidate count exceeds the limit"
                    )

        for owner, sha, directory_identity in candidates:
            if dry_run:
                print(
                    f"would quarantine and delete unreferenced release: {owner}@{sha}"
                )
                removed.append((owner, sha))
                continue
            _prune_release_candidate(
                home,
                owner,
                sha,
                directory_identity,
            )
            removed.append((owner, sha))
            print(f"pruned release after quarantine: {owner}@{sha}")
    if not removed:
        print("no unreferenced releases to prune")
    return removed


def _entries_by_target(entries: list[LinkEntry]) -> dict[PurePosixPath, LinkEntry]:
    return {entry.target: entry for entry in entries}


def _overlay_scan_parents(
    home: Path,
    owner: str,
    overlay_entries: list[LinkEntry],
    public_entries: list[LinkEntry],
) -> set[Path]:
    parents = _known_manifest_target_parents(home, overlay_entries, owner=owner)
    parents.update(
        _known_manifest_target_parents(home, public_entries, owner=PUBLIC_OWNER)
    )
    return parents


def _collect_overlay_issues(
    home: Path,
    owner: str,
    *,
    pending_batch: PendingLinkBatch | None = None,
) -> list[str]:
    owner = _validate_owner(owner)
    if owner == PUBLIC_OWNER:
        raise SyncError("overlay owner must not be public")
    overlay_entries = current_release_entries(home, owner)
    public_entries = current_release_entries(home, PUBLIC_OWNER)
    if not overlay_entries:
        return [f"overlay {owner} is not installed"]

    public_by_target = _entries_by_target(public_entries)
    overlay_by_target = _entries_by_target(overlay_entries)
    overlay_targets = {_entry_target_path(home, entry) for entry in overlay_entries}
    issues: list[str] = []

    known_owners = {owner, PUBLIC_OWNER}
    for entry in overlay_entries:
        target = _entry_target_path(home, entry)
        if _entry_materializes_regular_file(entry):
            try:
                snapshot = _capture_reconcile_target_snapshot(
                    home,
                    target,
                    require_managed_parent_access=True,
                )
            except (OSError, SyncError) as error:
                issues.append(
                    f"overlay regular-file validation failed: {target}: {error}"
                )
            else:
                regular = _regular_snapshot_from_reconcile(snapshot)
                if snapshot.link_identity is None:
                    issues.append(f"missing overlay regular file: {target}")
                elif regular is None:
                    issues.append(f"overlay regular-file type mismatch: {target}")
                else:
                    try:
                        _verify_pending_regular_aliases(
                            home,
                            pending_batch,
                            target,
                            regular,
                        )
                    except SyncError as error:
                        issues.append(
                            "overlay regular-file alias validation failed: "
                            f"{target}: {error}"
                        )
                    else:
                        if regular.mode != 0o600 or regular.uid != os.geteuid():
                            issues.append(
                                f"overlay regular-file access policy mismatch: {target}"
                            )
                        else:
                            try:
                                source = _entry_regular_source_path(home, entry)
                                expected_sha256 = _regular_source_sha256(home, source)
                            except (OSError, SyncError) as error:
                                issues.append(
                                    "overlay regular-file source validation failed: "
                                    f"{target}: {error}"
                                )
                            else:
                                if regular.sha256 != expected_sha256:
                                    issues.append(
                                        "overlay regular-file content mismatch: "
                                        f"{target}"
                                    )
            public_entry = public_by_target.get(entry.target)
            if (
                public_entry is not None
                and not entry.override
                and entry.target not in OPTIONAL_PUBLIC_TARGETS
            ):
                issues.append(
                    "target also exists in public manifest but lacks "
                    f"override=true: {target}"
                )
            if (
                public_entry is None
                and entry.override
                and entry.target not in OPTIONAL_PUBLIC_TARGETS
            ):
                issues.append(f"override target has no public base target: {target}")
            continue
        live_target = _read_optional_symlink_target_beneath(home, target)
        if live_target is None:
            issues.append(f"missing overlay symlink: {target}")
            continue
        live_owner = _link_managed_owner(home, target, known_owners)
        if live_owner != owner:
            issues.append(f"overlay target is not owned by {owner}: {target}")
        if live_target != _desired_link_target(home, entry):
            issues.append(f"overlay target drift: {target}")
        public_entry = public_by_target.get(entry.target)
        if (
            public_entry is not None
            and not entry.override
            and entry.target not in OPTIONAL_PUBLIC_TARGETS
        ):
            issues.append(
                f"target also exists in public manifest but lacks override=true: {target}"
            )
        if (
            public_entry is None
            and entry.override
            and entry.target not in OPTIONAL_PUBLIC_TARGETS
        ):
            issues.append(f"override target has no public base target: {target}")

    for public_entry in public_entries:
        target = _entry_target_path(home, public_entry)
        if _read_optional_symlink_target_beneath(home, target) is None:
            continue
        live_owner = _link_managed_owner(home, target, known_owners)
        if live_owner != owner:
            continue
        overlay_entry = overlay_by_target.get(public_entry.target)
        if public_entry.target not in OPTIONAL_PUBLIC_TARGETS and (
            overlay_entry is None or not overlay_entry.override
        ):
            issues.append(f"public target is shadowed by undeclared overlay: {target}")

    for parent in sorted(
        _overlay_scan_parents(home, owner, overlay_entries, public_entries)
    ):
        if not parent.is_dir():
            continue
        for candidate in parent.iterdir():
            if candidate in overlay_targets:
                continue
            if _read_optional_symlink_target_beneath(home, candidate) is None:
                continue
            if _link_managed_owner(home, candidate, known_owners) == owner:
                issues.append(
                    f"private-owned symlink is not in overlay manifest: {candidate}"
                )

    return issues


def verify_overlay(home: Path, owner: str) -> None:
    home = home.expanduser()
    issues = _collect_overlay_issues(home, owner)
    state_path = _state_path(home)
    current_sha = _current_sha(home, owner)
    overlay_entries = current_release_entries(home, owner)
    state: ManagedState | None = None
    if _path_exists_or_is_link(state_path):
        state = _load_managed_state(home)
        if state.owners.get(owner) != current_sha:
            issues.append(
                f"managed link state release mismatch for {owner}: "
                f"state={state.owners.get(owner)}, current={current_sha}"
            )
    for entry in overlay_entries:
        record = state.links.get(entry.target) if state is not None else None
        if state is None and (
            not _entry_materializes_regular_file(entry)
            or _is_optional_desired_entry(entry)
        ):
            continue
        if current_sha is None:
            continue
        expected_record = ManagedLinkRecord(
            source=entry.source,
            target=entry.target,
            kind=entry.kind,
            owner=owner,
            link_target=_desired_link_target(home, entry),
            release_sha=current_sha,
        )
        if record is None:
            if _entry_materializes_regular_file(
                entry
            ) and not _is_optional_desired_entry(entry):
                issues.append(
                    f"managed link state has a missing overlay regular claim: "
                    f"{_entry_target_path(home, entry)}"
                )
        elif record != expected_record:
            issues.append(
                f"managed link state has a conflicting overlay target: "
                f"{_entry_target_path(home, entry)}"
            )
    if issues:
        for issue in issues:
            print(f"overlay issue: {issue}")
        raise SyncError(f"overlay verification failed with {len(issues)} issue(s)")
    print(f"overlay verification ok: {owner}")


def uninstall_overlay(home: Path, owner: str, *, dry_run: bool) -> None:
    home = home.expanduser()
    owner = _validate_owner(owner)
    if owner == PUBLIC_OWNER:
        raise SyncError("refusing to uninstall public as an overlay")
    cleanup_budget = PendingCleanupActionBudget(MAX_PENDING_CLEANUP_BATCHES_PER_RUN)

    def apply_uninstall() -> None:
        _require_no_pending_unresolved_ticket_representations(home)
        if dry_run and _pending_cleanup_ready_batch_is_observed(home):
            print(
                "would clean a finalized or interrupted pending transaction under "
                "the install lock"
            )
            return
        loaded_state, initial_state_snapshot = _load_managed_state_with_snapshot(home)
        (
            loaded_state,
            initial_state_snapshot,
            recovered_pending_transaction,
        ) = _recover_pending_link_transaction(
            home,
            loaded_state,
            initial_state_snapshot,
            dry_run=dry_run,
        )
        if recovered_pending_transaction and dry_run:
            print(
                "would recover pending personal sync transaction under the install lock"
            )
            return
        if not dry_run:
            _cleanup_ready_pending_batches(home, budget=cleanup_budget)
            _require_no_pending_terminal_mutation_authority(home)
        _verify_managed_state_current_owner_claims(home, loaded_state)
        # Uncommitted recovery returns the exact restored before-state snapshot.
        # If that state was absent, plan this uninstall like a clean legacy retry
        # so the restored links are claimed before their owner is retired.
        bootstrap_history = not initial_state_snapshot.exists
        state = _refresh_managed_state_from_current(
            home,
            loaded_state,
            bootstrap_history=bootstrap_history,
        )
        baseline_link_snapshots = _capture_managed_state_link_snapshots(home, state)
        current_manifests = _installed_manifests(home)
        active_expectations = _capture_active_release_expectations(
            home,
            current_manifests,
        )
        outgoing_sha = state.owners.get(owner)
        outgoing_manifest = current_manifests.get(owner)
        if outgoing_manifest is None:
            if outgoing_sha is not None:
                outgoing_manifest = _load_installed_manifest_data(
                    home,
                    owner,
                    outgoing_sha,
                )
                if outgoing_manifest.owner != owner:
                    raise SyncError(
                        f"managed link state release owner mismatch: expected {owner}, "
                        f"got {outgoing_manifest.owner}"
                    )
                current_manifests[owner] = outgoing_manifest
        if outgoing_manifest is None:
            print(f"overlay {owner} is not installed")
            return
        if outgoing_sha is None:
            raise SyncError(f"managed link state release is missing for owner {owner}")
        next_manifests = {
            current_owner: manifest
            for current_owner, manifest in current_manifests.items()
            if current_owner != owner
        }
        public_manifest = next_manifests.get(PUBLIC_OWNER)
        if public_manifest is None:
            raise SyncError("overlay uninstall requires an installed public base")
        overlay_manifests = [
            manifest
            for current_owner, manifest in sorted(next_manifests.items())
            if current_owner != PUBLIC_OWNER
        ]
        desired_entries = _combine_entries(public_manifest.entries, overlay_manifests)
        _validate_active_replacements(
            home,
            current_manifests,
            next_manifests,
            desired_entries,
        )
        previous_entries = [
            entry
            for manifest in current_manifests.values()
            for entry in manifest.entries
        ]
        historical_removed_links = _combine_removed_links(
            list(current_manifests.values())
        )
        active_removed_links = _combine_removed_links(list(next_manifests.values()))
        actions = _plan_reconciliation(
            home,
            desired_entries,
            previous_entries,
            historical_removed_links,
            state,
            allow_cross_owner=True,
            allow_unledgered_removed_links=bootstrap_history,
        )
        _verify_managed_state_link_claims(home, state, actions)
        link_actions = [
            action
            for action in actions
            if action.action != PENDING_RELINQUISH_FOREIGN_ACTION
        ]
        required_replacements = _required_replacements_for_removals(
            home,
            link_actions,
            active_removed_links,
            desired_entries,
        )
        managed_targets = _managed_targets_after_reconciliation(home, state, actions)
        current = _current_link(home, owner)
        if dry_run:
            for action in actions:
                if action.action == PENDING_RELINQUISH_FOREIGN_ACTION:
                    print(f"would relinquish foreign managed claim {action.target}")
            _apply_reconcile_actions(
                home,
                link_actions,
                dry_run=True,
                required_replacements=required_replacements,
            )
            if _path_exists_or_is_link(current):
                print(f"would remove overlay current pointer {current}")
            else:
                print(f"overlay current pointer is already absent: {current}")
            if not actions:
                print(f"no overlay-managed symlinks found for {owner}")
            return

        initial_state_snapshot = _bind_managed_state_parent_for_pending_staging(
            home,
            initial_state_snapshot,
            loaded_state,
        )
        _ensure_current_can_switch(home, owner)
        current_snapshot = _capture_reconcile_target_snapshot(home, current)
        current_actions: list[ReconcileAction] = []
        if current_snapshot.link_identity is not None:
            previous_current = current_snapshot.link_target
            expected_current = f"releases/{outgoing_sha}"
            if previous_current != expected_current:
                raise SyncError(
                    f"current release mismatch for owner {owner}: "
                    f"expected {expected_current}, got {previous_current}"
                )
            current_actions.append(
                ReconcileAction(
                    "remove",
                    current,
                    "",
                    "directory",
                    expected_link_target=previous_current,
                    planned_snapshot=current_snapshot,
                )
            )
        outgoing_release = active_expectations.get(owner)
        if outgoing_release is None:
            outgoing_expectation = _installed_release_identity_and_directory_identity(
                home,
                owner,
                outgoing_sha,
            )
            if outgoing_expectation[0][1] != outgoing_manifest:
                raise SyncError(
                    f"managed link state release manifest mismatch for owner {owner}"
                )
            outgoing_release = ActiveReleaseExpectation(
                owner=owner,
                sha=outgoing_sha,
                manifest=outgoing_manifest,
                expectation=outgoing_expectation,
            )
            active_expectations[owner] = outgoing_release
        elif (
            outgoing_release.sha != outgoing_sha
            or outgoing_release.manifest != outgoing_manifest
        ):
            raise SyncError(f"outgoing release identity mismatch for owner {owner}")
        missing_remaining = set(next_manifests).difference(active_expectations)
        if missing_remaining:
            raise SyncError(
                "remaining active release identity is missing for owner(s): "
                + ", ".join(sorted(missing_remaining))
            )
        active_bindings = _open_active_release_bindings(
            home,
            active_expectations,
        )
        remaining_bindings = {
            current_owner: active_bindings[current_owner]
            for current_owner in next_manifests
        }
        outgoing_binding = active_bindings[owner]
        held_bindings = list(active_bindings.values())
        pending_batch: PendingLinkBatch | None = None
        link_transaction: ReconcileTransaction | None = None
        current_transaction: ReconcileTransaction | None = None
        state_transaction: ManagedStateFileTransaction | None = None
        state_committed = False
        try:
            expected_owner_shas = {
                current_owner: active_expectations[current_owner].sha
                for current_owner in next_manifests
            }
            planned_next_state = _planned_committed_state(
                home,
                desired_entries,
                expected_owner_shas,
                managed_targets,
            )
            pending_batch = _stage_pending_link_batch(
                home,
                [("managed", actions), ("current", current_actions)],
                desired_entries,
                expected_owner_shas,
                initial_state_snapshot,
                state,
                planned_next_state,
                required_replacements_by_scope={
                    "managed": required_replacements,
                },
            )
            _publish_pending_link_pointer(home, pending_batch)
            _verify_install_release_identities(
                home,
                list(remaining_bindings.values()),
                phase="before overlay uninstall",
                verify_current=True,
            )
            _verify_install_release_identities(
                home,
                [outgoing_binding],
                phase="before overlay uninstall",
                verify_current=bool(current_actions),
            )
            if not current_actions and (
                _capture_reconcile_target_snapshot(home, current) != current_snapshot
            ):
                raise SyncError(
                    f"missing current pointer changed before overlay uninstall: {current}"
                )
            link_transaction = ReconcileTransaction(
                batch_root=pending_batch.batch_root,
                mutations=[],
            )
            _apply_reconcile_actions(
                home,
                link_actions,
                dry_run=False,
                required_replacements=required_replacements,
                pending_batch=pending_batch,
                pending_scope="managed",
                batch_root=pending_batch.batch_root,
                transaction=link_transaction,
            )
            current_transaction = ReconcileTransaction(
                batch_root=pending_batch.batch_root,
                mutations=[],
            )
            _apply_reconcile_actions(
                home,
                current_actions,
                dry_run=False,
                pending_batch=pending_batch,
                pending_scope="current",
                batch_root=pending_batch.batch_root,
                transaction=current_transaction,
            )
            if current_actions:
                print(f"removed overlay current pointer {current}")
            _verify_install_release_identities(
                home,
                list(remaining_bindings.values()),
                phase="during overlay uninstall",
                verify_current=True,
            )
            _verify_install_release_identities(
                home,
                [outgoing_binding],
                phase="during overlay uninstall",
                verify_current=False,
            )
            if not current_actions and (
                _capture_reconcile_target_snapshot(home, current) != current_snapshot
            ):
                raise SyncError(
                    f"missing current pointer changed during overlay uninstall: {current}"
                )
            _verify_desired_entries(
                home,
                desired_entries,
                pending_batch=pending_batch,
            )
            for manifest in overlay_manifests:
                issues = _collect_overlay_issues(
                    home,
                    manifest.owner,
                    pending_batch=pending_batch,
                )
                if issues:
                    for issue in issues:
                        print(f"overlay issue: {issue}")
                    raise SyncError(
                        f"overlay verification failed with {len(issues)} issue(s)"
                    )

            owner_shas = _owner_shas_from_bound_current_releases(
                home,
                next_manifests,
                expected_owner_shas,
                remaining_bindings,
                phase="before overlay uninstall state publication",
            )
            next_state = _committed_state(
                home,
                desired_entries,
                owner_shas,
                managed_targets,
                pending_batch=pending_batch,
            )
            if next_state != planned_next_state:
                raise SyncError(
                    "observed uninstall state differs from the pending plan"
                )
            managed_link_snapshots = _trusted_managed_link_snapshots_for_state(
                home,
                next_state,
                baseline_link_snapshots,
                link_transaction,
            )
            _verify_install_release_bindings_lightweight(
                home,
                list(remaining_bindings.values()),
                phase="during final overlay uninstall state validation",
                verify_current=True,
            )
            _verify_install_release_bindings_lightweight(
                home,
                [outgoing_binding],
                phase="during final overlay uninstall state validation",
                verify_current=False,
            )
            _verify_desired_entries(
                home,
                desired_entries,
                pending_batch=pending_batch,
            )
            _verify_managed_link_snapshots(
                home,
                next_state,
                managed_link_snapshots,
            )
            state_transaction = _prepare_pending_managed_state_transaction(
                home,
                pending_batch,
                next_state,
            )
            _verify_install_release_identities(
                home,
                list(remaining_bindings.values()),
                phase="during final overlay uninstall state validation",
                verify_current=True,
            )
            _verify_install_release_identities(
                home,
                [outgoing_binding],
                phase="during final overlay uninstall state validation",
                verify_current=False,
            )
            _verify_desired_entries(
                home,
                desired_entries,
                pending_batch=pending_batch,
            )
            _verify_managed_link_snapshots(
                home,
                next_state,
                managed_link_snapshots,
            )
            _write_managed_state(home, next_state, state_transaction)
            _verify_published_state_transaction(home, state_transaction)
            _verify_install_release_identities(
                home,
                list(remaining_bindings.values()),
                phase="after overlay uninstall managed-state publication",
                verify_current=True,
            )
            _verify_install_release_identities(
                home,
                [outgoing_binding],
                phase="after overlay uninstall managed-state publication",
                verify_current=False,
            )
            _verify_desired_entries(
                home,
                desired_entries,
                pending_batch=pending_batch,
            )
            _verify_managed_link_snapshots(
                home,
                next_state,
                managed_link_snapshots,
            )
            _verify_committed_pending_link_records(home, pending_batch)
            _verify_published_state_transaction(home, state_transaction)
            _verify_install_release_identities(
                home,
                list(remaining_bindings.values()),
                phase="before overlay uninstall commit",
                verify_current=True,
            )
            _verify_install_release_identities(
                home,
                [outgoing_binding],
                phase="before overlay uninstall commit",
                verify_current=False,
            )
            if not current_actions and (
                _capture_reconcile_target_snapshot(home, current) != current_snapshot
            ):
                raise SyncError(
                    f"missing current pointer changed before overlay uninstall commit: "
                    f"{current}"
                )
            _publish_pending_commit_marker(home, pending_batch)
            state_committed = True
            _mark_pending_batch_cleanup_ready(home, pending_batch)
            _clear_pending_link_pointer(home, pending_batch, phase="after")
        except BaseException as error:
            if (
                not state_committed
                and pending_batch is not None
                and pending_batch.pointer_snapshot is not None
            ):
                try:
                    state_committed = _pending_commit_decision(home, pending_batch)
                except (OSError, SyncError) as marker_error:
                    _close_install_release_bindings(held_bindings)
                    raise SyncError(
                        "overlay uninstall failed with an ambiguous commit marker; "
                        "the pending transaction was retained: "
                        f"{marker_error}"
                    ) from error
            if state_committed:
                _close_install_release_bindings(held_bindings)
                raise SyncError(
                    "overlay uninstall committed managed state but finalization "
                    "failed; the pending transaction was retained for exact recovery"
                ) from error
            rollback_errors: list[str] = []
            try:
                _restore_managed_state_file(home, state_transaction)
            except (OSError, SyncError) as rollback_error:
                rollback_errors.append(f"state: {rollback_error}")
            try:
                _rollback_reconcile_transaction(home, current_transaction)
            except (OSError, SyncError) as rollback_error:
                rollback_errors.append(f"current: {rollback_error}")
            try:
                _rollback_reconcile_transaction(
                    home,
                    link_transaction,
                    pending_batch=pending_batch,
                )
            except (OSError, SyncError) as rollback_error:
                rollback_errors.append(f"links: {rollback_error}")
            try:
                _verify_install_release_identities(
                    home,
                    list(remaining_bindings.values()),
                    phase="during overlay uninstall rollback",
                    verify_current=True,
                )
                _verify_install_release_identities(
                    home,
                    [outgoing_binding],
                    phase="during overlay uninstall rollback",
                    verify_current=bool(current_actions),
                )
                if not current_actions and (
                    _capture_reconcile_target_snapshot(home, current)
                    != current_snapshot
                ):
                    raise SyncError(
                        "missing current pointer changed during overlay uninstall "
                        f"rollback: {current}"
                    )
            except (OSError, SyncError) as rollback_error:
                rollback_errors.append(f"releases: {rollback_error}")
            if (
                pending_batch is not None
                and pending_batch.pointer_snapshot is not None
                and not rollback_errors
            ):
                try:
                    _finalize_rolled_back_pending_batch(home, pending_batch)
                except (OSError, SyncError) as rollback_error:
                    rollback_errors.append(
                        f"pending rollback finalization: {rollback_error}"
                    )
            if rollback_errors:
                _close_install_release_bindings(held_bindings)
                raise SyncError(
                    f"overlay uninstall failed: {error}; rollback was incomplete: "
                    + "; ".join(rollback_errors)
                ) from error
            _close_install_release_bindings(held_bindings)
            raise
        try:
            _commit_managed_state_transaction(state_transaction)
            _commit_reconcile_transaction(current_transaction)
            _commit_reconcile_transaction(link_transaction)
            assert pending_batch is not None
            cleaned = _try_cleanup_finalized_pending_batch(home, pending_batch)
            if pending_batch.terminal_regular_after:
                if not cleaned:
                    raise SyncError(
                        "committed regular-file evidence cleanup was deferred"
                    )
        finally:
            _close_install_release_bindings(held_bindings)
        if not actions:
            print(f"no overlay-managed symlinks found for {owner}")

    if dry_run:
        if _recover_release_retention_transaction(home, dry_run=True):
            return
        apply_uninstall()
        return

    with installation_lock(home):
        _recover_release_retention_transaction(home, dry_run=False)
        apply_uninstall()


def _codex_user_home(home: Path) -> Path:
    home = home.expanduser()
    user_home = Path.home().expanduser()
    expected = user_home / ".codex"
    if home != expected:
        raise SyncError(
            f"scheduler --home must point at current user's ~/.codex: {home} "
            f"(expected {expected})"
        )
    return user_home


def _scheduler_runner(home: Path, runner: str | None) -> Path:
    if runner:
        return Path(runner).expanduser()
    return home.expanduser() / "bin" / "codex-personal-sync"


def _scheduler_runner_is_usable(runner: Path) -> bool:
    if not runner.is_absolute():
        return False
    try:
        lexical = runner.lstat()
        link_target = os.readlink(runner) if stat.S_ISLNK(lexical.st_mode) else None
        target = runner.stat()
        lexical_after = runner.lstat()
        link_target_after = (
            os.readlink(runner) if stat.S_ISLNK(lexical_after.st_mode) else None
        )
        target_after = runner.stat()
    except OSError:
        return False
    if (
        _managed_state_metadata_snapshot(lexical)
        != _managed_state_metadata_snapshot(lexical_after)
        or not _regular_stat_metadata_matches(target_after, target)
        or link_target != link_target_after
        or stat.S_ISDIR(lexical.st_mode)
        or not stat.S_ISREG(target.st_mode)
    ):
        return False
    if not os.access(runner, os.X_OK):
        return False
    try:
        resolved = runner.resolve(strict=True)
        _read_scheduler_regular_file(
            resolved,
            MAX_SCHEDULER_RUNNER_BYTES,
        )
    except (OSError, RuntimeError, SyncError):
        return False
    return True


def _validate_scheduler_runner(runner: Path, *, dry_run: bool) -> None:
    if not runner.is_absolute():
        raise SyncError(f"scheduler runner must be an absolute path: {runner}")
    if dry_run:
        return
    try:
        runner.lstat()
    except FileNotFoundError:
        raise SyncError(
            f"scheduler runner is missing: {runner}; run install first or pass --runner"
        )
    except OSError as error:
        raise SyncError(f"failed to inspect scheduler runner: {runner}") from error
    if not _scheduler_runner_is_usable(runner):
        raise SyncError(
            f"scheduler runner must resolve to a regular executable: {runner}; "
            "run install first or pass --runner"
        )


def _scheduler_platform(raw_platform: str) -> str:
    if raw_platform != "auto":
        return raw_platform
    if sys.platform == "darwin":
        return "macos"
    if sys.platform.startswith("linux"):
        return "linux"
    raise SyncError(f"unsupported scheduler platform: {sys.platform}")


def _scheduler_paths(platform_name: str, home: Path) -> SchedulerPaths:
    user_home = _codex_user_home(home)
    if platform_name == "macos":
        return SchedulerPaths(
            platform="macos",
            launchd_plist=user_home
            / "Library"
            / "LaunchAgents"
            / f"{LAUNCHD_LABEL}.plist",
        )
    if platform_name == "linux":
        systemd_root = user_home / ".config" / "systemd" / "user"
        return SchedulerPaths(
            platform="linux",
            systemd_service=systemd_root / f"{SYSTEMD_UNIT}.service",
            systemd_timer=systemd_root / f"{SYSTEMD_UNIT}.timer",
        )
    raise SyncError(f"unsupported scheduler platform: {platform_name}")


def _scheduler_config_parent(paths: SchedulerPaths) -> Path:
    if paths.platform == "macos":
        assert paths.launchd_plist is not None
        return paths.launchd_plist.parent
    if paths.platform == "linux":
        assert paths.systemd_service is not None
        assert paths.systemd_timer is not None
        if paths.systemd_service.parent != paths.systemd_timer.parent:
            raise SyncError("systemd scheduler config parents disagree")
        return paths.systemd_service.parent
    raise SyncError(f"unsupported scheduler platform: {paths.platform}")


def _scheduler_config_parent_is_missing(paths: SchedulerPaths) -> bool:
    parent = _scheduler_config_parent(paths)
    user_home = Path.home().expanduser()
    parts = _directory_parts_beneath(user_home, parent)
    directory_fds: list[int] = []

    def revalidate_open_chain() -> None:
        if not directory_fds or not _sync_home_matches_fd(
            user_home,
            directory_fds[0],
        ):
            raise SyncError(f"scheduler user home identity is uncertain: {user_home}")
        for index, part in enumerate(parts[: len(directory_fds) - 1]):
            child_fd = directory_fds[index + 1]
            try:
                child_identity = _directory_identity(child_fd)
            except (OSError, SyncError) as error:
                raise SyncError(
                    f"scheduler config parent component is unreadable: {parent}"
                ) from error
            try:
                named = os.stat(
                    part,
                    dir_fd=directory_fds[index],
                    follow_symlinks=False,
                )
            except FileNotFoundError as error:
                raise SyncError(
                    "scheduler config parent component disappeared during "
                    f"validation: {parent}"
                ) from error
            except OSError as error:
                raise SyncError(
                    f"scheduler config parent component is unreadable: {parent}"
                ) from error
            if (
                not stat.S_ISDIR(named.st_mode)
                or (named.st_dev, named.st_ino) != child_identity
            ):
                raise SyncError(
                    f"scheduler config parent component identity changed: {parent}"
                )
        if not _sync_home_matches_fd(user_home, directory_fds[0]):
            raise SyncError(f"scheduler user home identity changed: {user_home}")

    try:
        try:
            directory_fds.append(_open_sync_home(user_home))
        except FileNotFoundError as error:
            raise SyncError(f"scheduler user home is missing: {user_home}") from error
        except (OSError, SyncError) as error:
            raise SyncError(
                f"scheduler user home is unreadable: {user_home}"
            ) from error

        child_flags = _directory_open_flags(nofollow=True)
        for part in parts:
            current_fd = directory_fds[-1]
            try:
                child_fd = os.open(
                    part,
                    child_flags,
                    dir_fd=current_fd,
                )
            except FileNotFoundError:
                revalidate_open_chain()
                try:
                    os.stat(
                        part,
                        dir_fd=current_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    revalidate_open_chain()
                    return True
                except OSError as error:
                    raise SyncError(
                        "scheduler config parent component absence is "
                        f"unreadable: {parent}"
                    ) from error
                raise SyncError(
                    "scheduler config parent component appeared after "
                    f"a missing observation: {parent}"
                )
            except OSError as error:
                try:
                    metadata = os.stat(
                        part,
                        dir_fd=current_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError as stat_error:
                    raise SyncError(
                        "scheduler config parent component identity is "
                        f"uncertain: {parent}"
                    ) from stat_error
                except OSError as stat_error:
                    raise SyncError(
                        f"scheduler config parent component is unreadable: {parent}"
                    ) from stat_error
                if stat.S_ISLNK(metadata.st_mode):
                    reason = "is a symlink"
                elif not stat.S_ISDIR(metadata.st_mode):
                    reason = "is not a directory"
                else:
                    reason = "could not be opened safely"
                raise SyncError(
                    f"scheduler config parent component {reason}: {parent}"
                ) from error
            directory_fds.append(child_fd)
            revalidate_open_chain()
        revalidate_open_chain()
        return False
    finally:
        for directory_fd in reversed(directory_fds):
            _close_fd_quietly(directory_fd)


def _read_scheduler_regular_file(path: Path, maximum_bytes: int) -> bytes:
    parent_fd = -1
    file_fd = -1
    try:
        parent_fd = os.open(
            path.parent,
            _directory_open_flags(nofollow=True),
        )
        if not _archive_path_matches_fd(path.parent, parent_fd):
            raise SyncError(
                f"scheduler config parent changed before read: {path.parent}"
            )
        named = os.stat(
            path.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError:
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)
        raise
    except OSError as error:
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)
        raise SyncError(
            f"failed to inspect scheduler config {path}: {error}"
        ) from error
    except BaseException:
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)
        raise
    if not stat.S_ISREG(named.st_mode):
        _close_fd_quietly(parent_fd)
        raise SyncError(f"refusing non-file scheduler config: {path}")
    if named.st_uid != os.geteuid() or stat.S_IMODE(named.st_mode) & 0o022:
        _close_fd_quietly(parent_fd)
        raise SyncError(
            f"scheduler config must be user-owned and not group/world writable: {path}"
        )
    if named.st_size > maximum_bytes:
        _close_fd_quietly(parent_fd)
        raise SyncError(f"scheduler config exceeds {maximum_bytes} bytes: {path}")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    try:
        file_fd = os.open(path.name, flags, dir_fd=parent_fd)
        opened = os.fstat(file_fd)
        if (
            not stat.S_ISREG(opened.st_mode)
            or not _regular_stat_metadata_matches(opened, named)
            or not _archive_path_matches_fd(path.parent, parent_fd)
        ):
            raise SyncError(f"scheduler config changed before read: {path}")
        payload = bytearray()
        while len(payload) <= maximum_bytes:
            chunk = os.read(file_fd, min(64 * 1024, maximum_bytes + 1 - len(payload)))
            if not chunk:
                break
            payload.extend(chunk)
        if len(payload) > maximum_bytes:
            raise SyncError(f"scheduler config exceeds {maximum_bytes} bytes: {path}")
        try:
            os.lseek(file_fd, 0, os.SEEK_SET)
        except OSError as error:
            raise SyncError(
                f"failed to revalidate scheduler config {path}: {error}"
            ) from error
        confirmed_payload = bytearray()
        while len(confirmed_payload) <= maximum_bytes:
            chunk = os.read(
                file_fd,
                min(
                    64 * 1024,
                    maximum_bytes + 1 - len(confirmed_payload),
                ),
            )
            if not chunk:
                break
            confirmed_payload.extend(chunk)
        if len(confirmed_payload) > maximum_bytes:
            raise SyncError(f"scheduler config exceeds {maximum_bytes} bytes: {path}")
        if confirmed_payload != payload:
            raise SyncError(f"scheduler config content changed during read: {path}")
        after = os.fstat(file_fd)
        current = os.stat(
            path.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            not _regular_stat_metadata_matches(after, named)
            or not _regular_stat_metadata_matches(current, named)
            or not _archive_path_matches_fd(path.parent, parent_fd)
        ):
            raise SyncError(f"scheduler config changed during read: {path}")
        return bytes(payload)
    except OSError as error:
        raise SyncError(f"failed to read scheduler config {path}: {error}") from error
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)


def _parse_scheduler_program_arguments(
    arguments: object,
    *,
    platform_name: str,
    config_paths: tuple[Path, ...],
    interval_minutes: int,
) -> SchedulerConfig:
    if (
        not isinstance(arguments, list)
        or len(arguments) < 2
        or not all(isinstance(argument, str) and argument for argument in arguments)
    ):
        raise SyncError("scheduler program arguments are invalid")
    runner = Path(arguments[0]).expanduser()
    command = arguments[1]
    flags = arguments[2:]
    if len(flags) % 2:
        raise SyncError("scheduler program arguments must use option/value pairs")
    command_flag_contracts = {
        "install": (
            ("--repo", "--home"),
            ("--repo", "--home"),
        ),
        "install-private": (
            ("--repo", "--base-repo", "--owner", "--home"),
            ("--repo", "--base-repo", "--owner", "--home"),
        ),
        "run-scheduled": (
            ("--mode", "--repo", "--base-repo", "--owner", "--home"),
            ("--mode", "--repo", "--home"),
        ),
    }
    contract = command_flag_contracts.get(command)
    if contract is None:
        raise SyncError(f"scheduler config has unsupported command: {command}")
    allowed_flags, required_flags = contract
    parsed_flags: dict[str, str] = {}
    for index in range(0, len(flags), 2):
        name = flags[index]
        if name in parsed_flags:
            raise SyncError(f"scheduler config repeats {name}")
        value = flags[index + 1]
        if value.startswith("-"):
            raise SyncError(
                f"scheduler config value for {name} must not be an option token"
            )
        parsed_flags[name] = value
    for name in parsed_flags:
        if name not in allowed_flags:
            raise SyncError(f"scheduler config command {command} does not allow {name}")
    for name in required_flags:
        if name not in parsed_flags:
            raise SyncError(f"scheduler config is missing {name}")

    if command == "install":
        mode = "public"
    elif command == "install-private":
        mode = "private"
    else:
        mode = parsed_flags["--mode"]
        if mode not in {"public", "private"}:
            raise SyncError(f"scheduler config has unsupported mode: {mode}")

    repo = parsed_flags["--repo"]
    if REPOSITORY_RE.fullmatch(repo) is None:
        raise SyncError("scheduler repository must be an owner/repo string")
    raw_home = parsed_flags["--home"]
    configured_home = Path(raw_home).expanduser()
    if mode == "private":
        for name in ("--base-repo", "--owner"):
            if name not in parsed_flags:
                raise SyncError(f"scheduler config is missing {name}")
        base_repo = parsed_flags["--base-repo"]
        owner = parsed_flags["--owner"]
        if REPOSITORY_RE.fullmatch(base_repo) is None:
            raise SyncError("scheduler base repository must be an owner/repo string")
        owner = _validate_owner(owner, "scheduler owner")
        if owner == PUBLIC_OWNER:
            raise SyncError("private scheduler owner must not be public")
    else:
        base_repo = repo
        owner = PUBLIC_OWNER
        if "--base-repo" in parsed_flags:
            raise SyncError("public scheduler must not configure --base-repo")
        if "--owner" in parsed_flags:
            raise SyncError("public scheduler must not configure --owner")
    return SchedulerConfig(
        platform=platform_name,
        config_paths=config_paths,
        interval_minutes=interval_minutes,
        runner=runner,
        home=configured_home,
        command=command,
        mode=mode,
        repo=repo,
        base_repo=base_repo,
        owner=owner,
    )


def _load_macos_scheduler_config(
    paths: SchedulerPaths,
    *,
    audited_snapshot: ManagedStateFileSnapshot | None = None,
) -> SchedulerConfig | None:
    assert paths.launchd_plist is not None
    snapshot = audited_snapshot or _scheduler_config_snapshot(
        paths.launchd_plist,
        1024 * 1024,
    )
    if not snapshot.exists:
        return None
    assert snapshot.payload is not None
    payload = snapshot.payload
    try:
        data = plistlib.loads(payload)
    except Exception as error:
        raise SyncError(
            f"invalid launchd scheduler config: {paths.launchd_plist}"
        ) from error
    if not isinstance(data, dict) or data.get("Label") != LAUNCHD_LABEL:
        raise SyncError(f"launchd scheduler label is invalid: {paths.launchd_plist}")
    interval_seconds = data.get("StartInterval")
    if (
        type(interval_seconds) is not int
        or interval_seconds < 60
        or interval_seconds % 60
        or interval_seconds // 60 > MAX_SCHEDULER_INTERVAL_MINUTES
    ):
        raise SyncError("launchd scheduler interval must be whole minutes")
    config = _parse_scheduler_program_arguments(
        data.get("ProgramArguments"),
        platform_name="macos",
        config_paths=(paths.launchd_plist,),
        interval_minutes=interval_seconds // 60,
    )
    expected_aqua = _launchd_plist(
        config.home,
        config.repo,
        config.interval_minutes,
        config.runner,
        mode=config.mode,
        base_repo=config.base_repo or config.repo,
        owner=config.owner or PUBLIC_OWNER,
    )
    expected_background = _legacy_background_launchd_plist(
        config.home,
        config.repo,
        config.interval_minutes,
        config.runner,
        mode=config.mode,
        base_repo=config.base_repo or config.repo,
        owner=config.owner or PUBLIC_OWNER,
    )
    expected_legacy_gui = _legacy_gui_launchd_plist(
        config.home,
        config.repo,
        config.interval_minutes,
        config.runner,
        mode=config.mode,
        base_repo=config.base_repo or config.repo,
        owner=config.owner or PUBLIC_OWNER,
    )
    if config.command != "run-scheduled":
        expected_background["ProgramArguments"] = data.get("ProgramArguments")
        expected_legacy_gui["ProgramArguments"] = data.get("ProgramArguments")
    legacy_profiles = [
        (
            expected_background,
            MACOS_BACKGROUND_LAUNCHD_DOMAIN,
            MACOS_LAUNCHD_PROFILE_BACKGROUND,
        ),
        (
            expected_legacy_gui,
            MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
            MACOS_LAUNCHD_PROFILE_GUI,
        ),
    ]
    accepted_profiles: list[tuple[dict[str, Any], str, str]] = []
    if config.command == "run-scheduled":
        accepted_profiles.append(
            (
                expected_aqua,
                MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
                MACOS_LAUNCHD_PROFILE_AQUA,
            )
        )
    accepted_profiles.extend(legacy_profiles)
    if config.command != "run-scheduled":
        # Older published schedulers predate the no-bytecode environment
        # hardening. Admit only those two otherwise-exact historical profiles
        # so a bare install-scheduler can repair them in one transaction.
        accepted_profiles.extend(
            (
                (
                    {
                        **expected,
                        "EnvironmentVariables": {
                            key: value
                            for key, value in expected["EnvironmentVariables"].items()
                            if key != "PYTHONDONTWRITEBYTECODE"
                        },
                    },
                    domain,
                    profile,
                )
                for expected, domain, profile in legacy_profiles
            )
        )
    matched_profile = next(
        (
            (domain, profile)
            for expected, domain, profile in accepted_profiles
            if _plist_value_matches_exactly(data, expected)
        ),
        None,
    )
    if matched_profile is None:
        raise SyncError(
            f"launchd scheduler config has unsupported execution semantics: "
            f"{paths.launchd_plist}"
        )
    if not _scheduler_file_snapshots_match(
        _scheduler_config_snapshot(paths.launchd_plist, 1024 * 1024),
        snapshot,
    ):
        raise SyncError(
            f"launchd scheduler config changed during audit: {paths.launchd_plist}"
        )
    launchd_domain, launchd_profile = matched_profile
    return replace(
        config,
        launchd_domain=launchd_domain,
        launchd_profile=launchd_profile,
    )


def _plist_value_matches_exactly(actual: Any, expected: Any) -> bool:
    if type(actual) is not type(expected):
        return False
    if isinstance(expected, dict):
        return actual.keys() == expected.keys() and all(
            _plist_value_matches_exactly(actual[key], expected[key]) for key in expected
        )
    if isinstance(expected, list):
        return len(actual) == len(expected) and all(
            _plist_value_matches_exactly(actual_item, expected_item)
            for actual_item, expected_item in zip(actual, expected)
        )
    return actual == expected


def _systemd_drop_in_metadata(
    metadata: os.stat_result,
) -> tuple[int, int, int, int, int, int]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        stat.S_IFMT(metadata.st_mode),
        stat.S_IMODE(metadata.st_mode),
        metadata.st_uid,
        metadata.st_gid,
    )


def _systemd_drop_in_snapshot(unit_path: Path) -> SystemdDropInSnapshot:
    drop_in = unit_path.with_name(unit_path.name + ".d")
    user_home = Path.home().expanduser()
    try:
        drop_in.relative_to(user_home)
    except ValueError as error:
        raise SyncError(
            f"systemd drop-in path must remain beneath the user home: {drop_in}"
        ) from error
    try:
        parent_fd = _open_directory_beneath(user_home, drop_in.parent)
    except FileNotFoundError:
        return SystemdDropInSnapshot(exists=False)
    except OSError as error:
        raise SyncError(
            f"failed to inspect systemd drop-in parent: {drop_in}"
        ) from error
    directory_fd = -1
    try:
        parent_identity = _directory_identity(parent_fd)
        try:
            named_metadata = os.stat(
                drop_in.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            if not _bound_directory_matches(
                user_home,
                drop_in.parent,
                parent_fd,
            ):
                raise SyncError(
                    f"systemd drop-in parent changed during audit: {drop_in}"
                )
            return SystemdDropInSnapshot(
                exists=False,
                parent_identity=parent_identity,
            )
        except OSError as error:
            raise SyncError(
                f"failed to inspect systemd drop-in path: {drop_in}"
            ) from error
        if not stat.S_ISDIR(named_metadata.st_mode):
            raise SyncError(f"refusing unsafe systemd drop-in path: {drop_in}")
        if (
            named_metadata.st_uid != os.geteuid()
            or stat.S_IMODE(named_metadata.st_mode) & 0o022
        ):
            raise SyncError(
                f"systemd drop-in directory has unsafe access policy: {drop_in}"
            )
        try:
            directory_fd = os.open(
                drop_in.name,
                _directory_open_flags(nofollow=True),
                dir_fd=parent_fd,
            )
        except OSError as error:
            raise SyncError(
                f"failed to safely open systemd drop-in path: {drop_in}"
            ) from error
        opened_metadata = os.fstat(directory_fd)
        expected_metadata = _systemd_drop_in_metadata(named_metadata)
        if _systemd_drop_in_metadata(opened_metadata) != expected_metadata:
            raise SyncError(
                f"systemd drop-in directory changed during audit: {drop_in}"
            )
        try:
            entries = os.listdir(directory_fd)
        except OSError as error:
            raise SyncError(f"failed to inspect systemd drop-ins: {drop_in}") from error
        if entries:
            raise SyncError(f"systemd scheduler drop-ins are unsupported: {drop_in}")
        try:
            current_metadata = os.stat(
                drop_in.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except OSError as error:
            raise SyncError(
                f"systemd drop-in directory changed during audit: {drop_in}"
            ) from error
        if (
            _systemd_drop_in_metadata(os.fstat(directory_fd)) != expected_metadata
            or _systemd_drop_in_metadata(current_metadata) != expected_metadata
            or not _bound_directory_matches(
                user_home,
                drop_in.parent,
                parent_fd,
            )
        ):
            raise SyncError(
                f"systemd drop-in directory changed during audit: {drop_in}"
            )
        return SystemdDropInSnapshot(
            exists=True,
            parent_identity=parent_identity,
            directory_identity=(
                opened_metadata.st_dev,
                opened_metadata.st_ino,
            ),
            file_type=stat.S_IFMT(opened_metadata.st_mode),
            mode=stat.S_IMODE(opened_metadata.st_mode),
            uid=opened_metadata.st_uid,
            gid=opened_metadata.st_gid,
        )
    finally:
        if directory_fd >= 0:
            _close_fd_quietly(directory_fd)
        _close_fd_quietly(parent_fd)


def _audit_systemd_drop_ins(
    paths: SchedulerPaths,
) -> tuple[SystemdDropInSnapshot, SystemdDropInSnapshot]:
    assert paths.systemd_service is not None
    assert paths.systemd_timer is not None
    return (
        _systemd_drop_in_snapshot(paths.systemd_service),
        _systemd_drop_in_snapshot(paths.systemd_timer),
    )


def _revalidate_systemd_drop_ins(
    paths: SchedulerPaths,
    expected: tuple[SystemdDropInSnapshot, ...],
) -> None:
    current = _audit_systemd_drop_ins(paths)
    if len(current) != len(expected) or any(
        actual != bound for actual, bound in zip(current, expected)
    ):
        raise SyncError("systemd scheduler drop-ins changed after semantic audit")


def _load_linux_scheduler_config(
    paths: SchedulerPaths,
    *,
    audited_snapshots: (
        tuple[ManagedStateFileSnapshot, ManagedStateFileSnapshot] | None
    ) = None,
    audited_drop_ins: (
        tuple[SystemdDropInSnapshot, SystemdDropInSnapshot] | None
    ) = None,
) -> SchedulerConfig | None:
    assert paths.systemd_service is not None
    assert paths.systemd_timer is not None
    if audited_drop_ins is None:
        drop_in_snapshots = _audit_systemd_drop_ins(paths)
    else:
        drop_in_snapshots = audited_drop_ins
        _revalidate_systemd_drop_ins(paths, drop_in_snapshots)
    pair_transaction = _scheduler_pair_transaction_path(paths)
    if _path_exists_or_is_link(pair_transaction):
        raise SyncError(
            f"systemd scheduler has a pending pair transaction: {pair_transaction}"
        )
    if audited_snapshots is None:
        service_snapshot = _scheduler_config_snapshot(
            paths.systemd_service,
            1024 * 1024,
        )
        timer_snapshot = _scheduler_config_snapshot(
            paths.systemd_timer,
            1024 * 1024,
        )
    else:
        service_snapshot, timer_snapshot = audited_snapshots
    service_exists = service_snapshot.exists
    timer_exists = timer_snapshot.exists
    if not service_exists and not timer_exists:
        _revalidate_systemd_drop_ins(paths, drop_in_snapshots)
        return None
    if service_exists != timer_exists:
        raise SyncError("systemd scheduler service/timer pair is incomplete")
    assert service_snapshot.payload is not None
    assert timer_snapshot.payload is not None
    service_payload = service_snapshot.payload
    timer_payload = timer_snapshot.payload
    try:
        service = service_payload.decode("utf-8")
        timer = timer_payload.decode("utf-8")
    except UnicodeDecodeError as error:
        raise SyncError("systemd scheduler config is not valid UTF-8") from error
    exec_lines = [
        line.partition("=")[2]
        for line in service.splitlines()
        if line.startswith("ExecStart=")
    ]
    interval_lines = [
        line.partition("=")[2]
        for line in timer.splitlines()
        if line.startswith("OnUnitActiveSec=")
    ]
    if len(exec_lines) != 1 or len(interval_lines) != 1:
        raise SyncError("systemd scheduler config is missing a unique command/interval")
    interval_match = re.fullmatch(r"([1-9][0-9]{0,8})min", interval_lines[0])
    if interval_match is None:
        raise SyncError("systemd scheduler interval must use whole minutes")
    arguments = _parse_systemd_exec_arguments(exec_lines[0])
    try:
        interval_minutes = int(interval_match.group(1))
    except ValueError as error:
        raise SyncError("systemd scheduler interval is invalid") from error
    if interval_minutes > MAX_SCHEDULER_INTERVAL_MINUTES:
        raise SyncError("systemd scheduler interval exceeds the supported limit")
    config = _parse_scheduler_program_arguments(
        arguments,
        platform_name="linux",
        config_paths=(paths.systemd_service, paths.systemd_timer),
        interval_minutes=interval_minutes,
    )
    expected_service = _systemd_service(
        config.home,
        config.repo,
        config.runner,
        mode=config.mode,
        base_repo=config.base_repo or config.repo,
        owner=config.owner or PUBLIC_OWNER,
    )
    if config.command != "run-scheduled":
        expected_lines = expected_service.splitlines()
        expected_lines = [
            f"ExecStart={exec_lines[0]}" if line.startswith("ExecStart=") else line
            for line in expected_lines
        ]
        expected_service = "\n".join(expected_lines)
    expected_timer = _systemd_timer(config.interval_minutes)
    if service != expected_service or timer != expected_timer:
        raise SyncError("systemd scheduler config has unsupported execution semantics")
    if not _scheduler_file_snapshots_match(
        _scheduler_config_snapshot(paths.systemd_service, 1024 * 1024),
        service_snapshot,
    ) or not _scheduler_file_snapshots_match(
        _scheduler_config_snapshot(paths.systemd_timer, 1024 * 1024),
        timer_snapshot,
    ):
        raise SyncError("systemd scheduler service/timer pair changed during read")
    _revalidate_systemd_drop_ins(paths, drop_in_snapshots)
    return config


def _load_scheduler_config(paths: SchedulerPaths) -> SchedulerConfig | None:
    if paths.platform == "macos":
        return _load_macos_scheduler_config(paths)
    if paths.platform == "linux":
        return _load_linux_scheduler_config(paths)
    raise SyncError(f"unsupported scheduler platform: {paths.platform}")


def _audit_scheduler_config(paths: SchedulerPaths) -> SchedulerConfigAudit:
    if paths.platform == "macos":
        assert paths.launchd_plist is not None
        snapshot = _scheduler_config_snapshot(
            paths.launchd_plist,
            1024 * 1024,
        )
        return SchedulerConfigAudit(
            config=_load_macos_scheduler_config(
                paths,
                audited_snapshot=snapshot,
            ),
            snapshots=(snapshot,),
        )
    if paths.platform == "linux":
        assert paths.systemd_service is not None
        assert paths.systemd_timer is not None
        drop_in_snapshots = _audit_systemd_drop_ins(paths)
        snapshots = (
            _scheduler_config_snapshot(
                paths.systemd_service,
                1024 * 1024,
            ),
            _scheduler_config_snapshot(
                paths.systemd_timer,
                1024 * 1024,
            ),
        )
        return SchedulerConfigAudit(
            config=_load_linux_scheduler_config(
                paths,
                audited_snapshots=snapshots,
                audited_drop_ins=drop_in_snapshots,
            ),
            snapshots=snapshots,
            systemd_drop_ins=drop_in_snapshots,
        )
    raise SyncError(f"unsupported scheduler platform: {paths.platform}")


def _revalidate_scheduler_config_audit(
    paths: SchedulerPaths,
    audit: SchedulerConfigAudit,
) -> None:
    if paths.platform == "macos":
        assert paths.launchd_plist is not None
        current = (
            _scheduler_config_snapshot(
                paths.launchd_plist,
                1024 * 1024,
            ),
        )
    elif paths.platform == "linux":
        assert paths.systemd_service is not None
        assert paths.systemd_timer is not None
        current = (
            _scheduler_config_snapshot(
                paths.systemd_service,
                1024 * 1024,
            ),
            _scheduler_config_snapshot(
                paths.systemd_timer,
                1024 * 1024,
            ),
        )
        _revalidate_systemd_drop_ins(paths, audit.systemd_drop_ins)
    else:
        raise SyncError(f"unsupported scheduler platform: {paths.platform}")
    if len(current) != len(audit.snapshots) or any(
        not _scheduler_file_snapshots_match(actual, expected)
        for actual, expected in zip(current, audit.snapshots)
    ):
        raise SyncError("scheduler configuration changed after semantic audit")


def _legacy_launchd_plist(paths: SchedulerPaths, label: str) -> Path:
    assert paths.launchd_plist is not None
    return paths.launchd_plist.parent / f"{label}.plist"


def _macos_launchd_domain(domain_kind: str) -> str:
    if domain_kind not in {
        MACOS_BACKGROUND_LAUNCHD_DOMAIN,
        MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
    }:
        raise SyncError(f"unsupported macOS launchd domain: {domain_kind}")
    return f"{domain_kind}/{os.getuid()}"


def _conditionally_remove_bound_scheduler_config(
    binding: SchedulerActivationBinding,
    *,
    boundary: str,
    related_bindings: tuple[SchedulerActivationBinding, ...] = (),
) -> None:
    if binding.removed:
        raise SyncError(
            f"{binding.description} was already conditionally removed: {binding.path}"
        )
    bindings: list[SchedulerActivationBinding] = []
    seen: set[int] = set()
    for candidate in (binding, *related_bindings):
        identity = id(candidate)
        if identity in seen:
            continue
        seen.add(identity)
        bindings.append(candidate)
    for candidate in bindings:
        _revalidate_launchd_activation_binding(
            candidate,
            boundary=boundary,
        )
    if not binding.expected.exists:
        return
    _isolate_and_delete_pending_cleanup_file(
        binding.home,
        binding.path,
        binding.parent_fd,
        binding.expected,
        label=binding.description,
    )
    binding.expected = ManagedStateFileSnapshot(
        exists=False,
        parent_identity=binding.expected.parent_identity,
    )
    binding.removed = True
    after_boundary = (
        f"after {boundary.removeprefix('before ')}"
        if boundary.startswith("before ")
        else f"after {boundary}"
    )
    for candidate in bindings:
        _revalidate_launchd_activation_binding(
            candidate,
            boundary=after_boundary,
        )


def _cleanup_legacy_launchd_schedulers(
    paths: SchedulerPaths,
    *,
    dry_run: bool,
    disable: bool,
    remove: bool,
    activation_bindings: tuple[SchedulerActivationBinding, ...] = (),
    retained_legacy_bindings: tuple[SchedulerActivationBinding, ...] | None = None,
) -> None:
    if paths.launchd_plist is None:
        return
    if not remove:
        return
    labels = tuple(LEGACY_LAUNCHD_LABELS)

    def live_bindings(
        bindings: tuple[SchedulerActivationBinding, ...],
    ) -> tuple[SchedulerActivationBinding, ...]:
        live: list[SchedulerActivationBinding] = []
        seen: set[int] = set()
        for binding in bindings:
            identity = id(binding)
            if identity in seen:
                raise SyncError(
                    "legacy scheduler cleanup received duplicate file bindings"
                )
            seen.add(identity)
            live.append(binding)
        return tuple(live)

    def cleanup_one(
        label: str,
        legacy_plist: Path,
        legacy_binding: SchedulerActivationBinding | None,
        legacy_present: bool,
        complete_bindings: tuple[SchedulerActivationBinding, ...],
    ) -> None:
        if disable:
            del legacy_present
            for domain_kind in (
                MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
                MACOS_BACKGROUND_LAUNCHD_DOMAIN,
            ):
                domain = _macos_launchd_domain(domain_kind)
                _run_native_scheduler_action(
                    ["launchctl", "bootout", f"{domain}/{label}"],
                    dry_run=dry_run,
                    allow_fail=NATIVE_FAILURE_ALREADY_ABSENT,
                    activation_bindings=live_bindings(complete_bindings),
                )
                _run_native_scheduler_action(
                    ["launchctl", "disable", f"{domain}/{label}"],
                    dry_run=dry_run,
                    allow_fail=NATIVE_FAILURE_ALREADY_ABSENT,
                    activation_bindings=live_bindings(complete_bindings),
                )
        if dry_run:
            _unlink_file(legacy_plist, dry_run=True)
            return
        if legacy_binding is None:
            return
        _conditionally_remove_bound_scheduler_config(
            legacy_binding,
            boundary="before conditional legacy removal",
            related_bindings=complete_bindings,
        )

    if retained_legacy_bindings is not None:
        if dry_run:
            raise SyncError("dry-run cannot consume retained legacy bindings")
        if len(retained_legacy_bindings) != len(labels):
            raise SyncError("retained legacy scheduler binding count changed")
        activation_ids = {id(binding) for binding in activation_bindings}
        for label, legacy_binding in zip(labels, retained_legacy_bindings):
            legacy_plist = _legacy_launchd_plist(paths, label)
            if (
                legacy_binding.path != legacy_plist
                or id(legacy_binding) not in activation_ids
            ):
                raise SyncError(
                    f"retained legacy scheduler binding changed: {legacy_plist}"
                )
            cleanup_one(
                label,
                legacy_plist,
                legacy_binding,
                legacy_binding.expected.exists,
                activation_bindings,
            )
        return

    for label in labels:
        legacy_plist = _legacy_launchd_plist(paths, label)
        legacy_snapshot = _scheduler_config_snapshot(legacy_plist)

        if dry_run:
            cleanup_one(
                label,
                legacy_plist,
                None,
                legacy_snapshot.exists,
                (),
            )
            continue
        with _retain_launchd_activation_binding(
            legacy_plist,
            legacy_snapshot,
            description=f"legacy launchd scheduler {label}",
        ) as legacy_binding:
            cleanup_one(
                label,
                legacy_plist,
                legacy_binding,
                legacy_snapshot.exists,
                (*activation_bindings, legacy_binding),
            )


def _scheduler_log_dir(home: Path) -> Path:
    return _personal_sync_root(home.expanduser()) / "logs"


def _scheduler_install_args(
    runner: Path,
    repo: str,
    home: Path,
    *,
    mode: str = "public",
    base_repo: str = DEFAULT_PUBLIC_RELEASE_REPO,
    owner: str = "private",
) -> list[str]:
    if mode == "public":
        return [
            str(runner),
            "run-scheduled",
            "--mode",
            "public",
            "--repo",
            repo,
            "--home",
            str(home.expanduser()),
        ]
    if mode == "private":
        return [
            str(runner),
            "run-scheduled",
            "--mode",
            "private",
            "--repo",
            repo,
            "--base-repo",
            base_repo,
            "--owner",
            owner,
            "--home",
            str(home.expanduser()),
        ]
    raise SyncError(f"unsupported scheduler mode: {mode}")


def _legacy_gui_launchd_plist(
    home: Path,
    repo: str,
    interval_minutes: int,
    runner: Path,
    *,
    mode: str = "public",
    base_repo: str = DEFAULT_PUBLIC_RELEASE_REPO,
    owner: str = "private",
) -> dict[str, Any]:
    log_dir = _scheduler_log_dir(home)
    return {
        "Label": LAUNCHD_LABEL,
        "ProgramArguments": _scheduler_install_args(
            runner,
            repo,
            home,
            mode=mode,
            base_repo=base_repo,
            owner=owner,
        ),
        "StartInterval": interval_minutes * 60,
        "RunAtLoad": True,
        "StandardOutPath": str(log_dir / "codex-personal-sync.out.log"),
        "StandardErrorPath": str(log_dir / "codex-personal-sync.err.log"),
        "EnvironmentVariables": {
            "PATH": MACOS_SCHEDULER_PATH,
            "PYTHONDONTWRITEBYTECODE": "1",
        },
    }


def _launchd_plist(
    home: Path,
    repo: str,
    interval_minutes: int,
    runner: Path,
    *,
    mode: str = "public",
    base_repo: str = DEFAULT_PUBLIC_RELEASE_REPO,
    owner: str = "private",
) -> dict[str, Any]:
    payload = _legacy_background_launchd_plist(
        home,
        repo,
        interval_minutes,
        runner,
        mode=mode,
        base_repo=base_repo,
        owner=owner,
    )
    payload["LimitLoadToSessionType"] = MACOS_AQUA_SESSION_TYPE
    return payload


def _legacy_background_launchd_plist(
    home: Path,
    repo: str,
    interval_minutes: int,
    runner: Path,
    *,
    mode: str = "public",
    base_repo: str = DEFAULT_PUBLIC_RELEASE_REPO,
    owner: str = "private",
) -> dict[str, Any]:
    user_home = _codex_user_home(home)
    payload = _legacy_gui_launchd_plist(
        home,
        repo,
        interval_minutes,
        runner,
        mode=mode,
        base_repo=base_repo,
        owner=owner,
    )
    payload.update(
        {
            "LimitLoadToSessionType": MACOS_BACKGROUND_SESSION_TYPE,
            "LowPriorityIO": True,
            "ProcessType": MACOS_BACKGROUND_SESSION_TYPE,
            "ThrottleInterval": 60,
            "Umask": 0o077,
            "WorkingDirectory": str(user_home),
        }
    )
    payload["EnvironmentVariables"] = {
        "HOME": str(user_home),
        "PATH": MACOS_SCHEDULER_PATH,
        "PYTHONDONTWRITEBYTECODE": "1",
    }
    return payload


def _validate_systemd_argument(value: str) -> None:
    try:
        value.encode("utf-8")
    except UnicodeEncodeError as error:
        raise SyncError("systemd scheduler arguments must be valid UTF-8") from error
    if any(unicodedata.category(character) == "Cc" for character in value):
        raise SyncError(
            "systemd scheduler arguments must not contain control characters"
        )


def _systemd_quote(value: str) -> str:
    _validate_systemd_argument(value)
    escaped = (
        value.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("$", "$$")
        .replace("%", "%%")
    )
    return f'"{escaped}"'


def _parse_systemd_exec_arguments(command: str) -> list[str]:
    arguments: list[str] = []
    offset = 0
    while offset < len(command):
        if command[offset] != '"':
            raise SyncError("systemd scheduler command quoting is invalid")
        offset += 1
        argument: list[str] = []
        while offset < len(command):
            current = command[offset]
            if current == '"':
                offset += 1
                break
            if current == "\\":
                offset += 1
                if offset >= len(command) or command[offset] not in {'"', "\\"}:
                    raise SyncError("systemd scheduler command quoting is invalid")
                argument.append(command[offset])
                offset += 1
                continue
            if current in {"$", "%"}:
                if offset + 1 >= len(command) or command[offset + 1] != current:
                    raise SyncError(
                        "systemd scheduler command contains unsupported "
                        "expansion semantics"
                    )
                argument.append(current)
                offset += 2
                continue
            _validate_systemd_argument(current)
            argument.append(current)
            offset += 1
        else:
            raise SyncError("systemd scheduler command quoting is invalid")
        arguments.append("".join(argument))
        if offset == len(command):
            break
        if command[offset] != " ":
            raise SyncError("systemd scheduler command quoting is invalid")
        offset += 1
        if offset == len(command) or command[offset] == " ":
            raise SyncError("systemd scheduler command quoting is invalid")
    if not arguments:
        raise SyncError("systemd scheduler command quoting is invalid")
    canonical = " ".join(_systemd_quote(argument) for argument in arguments)
    if command != canonical:
        raise SyncError("systemd scheduler command quoting is invalid")
    return arguments


def _systemd_service(
    home: Path,
    repo: str,
    runner: Path,
    *,
    mode: str = "public",
    base_repo: str = DEFAULT_PUBLIC_RELEASE_REPO,
    owner: str = "private",
) -> str:
    exec_start = " ".join(
        _systemd_quote(arg)
        for arg in _scheduler_install_args(
            runner,
            repo,
            home,
            mode=mode,
            base_repo=base_repo,
            owner=owner,
        )
    )
    return "\n".join(
        [
            "[Unit]",
            "Description=Personal Codex config sync",
            "",
            "[Service]",
            "Type=oneshot",
            f"Environment={_systemd_quote(f'PATH={LINUX_SCHEDULER_PATH}')}",
            'Environment="PYTHONDONTWRITEBYTECODE=1"',
            f"ExecStart={exec_start}",
            "",
        ]
    )


def _systemd_timer(interval_minutes: int) -> str:
    return "\n".join(
        [
            "[Unit]",
            "Description=Run Personal Codex config sync periodically",
            "",
            "[Timer]",
            "OnBootSec=5min",
            f"OnUnitActiveSec={interval_minutes}min",
            "Persistent=true",
            f"Unit={SYSTEMD_UNIT}.service",
            "",
            "[Install]",
            "WantedBy=timers.target",
            "",
        ]
    )


def _native_scheduler_argv(args: list[str]) -> list[str]:
    if not args:
        raise SyncError("scheduler native command is empty")
    executable = {
        "launchctl": Path("/bin/launchctl"),
        "systemctl": Path("/usr/bin/systemctl"),
    }.get(args[0])
    if executable is None:
        raise SyncError(f"unsupported scheduler native command: {args[0]}")
    try:
        metadata = executable.stat()
    except OSError as error:
        raise SyncError(
            f"scheduler native executable is unavailable: {executable}"
        ) from error
    if (
        not stat.S_ISREG(metadata.st_mode)
        or metadata.st_uid != 0
        or stat.S_IMODE(metadata.st_mode) & 0o022
        or not os.access(executable, os.X_OK)
    ):
        raise SyncError(f"scheduler native executable is unsafe: {executable}")
    return [str(executable), *args[1:]]


def _scheduler_native_environment() -> dict[str, str]:
    environment = {
        "HOME": str(Path.home().expanduser()),
        "PATH": "/usr/bin:/bin",
        "LANG": "C",
        "LC_ALL": "C",
    }
    for name in ("XDG_RUNTIME_DIR", "DBUS_SESSION_BUS_ADDRESS"):
        value = os.environ.get(name)
        if value is not None and len(value.encode("utf-8")) <= 4096:
            environment[name] = value
    return environment


def _launchd_quoted_not_loaded_evidence(
    raw_evidence: str,
    *,
    label: str,
    uid: str,
    domain_kind: str,
) -> bool:
    evidence = re.sub(r"\s+", " ", raw_evidence.strip())
    if not evidence:
        return False
    if domain_kind == MACOS_BACKGROUND_LAUNCHD_DOMAIN:
        domain_evidence = r"in domain for uid: ([0-9]+)"
    elif domain_kind == MACOS_LEGACY_GUI_LAUNCHD_DOMAIN:
        domain_evidence = r"in domain for user gui: ([0-9]+)"
    else:
        return False
    matched = re.fullmatch(
        (
            r'(?:bad request\. )?could not find service "([^"]+)" '
            + domain_evidence
            + r"[.;]?"
        ),
        evidence,
        flags=re.IGNORECASE,
    )
    return matched is not None and matched.group(1) == label and matched.group(2) == uid


def _launchctl_expected_not_loaded_target(
    args: list[str],
) -> tuple[str, str, str] | None:
    if len(args) < 3 or args[0] != "launchctl":
        return None
    operation = args[1]
    if operation not in {"bootout", "disable"}:
        return None
    uid = str(os.getuid())
    for domain_kind in (
        MACOS_BACKGROUND_LAUNCHD_DOMAIN,
        MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
    ):
        domain = f"{domain_kind}/{uid}"
        for label in (LAUNCHD_LABEL, *LEGACY_LAUNCHD_LABELS):
            service_target = f"{domain}/{label}"
            if len(args) == 3 and args[2] == service_target:
                return label, uid, domain_kind
            if (
                operation == "bootout"
                and len(args) == 4
                and args[2] == domain
                and Path(args[3]).name == f"{label}.plist"
            ):
                return label, uid, domain_kind
    return None


def _launchd_gui_domain_unavailable_evidence(raw_evidence: str) -> bool:
    evidence = re.sub(r"\s+", " ", raw_evidence.strip())
    return (
        re.fullmatch(
            (
                r"(?:could not print domain|(?:boot-out|bootout) failed): "
                r"125: domain does not support specified action[.;]?"
            ),
            evidence,
            flags=re.IGNORECASE,
        )
        is not None
    )


def _launchd_gui_disable_unavailable_evidence(raw_evidence: str) -> bool:
    evidence = re.sub(r"\s+", " ", raw_evidence.strip())
    return (
        re.fullmatch(
            (
                r"could not disable service: "
                r"125: domain does not support specified action[.;]?"
            ),
            evidence,
            flags=re.IGNORECASE,
        )
        is not None
    )


def _native_scheduler_failure_is_already_absent(
    args: list[str],
    completed: subprocess.CompletedProcess[str],
) -> bool:
    if len(completed.stdout) > 64 * 1024 or len(completed.stderr) > 64 * 1024:
        return False
    evidence = re.sub(
        r"\s+",
        " ",
        (completed.stdout + "\n" + completed.stderr).strip().casefold(),
    )
    if not evidence:
        return False
    terminal_punctuation = r"[.;]?"
    if (
        len(args) >= 2
        and args[0] == "launchctl"
        and args[1]
        in {
            "bootout",
            "disable",
        }
    ):
        target = _launchctl_expected_not_loaded_target(args)
        return (
            re.fullmatch(
                (
                    r"(?:could not find specified service|"
                    r"could not find service in domain|"
                    r"service not found in domain)" + terminal_punctuation
                ),
                evidence,
            )
            is not None
            or re.fullmatch(
                (
                    r"(?:boot-out|bootout) failed: 3: no such process"
                    + terminal_punctuation
                ),
                evidence,
            )
            is not None
            or (
                target is not None
                and _launchd_quoted_not_loaded_evidence(
                    completed.stdout + "\n" + completed.stderr,
                    label=target[0],
                    uid=target[1],
                    domain_kind=target[2],
                )
            )
            or (
                target is not None
                and target[2] == MACOS_LEGACY_GUI_LAUNCHD_DOMAIN
                and (
                    _launchd_gui_domain_unavailable_evidence(
                        completed.stdout + "\n" + completed.stderr
                    )
                    or (
                        args[1] == "disable"
                        and _launchd_gui_disable_unavailable_evidence(
                            completed.stdout + "\n" + completed.stderr
                        )
                    )
                )
            )
        )
    if (
        len(args) == 5
        and args[:4] == ["systemctl", "--user", "disable", "--now"]
        and args[4] == f"{SYSTEMD_UNIT}.timer"
    ):
        unit = re.escape(args[4].casefold())
        return (
            re.fullmatch(
                (
                    rf"(?:failed to disable unit: )?unit {unit} "
                    rf"(?:not loaded|could not be found){terminal_punctuation}"
                ),
                evidence,
            )
            is not None
        )
    return False


def _raise_scheduler_failure_after_cleanup(
    process: _GuardedProcess,
    primary: BaseException,
) -> NoReturn:
    try:
        receipt = _cleanup_gh_process_group(
            process,
            process_label="scheduler",
        )
    except Exception as cleanup_error:
        raise SyncError(
            f"{primary}; scheduler process cleanup raised an exception: "
            f"{cleanup_error}",
            code="scheduler-cleanup-inconclusive",
        ) from primary
    if not receipt.complete:
        raise SyncError(
            f"{primary}; scheduler process cleanup was inconclusive: "
            f"{_gh_cleanup_detail(receipt)}",
            code="scheduler-cleanup-inconclusive",
        ) from primary
    raise primary


def _run_bounded_scheduler_process(
    native_args: list[str],
    *,
    timeout_seconds: float,
) -> subprocess.CompletedProcess[str]:
    """Run a fixed native scheduler argv with hard raw-byte and runtime caps."""
    if timeout_seconds <= 0:
        raise SyncError(
            "scheduler native timeout must be positive",
            code="scheduler-timeout",
        )
    deadline = time.monotonic() + timeout_seconds
    try:
        process = _spawn_guarded_process(
            native_args,
            deadline=deadline,
            process_label="scheduler native command",
            env=_scheduler_native_environment(),
            unavailable_code="scheduler-command-unavailable",
            unavailable_message="scheduler native command could not start",
        )
    except SyncError as error:
        if error.code == "process-guardian-cleanup-inconclusive":
            raise SyncError(
                f"scheduler guardian cleanup was inconclusive: {error}",
                code="scheduler-cleanup-inconclusive",
            ) from error
        if error.code == "process-guardian-operation-timeout":
            raise SyncError(
                "scheduler native command exceeded its monotonic deadline",
                code="scheduler-timeout",
            ) from error
        raise
    if process.stdout is None or process.stderr is None or process.status is None:
        _raise_scheduler_failure_after_cleanup(
            process,
            SyncError(
                "scheduler native command did not provide bounded process pipes",
                code="scheduler-process-io",
            ),
        )

    selector: selectors.BaseSelector | None = None
    retained = {
        "stdout": bytearray(),
        "stderr": bytearray(),
        "status": bytearray(),
    }
    producer_bytes = {"stdout": 0, "stderr": 0}
    limits = {
        "stdout": MAX_SCHEDULER_NATIVE_STDOUT_BYTES,
        "stderr": MAX_SCHEDULER_NATIVE_STDERR_BYTES,
    }
    result: subprocess.CompletedProcess[str] | None = None
    pending_error: BaseException | None = None
    pending_cause: BaseException | None = None
    terminalization_started = False
    close_failures: list[tuple[str, BaseException]] = []
    output_eof: set[str] = set()
    try:
        try:
            selector = selectors.DefaultSelector()
            for name, stream in (
                ("stdout", process.stdout),
                ("stderr", process.stderr),
                ("status", process.status),
            ):
                os.set_blocking(stream.fileno(), False)
                selector.register(stream, selectors.EVENT_READ, name)
            while True:
                if (
                    output_eof == {"stdout", "stderr"}
                    and len(retained["status"]) == PROCESS_GUARDIAN_STATUS_RECORD.size
                ):
                    _require_guardian_status_writer_live(
                        process,
                        process_label="scheduler native command",
                        error_code="scheduler-process-io",
                    )
                    break
                if not selector.get_map():
                    raise SyncError(
                        "scheduler guardian protocol ended before completion",
                        code="scheduler-process-io",
                    )
                remaining_runtime = deadline - time.monotonic()
                if remaining_runtime <= 0:
                    raise SyncError(
                        "scheduler native command exceeded its monotonic deadline",
                        code="scheduler-timeout",
                    )
                events = selector.select(remaining_runtime)
                if not events:
                    continue
                for key, _mask in events:
                    name = key.data
                    maximum_read = 64 * 1024
                    if name == "status":
                        maximum_read = (
                            PROCESS_GUARDIAN_STATUS_RECORD.size
                            + 1
                            - len(retained["status"])
                        )
                    else:
                        remaining_bytes = limits[name] - producer_bytes[name]
                        maximum_read = min(64 * 1024, remaining_bytes + 1)
                    try:
                        chunk = os.read(key.fileobj.fileno(), maximum_read)
                    except BlockingIOError:
                        continue
                    except OSError as error:
                        raise SyncError(
                            f"cannot read scheduler native {name}: {error}",
                            code="scheduler-process-io",
                        ) from error
                    if not chunk:
                        if name == "status":
                            raise SyncError(
                                "scheduler guardian exited before process-group "
                                "fencing",
                                code="scheduler-process-io",
                            )
                        output_eof.add(name)
                        selector.unregister(key.fileobj)
                        continue
                    if name == "status":
                        retained["status"].extend(chunk)
                        if len(retained["status"]) > (
                            PROCESS_GUARDIAN_STATUS_RECORD.size
                        ):
                            raise SyncError(
                                "scheduler guardian status exceeds its bound",
                                code="scheduler-process-io",
                            )
                        continue
                    producer_bytes[name] += len(chunk)
                    if producer_bytes[name] > limits[name]:
                        raise SyncError(
                            "scheduler native command "
                            f"{name} exceeds the {limits[name]}-byte raw output limit",
                            code="scheduler-output-limit",
                        )
                    retained[name].extend(chunk)
            target_returncode = _parse_guardian_status(
                process,
                bytes(retained["status"]),
                process_label="scheduler native command",
                error_code="scheduler-process-io",
            )
            if process.returncode is not None:
                raise SyncError(
                    "scheduler guardian exited before process-group fencing",
                    code="scheduler-process-io",
                )
            terminalization_started = True
            terminalization = _terminalize_process_group_before_reap(
                process,
                deadline=time.monotonic() + GH_CLEANUP_TIMEOUT_SECONDS,
                process_label="scheduler guardian",
            )
            if not terminalization.complete:
                raise SyncError(
                    "scheduler guardian terminalization was inconclusive: "
                    f"{_terminalization_detail(terminalization)}",
                    code="scheduler-cleanup-inconclusive",
                )
            stdout = bytes(retained["stdout"]).decode("utf-8", errors="replace")
            stderr = bytes(retained["stderr"]).decode("utf-8", errors="replace")
            result = subprocess.CompletedProcess(
                args=native_args,
                returncode=target_returncode,
                stdout=stdout,
                stderr=stderr,
            )
        except SyncError as error:
            pending_error = error
        except (OSError, ValueError) as error:
            pending_error = SyncError(
                f"scheduler bounded process supervision failed: {error}",
                code="scheduler-process-io",
            )
            pending_cause = error
        except BaseException as error:
            pending_error = error
        if pending_error is not None and not terminalization_started:
            cleanup_primary = pending_error
            try:
                _raise_scheduler_failure_after_cleanup(process, cleanup_primary)
            except BaseException as resolved_error:
                pending_error = resolved_error
                if resolved_error is not cleanup_primary:
                    pending_cause = None
    finally:
        close_failures = _close_process_supervision_resources(
            process,
            selector,
            process_label="scheduler native command",
        )
    if close_failures:
        close_detail = "; ".join(detail for detail, _error in close_failures)
        if pending_error is not None:
            raise SyncError(
                f"{pending_error}; scheduler cleanup was inconclusive: {close_detail}",
                code="scheduler-cleanup-inconclusive",
            ) from pending_error
        raise SyncError(
            f"scheduler cleanup was inconclusive: {close_detail}",
            code="scheduler-cleanup-inconclusive",
        ) from close_failures[0][1]
    if pending_error is not None:
        if pending_cause is not None:
            raise pending_error from pending_cause
        raise pending_error.with_traceback(pending_error.__traceback__)
    if result is None:
        raise SyncError(
            "scheduler native command produced no terminal result",
            code="scheduler-process-io",
        )
    return result


def _run_native_command(
    args: list[str],
    *,
    dry_run: bool,
    allow_fail: bool | str = False,
) -> None:
    if not isinstance(allow_fail, bool) and allow_fail != NATIVE_FAILURE_ALREADY_ABSENT:
        raise SyncError("unsupported native scheduler failure policy")
    if dry_run:
        print("would run: " + " ".join(args))
        return
    native_args = _native_scheduler_argv(args)
    try:
        completed = _run_bounded_scheduler_process(
            native_args,
            timeout_seconds=SCHEDULER_NATIVE_ACTION_TIMEOUT_SECONDS,
        )
    except SyncError as error:
        if allow_fail is True and error.code != "scheduler-cleanup-inconclusive":
            print(f"ignored failed command {' '.join(args)}: {error}")
            return
        raise SyncError(
            f"failed to run {' '.join(args)}: {error}",
            code=error.code,
        ) from error
    if completed.returncode != 0:
        message = completed.stderr.strip() or completed.stdout.strip()
        if (
            allow_fail == NATIVE_FAILURE_ALREADY_ABSENT
            and _native_scheduler_failure_is_already_absent(args, completed)
        ):
            print(
                f"ignored already-absent scheduler command {' '.join(args)}: {message}"
            )
            return
        if allow_fail is True:
            print(f"ignored failed command {' '.join(args)}: {message}")
            return
        raise SyncError(message or f"command failed: {' '.join(args)}")


def _launchd_activation_failure(
    binding: SchedulerActivationBinding,
    boundary: str,
    failure: str,
) -> SyncError:
    return SyncError(
        f"{binding.description} {failure} {boundary}: {binding.path}",
        code=binding.failure_code,
    )


def _revalidate_launchd_activation_binding(
    binding: SchedulerActivationBinding,
    *,
    boundary: str,
) -> None:
    expected = binding.expected
    if expected.parent_identity is None:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "has incomplete activation evidence",
        )
    try:
        parent_identity = _directory_identity(binding.parent_fd)
    except (OSError, SyncError) as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "parent descriptor became unreadable",
        ) from error
    if parent_identity != expected.parent_identity or not _bound_directory_matches(
        binding.home,
        binding.path.parent,
        binding.parent_fd,
    ):
        raise _launchd_activation_failure(
            binding,
            boundary,
            "parent chain changed",
        )
    if not expected.exists:
        if any(
            value is not None
            for value in (
                expected.payload,
                expected.mode,
                expected.file_identity,
                expected.file_type,
                expected.size,
                expected.uid,
                expected.gid,
            )
        ):
            raise _launchd_activation_failure(
                binding,
                boundary,
                "has incomplete absence evidence",
            )
        try:
            os.stat(
                binding.path.name,
                dir_fd=binding.parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        except OSError as error:
            raise _launchd_activation_failure(
                binding,
                boundary,
                "absence is unreadable",
            ) from error
        else:
            raise _launchd_activation_failure(
                binding,
                boundary,
                (
                    "reappeared after conditional removal"
                    if binding.removed
                    else "appeared after initial absence"
                ),
            )
        try:
            final_parent_identity = _directory_identity(binding.parent_fd)
        except (OSError, SyncError) as error:
            raise _launchd_activation_failure(
                binding,
                boundary,
                "parent descriptor became unreadable",
            ) from error
        if (
            final_parent_identity != expected.parent_identity
            or not _bound_directory_matches(
                binding.home,
                binding.path.parent,
                binding.parent_fd,
            )
        ):
            raise _launchd_activation_failure(
                binding,
                boundary,
                "parent chain changed",
            )
        return
    if (
        not _managed_state_snapshot_has_complete_file_evidence(expected)
        or expected.file_type != stat.S_IFREG
        or expected.payload is None
        or expected.size is None
        or expected.mode is None
        or expected.uid is None
        or expected.gid is None
        or expected.file_identity is None
        or binding.file_fd < 0
    ):
        raise _launchd_activation_failure(
            binding,
            boundary,
            "has incomplete activation evidence",
        )
    try:
        named_before = os.stat(
            binding.path.name,
            dir_fd=binding.parent_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "is missing",
        ) from error
    except OSError as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "is unreadable",
        ) from error

    expected_identity = expected.file_identity
    expected_access = (
        expected.file_type,
        expected.mode,
        expected.uid,
    )

    def validate_metadata(metadata: os.stat_result) -> None:
        if (metadata.st_dev, metadata.st_ino) != expected_identity:
            raise _launchd_activation_failure(
                binding,
                boundary,
                "object identity changed",
            )
        if (
            stat.S_IFMT(metadata.st_mode),
            stat.S_IMODE(metadata.st_mode),
            metadata.st_uid,
        ) != expected_access:
            raise _launchd_activation_failure(
                binding,
                boundary,
                "access policy changed",
            )
        if not _gid_matches_regular_file_access_policy(
            metadata.st_gid,
            expected.gid,
            expected.mode,
        ):
            raise _launchd_activation_failure(
                binding,
                boundary,
                "access policy changed",
            )
        if metadata.st_size != expected.size:
            raise _launchd_activation_failure(
                binding,
                boundary,
                "content changed",
            )

    def validate_descriptor(metadata: os.stat_result) -> None:
        validate_metadata(metadata)
        # A retained descriptor prevents inode reuse while it remains open.
        # A zero link count therefore proves that the canonical entry stopped
        # naming this object. Other link-count churn is benign and is not used
        # as mutation evidence.
        if metadata.st_nlink == 0:
            raise _launchd_activation_failure(
                binding,
                boundary,
                "object identity changed",
            )

    validate_metadata(named_before)
    try:
        opened_metadata = os.fstat(binding.file_fd)
    except OSError as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "is unreadable",
        ) from error
    validate_descriptor(opened_metadata)
    try:
        os.lseek(binding.file_fd, 0, os.SEEK_SET)
        payload = _read_managed_state_bytes(
            binding.file_fd,
            binding.path,
            max(expected.size, 1),
        )
        os.lseek(binding.file_fd, 0, os.SEEK_SET)
        confirmed_payload = _read_managed_state_bytes(
            binding.file_fd,
            binding.path,
            max(expected.size, 1),
        )
    except SyncError as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "is unreadable",
        ) from error
    except OSError as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "is unreadable",
        ) from error
    if payload != expected.payload or confirmed_payload != expected.payload:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "content changed",
        )
    try:
        validate_descriptor(os.fstat(binding.file_fd))
        named_after = os.stat(
            binding.path.name,
            dir_fd=binding.parent_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "is missing",
        ) from error
    except OSError as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "is unreadable",
        ) from error
    validate_metadata(named_after)
    try:
        final_parent_identity = _directory_identity(binding.parent_fd)
    except (OSError, SyncError) as error:
        raise _launchd_activation_failure(
            binding,
            boundary,
            "parent descriptor became unreadable",
        ) from error
    if (
        final_parent_identity != expected.parent_identity
        or not _bound_directory_matches(
            binding.home,
            binding.path.parent,
            binding.parent_fd,
        )
    ):
        raise _launchd_activation_failure(
            binding,
            boundary,
            "parent chain changed",
        )


def _release_retained_scheduler_activation_binding(
    binding: SchedulerActivationBinding,
    *,
    revalidate: bool,
) -> None:
    try:
        if revalidate:
            _revalidate_launchd_activation_binding(
                binding,
                boundary="after activation",
            )
    finally:
        if binding.file_fd >= 0:
            _close_fd_quietly(binding.file_fd)
            binding.file_fd = -1
        if binding.parent_fd >= 0:
            _close_fd_quietly(binding.parent_fd)
            binding.parent_fd = -1


def _reopen_scheduler_activation_binding_readonly(
    binding: SchedulerActivationBinding,
) -> None:
    if binding.file_fd < 0:
        raise SyncError(
            f"{binding.description} descriptor is closed before lease acquisition"
        )
    old_fd = binding.file_fd
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    try:
        readonly_fd = os.open(f"/proc/self/fd/{old_fd}", flags)
    except OSError as error:
        raise SyncError(
            f"cannot reopen retained {binding.description} read-only"
        ) from error
    binding.file_fd = readonly_fd
    try:
        _revalidate_launchd_activation_binding(
            binding,
            boundary="while converting to a read-only activation lease",
        )
    except BaseException:
        binding.file_fd = old_fd
        _close_fd_quietly(readonly_fd)
        raise
    _close_fd_quietly(old_fd)


def _systemd_activation_directory_paths(
    paths: SchedulerPaths,
    drop_ins: tuple[SystemdDropInSnapshot, ...],
) -> tuple[Path, ...]:
    assert paths.systemd_service is not None
    assert paths.systemd_timer is not None
    user_home = Path.home().expanduser()
    unit_parent = paths.systemd_service.parent
    relative_parent = unit_parent.relative_to(user_home)
    selected: list[Path] = [user_home]
    current = user_home
    for part in relative_parent.parts:
        current /= part
        selected.append(current)
    for unit_path, snapshot in zip(
        (paths.systemd_service, paths.systemd_timer),
        drop_ins,
    ):
        if snapshot.exists:
            selected.append(unit_path.with_name(unit_path.name + ".d"))
    return tuple(dict.fromkeys(selected))


def _systemd_activation_generation_directory(
    home: Path,
    path: Path,
) -> SystemdActivationDirectoryGeneration:
    directory_fd = _open_directory_beneath(home, path)
    try:
        metadata = os.fstat(directory_fd)
        if not _bound_directory_matches(home, path, directory_fd):
            raise SyncError(
                f"systemd activation directory changed while binding: {path}"
            )
        return SystemdActivationDirectoryGeneration(
            path=path,
            fd=directory_fd,
            identity=(metadata.st_dev, metadata.st_ino),
            access_policy=(
                stat.S_IMODE(metadata.st_mode),
                metadata.st_uid,
                metadata.st_gid,
            ),
            ctime_ns=metadata.st_ctime_ns,
        )
    except BaseException:
        _close_fd_quietly(directory_fd)
        raise


def _revalidate_systemd_activation_stability_guard(
    guard: SystemdActivationStabilityGuard,
    *,
    boundary: str,
    compare_generation: bool,
) -> bool:
    # The protected properties are each canonical name's object identity,
    # exact bytes/access policy, and the audited drop-in state. Read leases
    # make a conflicting write-open or truncate fail closed. ctime is only a
    # command-interval generation signal: a delta never classifies mutation,
    # but makes that reload interval inconclusive and forces a fresh reload
    # after exact state is revalidated.
    if guard.lease_break_observed:
        raise SyncError(
            "systemd scheduler unit read lease received a conflicting writer "
            f"{boundary}"
        )
    stable = True
    for binding in guard.bindings:
        try:
            lease_state = fcntl.fcntl(binding.file_fd, fcntl.F_GETLEASE)
        except OSError as error:
            raise SyncError(
                f"{binding.description} read lease is unreadable {boundary}"
            ) from error
        if lease_state != fcntl.F_RDLCK:
            raise SyncError(f"{binding.description} read lease changed {boundary}")
        _revalidate_launchd_activation_binding(
            binding,
            boundary=boundary,
        )
        try:
            current_file_ctime = os.fstat(binding.file_fd).st_ctime_ns
        except OSError as error:
            raise SyncError(
                f"{binding.description} generation is unreadable {boundary}"
            ) from error
        if compare_generation and (
            current_file_ctime != guard.file_ctimes[binding.file_fd]
        ):
            stable = False
    paths = SchedulerPaths(
        platform="linux",
        systemd_service=guard.bindings[0].path,
        systemd_timer=guard.bindings[1].path,
    )
    _revalidate_systemd_drop_ins(paths, guard.drop_ins)
    for directory in guard.directories:
        try:
            metadata = os.fstat(directory.fd)
        except OSError as error:
            raise SyncError(
                "systemd activation directory became unreadable "
                f"{boundary}: {directory.path}"
            ) from error
        if (
            (metadata.st_dev, metadata.st_ino) != directory.identity
            or (
                stat.S_IMODE(metadata.st_mode),
                metadata.st_uid,
                metadata.st_gid,
            )
            != directory.access_policy
            or not _bound_directory_matches(
                guard.bindings[0].home,
                directory.path,
                directory.fd,
            )
        ):
            raise SyncError(
                "systemd activation directory identity/access changed "
                f"{boundary}: {directory.path}"
            )
        if compare_generation and metadata.st_ctime_ns != directory.ctime_ns:
            stable = False
    return stable


def _reset_systemd_activation_generation(
    guard: SystemdActivationStabilityGuard,
    *,
    boundary: str,
) -> None:
    _revalidate_systemd_activation_stability_guard(
        guard,
        boundary=boundary,
        compare_generation=False,
    )
    for binding in guard.bindings:
        try:
            guard.file_ctimes[binding.file_fd] = os.fstat(binding.file_fd).st_ctime_ns
        except OSError as error:
            raise SyncError(
                f"{binding.description} generation is unreadable {boundary}"
            ) from error
    for directory in guard.directories:
        try:
            directory.ctime_ns = os.fstat(directory.fd).st_ctime_ns
        except OSError as error:
            raise SyncError(
                "systemd activation directory generation is unreadable "
                f"{boundary}: {directory.path}"
            ) from error
    _revalidate_systemd_activation_stability_guard(
        guard,
        boundary=boundary,
        compare_generation=True,
    )


@contextlib.contextmanager
def _retain_systemd_activation_stability_guard(
    paths: SchedulerPaths,
    bindings: tuple[SchedulerActivationBinding, SchedulerActivationBinding],
    drop_ins: tuple[SystemdDropInSnapshot, ...],
) -> Iterator[SystemdActivationStabilityGuard | None]:
    # A real systemd user manager is Linux-only. Non-Linux test runs mock every
    # native action and retain the existing identity/content revalidation.
    if not sys.platform.startswith("linux"):
        yield None
        return
    assert paths.systemd_service is not None
    assert paths.systemd_timer is not None
    if (
        len(bindings) != 2
        or len(drop_ins) != 2
        or bindings[0].path != paths.systemd_service
        or bindings[1].path != paths.systemd_timer
        or bindings[0].home != bindings[1].home
    ):
        raise SyncError(
            "systemd activation stability guard requires the exact "
            "service/timer binding pair"
        )
    required_fcntl_names = (
        "F_SETOWN",
        "F_SETLEASE",
        "F_GETLEASE",
        "F_RDLCK",
        "F_UNLCK",
    )
    if any(not hasattr(fcntl, name) for name in required_fcntl_names):
        raise SyncError("Linux file leases are unavailable for systemd activation")
    directories: list[SystemdActivationDirectoryGeneration] = []
    leased: list[SchedulerActivationBinding] = []
    guard: SystemdActivationStabilityGuard | None = None
    prior_sigio_handler: Any = None
    try:
        for binding in bindings:
            _reopen_scheduler_activation_binding_readonly(binding)
        for path in _systemd_activation_directory_paths(paths, drop_ins):
            directories.append(
                _systemd_activation_generation_directory(
                    bindings[0].home,
                    path,
                )
            )
        guard = SystemdActivationStabilityGuard(
            bindings=bindings,
            drop_ins=drop_ins,
            directories=tuple(directories),
            file_ctimes={
                binding.file_fd: os.fstat(binding.file_fd).st_ctime_ns
                for binding in bindings
            },
        )

        def lease_break_handler(
            _signal_number: int,
            _frame: Any,
        ) -> None:
            assert guard is not None
            guard.lease_break_observed = True

        prior_sigio_handler = signal.getsignal(signal.SIGIO)
        signal.signal(signal.SIGIO, lease_break_handler)
        for binding in bindings:
            fcntl.fcntl(binding.file_fd, fcntl.F_SETOWN, os.getpid())
            try:
                fcntl.fcntl(binding.file_fd, fcntl.F_SETLEASE, fcntl.F_RDLCK)
            except OSError as error:
                raise SyncError(
                    f"cannot acquire read lease for {binding.description}: {error}"
                ) from error
            leased.append(binding)
        _reset_systemd_activation_generation(
            guard,
            boundary="before native systemd activation",
        )
        yield guard
    finally:
        for binding in reversed(leased):
            try:
                fcntl.fcntl(
                    binding.file_fd,
                    fcntl.F_SETLEASE,
                    fcntl.F_UNLCK,
                )
            except OSError:
                pass
        if prior_sigio_handler is not None:
            signal.signal(signal.SIGIO, prior_sigio_handler)
        for directory in reversed(directories):
            _close_fd_quietly(directory.fd)


def _reload_systemd_manager_with_stable_units(
    guard: SystemdActivationStabilityGuard | None,
    *,
    dry_run: bool,
    activation_bindings: tuple[SchedulerActivationBinding, ...],
) -> None:
    if dry_run or guard is None:
        _run_native_scheduler_action(
            ["systemctl", "--user", "daemon-reload"],
            dry_run=dry_run,
            activation_bindings=activation_bindings,
        )
        return
    for attempt in range(MAX_SYSTEMD_STABLE_RELOAD_ATTEMPTS):
        _reset_systemd_activation_generation(
            guard,
            boundary="before native action systemctl --user daemon-reload",
        )
        _run_native_scheduler_action(
            ["systemctl", "--user", "daemon-reload"],
            dry_run=False,
            activation_bindings=activation_bindings,
        )
        if _revalidate_systemd_activation_stability_guard(
            guard,
            boundary="after native action systemctl --user daemon-reload",
            compare_generation=True,
        ):
            return
        if attempt + 1 < MAX_SYSTEMD_STABLE_RELOAD_ATTEMPTS:
            print(
                "systemd unit namespace generation changed during daemon-reload; "
                "retrying before enable/start"
            )
    raise SyncError(
        "systemd unit namespace could not produce a stable daemon-reload "
        f"after {MAX_SYSTEMD_STABLE_RELOAD_ATTEMPTS} attempts"
    )


@contextlib.contextmanager
def _retain_launchd_activation_binding(
    path: Path,
    expected: ManagedStateFileSnapshot,
    *,
    description: str = "launchd scheduler config",
    failure_code: str | None = None,
    revalidate_on_exit: bool = True,
) -> Iterator[SchedulerActivationBinding]:
    user_home = Path.home().expanduser()
    try:
        path.relative_to(user_home)
    except ValueError as error:
        raise SyncError(
            f"{description} must remain beneath the user home: {path}",
            code=failure_code,
        ) from error
    parent_fd = -1
    file_fd = -1
    binding: SchedulerActivationBinding | None = None
    try:
        try:
            parent_fd = _open_directory_beneath(user_home, path.parent)
        except FileNotFoundError as error:
            raise SyncError(
                f"{description} parent chain is missing: {path.parent}",
                code=failure_code,
            ) from error
        except (OSError, SyncError) as error:
            raise SyncError(
                f"{description} parent chain is unreadable: {path.parent}",
                code=failure_code,
            ) from error
        if expected.exists:
            flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            flags |= getattr(os, "O_NONBLOCK", 0)
            try:
                file_fd = os.open(path.name, flags, dir_fd=parent_fd)
            except FileNotFoundError as error:
                raise SyncError(
                    f"{description} is missing before activation: {path}",
                    code=failure_code,
                ) from error
            except OSError as error:
                raise SyncError(
                    f"{description} is unreadable before activation: {path}",
                    code=failure_code,
                ) from error
        binding = SchedulerActivationBinding(
            home=user_home,
            path=path,
            parent_fd=parent_fd,
            file_fd=file_fd,
            expected=expected,
            description=description,
            failure_code=failure_code,
        )
        _revalidate_launchd_activation_binding(
            binding,
            boundary="before activation",
        )
        yield binding
        if revalidate_on_exit:
            _revalidate_launchd_activation_binding(
                binding,
                boundary="after activation",
            )
    finally:
        if binding is not None and binding.file_fd >= 0:
            _close_fd_quietly(binding.file_fd)
            binding.file_fd = -1
        elif file_fd >= 0:
            _close_fd_quietly(file_fd)
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)


@contextlib.contextmanager
def _retain_scheduler_config_audit_bindings(
    paths: SchedulerPaths,
    audit: SchedulerConfigAudit,
) -> Iterator[tuple[SchedulerActivationBinding, ...]]:
    if audit.config is None:
        yield ()
        return
    if len(audit.config.config_paths) != len(audit.snapshots):
        raise SyncError(
            "scheduler audit path/snapshot cardinality changed before status",
            code="scheduler-config-drift",
        )
    with contextlib.ExitStack() as stack:
        bindings: list[SchedulerActivationBinding] = []
        for path, snapshot in zip(audit.config.config_paths, audit.snapshots):
            if not snapshot.exists:
                raise SyncError(
                    f"audited scheduler config disappeared before status: {path}",
                    code="scheduler-config-drift",
                )
            bindings.append(
                stack.enter_context(
                    _retain_launchd_activation_binding(
                        path,
                        snapshot,
                        description="audited scheduler config",
                        failure_code="scheduler-config-drift",
                    )
                )
            )
        _revalidate_scheduler_status_audit(paths, audit)
        yield tuple(bindings)
        for binding in bindings:
            _revalidate_launchd_activation_binding(
                binding,
                boundary="after scheduler status audit",
            )
        _revalidate_scheduler_status_audit(paths, audit)


def _revalidate_scheduler_status_audit(
    paths: SchedulerPaths,
    audit: SchedulerConfigAudit,
) -> None:
    try:
        _revalidate_scheduler_config_audit(paths, audit)
    except SyncError as error:
        raise SyncError(
            f"scheduler configuration drifted during status: {error}",
            code="scheduler-config-drift",
        ) from error


def _run_native_scheduler_action(
    args: list[str],
    *,
    dry_run: bool,
    allow_fail: bool | str = False,
    activation_binding: SchedulerActivationBinding | None = None,
    activation_bindings: tuple[SchedulerActivationBinding, ...] = (),
) -> None:
    action = " ".join(args[:3])
    bindings = (
        (activation_binding,) + activation_bindings
        if activation_binding is not None
        else activation_bindings
    )
    if len({id(binding) for binding in bindings}) != len(bindings):
        raise SyncError("native scheduler action received duplicate file bindings")
    for binding in bindings:
        _revalidate_launchd_activation_binding(
            binding,
            boundary=f"before native action {action}",
        )
    try:
        _run_native_command(
            args,
            dry_run=dry_run,
            allow_fail=allow_fail,
        )
    finally:
        for binding in bindings:
            _revalidate_launchd_activation_binding(
                binding,
                boundary=f"after native action {action}",
            )


def _scheduler_daemon_enabled(
    paths: SchedulerPaths,
    *,
    config_audit: SchedulerConfigAudit | None = None,
    activation_bindings: tuple[SchedulerActivationBinding, ...] = (),
    activation_snapshot: ManagedStateFileSnapshot | None = None,
    uninstall_snapshot: ManagedStateFileSnapshot | None = None,
) -> SchedulerDaemonQuery:
    def revalidate(boundary: str) -> None:
        for binding in activation_bindings:
            _revalidate_launchd_activation_binding(
                binding,
                boundary=boundary,
            )
        if uninstall_snapshot is not None:
            current_uninstall = _scheduler_config_snapshot(
                _scheduler_uninstall_transaction_path(paths),
                MAX_SCHEDULER_UNINSTALL_TRANSACTION_BYTES,
            )
            if not _scheduler_file_snapshots_match(
                current_uninstall,
                uninstall_snapshot,
            ):
                raise SyncError(
                    "scheduler uninstall transaction changed during "
                    f"daemon query at {boundary}",
                    code="scheduler-uninstall-incomplete",
                )
        if activation_snapshot is not None:
            current_activation = _scheduler_config_snapshot(
                _scheduler_activation_transaction_path(paths),
                MAX_SCHEDULER_ACTIVATION_TRANSACTION_BYTES,
            )
            if not _scheduler_file_snapshots_match(
                current_activation,
                activation_snapshot,
            ):
                raise SyncError(
                    "scheduler activation transaction changed during "
                    f"daemon query at {boundary}",
                    code="scheduler-activation-incomplete",
                )
        if config_audit is not None:
            _revalidate_scheduler_status_audit(paths, config_audit)

    def run_query(
        args: list[str],
        *,
        description: str,
    ) -> subprocess.CompletedProcess[str] | SchedulerDaemonQuery:
        revalidate(f"before native scheduler {description}")
        try:
            try:
                native_args = _native_scheduler_argv(args)
                return _run_bounded_scheduler_process(
                    native_args,
                    timeout_seconds=SCHEDULER_NATIVE_QUERY_TIMEOUT_SECONDS,
                )
            except SyncError as error:
                if error.code == "scheduler-timeout":
                    return SchedulerDaemonQuery(
                        "unavailable",
                        f"scheduler daemon {description} timed out",
                    )
                if error.code == "scheduler-output-limit":
                    return SchedulerDaemonQuery(
                        "unavailable",
                        "scheduler daemon query output exceeded its byte limit",
                    )
                if error.code == "scheduler-cleanup-inconclusive":
                    return SchedulerDaemonQuery(
                        "unavailable",
                        f"scheduler daemon {description} cleanup was inconclusive",
                    )
                if error.code == "scheduler-command-unavailable":
                    return SchedulerDaemonQuery(
                        "unavailable",
                        f"scheduler daemon {description} executable is unavailable",
                    )
                return SchedulerDaemonQuery(
                    "unavailable",
                    f"scheduler daemon {description} could not be supervised",
                )
            except OSError:
                return SchedulerDaemonQuery(
                    "unavailable",
                    f"scheduler daemon {description} could not start",
                )
        finally:
            revalidate(f"after native scheduler {description}")

    def systemd_unavailable_reason(
        completed: subprocess.CompletedProcess[str],
        *,
        description: str,
    ) -> str:
        evidence = re.sub(
            r"\s+",
            " ",
            (completed.stdout + "\n" + completed.stderr).strip().casefold(),
        )
        if any(
            marker in evidence
            for marker in (
                "failed to connect to bus",
                "no medium found",
                "system has not been booted with systemd",
            )
        ):
            return "systemd user bus is unavailable"
        if any(
            marker in evidence
            for marker in (
                "operation not permitted",
                "permission denied",
                "access denied",
            )
        ):
            return f"systemd scheduler {description} was denied"
        return (
            f"systemd scheduler {description} returned no recognized "
            "daemon-state evidence"
        )

    if paths.platform == "macos":

        def classify_launchd_query(
            completed: subprocess.CompletedProcess[str],
            *,
            domain_kind: str,
            label: str,
        ) -> SchedulerDaemonQuery:
            raw_evidence = completed.stdout + "\n" + completed.stderr
            evidence = raw_evidence.strip().casefold()
            if any(
                marker in evidence
                for marker in (
                    "operation not permitted",
                    "permission denied",
                    "access denied",
                )
            ):
                return SchedulerDaemonQuery(
                    "unavailable",
                    f"launchd {domain_kind} domain query for {label} was denied",
                )
            if completed.stderr.strip() and completed.returncode == 0:
                return SchedulerDaemonQuery(
                    "unavailable",
                    f"launchd {domain_kind} domain query for {label} returned "
                    "contradictory error output",
                )
            if completed.returncode == 0:
                return SchedulerDaemonQuery("enabled")
            if (
                any(
                    re.fullmatch(pattern, evidence) is not None
                    for pattern in (
                        r"could not find specified service[.;]?",
                        r"could not find service in domain[.;]?",
                        r"service not found in domain[.;]?",
                    )
                )
                or _launchd_quoted_not_loaded_evidence(
                    raw_evidence,
                    label=label,
                    uid=str(os.getuid()),
                    domain_kind=domain_kind,
                )
                or (
                    domain_kind == MACOS_LEGACY_GUI_LAUNCHD_DOMAIN
                    and _launchd_gui_domain_unavailable_evidence(raw_evidence)
                )
            ):
                return SchedulerDaemonQuery(
                    "disabled",
                    f"launchd reports that scheduler service {label} is not "
                    f"loaded in the {domain_kind} domain",
                )
            return SchedulerDaemonQuery(
                "unavailable",
                f"launchd {domain_kind} domain query for {label} failed "
                "without explicit not-loaded evidence",
            )

        launchd_queries: dict[tuple[str, str], SchedulerDaemonQuery] = {}
        for label in (LAUNCHD_LABEL, *LEGACY_LAUNCHD_LABELS):
            for domain_kind in (
                MACOS_BACKGROUND_LAUNCHD_DOMAIN,
                MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
            ):
                completed = run_query(
                    [
                        "launchctl",
                        "print",
                        f"{_macos_launchd_domain(domain_kind)}/{label}",
                    ],
                    description=f"{domain_kind} domain query for {label}",
                )
                if isinstance(completed, SchedulerDaemonQuery):
                    launchd_queries[(label, domain_kind)] = completed
                else:
                    launchd_queries[(label, domain_kind)] = classify_launchd_query(
                        completed,
                        domain_kind=domain_kind,
                        label=label,
                    )

        unavailable = next(
            (
                query
                for query in launchd_queries.values()
                if query.classification == "unavailable"
            ),
            None,
        )
        if unavailable is not None:
            return unavailable
        domain_queries = {
            domain_kind: launchd_queries[(LAUNCHD_LABEL, domain_kind)]
            for domain_kind in (
                MACOS_BACKGROUND_LAUNCHD_DOMAIN,
                MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
            )
        }
        enabled_domains = tuple(
            domain_kind
            for domain_kind, query in domain_queries.items()
            if query.classification == "enabled"
        )
        loaded_legacy_services = tuple(
            (label, domain_kind)
            for label in LEGACY_LAUNCHD_LABELS
            for domain_kind in (
                MACOS_BACKGROUND_LAUNCHD_DOMAIN,
                MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
            )
            if launchd_queries[(label, domain_kind)].classification == "enabled"
        )
        if config_audit is not None and config_audit.config is None:
            loaded_orphans = (
                *((LAUNCHD_LABEL, domain_kind) for domain_kind in enabled_domains),
                *loaded_legacy_services,
            )
            if loaded_orphans:
                loaded = ", ".join(
                    f"{label} in the {domain_kind} domain"
                    for label, domain_kind in loaded_orphans
                )
                return SchedulerDaemonQuery(
                    "enabled",
                    f"launchd reports loaded scheduler orphans: {loaded}",
                )
        if loaded_legacy_services:
            loaded = ", ".join(
                f"{label} in the {domain_kind} domain"
                for label, domain_kind in loaded_legacy_services
            )
            return SchedulerDaemonQuery(
                "unavailable",
                f"launchd reports loaded legacy scheduler services: {loaded}",
            )
        if not enabled_domains:
            return SchedulerDaemonQuery(
                "disabled",
                "launchd reports that the scheduler service is not loaded in "
                "either the user or GUI domain",
            )
        if len(enabled_domains) != 1:
            return SchedulerDaemonQuery(
                "unavailable",
                "launchd reports duplicate scheduler services in the user and "
                "GUI domains",
            )
        loaded_domain = enabled_domains[0]
        configured_domain = (
            config_audit.config.launchd_domain
            if config_audit is not None and config_audit.config is not None
            else None
        )
        if configured_domain is not None and loaded_domain != configured_domain:
            return SchedulerDaemonQuery(
                "unavailable",
                f"launchd scheduler is loaded in the {loaded_domain} domain but "
                f"the audited configuration targets {configured_domain}",
            )
        return SchedulerDaemonQuery(
            "enabled",
            (
                "launchd scheduler is loaded in the legacy Background domain"
                if loaded_domain == MACOS_BACKGROUND_LAUNCHD_DOMAIN
                else None
            ),
        )

    if paths.platform != "linux":
        return SchedulerDaemonQuery(
            "unavailable",
            "scheduler daemon query is unsupported on this platform",
        )
    enabled_result = run_query(
        [
            "systemctl",
            "--user",
            "is-enabled",
            f"{SYSTEMD_UNIT}.timer",
        ],
        description="enablement query",
    )
    if isinstance(enabled_result, SchedulerDaemonQuery):
        return enabled_result
    active_result = run_query(
        [
            "systemctl",
            "--user",
            "is-active",
            f"{SYSTEMD_UNIT}.timer",
        ],
        description="activity query",
    )
    if isinstance(active_result, SchedulerDaemonQuery):
        return active_result
    if enabled_result.stderr.strip():
        return SchedulerDaemonQuery(
            "unavailable",
            systemd_unavailable_reason(
                enabled_result,
                description="enablement query",
            ),
        )
    if active_result.stderr.strip():
        return SchedulerDaemonQuery(
            "unavailable",
            systemd_unavailable_reason(
                active_result,
                description="activity query",
            ),
        )
    enabled_state = enabled_result.stdout.strip().casefold()
    active_state = active_result.stdout.strip().casefold()
    active_or_transitional_states = {
        "active",
        "activating",
        "deactivating",
        "maintenance",
        "reloading",
    }
    inactive_states = {
        "failed",
        "inactive",
        "not-found",
        "unknown",
    }
    if active_result.returncode == 0 and active_state in inactive_states:
        return SchedulerDaemonQuery(
            "unavailable",
            "systemd scheduler activity query returned contradictory "
            f"success state {active_state}",
        )
    if not (enabled_result.returncode == 0 and enabled_state == "enabled"):
        terminal_disabled_states = {
            "disabled",
            "masked",
            "masked-runtime",
            "not-found",
        }
        residual_enablement_states = {
            "alias",
            "disabled-runtime",
            "enabled-runtime",
            "generated",
            "indirect",
            "linked",
            "linked-runtime",
            "static",
            "transient",
        }
        if enabled_state in terminal_disabled_states | residual_enablement_states:
            if active_state in active_or_transitional_states:
                return SchedulerDaemonQuery(
                    "active-disabled",
                    "systemd reports that the scheduler timer has "
                    f"activity state {active_state} despite unit state "
                    f"{enabled_state}",
                )
            if active_state not in inactive_states:
                return SchedulerDaemonQuery(
                    "unavailable",
                    systemd_unavailable_reason(
                        active_result,
                        description="activity query",
                    ),
                )
            if enabled_state in residual_enablement_states:
                return SchedulerDaemonQuery(
                    "enabled-inactive",
                    "systemd scheduler retains non-terminal unit state "
                    f"{enabled_state} while activity state is {active_state}",
                )
            return SchedulerDaemonQuery(
                "disabled",
                f"systemd reports scheduler unit state {enabled_state}",
            )
        return SchedulerDaemonQuery(
            "unavailable",
            systemd_unavailable_reason(
                enabled_result,
                description="enablement query",
            ),
        )
    if active_result.returncode == 0 and active_state == "active":
        return SchedulerDaemonQuery("enabled")
    if active_state in active_or_transitional_states | inactive_states:
        return SchedulerDaemonQuery(
            "enabled-inactive",
            f"systemd scheduler timer is enabled but not active (state {active_state})",
        )
    return SchedulerDaemonQuery(
        "unavailable",
        systemd_unavailable_reason(
            active_result,
            description="activity query",
        ),
    )


def _scheduler_config_snapshot_at(
    user_home: Path,
    path: Path,
    parent_fd: int,
    maximum_bytes: int = 1024 * 1024,
) -> ManagedStateFileSnapshot:
    try:
        path.relative_to(user_home)
    except ValueError as error:
        raise SyncError(
            f"scheduler config must remain beneath the user home: {path}"
        ) from error
    snapshot = _read_managed_state_file_snapshot(
        user_home,
        path,
        parent_fd,
        maximum_bytes=maximum_bytes,
    )
    if not snapshot.exists:
        return snapshot
    if (
        not _managed_state_snapshot_has_complete_file_evidence(snapshot)
        or snapshot.file_type != stat.S_IFREG
        or snapshot.uid != os.geteuid()
        or snapshot.mode is None
        or snapshot.mode & 0o022
        or snapshot.payload is None
        or len(snapshot.payload) > maximum_bytes
    ):
        raise SyncError(
            f"scheduler config must be a bounded user-owned regular file: {path}"
        )
    return snapshot


def _scheduler_config_snapshot(
    path: Path,
    maximum_bytes: int = 1024 * 1024,
) -> ManagedStateFileSnapshot:
    user_home = Path.home().expanduser()
    try:
        path.relative_to(user_home)
    except ValueError as error:
        raise SyncError(
            f"scheduler config must remain beneath the user home: {path}"
        ) from error
    try:
        parent_fd = _open_directory_beneath(user_home, path.parent)
    except FileNotFoundError:
        return ManagedStateFileSnapshot(exists=False)
    try:
        return _scheduler_config_snapshot_at(
            user_home,
            path,
            parent_fd,
            maximum_bytes,
        )
    finally:
        _close_fd_quietly(parent_fd)


def _scheduler_file_snapshots_match(
    actual: ManagedStateFileSnapshot,
    expected: ManagedStateFileSnapshot,
) -> bool:
    if not actual.exists or not expected.exists:
        return (
            not actual.exists
            and not expected.exists
            and (
                expected.parent_identity is None
                or actual.parent_identity == expected.parent_identity
            )
        )
    return (
        actual.parent_identity == expected.parent_identity
        and _managed_state_snapshot_matches_file_evidence(actual, expected)
    )


def _revalidate_published_systemd_pair(
    paths: SchedulerPaths,
    expected: tuple[ManagedStateFileSnapshot, ManagedStateFileSnapshot],
    retained: tuple[SchedulerActivationBinding, SchedulerActivationBinding],
) -> None:
    assert paths.systemd_service is not None
    assert paths.systemd_timer is not None
    service_path = paths.systemd_service
    timer_path = paths.systemd_timer
    if service_path.parent != timer_path.parent:
        raise SyncError(
            "published systemd scheduler service/timer pair changed "
            "before daemon activation"
        )
    user_home = Path.home().expanduser()
    parent_fd = -1
    opened: list[
        tuple[
            Path,
            int,
            ManagedStateFileSnapshot,
            os.stat_result,
        ]
    ] = []
    try:
        for path, bound, binding in zip(
            (service_path, timer_path),
            expected,
            retained,
        ):
            if binding.path != path or binding.expected != bound:
                raise SyncError(
                    "published systemd scheduler service/timer pair changed "
                    "before daemon activation"
                )
            _revalidate_launchd_activation_binding(
                binding,
                boundary="during published systemd pair revalidation",
            )
        parent_fd = _open_directory_beneath(user_home, service_path.parent)
        parent_identity = _directory_identity(parent_fd)
        if not _bound_directory_matches(
            user_home,
            service_path.parent,
            parent_fd,
        ) or any(
            not _managed_state_snapshot_has_complete_file_evidence(bound)
            or bound.parent_identity != parent_identity
            for bound in expected
        ):
            raise SyncError(
                "published systemd scheduler service/timer pair changed "
                "before daemon activation"
            )
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        flags |= getattr(os, "O_NONBLOCK", 0)
        for path, bound in zip((service_path, timer_path), expected):
            named = os.stat(
                path.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            file_fd = os.open(path.name, flags, dir_fd=parent_fd)
            opened_metadata = os.fstat(file_fd)
            if not _regular_stat_matches_managed_state_file_snapshot(
                named, bound
            ) or not _regular_stat_metadata_matches(opened_metadata, named):
                _close_fd_quietly(file_fd)
                raise SyncError(
                    "published systemd scheduler service/timer pair changed "
                    "before daemon activation"
                )
            opened.append((path, file_fd, bound, named))
            payload = _read_managed_state_bytes(
                file_fd,
                path,
                max(bound.size or 0, 1),
            )
            if payload != bound.payload:
                raise SyncError(
                    "published systemd scheduler service/timer pair changed "
                    "before daemon activation"
                )
        for path, file_fd, bound, baseline_metadata in opened:
            os.lseek(file_fd, 0, os.SEEK_SET)
            confirmed_payload = _read_managed_state_bytes(
                file_fd,
                path,
                max(bound.size or 0, 1),
            )
            if confirmed_payload != bound.payload or not _regular_stat_metadata_matches(
                os.fstat(file_fd),
                baseline_metadata,
            ):
                raise SyncError(
                    "published systemd scheduler service/timer pair changed "
                    "before daemon activation"
                )
        # Both descriptors have now been reread. Revalidate both canonical
        # names only after that shared read phase, then recheck both
        # descriptors once more before accepting the pair.
        for path, file_fd, _bound, baseline_metadata in opened:
            named = os.stat(
                path.name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if not _regular_stat_metadata_matches(
                named, baseline_metadata
            ) or not _regular_stat_metadata_matches(
                os.fstat(file_fd),
                baseline_metadata,
            ):
                raise SyncError(
                    "published systemd scheduler service/timer pair changed "
                    "before daemon activation"
                )
        if _directory_identity(
            parent_fd
        ) != parent_identity or not _bound_directory_matches(
            user_home,
            service_path.parent,
            parent_fd,
        ):
            raise SyncError(
                "published systemd scheduler service/timer pair changed "
                "before daemon activation"
            )
        for binding in retained:
            _revalidate_launchd_activation_binding(
                binding,
                boundary="during published systemd pair revalidation",
            )
    except (FileNotFoundError, OSError, SyncError) as error:
        if isinstance(error, SyncError) and str(error).startswith(
            "published systemd scheduler service/timer pair changed"
        ):
            raise
        raise SyncError(
            "published systemd scheduler service/timer pair changed "
            "before daemon activation"
        ) from error
    finally:
        for _path, file_fd, _bound, _metadata in opened:
            _close_fd_quietly(file_fd)
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)


def _scheduler_file_logical_state_matches(
    actual: ManagedStateFileSnapshot,
    expected: ManagedStateFileSnapshot,
) -> bool:
    """Compare scheduler content and access policy, not replaceable inode identity."""
    if not actual.exists or not expected.exists:
        return not actual.exists and not expected.exists
    return (
        actual.payload == expected.payload
        and actual.mode == expected.mode
        and actual.file_type == expected.file_type
        and actual.size == expected.size
        and actual.uid == expected.uid
        and _gid_matches_regular_file_access_policy(
            actual.gid,
            expected.gid,
            expected.mode,
        )
    )


def _open_scheduler_recovery_binding(
    path: Path,
    parent_fd: int,
    expected: ManagedStateFileSnapshot,
) -> int:
    if not _managed_state_snapshot_has_complete_file_evidence(expected):
        raise SyncError(f"scheduler recovery evidence is incomplete: {path}")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    file_fd = -1
    try:
        named = os.stat(
            path.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        file_fd = os.open(path.name, flags, dir_fd=parent_fd)
        opened = os.fstat(file_fd)
        if not _regular_stat_matches_managed_state_file_snapshot(
            named, expected
        ) or not _regular_stat_metadata_matches(opened, named):
            raise SyncError(f"scheduler recovery evidence changed: {path}")
        payload = _read_managed_state_bytes(
            file_fd,
            path,
            max(expected.size or 0, 1),
        )
        os.lseek(file_fd, 0, os.SEEK_SET)
        confirmed_payload = _read_managed_state_bytes(
            file_fd,
            path,
            max(expected.size or 0, 1),
        )
        if (
            payload != expected.payload
            or confirmed_payload != expected.payload
            or not _regular_stat_metadata_matches(os.fstat(file_fd), named)
        ):
            raise SyncError(f"scheduler recovery evidence changed: {path}")
        return file_fd
    except BaseException:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)
        raise


def _scheduler_recovery_binding_matches(
    home: Path,
    file_fd: int,
    path: Path,
    parent_fd: int,
    expected: ManagedStateFileSnapshot,
) -> bool:
    if (
        file_fd < 0
        or not _managed_state_snapshot_has_complete_file_evidence(expected)
        or expected.parent_identity is None
    ):
        return False
    try:
        if expected.parent_identity != _directory_identity(
            parent_fd
        ) or not _bound_directory_matches(home, path.parent, parent_fd):
            return False
        named_before = os.stat(
            path.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if not _regular_stat_matches_managed_state_file_snapshot(
            named_before,
            expected,
        ):
            return False
        if not _regular_stat_metadata_matches(os.fstat(file_fd), named_before):
            return False
        os.lseek(file_fd, 0, os.SEEK_SET)
        payload = _read_managed_state_bytes(
            file_fd,
            path,
            max(expected.size or 0, 1),
        )
        os.lseek(file_fd, 0, os.SEEK_SET)
        confirmed_payload = _read_managed_state_bytes(
            file_fd,
            path,
            max(expected.size or 0, 1),
        )
        named_after = os.stat(
            path.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        return (
            payload == expected.payload
            and confirmed_payload == expected.payload
            and _regular_stat_metadata_matches(os.fstat(file_fd), named_before)
            and _regular_stat_metadata_matches(named_after, named_before)
            and expected.parent_identity == _directory_identity(parent_fd)
            and _bound_directory_matches(home, path.parent, parent_fd)
        )
    except (OSError, SyncError):
        return False


def _scheduler_runtime_publication_marker_path(path: Path) -> Path:
    return path.with_name(SCHEDULER_STATUS_PUBLICATION_MARKER_NAME)


def _scheduler_runtime_publication_marker_payload(
    path: Path,
    temporary_name: str,
    staged: ManagedStateFileSnapshot,
    before: ManagedStateFileSnapshot,
    recovery_name: str | None,
) -> bytes:
    if (
        not _managed_state_snapshot_has_complete_file_evidence(staged)
        or staged.parent_identity is None
    ):
        raise SyncError(
            f"scheduler runtime staged publication evidence is incomplete: {path}"
        )
    return _bounded_json_document(
        {
            "version": 1,
            "target": path.name,
            "temporary": temporary_name,
            "recovery": recovery_name,
            "parent_identity": list(staged.parent_identity),
            "staged_identity": list(staged.file_identity),
            "staged_sha256": hashlib.sha256(staged.payload).hexdigest(),
            "expected_live_identity": (
                list(before.file_identity) if before.file_identity is not None else None
            ),
        },
        max_bytes=MAX_SCHEDULER_STATUS_BYTES,
        overflow_error="scheduler runtime publication marker exceeds the size limit",
    )


def _create_scheduler_runtime_publication_marker(
    user_home: Path,
    path: Path,
    parent_fd: int,
    payload: bytes,
) -> ManagedStateFileSnapshot:
    marker_path = _scheduler_runtime_publication_marker_path(path)
    if not _bound_directory_matches(user_home, path.parent, parent_fd):
        raise SyncError(
            f"scheduler runtime state parent changed before publication: {path}"
        )
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    flags |= getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    marker_fd = -1
    try:
        try:
            marker_fd = os.open(
                marker_path.name,
                flags,
                0o600,
                dir_fd=parent_fd,
            )
        except FileExistsError as error:
            raise SyncError(
                "scheduler runtime state has an unresolved publication marker: "
                f"{marker_path}",
                code="scheduler-state-publication-incomplete",
            ) from error
        os.fchmod(marker_fd, 0o600)
        with os.fdopen(marker_fd, "wb", closefd=True) as stream:
            marker_fd = -1
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        os.fsync(parent_fd)
        marker = _read_managed_state_file_snapshot(
            user_home,
            marker_path,
            parent_fd,
            maximum_bytes=MAX_SCHEDULER_STATUS_BYTES,
        )
        if (
            marker.payload != payload
            or marker.mode != 0o600
            or marker.file_type != stat.S_IFREG
            or marker.uid != os.geteuid()
            or not _bound_directory_matches(user_home, path.parent, parent_fd)
        ):
            raise SyncError(
                f"scheduler runtime publication marker changed: {marker_path}"
            )
        return marker
    except OSError as error:
        raise SyncError(
            f"failed to publish scheduler runtime marker {marker_path}: {error}"
        ) from error
    finally:
        if marker_fd >= 0:
            _close_fd_quietly(marker_fd)


def _ensure_scheduler_runtime_publication_is_blocked(
    user_home: Path,
    path: Path,
    parent_fd: int,
    payload: bytes,
    expected: ManagedStateFileSnapshot | None,
) -> ManagedStateFileSnapshot | None:
    marker_path = _scheduler_runtime_publication_marker_path(path)
    if not _bound_directory_matches(user_home, path.parent, parent_fd):
        raise SyncError(
            f"scheduler runtime state parent changed after publication: {path}"
        )
    marker_identity = _named_entry_identity(parent_fd, marker_path.name)
    if marker_identity is None:
        return _create_scheduler_runtime_publication_marker(
            user_home,
            path,
            parent_fd,
            payload,
        )
    if expected is not None and marker_identity == expected.file_identity:
        try:
            current = _read_managed_state_file_snapshot(
                user_home,
                marker_path,
                parent_fd,
                expected_identity=expected.file_identity,
                maximum_bytes=MAX_SCHEDULER_STATUS_BYTES,
            )
        except SyncError:
            current = None
        if current is not None and _scheduler_file_snapshots_match(
            current,
            expected,
        ):
            return current
    # Any retained foreign entry still makes the reader fail closed. Persist
    # the directory entry and leave it untouched rather than deleting or
    # replacing untrusted evidence.
    os.fsync(parent_fd)
    if not _bound_directory_matches(user_home, path.parent, parent_fd):
        raise SyncError(
            f"scheduler runtime state parent changed after publication: {path}"
        )
    return None


def _commit_scheduler_runtime_publication_marker(
    user_home: Path,
    path: Path,
    parent_fd: int,
    expected: ManagedStateFileSnapshot,
) -> None:
    marker_path = _scheduler_runtime_publication_marker_path(path)
    current = _read_managed_state_file_snapshot(
        user_home,
        marker_path,
        parent_fd,
        expected_identity=expected.file_identity,
        maximum_bytes=MAX_SCHEDULER_STATUS_BYTES,
    )
    if not _scheduler_file_snapshots_match(
        current, expected
    ) or not _bound_directory_matches(user_home, path.parent, parent_fd):
        raise SyncError(f"scheduler runtime publication marker changed: {marker_path}")
    # Persist every prior live/preimage validation while the blocking marker
    # is still canonical. A successful unlink is the publication commit point;
    # no fallible validation or cleanup may follow it.
    os.fsync(parent_fd)
    os.unlink(marker_path.name, dir_fd=parent_fd)


def _atomic_write_scheduler_config(
    path: Path,
    payload: bytes,
    *,
    expected_snapshot: ManagedStateFileSnapshot | None = None,
    mode: int = 0o600,
    gid: int | None = None,
    rollback_displaced_conflict: bool = False,
    retain_activation_description: str | None = None,
) -> (
    ManagedStateFileSnapshot
    | tuple[ManagedStateFileSnapshot, SchedulerActivationBinding]
):
    if mode & 0o022 or mode < 0 or mode > 0o7777:
        raise SyncError(f"scheduler config mode is unsafe: {mode:#o}")
    if gid is not None and (type(gid) is not int or gid < 0):
        raise SyncError(f"scheduler config group is invalid: {gid!r}")
    user_home = Path.home().expanduser()
    try:
        path.relative_to(user_home)
    except ValueError as error:
        raise SyncError(
            f"scheduler config must remain beneath the user home: {path}"
        ) from error
    parent_fd = _open_or_create_directory_beneath(
        user_home,
        path.parent,
        mode=0o755,
    )
    temporary_name = (
        f".{path.name}.personal-sync-write-"
        f"{os.getpid()}-{time.time_ns()}-{os.urandom(8).hex()}"
    )
    file_fd = -1
    published = False
    retained_old = False
    recovery_name: str | None = None
    recovery_fd = -1
    preserve_recovery = False
    exchanged = False
    publication_attempted = False
    publication_marker: ManagedStateFileSnapshot | None = None
    publication_marker_payload: bytes | None = None
    publication_committed = False
    installed: ManagedStateFileSnapshot | None = None
    try:
        before = _read_managed_state_file_snapshot(
            user_home,
            path,
            parent_fd,
        )
        if expected_snapshot is not None and not _scheduler_file_snapshots_match(
            before,
            expected_snapshot,
        ):
            raise SyncError(
                f"scheduler config changed before conditional publication: {path}"
            )
        flags = os.O_RDWR if retain_activation_description is not None else os.O_WRONLY
        flags |= os.O_CREAT | os.O_EXCL
        flags |= getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        file_fd = os.open(
            temporary_name,
            flags,
            mode,
            dir_fd=parent_fd,
        )
        staged_gid = os.fstat(file_fd).st_gid
        if gid is not None and staged_gid != gid:
            try:
                caller_groups = {os.getegid(), *os.getgroups()}
            except OSError as error:
                raise SyncError(
                    f"cannot verify scheduler config group before publication: "
                    f"{path}: {error}"
                ) from error
            if gid not in caller_groups:
                raise SyncError(
                    f"cannot restore scheduler config group before publication: "
                    f"{path}: gid {gid} is not assigned to the caller"
                )
            try:
                os.fchown(file_fd, -1, gid)
            except OSError as error:
                raise SyncError(
                    f"cannot restore scheduler config group before publication: "
                    f"{path}: {error}"
                ) from error
        # fchown may clear special mode bits. Apply the complete recorded mode
        # afterward so recovery restores the selected access policy exactly.
        os.fchmod(file_fd, mode)
        stream_fd = (
            os.dup(file_fd) if retain_activation_description is not None else file_fd
        )
        try:
            stream = os.fdopen(stream_fd, "wb", closefd=True)
        except BaseException:
            if stream_fd != file_fd:
                _close_fd_quietly(stream_fd)
            raise
        if stream_fd == file_fd:
            file_fd = -1
        with stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        os.fsync(parent_fd)
        temporary_path = path.with_name(temporary_name)
        staged = _read_managed_state_file_snapshot(
            user_home,
            temporary_path,
            parent_fd,
        )
        if (
            staged.payload != payload
            or staged.mode != mode
            or (gid is not None and staged.gid != gid)
        ):
            raise SyncError(f"scheduler config staging failed: {path}")
        if before.exists:
            assert before.file_identity is not None
            recovery_name = f"{temporary_name}.original"
            try:
                os.link(
                    path.name,
                    recovery_name,
                    src_dir_fd=parent_fd,
                    dst_dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except OSError as error:
                raise SyncError(
                    f"cannot preserve scheduler config recovery evidence: "
                    f"{path}: {error}"
                ) from error
            # The link becomes the only independently named recovery evidence
            # as soon as link(2) succeeds. Preserve it on every later fsync or
            # binding failure, even before durability can be proved.
            preserve_recovery = True
            os.fsync(parent_fd)
            recovery_path = path.with_name(recovery_name)
            recovery = _read_managed_state_file_snapshot(
                user_home,
                recovery_path,
                parent_fd,
                expected_identity=before.file_identity,
            )
            recovery_fd = _open_scheduler_recovery_binding(
                recovery_path,
                parent_fd,
                before,
            )
            current_before = _read_managed_state_file_snapshot(
                user_home,
                path,
                parent_fd,
                expected_identity=before.file_identity,
            )
            if (
                not _managed_state_snapshot_matches_file_evidence(
                    recovery,
                    before,
                )
                or not _managed_state_snapshot_matches_file_evidence(
                    current_before,
                    before,
                )
                or not _scheduler_recovery_binding_matches(
                    user_home,
                    recovery_fd,
                    recovery_path,
                    parent_fd,
                    before,
                )
            ):
                preserve_recovery = True
                raise SyncError(
                    f"scheduler config changed while preserving recovery "
                    f"evidence: {path}"
                )
            if rollback_displaced_conflict:
                publication_marker_payload = (
                    _scheduler_runtime_publication_marker_payload(
                        path,
                        temporary_name,
                        staged,
                        before,
                        recovery_name,
                    )
                )
                publication_marker = _create_scheduler_runtime_publication_marker(
                    user_home,
                    path,
                    parent_fd,
                    publication_marker_payload,
                )
            publication_attempted = True
            _rename_exchange_at(
                parent_fd,
                temporary_name,
                parent_fd,
                path.name,
            )
            exchanged = True
            retained_old = True
            os.fsync(parent_fd)
            try:
                displaced = _read_managed_state_file_snapshot(
                    user_home,
                    temporary_path,
                    parent_fd,
                )
            except SyncError:
                displaced = None
            if displaced is None or not _managed_state_snapshot_matches_file_evidence(
                displaced,
                before,
            ):
                preserve_recovery = True
                if publication_marker_payload is not None:
                    retained_marker = _ensure_scheduler_runtime_publication_is_blocked(
                        user_home,
                        path,
                        parent_fd,
                        publication_marker_payload,
                        publication_marker,
                    )
                    if retained_marker is not None:
                        publication_marker = retained_marker
                installed_after_mismatch = _read_managed_state_file_snapshot(
                    user_home,
                    path,
                    parent_fd,
                    expected_identity=staged.file_identity,
                )
                recovery = _read_managed_state_file_snapshot(
                    user_home,
                    recovery_path,
                    parent_fd,
                    expected_identity=before.file_identity,
                )
                if (
                    not _managed_state_snapshot_matches_file_evidence(
                        installed_after_mismatch,
                        staged,
                    )
                    or not _managed_state_snapshot_matches_file_evidence(
                        recovery,
                        before,
                    )
                    or not _scheduler_recovery_binding_matches(
                        user_home,
                        recovery_fd,
                        recovery_path,
                        parent_fd,
                        before,
                    )
                    or not _bound_directory_matches(
                        user_home,
                        path.parent,
                        parent_fd,
                    )
                ):
                    preserve_recovery = True
                    raise SyncError(
                        f"scheduler config and recovery evidence changed during "
                        f"publication: {path}"
                    )
                published = True
                retained_old = False
                if rollback_displaced_conflict:
                    raise SyncError(
                        "conditional scheduler publication could not prove that "
                        "the temporary object is the exact state displaced from "
                        f"the live path; it was not exchanged back into {path}. "
                        f"The descriptor-bound recovery evidence is retained as "
                        f"{recovery_path} and the untrusted displaced locator as "
                        f"{temporary_path}"
                    )
                raise SyncError(
                    f"scheduler config displaced path changed during "
                    f"publication; the trusted staged config remains live and "
                    f"the exact original is preserved as {recovery_path}"
                )
        else:
            if rollback_displaced_conflict:
                publication_marker_payload = (
                    _scheduler_runtime_publication_marker_payload(
                        path,
                        temporary_name,
                        staged,
                        before,
                        recovery_name,
                    )
                )
                publication_marker = _create_scheduler_runtime_publication_marker(
                    user_home,
                    path,
                    parent_fd,
                    publication_marker_payload,
                )
            publication_attempted = True
            _rename_noreplace_at(
                parent_fd,
                temporary_name,
                parent_fd,
                path.name,
            )
        published = True
        os.fsync(parent_fd)
        installed = _read_managed_state_file_snapshot(
            user_home,
            path,
            parent_fd,
            expected_identity=staged.file_identity,
        )
        if (
            installed.payload != payload
            or installed.mode != mode
            or not _managed_state_snapshot_matches_file_evidence(
                installed,
                staged,
            )
            or not _bound_directory_matches(user_home, path.parent, parent_fd)
        ):
            raise SyncError(f"scheduler config changed during publication: {path}")
        if retained_old:
            if recovery_name is None:
                raise SyncError(f"scheduler config recovery locator is missing: {path}")
            recovery_path = path.with_name(recovery_name)
            recovery = _read_managed_state_file_snapshot(
                user_home,
                recovery_path,
                parent_fd,
                expected_identity=before.file_identity,
            )
            if not _managed_state_snapshot_matches_file_evidence(
                recovery,
                before,
            ) or not _scheduler_recovery_binding_matches(
                user_home,
                recovery_fd,
                recovery_path,
                parent_fd,
                before,
            ):
                preserve_recovery = True
                raise SyncError(
                    f"scheduler config recovery evidence changed after "
                    f"publication: {path}"
                )
            old_snapshot = _read_managed_state_file_snapshot(
                user_home,
                temporary_path,
                parent_fd,
                expected_identity=before.file_identity,
            )
            if not _managed_state_snapshot_matches_file_evidence(
                old_snapshot,
                before,
            ):
                raise SyncError(
                    f"scheduler config backup changed after publication: {path}"
                )
            # Remove the auxiliary recovery link while the exchanged preimage
            # remains a separately proven durable locator. Only after that
            # locator is revalidated may the final backup be deleted.
            _isolate_and_delete_pending_cleanup_file(
                user_home,
                recovery_path,
                parent_fd,
                recovery,
                label=f"scheduler config recovery evidence {path}",
            )
            recovery_name = None
            old_snapshot = _read_managed_state_file_snapshot(
                user_home,
                temporary_path,
                parent_fd,
                expected_identity=before.file_identity,
            )
            if not _managed_state_snapshot_matches_file_evidence(
                old_snapshot,
                before,
            ) or not _bound_directory_matches(
                user_home,
                path.parent,
                parent_fd,
            ):
                raise SyncError(
                    f"scheduler config backup changed while removing recovery "
                    f"evidence: {path}"
                )
            _isolate_and_delete_pending_cleanup_file(
                user_home,
                temporary_path,
                parent_fd,
                old_snapshot,
                label=f"scheduler config backup {path}",
            )
            retained_old = False
        installed = _read_managed_state_file_snapshot(
            user_home,
            path,
            parent_fd,
            expected_identity=staged.file_identity,
        )
        if (
            installed.payload != payload
            or installed.mode != mode
            or not _managed_state_snapshot_matches_file_evidence(
                installed,
                staged,
            )
            or not _bound_directory_matches(user_home, path.parent, parent_fd)
        ):
            raise SyncError(
                f"scheduler config changed after publication cleanup: {path}"
            )
        retained_binding: SchedulerActivationBinding | None = None
        result: (
            ManagedStateFileSnapshot
            | tuple[ManagedStateFileSnapshot, SchedulerActivationBinding]
        ) = installed
        if retain_activation_description is not None:
            if file_fd < 0:
                raise SyncError(
                    f"scheduler config publication descriptor is missing: {path}"
                )
            retained_binding = SchedulerActivationBinding(
                home=user_home,
                path=path,
                parent_fd=parent_fd,
                file_fd=file_fd,
                expected=installed,
                description=retain_activation_description,
            )
            _revalidate_launchd_activation_binding(
                retained_binding,
                boundary="after publication",
            )
            result = (installed, retained_binding)
        if publication_marker is not None:
            _commit_scheduler_runtime_publication_marker(
                user_home,
                path,
                parent_fd,
                publication_marker,
            )
            # unlink(2) returning successfully is the commit linearization
            # point. Nothing below this assignment may fail.
            publication_committed = True
            publication_marker = None
            if retained_binding is not None:
                parent_fd = -1
                file_fd = -1
            return result
        publication_committed = True
        if retained_binding is not None:
            parent_fd = -1
            file_fd = -1
        return result
    except OSError as error:
        raise SyncError(
            f"failed to publish scheduler config {path}: {error}"
        ) from error
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)
        if recovery_fd >= 0:
            _close_fd_quietly(recovery_fd)
        if not published and not retained_old:
            try:
                staged_cleanup = _read_managed_state_file_snapshot(
                    user_home,
                    path.with_name(temporary_name),
                    parent_fd,
                )
                if staged_cleanup.exists:
                    _isolate_and_delete_pending_cleanup_file(
                        user_home,
                        path.with_name(temporary_name),
                        parent_fd,
                        staged_cleanup,
                        label=f"scheduler config staging file {path}",
                    )
            except (OSError, SyncError):
                pass
        if recovery_name is not None and not preserve_recovery and not exchanged:
            try:
                recovery_path = path.with_name(recovery_name)
                recovery_cleanup = _read_managed_state_file_snapshot(
                    user_home,
                    recovery_path,
                    parent_fd,
                    expected_identity=before.file_identity,
                )
                if _managed_state_snapshot_matches_file_evidence(
                    recovery_cleanup,
                    before,
                ):
                    _isolate_and_delete_pending_cleanup_file(
                        user_home,
                        recovery_path,
                        parent_fd,
                        recovery_cleanup,
                        label=f"scheduler config recovery evidence {path}",
                    )
            except (OSError, SyncError):
                pass
        if (
            publication_attempted
            and not publication_committed
            and publication_marker_payload is not None
        ):
            try:
                _ensure_scheduler_runtime_publication_is_blocked(
                    user_home,
                    path,
                    parent_fd,
                    publication_marker_payload,
                    publication_marker,
                )
            except (OSError, SyncError):
                pass
        elif publication_marker is not None and not publication_attempted:
            try:
                marker_path = _scheduler_runtime_publication_marker_path(path)
                marker_cleanup = _read_managed_state_file_snapshot(
                    user_home,
                    marker_path,
                    parent_fd,
                    expected_identity=publication_marker.file_identity,
                    maximum_bytes=MAX_SCHEDULER_STATUS_BYTES,
                )
                if _scheduler_file_snapshots_match(
                    marker_cleanup,
                    publication_marker,
                ):
                    _isolate_and_delete_pending_cleanup_file(
                        user_home,
                        marker_path,
                        parent_fd,
                        marker_cleanup,
                        label=f"scheduler runtime publication marker {path}",
                    )
            except (OSError, SyncError):
                pass
        _close_fd_quietly(parent_fd)


def _write_text(
    path: Path,
    content: str,
    *,
    dry_run: bool,
    expected_snapshot: ManagedStateFileSnapshot | None = None,
) -> ManagedStateFileSnapshot | None:
    if dry_run:
        print(f"would write {path}")
        print(content.rstrip())
        return None
    return _atomic_write_scheduler_config(
        path,
        content.encode("utf-8"),
        expected_snapshot=expected_snapshot,
    )


def _write_text_with_activation_binding(
    path: Path,
    content: str,
    *,
    expected_snapshot: ManagedStateFileSnapshot,
    description: str,
) -> tuple[ManagedStateFileSnapshot, SchedulerActivationBinding]:
    result = _atomic_write_scheduler_config(
        path,
        content.encode("utf-8"),
        expected_snapshot=expected_snapshot,
        retain_activation_description=description,
    )
    if not isinstance(result, tuple):
        raise SyncError(f"scheduler config publication binding is missing: {path}")
    return result


def _systemd_timer_enablement_path(paths: SchedulerPaths) -> Path:
    assert paths.systemd_timer is not None
    return paths.systemd_timer.parent / "timers.target.wants" / paths.systemd_timer.name


def _ensure_systemd_timer_enablement(
    paths: SchedulerPaths,
    *,
    dry_run: bool,
) -> SymlinkSnapshot | None:
    assert paths.systemd_timer is not None
    target = _systemd_timer_enablement_path(paths)
    link_target = str(paths.systemd_timer)
    if dry_run:
        print(f"would enable {target} -> {link_target}")
        return None
    user_home = Path.home().expanduser()
    planned = _capture_reconcile_target_snapshot(user_home, target)
    if planned.link_target == link_target:
        _require_reconcile_target_snapshot(user_home, target, planned)
        return _read_symlink_snapshot_beneath(user_home, target)
    if planned.link_identity is not None:
        raise SyncError(
            f"systemd timer enablement path is occupied by foreign content: {target}"
        )
    created = _create_symlink_beneath(
        user_home,
        target,
        link_target,
        "file",
        expected_snapshot=planned,
        created_parent_identities={},
    )
    current = _read_symlink_snapshot_beneath(user_home, target)
    if current != created or current.link_target != link_target:
        raise SyncError(
            f"systemd timer enablement changed during publication: {target}"
        )
    return current


def _revalidate_systemd_timer_enablement(
    paths: SchedulerPaths,
    expected: SymlinkSnapshot,
) -> None:
    target = _systemd_timer_enablement_path(paths)
    try:
        current = _read_symlink_snapshot_beneath(
            Path.home().expanduser(),
            target,
        )
    except (OSError, SyncError) as error:
        raise SyncError(
            f"systemd timer enablement is unreadable after publication: {target}"
        ) from error
    if current != expected or current.link_target != str(paths.systemd_timer):
        raise SyncError(f"systemd timer enablement changed after publication: {target}")


def _remove_scheduler_config_if_snapshot(
    path: Path,
    expected: ManagedStateFileSnapshot,
) -> None:
    user_home = Path.home().expanduser()
    parent_fd = _open_directory_beneath(user_home, path.parent)
    try:
        snapshot = _read_managed_state_file_snapshot(
            user_home,
            path,
            parent_fd,
        )
        if not snapshot.exists:
            if expected.exists:
                raise SyncError(f"scheduler config disappeared before removal: {path}")
            return
        if not _scheduler_file_snapshots_match(snapshot, expected):
            raise SyncError(f"scheduler config changed before rollback removal: {path}")
        _isolate_and_delete_pending_cleanup_file(
            user_home,
            path,
            parent_fd,
            snapshot,
            label=f"scheduler config rollback {path}",
        )
    finally:
        _close_fd_quietly(parent_fd)


def _remove_scheduler_config_if_payload(path: Path, payload: bytes) -> None:
    snapshot = _scheduler_config_snapshot(path, max(len(payload), 1))
    if not snapshot.exists:
        return
    if snapshot.payload != payload:
        raise SyncError(f"scheduler config changed before rollback removal: {path}")
    _remove_scheduler_config_if_snapshot(path, snapshot)


def _write_plist(
    path: Path,
    payload: dict[str, Any],
    *,
    dry_run: bool,
    expected_snapshot: ManagedStateFileSnapshot | None = None,
) -> ManagedStateFileSnapshot | None:
    if dry_run:
        print(f"would write {path}")
        print(json.dumps(payload, indent=2, sort_keys=True))
        return None
    return _atomic_write_scheduler_config(
        path,
        plistlib.dumps(payload, sort_keys=True),
        expected_snapshot=expected_snapshot,
    )


def _scheduler_pair_transaction_path(paths: SchedulerPaths) -> Path:
    assert paths.systemd_service is not None
    return paths.systemd_service.parent / SCHEDULER_PAIR_TRANSACTION_NAME


def _scheduler_activation_transaction_path(paths: SchedulerPaths) -> Path:
    return _scheduler_config_parent(paths) / SCHEDULER_ACTIVATION_TRANSACTION_NAME


def _scheduler_uninstall_transaction_path(paths: SchedulerPaths) -> Path:
    return _scheduler_config_parent(paths) / SCHEDULER_UNINSTALL_TRANSACTION_NAME


def _scheduler_activation_transaction_payload(
    home: Path,
    paths: SchedulerPaths,
) -> bytes:
    return _bounded_json_document(
        {
            "version": 1,
            "platform": paths.platform,
            "home": str(home.expanduser()),
            "phase": "activation-required",
        },
        max_bytes=MAX_SCHEDULER_ACTIVATION_TRANSACTION_BYTES,
        overflow_error="scheduler activation transaction exceeds the size limit",
    )


def _scheduler_activation_transaction_state(
    home: Path,
    paths: SchedulerPaths,
) -> ManagedStateFileSnapshot:
    marker = _scheduler_activation_transaction_path(paths)
    try:
        snapshot = _scheduler_config_snapshot(
            marker,
            MAX_SCHEDULER_ACTIVATION_TRANSACTION_BYTES,
        )
    except SyncError as error:
        raise SyncError(
            f"scheduler activation transaction is invalid: {marker}: {error}",
            code="scheduler-activation-state-invalid",
        ) from error
    if not snapshot.exists:
        return snapshot
    assert snapshot.payload is not None
    try:
        data = _decode_managed_state_json(snapshot.payload, marker)
    except SyncError as error:
        raise SyncError(
            f"scheduler activation transaction is invalid: {marker}: {error}",
            code="scheduler-activation-state-invalid",
        ) from error
    if set(data) != {
        "version",
        "platform",
        "home",
        "phase",
    }:
        raise SyncError(
            f"scheduler activation transaction has unsupported fields: {marker}",
            code="scheduler-activation-state-invalid",
        )
    if (
        data.get("version") != 1
        or data.get("platform") != paths.platform
        or data.get("home") != str(home.expanduser())
        or data.get("phase") != "activation-required"
        or snapshot.payload != _scheduler_activation_transaction_payload(home, paths)
    ):
        raise SyncError(
            f"scheduler activation transaction is not canonical: {marker}",
            code="scheduler-activation-state-invalid",
        )
    return snapshot


def _ensure_scheduler_activation_transaction(
    home: Path,
    paths: SchedulerPaths,
    *,
    before: ManagedStateFileSnapshot,
    dry_run: bool,
) -> ManagedStateFileSnapshot | None:
    marker = _scheduler_activation_transaction_path(paths)
    if before.exists:
        return before
    payload = _scheduler_activation_transaction_payload(home, paths)
    if dry_run:
        print(f"would write scheduler activation transaction: {marker}")
        return None
    return _atomic_write_scheduler_config(
        marker,
        payload,
        expected_snapshot=before,
    )


def _scheduler_uninstall_transaction_payload(
    home: Path,
    paths: SchedulerPaths,
    *,
    disable: bool,
) -> bytes:
    return _bounded_json_document(
        {
            "version": 1,
            "platform": paths.platform,
            "home": str(home.expanduser()),
            "disable": disable,
            "phase": "prepared",
        },
        max_bytes=MAX_SCHEDULER_UNINSTALL_TRANSACTION_BYTES,
        overflow_error="scheduler uninstall transaction exceeds the size limit",
    )


def _scheduler_uninstall_transaction_state(
    home: Path,
    paths: SchedulerPaths,
) -> tuple[ManagedStateFileSnapshot, bool | None]:
    marker = _scheduler_uninstall_transaction_path(paths)
    try:
        snapshot = _scheduler_config_snapshot(
            marker,
            MAX_SCHEDULER_UNINSTALL_TRANSACTION_BYTES,
        )
    except SyncError as error:
        raise SyncError(
            f"scheduler uninstall transaction is invalid: {marker}: {error}",
            code="scheduler-uninstall-state-invalid",
        ) from error
    if not snapshot.exists:
        return snapshot, None
    assert snapshot.payload is not None
    try:
        data = _decode_managed_state_json(snapshot.payload, marker)
    except SyncError as error:
        raise SyncError(
            f"scheduler uninstall transaction is invalid: {marker}: {error}",
            code="scheduler-uninstall-state-invalid",
        ) from error
    if set(data) != {
        "version",
        "platform",
        "home",
        "disable",
        "phase",
    }:
        raise SyncError(
            f"scheduler uninstall transaction has unsupported fields: {marker}",
            code="scheduler-uninstall-state-invalid",
        )
    disable = data.get("disable")
    if (
        data.get("version") != 1
        or data.get("platform") != paths.platform
        or data.get("home") != str(home.expanduser())
        or type(disable) is not bool
        or data.get("phase") != "prepared"
        or snapshot.payload
        != _scheduler_uninstall_transaction_payload(
            home,
            paths,
            disable=disable,
        )
    ):
        raise SyncError(
            f"scheduler uninstall transaction is not canonical: {marker}",
            code="scheduler-uninstall-state-invalid",
        )
    return snapshot, disable


def _assert_scheduler_uninstall_not_pending(
    home: Path,
    paths: SchedulerPaths,
) -> None:
    snapshot, _disable = _scheduler_uninstall_transaction_state(home, paths)
    if snapshot.exists:
        marker = _scheduler_uninstall_transaction_path(paths)
        raise SyncError(
            f"scheduler has an incomplete uninstall transaction: {marker}",
            code="scheduler-uninstall-incomplete",
        )


def _scheduler_pair_transaction_payload(
    *,
    service_before: ManagedStateFileSnapshot,
    timer_before: ManagedStateFileSnapshot,
    service_after: bytes,
    timer_after: bytes,
) -> bytes:
    def encode_snapshot(
        snapshot: ManagedStateFileSnapshot,
    ) -> dict[str, Any]:
        if not snapshot.exists:
            return {"exists": False}
        if not _managed_state_snapshot_has_complete_file_evidence(snapshot):
            raise SyncError("scheduler pair transaction before-state is incomplete")
        assert snapshot.payload is not None
        assert snapshot.file_identity is not None
        assert snapshot.file_type is not None
        assert snapshot.mode is not None
        assert snapshot.size is not None
        assert snapshot.uid is not None
        assert snapshot.gid is not None
        return {
            "exists": True,
            "payload": base64.b64encode(snapshot.payload).decode("ascii"),
            "mode": snapshot.mode,
            "identity": list(snapshot.file_identity),
            "file_type": snapshot.file_type,
            "size": snapshot.size,
            "uid": snapshot.uid,
            "gid": snapshot.gid,
        }

    return _bounded_json_document(
        {
            "version": 2,
            "service_before": encode_snapshot(service_before),
            "timer_before": encode_snapshot(timer_before),
            "service_after": base64.b64encode(service_after).decode("ascii"),
            "timer_after": base64.b64encode(timer_after).decode("ascii"),
        },
        max_bytes=MAX_SCHEDULER_PAIR_TRANSACTION_BYTES,
        overflow_error="scheduler pair transaction exceeds the size limit",
    )


def _parse_scheduler_pair_transaction(
    payload: bytes,
    path: Path,
) -> tuple[
    ManagedStateFileSnapshot,
    ManagedStateFileSnapshot,
    bytes,
    bytes,
]:
    data = _decode_managed_state_json(payload, path)
    expected_fields = {
        "version",
        "service_before",
        "timer_before",
        "service_after",
        "timer_after",
    }
    if set(data) != expected_fields or data.get("version") != 2:
        raise SyncError("scheduler pair transaction has unsupported fields")

    def decode_payload(field: str) -> bytes:
        value = data.get(field)
        if not isinstance(value, str):
            raise SyncError(f"scheduler pair transaction {field} is invalid")
        try:
            decoded = base64.b64decode(value, validate=True)
        except (ValueError, binascii.Error) as error:
            raise SyncError(f"scheduler pair transaction {field} is invalid") from error
        if len(decoded) > 1024 * 1024:
            raise SyncError(
                f"scheduler pair transaction {field} exceeds the size limit"
            )
        return decoded

    def decode_snapshot(field: str) -> ManagedStateFileSnapshot:
        value = data.get(field)
        if not isinstance(value, dict) or "exists" not in value:
            raise SyncError(f"scheduler pair transaction {field} is invalid")
        if value.get("exists") is False:
            if set(value) != {"exists"}:
                raise SyncError(f"scheduler pair transaction {field} is not canonical")
            return ManagedStateFileSnapshot(exists=False)
        expected_snapshot_fields = {
            "exists",
            "payload",
            "mode",
            "identity",
            "file_type",
            "size",
            "uid",
            "gid",
        }
        if value.get("exists") is not True or set(value) != expected_snapshot_fields:
            raise SyncError(f"scheduler pair transaction {field} is invalid")
        encoded_payload = value.get("payload")
        if not isinstance(encoded_payload, str):
            raise SyncError(f"scheduler pair transaction {field} is invalid")
        try:
            decoded = base64.b64decode(encoded_payload, validate=True)
        except (ValueError, binascii.Error) as error:
            raise SyncError(f"scheduler pair transaction {field} is invalid") from error
        identity = value.get("identity")
        mode = value.get("mode")
        file_type = value.get("file_type")
        size = value.get("size")
        uid = value.get("uid")
        gid = value.get("gid")
        if (
            len(decoded) > 1024 * 1024
            or not isinstance(identity, list)
            or len(identity) != 2
            or not all(type(part) is int and part >= 0 for part in identity)
            or type(mode) is not int
            or mode < 0
            or mode > 0o7777
            or mode & 0o022
            or file_type != stat.S_IFREG
            or type(size) is not int
            or size != len(decoded)
            or uid != os.geteuid()
            or type(gid) is not int
            or gid < 0
        ):
            raise SyncError(f"scheduler pair transaction {field} is invalid")
        return ManagedStateFileSnapshot(
            exists=True,
            payload=decoded,
            mode=mode,
            file_identity=(identity[0], identity[1]),
            file_type=file_type,
            size=size,
            uid=uid,
            gid=gid,
        )

    service_before = decode_snapshot("service_before")
    timer_before = decode_snapshot("timer_before")
    service_after = decode_payload("service_after")
    timer_after = decode_payload("timer_after")
    canonical = _scheduler_pair_transaction_payload(
        service_before=service_before,
        timer_before=timer_before,
        service_after=service_after,
        timer_after=timer_after,
    )
    if payload != canonical:
        raise SyncError("scheduler pair transaction is not canonical")
    return service_before, timer_before, service_after, timer_after


def _scheduler_snapshot_matches_after_payload(
    snapshot: ManagedStateFileSnapshot,
    payload: bytes,
) -> bool:
    # New scheduler files are mode 0600, so group identity cannot affect their
    # access policy. Bind bytes/type/owner/mode/size and deliberately ignore gid.
    return (
        snapshot.exists
        and snapshot.payload == payload
        and snapshot.mode == 0o600
        and snapshot.file_type == stat.S_IFREG
        and snapshot.uid == os.geteuid()
        and snapshot.size == len(payload)
    )


def _restore_scheduler_config_snapshot(
    path: Path,
    *,
    current: ManagedStateFileSnapshot,
    desired: ManagedStateFileSnapshot,
) -> None:
    if _scheduler_file_logical_state_matches(current, desired):
        return
    if not desired.exists:
        if current.exists:
            _remove_scheduler_config_if_snapshot(path, current)
        return
    assert desired.payload is not None
    assert desired.mode is not None
    assert desired.gid is not None
    _atomic_write_scheduler_config(
        path,
        desired.payload,
        expected_snapshot=current,
        mode=desired.mode,
        gid=desired.gid,
    )


def _systemd_pair_recovery_members(
    group: SystemdPairRecoveryGroup,
) -> tuple[
    SystemdPairRecoveryMember,
    SystemdPairRecoveryMember,
    SystemdPairRecoveryMember,
]:
    return group.marker, group.service, group.timer


def _revalidate_systemd_pair_recovery_member(
    group: SystemdPairRecoveryGroup,
    member: SystemdPairRecoveryMember,
) -> None:
    expected = member.expected
    if expected.parent_identity != group.parent_identity:
        raise SyncError(f"incomplete parent evidence for {member.path}")
    if expected.exists:
        if not _scheduler_recovery_binding_matches(
            group.home,
            member.file_fd,
            member.path,
            group.parent_fd,
            expected,
        ):
            raise SyncError(f"object binding changed for {member.path}")
        return
    if any(
        value is not None
        for value in (
            expected.payload,
            expected.mode,
            expected.file_identity,
            expected.file_type,
            expected.size,
            expected.uid,
            expected.gid,
        )
    ):
        raise SyncError(f"incomplete absence evidence for {member.path}")
    try:
        os.stat(
            member.path.name,
            dir_fd=group.parent_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError:
        return
    except OSError as error:
        raise SyncError(f"absence is unreadable for {member.path}") from error
    raise SyncError(f"absent object appeared at {member.path}")


def _revalidate_systemd_pair_recovery_group(
    group: SystemdPairRecoveryGroup,
    *,
    boundary: str,
) -> None:
    try:
        if _directory_identity(
            group.parent_fd
        ) != group.parent_identity or not _bound_directory_matches(
            group.home,
            group.parent_path,
            group.parent_fd,
        ):
            raise SyncError("unit parent identity changed")
        # Object identity, exact bytes, and access policy are protected for
        # present members; exact name absence is protected for absent members.
        # Run two stabilization passes and one final complete pass so a change
        # to an earlier member while a later member is checked is observed.
        for _verification_round in range(2):
            for member in _systemd_pair_recovery_members(group):
                _revalidate_systemd_pair_recovery_member(group, member)
        for member in _systemd_pair_recovery_members(group):
            _revalidate_systemd_pair_recovery_member(group, member)
        if _directory_identity(
            group.parent_fd
        ) != group.parent_identity or not _bound_directory_matches(
            group.home,
            group.parent_path,
            group.parent_fd,
        ):
            raise SyncError("unit parent identity changed")
    except (OSError, SyncError) as error:
        raise SyncError(
            f"systemd scheduler pair recovery object group changed {boundary}: {error}"
        ) from error


def _bind_systemd_pair_recovery_member(
    home: Path,
    path: Path,
    parent_fd: int,
    *,
    maximum_bytes: int = 1024 * 1024,
) -> SystemdPairRecoveryMember:
    expected = _scheduler_config_snapshot_at(
        home,
        path,
        parent_fd,
        maximum_bytes,
    )
    file_fd = (
        _open_scheduler_recovery_binding(path, parent_fd, expected)
        if expected.exists
        else -1
    )
    return SystemdPairRecoveryMember(
        path=path,
        expected=expected,
        file_fd=file_fd,
    )


@contextlib.contextmanager
def _retain_systemd_pair_recovery_group(
    paths: SchedulerPaths,
) -> Iterator[SystemdPairRecoveryGroup]:
    assert paths.systemd_service is not None
    assert paths.systemd_timer is not None
    marker = _scheduler_pair_transaction_path(paths)
    parent_path = paths.systemd_service.parent
    if paths.systemd_timer.parent != parent_path or marker.parent != parent_path:
        raise SyncError("systemd scheduler pair recovery parents disagree")
    home = Path.home().expanduser()
    parent_fd = -1
    members: list[SystemdPairRecoveryMember] = []
    try:
        parent_fd = _open_directory_beneath(home, parent_path)
        parent_identity = _directory_identity(parent_fd)
        if not _bound_directory_matches(home, parent_path, parent_fd):
            raise SyncError(
                "systemd scheduler pair recovery parent changed before binding"
            )
        members.append(
            _bind_systemd_pair_recovery_member(
                home,
                marker,
                parent_fd,
                maximum_bytes=MAX_SCHEDULER_PAIR_TRANSACTION_BYTES,
            )
        )
        members.append(
            _bind_systemd_pair_recovery_member(
                home,
                paths.systemd_service,
                parent_fd,
            )
        )
        members.append(
            _bind_systemd_pair_recovery_member(
                home,
                paths.systemd_timer,
                parent_fd,
            )
        )
        group = SystemdPairRecoveryGroup(
            home=home,
            parent_path=parent_path,
            parent_fd=parent_fd,
            parent_identity=parent_identity,
            marker=members[0],
            service=members[1],
            timer=members[2],
        )
        _revalidate_systemd_pair_recovery_group(
            group,
            boundary="while binding the transaction",
        )
        yield group
    finally:
        for member in members:
            if member.file_fd >= 0:
                _close_fd_quietly(member.file_fd)
        if parent_fd >= 0:
            _close_fd_quietly(parent_fd)


def _refresh_systemd_pair_recovery_member(
    group: SystemdPairRecoveryGroup,
    member: SystemdPairRecoveryMember,
    desired: ManagedStateFileSnapshot,
) -> None:
    if _directory_identity(
        group.parent_fd
    ) != group.parent_identity or not _bound_directory_matches(
        group.home,
        group.parent_path,
        group.parent_fd,
    ):
        raise SyncError(
            "systemd scheduler pair recovery parent changed during rollback"
        )
    refreshed = _scheduler_config_snapshot_at(
        group.home,
        member.path,
        group.parent_fd,
    )
    if (
        refreshed.parent_identity != group.parent_identity
        or not _scheduler_file_logical_state_matches(refreshed, desired)
    ):
        raise SyncError(
            "systemd scheduler pair transaction rollback could not be verified"
        )
    refreshed_fd = (
        _open_scheduler_recovery_binding(
            member.path,
            group.parent_fd,
            refreshed,
        )
        if refreshed.exists
        else -1
    )
    old_fd = member.file_fd
    member.expected = refreshed
    member.file_fd = refreshed_fd
    if old_fd >= 0:
        _close_fd_quietly(old_fd)
    _revalidate_systemd_pair_recovery_group(
        group,
        boundary=f"after rollback of {member.path.name}",
    )


def _commit_systemd_pair_recovery_marker(
    group: SystemdPairRecoveryGroup,
) -> None:
    try:
        os.fsync(group.parent_fd)
    except OSError as error:
        raise SyncError(
            "failed to sync recovered systemd scheduler pair transaction"
        ) from error
    _revalidate_systemd_pair_recovery_group(
        group,
        boundary="after parent sync before transaction marker commit",
    )
    try:
        os.unlink(
            group.marker.path.name,
            dir_fd=group.parent_fd,
        )
    except OSError as error:
        raise SyncError(
            "failed to commit recovered systemd scheduler pair transaction"
        ) from error


def _recover_scheduler_pair_transaction(
    paths: SchedulerPaths,
    *,
    dry_run: bool,
) -> bool:
    if paths.platform != "linux":
        return False
    assert paths.systemd_service is not None
    assert paths.systemd_timer is not None
    marker = _scheduler_pair_transaction_path(paths)
    try:
        recovery_context = _retain_systemd_pair_recovery_group(paths)
        group = recovery_context.__enter__()
    except FileNotFoundError:
        return False
    try:
        if not group.marker.expected.exists:
            _revalidate_systemd_pair_recovery_group(
                group,
                boundary="while confirming transaction absence",
            )
            return False
        if group.marker.expected.payload is None:
            raise SyncError(f"scheduler pair transaction disappeared: {marker}")
        (
            service_before,
            timer_before,
            service_after,
            timer_after,
        ) = _parse_scheduler_pair_transaction(
            group.marker.expected.payload,
            marker,
        )
        service_current = group.service.expected
        timer_current = group.timer.expected
        service_matches_before = _scheduler_file_logical_state_matches(
            service_current,
            service_before,
        )
        timer_matches_before = _scheduler_file_logical_state_matches(
            timer_current,
            timer_before,
        )
        service_matches_after = _scheduler_snapshot_matches_after_payload(
            service_current,
            service_after,
        )
        timer_matches_after = _scheduler_snapshot_matches_after_payload(
            timer_current,
            timer_after,
        )
        if not service_matches_before and not service_matches_after:
            raise SyncError("scheduler service changed during pending pair transaction")
        if not timer_matches_before and not timer_matches_after:
            raise SyncError("scheduler timer changed during pending pair transaction")
        both_after = service_matches_after and timer_matches_after
        action = "commit" if both_after else "roll back"
        if dry_run:
            raise SyncError(
                "scheduler pair transaction requires recovery before dry-run: "
                f"{marker} ({action})"
            )
        if not both_after:
            _revalidate_systemd_pair_recovery_group(
                group,
                boundary="before service rollback",
            )
            _restore_scheduler_config_snapshot(
                paths.systemd_service,
                current=service_current,
                desired=service_before,
            )
            _refresh_systemd_pair_recovery_member(
                group,
                group.service,
                service_before,
            )
            _restore_scheduler_config_snapshot(
                paths.systemd_timer,
                current=timer_current,
                desired=timer_before,
            )
            _refresh_systemd_pair_recovery_member(
                group,
                group.timer,
                timer_before,
            )
        _commit_systemd_pair_recovery_marker(group)
    finally:
        recovery_context.__exit__(None, None, None)
    print(f"recovered scheduler pair transaction ({action}): {marker}")
    return True


def install_scheduler(
    home: Path,
    repo: str | None,
    interval_minutes: int | None,
    platform_name: str,
    runner: str | None,
    *,
    dry_run: bool,
    enable: bool,
    mode: str | None = None,
    base_repo: str | None = None,
    owner: str | None = None,
) -> None:
    if interval_minutes is not None and interval_minutes < 1:
        raise SyncError("scheduler interval must be at least 1 minute")
    if (
        interval_minutes is not None
        and interval_minutes > MAX_SCHEDULER_INTERVAL_MINUTES
    ):
        raise SyncError(
            "scheduler interval must not exceed "
            f"{MAX_SCHEDULER_INTERVAL_MINUTES} minutes"
        )
    if mode is not None and mode not in {"public", "private"}:
        raise SyncError(f"unsupported scheduler mode: {mode}")
    if repo is not None and REPOSITORY_RE.fullmatch(repo) is None:
        raise SyncError("scheduler repository must be an owner/repo string")
    if base_repo is not None and REPOSITORY_RE.fullmatch(base_repo) is None:
        raise SyncError("scheduler base repository must be an owner/repo string")
    if owner is not None:
        owner = _validate_owner(owner)
    if mode == "private" and owner == PUBLIC_OWNER:
        raise SyncError("private scheduler owner must not be public")
    home = home.expanduser()
    selected_platform = _scheduler_platform(platform_name)
    runner_path = _scheduler_runner(home, runner)
    paths = _scheduler_paths(selected_platform, home)
    if selected_platform == "linux":
        # Reject path bytes that systemd cannot represent before entering any
        # scheduler recovery or publication transaction. Repository and owner
        # values are constrained by their lexical validators above or after
        # an omitted value is reconstructed from an audited config.
        _systemd_quote(str(runner_path))
        _systemd_quote(str(home))
    if dry_run:
        _install_scheduler_transaction(
            home,
            repo,
            interval_minutes,
            selected_platform,
            runner_path,
            paths,
            dry_run=True,
            enable=enable,
            mode=mode,
            base_repo=base_repo,
            owner=owner,
        )
        return
    # Preserve the no-write failure behavior for an unusable runner, then
    # revalidate the same property inside the transaction lock below.
    _validate_scheduler_runner(runner_path, dry_run=False)
    with installation_lock(home):
        _install_scheduler_transaction(
            home,
            repo,
            interval_minutes,
            selected_platform,
            runner_path,
            paths,
            dry_run=False,
            enable=enable,
            mode=mode,
            base_repo=base_repo,
            owner=owner,
        )


def _install_scheduler_transaction(
    home: Path,
    repo: str | None,
    interval_minutes: int | None,
    selected_platform: str,
    runner_path: Path,
    paths: SchedulerPaths,
    *,
    dry_run: bool,
    enable: bool,
    mode: str | None,
    base_repo: str | None,
    owner: str | None,
) -> None:
    with contextlib.ExitStack() as binding_stack:
        _install_scheduler_transaction_with_bindings(
            home,
            repo,
            interval_minutes,
            selected_platform,
            runner_path,
            paths,
            dry_run=dry_run,
            enable=enable,
            mode=mode,
            base_repo=base_repo,
            owner=owner,
            binding_stack=binding_stack,
        )


def _install_scheduler_transaction_with_bindings(
    home: Path,
    repo: str | None,
    interval_minutes: int | None,
    selected_platform: str,
    runner_path: Path,
    paths: SchedulerPaths,
    *,
    dry_run: bool,
    enable: bool,
    mode: str | None,
    base_repo: str | None,
    owner: str | None,
    binding_stack: contextlib.ExitStack,
) -> None:
    _assert_scheduler_uninstall_not_pending(home, paths)
    initial_systemd_drop_ins: tuple[SystemdDropInSnapshot, ...] = ()
    if selected_platform == "linux":
        assert paths.systemd_service is not None
        if not dry_run:
            unit_root_fd = _open_or_create_directory_beneath(
                Path.home().expanduser(),
                paths.systemd_service.parent,
                mode=0o755,
            )
            _close_fd_quietly(unit_root_fd)
        initial_systemd_drop_ins = _audit_systemd_drop_ins(paths)
    _recover_scheduler_pair_transaction(paths, dry_run=dry_run)
    if initial_systemd_drop_ins:
        _revalidate_systemd_drop_ins(paths, initial_systemd_drop_ins)
    _validate_scheduler_runner(runner_path, dry_run=dry_run)
    config_audit = _audit_scheduler_config(paths)
    existing = config_audit.config
    if existing is not None and existing.home != home:
        raise SyncError(
            "existing scheduler targets a different Codex home: "
            f"{existing.home} (expected {home})"
        )
    effective_mode = (
        existing.mode if mode is None and existing is not None else mode or "public"
    )
    effective_repo = (
        existing.repo
        if repo is None and existing is not None
        else repo or default_release_repo()
    )
    if effective_repo is None or REPOSITORY_RE.fullmatch(effective_repo) is None:
        raise SyncError("scheduler repository must be supplied for a new installation")
    if effective_mode == "private":
        effective_base_repo = (
            existing.base_repo
            if base_repo is None and existing is not None and existing.mode == "private"
            else base_repo or default_base_release_repo()
        )
        effective_owner = (
            existing.owner
            if owner is None and existing is not None and existing.mode == "private"
            else owner or "private"
        )
        if (
            effective_base_repo is None
            or REPOSITORY_RE.fullmatch(effective_base_repo) is None
        ):
            raise SyncError("scheduler base repository must be an owner/repo string")
        assert effective_owner is not None
        effective_owner = _validate_owner(effective_owner)
        if effective_owner == PUBLIC_OWNER:
            raise SyncError("private scheduler owner must not be public")
    else:
        effective_base_repo = effective_repo
        effective_owner = PUBLIC_OWNER
    mode = effective_mode
    repo = effective_repo
    base_repo = effective_base_repo
    owner = effective_owner
    effective_interval = (
        existing.interval_minutes
        if interval_minutes is None and existing is not None
        else interval_minutes or DEFAULT_SCHEDULER_INTERVAL_MINUTES
    )
    desired_base_repo = repo if mode == "public" else base_repo
    desired_owner = PUBLIC_OWNER if mode == "public" else owner
    config_matches = existing is not None and (
        existing.interval_minutes == effective_interval
        and existing.runner == runner_path
        and existing.command == "run-scheduled"
        and existing.mode == mode
        and existing.repo == repo
        and existing.base_repo == desired_base_repo
        and existing.owner == desired_owner
        and (
            selected_platform != "macos"
            or existing.launchd_profile == MACOS_LAUNCHD_PROFILE_AQUA
        )
    )
    if config_matches:
        assert existing is not None
        print(
            "scheduler already matches audited configuration; "
            f"preserved {existing.interval_minutes}-minute interval"
        )
    activation_before = _scheduler_activation_transaction_state(home, paths)
    activation_required = (
        activation_before.exists
        or enable
        or (existing is not None and not config_matches)
    )
    activation_snapshot = (
        _ensure_scheduler_activation_transaction(
            home,
            paths,
            before=activation_before,
            dry_run=dry_run,
        )
        if activation_required
        else None
    )
    if selected_platform == "macos":
        assert paths.launchd_plist is not None
        published_launchd_snapshot: ManagedStateFileSnapshot | None
        if not dry_run:
            _ensure_safe_internal_directory(
                home,
                _scheduler_log_dir(home),
                create=True,
            )
        if not config_matches:
            published_launchd_snapshot = _write_plist(
                paths.launchd_plist,
                _launchd_plist(
                    home,
                    repo,
                    effective_interval,
                    runner_path,
                    mode=mode,
                    base_repo=base_repo,
                    owner=owner,
                ),
                dry_run=dry_run,
                expected_snapshot=config_audit.snapshots[0],
            )
        else:
            _revalidate_scheduler_config_audit(paths, config_audit)
            published_launchd_snapshot = None if dry_run else config_audit.snapshots[0]

        def activate(
            bindings: tuple[SchedulerActivationBinding, ...],
            legacy_bindings: tuple[SchedulerActivationBinding, ...] | None,
            activation_binding: SchedulerActivationBinding | None,
        ) -> None:
            _cleanup_legacy_launchd_schedulers(
                paths,
                dry_run=dry_run,
                disable=enable,
                remove=enable,
                activation_bindings=bindings,
                retained_legacy_bindings=legacy_bindings,
            )
            if enable:
                gui_domain = _macos_launchd_domain(MACOS_LEGACY_GUI_LAUNCHD_DOMAIN)
                background_domain = _macos_launchd_domain(
                    MACOS_BACKGROUND_LAUNCHD_DOMAIN
                )
                _run_native_scheduler_action(
                    [
                        "launchctl",
                        "bootout",
                        f"{background_domain}/{LAUNCHD_LABEL}",
                    ],
                    dry_run=dry_run,
                    allow_fail=NATIVE_FAILURE_ALREADY_ABSENT,
                    activation_bindings=bindings,
                )
                _run_native_scheduler_action(
                    [
                        "launchctl",
                        "disable",
                        f"{background_domain}/{LAUNCHD_LABEL}",
                    ],
                    dry_run=dry_run,
                    allow_fail=NATIVE_FAILURE_ALREADY_ABSENT,
                    activation_bindings=bindings,
                )
                _run_native_scheduler_action(
                    [
                        "launchctl",
                        "bootout",
                        f"{gui_domain}/{LAUNCHD_LABEL}",
                    ],
                    dry_run=dry_run,
                    allow_fail=NATIVE_FAILURE_ALREADY_ABSENT,
                    activation_bindings=bindings,
                )
                _run_native_scheduler_action(
                    [
                        "launchctl",
                        "enable",
                        f"{gui_domain}/{LAUNCHD_LABEL}",
                    ],
                    dry_run=dry_run,
                    activation_bindings=bindings,
                )
                _run_native_scheduler_action(
                    [
                        "launchctl",
                        "bootstrap",
                        gui_domain,
                        str(paths.launchd_plist),
                    ],
                    dry_run=dry_run,
                    activation_bindings=bindings,
                )
                _run_native_scheduler_action(
                    [
                        "launchctl",
                        "enable",
                        f"{gui_domain}/{LAUNCHD_LABEL}",
                    ],
                    dry_run=dry_run,
                    activation_bindings=bindings,
                )
                if dry_run:
                    _unlink_file(
                        _scheduler_activation_transaction_path(paths),
                        dry_run=True,
                    )
                else:
                    assert activation_binding is not None
                    _commit_scheduler_activation_transaction(
                        activation_binding,
                        related_bindings=tuple(
                            binding
                            for binding in bindings
                            if binding is not activation_binding
                        ),
                    )

        if dry_run:
            activate((), None, None)
        else:
            assert published_launchd_snapshot is not None
            legacy_binding_specs = (
                tuple(
                    (
                        _legacy_launchd_plist(paths, label),
                        _scheduler_config_snapshot(
                            _legacy_launchd_plist(paths, label),
                        ),
                        f"legacy launchd scheduler {label}",
                    )
                    for label in LEGACY_LAUNCHD_LABELS
                )
                if enable
                else ()
            )
            binding_specs = (
                (
                    paths.launchd_plist,
                    published_launchd_snapshot,
                    "macOS launchd scheduler config",
                ),
                *legacy_binding_specs,
            )
            with contextlib.ExitStack() as stack:
                config_bindings = tuple(
                    stack.enter_context(
                        _retain_launchd_activation_binding(
                            path,
                            snapshot,
                            description=description,
                            revalidate_on_exit=not enable,
                        )
                    )
                    for path, snapshot, description in binding_specs
                )
                activation_binding = (
                    _retain_scheduler_activation_transaction(
                        stack,
                        paths,
                        activation_snapshot,
                        revalidate_on_exit=not enable,
                    )
                    if activation_snapshot is not None
                    else None
                )
                bindings = (
                    (*config_bindings, activation_binding)
                    if activation_binding is not None
                    else config_bindings
                )
                activate(
                    bindings,
                    config_bindings[1:],
                    activation_binding,
                )
        if activation_required and not enable:
            print(
                "scheduler activation remains incomplete: "
                f"{_scheduler_activation_transaction_path(paths)}"
            )
        print(f"installed macOS launchd scheduler: {paths.launchd_plist}")
        return

    if selected_platform == "linux":
        assert paths.systemd_service is not None
        assert paths.systemd_timer is not None
        published_systemd_snapshots: (
            tuple[ManagedStateFileSnapshot, ManagedStateFileSnapshot] | None
        ) = None
        published_systemd_bindings: (
            tuple[SchedulerActivationBinding, SchedulerActivationBinding] | None
        ) = None
        if not config_matches:
            desired_service = _systemd_service(
                home,
                repo,
                runner_path,
                mode=mode,
                base_repo=base_repo,
                owner=owner,
            )
            desired_timer = _systemd_timer(effective_interval)
            service_before, timer_before = config_audit.snapshots
            marker_payload = _scheduler_pair_transaction_payload(
                service_before=service_before,
                timer_before=timer_before,
                service_after=desired_service.encode("utf-8"),
                timer_after=desired_timer.encode("utf-8"),
            )
            if not dry_run:
                marker_path = _scheduler_pair_transaction_path(paths)
                marker_before = _scheduler_config_snapshot(
                    marker_path,
                    MAX_SCHEDULER_PAIR_TRANSACTION_BYTES,
                )
                if marker_before.exists:
                    raise SyncError(
                        f"scheduler pair transaction already exists: {marker_path}"
                    )
                _atomic_write_scheduler_config(
                    marker_path,
                    marker_payload,
                    expected_snapshot=marker_before,
                )
                _revalidate_systemd_drop_ins(
                    paths,
                    config_audit.systemd_drop_ins,
                )
            service_binding: SchedulerActivationBinding | None = None
            if dry_run:
                service_installed = _write_text(
                    paths.systemd_service,
                    desired_service,
                    dry_run=True,
                    expected_snapshot=service_before,
                )
            else:
                service_installed, service_binding = (
                    _write_text_with_activation_binding(
                        paths.systemd_service,
                        desired_service,
                        expected_snapshot=service_before,
                        description="Linux systemd scheduler service",
                    )
                )
                binding_stack.callback(
                    _release_retained_scheduler_activation_binding,
                    service_binding,
                    revalidate=not enable,
                )
            _revalidate_systemd_drop_ins(
                paths,
                config_audit.systemd_drop_ins,
            )
            timer_binding: SchedulerActivationBinding | None = None
            if dry_run:
                timer_installed = _write_text(
                    paths.systemd_timer,
                    desired_timer,
                    dry_run=True,
                    expected_snapshot=timer_before,
                )
            else:
                timer_installed, timer_binding = _write_text_with_activation_binding(
                    paths.systemd_timer,
                    desired_timer,
                    expected_snapshot=timer_before,
                    description="Linux systemd scheduler timer",
                )
                binding_stack.callback(
                    _release_retained_scheduler_activation_binding,
                    timer_binding,
                    revalidate=not enable,
                )
            _revalidate_systemd_drop_ins(
                paths,
                config_audit.systemd_drop_ins,
            )
            if not dry_run:
                assert service_installed is not None
                assert timer_installed is not None
                published_systemd_snapshots = (
                    service_installed,
                    timer_installed,
                )
                assert service_binding is not None
                assert timer_binding is not None
                published_systemd_bindings = (
                    service_binding,
                    timer_binding,
                )
                _revalidate_published_systemd_pair(
                    paths,
                    published_systemd_snapshots,
                    published_systemd_bindings,
                )
                marker_snapshot = _scheduler_config_snapshot(
                    _scheduler_pair_transaction_path(paths),
                    MAX_SCHEDULER_PAIR_TRANSACTION_BYTES,
                )
                if marker_snapshot.payload != marker_payload:
                    raise SyncError("scheduler pair transaction changed before commit")
                _remove_scheduler_config_if_snapshot(
                    _scheduler_pair_transaction_path(paths),
                    marker_snapshot,
                )
                _revalidate_systemd_drop_ins(
                    paths,
                    config_audit.systemd_drop_ins,
                )
                _revalidate_published_systemd_pair(
                    paths,
                    published_systemd_snapshots,
                    published_systemd_bindings,
                )
        else:
            _revalidate_scheduler_config_audit(paths, config_audit)
            service_snapshot, timer_snapshot = config_audit.snapshots
            published_systemd_snapshots = (
                service_snapshot,
                timer_snapshot,
            )

        def activate_linux(
            bindings: tuple[SchedulerActivationBinding, ...],
            activation_binding: SchedulerActivationBinding | None,
            stability_guard: SystemdActivationStabilityGuard | None,
        ) -> None:
            config_bindings = tuple(
                binding for binding in bindings if binding is not activation_binding
            )
            _revalidate_systemd_drop_ins(
                paths,
                config_audit.systemd_drop_ins,
            )
            if published_systemd_snapshots is not None and not dry_run:
                _revalidate_published_systemd_pair(
                    paths,
                    published_systemd_snapshots,
                    config_bindings,
                )
            _reload_systemd_manager_with_stable_units(
                stability_guard,
                dry_run=dry_run,
                activation_bindings=bindings,
            )
            _revalidate_systemd_drop_ins(
                paths,
                config_audit.systemd_drop_ins,
            )
            if published_systemd_snapshots is not None and not dry_run:
                _revalidate_published_systemd_pair(
                    paths,
                    published_systemd_snapshots,
                    config_bindings,
                )
            enablement_snapshot = _ensure_systemd_timer_enablement(
                paths,
                dry_run=dry_run,
            )
            _revalidate_systemd_drop_ins(
                paths,
                config_audit.systemd_drop_ins,
            )
            if published_systemd_snapshots is not None and not dry_run:
                _revalidate_published_systemd_pair(
                    paths,
                    published_systemd_snapshots,
                    config_bindings,
                )
            _run_native_scheduler_action(
                ["systemctl", "--user", "start", f"{SYSTEMD_UNIT}.timer"],
                dry_run=dry_run,
                activation_bindings=bindings,
            )
            _revalidate_systemd_drop_ins(
                paths,
                config_audit.systemd_drop_ins,
            )
            if published_systemd_snapshots is not None and not dry_run:
                _revalidate_published_systemd_pair(
                    paths,
                    published_systemd_snapshots,
                    config_bindings,
                )
                assert enablement_snapshot is not None
                _revalidate_systemd_timer_enablement(
                    paths,
                    enablement_snapshot,
                )
            if dry_run:
                _unlink_file(
                    _scheduler_activation_transaction_path(paths),
                    dry_run=True,
                )
            else:
                assert activation_binding is not None
                if stability_guard is not None:
                    _revalidate_systemd_activation_stability_guard(
                        stability_guard,
                        boundary="before activation transaction commit",
                        compare_generation=False,
                    )
                assert enablement_snapshot is not None
                _revalidate_systemd_timer_enablement(
                    paths,
                    enablement_snapshot,
                )
                _commit_scheduler_activation_transaction(
                    activation_binding,
                    related_bindings=config_bindings,
                )

        if dry_run:
            if enable:
                activate_linux((), None, None)
            else:
                _revalidate_systemd_drop_ins(
                    paths,
                    config_audit.systemd_drop_ins,
                )
        else:
            assert published_systemd_snapshots is not None
            if published_systemd_bindings is None:
                config_bindings = tuple(
                    binding_stack.enter_context(
                        _retain_launchd_activation_binding(
                            path,
                            snapshot,
                            description=description,
                            revalidate_on_exit=not enable,
                        )
                    )
                    for path, snapshot, description in (
                        (
                            paths.systemd_service,
                            published_systemd_snapshots[0],
                            "Linux systemd scheduler service",
                        ),
                        (
                            paths.systemd_timer,
                            published_systemd_snapshots[1],
                            "Linux systemd scheduler timer",
                        ),
                    )
                )
            else:
                config_bindings = published_systemd_bindings
            activation_binding = (
                _retain_scheduler_activation_transaction(
                    binding_stack,
                    paths,
                    activation_snapshot,
                    revalidate_on_exit=not enable,
                )
                if activation_snapshot is not None
                else None
            )
            bindings = (
                (*config_bindings, activation_binding)
                if activation_binding is not None
                else config_bindings
            )
            if enable:
                with _retain_systemd_activation_stability_guard(
                    paths,
                    config_bindings,
                    config_audit.systemd_drop_ins,
                ) as stability_guard:
                    activate_linux(
                        bindings,
                        activation_binding,
                        stability_guard,
                    )
            else:
                _revalidate_systemd_drop_ins(
                    paths,
                    config_audit.systemd_drop_ins,
                )
                _revalidate_published_systemd_pair(
                    paths,
                    published_systemd_snapshots,
                    config_bindings,
                )
        if activation_required and not enable:
            print(
                "scheduler activation remains incomplete: "
                f"{_scheduler_activation_transaction_path(paths)}"
            )
        print(f"installed Linux systemd user scheduler: {paths.systemd_timer}")
        return

    raise SyncError(f"unsupported scheduler platform: {selected_platform}")


def _unlink_file(path: Path, *, dry_run: bool) -> None:
    if dry_run:
        print(f"would remove {path}")
        return
    try:
        user_home = Path.home().expanduser()
        path.relative_to(user_home)
        parent_fd = _open_directory_beneath(user_home, path.parent)
    except FileNotFoundError:
        return
    except ValueError as error:
        raise SyncError(
            f"scheduler config removal is outside the user home: {path}"
        ) from error
    try:
        snapshot = _read_managed_state_file_snapshot(
            user_home,
            path,
            parent_fd,
        )
        if not snapshot.exists:
            return
        _isolate_and_delete_pending_cleanup_file(
            user_home,
            path,
            parent_fd,
            snapshot,
            label=f"scheduler config {path}",
        )
    finally:
        _close_fd_quietly(parent_fd)


def _report_preserved_systemd_drop_ins(paths: SchedulerPaths) -> None:
    assert paths.systemd_service is not None
    assert paths.systemd_timer is not None
    # This scheduler does not create drop-ins or an ownership receipt. Any
    # residue is therefore foreign user content: report it for doctor/status
    # follow-up, but never infer ownership from its name and never delete it.
    for unit_path in (paths.systemd_service, paths.systemd_timer):
        drop_in = unit_path.with_name(unit_path.name + ".d")
        if _path_exists_or_is_link(drop_in):
            print(
                "preserved foreign systemd drop-in residue without an "
                f"ownership receipt: {drop_in}"
            )


def _scheduler_activation_commit_group(
    marker_binding: SchedulerActivationBinding,
    related_bindings: tuple[SchedulerActivationBinding, ...],
) -> tuple[SchedulerActivationBinding, ...]:
    bindings = (*related_bindings, marker_binding)
    if len({id(binding) for binding in bindings}) != len(bindings):
        raise SyncError(
            "scheduler activation commit received duplicate file bindings",
            code=marker_binding.failure_code,
        )
    parent_path = marker_binding.path.parent
    parent_identity = marker_binding.expected.parent_identity
    if parent_identity is None:
        raise SyncError(
            "scheduler activation commit has incomplete parent evidence",
            code=marker_binding.failure_code,
        )
    shared_parent_fd = marker_binding.parent_fd
    for binding in bindings:
        if (
            binding.home != marker_binding.home
            or binding.path.parent != parent_path
            or binding.expected.parent_identity != parent_identity
        ):
            raise SyncError(
                "scheduler activation commit object group disagrees on its parent",
                code=marker_binding.failure_code,
            )
    try:
        if _directory_identity(
            shared_parent_fd
        ) != parent_identity or not _bound_directory_matches(
            marker_binding.home,
            parent_path,
            shared_parent_fd,
        ):
            raise SyncError("scheduler activation commit parent identity changed")
    except (OSError, SyncError) as error:
        raise SyncError(
            "scheduler activation commit object group parent is unreadable",
            code=marker_binding.failure_code,
        ) from error
    return tuple(replace(binding, parent_fd=shared_parent_fd) for binding in bindings)


def _revalidate_scheduler_activation_commit_group(
    bindings: tuple[SchedulerActivationBinding, ...],
) -> None:
    if not bindings:
        raise SyncError("scheduler activation commit object group is empty")
    shared_parent_fd = bindings[0].parent_fd
    parent_identity = bindings[0].expected.parent_identity
    home = bindings[0].home
    parent_path = bindings[0].path.parent
    if (
        parent_identity is None
        or any(binding.parent_fd != shared_parent_fd for binding in bindings)
        or any(binding.home != home for binding in bindings)
        or any(binding.path.parent != parent_path for binding in bindings)
        or any(
            binding.expected.parent_identity != parent_identity for binding in bindings
        )
    ):
        raise SyncError("scheduler activation commit object group is inconsistent")
    # Exact config/marker identity, bytes, access policy, and canonical-name
    # presence or absence are the protected properties. Two stabilization
    # passes plus a final whole-group pass catch an earlier member changing
    # while a later member is checked.
    for _verification_round in range(2):
        for binding in bindings:
            _revalidate_launchd_activation_binding(
                binding,
                boundary="after daemon activation before transaction commit",
            )
    for binding in bindings:
        _revalidate_launchd_activation_binding(
            binding,
            boundary="after daemon activation before transaction commit",
        )
    try:
        if _directory_identity(
            shared_parent_fd
        ) != parent_identity or not _bound_directory_matches(
            home,
            parent_path,
            shared_parent_fd,
        ):
            raise SyncError("scheduler activation commit parent identity changed")
    except (OSError, SyncError) as error:
        raise SyncError(
            "scheduler activation commit object group parent is unreadable"
        ) from error


def _commit_scheduler_activation_transaction(
    marker_binding: SchedulerActivationBinding,
    *,
    related_bindings: tuple[SchedulerActivationBinding, ...],
) -> None:
    bindings = _scheduler_activation_commit_group(
        marker_binding,
        related_bindings,
    )
    try:
        os.fsync(marker_binding.parent_fd)
    except OSError as error:
        raise SyncError(
            f"failed to sync scheduler activation transaction: {marker_binding.path}",
            code=marker_binding.failure_code,
        ) from error
    _revalidate_scheduler_activation_commit_group(bindings)
    try:
        os.unlink(
            marker_binding.path.name,
            dir_fd=marker_binding.parent_fd,
        )
    except OSError as error:
        raise SyncError(
            f"failed to commit scheduler activation transaction: {marker_binding.path}",
            code=marker_binding.failure_code,
        ) from error
    # Exact marker unlink is the activation commit point. The caller performs
    # only descriptor cleanup and success reporting afterward.
    marker_binding.expected = ManagedStateFileSnapshot(
        exists=False,
        parent_identity=marker_binding.expected.parent_identity,
    )
    marker_binding.removed = True


def _retain_scheduler_activation_transaction(
    stack: contextlib.ExitStack,
    paths: SchedulerPaths,
    snapshot: ManagedStateFileSnapshot,
    *,
    revalidate_on_exit: bool,
) -> SchedulerActivationBinding:
    if not snapshot.exists:
        raise SyncError(
            "scheduler activation transaction is missing before binding",
            code="scheduler-activation-incomplete",
        )
    return stack.enter_context(
        _retain_launchd_activation_binding(
            _scheduler_activation_transaction_path(paths),
            snapshot,
            description="scheduler activation transaction",
            failure_code="scheduler-activation-incomplete",
            revalidate_on_exit=revalidate_on_exit,
        )
    )


def _scheduler_uninstall_commit_group(
    marker_binding: SchedulerActivationBinding,
    related_bindings: tuple[SchedulerActivationBinding, ...],
) -> tuple[SchedulerActivationBinding, ...]:
    bindings = (*related_bindings, marker_binding)
    if len({id(binding) for binding in bindings}) != len(bindings):
        raise SyncError("scheduler uninstall commit received duplicate file bindings")
    parent_path = marker_binding.path.parent
    parent_identity = marker_binding.expected.parent_identity
    if parent_identity is None:
        raise SyncError(
            "scheduler uninstall commit has incomplete parent evidence",
            code=marker_binding.failure_code,
        )
    shared_parent_fd = marker_binding.parent_fd
    for binding in bindings:
        if (
            binding.home != marker_binding.home
            or binding.path.parent != parent_path
            or binding.expected.parent_identity != parent_identity
        ):
            raise SyncError(
                "scheduler uninstall commit object group disagrees on its parent",
                code=marker_binding.failure_code,
            )
    try:
        if _directory_identity(
            shared_parent_fd
        ) != parent_identity or not _bound_directory_matches(
            marker_binding.home,
            parent_path,
            shared_parent_fd,
        ):
            raise SyncError("scheduler uninstall commit parent identity changed")
    except (OSError, SyncError) as error:
        raise SyncError(
            "scheduler uninstall commit object group parent is unreadable",
            code=marker_binding.failure_code,
        ) from error
    # Every canonical-name lookup in the commit pass uses the one retained
    # marker-parent descriptor. File descriptors remain bound to their exact
    # original objects for present-member content and access revalidation.
    return tuple(replace(binding, parent_fd=shared_parent_fd) for binding in bindings)


def _revalidate_scheduler_uninstall_commit_group(
    bindings: tuple[SchedulerActivationBinding, ...],
) -> None:
    if not bindings:
        raise SyncError("scheduler uninstall commit object group is empty")
    shared_parent_fd = bindings[0].parent_fd
    parent_identity = bindings[0].expected.parent_identity
    home = bindings[0].home
    parent_path = bindings[0].path.parent
    if (
        parent_identity is None
        or any(binding.parent_fd != shared_parent_fd for binding in bindings)
        or any(binding.home != home for binding in bindings)
        or any(binding.path.parent != parent_path for binding in bindings)
        or any(
            binding.expected.parent_identity != parent_identity for binding in bindings
        )
    ):
        raise SyncError("scheduler uninstall commit object group is inconsistent")
    # Present members protect identity, bytes, and access policy; removed or
    # initially absent members protect exact canonical-name absence. As with
    # pair recovery, two stabilization passes plus a final complete pass catch
    # an earlier member changing while a later member is being checked.
    for _verification_round in range(2):
        for binding in bindings:
            _revalidate_launchd_activation_binding(
                binding,
                boundary="after parent sync before uninstall transaction commit",
            )
    for binding in bindings:
        _revalidate_launchd_activation_binding(
            binding,
            boundary="after parent sync before uninstall transaction commit",
        )
    try:
        if _directory_identity(
            shared_parent_fd
        ) != parent_identity or not _bound_directory_matches(
            home,
            parent_path,
            shared_parent_fd,
        ):
            raise SyncError("scheduler uninstall commit parent identity changed")
    except (OSError, SyncError) as error:
        raise SyncError(
            "scheduler uninstall commit object group parent is unreadable"
        ) from error


def _commit_scheduler_uninstall_transaction(
    marker_binding: SchedulerActivationBinding,
    *,
    related_bindings: tuple[SchedulerActivationBinding, ...],
) -> None:
    bindings = _scheduler_uninstall_commit_group(
        marker_binding,
        related_bindings,
    )
    try:
        os.fsync(marker_binding.parent_fd)
    except OSError as error:
        raise SyncError(
            f"failed to sync scheduler uninstall transaction: {marker_binding.path}"
        ) from error
    _revalidate_scheduler_uninstall_commit_group(bindings)
    try:
        os.unlink(
            marker_binding.path.name,
            dir_fd=marker_binding.parent_fd,
        )
    except OSError as error:
        raise SyncError(
            f"failed to commit scheduler uninstall transaction: {marker_binding.path}"
        ) from error
    # The exact marker unlink is the uninstall commit point. Context cleanup
    # below only closes descriptors and performs no further validation.
    marker_binding.expected = ManagedStateFileSnapshot(
        exists=False,
        parent_identity=marker_binding.expected.parent_identity,
    )
    marker_binding.removed = True


def _retain_scheduler_uninstall_transaction(
    stack: contextlib.ExitStack,
    home: Path,
    paths: SchedulerPaths,
    *,
    disable: bool,
    before: ManagedStateFileSnapshot,
    recorded_disable: bool | None,
) -> SchedulerActivationBinding:
    marker = _scheduler_uninstall_transaction_path(paths)
    if before.exists:
        if recorded_disable != disable:
            raise SyncError(
                f"scheduler uninstall retry changed the --no-disable policy: {marker}",
                code="scheduler-uninstall-incomplete",
            )
        installed = before
    else:
        installed = _atomic_write_scheduler_config(
            marker,
            _scheduler_uninstall_transaction_payload(
                home,
                paths,
                disable=disable,
            ),
            expected_snapshot=before,
        )
    return stack.enter_context(
        _retain_launchd_activation_binding(
            marker,
            installed,
            description="scheduler uninstall transaction",
            failure_code="scheduler-uninstall-incomplete",
            revalidate_on_exit=False,
        )
    )


def _query_orphan_scheduler_for_uninstall(
    paths: SchedulerPaths,
    bindings: tuple[SchedulerActivationBinding, ...],
    *,
    require_disabled: bool,
    config_audit: SchedulerConfigAudit | None = None,
) -> SchedulerDaemonQuery:
    query = _scheduler_daemon_enabled(
        paths,
        config_audit=config_audit,
        activation_bindings=bindings,
    )
    if query.classification not in {
        "enabled",
        "disabled",
        "active-disabled",
        "enabled-inactive",
    }:
        raise SyncError(
            query.reason
            or "scheduler daemon state is unavailable during orphan cleanup",
            code="scheduler-uninstall-incomplete",
        )
    if require_disabled and query.classification != "disabled":
        raise SyncError(
            "scheduler daemon remains active after orphan cleanup"
            + (f": {query.reason}" if query.reason else ""),
            code="scheduler-uninstall-incomplete",
        )
    return query


def uninstall_scheduler(
    home: Path,
    platform_name: str,
    *,
    dry_run: bool,
    disable: bool,
) -> None:
    home = home.expanduser()
    selected_platform = _scheduler_platform(platform_name)
    paths = _scheduler_paths(selected_platform, home)
    if dry_run:
        _uninstall_scheduler_transaction(
            home,
            selected_platform,
            paths,
            dry_run=True,
            disable=disable,
        )
        return
    config_parent_missing = _scheduler_config_parent_is_missing(paths)
    if config_parent_missing and not disable:
        print(
            f"{selected_platform} scheduler already absent; "
            f"config parent is missing: {_scheduler_config_parent(paths)}"
        )
        return
    with installation_lock(home):
        _uninstall_scheduler_transaction(
            home,
            selected_platform,
            paths,
            dry_run=False,
            disable=disable,
        )


def _uninstall_scheduler_transaction(
    home: Path,
    selected_platform: str,
    paths: SchedulerPaths,
    *,
    dry_run: bool,
    disable: bool,
) -> None:
    _recover_scheduler_pair_transaction(paths, dry_run=dry_run)
    config_parent_missing = not dry_run and _scheduler_config_parent_is_missing(paths)
    if config_parent_missing and not disable:
        print(
            f"{selected_platform} scheduler already absent; "
            f"config parent is missing: {_scheduler_config_parent(paths)}"
        )
        return
    if config_parent_missing and disable:
        config_parent_fd = _open_or_create_directory_beneath(
            Path.home().expanduser(),
            _scheduler_config_parent(paths),
            mode=0o755,
        )
        _close_fd_quietly(config_parent_fd)
        if _scheduler_config_parent_is_missing(paths):
            raise SyncError(
                "scheduler config parent is still missing after orphan "
                f"cleanup preparation: {_scheduler_config_parent(paths)}",
                code="scheduler-uninstall-incomplete",
            )
    uninstall_marker_before, recorded_disable = _scheduler_uninstall_transaction_state(
        home, paths
    )
    if dry_run and uninstall_marker_before.exists:
        raise SyncError(
            "scheduler uninstall transaction requires recovery before dry-run: "
            f"{_scheduler_uninstall_transaction_path(paths)}",
            code="scheduler-uninstall-incomplete",
        )
    activation_marker_snapshot = _scheduler_config_snapshot(
        _scheduler_activation_transaction_path(paths),
        MAX_SCHEDULER_ACTIVATION_TRANSACTION_BYTES,
    )
    if selected_platform == "macos":
        assert paths.launchd_plist is not None
        binding_specs = (
            (
                paths.launchd_plist,
                "macOS launchd scheduler config",
            ),
            *(
                (
                    _legacy_launchd_plist(paths, label),
                    f"legacy launchd scheduler {label}",
                )
                for label in LEGACY_LAUNCHD_LABELS
            ),
            (
                _scheduler_activation_transaction_path(paths),
                "scheduler activation transaction",
            ),
        )
        snapshots = (
            *(
                _scheduler_config_snapshot(path)
                for path, _description in binding_specs[:-1]
            ),
            activation_marker_snapshot,
        )
        orphan_cleanup = disable and not snapshots[0].exists
        orphan_config_audit = (
            SchedulerConfigAudit(config=None, snapshots=(snapshots[0],))
            if orphan_cleanup
            else None
        )

        def uninstall_macos(
            binding: SchedulerActivationBinding | None,
            bindings: tuple[SchedulerActivationBinding, ...],
            legacy_bindings: tuple[SchedulerActivationBinding, ...] | None,
            activation_binding: SchedulerActivationBinding | None,
            marker_binding: SchedulerActivationBinding | None,
        ) -> None:
            complete_bindings = (
                (*bindings, marker_binding) if marker_binding is not None else bindings
            )
            if orphan_cleanup and not dry_run:
                _query_orphan_scheduler_for_uninstall(
                    paths,
                    complete_bindings,
                    require_disabled=False,
                    config_audit=orphan_config_audit,
                )
            if disable:
                for domain_kind in (
                    MACOS_BACKGROUND_LAUNCHD_DOMAIN,
                    MACOS_LEGACY_GUI_LAUNCHD_DOMAIN,
                ):
                    domain = _macos_launchd_domain(domain_kind)
                    _run_native_scheduler_action(
                        [
                            "launchctl",
                            "bootout",
                            f"{domain}/{LAUNCHD_LABEL}",
                        ],
                        dry_run=dry_run,
                        allow_fail=NATIVE_FAILURE_ALREADY_ABSENT,
                        activation_bindings=complete_bindings,
                    )
                    _run_native_scheduler_action(
                        [
                            "launchctl",
                            "disable",
                            f"{domain}/{LAUNCHD_LABEL}",
                        ],
                        dry_run=dry_run,
                        allow_fail=NATIVE_FAILURE_ALREADY_ABSENT,
                        activation_bindings=complete_bindings,
                    )
            _cleanup_legacy_launchd_schedulers(
                paths,
                dry_run=dry_run,
                disable=disable,
                remove=True,
                activation_bindings=complete_bindings,
                retained_legacy_bindings=legacy_bindings,
            )
            if orphan_cleanup and not dry_run:
                _query_orphan_scheduler_for_uninstall(
                    paths,
                    complete_bindings,
                    require_disabled=True,
                    config_audit=orphan_config_audit,
                )
            if dry_run:
                _unlink_file(paths.launchd_plist, dry_run=True)
                _unlink_file(
                    _scheduler_activation_transaction_path(paths),
                    dry_run=True,
                )
            else:
                assert binding is not None
                assert activation_binding is not None
                assert marker_binding is not None
                _conditionally_remove_bound_scheduler_config(
                    binding,
                    boundary="before conditional scheduler removal",
                    related_bindings=complete_bindings,
                )
                _conditionally_remove_bound_scheduler_config(
                    activation_binding,
                    boundary="before conditional activation marker removal",
                    related_bindings=complete_bindings,
                )
                _commit_scheduler_uninstall_transaction(
                    marker_binding,
                    related_bindings=bindings,
                )

        if dry_run:
            uninstall_macos(None, (), None, None, None)
        else:
            with contextlib.ExitStack() as stack:
                bindings = tuple(
                    stack.enter_context(
                        _retain_launchd_activation_binding(
                            path,
                            snapshot,
                            description=description,
                            revalidate_on_exit=False,
                        )
                    )
                    for (path, description), snapshot in zip(
                        binding_specs,
                        snapshots,
                    )
                )
                marker_binding = _retain_scheduler_uninstall_transaction(
                    stack,
                    home,
                    paths,
                    disable=disable,
                    before=uninstall_marker_before,
                    recorded_disable=recorded_disable,
                )
                uninstall_macos(
                    bindings[0],
                    bindings,
                    bindings[1:-1],
                    bindings[-1],
                    marker_binding,
                )
        print(f"removed macOS launchd scheduler: {paths.launchd_plist}")
        return

    if selected_platform == "linux":
        assert paths.systemd_service is not None
        assert paths.systemd_timer is not None
        snapshots = (
            _scheduler_config_snapshot(paths.systemd_service),
            _scheduler_config_snapshot(paths.systemd_timer),
            activation_marker_snapshot,
        )
        orphan_cleanup = disable and not snapshots[0].exists and not snapshots[1].exists

        def uninstall_linux(
            bindings: tuple[SchedulerActivationBinding, ...],
            marker_binding: SchedulerActivationBinding | None,
        ) -> None:
            complete_bindings = (
                (*bindings, marker_binding) if marker_binding is not None else bindings
            )
            if orphan_cleanup and not dry_run:
                _query_orphan_scheduler_for_uninstall(
                    paths,
                    complete_bindings,
                    require_disabled=False,
                )
            if disable:
                _run_native_scheduler_action(
                    [
                        "systemctl",
                        "--user",
                        "disable",
                        "--now",
                        f"{SYSTEMD_UNIT}.timer",
                    ],
                    dry_run=dry_run,
                    allow_fail=NATIVE_FAILURE_ALREADY_ABSENT,
                    activation_bindings=complete_bindings,
                )
            if dry_run:
                _unlink_file(paths.systemd_timer, dry_run=True)
                _unlink_file(paths.systemd_service, dry_run=True)
            else:
                assert marker_binding is not None
                service_binding, timer_binding = bindings[:2]
                _conditionally_remove_bound_scheduler_config(
                    timer_binding,
                    boundary="before conditional scheduler timer removal",
                    related_bindings=complete_bindings,
                )
                _conditionally_remove_bound_scheduler_config(
                    service_binding,
                    boundary="before conditional scheduler service removal",
                    related_bindings=complete_bindings,
                )
            _report_preserved_systemd_drop_ins(paths)
            if disable:
                _run_native_scheduler_action(
                    ["systemctl", "--user", "daemon-reload"],
                    dry_run=dry_run,
                    activation_bindings=complete_bindings,
                )
            if orphan_cleanup and not dry_run:
                _query_orphan_scheduler_for_uninstall(
                    paths,
                    complete_bindings,
                    require_disabled=True,
                )
            if not dry_run:
                assert marker_binding is not None
                activation_binding = bindings[-1]
                _conditionally_remove_bound_scheduler_config(
                    activation_binding,
                    boundary="before conditional activation marker removal",
                    related_bindings=complete_bindings,
                )
                _commit_scheduler_uninstall_transaction(
                    marker_binding,
                    related_bindings=bindings,
                )
            else:
                _unlink_file(
                    _scheduler_activation_transaction_path(paths),
                    dry_run=True,
                )

        if dry_run:
            uninstall_linux((), None)
        else:
            with contextlib.ExitStack() as stack:
                bindings = tuple(
                    stack.enter_context(
                        _retain_launchd_activation_binding(
                            path,
                            snapshot,
                            description=description,
                            revalidate_on_exit=False,
                        )
                    )
                    for path, snapshot, description in (
                        (
                            paths.systemd_service,
                            snapshots[0],
                            "Linux systemd scheduler service",
                        ),
                        (
                            paths.systemd_timer,
                            snapshots[1],
                            "Linux systemd scheduler timer",
                        ),
                        (
                            _scheduler_activation_transaction_path(paths),
                            snapshots[2],
                            "scheduler activation transaction",
                        ),
                    )
                )
                marker_binding = _retain_scheduler_uninstall_transaction(
                    stack,
                    home,
                    paths,
                    disable=disable,
                    before=uninstall_marker_before,
                    recorded_disable=recorded_disable,
                )
                uninstall_linux(bindings, marker_binding)
        print(f"removed Linux systemd user scheduler: {paths.systemd_timer}")
        return

    raise SyncError(f"unsupported scheduler platform: {selected_platform}")


def _skill_entry_property_snapshot(
    metadata: os.stat_result,
) -> tuple[int, int, int, int, int, int]:
    """Capture identity and access policy without directory churn metadata."""
    return (
        metadata.st_dev,
        metadata.st_ino,
        stat.S_IFMT(metadata.st_mode),
        stat.S_IMODE(metadata.st_mode),
        metadata.st_uid,
        metadata.st_gid,
    )


def _read_bound_skill_manifest(
    directory_fd: int,
    display_root: Path,
) -> bytes | None:
    manifest = display_root / "SKILL.md"
    try:
        named = os.stat(
            "SKILL.md",
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError:
        return None
    except OSError as error:
        raise SyncError(f"failed to inspect skill manifest: {manifest}") from error
    if not stat.S_ISREG(named.st_mode):
        return None
    if named.st_uid != os.geteuid() or stat.S_IMODE(named.st_mode) & 0o022:
        return None
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    file_fd = -1
    try:
        file_fd = os.open(
            "SKILL.md",
            flags,
            dir_fd=directory_fd,
        )
        if not _regular_stat_metadata_matches(os.fstat(file_fd), named):
            raise SyncError(f"skill manifest changed before read: {manifest}")

        def read_once() -> bytes:
            payload = bytearray()
            while len(payload) < MAX_SKILL_FRONTMATTER_BYTES:
                chunk = os.read(
                    file_fd,
                    min(
                        64 * 1024,
                        MAX_SKILL_FRONTMATTER_BYTES - len(payload),
                    ),
                )
                if not chunk:
                    break
                payload.extend(chunk)
            return bytes(payload)

        payload = read_once()
        os.lseek(file_fd, 0, os.SEEK_SET)
        if read_once() != payload:
            raise SyncError(f"skill manifest content changed during read: {manifest}")
        current = os.stat(
            "SKILL.md",
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        if not _regular_stat_metadata_matches(
            os.fstat(file_fd), named
        ) or not _regular_stat_metadata_matches(current, named):
            raise SyncError(f"skill manifest changed during read: {manifest}")
        return payload
    except OSError as error:
        raise SyncError(f"failed to read skill manifest: {manifest}") from error
    finally:
        if file_fd >= 0:
            _close_fd_quietly(file_fd)


def _skill_frontmatter_name_from_directory_fd(
    directory_fd: int,
    skill_root: Path,
) -> tuple[bool, str | None]:
    directory_before = _skill_entry_property_snapshot(os.fstat(directory_fd))
    payload = _read_bound_skill_manifest(directory_fd, skill_root)
    if _skill_entry_property_snapshot(os.fstat(directory_fd)) != directory_before:
        raise SyncError(f"skill directory changed during audit: {skill_root}")
    if payload is None:
        return False, None
    raw_lines = payload.splitlines(keepends=True)
    if not raw_lines or raw_lines[0].strip() != b"---":
        return True, None
    closing_index = next(
        (
            index
            for index, raw_line in enumerate(raw_lines[1:], start=1)
            if raw_line.strip() == b"---"
        ),
        None,
    )
    if closing_index is None:
        return True, None
    try:
        text = b"".join(raw_lines[: closing_index + 1]).decode("utf-8")
    except UnicodeDecodeError:
        return True, None
    lines = text.splitlines()
    name: str | None = None
    for line in lines[1:]:
        if line.strip() == "---":
            return True, name
        match = re.fullmatch(r"\s*name\s*:\s*(.*?)\s*", line)
        if match is None:
            continue
        value = match.group(1)
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            value = value[1:-1]
        name = value or None
    return True, None


def _bounded_skill_child_names(directory_fd: int) -> tuple[str, ...]:
    return _directory_member_names(
        directory_fd,
        maximum_entries=MAX_ACTIVE_SKILL_ENTRIES,
        overflow_message="active skills root exceeds the entry scan limit",
    )


def _open_bound_skill_directory(
    parent_fd: int,
    name: str,
    expected: os.stat_result,
    display_path: Path,
) -> int:
    directory_fd = -1
    try:
        directory_fd = os.open(
            name,
            _directory_open_flags(nofollow=True),
            dir_fd=parent_fd,
        )
        if _skill_entry_property_snapshot(
            os.fstat(directory_fd)
        ) != _skill_entry_property_snapshot(expected):
            raise SyncError(f"skill directory changed before audit: {display_path}")
        current = os.stat(
            name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if _skill_entry_property_snapshot(current) != _skill_entry_property_snapshot(
            expected
        ):
            raise SyncError(f"skill directory changed before audit: {display_path}")
        result = directory_fd
        directory_fd = -1
        return result
    finally:
        if directory_fd >= 0:
            _close_fd_quietly(directory_fd)


def _bound_skill_entry_still_matches(
    parent_fd: int,
    name: str,
    expected: os.stat_result,
) -> bool:
    try:
        current = os.stat(
            name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
    except OSError:
        return False
    return _skill_entry_property_snapshot(current) == _skill_entry_property_snapshot(
        expected
    )


def audit_active_skills(
    home: Path,
    *,
    manifest_cache: dict[tuple[str, str], ManifestData | None] | None = None,
) -> list[DoctorIssue]:
    home = home.expanduser()
    skills_root = home / "skills"
    issues: list[DoctorIssue] = []
    try:
        state = _load_managed_state(home, manifest_cache=manifest_cache)
    except SyncError as error:
        issues.append(
            DoctorIssue(
                (
                    "immutable-release-drift"
                    if error.code == "immutable-release-drift"
                    else "generated-drift"
                ),
                _state_path(home),
                f"managed source state is invalid: {error}",
            )
        )
        state = _empty_managed_state()
    managed_skills = {
        record.target.parts[1]: record
        for record in state.links.values()
        if record.kind == "skill"
        and len(record.target.parts) == 2
        and record.target.parts[0] == "skills"
    }
    root_fd = -1
    try:
        root_fd = _open_directory_beneath(home, skills_root)
    except FileNotFoundError:
        for skill_name, record in sorted(managed_skills.items()):
            issues.append(
                DoctorIssue(
                    "generated-drift",
                    skills_root / skill_name,
                    f"managed skill root is missing for "
                    f"{record.owner}@{record.release_sha}",
                )
            )
        return issues
    except (OSError, SyncError) as error:
        return [
            DoctorIssue(
                "skills-root-unsafe",
                skills_root,
                f"active skills root is not a stable non-symlink directory: {error}",
            )
        ]

    candidates: list[tuple[Path, str | None]] = []
    observed_names: set[str] = set()
    try:
        root_names = _bounded_skill_child_names(root_fd)
    except (OSError, SyncError) as error:
        code = (
            "skills-root-overflow"
            if isinstance(error, SyncError)
            else "skills-root-unreadable"
        )
        issues.append(
            DoctorIssue(
                code,
                skills_root,
                f"active skills root cannot be listed: {error}",
            )
        )
        _close_fd_quietly(root_fd)
        return issues

    for entry_name in root_names:
        observed_names.add(entry_name)
        entry = skills_root / entry_name
        try:
            entry_metadata = os.stat(
                entry_name,
                dir_fd=root_fd,
                follow_symlinks=False,
            )
        except OSError as error:
            issues.append(
                DoctorIssue(
                    "skills-root-unreadable",
                    entry,
                    f"active skill entry cannot be inspected: {error}",
                )
            )
            continue
        if CACHE_OR_BACKUP_SKILL_NAMES.search(entry_name):
            issues.append(
                DoctorIssue(
                    "cache-or-backup",
                    entry,
                    "cache or backup directory is active in the skill discovery root",
                )
            )
        if entry_name in RESERVED_EXTERNAL_SKILL_ROOTS:
            if not stat.S_ISDIR(entry_metadata.st_mode):
                issues.append(
                    DoctorIssue(
                        "skills-root-unsafe",
                        entry,
                        "reserved skill root must be a non-symlink directory",
                    )
                )
                continue
            external_fd = -1
            try:
                external_fd = _open_bound_skill_directory(
                    root_fd,
                    entry_name,
                    entry_metadata,
                    entry,
                )
                external_names = _bounded_skill_child_names(external_fd)
            except (OSError, SyncError) as error:
                issues.append(
                    DoctorIssue(
                        (
                            "skills-root-overflow"
                            if isinstance(error, SyncError)
                            else "skills-root-unreadable"
                        ),
                        entry,
                        f"reserved skill root cannot be listed: {error}",
                    )
                )
                if external_fd >= 0:
                    _close_fd_quietly(external_fd)
                continue
            external_candidates: list[tuple[Path, str | None]] = []
            for external_name in external_names:
                external = entry / external_name
                if CACHE_OR_BACKUP_SKILL_NAMES.search(external_name):
                    issues.append(
                        DoctorIssue(
                            "cache-or-backup",
                            external,
                            "cache or backup directory is active in the "
                            "reserved skill discovery root",
                        )
                    )
                try:
                    external_metadata = os.stat(
                        external_name,
                        dir_fd=external_fd,
                        follow_symlinks=False,
                    )
                except OSError as error:
                    issues.append(
                        DoctorIssue(
                            "skills-root-unreadable",
                            external,
                            f"reserved active skill cannot be inspected: {error}",
                        )
                    )
                    continue
                if stat.S_ISLNK(external_metadata.st_mode):
                    try:
                        os.stat(
                            external_name,
                            dir_fd=external_fd,
                            follow_symlinks=True,
                        )
                    except OSError:
                        code = "broken-link"
                        detail = "reserved active skill symlink target is missing"
                    else:
                        code = "unsafe-skill-link"
                        detail = (
                            "reserved active skill symlinks are not traversed "
                            "during bounded audit"
                        )
                    issues.append(DoctorIssue(code, external, detail))
                    continue
                if not stat.S_ISDIR(external_metadata.st_mode):
                    continue
                skill_fd = -1
                try:
                    skill_fd = _open_bound_skill_directory(
                        external_fd,
                        external_name,
                        external_metadata,
                        external,
                    )
                    has_manifest, frontmatter_name = (
                        _skill_frontmatter_name_from_directory_fd(
                            skill_fd,
                            external,
                        )
                    )
                    if not _bound_skill_entry_still_matches(
                        external_fd,
                        external_name,
                        external_metadata,
                    ):
                        raise SyncError(
                            f"reserved active skill changed during audit: {external}"
                        )
                    if has_manifest:
                        external_candidates.append((external, frontmatter_name))
                except (OSError, SyncError) as error:
                    issues.append(
                        DoctorIssue(
                            "skill-audit-inconclusive",
                            external,
                            f"reserved active skill changed during audit: {error}",
                        )
                    )
                finally:
                    if skill_fd >= 0:
                        _close_fd_quietly(skill_fd)
            if not _bound_skill_entry_still_matches(
                root_fd,
                entry_name,
                entry_metadata,
            ) or _skill_entry_property_snapshot(
                os.fstat(external_fd)
            ) != _skill_entry_property_snapshot(entry_metadata):
                issues.append(
                    DoctorIssue(
                        "skills-root-unsafe",
                        entry,
                        "reserved skill root changed during audit",
                    )
                )
            else:
                candidates.extend(external_candidates)
            _close_fd_quietly(external_fd)
            continue
        record = managed_skills.get(entry_name)
        if record is not None:
            if not stat.S_ISLNK(entry_metadata.st_mode):
                issues.append(
                    DoctorIssue(
                        "generated-drift",
                        entry,
                        "managed skill is no longer a symlink",
                    )
                )
                if stat.S_ISDIR(entry_metadata.st_mode):
                    skill_fd = -1
                    try:
                        skill_fd = _open_bound_skill_directory(
                            root_fd,
                            entry_name,
                            entry_metadata,
                            entry,
                        )
                        has_manifest, frontmatter_name = (
                            _skill_frontmatter_name_from_directory_fd(
                                skill_fd,
                                entry,
                            )
                        )
                        if not _bound_skill_entry_still_matches(
                            root_fd,
                            entry_name,
                            entry_metadata,
                        ):
                            raise SyncError(
                                f"managed skill changed during audit: {entry}"
                            )
                        if has_manifest:
                            candidates.append((entry, frontmatter_name))
                    except (OSError, SyncError) as error:
                        issues.append(
                            DoctorIssue(
                                "generated-drift",
                                entry,
                                f"managed skill cannot be audited: {error}",
                            )
                        )
                    finally:
                        if skill_fd >= 0:
                            _close_fd_quietly(skill_fd)
                continue
            try:
                actual_target = os.readlink(
                    entry_name,
                    dir_fd=root_fd,
                )
            except OSError as error:
                issues.append(
                    DoctorIssue(
                        "generated-drift",
                        entry,
                        f"managed skill link cannot be read: {error}",
                    )
                )
                continue
            if actual_target != record.link_target:
                issues.append(
                    DoctorIssue(
                        "generated-drift",
                        entry,
                        "managed skill link target differs from generated state",
                    )
                )
                continue
            skill_source = (
                _releases_root(home, record.owner)
                / record.release_sha
                / Path(*record.source.parts)
            )
            skill_fd = -1
            try:
                skill_fd = _open_directory_beneath(home, skill_source)
                has_manifest, frontmatter_name = (
                    _skill_frontmatter_name_from_directory_fd(
                        skill_fd,
                        entry,
                    )
                )
                current_target = os.readlink(
                    entry_name,
                    dir_fd=root_fd,
                )
                if (
                    not _bound_skill_entry_still_matches(
                        root_fd,
                        entry_name,
                        entry_metadata,
                    )
                    or current_target != actual_target
                ):
                    raise SyncError(f"managed skill link changed during audit: {entry}")
                if not has_manifest:
                    issues.append(
                        DoctorIssue(
                            "generated-drift",
                            entry,
                            "managed skill target is not a directory with SKILL.md",
                        )
                    )
                else:
                    candidates.append((entry, frontmatter_name))
            except (OSError, SyncError) as error:
                issues.append(
                    DoctorIssue(
                        "generated-drift",
                        entry,
                        f"managed skill target cannot be audited: {error}",
                    )
                )
            finally:
                if skill_fd >= 0:
                    _close_fd_quietly(skill_fd)
            continue

        if stat.S_ISLNK(entry_metadata.st_mode):
            try:
                os.stat(
                    entry_name,
                    dir_fd=root_fd,
                    follow_symlinks=True,
                )
            except OSError:
                issues.append(
                    DoctorIssue(
                        "broken-link",
                        entry,
                        "active skill symlink target is missing",
                    )
                )
            else:
                issues.append(
                    DoctorIssue(
                        "unsafe-skill-link",
                        entry,
                        "unmanaged skill symlinks are not traversed during bounded audit",
                    )
                )
            continue
        if not stat.S_ISDIR(entry_metadata.st_mode):
            issues.append(
                DoctorIssue(
                    "unmanaged-skill-entry",
                    entry,
                    "unmanaged entry is present in the active skill discovery root",
                )
            )
            continue
        skill_fd = -1
        try:
            skill_fd = _open_bound_skill_directory(
                root_fd,
                entry_name,
                entry_metadata,
                entry,
            )
            has_manifest, frontmatter_name = _skill_frontmatter_name_from_directory_fd(
                skill_fd,
                entry,
            )
            if not _bound_skill_entry_still_matches(
                root_fd,
                entry_name,
                entry_metadata,
            ):
                raise SyncError(f"active skill changed during audit: {entry}")
        except (OSError, SyncError) as error:
            issues.append(
                DoctorIssue(
                    "skill-audit-inconclusive",
                    entry,
                    f"active skill changed during audit: {error}",
                )
            )
            continue
        finally:
            if skill_fd >= 0:
                _close_fd_quietly(skill_fd)
        if has_manifest:
            issues.append(
                DoctorIssue(
                    "unmanaged-skill",
                    entry,
                    "active skill is not claimed by personal sync state",
                )
            )
            candidates.append((entry, frontmatter_name))
        else:
            issues.append(
                DoctorIssue(
                    "unmanaged-skill-entry",
                    entry,
                    "unmanaged entry is present in the active skill discovery root",
                )
            )

    if not _bound_directory_matches(home, skills_root, root_fd):
        issues.append(
            DoctorIssue(
                "skills-root-unsafe",
                skills_root,
                "active skills root changed during audit",
            )
        )
        _close_fd_quietly(root_fd)
        return issues
    _close_fd_quietly(root_fd)

    for skill_name, record in sorted(managed_skills.items()):
        path = skills_root / skill_name
        if skill_name not in observed_names:
            issues.append(
                DoctorIssue(
                    "generated-drift",
                    path,
                    f"managed skill link is missing for {record.owner}@{record.release_sha}",
                )
            )

    names: dict[str, list[Path]] = {}
    for candidate, name in candidates:
        if name is None:
            issues.append(
                DoctorIssue(
                    "invalid-frontmatter",
                    candidate / "SKILL.md",
                    "skill frontmatter has no readable name",
                )
            )
            continue
        names.setdefault(name, []).append(candidate)
    for name, paths in sorted(names.items()):
        if len(paths) < 2:
            continue
        preview = ", ".join(str(path) for path in paths[:8])
        if len(paths) > 8:
            preview += f", ... ({len(paths) - 8} more)"
        detail = (
            f"duplicate skill frontmatter name {name} "
            f"across {len(paths)} paths: {preview}"
        )
        for path in paths:
            issues.append(
                DoctorIssue(
                    "duplicate-skill-name",
                    path,
                    detail,
                )
            )
    return issues


def _print_doctor_issues(
    issues: list[DoctorIssue],
    *,
    heading: str = "active skills discovery",
) -> None:
    if not issues:
        print(f"{heading}: ok")
        return
    print(f"{heading}: {len(issues)} issue(s)")
    for issue in issues:
        print(f"- {issue.code}: {issue.path}: {issue.detail}")


def doctor(
    home: Path,
    platform_name: str,
    *,
    json_output: bool,
) -> tuple[SchedulerReport, list[DoctorIssue]]:
    home = home.expanduser()
    report = scheduler_report(home, platform_name)
    issues = audit_active_skills(home)
    classified: set[tuple[str, str]] = set()
    if not report.installed:
        issues.append(
            DoctorIssue(
                "scheduler-not-installed",
                report.config_paths[0] if report.config_paths else home.expanduser(),
                "personal sync scheduler is not installed",
            )
        )
    if report.installed and not report.stable_runner:
        detail = "scheduler does not use the stable installed runner path"
        issues.append(
            DoctorIssue(
                "scheduler-runner-drift",
                report.runner or home.expanduser(),
                detail,
            )
        )
        classified.add(("scheduler-runner-drift", detail))
    for code, owner, sha, detail in report.release_integrity:
        issues.append(
            DoctorIssue(
                code,
                _releases_root(home, owner) / sha,
                detail,
            )
        )
        classified.add((code, detail))
    if (
        report.quarantine_batches is not None
        and report.quarantine_batches >= report.quarantine_limit
    ):
        detail = (
            "quarantine retains too many transaction batches: "
            f"{report.quarantine_batches} >= {report.quarantine_limit}"
        )
        issues.append(
            DoctorIssue(
                "quarantine-saturated",
                _personal_sync_root(home) / QUARANTINE_RELATIVE_PATH,
                detail,
            )
        )
        classified.add(("quarantine-saturated", detail))
    if (
        report.mirror_quarantine is not None
        and report.mirror_quarantine.classification in {"saturated", "inconclusive"}
    ):
        issue_code = (
            "mirror-quarantine-saturated"
            if report.mirror_quarantine.classification == "saturated"
            else (
                report.mirror_quarantine.reason_code
                or "mirror-quarantine-audit-inconclusive"
            )
        )
        detail = _mirror_quarantine_failure_detail(report.mirror_quarantine)
        issues.append(
            DoctorIssue(
                issue_code,
                report.mirror_quarantine.path,
                detail,
            )
        )
        classified.add((issue_code, detail))
    for failure_code, failure_reason in _scheduler_report_failures(report):
        issue_code = (
            failure_code
            if failure_code
            in {
                "immutable-release-drift",
                "mirror-quarantine-saturated",
                "mirror-quarantine-audit-inconclusive",
                MIRROR_PRIVATE_OWNER_RECORD_REASON_ROOT_MISMATCH,
                "legacy-recovery-pending",
                "private-control-root-inconclusive",
                "quarantine-saturated",
                "quarantine-audit-inconclusive",
                "scheduler-config-drift",
                "scheduler-daemon-unavailable",
                "scheduler-daemon-disabled",
                "scheduler-orphan-active",
                "scheduler-runner-drift",
                "scheduler-activation-incomplete",
                "scheduler-activation-state-invalid",
                "scheduler-uninstall-incomplete",
                "scheduler-uninstall-state-invalid",
            }
            else "scheduler-failure"
        )
        if (issue_code, failure_reason) not in classified:
            issues.append(
                DoctorIssue(
                    issue_code,
                    (
                        (
                            report.mirror_quarantine.path
                            if report.mirror_quarantine is not None
                            else Path(os.path.abspath(MIRROR_PRIVATE_CONTROL_PARENT))
                            / MIRROR_DURABLE_QUARANTINE_ROOT_NAME
                        )
                        if issue_code.startswith("mirror-quarantine-")
                        or issue_code
                        in {
                            MIRROR_PRIVATE_OWNER_RECORD_REASON_ROOT_MISMATCH,
                            MIRROR_PRIVATE_CONTROL_REASON_LEGACY_PENDING,
                            MIRROR_PRIVATE_CONTROL_REASON_INCONCLUSIVE,
                        }
                        else (_personal_sync_root(home) / QUARANTINE_RELATIVE_PATH)
                        if issue_code.startswith("quarantine-")
                        else (
                            _scheduler_activation_transaction_path(
                                _scheduler_paths(report.platform, home)
                            )
                            if issue_code.startswith("scheduler-activation-")
                            else (
                                _scheduler_uninstall_transaction_path(
                                    _scheduler_paths(report.platform, home)
                                )
                                if issue_code.startswith("scheduler-uninstall-")
                                else (
                                    report.config_paths[0]
                                    if report.config_paths
                                    else home
                                )
                            )
                        )
                    ),
                    failure_reason,
                )
            )
            classified.add((issue_code, failure_reason))
    if json_output:
        payload = {
            "scheduler": _scheduler_report_payload(report),
            "issues": [
                {
                    "code": issue.code,
                    "path": str(issue.path),
                    "detail": issue.detail,
                }
                for issue in issues
            ],
        }
        print(json.dumps(payload, indent=2, sort_keys=True))
    else:
        _print_scheduler_report(report)
        _print_doctor_issues(issues, heading="doctor")
    return report, issues


def _scheduler_status_path(home: Path) -> Path:
    return _personal_sync_root(home) / SCHEDULER_STATUS_RELATIVE_PATH


def _scheduler_runtime_publication_name_key(name: str) -> str:
    return unicodedata.normalize("NFC", name).casefold()


def _scheduler_runtime_publication_is_incomplete(
    home: Path,
    status_path: Path,
    parent_fd: int,
) -> bool:
    marker_path = _scheduler_runtime_publication_marker_path(status_path)
    if not _bound_directory_matches(home, status_path.parent, parent_fd):
        raise SyncError(f"scheduler runtime state parent changed: {status_path}")
    try:
        os.stat(
            marker_path.name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
    except FileNotFoundError:
        canonical_marker_present = False
    except OSError as error:
        raise SyncError(
            f"scheduler runtime publication evidence is unreadable: {marker_path}",
            code="scheduler-state-publication-incomplete",
        ) from error
    else:
        canonical_marker_present = True
    try:
        names = _directory_member_names(
            parent_fd,
            maximum_entries=MAX_ACTIVE_SKILL_ENTRIES,
            overflow_message=(
                "scheduler runtime state directory exceeds the scan limit"
            ),
        )
    except (OSError, SyncError) as error:
        raise SyncError(
            f"scheduler runtime publication evidence is unreadable: {marker_path}",
            code="scheduler-state-publication-incomplete",
        ) from error
    if not _bound_directory_matches(home, status_path.parent, parent_fd):
        raise SyncError(f"scheduler runtime state parent changed: {status_path}")
    transaction_prefix = f".{status_path.name}.personal-sync-write-"
    retained_marker_prefix = f"{PENDING_CLEANUP_RETAINED_PREFIX}{marker_path.name}-"
    retained_transaction_prefix = (
        f"{PENDING_CLEANUP_RETAINED_PREFIX}{transaction_prefix}"
    )
    marker_key = _scheduler_runtime_publication_name_key(marker_path.name)
    protected_prefix_keys = tuple(
        _scheduler_runtime_publication_name_key(prefix)
        for prefix in (
            transaction_prefix,
            retained_marker_prefix,
            retained_transaction_prefix,
        )
    )
    protected_spellings: dict[str, str] = {}
    publication_incomplete = canonical_marker_present
    for name in names:
        portable_name = _scheduler_runtime_publication_name_key(name)
        protected = portable_name == marker_key or portable_name.startswith(
            protected_prefix_keys
        )
        if not protected:
            continue
        previous = protected_spellings.get(portable_name)
        if previous is not None and previous != name:
            raise SyncError(
                "scheduler runtime publication evidence has ambiguous "
                f"portable aliases: {marker_path}",
                code="scheduler-state-publication-incomplete",
            )
        protected_spellings[portable_name] = name
        publication_incomplete = True
    return publication_incomplete


def _reject_incomplete_scheduler_runtime_publication(
    home: Path,
    status_path: Path,
    parent_fd: int,
) -> None:
    if _scheduler_runtime_publication_is_incomplete(
        home,
        status_path,
        parent_fd,
    ):
        raise SyncError(
            "scheduler runtime state has an unresolved publication marker: "
            f"{_scheduler_runtime_publication_marker_path(status_path)}",
            code="scheduler-state-publication-incomplete",
        )


def _parse_scheduler_utc_timestamp(
    value: object,
    field_name: str,
    *,
    now: datetime,
) -> datetime | None:
    if value is None:
        return None
    if (
        not isinstance(value, str)
        or re.fullmatch(
            r"[0-9]{4}-[0-9]{2}-[0-9]{2}T"
            r"[0-9]{2}:[0-9]{2}:[0-9]{2}"
            r"(?:\.[0-9]{6})?\+00:00",
            value,
        )
        is None
    ):
        raise SyncError(
            f"scheduler runtime state {field_name} is not canonical UTC",
            code="scheduler-state-timestamp-invalid",
        )
    try:
        parsed = datetime.fromisoformat(value)
        upper_bound = now + MAX_SCHEDULER_ATTEMPT_FUTURE_SKEW
    except (OverflowError, ValueError) as error:
        raise SyncError(
            f"scheduler runtime state {field_name} is invalid",
            code="scheduler-state-timestamp-invalid",
        ) from error
    if (
        parsed.tzinfo is None
        or parsed.utcoffset() != timedelta(0)
        or parsed.isoformat() != value
        or parsed > upper_bound
    ):
        raise SyncError(
            f"scheduler runtime state {field_name} is invalid",
            code="scheduler-state-timestamp-invalid",
        )
    return parsed


def _read_scheduler_runtime_state_with_snapshot(
    home: Path,
    *,
    recover_timestamps: bool = False,
) -> tuple[dict[str, Any] | None, ManagedStateFileSnapshot]:
    path = _scheduler_status_path(home)
    if not _ensure_safe_internal_parent(
        home,
        path,
        create=False,
        allow_missing=True,
    ):
        return None, ManagedStateFileSnapshot(exists=False)
    parent_fd = _open_directory_beneath(home, path.parent)
    try:
        _reject_incomplete_scheduler_runtime_publication(
            home,
            path,
            parent_fd,
        )
        snapshot = _read_managed_state_file_snapshot(home, path, parent_fd)
        _reject_incomplete_scheduler_runtime_publication(
            home,
            path,
            parent_fd,
        )
    finally:
        _close_fd_quietly(parent_fd)
    if not snapshot.exists:
        return None, snapshot
    if (
        snapshot.payload is None
        or len(snapshot.payload) > MAX_SCHEDULER_STATUS_BYTES
        or snapshot.mode != 0o600
    ):
        raise SyncError(f"scheduler runtime state is invalid: {path}")
    data = _decode_managed_state_json(snapshot.payload, path)
    version_one_fields = {
        "version",
        "last_attempt",
        "last_success",
        "success",
        "failure_reason",
        "mode",
        "repo",
        "base_repo",
        "owner",
    }
    version_two_fields = version_one_fields | {
        "failure_code",
        "release_trees",
    }
    if data.get("version") == 1 and set(data) == version_one_fields:
        data = dict(data)
        data["version"] = 2
        data["failure_code"] = None
        data["release_trees"] = {}
    elif data.get("version") != 2 or set(data) != version_two_fields:
        raise SyncError(f"scheduler runtime state has unsupported fields: {path}")
    for field in (
        "last_attempt",
        "last_success",
        "failure_reason",
        "base_repo",
        "owner",
    ):
        if data.get(field) is not None and not isinstance(data.get(field), str):
            raise SyncError(f"scheduler runtime state {field} is invalid")
    if not isinstance(data.get("success"), bool):
        raise SyncError("scheduler runtime state success is invalid")
    failure_code = data.get("failure_code")
    if failure_code is not None and (
        not isinstance(failure_code, str)
        or re.fullmatch(r"[a-z][a-z0-9-]{0,63}", failure_code) is None
    ):
        raise SyncError("scheduler runtime state failure_code is invalid")
    raw_release_trees = data.get("release_trees")
    if (
        not isinstance(raw_release_trees, dict)
        or len(raw_release_trees) > MAX_PENDING_RELEASES
    ):
        raise SyncError("scheduler runtime state release_trees is invalid")
    release_trees: dict[str, dict[str, str]] = {}
    for raw_owner, raw_evidence in raw_release_trees.items():
        release_owner = _validate_owner(
            raw_owner,
            "scheduler runtime release owner",
        )
        if not isinstance(raw_evidence, dict) or set(raw_evidence) != {
            "sha",
            "tree_sha256",
        }:
            raise SyncError("scheduler runtime release evidence is invalid")
        release_sha = raw_evidence.get("sha")
        tree_sha256 = raw_evidence.get("tree_sha256")
        if (
            not isinstance(release_sha, str)
            or RELEASE_DIR_RE.fullmatch(release_sha) is None
            or not isinstance(tree_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", tree_sha256) is None
        ):
            raise SyncError("scheduler runtime release evidence is invalid")
        release_trees[release_owner] = {
            "sha": release_sha,
            "tree_sha256": tree_sha256,
        }
    data["release_trees"] = dict(sorted(release_trees.items()))
    if data.get("mode") not in {"public", "private"}:
        raise SyncError("scheduler runtime state mode is invalid")
    repo = data.get("repo")
    if not isinstance(repo, str) or REPOSITORY_RE.fullmatch(repo) is None:
        raise SyncError("scheduler runtime state repo is invalid")
    base_repo = data.get("base_repo")
    if base_repo is not None and REPOSITORY_RE.fullmatch(base_repo) is None:
        raise SyncError("scheduler runtime state base_repo is invalid")
    owner = data.get("owner")
    if owner is not None:
        _validate_owner(owner, "scheduler runtime state owner")
    now = datetime.now(timezone.utc)
    try:
        last_attempt = _parse_scheduler_utc_timestamp(
            data.get("last_attempt"),
            "last_attempt",
            now=now,
        )
        last_success = _parse_scheduler_utc_timestamp(
            data.get("last_success"),
            "last_success",
            now=now,
        )
        if last_success is not None and (
            last_attempt is None or last_success > last_attempt
        ):
            raise SyncError(
                "scheduler runtime state last_success exceeds last_attempt",
                code="scheduler-state-timestamp-invalid",
            )
        if data["success"] and last_success != last_attempt:
            raise SyncError(
                "successful scheduler runtime state has mismatched timestamps",
                code="scheduler-state-timestamp-invalid",
            )
    except SyncError as error:
        if not recover_timestamps or error.code != "scheduler-state-timestamp-invalid":
            raise
        data = dict(data)
        data["last_attempt"] = None
        data["last_success"] = None
        data["success"] = False
        data["failure_reason"] = "invalid scheduler timestamp was recovered"
        data["failure_code"] = "scheduler-state-timestamp-recovered"
        data["release_trees"] = {}
    return data, snapshot


def _read_scheduler_runtime_state(
    home: Path,
    *,
    recover_timestamps: bool = False,
) -> dict[str, Any] | None:
    state, _snapshot = _read_scheduler_runtime_state_with_snapshot(
        home,
        recover_timestamps=recover_timestamps,
    )
    return state


def _write_scheduler_runtime_state(
    home: Path,
    data: dict[str, Any],
    *,
    expected_snapshot: ManagedStateFileSnapshot | None = None,
) -> None:
    path = _scheduler_status_path(home)
    payload = _bounded_json_document(
        data,
        max_bytes=MAX_SCHEDULER_STATUS_BYTES,
        overflow_error="scheduler runtime state exceeds the size limit",
    )
    _ensure_safe_internal_directory(home, path.parent, create=True)
    if expected_snapshot is None:
        parent_fd = _open_directory_beneath(home, path.parent)
        try:
            expected_snapshot = _read_managed_state_file_snapshot(
                home,
                path,
                parent_fd,
                maximum_bytes=MAX_SCHEDULER_STATUS_BYTES,
            )
        finally:
            _close_fd_quietly(parent_fd)
    _atomic_write_scheduler_config(
        path,
        payload,
        expected_snapshot=expected_snapshot,
        mode=0o600,
        rollback_displaced_conflict=True,
    )


def _scheduler_runtime_payload(
    *,
    previous: dict[str, Any] | None,
    attempt: str,
    success: bool,
    failure_reason: str | None,
    failure_code: str | None = None,
    release_trees: dict[str, dict[str, str]] | None = None,
    mode: str,
    repo: str,
    base_repo: str | None,
    owner: str | None,
) -> dict[str, Any]:
    same_target = (
        previous is not None
        and previous.get("mode") == mode
        and previous.get("repo") == repo
        and previous.get("base_repo") == base_repo
        and previous.get("owner") == owner
    )
    attempt_time = _parse_scheduler_utc_timestamp(
        attempt,
        "attempt",
        now=datetime.now(timezone.utc),
    )
    assert attempt_time is not None
    previous_success: str | None = None
    if same_target and previous is not None:
        candidate_success = previous.get("last_success")
        try:
            candidate_success_time = _parse_scheduler_utc_timestamp(
                candidate_success,
                "last_success",
                now=attempt_time,
            )
        except SyncError:
            candidate_success_time = None
        if (
            candidate_success_time is not None
            and candidate_success_time <= attempt_time
            and isinstance(candidate_success, str)
        ):
            previous_success = candidate_success
    if release_trees is None:
        previous_release_trees = (
            previous.get("release_trees", {})
            if previous_success is not None and previous is not None
            else {}
        )
        release_trees = (
            previous_release_trees if isinstance(previous_release_trees, dict) else {}
        )
    return {
        "version": 2,
        "last_attempt": attempt,
        "last_success": attempt if success else previous_success,
        "success": success,
        "failure_reason": failure_reason,
        "failure_code": failure_code,
        "release_trees": dict(sorted(release_trees.items())),
        "mode": mode,
        "repo": repo,
        "base_repo": base_repo,
        "owner": owner,
    }


def _validated_previous_scheduler_attempt(
    value: object,
    *,
    now: datetime,
) -> datetime | None:
    """Return a bounded canonical UTC attempt or reject it as stale metadata."""
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value)
        offset = parsed.utcoffset()
    except (OverflowError, ValueError):
        return None
    if parsed.tzinfo is None or offset != timedelta(0) or parsed.isoformat() != value:
        return None
    try:
        upper_bound = now + MAX_SCHEDULER_ATTEMPT_FUTURE_SKEW
        incrementable_limit = datetime.max.replace(
            tzinfo=timezone.utc,
        ) - timedelta(microseconds=1)
    except OverflowError:
        return None
    if parsed > upper_bound or parsed > incrementable_limit:
        return None
    return parsed


def _next_scheduler_attempt(previous: dict[str, Any] | None) -> str:
    """Return a canonical UTC attempt token safe for equality-based CAS."""
    selected = datetime.now(timezone.utc)
    previous_attempt = previous.get("last_attempt") if previous is not None else None
    previous_time = _validated_previous_scheduler_attempt(
        previous_attempt,
        now=selected,
    )
    if previous_time is not None and previous_time >= selected:
        selected = previous_time + timedelta(microseconds=1)
    attempt = selected.isoformat()
    if attempt == previous_attempt:
        attempt = (selected + timedelta(microseconds=1)).isoformat()
    return attempt


def _scheduler_runtime_target_matches(
    state: dict[str, Any],
    *,
    mode: str,
    repo: str,
    base_repo: str | None,
    owner: str | None,
) -> bool:
    return (
        state.get("mode") == mode
        and state.get("repo") == repo
        and state.get("base_repo") == base_repo
        and state.get("owner") == owner
    )


def _revalidate_active_scheduler_attempt_unlocked(home: Path) -> None:
    guard = _ACTIVE_SCHEDULER_ATTEMPT.get()
    if guard is None:
        return
    if _sync_home_binding_key(home) != guard.home_key:
        raise SyncError(
            "scheduled sync attempted to mutate a different installation home",
            code="scheduled-sync-attempt-home-mismatch",
        )
    current, _state_snapshot = _read_scheduler_runtime_state_with_snapshot(home)
    if (
        current is None
        or current.get("last_attempt") != guard.attempt
        or not _scheduler_runtime_target_matches(
            current,
            mode=guard.mode,
            repo=guard.repo,
            base_repo=guard.base_repo,
            owner=guard.owner,
        )
    ):
        raise SyncError(
            "scheduled sync attempt was superseded before installation",
            code="scheduled-sync-superseded",
        )


def _begin_scheduler_attempt(
    home: Path,
    *,
    mode: str,
    repo: str,
    base_repo: str | None,
    owner: str | None,
) -> str:
    # The existing per-Codex-home install lock is the scheduler-state compare
    # and swap boundary. It makes attempt allocation monotonic across processes
    # without holding a global lock during network or installation work.
    with installation_lock(home):
        previous, state_snapshot = _read_scheduler_runtime_state_with_snapshot(
            home,
            recover_timestamps=True,
        )
        attempt = _next_scheduler_attempt(previous)
        _write_scheduler_runtime_state(
            home,
            _scheduler_runtime_payload(
                previous=previous,
                attempt=attempt,
                success=False,
                failure_reason="scheduled sync did not complete",
                failure_code="scheduled-sync-incomplete",
                mode=mode,
                repo=repo,
                base_repo=base_repo,
                owner=owner,
            ),
            expected_snapshot=state_snapshot,
        )
    return attempt


def _complete_scheduler_attempt(
    home: Path,
    *,
    attempt: str,
    success: bool,
    failure_reason: str | None,
    failure_code: str | None,
    release_trees: dict[str, dict[str, str]] | None = None,
    mode: str,
    repo: str,
    base_repo: str | None,
    owner: str | None,
) -> bool:
    # Compare and publish while holding the same per-home lock used to allocate
    # attempts. A completion from an older overlapping run never replaces the
    # state of the currently recorded attempt.
    with installation_lock(home):
        current, state_snapshot = _read_scheduler_runtime_state_with_snapshot(home)
        if (
            current is None
            or current.get("last_attempt") != attempt
            or not _scheduler_runtime_target_matches(
                current,
                mode=mode,
                repo=repo,
                base_repo=base_repo,
                owner=owner,
            )
        ):
            print(
                "scheduled sync attempt was superseded; "
                f"left newer runtime state unchanged: {attempt}"
            )
            return False
        _write_scheduler_runtime_state(
            home,
            _scheduler_runtime_payload(
                previous=current,
                attempt=attempt,
                success=success,
                failure_reason=failure_reason,
                failure_code=failure_code,
                release_trees=release_trees,
                mode=mode,
                repo=repo,
                base_repo=base_repo,
                owner=owner,
            ),
            expected_snapshot=state_snapshot,
        )
    return True


def _capture_scheduler_release_trees(
    home: Path,
    *,
    mode: str,
    owner: str,
) -> dict[str, dict[str, str]]:
    expected_owner_uid = os.geteuid() if sys.platform == "darwin" else None
    owners = [PUBLIC_OWNER]
    if mode == "private":
        owners.append(owner)
    initial_shas: dict[str, str] = {}
    for release_owner in owners:
        sha = _current_sha(
            home,
            release_owner,
            release_identity_owner_uid=expected_owner_uid,
        )
        if sha is None:
            raise SyncError(
                f"scheduler current release is missing for owner {release_owner}",
                code="current-release-unverifiable",
            )
        initial_shas[release_owner] = sha
    initial_expectations: dict[str, ReleaseTreeDirectoryEvidence] = {}
    for release_owner in owners:
        sha = initial_shas[release_owner]
        initial_expectations[release_owner] = (
            _installed_release_identity_and_directory_evidence(
                home,
                release_owner,
                sha,
                release_identity_owner_uid=expected_owner_uid,
            )
        )
    terminal_expectations: dict[str, ReleaseTreeDirectoryEvidence] = {}
    for release_owner in owners:
        sha = initial_shas[release_owner]
        terminal_expectations[release_owner] = (
            _installed_release_identity_and_directory_evidence(
                home,
                release_owner,
                sha,
                release_identity_owner_uid=expected_owner_uid,
            )
        )
    for release_owner in owners:
        sha = initial_shas[release_owner]
        if terminal_expectations[release_owner] != initial_expectations[release_owner]:
            raise SyncError(
                "scheduler release tree changed during identity validation: "
                f"{release_owner}@{sha}",
                code="current-release-unverifiable",
            )
    validation_expectations: dict[str, ReleaseTreeDirectoryEvidence] = {}
    for release_owner in owners:
        sha = initial_shas[release_owner]
        validation_expectations[release_owner] = (
            _installed_release_identity_and_directory_evidence(
                home,
                release_owner,
                sha,
                release_identity_owner_uid=expected_owner_uid,
            )
        )
    for release_owner in owners:
        sha = initial_shas[release_owner]
        if (
            validation_expectations[release_owner]
            != terminal_expectations[release_owner]
        ):
            raise SyncError(
                "scheduler release tree changed during identity validation: "
                f"{release_owner}@{sha}",
                code="current-release-unverifiable",
            )
    evidence: dict[str, dict[str, str]] = {}
    for release_owner in owners:
        sha = initial_shas[release_owner]
        terminal_identity, _directory_identity_value, _directory_access_policy = (
            terminal_expectations[release_owner]
        )
        evidence[release_owner] = {
            "sha": sha,
            "tree_sha256": terminal_identity[2],
        }
    final_shas = {
        release_owner: _current_sha(
            home,
            release_owner,
            release_identity_owner_uid=expected_owner_uid,
        )
        for release_owner in owners
    }
    if final_shas != initial_shas:
        raise SyncError(
            "scheduler current release changed during identity validation",
            code="current-release-unverifiable",
        )
    return dict(sorted(evidence.items()))


def release_identities(
    home: Path,
    *,
    mode: str,
    owner: str,
) -> dict[str, Any]:
    home = home.expanduser()
    if mode not in {"public", "private"}:
        raise SyncError(f"unsupported release identity mode: {mode}")
    owner = _validate_owner(owner)
    if mode == "public":
        owner = PUBLIC_OWNER
    elif owner == PUBLIC_OWNER:
        raise SyncError("private release identity owner must not be public")
    try:
        lock = installation_lock(home, create=False)
        with lock:
            releases = _capture_scheduler_release_trees(
                home,
                mode=mode,
                owner=owner,
            )
    except (FileNotFoundError, OSError) as error:
        raise SyncError(
            "release identity state is unavailable",
            code="current-release-unverifiable",
        ) from error
    expected_owners = {PUBLIC_OWNER, owner} if mode == "private" else {PUBLIC_OWNER}
    if set(releases) != expected_owners:
        raise SyncError(
            "active release identity owner set is incomplete",
            code="current-release-unverifiable",
        )
    return {
        "version": 1,
        "mode": mode,
        "release_trees": releases,
    }


def run_scheduled(
    home: Path,
    repo: str,
    *,
    mode: str,
    base_repo: str,
    owner: str,
) -> None:
    home = home.expanduser()
    if mode not in {"public", "private"}:
        raise SyncError(f"unsupported scheduler mode: {mode}")
    if REPOSITORY_RE.fullmatch(repo) is None:
        raise SyncError("scheduler repository must be an owner/repo string")
    owner = _validate_owner(owner)
    if mode == "private":
        if owner == PUBLIC_OWNER:
            raise SyncError("private scheduler owner must not be public")
        if REPOSITORY_RE.fullmatch(base_repo) is None:
            raise SyncError("scheduler base repository must be an owner/repo string")
        effective_base_repo: str | None = base_repo
        effective_owner: str | None = owner
    else:
        effective_base_repo = repo
        effective_owner = PUBLIC_OWNER
    attempt = _begin_scheduler_attempt(
        home,
        mode=mode,
        repo=repo,
        base_repo=effective_base_repo,
        owner=effective_owner,
    )
    guard = SchedulerAttemptGuard(
        home_key=_sync_home_binding_key(home),
        attempt=attempt,
        mode=mode,
        repo=repo,
        base_repo=effective_base_repo,
        owner=effective_owner,
    )
    try:
        guard_token = _ACTIVE_SCHEDULER_ATTEMPT.set(guard)
        try:
            if mode == "public":
                install_from_github(repo, home, dry_run=False)
            else:
                install_private_from_github(
                    repo,
                    home,
                    base_repo=base_repo,
                    owner=owner,
                    dry_run=False,
                )
        finally:
            _ACTIVE_SCHEDULER_ATTEMPT.reset(guard_token)
        release_trees = _capture_scheduler_release_trees(
            home,
            mode=mode,
            owner=owner,
        )
    except SyncError as error:
        _complete_scheduler_attempt(
            home,
            attempt=attempt,
            success=False,
            failure_reason=str(error)[:4096],
            failure_code=error.code,
            mode=mode,
            repo=repo,
            base_repo=effective_base_repo,
            owner=effective_owner,
        )
        raise
    _complete_scheduler_attempt(
        home,
        attempt=attempt,
        success=True,
        failure_reason=None,
        failure_code=None,
        release_trees=release_trees,
        mode=mode,
        repo=repo,
        base_repo=effective_base_repo,
        owner=effective_owner,
    )


def _current_releases_for_scheduler(
    home: Path,
    config: SchedulerConfig | None,
) -> tuple[tuple[str, str], ...]:
    if config is None:
        return ()
    owners = [PUBLIC_OWNER]
    if config.mode == "private" and config.owner is not None:
        owners.append(config.owner)
    releases: list[tuple[str, str]] = []
    for owner in owners:
        sha = _current_sha(home, owner)
        if sha is None:
            raise SyncError(
                f"required scheduler current release is missing for owner {owner}",
                code="current-release-missing",
            )
        releases.append((owner, sha))
    return tuple(releases)


def _stable_scheduler_runner_matches(
    home: Path,
    config: SchedulerConfig | None,
) -> bool:
    if config is None:
        return False
    stable_path = _scheduler_runner(home, None)
    if (
        config.runner != stable_path
        or config.command != "run-scheduled"
        or config.home != home
    ):
        return False
    runner_parent_fd = -1
    source_parent_fd = -1
    try:
        runner_parent_fd = _open_directory_beneath(home, stable_path.parent)
        metadata = os.stat(
            stable_path.name,
            dir_fd=runner_parent_fd,
            follow_symlinks=False,
        )
        if not stat.S_ISLNK(metadata.st_mode):
            return False
        expected_link_snapshot = _managed_state_metadata_snapshot(metadata)
        actual_target = os.readlink(
            stable_path.name,
            dir_fd=runner_parent_fd,
        )
        state = _load_managed_state(home)
        records = [
            record
            for record in state.links.values()
            if record.target == PurePosixPath("bin/codex-personal-sync")
        ]
        if len(records) != 1:
            return False
        record = records[0]
        if (
            record.link_target != actual_target
            or state.owners.get(record.owner) != record.release_sha
        ):
            return False
        source_path = (
            _releases_root(home, record.owner)
            / record.release_sha
            / Path(*record.source.parts)
        )
        source_parent_fd = _open_directory_beneath(home, source_path.parent)
        source = _read_managed_state_file_snapshot(
            home,
            source_path,
            source_parent_fd,
        )
        if (
            not _managed_state_snapshot_has_complete_file_evidence(source)
            or source.file_type != stat.S_IFREG
            or source.uid != os.geteuid()
            or source.mode is None
            or source.mode & 0o022
            or source.mode & 0o111 == 0
            or source.size is None
            or source.size > MAX_SCHEDULER_RUNNER_BYTES
        ):
            return False
        current_metadata = os.stat(
            stable_path.name,
            dir_fd=runner_parent_fd,
            follow_symlinks=False,
        )
        current_target = os.readlink(
            stable_path.name,
            dir_fd=runner_parent_fd,
        )
        return (
            _managed_state_metadata_snapshot(current_metadata) == expected_link_snapshot
            and current_target == actual_target
            and _bound_directory_matches(
                home,
                stable_path.parent,
                runner_parent_fd,
            )
            and _bound_directory_matches(
                home,
                source_path.parent,
                source_parent_fd,
            )
        )
    except (OSError, SyncError):
        return False
    finally:
        if source_parent_fd >= 0:
            _close_fd_quietly(source_parent_fd)
        if runner_parent_fd >= 0:
            _close_fd_quietly(runner_parent_fd)


def _scheduler_release_integrity_issues(
    home: Path,
    current_releases: tuple[tuple[str, str], ...],
    baseline: dict[str, dict[str, str]] | None = None,
) -> tuple[tuple[str, str, str, str], ...]:
    baseline = baseline or {}
    issues: list[tuple[str, str, str, str]] = []
    for owner, sha in current_releases:
        try:
            _payload, _manifest, tree_sha256 = _installed_release_identity(
                home,
                owner,
                sha,
            )
        except SyncError as error:
            code = (
                "immutable-release-drift"
                if error.code == "immutable-release-drift"
                else "immutable-release-unverifiable"
            )
            issues.append((code, owner, sha, str(error)))
            continue
        expected = baseline.get(owner)
        if expected is None or expected.get("sha") != sha:
            issues.append(
                (
                    "immutable-release-baseline-missing",
                    owner,
                    sha,
                    "no verified scheduler baseline exists for the current "
                    f"release {owner}@{sha}",
                )
            )
            continue
        if expected.get("tree_sha256") != tree_sha256:
            issues.append(
                (
                    "immutable-release-drift",
                    owner,
                    sha,
                    "installed release tree digest differs from the last "
                    f"verified scheduler baseline for {owner}@{sha}",
                )
            )
    return tuple(issues)


def _mirror_object_identity(metadata: os.stat_result) -> tuple[int, int, int]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        stat.S_IFMT(metadata.st_mode),
    )


def _mirror_access_policy(metadata: os.stat_result) -> tuple[int, int, int]:
    return (
        stat.S_IMODE(metadata.st_mode),
        metadata.st_uid,
        metadata.st_gid,
    )


def _release_mirror_descriptors_best_effort(
    descriptors: tuple[tuple[str, int, bool], ...],
) -> tuple[str, ...]:
    errors: list[str] = []
    released_fds: set[int] = set()
    for label, descriptor, unlock_attempted in descriptors:
        if descriptor < 0 or descriptor in released_fds:
            continue
        released_fds.add(descriptor)
        if unlock_attempted:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            except OSError as error:
                errors.append(f"cannot release {label}: {error}")
        try:
            os.close(descriptor)
        except OSError as error:
            errors.append(f"cannot close {label}: {error}")
    return tuple(errors)


def _raise_sync_with_secondary_cleanup(
    primary_error: BaseException,
    label: str,
    cleanup_errors: tuple[str, ...] | list[str],
) -> NoReturn:
    if cleanup_errors:
        raise SyncError(
            f"{primary_error}; secondary {label}: " + "; ".join(cleanup_errors)
        ) from primary_error
    raise primary_error


@contextlib.contextmanager
def _mirror_descriptor_cleanup_scope(
    descriptors: Callable[[], tuple[tuple[str, int, bool], ...]],
    *,
    label: str,
) -> Iterator[None]:
    try:
        yield
    except (OSError, SyncError) as error:
        cleanup_errors = _release_mirror_descriptors_best_effort(descriptors())
        _raise_sync_with_secondary_cleanup(error, label, cleanup_errors)
    else:
        cleanup_errors = _release_mirror_descriptors_best_effort(descriptors())
        if cleanup_errors:
            raise SyncError(f"{label}: " + "; ".join(cleanup_errors))


def _bind_mirror_audit_directory(
    path: Path,
    label: str,
) -> tuple[int, tuple[int, int, int], tuple[int, int, int]]:
    path = Path(os.path.abspath(path))
    try:
        path_metadata = os.stat(path, follow_symlinks=False)
    except OSError as error:
        raise SyncError(f"cannot inspect {label}: {path}: {error}") from error
    if stat.S_ISLNK(path_metadata.st_mode) or not stat.S_ISDIR(path_metadata.st_mode):
        raise SyncError(f"{label} must be a non-symlink directory: {path}")
    try:
        directory_fd = os.open(path, _source_directory_flags())
    except OSError as error:
        raise SyncError(f"cannot safely open {label}: {path}: {error}") from error
    try:
        descriptor_metadata = os.fstat(directory_fd)
    except OSError as error:
        close_errors = _release_mirror_descriptors_best_effort(
            ((label, directory_fd, False),)
        )
        _raise_sync_with_secondary_cleanup(
            SyncError(f"cannot inspect the bound {label}: {path}: {error}"),
            f"{label} bind cleanup failures",
            close_errors,
        )
    if _mirror_object_identity(path_metadata) != _mirror_object_identity(
        descriptor_metadata
    ) or _mirror_access_policy(path_metadata) != _mirror_access_policy(
        descriptor_metadata
    ):
        close_errors = _release_mirror_descriptors_best_effort(
            ((label, directory_fd, False),)
        )
        _raise_sync_with_secondary_cleanup(
            SyncError(f"{label} changed while binding it: {path}"),
            f"{label} bind cleanup failures",
            close_errors,
        )
    return (
        directory_fd,
        _mirror_object_identity(descriptor_metadata),
        _mirror_access_policy(descriptor_metadata),
    )


def _bind_mirror_trusted_account_home(
    path: Path,
) -> tuple[int, tuple[int, int, int], tuple[int, int, int]]:
    path = Path(os.path.abspath(path))
    if not path.is_absolute() or path == Path("/"):
        raise SyncError("canonical account home must be an absolute child path")
    components = path.parts[1:]
    if not components or len(components) > MIRROR_PRIVATE_CONTROL_MAX_ANCESTORS:
        raise SyncError("canonical account home exceeds its ancestor limit")
    current_path = Path("/")
    current_fd = os.open(current_path, _source_directory_flags())
    try:
        for component in components:
            child_fd = -1
            try:
                path_metadata = os.stat(
                    component,
                    dir_fd=current_fd,
                    follow_symlinks=False,
                )
                if not stat.S_ISDIR(path_metadata.st_mode):
                    raise SyncError(
                        "canonical account-home ancestors must be non-symlink "
                        f"directories: {current_path / component}"
                    )
                child_fd = os.open(
                    component,
                    _source_directory_flags(),
                    dir_fd=current_fd,
                )
                child_metadata = os.fstat(child_fd)
                if _mirror_object_identity(path_metadata) != _mirror_object_identity(
                    child_metadata
                ) or _mirror_access_policy(path_metadata) != _mirror_access_policy(
                    child_metadata
                ):
                    raise SyncError(
                        "canonical account-home ancestor changed while binding it: "
                        f"{current_path / component}"
                    )
                mode, uid, _gid = _mirror_access_policy(child_metadata)
                if uid not in {0, os.geteuid()} or mode & 0o022:
                    raise SyncError(
                        "canonical account-home ancestors must be root/current-owned "
                        "and not group/world writable: "
                        f"{current_path / component}"
                    )
            except OSError as error:
                close_errors = _release_mirror_descriptors_best_effort(
                    (("unadopted account-home ancestor", child_fd, False),)
                )
                child_fd = -1
                _raise_sync_with_secondary_cleanup(
                    SyncError(
                        f"cannot bind canonical account-home ancestor "
                        f"{current_path / component}: {error}"
                    ),
                    "account-home child cleanup failures",
                    close_errors,
                )
            except BaseException as error:
                close_errors = _release_mirror_descriptors_best_effort(
                    (("unadopted account-home ancestor", child_fd, False),)
                )
                child_fd = -1
                _raise_sync_with_secondary_cleanup(
                    error,
                    "account-home child cleanup failures",
                    close_errors,
                )
            previous_fd = current_fd
            current_fd = child_fd
            child_fd = -1
            current_path /= component
            close_errors = _release_mirror_descriptors_best_effort(
                (("previous account-home ancestor", previous_fd, False),)
            )
            if close_errors:
                raise SyncError("; ".join(close_errors))
        metadata = os.fstat(current_fd)
        access_policy = _mirror_access_policy(metadata)
        if access_policy[1] != os.geteuid() or access_policy[0] & 0o022:
            raise SyncError(
                "canonical account home must be owned by the current uid and "
                "not group/world writable"
            )
        result = current_fd, _mirror_object_identity(metadata), access_policy
        current_fd = -1
        return result
    except BaseException as error:
        close_errors = _release_mirror_descriptors_best_effort(
            (("current account-home ancestor", current_fd, False),)
        )
        current_fd = -1
        _raise_sync_with_secondary_cleanup(
            error,
            "account-home cleanup failures",
            close_errors,
        )


def _bind_mirror_primary_control_parent(
    spec: MirrorPrivateControlRootSpec,
) -> tuple[int, tuple[int, int, int], tuple[int, int, int]] | None:
    if (
        not spec.allocate
        or spec.shared_parent
        or spec.account_home is None
        or spec.parent_path != spec.account_home / MIRROR_PRIVATE_CONTROL_NAMESPACE_NAME
    ):
        raise SyncError(f"private-control root schema is invalid [{spec.root_id}]")
    home_fd, home_identity, home_access_policy = _bind_mirror_trusted_account_home(
        spec.account_home
    )
    parent_fd = -1
    result: tuple[int, tuple[int, int, int], tuple[int, int, int]] | None = None
    try:
        try:
            os.stat(
                MIRROR_PRIVATE_CONTROL_NAMESPACE_NAME,
                dir_fd=home_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        else:
            parent_fd, parent_identity, parent_access_policy = (
                _bind_mirror_audit_child_directory(
                    home_fd,
                    spec.account_home,
                    MIRROR_PRIVATE_CONTROL_NAMESPACE_NAME,
                    f"private-control allocation root [{spec.root_id}]",
                )
            )
            if (
                parent_access_policy[0] != 0o700
                or parent_access_policy[1] != os.geteuid()
            ):
                raise SyncError(
                    f"private-control allocation root [{spec.root_id}] must be "
                    "mode 0700 and owned by the current uid"
                )
            _revalidate_mirror_audit_directory(
                spec.account_home,
                home_fd,
                home_identity,
                home_access_policy,
                "canonical account home",
            )
            result = parent_fd, parent_identity, parent_access_policy
    except BaseException as error:
        close_errors = _release_mirror_descriptors_best_effort(
            (
                (f"private-control parent [{spec.root_id}]", parent_fd, False),
                (f"canonical account home [{spec.root_id}]", home_fd, False),
            )
        )
        parent_fd = -1
        home_fd = -1
        _raise_sync_with_secondary_cleanup(
            error,
            "primary private-control bind cleanup failures",
            close_errors,
        )
    home_close_errors = _release_mirror_descriptors_best_effort(
        ((f"canonical account home [{spec.root_id}]", home_fd, False),)
    )
    home_fd = -1
    if home_close_errors:
        parent_close_errors = _release_mirror_descriptors_best_effort(
            ((f"private-control parent [{spec.root_id}]", parent_fd, False),)
        )
        parent_fd = -1
        raise SyncError(
            "primary private-control bind cleanup failures: "
            + "; ".join((*home_close_errors, *parent_close_errors))
        )
    return result


def _capture_mirror_quarantine_parent_absence(
    spec: MirrorPrivateControlRootSpec,
) -> MirrorQuarantineRootReceipt:
    parent_path = Path(os.path.abspath(spec.parent_path))
    if spec.allocate:
        if (
            spec.shared_parent
            or spec.account_home is None
            or parent_path
            != Path(os.path.abspath(spec.account_home))
            / MIRROR_PRIVATE_CONTROL_NAMESPACE_NAME
        ):
            raise SyncError(f"private-control root schema is invalid [{spec.root_id}]")
        anchor_path = Path(os.path.abspath(spec.account_home))
        absence_name = MIRROR_PRIVATE_CONTROL_NAMESPACE_NAME
        anchor_fd, anchor_identity, anchor_access_policy = (
            _bind_mirror_trusted_account_home(anchor_path)
        )
        anchor_label = f"canonical account home [{spec.root_id}]"
    else:
        if (
            not spec.shared_parent
            or spec.account_home is not None
            or parent_path == Path("/")
            or parent_path.name in {"", ".", ".."}
        ):
            raise SyncError(f"private-control root schema is invalid [{spec.root_id}]")
        anchor_path = parent_path.parent
        absence_name = parent_path.name
        anchor_fd, anchor_identity, anchor_access_policy = _bind_mirror_audit_directory(
            anchor_path,
            f"legacy private-control absence anchor [{spec.root_id}]",
        )
        anchor_label = f"legacy private-control absence anchor [{spec.root_id}]"
    receipt: MirrorQuarantineRootReceipt | None = None
    primary_error: BaseException | None = None
    try:
        try:
            os.stat(
                absence_name,
                dir_fd=anchor_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        except OSError as error:
            raise SyncError(
                f"cannot verify absent private-control parent [{spec.root_id}]: {error}"
            ) from error
        else:
            raise SyncError(
                f"private-control parent [{spec.root_id}] is no longer absent"
            )
        _revalidate_mirror_audit_directory(
            anchor_path,
            anchor_fd,
            anchor_identity,
            anchor_access_policy,
            anchor_label,
        )
        receipt = MirrorQuarantineRootReceipt(
            root_id=spec.root_id,
            parent_path=parent_path,
            scope="parent-absent",
            parent_identity=None,
            parent_access_policy=None,
            absence_anchor_path=anchor_path,
            absence_name=absence_name,
            absence_anchor_identity=anchor_identity,
            absence_anchor_access_policy=anchor_access_policy,
        )
    except BaseException as error:
        primary_error = error
    close_errors = _release_mirror_descriptors_best_effort(
        ((anchor_label, anchor_fd, False),)
    )
    anchor_fd = -1
    if primary_error is not None:
        _raise_sync_with_secondary_cleanup(
            primary_error,
            "absence-anchor cleanup failures",
            close_errors,
        )
    if close_errors:
        raise SyncError("absence-anchor cleanup failures: " + "; ".join(close_errors))
    assert receipt is not None
    return receipt


def _mirror_legacy_shared_parent_policy_is_valid(
    access_policy: tuple[int, int, int],
) -> bool:
    mode, uid, _gid = access_policy
    return mode == 0o1777 and uid == 0


def _mirror_private_control_child_metadata(
    parent_fd: int,
    name: str,
    label: str,
) -> tuple[tuple[int, int, int], tuple[int, int, int]] | None:
    try:
        metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        return None
    except OSError as error:
        raise SyncError(f"cannot inspect {label} {name}: {error}") from error
    return _mirror_object_identity(metadata), _mirror_access_policy(metadata)


def _mirror_legacy_child_metadata(
    parent_fd: int,
    name: str,
    root_id: str,
) -> tuple[tuple[int, int, int], tuple[int, int, int]] | None:
    return _mirror_private_control_child_metadata(
        parent_fd,
        name,
        f"legacy private-control child [{root_id}]",
    )


def _mirror_private_control_alias_error(
    parent_identity: tuple[int, int, int],
    tool_record: tuple[tuple[int, int, int], tuple[int, int, int]] | None,
    quarantine_record: tuple[tuple[int, int, int], tuple[int, int, int]] | None,
    seen_parent_identities: set[tuple[int, int, int]],
    seen_child_identities: set[tuple[int, int, int]],
) -> str | None:
    observed = tuple(
        record for record in (tool_record, quarantine_record) if record is not None
    )
    child_identities = {record[0] for record in observed}
    if parent_identity in seen_child_identities:
        return "private-control parent aliases an earlier fixed child"
    if len(child_identities) != len(observed):
        return "private-control fixed child roles alias each other"
    if parent_identity in child_identities:
        return "private-control fixed child aliases its own parent"
    if child_identities & (seen_parent_identities | seen_child_identities):
        return "distinct private-control parent aliases an earlier control object"
    return None


def _bind_mirror_audit_child_directory(
    parent_fd: int,
    parent_path: Path,
    name: str,
    label: str,
) -> tuple[int, tuple[int, int, int], tuple[int, int, int]]:
    try:
        path_metadata = os.stat(
            name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
    except OSError as error:
        raise SyncError(
            f"cannot inspect {label}: {parent_path / name}: {error}"
        ) from error
    if stat.S_ISLNK(path_metadata.st_mode) or not stat.S_ISDIR(path_metadata.st_mode):
        raise SyncError(
            f"{label} must be a non-symlink directory: {parent_path / name}"
        )
    try:
        directory_fd = os.open(
            name,
            _source_directory_flags(),
            dir_fd=parent_fd,
        )
    except OSError as error:
        raise SyncError(
            f"cannot safely open {label}: {parent_path / name}: {error}"
        ) from error
    try:
        descriptor_metadata = os.fstat(directory_fd)
    except OSError as error:
        close_errors = _release_mirror_descriptors_best_effort(
            ((label, directory_fd, False),)
        )
        _raise_sync_with_secondary_cleanup(
            SyncError(
                f"cannot inspect the bound {label}: {parent_path / name}: {error}"
            ),
            f"{label} bind cleanup failures",
            close_errors,
        )
    if _mirror_object_identity(path_metadata) != _mirror_object_identity(
        descriptor_metadata
    ) or _mirror_access_policy(path_metadata) != _mirror_access_policy(
        descriptor_metadata
    ):
        close_errors = _release_mirror_descriptors_best_effort(
            ((label, directory_fd, False),)
        )
        _raise_sync_with_secondary_cleanup(
            SyncError(f"{label} changed while binding it: {parent_path / name}"),
            f"{label} bind cleanup failures",
            close_errors,
        )
    return (
        directory_fd,
        _mirror_object_identity(descriptor_metadata),
        _mirror_access_policy(descriptor_metadata),
    )


def _revalidate_mirror_audit_directory(
    path: Path,
    directory_fd: int,
    identity: tuple[int, int, int],
    access_policy: tuple[int, int, int],
    label: str,
) -> None:
    try:
        path_metadata = os.stat(path, follow_symlinks=False)
        descriptor_metadata = os.fstat(directory_fd)
    except OSError as error:
        raise SyncError(f"{label} became unavailable: {path}: {error}") from error
    if (
        _mirror_object_identity(path_metadata) != identity
        or _mirror_object_identity(descriptor_metadata) != identity
    ):
        raise SyncError(f"{label} was replaced during audit: {path}")
    if (
        _mirror_access_policy(path_metadata) != access_policy
        or _mirror_access_policy(descriptor_metadata) != access_policy
    ):
        raise SyncError(f"{label} access policy changed during audit: {path}")


def _mirror_directory_is_at_or_below(
    candidate_fd: int,
    ancestor_identity: tuple[int, int, int],
    *,
    label: str,
) -> bool:
    try:
        current_fd = os.dup(candidate_fd)
    except OSError as error:
        raise SyncError(
            f"cannot duplicate {label} for ancestry audit: {error}"
        ) from error
    result: bool | None = None
    primary_error: BaseException | None = None
    try:
        for _depth in range(MIRROR_PRIVATE_CONTROL_MAX_ANCESTORS):
            try:
                current_identity = _mirror_object_identity(os.fstat(current_fd))
            except OSError as error:
                raise SyncError(f"cannot inspect {label} ancestry: {error}") from error
            if current_identity == ancestor_identity:
                result = True
                break
            parent_fd = -1
            try:
                parent_fd = os.open(
                    "..",
                    _source_directory_flags(),
                    dir_fd=current_fd,
                )
                parent_identity = _mirror_object_identity(os.fstat(parent_fd))
            except OSError as error:
                close_errors = _release_mirror_descriptors_best_effort(
                    ((f"unadopted {label} ancestry parent", parent_fd, False),)
                )
                _raise_sync_with_secondary_cleanup(
                    SyncError(f"cannot inspect {label} ancestry: {error}"),
                    f"{label} ancestry parent cleanup failures",
                    close_errors,
                )
            previous_fd = current_fd
            current_fd = parent_fd
            parent_fd = -1
            close_errors = _release_mirror_descriptors_best_effort(
                ((f"previous {label} ancestry directory", previous_fd, False),)
            )
            if close_errors:
                raise SyncError("; ".join(close_errors))
            if parent_identity == current_identity:
                result = False
                break
        else:
            raise SyncError(
                f"{label} ancestry exceeds "
                f"{MIRROR_PRIVATE_CONTROL_MAX_ANCESTORS} directories"
            )
    except BaseException as error:
        primary_error = error
    close_errors = _release_mirror_descriptors_best_effort(
        ((f"current {label} ancestry directory", current_fd, False),)
    )
    current_fd = -1
    if primary_error is not None:
        _raise_sync_with_secondary_cleanup(
            primary_error,
            f"{label} ancestry cleanup failures",
            close_errors,
        )
    if close_errors:
        raise SyncError("; ".join(close_errors))
    assert result is not None
    return result


def _validate_mirror_private_control_metadata_topology(
    *,
    root_id: str,
    parent_fd: int,
    parent_identity: tuple[int, int, int],
    tool_record: tuple[tuple[int, int, int], tuple[int, int, int]] | None,
    quarantine_record: tuple[tuple[int, int, int], tuple[int, int, int]] | None,
) -> None:
    """Validate topology observable without opening either fixed child."""

    children = tuple(
        (label, record)
        for label, record in (
            ("mirror private tool root", tool_record),
            ("mirror durable quarantine segment", quarantine_record),
        )
        if record is not None
    )
    for label, record in children:
        identity, _access_policy = record
        # The no-follow lookup through parent_fd proves that the fixed name is
        # directly below the bound parent. Walking only the parent upward also
        # rejects inverted containment without opening a foreign child.
        if identity == parent_identity or _mirror_directory_is_at_or_below(
            parent_fd,
            identity,
            label=f"private-control parent [{root_id}]",
        ):
            raise SyncError(
                f"{label} [{root_id}] does not have strict parent-to-child containment"
            )
    if tool_record is not None and quarantine_record is not None:
        if tool_record[0][0] != quarantine_record[0][0]:
            raise SyncError(
                f"mirror private tool and quarantine roots [{root_id}] must be "
                "on the same filesystem"
            )
        if tool_record[0] == quarantine_record[0]:
            raise SyncError(
                f"mirror private tool and quarantine roots [{root_id}] overlap"
            )


def _validate_mirror_private_control_bound_topology(
    *,
    root_id: str,
    parent_fd: int,
    parent_identity: tuple[int, int, int],
    tool_fd: int = -1,
    tool_identity: tuple[int, int, int] | None = None,
    quarantine_fd: int = -1,
    quarantine_identity: tuple[int, int, int] | None = None,
) -> None:
    if (tool_fd >= 0) != (tool_identity is not None) or (quarantine_fd >= 0) != (
        quarantine_identity is not None
    ):
        raise SyncError(
            f"mirror private-control topology binding [{root_id}] is incomplete"
        )
    children = tuple(
        (label, directory_fd, identity)
        for label, directory_fd, identity in (
            ("mirror private tool root", tool_fd, tool_identity),
            (
                "mirror durable quarantine segment",
                quarantine_fd,
                quarantine_identity,
            ),
        )
        if directory_fd >= 0 and identity is not None
    )
    for label, directory_fd, identity in children:
        if (
            identity == parent_identity
            or not _mirror_directory_is_at_or_below(
                directory_fd,
                parent_identity,
                label=f"{label} [{root_id}]",
            )
            or _mirror_directory_is_at_or_below(
                parent_fd,
                identity,
                label=f"private-control parent [{root_id}]",
            )
        ):
            raise SyncError(
                f"{label} [{root_id}] is not a strict descendant of its "
                "fixed-name parent"
            )
    if tool_fd >= 0 and quarantine_fd >= 0:
        try:
            tool_metadata = os.fstat(tool_fd)
            quarantine_metadata = os.fstat(quarantine_fd)
        except OSError as error:
            raise SyncError(
                f"cannot inspect mirror private-control topology [{root_id}]: {error}"
            ) from error
        if tool_metadata.st_dev != quarantine_metadata.st_dev:
            raise SyncError(
                f"mirror private tool and quarantine roots [{root_id}] must be "
                "on the same filesystem"
            )
        assert tool_identity is not None
        assert quarantine_identity is not None
        if _mirror_directory_is_at_or_below(
            tool_fd,
            quarantine_identity,
            label=f"mirror private tool root [{root_id}]",
        ) or _mirror_directory_is_at_or_below(
            quarantine_fd,
            tool_identity,
            label=f"mirror durable quarantine segment [{root_id}]",
        ):
            raise SyncError(
                f"mirror private tool and quarantine roots [{root_id}] overlap"
            )


def _acquire_mirror_audit_shared_lock(
    directory_fd: int,
    label: str,
) -> None:
    try:
        fcntl.flock(directory_fd, fcntl.LOCK_SH | fcntl.LOCK_NB)
    except BlockingIOError as error:
        raise SyncError(f"{label} is busy with an active writer") from error
    except OSError as error:
        raise SyncError(f"cannot acquire the {label} audit lease: {error}") from error


def _bounded_mirror_directory_names(
    directory_fd: int,
    *,
    limit: int,
    label: str,
) -> tuple[tuple[str, ...], bool]:
    def scan() -> tuple[tuple[str, ...], bool]:
        names: list[str] = []
        try:
            with os.scandir(directory_fd) as entries:
                for entry in entries:
                    name = entry.name
                    if (
                        not isinstance(name, str)
                        or name in {"", ".", ".."}
                        or "/" in name
                    ):
                        raise SyncError(
                            f"{label} contains an unsafe entry name: {name!r}"
                        )
                    names.append(name)
                    if len(names) > limit:
                        return tuple(sorted(names)), True
        except OSError as error:
            raise SyncError(f"cannot inventory {label}: {error}") from error
        return tuple(sorted(names)), False

    first, first_overflow = scan()
    if first_overflow:
        return first, True
    second, second_overflow = scan()
    if second_overflow or second != first:
        raise SyncError(f"{label} namespace changed during audit")
    return first, False


def _read_bounded_mirror_owner_payload(
    file_fd: int,
    label: str,
) -> bytes:
    try:
        before = os.fstat(file_fd)
    except OSError as error:
        raise SyncError(f"cannot inspect {label} before reading: {error}") from error

    def read_once() -> bytes:
        try:
            os.lseek(file_fd, 0, os.SEEK_SET)
            payload = bytearray()
            while len(payload) <= MAX_MIRROR_PRIVATE_OWNER_RECORD_BYTES:
                chunk = os.read(
                    file_fd,
                    min(
                        4096,
                        MAX_MIRROR_PRIVATE_OWNER_RECORD_BYTES + 1 - len(payload),
                    ),
                )
                if not chunk:
                    break
                payload.extend(chunk)
        except OSError as error:
            raise SyncError(f"cannot read {label}: {error}") from error
        if len(payload) > MAX_MIRROR_PRIVATE_OWNER_RECORD_BYTES:
            raise SyncError(
                f"{label} exceeds {MAX_MIRROR_PRIVATE_OWNER_RECORD_BYTES} bytes"
            )
        return bytes(payload)

    first = read_once()
    second = read_once()
    try:
        after = os.fstat(file_fd)
    except OSError as error:
        raise SyncError(f"cannot inspect {label} after reading: {error}") from error
    if (
        _mirror_object_identity(before) != _mirror_object_identity(after)
        or _mirror_access_policy(before) != _mirror_access_policy(after)
        or before.st_size != after.st_size
        or first != second
    ):
        raise SyncError(f"{label} changed while reading it")
    return first


def _mirror_owner_record_from_pairs(
    pairs: list[tuple[str, Any]],
) -> dict[str, Any]:
    record: dict[str, Any] = {}
    for key, value in pairs:
        if key in record:
            raise ValueError(f"duplicate key: {key}")
        record[key] = value
    return record


def _is_strict_json_integer(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _audit_mirror_owner_record(
    tool_fd: int,
    owner_name: str,
    expected_root_id: str,
) -> MirrorQuarantineOwnerRecord:
    label = f"mirror private owner record {owner_name}"
    try:
        path_metadata = os.stat(
            owner_name,
            dir_fd=tool_fd,
            follow_symlinks=False,
        )
        if not stat.S_ISREG(path_metadata.st_mode):
            raise SyncError(f"{label} must be a regular file")
        owner_fd = os.open(
            owner_name,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=tool_fd,
        )
    except OSError as error:
        raise SyncError(f"cannot bind {label}: {error}") from error
    with _mirror_descriptor_cleanup_scope(
        lambda: ((label, owner_fd, False),),
        label=f"{label} descriptor cleanup failures",
    ):
        try:
            descriptor_metadata = os.fstat(owner_fd)
        except OSError as error:
            raise SyncError(f"cannot inspect the bound {label}: {error}") from error
        identity = _mirror_object_identity(descriptor_metadata)
        access_policy = _mirror_access_policy(descriptor_metadata)
        if (
            _mirror_object_identity(path_metadata) != identity
            or _mirror_access_policy(path_metadata) != access_policy
        ):
            raise SyncError(f"{label} changed while opening it")
        try:
            fcntl.flock(owner_fd, fcntl.LOCK_SH | fcntl.LOCK_NB)
        except BlockingIOError:
            try:
                final_path_metadata = os.stat(
                    owner_name,
                    dir_fd=tool_fd,
                    follow_symlinks=False,
                )
            except OSError as error:
                raise SyncError(f"cannot revalidate active {label}: {error}") from error
            if (
                _mirror_object_identity(final_path_metadata) != identity
                or _mirror_access_policy(final_path_metadata) != access_policy
            ):
                raise SyncError(f"{label} changed after its active lease was observed")
            return MirrorQuarantineOwnerRecord(
                name=owner_name,
                identity=identity,
                access_policy=access_policy,
                sha256=None,
                state="active",
                detail="owner record is held by an active exclusive lease",
                root_id=expected_root_id,
            )
        except OSError as error:
            raise SyncError(
                f"cannot acquire the {label} audit lease: {error}"
            ) from error
        try:
            payload = _read_bounded_mirror_owner_payload(owner_fd, label)
            digest = hashlib.sha256(payload).hexdigest()
            try:
                final_path_metadata = os.stat(
                    owner_name,
                    dir_fd=tool_fd,
                    follow_symlinks=False,
                )
            except OSError as error:
                raise SyncError(f"cannot revalidate {label}: {error}") from error
            if (
                _mirror_object_identity(final_path_metadata) != identity
                or _mirror_access_policy(final_path_metadata) != access_policy
            ):
                raise SyncError(f"{label} changed after it was read")
            try:
                record = json.loads(
                    payload.decode("utf-8"),
                    object_pairs_hook=_mirror_owner_record_from_pairs,
                )
            except (
                UnicodeDecodeError,
                ValueError,
                json.JSONDecodeError,
                RecursionError,
            ) as error:
                return MirrorQuarantineOwnerRecord(
                    name=owner_name,
                    identity=identity,
                    access_policy=access_policy,
                    sha256=digest,
                    state="invalid",
                    detail=f"owner record schema is invalid: {error}",
                )
            root_scope = _mirror_private_owner_record_root_scope(
                record,
                expected_root_id,
            )
            observed_root_id = (
                record.get("root_id") if isinstance(record, dict) else None
            )
            if root_scope == MIRROR_PRIVATE_OWNER_RECORD_REASON_ROOT_MISMATCH:
                return MirrorQuarantineOwnerRecord(
                    name=owner_name,
                    identity=identity,
                    access_policy=access_policy,
                    sha256=digest,
                    state="invalid",
                    detail=(
                        "owner record root scope does not match its containing "
                        f"root {expected_root_id}"
                    ),
                    root_id=(
                        observed_root_id if isinstance(observed_root_id, str) else None
                    ),
                    reason_code=MIRROR_PRIVATE_OWNER_RECORD_REASON_ROOT_MISMATCH,
                )
            private_name = (
                record.get("private_name") if isinstance(record, dict) else None
            )
            private_identity = (
                record.get("private_identity") if isinstance(record, dict) else None
            )
            valid = (
                isinstance(record, dict)
                and root_scope in {"accepted-legacy", "accepted-current"}
                and _is_strict_json_integer(record["owner_pid"])
                and record["owner_pid"] > 0
                and type(record["owner_uid"]) is int
                and record["owner_uid"] == os.geteuid()
                and type(record["owner_gid"]) is int
                and record["owner_gid"] == os.getegid()
                and isinstance(record["owner_nonce"], str)
                and re.fullmatch(r"[0-9a-f]{32}", record["owner_nonce"]) is not None
                and isinstance(record["phase"], str)
                and record["phase"] in MIRROR_PRIVATE_OWNER_RECORD_PHASES
                and isinstance(private_name, str)
                and MIRROR_PRIVATE_SNAPSHOT_RE.fullmatch(private_name) is not None
                and owner_name == f"{private_name}.owner.json"
                and isinstance(private_identity, list)
                and len(private_identity) == 3
                and all(
                    _is_strict_json_integer(item) and item >= 0
                    for item in private_identity
                )
                and access_policy == (0o600, os.geteuid(), os.getegid())
            )
            if not valid:
                return MirrorQuarantineOwnerRecord(
                    name=owner_name,
                    identity=identity,
                    access_policy=access_policy,
                    sha256=digest,
                    state="invalid",
                    detail="owner record fields do not match the recovery schema",
                )
            expected_private_identity = tuple(private_identity)
            assert private_name is not None
            try:
                private_metadata = os.stat(
                    private_name,
                    dir_fd=tool_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                observed_private_identity = None
                private_state = "missing"
            except OSError as error:
                raise SyncError(
                    f"cannot inspect mirror private snapshot {private_name}: {error}"
                ) from error
            else:
                observed_private_identity = _mirror_object_identity(private_metadata)
                private_state = (
                    "matching"
                    if stat.S_ISDIR(private_metadata.st_mode)
                    and observed_private_identity == expected_private_identity
                    else "mismatched"
                )
            return MirrorQuarantineOwnerRecord(
                name=owner_name,
                identity=identity,
                access_policy=access_policy,
                sha256=digest,
                state="stale",
                owner_pid=record["owner_pid"],
                owner_nonce=record["owner_nonce"],
                phase=record["phase"],
                private_name=private_name,
                expected_private_identity=expected_private_identity,
                observed_private_identity=observed_private_identity,
                private_state=private_state,
                root_id=expected_root_id,
            )
        finally:
            try:
                fcntl.flock(owner_fd, fcntl.LOCK_UN)
            except OSError as error:
                raise SyncError(
                    f"cannot release the {label} audit lease: {error}"
                ) from error


def _pc_recovery_audit_adoption_locked(
    spec: MirrorPrivateControlRootSpec,
    parent: _PrivateControlRecoveryBinding,
    tool: _PrivateControlRecoveryBinding | None,
    quarantine: _PrivateControlRecoveryBinding | None,
    *,
    expected_plan_digest: str | None = None,
) -> str | None:
    primary_spec, legacy_spec = _pc_recovery_specs(spec.root_id)
    if spec != legacy_spec:
        raise SyncError("private-control recovery audit registry entry changed")
    primary_binding = _bind_mirror_primary_control_parent(primary_spec)
    if primary_binding is None:
        return None
    primary_fd, primary_identity, primary_access = primary_binding
    primary = _PrivateControlRecoveryBinding(
        label=f"primary private-control parent [{primary_spec.root_id}]",
        path=Path(os.path.abspath(primary_spec.parent_path)),
        fd=primary_fd,
        identity=primary_identity,
        access=primary_access,
    )
    try:
        try:
            os.stat(
                MIRROR_PRIVATE_CONTROL_RECOVERY_MARKER_NAME,
                dir_fd=primary.fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            try:
                os.stat(
                    MIRROR_PRIVATE_CONTROL_RECOVERY_RECEIPT_NAME,
                    dir_fd=primary.fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                _pc_recovery_revalidate_directory(primary)
                return None
            except OSError as error:
                raise SyncError(
                    f"cannot inspect retained-in-place recovery receipt: {error}"
                ) from error
            raise SyncError(
                "retained-in-place recovery receipt exists without its cutover marker"
            )
        except OSError as error:
            raise SyncError(
                f"cannot inspect retained-in-place recovery cutover marker: {error}"
            ) from error
        if tool is None or quarantine is None:
            raise SyncError(
                "retained-in-place recovery cutover requires its exact legacy "
                "tool and quarantine roots"
            )
        _pc_recovery_validate_topology(
            parent,
            tool,
            quarantine,
            primary,
        )
        verification = _pc_recovery_verify_adoption_locked(
            primary,
            parent,
            tool,
            quarantine,
            expected_plan_digest=expected_plan_digest,
        )
        plan = verification["plan"]
        plan_digest = plan["plan_digest"]
        if not isinstance(plan_digest, str):
            raise SyncError("verified recovery plan digest is invalid")
        return plan_digest
    finally:
        active_error = sys.exc_info()[1]
        try:
            _pc_recovery_close_bindings((primary,))
        except SyncError as cleanup_error:
            if active_error is None:
                raise
            _raise_sync_with_secondary_cleanup(
                active_error,
                "recovery audit primary-parent cleanup failure",
                (str(cleanup_error),),
            )


def _mirror_quarantine_root_audit(
    spec: MirrorPrivateControlRootSpec,
    seen_parent_identities: set[tuple[int, int, int]] | None = None,
    seen_child_identities: set[tuple[int, int, int]] | None = None,
) -> MirrorQuarantineAudit:
    parent_path = Path(os.path.abspath(spec.parent_path))
    tool_path = parent_path / MIRROR_PRIVATE_TOOL_ROOT_NAME
    quarantine_path = parent_path / MIRROR_DURABLE_QUARANTINE_ROOT_NAME
    parent_fd = -1
    tool_fd = -1
    quarantine_fd = -1
    tool_lease_attempted = False
    quarantine_lease_attempted = False
    tool_was_present = False
    quarantine_inspection_attempted = False
    quarantine_was_present = False
    quarantine_coordination_ready = True
    entry_count: int | None = None
    count_is_lower_bound = False
    tool_identity: tuple[int, int, int] | None = None
    tool_access_policy: tuple[int, int, int] | None = None
    segment_identity: tuple[int, int, int] | None = None
    segment_access_policy: tuple[int, int, int] | None = None
    owner_records: list[MirrorQuarantineOwnerRecord] = []
    audit_errors: list[str] = []
    tool_names: tuple[str, ...] = ()
    parent_identity: tuple[int, int, int] | None = None
    parent_access_policy: tuple[int, int, int] | None = None
    first_tool: tuple[tuple[int, int, int], tuple[int, int, int]] | None = None
    first_quarantine: tuple[tuple[int, int, int], tuple[int, int, int]] | None = None
    fixed_metadata_captured = False
    adoption_plan_digest: str | None = None
    forced_reason_code: str | None = None
    prior_parent_identities = (
        set() if seen_parent_identities is None else seen_parent_identities
    )
    prior_child_identities = (
        set() if seen_child_identities is None else seen_child_identities
    )
    try:
        if spec.allocate:
            primary_binding = _bind_mirror_primary_control_parent(spec)
            if primary_binding is None:
                root_receipt = _capture_mirror_quarantine_parent_absence(spec)
                return MirrorQuarantineAudit(
                    classification="absent",
                    path=quarantine_path,
                    entry_count=0,
                    entry_limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
                    count_is_lower_bound=False,
                    segment_identity=None,
                    segment_access_policy=None,
                    root_id=spec.root_id,
                    root_receipt=root_receipt,
                )
            parent_fd, parent_identity, parent_access_policy = primary_binding
            if (
                seen_parent_identities is not None
                and parent_identity in seen_parent_identities
            ):
                _revalidate_mirror_audit_directory(
                    parent_path,
                    parent_fd,
                    parent_identity,
                    parent_access_policy,
                    f"private-control parent [{spec.root_id}]",
                )
                return MirrorQuarantineAudit(
                    classification="duplicate",
                    path=quarantine_path,
                    entry_count=None,
                    entry_limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
                    count_is_lower_bound=False,
                    segment_identity=None,
                    segment_access_policy=None,
                    root_id=spec.root_id,
                    root_parent_identity=parent_identity,
                    root_receipt=MirrorQuarantineRootReceipt(
                        root_id=spec.root_id,
                        parent_path=parent_path,
                        scope="parent-only",
                        parent_identity=parent_identity,
                        parent_access_policy=parent_access_policy,
                    ),
                )
            first_tool = _mirror_private_control_child_metadata(
                parent_fd,
                MIRROR_PRIVATE_TOOL_ROOT_NAME,
                f"primary private-control child [{spec.root_id}]",
            )
            first_quarantine = _mirror_private_control_child_metadata(
                parent_fd,
                MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                f"primary private-control child [{spec.root_id}]",
            )
            fixed_metadata_captured = True
            alias_error = _mirror_private_control_alias_error(
                parent_identity,
                first_tool,
                first_quarantine,
                prior_parent_identities,
                prior_child_identities,
            )
            if alias_error is not None:
                tool_identity = None if first_tool is None else first_tool[0]
                segment_identity = (
                    None if first_quarantine is None else first_quarantine[0]
                )
                raise SyncError(alias_error)
            _validate_mirror_private_control_metadata_topology(
                root_id=spec.root_id,
                parent_fd=parent_fd,
                parent_identity=parent_identity,
                tool_record=first_tool,
                quarantine_record=first_quarantine,
            )
        else:
            if not spec.shared_parent or spec.account_home is not None:
                raise SyncError(
                    f"private-control root schema is invalid [{spec.root_id}]"
                )
            try:
                (
                    parent_fd,
                    parent_identity,
                    parent_access_policy,
                ) = _bind_mirror_audit_directory(
                    parent_path,
                    f"legacy shared private-control parent [{spec.root_id}]",
                )
            except SyncError as bind_error:
                try:
                    root_receipt = _capture_mirror_quarantine_parent_absence(spec)
                except SyncError as absence_error:
                    raise SyncError(
                        f"{bind_error}; secondary absence-anchor verification "
                        f"failure: {absence_error}"
                    ) from bind_error
                return MirrorQuarantineAudit(
                    classification="absent",
                    path=quarantine_path,
                    entry_count=0,
                    entry_limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
                    count_is_lower_bound=False,
                    segment_identity=None,
                    segment_access_policy=None,
                    root_id=spec.root_id,
                    root_receipt=root_receipt,
                )
            if not _mirror_legacy_shared_parent_policy_is_valid(parent_access_policy):
                raise SyncError(
                    f"legacy shared private-control parent [{spec.root_id}] "
                    "must be root-owned mode 1777"
                )
            if (
                seen_parent_identities is not None
                and parent_identity in seen_parent_identities
            ):
                _revalidate_mirror_audit_directory(
                    parent_path,
                    parent_fd,
                    parent_identity,
                    parent_access_policy,
                    f"legacy shared private-control parent [{spec.root_id}]",
                )
                return MirrorQuarantineAudit(
                    classification="duplicate",
                    path=quarantine_path,
                    entry_count=None,
                    entry_limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
                    count_is_lower_bound=False,
                    segment_identity=None,
                    segment_access_policy=None,
                    root_id=spec.root_id,
                    root_parent_identity=parent_identity,
                    root_receipt=MirrorQuarantineRootReceipt(
                        root_id=spec.root_id,
                        parent_path=parent_path,
                        scope="parent-only",
                        parent_identity=parent_identity,
                        parent_access_policy=parent_access_policy,
                    ),
                )
            first_tool = _mirror_legacy_child_metadata(
                parent_fd,
                MIRROR_PRIVATE_TOOL_ROOT_NAME,
                spec.root_id,
            )
            first_quarantine = _mirror_legacy_child_metadata(
                parent_fd,
                MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                spec.root_id,
            )
            fixed_metadata_captured = True
            alias_error = _mirror_private_control_alias_error(
                parent_identity,
                first_tool,
                first_quarantine,
                prior_parent_identities,
                prior_child_identities,
            )
            if alias_error is not None:
                tool_identity = None if first_tool is None else first_tool[0]
                segment_identity = (
                    None if first_quarantine is None else first_quarantine[0]
                )
                raise SyncError(alias_error)
            observed = tuple(
                item for item in (first_tool, first_quarantine) if item is not None
            )
            ownership_state = _mirror_private_control_legacy_ownership_state(observed)
            if ownership_state == "foreign-unrelated":
                second_tool = _mirror_legacy_child_metadata(
                    parent_fd,
                    MIRROR_PRIVATE_TOOL_ROOT_NAME,
                    spec.root_id,
                )
                second_quarantine = _mirror_legacy_child_metadata(
                    parent_fd,
                    MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                    spec.root_id,
                )
                if (second_tool, second_quarantine) != (
                    first_tool,
                    first_quarantine,
                ):
                    raise SyncError(
                        "foreign-unrelated legacy metadata changed during audit"
                    )
                _revalidate_mirror_audit_directory(
                    parent_path,
                    parent_fd,
                    parent_identity,
                    parent_access_policy,
                    f"legacy shared private-control parent [{spec.root_id}]",
                )
                return MirrorQuarantineAudit(
                    classification="foreign-unrelated",
                    path=quarantine_path,
                    entry_count=None,
                    entry_limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
                    count_is_lower_bound=False,
                    segment_identity=(
                        None if first_quarantine is None else first_quarantine[0]
                    ),
                    segment_access_policy=(
                        None if first_quarantine is None else first_quarantine[1]
                    ),
                    root_id=spec.root_id,
                    root_parent_identity=parent_identity,
                    tool_identity=None if first_tool is None else first_tool[0],
                    root_receipt=MirrorQuarantineRootReceipt(
                        root_id=spec.root_id,
                        parent_path=parent_path,
                        scope="fixed-metadata",
                        parent_identity=parent_identity,
                        parent_access_policy=parent_access_policy,
                        tool_record=first_tool,
                        quarantine_record=first_quarantine,
                    ),
                )
            if ownership_state == "inconclusive":
                raise SyncError("legacy private-control children have mixed ownership")
        tool_coordination_ready = True
        try:
            os.stat(
                MIRROR_PRIVATE_TOOL_ROOT_NAME,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        except OSError as error:
            tool_coordination_ready = False
            audit_errors.append(f"cannot inspect mirror private tool root: {error}")
        else:
            tool_was_present = True
            try:
                (
                    tool_fd,
                    tool_identity,
                    tool_access_policy,
                ) = _bind_mirror_audit_child_directory(
                    parent_fd,
                    parent_path,
                    MIRROR_PRIVATE_TOOL_ROOT_NAME,
                    "mirror private tool root",
                )
                if (
                    not spec.allocate
                    and (
                        tool_identity,
                        tool_access_policy,
                    )
                    != first_tool
                ):
                    raise SyncError(
                        "legacy private tool root changed before audit binding"
                    )
                if (
                    tool_access_policy[0] != 0o700
                    or tool_access_policy[1] != os.geteuid()
                ):
                    raise SyncError(
                        "mirror private tool root must be mode 0700 and "
                        "owned by the current uid"
                    )
                _validate_mirror_private_control_bound_topology(
                    root_id=spec.root_id,
                    parent_fd=parent_fd,
                    parent_identity=parent_identity,
                    tool_fd=tool_fd,
                    tool_identity=tool_identity,
                )
                tool_lease_attempted = True
                _acquire_mirror_audit_shared_lock(
                    tool_fd,
                    "mirror private tool root",
                )
            except SyncError as error:
                tool_coordination_ready = False
                audit_errors.append(str(error))

        if tool_coordination_ready and not tool_was_present:
            quarantine_inspection_attempted = True
            try:
                os.stat(
                    MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                entry_count = 0
            except OSError as error:
                quarantine_coordination_ready = False
                audit_errors.append(
                    f"cannot inspect mirror quarantine segment presence: {error}"
                )
            else:
                quarantine_was_present = True
                if not spec.allocate:
                    forced_reason_code = MIRROR_PRIVATE_CONTROL_REASON_LEGACY_PENDING
                audit_errors.append(
                    "mirror durable quarantine segment exists without its "
                    "coordination tool root"
                )
        elif tool_coordination_ready:
            quarantine_inspection_attempted = True
            try:
                os.stat(
                    MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                entry_count = 0
            except OSError as error:
                quarantine_coordination_ready = False
                audit_errors.append(
                    f"cannot inspect mirror quarantine segment: {error}"
                )
            else:
                quarantine_was_present = True
                try:
                    (
                        quarantine_fd,
                        segment_identity,
                        segment_access_policy,
                    ) = _bind_mirror_audit_child_directory(
                        parent_fd,
                        parent_path,
                        MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                        "mirror durable quarantine segment",
                    )
                    if (
                        not spec.allocate
                        and (
                            segment_identity,
                            segment_access_policy,
                        )
                        != first_quarantine
                    ):
                        raise SyncError(
                            "legacy durable quarantine changed before audit binding"
                        )
                    if (
                        segment_access_policy[0] != 0o700
                        or segment_access_policy[1] != os.geteuid()
                    ):
                        raise SyncError(
                            "mirror durable quarantine segment must be mode 0700 "
                            "and owned by the current uid"
                        )
                    _validate_mirror_private_control_bound_topology(
                        root_id=spec.root_id,
                        parent_fd=parent_fd,
                        parent_identity=parent_identity,
                        tool_fd=tool_fd,
                        tool_identity=tool_identity,
                        quarantine_fd=quarantine_fd,
                        quarantine_identity=segment_identity,
                    )
                    quarantine_lease_attempted = True
                    _acquire_mirror_audit_shared_lock(
                        quarantine_fd,
                        "mirror durable quarantine segment",
                    )
                except SyncError as error:
                    quarantine_coordination_ready = False
                    audit_errors.append(str(error))

        if not spec.allocate and spec.root_id == MIRROR_PRIVATE_CONTROL_LEGACY_ROOT_ID:
            if parent_identity is None or parent_access_policy is None:
                audit_errors.append(
                    "legacy private-control parent binding is incomplete"
                )
            else:
                recovery_parent = _PrivateControlRecoveryBinding(
                    label=f"legacy private-control parent [{spec.root_id}]",
                    path=parent_path,
                    fd=parent_fd,
                    identity=parent_identity,
                    access=parent_access_policy,
                )
                recovery_tool = (
                    _PrivateControlRecoveryBinding(
                        label=f"legacy private-control tool root [{spec.root_id}]",
                        path=tool_path,
                        fd=tool_fd,
                        identity=tool_identity,
                        access=tool_access_policy,
                    )
                    if (
                        tool_coordination_ready
                        and tool_was_present
                        and tool_lease_attempted
                        and tool_fd >= 0
                        and tool_identity is not None
                        and tool_access_policy is not None
                    )
                    else None
                )
                recovery_quarantine = (
                    _PrivateControlRecoveryBinding(
                        label=f"legacy quarantine [{spec.root_id}]",
                        path=quarantine_path,
                        fd=quarantine_fd,
                        identity=segment_identity,
                        access=segment_access_policy,
                    )
                    if (
                        quarantine_coordination_ready
                        and quarantine_was_present
                        and quarantine_lease_attempted
                        and quarantine_fd >= 0
                        and segment_identity is not None
                        and segment_access_policy is not None
                    )
                    else None
                )
                try:
                    adoption_plan_digest = _pc_recovery_audit_adoption_locked(
                        spec,
                        recovery_parent,
                        recovery_tool,
                        recovery_quarantine,
                    )
                except SyncError as error:
                    audit_errors.append(
                        f"{MIRROR_PRIVATE_CONTROL_REASON_INCONCLUSIVE} "
                        f"[{spec.root_id}]: {error}"
                    )

        if (
            tool_coordination_ready
            and tool_was_present
            and quarantine_coordination_ready
            and adoption_plan_digest is None
        ):
            try:
                tool_names, tool_overflow = _bounded_mirror_directory_names(
                    tool_fd,
                    limit=MIRROR_PRIVATE_TOOL_ROOT_ENTRY_LIMIT,
                    label="mirror private tool root",
                )
                if tool_overflow:
                    raise SyncError(
                        "mirror private tool root exceeds its bounded "
                        f"{MIRROR_PRIVATE_TOOL_ROOT_ENTRY_LIMIT}-entry audit"
                    )
                for owner_name in tool_names:
                    if not owner_name.endswith(".owner.json"):
                        continue
                    private_name = owner_name[: -len(".owner.json")]
                    if MIRROR_PRIVATE_SNAPSHOT_RE.fullmatch(private_name) is None:
                        continue
                    try:
                        owner_records.append(
                            _audit_mirror_owner_record(
                                tool_fd,
                                owner_name,
                                spec.root_id,
                            )
                        )
                    except SyncError as error:
                        audit_errors.append(str(error))
                if quarantine_fd >= 0:
                    quarantine_names, count_is_lower_bound = (
                        _bounded_mirror_directory_names(
                            quarantine_fd,
                            limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
                            label="mirror durable quarantine segment",
                        )
                    )
                    entry_count = len(quarantine_names)
                for owner_record in owner_records:
                    if (
                        owner_record.reason_code
                        == MIRROR_PRIVATE_OWNER_RECORD_REASON_ROOT_MISMATCH
                    ):
                        audit_errors.append(
                            f"{owner_record.reason_code} [{spec.root_id}]: "
                            f"{owner_record.name}"
                        )
                _revalidate_mirror_audit_directory(
                    tool_path,
                    tool_fd,
                    tool_identity,
                    tool_access_policy,
                    "mirror private tool root",
                )
                if quarantine_fd >= 0:
                    _revalidate_mirror_audit_directory(
                        quarantine_path,
                        quarantine_fd,
                        segment_identity,
                        segment_access_policy,
                        "mirror durable quarantine segment",
                    )
            except SyncError as error:
                audit_errors.append(str(error))

        if not tool_was_present:
            try:
                os.stat(
                    MIRROR_PRIVATE_TOOL_ROOT_NAME,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                pass
            except OSError as error:
                audit_errors.append(
                    f"cannot revalidate mirror private tool root presence: {error}"
                )
            else:
                audit_errors.append("mirror private tool root appeared during audit")
        elif (
            tool_identity is not None
            and tool_fd >= 0
            and tool_access_policy is not None
        ):
            try:
                _revalidate_mirror_audit_directory(
                    tool_path,
                    tool_fd,
                    tool_identity,
                    tool_access_policy,
                    "mirror private tool root",
                )
            except SyncError as error:
                audit_errors.append(str(error))

        if quarantine_inspection_attempted and not quarantine_was_present:
            try:
                os.stat(
                    MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                pass
            except OSError as error:
                audit_errors.append(
                    f"cannot revalidate mirror quarantine segment presence: {error}"
                )
            else:
                audit_errors.append(
                    "mirror durable quarantine segment appeared during audit"
                )
        elif (
            quarantine_inspection_attempted
            and quarantine_was_present
            and segment_identity is not None
            and quarantine_fd >= 0
            and segment_access_policy is not None
        ):
            try:
                _revalidate_mirror_audit_directory(
                    quarantine_path,
                    quarantine_fd,
                    segment_identity,
                    segment_access_policy,
                    "mirror durable quarantine segment",
                )
            except SyncError as error:
                audit_errors.append(str(error))

        if not spec.allocate:
            final_tool = _mirror_legacy_child_metadata(
                parent_fd,
                MIRROR_PRIVATE_TOOL_ROOT_NAME,
                spec.root_id,
            )
            final_quarantine = _mirror_legacy_child_metadata(
                parent_fd,
                MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                spec.root_id,
            )
            if (final_tool, final_quarantine) != (
                first_tool,
                first_quarantine,
            ):
                audit_errors.append("legacy fixed-root metadata changed during audit")
        _revalidate_mirror_audit_directory(
            parent_path,
            parent_fd,
            parent_identity,
            parent_access_policy,
            "mirror private-control parent",
        )
    except (OSError, SyncError) as error:
        audit_errors.append(str(error))
    finally:
        cleanup_errors = _release_mirror_descriptors_best_effort(
            (
                (
                    "mirror durable quarantine segment",
                    quarantine_fd,
                    quarantine_lease_attempted,
                ),
                ("mirror private tool root", tool_fd, tool_lease_attempted),
                ("mirror private-control parent", parent_fd, False),
            )
        )
        quarantine_fd = -1
        tool_fd = -1
        parent_fd = -1
        if cleanup_errors:
            if audit_errors:
                _raise_sync_with_secondary_cleanup(
                    SyncError("; ".join(audit_errors)),
                    "mirror private-control root cleanup failures",
                    cleanup_errors,
                )
            raise SyncError(
                "mirror private-control root cleanup failures: "
                + "; ".join(cleanup_errors)
            )

    reason_code = None
    if audit_errors:
        classification = "inconclusive"
        reason_code = (
            MIRROR_PRIVATE_OWNER_RECORD_REASON_ROOT_MISMATCH
            if any(
                record.reason_code == MIRROR_PRIVATE_OWNER_RECORD_REASON_ROOT_MISMATCH
                for record in owner_records
            )
            else forced_reason_code or MIRROR_PRIVATE_CONTROL_REASON_INCONCLUSIVE
        )
    elif adoption_plan_digest is not None:
        classification = "adopted-retained-in-place"
    elif not spec.allocate and (
        tool_names or (entry_count is not None and entry_count > 0)
    ):
        classification = "inconclusive"
        reason_code = MIRROR_PRIVATE_CONTROL_REASON_LEGACY_PENDING
        audit_errors.append(
            "same-uid legacy recovery evidence remains in its original root"
        )
    elif (
        entry_count is not None and entry_count >= MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT
    ):
        classification = "saturated"
    elif segment_identity is None:
        classification = "absent"
    else:
        classification = "available"
    root_receipt = None
    if parent_identity is not None and parent_access_policy is not None:
        root_receipt = MirrorQuarantineRootReceipt(
            root_id=spec.root_id,
            parent_path=parent_path,
            scope="fixed-metadata" if fixed_metadata_captured else "parent-only",
            parent_identity=parent_identity,
            parent_access_policy=parent_access_policy,
            tool_record=first_tool if fixed_metadata_captured else None,
            quarantine_record=first_quarantine if fixed_metadata_captured else None,
            adoption_plan_digest=(
                adoption_plan_digest
                if classification == "adopted-retained-in-place"
                else None
            ),
        )
    return MirrorQuarantineAudit(
        classification=classification,
        path=quarantine_path,
        entry_count=entry_count,
        entry_limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
        count_is_lower_bound=count_is_lower_bound,
        segment_identity=segment_identity,
        segment_access_policy=segment_access_policy,
        owner_records=tuple(owner_records),
        detail="; ".join(audit_errors) if audit_errors else None,
        root_id=spec.root_id,
        reason_code=reason_code,
        root_parent_identity=parent_identity,
        tool_identity=tool_identity,
        root_receipt=root_receipt,
    )


def _bind_mirror_terminal_registry_parent(
    spec: MirrorPrivateControlRootSpec,
) -> tuple[int, tuple[int, int, int], tuple[int, int, int]] | None:
    if spec.allocate:
        return _bind_mirror_primary_control_parent(spec)
    if not spec.shared_parent or spec.account_home is not None:
        raise SyncError(f"private-control root schema is invalid [{spec.root_id}]")
    parent_path = Path(os.path.abspath(spec.parent_path))
    try:
        return _bind_mirror_audit_directory(
            parent_path,
            f"terminal legacy private-control parent [{spec.root_id}]",
        )
    except SyncError as bind_error:
        try:
            _capture_mirror_quarantine_parent_absence(spec)
        except SyncError as absence_error:
            raise SyncError(
                f"{bind_error}; secondary absence-anchor verification failure: "
                f"{absence_error}"
            ) from bind_error
        return None


def _revalidate_mirror_quarantine_root_receipt(
    spec: MirrorPrivateControlRootSpec,
    audit: MirrorQuarantineAudit,
) -> str:
    """Revalidate the receipt's selected protected property.

    Identity is dev/inode/type and access policy is mode/uid/gid. An anchored
    missing fixed name is protected as absence. Directory timestamps and child
    listings are deliberately excluded so benign child-entry churn is not
    mistaken for replacement, content mutation, or access-policy drift.
    Adopted retained-in-place receipts additionally protect the complete
    inventory and publication binding. Timestamps and allocated-block counts
    remain excluded; allocated bytes are an admission cap, not content identity.
    """

    receipt = audit.root_receipt
    if receipt is None:
        raise SyncError("initial root receipt is unavailable")
    parent_path = Path(os.path.abspath(spec.parent_path))
    if (
        receipt.root_id != spec.root_id
        or audit.root_id != spec.root_id
        or receipt.parent_path != parent_path
    ):
        raise SyncError("root receipt does not match its registry entry")
    absence_fields = (
        receipt.absence_anchor_path,
        receipt.absence_name,
        receipt.absence_anchor_identity,
        receipt.absence_anchor_access_policy,
    )
    if receipt.scope == "parent-absent":
        if (
            receipt.parent_identity is not None
            or receipt.parent_access_policy is not None
            or receipt.tool_record is not None
            or receipt.quarantine_record is not None
            or receipt.adoption_plan_digest is not None
            or audit.classification == "adopted-retained-in-place"
            or any(field is None for field in absence_fields)
        ):
            raise SyncError("absent-parent root receipt is incomplete")
        current = _capture_mirror_quarantine_parent_absence(spec)
        if (
            current.absence_anchor_path,
            current.absence_name,
            current.absence_anchor_identity,
            current.absence_anchor_access_policy,
        ) != absence_fields:
            raise SyncError("private-control parent absence anchor changed")
        return "stable(parent-absent)"
    if receipt.scope not in {"parent-only", "fixed-metadata"}:
        raise SyncError(f"root receipt scope is invalid: {receipt.scope}")
    adopted = audit.classification == "adopted-retained-in-place"
    if adopted:
        if (
            spec.allocate
            or spec.root_id != MIRROR_PRIVATE_CONTROL_LEGACY_ROOT_ID
            or receipt.scope != "fixed-metadata"
            or receipt.tool_record is None
            or receipt.quarantine_record is None
            or not isinstance(receipt.adoption_plan_digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", receipt.adoption_plan_digest) is None
        ):
            raise SyncError("adopted retained-in-place root receipt is incomplete")
    elif receipt.adoption_plan_digest is not None:
        raise SyncError("non-adopted root receipt has a recovery plan digest")
    if (
        receipt.parent_identity is None
        or receipt.parent_access_policy is None
        or any(field is not None for field in absence_fields)
        or (
            receipt.scope == "parent-only"
            and (
                receipt.tool_record is not None or receipt.quarantine_record is not None
            )
        )
    ):
        raise SyncError("present-parent root receipt is incomplete")
    parent_binding = _bind_mirror_terminal_registry_parent(spec)
    if parent_binding is None:
        raise SyncError("private-control parent disappeared")
    parent_fd, parent_identity, parent_access_policy = parent_binding
    with _mirror_descriptor_cleanup_scope(
        lambda: (
            (
                f"terminal private-control parent [{spec.root_id}]",
                parent_fd,
                False,
            ),
        ),
        label="terminal private-control parent cleanup failures",
    ):
        if (
            parent_identity != receipt.parent_identity
            or parent_access_policy != receipt.parent_access_policy
        ):
            raise SyncError("private-control parent identity or access policy changed")
        if not spec.allocate and not _mirror_legacy_shared_parent_policy_is_valid(
            parent_access_policy
        ):
            raise SyncError("legacy shared private-control parent policy changed")
        if receipt.scope == "parent-only":
            _revalidate_mirror_audit_directory(
                parent_path,
                parent_fd,
                parent_identity,
                parent_access_policy,
                f"terminal private-control parent [{spec.root_id}]",
            )
            return "stable(parent-only)"
        if spec.allocate:
            tool_record = _mirror_private_control_child_metadata(
                parent_fd,
                MIRROR_PRIVATE_TOOL_ROOT_NAME,
                f"terminal primary private-control child [{spec.root_id}]",
            )
            quarantine_record = _mirror_private_control_child_metadata(
                parent_fd,
                MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                f"terminal primary private-control child [{spec.root_id}]",
            )
        else:
            tool_record = _mirror_legacy_child_metadata(
                parent_fd,
                MIRROR_PRIVATE_TOOL_ROOT_NAME,
                spec.root_id,
            )
            quarantine_record = _mirror_legacy_child_metadata(
                parent_fd,
                MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                spec.root_id,
            )
        if spec.allocate or audit.classification != "foreign-unrelated":
            _validate_mirror_private_control_metadata_topology(
                root_id=spec.root_id,
                parent_fd=parent_fd,
                parent_identity=parent_identity,
                tool_record=tool_record,
                quarantine_record=quarantine_record,
            )
        if (
            tool_record != receipt.tool_record
            or quarantine_record != receipt.quarantine_record
        ):
            raise SyncError(
                "private-control fixed-name identity or access policy changed"
            )
        if adopted:
            assert receipt.adoption_plan_digest is not None
            adopted_tool_fd = -1
            adopted_quarantine_fd = -1
            adopted_tool_locked = False
            adopted_quarantine_locked = False
            with _mirror_descriptor_cleanup_scope(
                lambda: (
                    (
                        f"terminal adopted quarantine [{spec.root_id}]",
                        adopted_quarantine_fd,
                        adopted_quarantine_locked,
                    ),
                    (
                        f"terminal adopted tool root [{spec.root_id}]",
                        adopted_tool_fd,
                        adopted_tool_locked,
                    ),
                ),
                label="terminal adopted recovery cleanup failures",
            ):
                (
                    adopted_tool_fd,
                    adopted_tool_identity,
                    adopted_tool_access,
                ) = _bind_mirror_audit_child_directory(
                    parent_fd,
                    parent_path,
                    MIRROR_PRIVATE_TOOL_ROOT_NAME,
                    f"terminal adopted tool root [{spec.root_id}]",
                )
                if (
                    adopted_tool_identity,
                    adopted_tool_access,
                ) != receipt.tool_record:
                    raise SyncError(
                        "adopted legacy tool root changed before terminal binding"
                    )
                _acquire_mirror_audit_shared_lock(
                    adopted_tool_fd,
                    f"terminal adopted tool root [{spec.root_id}]",
                )
                adopted_tool_locked = True
                (
                    adopted_quarantine_fd,
                    adopted_quarantine_identity,
                    adopted_quarantine_access,
                ) = _bind_mirror_audit_child_directory(
                    parent_fd,
                    parent_path,
                    MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                    f"terminal adopted quarantine [{spec.root_id}]",
                )
                if (
                    adopted_quarantine_identity,
                    adopted_quarantine_access,
                ) != receipt.quarantine_record:
                    raise SyncError(
                        "adopted legacy quarantine changed before terminal binding"
                    )
                _validate_mirror_private_control_bound_topology(
                    root_id=spec.root_id,
                    parent_fd=parent_fd,
                    parent_identity=parent_identity,
                    tool_fd=adopted_tool_fd,
                    tool_identity=adopted_tool_identity,
                    quarantine_fd=adopted_quarantine_fd,
                    quarantine_identity=adopted_quarantine_identity,
                )
                _acquire_mirror_audit_shared_lock(
                    adopted_quarantine_fd,
                    f"terminal adopted quarantine [{spec.root_id}]",
                )
                adopted_quarantine_locked = True
                recovery_parent = _PrivateControlRecoveryBinding(
                    label=f"terminal legacy parent [{spec.root_id}]",
                    path=parent_path,
                    fd=parent_fd,
                    identity=parent_identity,
                    access=parent_access_policy,
                )
                recovery_tool = _PrivateControlRecoveryBinding(
                    label=f"terminal legacy tool root [{spec.root_id}]",
                    path=parent_path / MIRROR_PRIVATE_TOOL_ROOT_NAME,
                    fd=adopted_tool_fd,
                    identity=adopted_tool_identity,
                    access=adopted_tool_access,
                )
                recovery_quarantine = _PrivateControlRecoveryBinding(
                    label=f"terminal legacy quarantine [{spec.root_id}]",
                    path=parent_path / MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                    fd=adopted_quarantine_fd,
                    identity=adopted_quarantine_identity,
                    access=adopted_quarantine_access,
                )
                terminal_digest = _pc_recovery_audit_adoption_locked(
                    spec,
                    recovery_parent,
                    recovery_tool,
                    recovery_quarantine,
                    expected_plan_digest=receipt.adoption_plan_digest,
                )
                if terminal_digest != receipt.adoption_plan_digest:
                    raise SyncError(
                        "adopted retained-in-place recovery publication disappeared"
                    )
                final_tool = _mirror_legacy_child_metadata(
                    parent_fd,
                    MIRROR_PRIVATE_TOOL_ROOT_NAME,
                    spec.root_id,
                )
                final_quarantine = _mirror_legacy_child_metadata(
                    parent_fd,
                    MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
                    spec.root_id,
                )
                if (
                    final_tool != receipt.tool_record
                    or final_quarantine != receipt.quarantine_record
                ):
                    raise SyncError(
                        "adopted legacy fixed roots changed during terminal verification"
                    )
                _revalidate_mirror_audit_directory(
                    recovery_tool.path,
                    recovery_tool.fd,
                    recovery_tool.identity,
                    recovery_tool.access,
                    recovery_tool.label,
                )
                _revalidate_mirror_audit_directory(
                    recovery_quarantine.path,
                    recovery_quarantine.fd,
                    recovery_quarantine.identity,
                    recovery_quarantine.access,
                    recovery_quarantine.label,
                )
                _revalidate_mirror_audit_directory(
                    parent_path,
                    parent_fd,
                    parent_identity,
                    parent_access_policy,
                    f"terminal private-control parent [{spec.root_id}]",
                )
                return "stable(adopted-retained-in-place)"
        _revalidate_mirror_audit_directory(
            parent_path,
            parent_fd,
            parent_identity,
            parent_access_policy,
            f"terminal private-control parent [{spec.root_id}]",
        )
        return "stable(fixed-metadata)"


def _revalidate_mirror_quarantine_registry(
    root_audits: list[MirrorQuarantineAudit],
) -> tuple[list[MirrorQuarantineAudit], str | None]:
    if len(root_audits) != len(MIRROR_PRIVATE_CONTROL_ROOT_SPECS):
        raise SyncError("private-control registry audit coverage is incomplete")
    updated: list[MirrorQuarantineAudit] = []
    statuses: list[str] = []
    failed = False
    for spec, audit in zip(MIRROR_PRIVATE_CONTROL_ROOT_SPECS, root_audits):
        try:
            state = _revalidate_mirror_quarantine_root_receipt(spec, audit)
        except (OSError, SyncError) as error:
            failed = True
            statuses.append(f"{spec.root_id}=inconclusive({error})")
            updated.append(
                replace(
                    audit,
                    classification="inconclusive",
                    reason_code=(
                        audit.reason_code
                        if audit.reason_code
                        == MIRROR_PRIVATE_OWNER_RECORD_REASON_ROOT_MISMATCH
                        else MIRROR_PRIVATE_CONTROL_REASON_INCONCLUSIVE
                    ),
                    detail=(
                        f"terminal root revalidation failed: {error}"
                        if audit.detail is None
                        else f"{audit.detail}; terminal root revalidation "
                        f"failed: {error}"
                    ),
                )
            )
        else:
            statuses.append(f"{spec.root_id}={state}")
            updated.append(audit)
    if not failed:
        return updated, None
    return (
        updated,
        "terminal mirror quarantine registry revalidation covered every root "
        f"[{'; '.join(statuses)}]",
    )


def _mirror_quarantine_audit() -> MirrorQuarantineAudit:
    root_ids = [spec.root_id for spec in MIRROR_PRIVATE_CONTROL_ROOT_SPECS]
    if len(root_ids) != len(set(root_ids)):
        raise SyncError("private-control root ids must be unique")
    if sum(1 for spec in MIRROR_PRIVATE_CONTROL_ROOT_SPECS if spec.allocate) != 1:
        raise SyncError(
            "private-control registry must contain exactly one allocation root"
        )
    allocation_root_id = next(
        spec.root_id for spec in MIRROR_PRIVATE_CONTROL_ROOT_SPECS if spec.allocate
    )
    root_audits: list[MirrorQuarantineAudit] = []
    seen_parent_identities: set[tuple[int, int, int]] = set()
    seen_child_identities: set[tuple[int, int, int]] = set()
    for spec in MIRROR_PRIVATE_CONTROL_ROOT_SPECS:
        try:
            audit = _mirror_quarantine_root_audit(
                spec,
                seen_parent_identities,
                seen_child_identities,
            )
        except (OSError, SyncError) as error:
            audit = MirrorQuarantineAudit(
                classification="inconclusive",
                path=(
                    Path(os.path.abspath(spec.parent_path))
                    / MIRROR_DURABLE_QUARANTINE_ROOT_NAME
                ),
                entry_count=None,
                entry_limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
                count_is_lower_bound=False,
                segment_identity=None,
                segment_access_policy=None,
                detail=f"initial root audit failed: {error}",
                root_id=spec.root_id,
                reason_code=MIRROR_PRIVATE_CONTROL_REASON_INCONCLUSIVE,
            )
        if audit.classification == "duplicate":
            root_audits.append(audit)
            continue
        receipt = audit.root_receipt
        root_parent_identity = (
            receipt.parent_identity
            if receipt is not None
            else audit.root_parent_identity
        )
        observed_child_identities = (
            tuple(
                identity
                for identity in (audit.tool_identity, audit.segment_identity)
                if identity is not None
            )
            if receipt is None
            else tuple(
                record[0]
                for record in (receipt.tool_record, receipt.quarantine_record)
                if record is not None
            )
        )
        child_identities = set(observed_child_identities)
        alias_error = None
        if (
            root_parent_identity is not None
            and root_parent_identity in seen_child_identities
        ):
            alias_error = "private-control parent aliases an earlier fixed child"
        elif len(child_identities) != len(observed_child_identities):
            alias_error = "private-control fixed child roles alias each other"
        elif (
            root_parent_identity is not None
            and root_parent_identity in child_identities
        ):
            alias_error = "private-control fixed child aliases its own parent"
        elif child_identities & (seen_parent_identities | seen_child_identities):
            alias_error = (
                "distinct private-control parent aliases an earlier control object"
            )
        if alias_error is not None:
            audit = replace(
                audit,
                classification="inconclusive",
                reason_code=MIRROR_PRIVATE_CONTROL_REASON_INCONCLUSIVE,
                detail=(
                    alias_error
                    if audit.detail is None
                    else f"{audit.detail}; {alias_error}"
                ),
            )
        if root_parent_identity is not None:
            seen_parent_identities.add(root_parent_identity)
        seen_child_identities.update(child_identities)
        root_audits.append(audit)
    root_audits, terminal_revalidation_detail = _revalidate_mirror_quarantine_registry(
        root_audits
    )
    legacy_states = tuple(
        (
            audit.reason_code
            if audit.reason_code is not None
            else "adopted-retained-in-place"
            if audit.classification == "adopted-retained-in-place"
            else "foreign-unrelated"
            if audit.classification == "foreign-unrelated"
            else "absent"
            if audit.classification == "absent"
            else "duplicate"
            if audit.classification == "duplicate"
            else "same-uid-empty"
            if audit.classification == "available" and audit.entry_count == 0
            else MIRROR_PRIVATE_CONTROL_REASON_LEGACY_PENDING
        )
        for audit in root_audits
        if audit.root_id != allocation_root_id
    )
    allocation_allowed, aggregate_reason = (
        _mirror_private_control_preallocation_decision(legacy_states)
    )
    if terminal_revalidation_detail is not None:
        allocation_allowed = False
        if aggregate_reason is None:
            aggregate_reason = MIRROR_PRIVATE_CONTROL_REASON_INCONCLUSIVE
    decisive = None
    if not allocation_allowed:
        decisive = next(
            (
                audit
                for audit in root_audits
                if audit.reason_code == aggregate_reason
                or (
                    aggregate_reason == MIRROR_PRIVATE_CONTROL_REASON_INCONCLUSIVE
                    and audit.classification == "inconclusive"
                )
            ),
            None,
        )
    if decisive is None:
        decisive = next(
            (audit for audit in root_audits if audit.classification == "inconclusive"),
            None,
        )
    if decisive is None:
        decisive = next(
            (audit for audit in root_audits if audit.classification == "saturated"),
            None,
        )
    if decisive is None:
        decisive = next(
            (audit for audit in root_audits if audit.root_id == allocation_root_id),
            root_audits[0],
        )
    return replace(
        decisive,
        classification=(
            "inconclusive" if not allocation_allowed else decisive.classification
        ),
        reason_code=(
            aggregate_reason if not allocation_allowed else decisive.reason_code
        ),
        detail=(
            decisive.detail
            if terminal_revalidation_detail is None
            else (
                terminal_revalidation_detail
                if decisive.detail is None
                else f"{decisive.detail}; {terminal_revalidation_detail}"
            )
        ),
        root_audits=tuple(root_audits),
    )


def _mirror_quarantine_failure_detail(
    audit: MirrorQuarantineAudit,
) -> str:
    rendered_count = (
        "unknown"
        if audit.entry_count is None
        else (
            f">={audit.entry_count}"
            if audit.count_is_lower_bound
            else str(audit.entry_count)
        )
    )
    identity = (
        "unknown"
        if audit.segment_identity is None
        else ":".join(f"{component:x}" for component in audit.segment_identity)
    )
    access_policy = (
        "unknown"
        if audit.segment_access_policy is None
        else (
            f"{audit.segment_access_policy[0]:04o}:"
            f"{audit.segment_access_policy[1]}:"
            f"{audit.segment_access_policy[2]}"
        )
    )
    blocked_recovery_records = [
        record
        for record in audit.owner_records
        if record.state == "stale" and record.private_state in {"missing", "matching"}
    ]

    def render_owner(record: MirrorQuarantineOwnerRecord) -> str:
        owner_identity = ":".join(f"{component:x}" for component in record.identity)
        owner_access_policy = (
            f"{record.access_policy[0]:04o}:"
            f"{record.access_policy[1]}:"
            f"{record.access_policy[2]}"
        )
        expected_private_identity = (
            "none"
            if record.expected_private_identity is None
            else ":".join(
                f"{component:x}" for component in record.expected_private_identity
            )
        )
        observed_private_identity = (
            "none"
            if record.observed_private_identity is None
            else ":".join(
                f"{component:x}" for component in record.observed_private_identity
            )
        )
        return (
            f"{record.name}"
            f"[identity={owner_identity},access={owner_access_policy},"
            f"sha256={record.sha256 or 'unavailable'},"
            f"root={record.root_id},reason={record.reason_code},"
            f"pid={record.owner_pid},nonce={record.owner_nonce},"
            f"phase={record.phase},private={record.private_name},"
            f"expected-private-identity={expected_private_identity},"
            f"observed-private-identity={observed_private_identity},"
            f"private-state={record.private_state}]"
        )

    recovery_preview = (
        ", ".join(render_owner(record) for record in blocked_recovery_records[:8])
        or "none"
    )
    if len(blocked_recovery_records) > 8:
        recovery_preview += f", ... ({len(blocked_recovery_records) - 8} more)"
    detail = (
        f"mirror durable quarantine root {audit.root_id} segment {audit.path} is "
        f"{audit.classification}: count={rendered_count}, "
        f"cap={audit.entry_limit}, identity={identity}, access={access_policy}, "
        f"blocked-recovery-owner-records={recovery_preview}"
    )
    if audit.detail:
        detail += f"; audit-error={audit.detail}"
    return detail


def scheduler_report(home: Path, platform_name: str) -> SchedulerReport:
    home = home.expanduser()
    selected_platform = _scheduler_platform(platform_name)
    paths = _scheduler_paths(selected_platform, home)
    config: SchedulerConfig | None = None
    config_audit: SchedulerConfigAudit | None = None
    config_bindings: tuple[SchedulerActivationBinding, ...] = ()
    status_bindings: tuple[SchedulerActivationBinding, ...] = ()
    retained_activation_snapshot = False
    retained_uninstall_snapshot = False
    config_binding_stack = contextlib.ExitStack()
    failures: list[tuple[str | None, str]] = []
    activation_snapshot: ManagedStateFileSnapshot | None = None
    uninstall_snapshot: ManagedStateFileSnapshot | None = None
    activation_problem = False
    uninstall_problem = False
    config_problem = False
    activation_codes = {
        "scheduler-activation-incomplete",
        "scheduler-activation-state-invalid",
    }
    uninstall_codes = {
        "scheduler-uninstall-incomplete",
        "scheduler-uninstall-state-invalid",
    }
    transaction_codes = activation_codes | uninstall_codes

    def record_failure(
        code: str | None,
        reason: str,
        *,
        primary: bool = False,
    ) -> None:
        entry = (code, reason)
        if primary and code is not None:
            failures[:] = [existing for existing in failures if existing[0] != code]
        if entry in failures:
            if primary:
                failures.remove(entry)
                failures.insert(0, entry)
        elif primary:
            failures.insert(0, entry)
        else:
            failures.append(entry)

    try:
        uninstall_snapshot, _recorded_disable = _scheduler_uninstall_transaction_state(
            home,
            paths,
        )
        if uninstall_snapshot.exists:
            uninstall_problem = True
            marker = _scheduler_uninstall_transaction_path(paths)
            record_failure(
                "scheduler-uninstall-incomplete",
                f"scheduler has an incomplete uninstall transaction: {marker}",
                primary=True,
            )
    except SyncError as error:
        uninstall_problem = True
        record_failure(
            error.code or "scheduler-uninstall-state-invalid",
            str(error),
            primary=True,
        )
    try:
        activation_snapshot = _scheduler_activation_transaction_state(home, paths)
        if activation_snapshot.exists:
            activation_problem = True
            marker = _scheduler_activation_transaction_path(paths)
            record_failure(
                "scheduler-activation-incomplete",
                f"scheduler has an incomplete activation transaction: {marker}",
                primary=True,
            )
    except SyncError as error:
        activation_problem = True
        record_failure(
            error.code or "scheduler-activation-state-invalid",
            str(error),
            primary=True,
        )
    try:
        config_audit = _audit_scheduler_config(paths)
        config = config_audit.config
        if config is not None:
            config_bindings = config_binding_stack.enter_context(
                _retain_scheduler_config_audit_bindings(
                    paths,
                    config_audit,
                )
            )
            status_bindings = config_bindings
    except SyncError as error:
        config_binding_stack.close()
        config_binding_stack = contextlib.ExitStack()
        config = None
        config_audit = None
        config_bindings = ()
        config_problem = True
        record_failure(
            error.code or "scheduler-config-invalid",
            str(error),
        )
    if (
        activation_snapshot is not None
        and activation_snapshot.parent_identity is not None
        and not config_problem
    ):
        try:
            activation_binding = config_binding_stack.enter_context(
                _retain_launchd_activation_binding(
                    _scheduler_activation_transaction_path(paths),
                    activation_snapshot,
                    description="scheduler activation transaction",
                    failure_code="scheduler-activation-incomplete",
                )
            )
            status_bindings = (*config_bindings, activation_binding)
            retained_activation_snapshot = True
        except SyncError as error:
            activation_problem = True
            record_failure(
                error.code or "scheduler-activation-state-invalid",
                str(error),
                primary=True,
            )
    if (
        uninstall_snapshot is not None
        and uninstall_snapshot.parent_identity is not None
        and not uninstall_problem
        and not config_problem
    ):
        try:
            uninstall_binding = config_binding_stack.enter_context(
                _retain_launchd_activation_binding(
                    _scheduler_uninstall_transaction_path(paths),
                    uninstall_snapshot,
                    description="scheduler uninstall transaction",
                    failure_code="scheduler-uninstall-incomplete",
                )
            )
            status_bindings = (*status_bindings, uninstall_binding)
            retained_uninstall_snapshot = True
        except SyncError as error:
            uninstall_problem = True
            record_failure(
                error.code or "scheduler-uninstall-state-invalid",
                str(error),
                primary=True,
            )
    runtime_state: dict[str, Any] | None = None
    try:
        runtime_state = _read_scheduler_runtime_state(home)
    except SyncError as error:
        record_failure(
            error.code or "scheduler-state-invalid",
            str(error),
        )
    runtime_matches_config = (
        runtime_state is not None
        and config is not None
        and not (
            runtime_state["mode"] != config.mode
            or runtime_state["repo"] != config.repo
            or runtime_state["base_repo"] != config.base_repo
            or runtime_state["owner"] != config.owner
        )
    )
    if runtime_state is not None and config is not None and not runtime_matches_config:
        record_failure(
            "scheduler-target-mismatch",
            "scheduler runtime state belongs to a different configured target",
        )
    elif (
        runtime_matches_config
        and runtime_state is not None
        and not runtime_state["success"]
    ):
        record_failure(
            runtime_state.get("failure_code"),
            runtime_state["failure_reason"] or "last scheduled sync failed",
        )
    try:
        current_releases = _current_releases_for_scheduler(home, config)
    except SyncError as error:
        current_releases = ()
        record_failure(
            error.code or "current-release-unverifiable",
            str(error),
        )
    release_baseline = (
        runtime_state.get("release_trees", {})
        if runtime_matches_config and runtime_state is not None
        else {}
    )
    release_integrity = _scheduler_release_integrity_issues(
        home,
        current_releases,
        release_baseline,
    )
    actionable_release_integrity = [
        issue
        for issue in release_integrity
        if issue[0] != "immutable-release-baseline-missing"
    ]
    for code, _owner, _sha, detail in actionable_release_integrity:
        record_failure(code, detail)
    try:
        mirror_quarantine = _mirror_quarantine_audit()
    except (OSError, SyncError) as error:
        mirror_quarantine = MirrorQuarantineAudit(
            classification="inconclusive",
            path=(
                Path(os.path.abspath(MIRROR_PRIVATE_CONTROL_PARENT))
                / MIRROR_DURABLE_QUARANTINE_ROOT_NAME
            ),
            entry_count=None,
            entry_limit=MIRROR_DURABLE_QUARANTINE_ENTRY_LIMIT,
            count_is_lower_bound=False,
            segment_identity=None,
            segment_access_policy=None,
            detail=f"mirror quarantine audit failed unexpectedly: {error}",
        )
    if mirror_quarantine.classification == "saturated":
        record_failure(
            "mirror-quarantine-saturated",
            _mirror_quarantine_failure_detail(mirror_quarantine),
        )
    elif mirror_quarantine.classification == "inconclusive":
        record_failure(
            mirror_quarantine.reason_code or "mirror-quarantine-audit-inconclusive",
            _mirror_quarantine_failure_detail(mirror_quarantine),
        )
    try:
        quarantine_batches = _quarantine_batch_count(home)
    except (OSError, SyncError) as error:
        quarantine_batches = None
        record_failure(
            "quarantine-audit-inconclusive",
            f"quarantine capacity audit failed: {error}",
        )
    installed = config is not None
    stable_runner = _stable_scheduler_runner_matches(home, config)
    if installed and not stable_runner:
        record_failure(
            "scheduler-runner-drift",
            "scheduler does not use the stable installed runner path",
        )
    enabled: bool | None = None
    daemon_query: SchedulerDaemonQuery | None = None
    daemon_failure_is_transaction = False
    if activation_problem or uninstall_problem or config_problem:
        daemon_failure_is_transaction = True
        if activation_problem:
            daemon_query = SchedulerDaemonQuery(
                "unavailable",
                "scheduler activation is incomplete; the on-disk "
                "configuration is not proven loaded",
            )
        elif uninstall_problem:
            daemon_query = SchedulerDaemonQuery(
                "unavailable",
                "scheduler uninstall is incomplete; daemon state is not "
                "proven terminal",
            )
        else:
            daemon_query = SchedulerDaemonQuery(
                "unavailable",
                "scheduler configuration is invalid; daemon state cannot be "
                "bound to an audited configuration",
            )
    else:
        try:
            raw_daemon_query = _scheduler_daemon_enabled(
                paths,
                config_audit=config_audit,
                activation_bindings=status_bindings,
                activation_snapshot=(
                    activation_snapshot if not retained_activation_snapshot else None
                ),
                uninstall_snapshot=(
                    uninstall_snapshot if not retained_uninstall_snapshot else None
                ),
            )
            if isinstance(raw_daemon_query, SchedulerDaemonQuery):
                daemon_query = raw_daemon_query
            elif raw_daemon_query is True:
                daemon_query = SchedulerDaemonQuery("enabled")
            elif raw_daemon_query is False:
                daemon_query = SchedulerDaemonQuery(
                    "disabled",
                    "scheduler daemon explicitly reports a disabled state",
                )
            else:
                daemon_query = SchedulerDaemonQuery(
                    "unavailable",
                    "scheduler daemon query returned no structured evidence",
                )
        except SyncError as error:
            failure_code = error.code or "scheduler-config-drift"
            daemon_failure_is_transaction = failure_code in transaction_codes
            record_failure(
                failure_code,
                str(error),
                primary=True,
            )
            daemon_query = SchedulerDaemonQuery(
                "unavailable",
                "scheduler daemon query was invalidated by scheduler "
                "configuration or transaction drift",
            )
    assert daemon_query is not None
    enabled = daemon_query.enabled
    if installed:
        if daemon_query.classification == "disabled":
            record_failure(
                "scheduler-daemon-disabled",
                daemon_query.reason or "scheduler daemon is not enabled",
            )
        elif daemon_query.classification in {
            "active-disabled",
            "enabled-inactive",
        }:
            record_failure(
                "scheduler-daemon-disabled",
                daemon_query.reason
                or "scheduler daemon is active without durable enablement",
            )
        elif daemon_query.classification == "unavailable":
            if not daemon_failure_is_transaction:
                record_failure(
                    "scheduler-daemon-unavailable",
                    daemon_query.reason or "scheduler daemon state is unavailable",
                )
        elif daemon_query.classification != "enabled":
            daemon_query = SchedulerDaemonQuery(
                "unavailable",
                "scheduler daemon query returned an invalid classification",
            )
            enabled = None
            record_failure(
                "scheduler-daemon-unavailable",
                daemon_query.reason,
            )
    elif daemon_query.classification in {
        "active-disabled",
        "enabled",
        "enabled-inactive",
    }:
        enabled = True
        record_failure(
            "scheduler-orphan-active",
            daemon_query.reason
            or "scheduler daemon is active without installed configuration",
            primary=True,
        )
    elif daemon_query.classification == "unavailable":
        if not daemon_failure_is_transaction:
            record_failure(
                "scheduler-daemon-unavailable",
                daemon_query.reason or "scheduler daemon state is unavailable",
            )
    elif daemon_query.classification != "disabled":
        daemon_query = SchedulerDaemonQuery(
            "unavailable",
            "scheduler daemon query returned an invalid classification",
        )
        enabled = None
        record_failure(
            "scheduler-daemon-unavailable",
            daemon_query.reason,
        )
    try:
        config_binding_stack.close()
    except SyncError as error:
        failure_code = error.code or "scheduler-config-drift"
        transaction_drift = failure_code in transaction_codes
        record_failure(
            failure_code,
            str(error),
            primary=True,
        )
        daemon_query = SchedulerDaemonQuery(
            "unavailable",
            "scheduler daemon query was invalidated by scheduler "
            "configuration or transaction drift",
        )
        enabled = None
        if daemon_query is not None:
            failures[:] = [
                entry
                for entry in failures
                if entry[0]
                not in {
                    "scheduler-daemon-disabled",
                    "scheduler-daemon-unavailable",
                    "scheduler-orphan-active",
                }
            ]
            if not transaction_drift:
                record_failure(
                    "scheduler-daemon-unavailable",
                    daemon_query.reason,
                )
    config_paths = (
        config.config_paths
        if config is not None
        else tuple(
            path
            for path in (
                paths.launchd_plist,
                paths.systemd_service,
                paths.systemd_timer,
            )
            if path is not None
        )
    )
    failure_code, failure_reason = failures[0] if failures else (None, None)
    return SchedulerReport(
        platform=selected_platform,
        installed=installed,
        enabled=enabled,
        config_paths=config_paths,
        interval_minutes=config.interval_minutes if config is not None else None,
        runner=config.runner if config is not None else None,
        stable_runner=stable_runner,
        command=config.command if config is not None else None,
        mode=config.mode if config is not None else None,
        repo=config.repo if config is not None else None,
        base_repo=config.base_repo if config is not None else None,
        private_repo=(
            config.repo if config is not None and config.mode == "private" else None
        ),
        owner=config.owner if config is not None else None,
        migration_needed=(
            config is not None
            and (
                config.command != "run-scheduled"
                or (
                    config.platform == "macos"
                    and config.launchd_profile != MACOS_LAUNCHD_PROFILE_AQUA
                )
            )
        ),
        last_attempt=(
            runtime_state.get("last_attempt")
            if runtime_matches_config and runtime_state is not None
            else None
        ),
        recent_success=(
            runtime_state.get("last_success")
            if runtime_matches_config and runtime_state is not None
            else None
        ),
        current_releases=current_releases,
        failure_reason=failure_reason,
        failure_code=failure_code,
        quarantine_batches=quarantine_batches,
        mirror_quarantine=mirror_quarantine,
        release_integrity=release_integrity,
        daemon_query=daemon_query,
        failures=tuple(failures),
    )


def _scheduler_report_failures(
    report: SchedulerReport,
) -> tuple[tuple[str | None, str], ...]:
    if report.failures:
        return report.failures
    if report.failure_reason is None:
        return ()
    return ((report.failure_code, report.failure_reason),)


def _mirror_identity_payload(
    identity: tuple[int, int, int] | None,
) -> dict[str, int] | None:
    if identity is None:
        return None
    return {
        "device": identity[0],
        "inode": identity[1],
        "file_type": identity[2],
    }


def _mirror_access_policy_payload(
    access_policy: tuple[int, int, int] | None,
) -> dict[str, int] | None:
    if access_policy is None:
        return None
    return {
        "mode": access_policy[0],
        "uid": access_policy[1],
        "gid": access_policy[2],
    }


def _mirror_quarantine_payload(
    audit: MirrorQuarantineAudit | None,
) -> dict[str, Any] | None:
    if audit is None:
        return None
    payload = {
        "classification": audit.classification,
        "root_id": audit.root_id,
        "reason_code": audit.reason_code,
        "path": str(audit.path),
        "entry_count": audit.entry_count,
        "entry_limit": audit.entry_limit,
        "segment_name": MIRROR_DURABLE_QUARANTINE_ROOT_NAME,
        "segment_entry_count": audit.entry_count,
        "segment_entry_limit": audit.entry_limit,
        "count_is_lower_bound": audit.count_is_lower_bound,
        "segment_identity": _mirror_identity_payload(audit.segment_identity),
        "root_parent_identity": _mirror_identity_payload(audit.root_parent_identity),
        "segment_access_policy": _mirror_access_policy_payload(
            audit.segment_access_policy
        ),
        "owner_records": [
            {
                "name": record.name,
                "identity": _mirror_identity_payload(record.identity),
                "access_policy": _mirror_access_policy_payload(record.access_policy),
                "sha256": record.sha256,
                "state": record.state,
                "detail": record.detail,
                "root_id": record.root_id,
                "reason_code": record.reason_code,
                "owner_pid": record.owner_pid,
                "owner_nonce": record.owner_nonce,
                "phase": record.phase,
                "private_name": record.private_name,
                "expected_private_identity": _mirror_identity_payload(
                    record.expected_private_identity
                ),
                "observed_private_identity": _mirror_identity_payload(
                    record.observed_private_identity
                ),
                "private_state": record.private_state,
            }
            for record in audit.owner_records
        ],
        "detail": audit.detail,
    }
    payload["roots"] = [
        _mirror_quarantine_payload(replace(root_audit, root_audits=()))
        for root_audit in audit.root_audits
    ]
    return payload


def _scheduler_report_payload(report: SchedulerReport) -> dict[str, Any]:
    return {
        "platform": report.platform,
        "installed": report.installed,
        "enabled": report.enabled,
        "config": [str(path) for path in report.config_paths],
        "interval_minutes": report.interval_minutes,
        "runner": str(report.runner) if report.runner is not None else None,
        "stable_runner": report.stable_runner,
        "command": report.command,
        "mode": report.mode,
        "repo": report.repo,
        "base_repo": report.base_repo,
        "private_repo": report.private_repo,
        "owner": report.owner,
        "migration_needed": report.migration_needed,
        "last_attempt": report.last_attempt,
        "recent_success": report.recent_success,
        "current_release": dict(report.current_releases),
        "release_integrity": [
            {
                "code": code,
                "owner": owner,
                "sha": sha,
                "detail": detail,
            }
            for code, owner, sha, detail in report.release_integrity
        ],
        "quarantine_batches": report.quarantine_batches,
        "quarantine_limit": report.quarantine_limit,
        "mirror_quarantine": _mirror_quarantine_payload(report.mirror_quarantine),
        "failure_code": report.failure_code,
        "failure_reason": report.failure_reason,
        "daemon_query": (
            {
                "classification": report.daemon_query.classification,
                "reason": report.daemon_query.reason,
            }
            if report.daemon_query is not None
            else None
        ),
        "failures": [
            {
                "code": code,
                "reason": reason,
            }
            for code, reason in _scheduler_report_failures(report)
        ],
    }


def status_scheduler(
    home: Path,
    platform_name: str,
    *,
    json_output: bool,
) -> SchedulerReport:
    report = scheduler_report(home, platform_name)
    payload = _scheduler_report_payload(report)
    if json_output:
        print(json.dumps(payload, indent=2, sort_keys=True))
        return report
    _print_scheduler_report(report)
    return report


def _print_scheduler_report(report: SchedulerReport) -> None:
    print(f"scheduler platform: {report.platform}")
    print(f"scheduler installed: {'yes' if report.installed else 'no'}")
    print(
        "scheduler enabled: "
        + ("unknown" if report.enabled is None else ("yes" if report.enabled else "no"))
    )
    print(
        "scheduler config: "
        + (", ".join(str(path) for path in report.config_paths) or "none")
    )
    print(
        "scheduler interval: "
        + (
            f"{report.interval_minutes} minute(s)"
            if report.interval_minutes is not None
            else "unknown"
        )
    )
    print(f"scheduler runner: {report.runner or 'unknown'}")
    print(f"scheduler stable runner: {'yes' if report.stable_runner else 'no'}")
    print(f"scheduler command: {report.command or 'unknown'}")
    print(f"scheduler mode: {report.mode or 'unknown'}")
    print(f"scheduler repo: {report.repo or 'unknown'}")
    print(f"scheduler base repo: {report.base_repo or 'unknown'}")
    print(f"scheduler private repo: {report.private_repo or 'none'}")
    print(f"scheduler owner: {report.owner or 'unknown'}")
    print("scheduler migration needed: " + ("yes" if report.migration_needed else "no"))
    print(f"scheduler last attempt: {report.last_attempt or 'none'}")
    print(f"scheduler recent success: {report.recent_success or 'none'}")
    print(
        "scheduler current release: "
        + (
            ", ".join(f"{owner}@{sha}" for owner, sha in report.current_releases)
            or "none"
        )
    )
    print(
        "scheduler release integrity: "
        + (
            "; ".join(
                f"{code} {owner}@{sha}: {detail}"
                for code, owner, sha, detail in report.release_integrity
            )
            or "ok"
        )
    )
    print(
        "scheduler quarantine batches: "
        + (
            "unknown"
            if report.quarantine_batches is None
            else (f"{report.quarantine_batches}/{report.quarantine_limit}")
        )
    )
    if report.mirror_quarantine is None:
        print("scheduler mirror quarantine: unknown")
    else:
        mirror_count = (
            "unknown"
            if report.mirror_quarantine.entry_count is None
            else (
                f">={report.mirror_quarantine.entry_count}"
                if report.mirror_quarantine.count_is_lower_bound
                else str(report.mirror_quarantine.entry_count)
            )
        )
        mirror_identity = (
            "unknown"
            if report.mirror_quarantine.segment_identity is None
            else ":".join(
                f"{component:x}"
                for component in report.mirror_quarantine.segment_identity
            )
        )
        mirror_access_policy = (
            "unknown"
            if report.mirror_quarantine.segment_access_policy is None
            else (
                f"{report.mirror_quarantine.segment_access_policy[0]:04o}:"
                f"{report.mirror_quarantine.segment_access_policy[1]}:"
                f"{report.mirror_quarantine.segment_access_policy[2]}"
            )
        )
        blocked_recovery_records = [
            record
            for record in report.mirror_quarantine.owner_records
            if record.state == "stale"
            and record.private_state in {"missing", "matching"}
        ]
        print(
            "scheduler mirror quarantine: "
            f"{report.mirror_quarantine.classification} "
            f"root={report.mirror_quarantine.root_id} "
            f"reason={report.mirror_quarantine.reason_code or 'none'} "
            f"{mirror_count}/{report.mirror_quarantine.entry_limit} "
            f"segment={MIRROR_DURABLE_QUARANTINE_ROOT_NAME} "
            f"path={report.mirror_quarantine.path} "
            f"identity={mirror_identity} "
            f"access={mirror_access_policy} "
            "blocked-recovery-owner-records="
            + (
                ", ".join(
                    (
                        f"{record.name}"
                        f"[identity={':'.join(f'{item:x}' for item in record.identity)},"
                        f"access={record.access_policy[0]:04o}:"
                        f"{record.access_policy[1]}:{record.access_policy[2]},"
                        f"sha256={record.sha256 or 'unavailable'},"
                        f"phase={record.phase},nonce={record.owner_nonce},"
                        f"private={record.private_name},"
                        f"private-state={record.private_state}]"
                    )
                    for record in blocked_recovery_records
                )
                or "none"
            )
        )
    print(f"scheduler failure code: {report.failure_code or 'none'}")
    print(f"scheduler failure reason: {report.failure_reason or 'none'}")
    print(
        "scheduler daemon query: "
        + (
            "not-run"
            if report.daemon_query is None
            else (
                report.daemon_query.classification
                + (
                    f" ({report.daemon_query.reason})"
                    if report.daemon_query.reason is not None
                    else ""
                )
            )
        )
    )
    print(
        "scheduler failures: "
        + (
            "; ".join(
                f"{code or 'scheduler-failure'}: {reason}"
                for code, reason in _scheduler_report_failures(report)
            )
            or "none"
        )
    )


def _non_empty_env(name: str) -> str | None:
    value = os.environ.get(name)
    if value is None:
        return None
    value = value.strip()
    return value or None


def default_release_repo() -> str | None:
    return _non_empty_env(DEFAULT_RELEASE_REPO_ENV)


def default_base_release_repo() -> str:
    return _non_empty_env(DEFAULT_BASE_RELEASE_REPO_ENV) or DEFAULT_PUBLIC_RELEASE_REPO


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Install personal Codex config from GitHub release assets."
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    release_repo = default_release_repo()
    base_release_repo = default_base_release_repo()

    install_parser = subparsers.add_parser(
        "install", help="Download and install latest release"
    )
    install_parser.add_argument(
        "--repo", default=release_repo, required=release_repo is None
    )
    install_parser.add_argument("--home", default="~/.codex")
    install_parser.add_argument("--dry-run", action="store_true")

    install_private_parser = subparsers.add_parser(
        "install-private",
        help="Install a public base release and then a private overlay release",
    )
    install_private_parser.add_argument(
        "--repo",
        default=release_repo,
        required=release_repo is None,
        help="Private overlay release repository",
    )
    install_private_parser.add_argument("--base-repo", default=base_release_repo)
    install_private_parser.add_argument("--owner", default="private")
    install_private_parser.add_argument("--home", default="~/.codex")
    install_private_parser.add_argument("--dry-run", action="store_true")

    status_parser = subparsers.add_parser(
        "status", help="Show current release and link state"
    )
    status_parser.add_argument("--home", default="~/.codex")
    status_parser.add_argument("--owner", default=PUBLIC_OWNER)
    status_parser.add_argument(
        "--strict",
        action="store_true",
        help="Exit non-zero when active skill discovery issues are found",
    )

    rollback_parser = subparsers.add_parser(
        "rollback", help="Switch current to an older release"
    )
    rollback_parser.add_argument("--home", default="~/.codex")
    rollback_parser.add_argument("--owner", default=PUBLIC_OWNER)
    rollback_parser.add_argument("--to", help="Exact or unique release SHA prefix")

    verify_overlay_parser = subparsers.add_parser(
        "verify-overlay",
        help="Verify an installed private overlay against the public base",
    )
    verify_overlay_parser.add_argument("--home", default="~/.codex")
    verify_overlay_parser.add_argument("--owner", default="private")

    release_identities_parser = subparsers.add_parser(
        "release-identities",
        help="Validate and report active release identities",
    )
    release_identities_parser.add_argument(
        "--mode", choices=("public", "private"), required=True
    )
    release_identities_parser.add_argument("--owner", default="private")
    release_identities_parser.add_argument("--home", default="~/.codex")
    release_identities_parser.add_argument("--json", action="store_true")

    uninstall_overlay_parser = subparsers.add_parser(
        "uninstall-overlay",
        help="Remove an overlay and restore public links for declared overrides",
    )
    uninstall_overlay_parser.add_argument("--home", default="~/.codex")
    uninstall_overlay_parser.add_argument("--owner", default="private")
    uninstall_overlay_parser.add_argument("--dry-run", action="store_true")

    scheduler_parser = subparsers.add_parser(
        "install-scheduler",
        help="Install a user-level scheduler that periodically runs install",
    )
    scheduler_parser.add_argument(
        "--repo",
        default=None,
        help=(
            "Release repository; preserves an existing audited scheduler value "
            "when omitted"
        ),
    )
    scheduler_parser.add_argument(
        "--mode",
        choices=("public", "private"),
        default=None,
        help="Scheduler mode; preserves an existing audited mode when omitted",
    )
    scheduler_parser.add_argument(
        "--base-repo",
        default=None,
        help="Public base repository for private mode; preserves it when omitted",
    )
    scheduler_parser.add_argument(
        "--owner",
        default=None,
        help="Overlay owner for private mode; preserves it when omitted",
    )
    scheduler_parser.add_argument("--home", default="~/.codex")
    scheduler_parser.add_argument(
        "--interval-minutes",
        type=int,
        default=None,
        help=(
            "Scheduler interval; preserves an existing audited interval when omitted "
            f"(new installs default to {DEFAULT_SCHEDULER_INTERVAL_MINUTES})"
        ),
    )
    scheduler_parser.add_argument(
        "--platform", choices=("auto", "macos", "linux"), default="auto"
    )
    scheduler_parser.add_argument("--runner", help="Executable sync script path")
    scheduler_parser.add_argument("--dry-run", action="store_true")
    scheduler_parser.add_argument(
        "--no-enable",
        action="store_true",
        help="Write scheduler files without loading/enabling them",
    )

    unscheduler_parser = subparsers.add_parser(
        "uninstall-scheduler",
        help="Disable and remove the user-level scheduler",
    )
    unscheduler_parser.add_argument("--home", default="~/.codex")
    unscheduler_parser.add_argument(
        "--platform", choices=("auto", "macos", "linux"), default="auto"
    )
    unscheduler_parser.add_argument("--dry-run", action="store_true")
    unscheduler_parser.add_argument(
        "--no-disable",
        action="store_true",
        help="Remove scheduler files without calling launchctl/systemctl",
    )

    scheduler_status_parser = subparsers.add_parser(
        "status-scheduler",
        help="Report scheduler config, interval, repositories, and last run",
    )
    scheduler_status_parser.add_argument("--home", default="~/.codex")
    scheduler_status_parser.add_argument(
        "--platform",
        choices=("auto", "macos", "linux"),
        default="auto",
    )
    scheduler_status_parser.add_argument("--json", action="store_true")
    scheduler_status_parser.add_argument("--strict", action="store_true")

    doctor_parser = subparsers.add_parser(
        "doctor",
        help="Audit scheduler health and active skill discovery",
    )
    doctor_parser.add_argument("--home", default="~/.codex")
    doctor_parser.add_argument(
        "--platform",
        choices=("auto", "macos", "linux"),
        default="auto",
    )
    doctor_parser.add_argument("--json", action="store_true")
    doctor_parser.add_argument("--strict", action="store_true")

    run_scheduled_parser = subparsers.add_parser(
        "run-scheduled",
        help=argparse.SUPPRESS,
    )
    run_scheduled_parser.add_argument(
        "--mode", choices=("public", "private"), required=True
    )
    run_scheduled_parser.add_argument("--repo", required=True)
    run_scheduled_parser.add_argument("--base-repo", default=base_release_repo)
    run_scheduled_parser.add_argument("--owner", default="private")
    run_scheduled_parser.add_argument("--home", default="~/.codex")

    pin_parser = subparsers.add_parser(
        "pin-release",
        help="Protect an installed release from retention pruning",
    )
    pin_parser.add_argument("--home", default="~/.codex")
    pin_parser.add_argument("--owner", default=PUBLIC_OWNER)
    pin_parser.add_argument("--sha", required=True)

    unpin_parser = subparsers.add_parser(
        "unpin-release",
        help="Remove a user retention pin from an installed release",
    )
    unpin_parser.add_argument("--home", default="~/.codex")
    unpin_parser.add_argument("--owner", default=PUBLIC_OWNER)
    unpin_parser.add_argument("--sha", required=True)

    prune_parser = subparsers.add_parser(
        "prune-releases",
        help="Quarantine and delete only unreferenced installed releases",
    )
    prune_parser.add_argument("--home", default="~/.codex")
    prune_parser.add_argument(
        "--owner",
        action="append",
        dest="owners",
        help="Limit pruning to an owner; repeat to select multiple owners",
    )
    prune_parser.add_argument("--dry-run", action="store_true")

    recovery_parser = subparsers.add_parser(
        "recover-private-control",
        help="Adopt exact legacy private-control evidence without moving it",
    )
    recovery_parser.add_argument(
        "--root-id",
        required=True,
        choices=(MIRROR_PRIVATE_CONTROL_LEGACY_ROOT_ID,),
    )
    recovery_mode = recovery_parser.add_mutually_exclusive_group(required=True)
    recovery_mode.add_argument("--dry-run", action="store_true")
    recovery_mode.add_argument("--execute", action="store_true")
    recovery_parser.add_argument("--output-receipt", type=Path)
    recovery_parser.add_argument("--receipt", type=Path)

    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        if args.command == "install":
            install_from_github(args.repo, Path(args.home), dry_run=args.dry_run)
        elif args.command == "install-private":
            install_private_from_github(
                args.repo,
                Path(args.home),
                base_repo=args.base_repo,
                owner=args.owner,
                dry_run=args.dry_run,
            )
        elif args.command == "status":
            status_ok = status(Path(args.home), args.owner)
            if args.strict and not status_ok:
                return 1
        elif args.command == "rollback":
            rollback(Path(args.home), args.to, args.owner)
        elif args.command == "verify-overlay":
            verify_overlay(Path(args.home), args.owner)
        elif args.command == "release-identities":
            payload = release_identities(
                Path(args.home),
                mode=args.mode,
                owner=args.owner,
            )
            if args.json:
                print(json.dumps(payload, indent=2, sort_keys=True))
            else:
                for release_owner, identity in payload["release_trees"].items():
                    print(
                        f"{release_owner} {identity['sha']} {identity['tree_sha256']}"
                    )
        elif args.command == "uninstall-overlay":
            uninstall_overlay(Path(args.home), args.owner, dry_run=args.dry_run)
        elif args.command == "install-scheduler":
            install_scheduler(
                Path(args.home),
                args.repo,
                args.interval_minutes,
                args.platform,
                args.runner,
                dry_run=args.dry_run,
                enable=not args.no_enable,
                mode=args.mode,
                base_repo=args.base_repo,
                owner=args.owner,
            )
        elif args.command == "uninstall-scheduler":
            uninstall_scheduler(
                Path(args.home),
                args.platform,
                dry_run=args.dry_run,
                disable=not args.no_disable,
            )
        elif args.command == "status-scheduler":
            report = status_scheduler(
                Path(args.home),
                args.platform,
                json_output=args.json,
            )
            if args.strict and (
                not report.installed
                or not report.stable_runner
                or report.failure_reason is not None
            ):
                return 1
        elif args.command == "doctor":
            _report, issues = doctor(
                Path(args.home),
                args.platform,
                json_output=args.json,
            )
            if args.strict and issues:
                return 1
        elif args.command == "run-scheduled":
            run_scheduled(
                Path(args.home),
                args.repo,
                mode=args.mode,
                base_repo=args.base_repo,
                owner=args.owner,
            )
        elif args.command == "pin-release":
            pin_release(Path(args.home), args.owner, args.sha)
        elif args.command == "unpin-release":
            unpin_release(Path(args.home), args.owner, args.sha)
        elif args.command == "prune-releases":
            prune_releases(
                Path(args.home),
                args.owners,
                dry_run=args.dry_run,
            )
        elif args.command == "recover-private-control":
            if args.dry_run:
                if args.output_receipt is None or args.receipt is not None:
                    raise SyncError(
                        "--dry-run requires --output-receipt and rejects --receipt"
                    )
                receipt = plan_private_control_recovery(
                    args.root_id,
                    args.output_receipt,
                )
            else:
                if args.receipt is None or args.output_receipt is not None:
                    raise SyncError(
                        "--execute requires --receipt and rejects --output-receipt"
                    )
                receipt = execute_private_control_recovery(
                    args.root_id,
                    args.receipt,
                )
            sys.stdout.buffer.write(_pc_recovery_json_bytes(receipt, pretty=True))
        else:
            parser.error(f"unknown command: {args.command}")
    except SyncError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
